Create or Replace PROCEDURE "THJS"."PROC_ERRLOG" (I_OPERATE_DATE  IN CHAR,
                                        I_OPERATE_TIME  IN CHAR,
                                        I_RULE_ID       IN VARCHAR2,
                                        I_FUNCTION_ID   IN VARCHAR2,
                                        I_ERROR_SQLCODE IN VARCHAR2,
                                        I_ERROR_SQLERRM IN VARCHAR2)
 IS
BEGIN
  INSERT INTO THJS.TB_ERRORLOG
    (OPERATE_DATE,
     OPERATE_TIME,
     FUNCTION_ID,
     ERROR_SQLCODE,
     ERROR_SQLERRM)
  VALUES
    (I_OPERATE_DATE,
     I_OPERATE_TIME,
     I_FUNCTION_ID,
     I_ERROR_SQLCODE,
     I_ERROR_SQLERRM);
  COMMIT;
END;

Create or Replace procedure "THJS"."P_BIGTABLE_D" (i_table_name  in varchar2, --表名
                                              i_condition   in varchar2, --条件
                                              i_count       in integer, --每次删除的记录数
                                              i_user        in varchar2, --操作人员
                                              o_return_msg  out varchar2,
                                              o_return_code out integer) is
  ----------------------------------------------------------------------------------
  --版    权：GTJA
  --版    本：1.0.0
  --开发人员：CZC@GTJA
  --创建日期：20200520
  --模块编号：
  --模块名称：大数据表删除
  --功能名称：
  ----------------------------------------------------------------------------------
  --==============================================================================
  --固定变量
  v_userexp exception; -- 用户定义错
  v_tradedate    varchar2(8); -- 任务执行时间(业务日期)
  v_exec_func_id integer default '0'; -- 任务id
  v_func_own     varchar2(20) default 'thjs'; -- 任务归属用户（schema）
  v_func_name    varchar2(2000) default 'p_bigtable_d'; -- 任务名称(存储过程的名字)
  v_sqlerrm      varchar2(4000); -- 错误提示信息
  v_sqlcode      number; -- 错误代码
  v_sqlerrl      varchar2(4000); -- 错误行号
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  v_sql       varchar2(10000);
  v_del_count number := 0;
  --=============================================================
  -- 业务处理过程
  --=============================================================

begin

  v_tradedate := to_char(sysdate, 'yyyyMMdd');

  delete from thjs.tb_data_log t
   where t.busi_date = v_tradedate
     and t.table_name = i_table_name;
  commit;

  while 1 = 1 loop
  
    v_sql := 'delete from ' || i_table_name || ' t where ' || i_condition ||
             ' and rownum<=:rn';
             
    execute immediate v_sql
      using i_count;
  
    if SQL%NOTFOUND THEN
      exit;
    else
      v_del_count := v_del_count + SQL%ROWCOUNT;
    end if;
  
    insert into thjs.tb_data_log
      (busi_date, table_name, op_desc, op_count, op_user)
    values
      (v_tradedate, i_table_name, 'DELETE', v_del_count, i_user);
  
    commit;
  
  end loop;

  commit;

  o_return_msg  := '执行成功';
  o_return_code := 0;

exception
  -- 非预定义异常处理
  when v_userexp then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    hgman.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
    -- 预定义异常处理
  when others then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    hgman.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
end;

Create or Replace procedure "THJS"."P_CHECK_DATA" (
  rt_cursor   out types.cursortype,
  i_tradedate in varchar2 --日期
) is
  --------------------------------------------------------
  -- version: 0.0.1
  -- time   : 2025-06-26
  -- remark : 做市清单邮件任务检测

  --------------------------------------------------------

  v_cnt_x  int;
  v_cnt    int;
  v_cnt_y  int;
  v_last_tradedate varchar2(8);
begin
  --取上一个交易日
  select kingstar.get_last_n_trade_date(i_tradedate,-1) 
    into v_last_tradedate
  from dual;
  --默认返回0
  v_cnt := 0;

  --Y公司采集标志采集完此处校验监测任务
  select count(1)
    into v_cnt_x
  from hgpt.tb_hg_xx_070403_all t
  where t.busi_date = v_last_tradedate;

  select count(1)
    into v_cnt_y
  from htzq.t_htzq_zyzs h
  where h.hdate = v_last_tradedate;

  if (v_cnt_x > 0 and v_cnt_x > 0 )
  then
    v_cnt := 1;
  end if;

  --返回数据标记
  open rt_cursor for
    select v_cnt from dual;

exception
  when others then
    null;
end;

Create or Replace PROCEDURE "THJS"."P_COMP_CACHE" (i_pripid in char)
/*==============================================================================
  版 本    : 1.0.0
  创建人   : czc
  模块编号 : 0
  日 期    : 2019-04-12
  功能描述 : 投行数据集市 主体信息页记录数缓存
  ==============================================================================*/
 as
  v_sqlcode  integer default 0;
  v_sqlstate char(5) default '';
  --v_errcode        integer default 0;
  --v_errstate       char(5) default '';
  v_err_msg varchar2(128) default '';
  --v_not_found      integer default 0;
  --v_last_time      char(8);
  v_function_id    integer default 0; --定义存储过程模块编号
  v_error_line_num integer default 0; --错误行号
  --v_error_level    integer default 0; --错误级别
  v_function_desc varchar2(50) default '主体信息页记录数缓存'; --功能描述
  v_program_name  char(40) default 'p_comp_cache'; --程序名
  v_pr_task_id    number default 0; --任务标示
  -- =======================================================================================================================
  -- 定义业务变量
  -- =======================================================================================================================
  v_count       integer default 0;
  v_tradedate   varchar2(8);
  v_pripid      varchar2(100); --工商主体编号
  v_entname     varchar2(250); --主体名称
  v_regno       varchar2(100); --工商注册号
  v_credit_code varchar2(100); --统一社会信用代码
  v_eid         varchar2(100); --企业ID
  -- =======================================================================================================================
  -- 业务开始
  -- =======================================================================================================================
begin

  SELECT count(1)
    into v_count
    FROM ZTGS.ENTERPRISEBASEINFOCOLLECT E --企业主体表
   WHERE E.PRIPID = i_pripid;
  --避免无数据造成的错误
  if v_count = 0 then
    return;
  end if;
  --对持续督导，项目信息中涉及的主体进行缓存
  --其余主体在查询时计算 并计入缓存

  SELECT to_char(sysdate, 'yyyyMMdd'),
         E.Pripid,
         E.ENTNAME,
         E.REGNO,
         E.Credit_Code,
         E.EID
    into v_tradedate, v_pripid, v_entname, v_regno, v_credit_code, v_eid
    FROM ZTGS.ENTERPRISEBASEINFOCOLLECT E --企业主体表
   WHERE E.PRIPID = i_pripid;

  --缓存当前主体财汇舆情行业分类
  execute immediate 'truncate table thjs.tmp_chyq_comp_industry';
  insert into thjs.tmp_chyq_comp_industry
    (compcode, mindustryid, level1id, level1name, pripid)
    select distinct c.compcode,
                    m.mindustryid,
                    ci.level1id,
                    ci.level1name,
                    v_pripid
      from CHYQ.TQ_COMP_INDUSTRY ci --行业分类表
     inner join CHYQ.T_IND_MAPPING m --行业对照表
        on m.standard = ci.indclasscode
       and m.industryid = ci.level1id
     inner join chyq.tq_comp_info c
        on c.compcode = ci.compcode
     where (c.bizlicenseno = v_regno or c.compname = v_entname);
  commit;

  delete from thjs.tb_comp_bizcount c where c.pripid = v_pripid;
  commit;

  insert into thjs.tb_comp_bizcount
    (tradedate, pripid, pro_name, col_nameche, col_num)
    SELECT v_tradedate as tradedate,
           v_pripid    as pripid,
           PRO_NAME,
           COL_NAMECHE,
           COL_NUM
      FROM (SELECT COUNT(1) COL_NUM,
                   'P_TYNEWS_INFO_XMZL' PRO_NAME,
                   '客户及业务信息 --项目总览' COL_NAMECHE
              FROM GTJA.TCL_DF_V_CUST_INFO T
             WHERE KHXYCODE = v_credit_code
            UNION
            SELECT COUNT(1) COL_NUM,
                   'P_TYNEWS_INFO_FXXX' PRO_NAME,
                   '客户及业务信息 --发行信息' COL_NAMECHE
              FROM GTJA.TCL_DF_V_CUST_FX T
             WHERE T.TYSHXYCODE = v_credit_code
            UNION
            SELECT COUNT(1) COL_NUM,
                   'P_TYNEWS_INFO_XMSH' PRO_NAME,
                   '客户及业务信息 --项目审核' COL_NAMECHE
              FROM GTJA.TCL_DF_WF_FK_VOTE_INFO T
             INNER JOIN GTJA.TCL_DF_V_CUST_INFO B
                ON B.PROJID = T.PROJID
             WHERE B.KHXYCODE = v_credit_code
            UNION
            SELECT COUNT(1) COL_NUM,
                   'P_TYNEWS_INFO_JGYCF' PRO_NAME,
                   '客户及业务信息 --监管与处罚' COL_NAMECHE
              FROM GTJA.TB_IMPORT_1825015140 T
             WHERE T.SSJG = v_entname
            UNION
            SELECT COUNT(1) COL_NUM,
                   'P_TYNEWS_INFO_XYFXPC' PRO_NAME,
                   '客户及业务信息 --信用风险排查' COL_NAMECHE
              FROM GTJA.TB_IMPORT_1825015150 T
             WHERE T.TYSHXYDM = v_credit_code
            UNION
            SELECT COUNT(1) COL_NUM,
                   'P_TYNEWS_INFINA_MAIN' PRO_NAME,
                   '内部财务数据 -- 财务主信息' COL_NAMECHE
              FROM THJS.THDB_V_FINANCE_AFFIRM T
             WHERE exists (select 1
                      from thjs.tb_thdb_cust_info p
                     where p.pripid = v_pripid
                       and p.projid = T.PROJ_ID)
            UNION
            SELECT COUNT(1) COL_NUM,
                   'P_TYNEWS_INFINA_INCOME' PRO_NAME,
                   '内部财务数据 -- 收入明细' COL_NAMECHE
              FROM THJS.THDB_V_FINANCE_INCOME T
             WHERE exists (select 1
                      from thjs.tb_thdb_cust_info p
                     where p.pripid = v_pripid
                       and p.projid = T.PROJ_ID)
            UNION
            SELECT COUNT(1) COL_NUM,
                   'P_TYNEWS_INFINA_EXPEN' PRO_NAME,
                   '内部财务数据 -- 支出明细' COL_NAMECHE
              FROM THJS.THDB_V_FINANCE_EXPEND T
             WHERE exists (select 1
                      from thjs.tb_thdb_cust_info p
                     where p.pripid = v_pripid
                       and p.projid = T.PROJ_ID)
            UNION
            SELECT COUNT(1) COL_NUM,
                   'P_TYNEWS_INFINA_INVO' PRO_NAME,
                   '内部财务数据 -- 发票明细' COL_NAMECHE
              FROM THJS.THDB_V_FINANCE_INVOICE T
             WHERE exists (select 1
                      from thjs.tb_thdb_cust_info p
                     where p.pripid = v_pripid
                       and p.projid = T.PROJ_ID)
            union all
            SELECT COUNT(1) COL_NUM,
                   'P_TYNEWS_HIS_ADUIT' PRO_NAME,
                   '历史数据 -- 审计署数据' COL_NAMECHE
              FROM THJS.Tb_Aduit_Bond_Uwinfo T
             inner join zx90.tcl_cbonddescription a1
                on a1.s_info_windcode = t.bond_code
             INNER JOIN ZX90.TCL_COMPINTRODUCTION C
                ON C.COMP_ID = A1.B_INFO_ISSUERCODE
             WHERE exists (select 1
                      from thjs.tb_thdb_cust_info p
                     where p.pripid = v_pripid
                       and p.credit_code = c.registernumber)
            /*UNION
            SELECT COUNT(1) COL_NUM,
                  'P_TYNEWS_ASTOCK_NAME' PRO_NAME,
                  'A股发行情况 -- 公司简介' COL_NAMECHE
             FROM ZX90.TCL_ASHAREINTRODUCTION B1
            INNER JOIN ZX90.TCL_ASHAREDESCRIPTION A1
               ON A1.S_INFO_WINDCODE = B1.S_INFO_WINDCODE
            INNER JOIN ZX90.TCL_COMPINTRODUCTION C
               ON C.COMP_ID = A1.S_INFO_COMPCODE
            WHERE C.REGISTERNUMBER = v_credit_code*/
            union all
            SELECT COUNT(1) COL_NUM,
                   'P_TYNEWS_ASTOCK_ISSU' PRO_NAME,
                   'A股发行情况' COL_NAMECHE
              FROM ZX90.TCL_ASHAREDESCRIPTION A1
             INNER JOIN ZX90.TCL_COMPINTRODUCTION C
                ON C.COMP_ID = A1.S_INFO_COMPCODE
             WHERE C.REGISTERNUMBER = v_credit_code
               AND A1.S_INFO_WINDCODE IN
                   (SELECT DISTINCT T1.S_INFO_WINDCODE
                      FROM ZX90.TCL_ASHAREAGENCY T1
                     WHERE T1.S_AGENCY_NAMEID = '2024680')
            /*UNION
            SELECT COUNT(1) COL_NUM,
                   'P_TYNEWS_WIND_COMP' PRO_NAME,
                   'WIND债券发行情况--公司简介' COL_NAMECHE
              FROM ZX90.TCL_CBONDINTRODUCTION B1
             WHERE B1.S_INFO_COMPCODE = I_OBJ_NAME*/
            UNION
            SELECT COUNT(1) COL_NUM,
                   'P_TYNEWS_WIND_ISSU' PRO_NAME,
                   'WIND债券发行情况' COL_NAMECHE
              FROM ZX90.TCL_CBONDDESCRIPTION A1
             INNER JOIN ZX90.TCL_COMPINTRODUCTION C
                ON C.COMP_ID = A1.B_INFO_ISSUERCODE
             WHERE C.REGISTERNUMBER = v_credit_code
               AND A1.S_INFO_WINDCODE IN
                   (SELECT T1.B_INFO_WINDCODE
                      FROM ZX90.TCL_CBONDAGENCY T1
                     WHERE T1.B_AGENCY_NAMEID = '2024680')
            UNION
            SELECT COUNT(1) COL_NUM,
                   'P_TYNEWS_NEEQS_ISSU' PRO_NAME,
                   'WIND三板发行情况' COL_NAMECHE
              FROM ZX90.Tcl_Neeqsdescription n
             inner join zx90.tcl_neeqsseo s
                on s.s_info_windcode = n.s_info_windcode
             inner join zx90.tcl_windcustomcode_all w
                on w.s_info_windcode = n.s_info_windcode
             inner join zx90.tcl_neeqsintroduction i
                on i.s_info_compcode = w.s_info_compcode
             INNER JOIN ZX90.TCL_COMPINTRODUCTION C
                ON C.COMP_ID = i.s_info_compcode
                or c.comp_name = i.s_info_compname
             WHERE C.REGISTERNUMBER = v_credit_code
               AND n.S_INFO_WINDCODE IN
                   (SELECT T1.B_INFO_WINDCODE
                      FROM ZX90.TCL_CBONDAGENCY T1
                     WHERE T1.B_AGENCY_NAMEID = '2024680')
            UNION
            SELECT COUNT(1) COL_NUM,
                   'P_TYNEWS_YULUN_CXXX' PRO_NAME,
                   '舆论信息 -- 诚信信息' COL_NAMECHE
              FROM (SELECT IT0026_001,
                           IT0026_002,
                           IT0026_005,
                           TO_CHAR(IT0026_006, 'YYYYMMDD') IT0026_006,
                           TO_CHAR(ENTRYDT, 'YYYYMMDD') ENTRYDT,
                           FLAG
                      FROM CHYQ.TIT0026_1 T
                     WHERE t.IT0026_015 is not null
                       and T.IT0026_004 =
                           (SELECT C.COMPCODE
                              FROM CHYQ.TQ_COMP_INFO C --机构资料表
                             WHERE (c.bizlicenseno = v_regno or
                                   c.compname = v_entname))
                    UNION
                    SELECT IT0026_001,
                           IT0026_002,
                           IT0026_005,
                           TO_CHAR(IT0026_006, 'YYYYMMDD') IT0026_006,
                           TO_CHAR(ENTRYDT, 'YYYYMMDD') ENTRYDT,
                           FLAG
                      FROM CHYQ.TIT0026_3 T1
                     WHERE t1.IT0026_032 is not null
                       and T1.IT0026_005 =
                           (SELECT C.Compname
                              FROM CHYQ.TQ_COMP_INFO C --机构资料表
                             WHERE (c.bizlicenseno = v_regno or
                                   c.compname = v_entname)))
            UNION
            SELECT COUNT(1) COL_NUM,
                   'P_TYNEWS_YULUN_HYNEWS' PRO_NAME,
                   '舆论信息 -- 行业新闻' COL_NAMECHE
              FROM CHYQ.T_NEWS_TEXT_IND T
             inner join CHYQ.T_NEWS_IND b --新闻行业表
                on b.newscode = t.newscode
             WHERE t.isvalid = 1 --有效
               and t.status = 1 --正常
               and t.newslink is not null
               and t.publishtime > add_months(sysdate, -1) --数据量太大，暂取1个月舆情
               and exists
             (select 1
                      from thjs.tmp_chyq_comp_industry m
                     where m.mindustryid = b.industrycode)
            UNION
            SELECT COUNT(1) COL_NUM,
                   'P_TYNEWS_YULUN_NEWS' PRO_NAME,
                   '舆论信息 -- 新闻公告 (负面新闻)' COL_NAMECHE
              FROM CHYQ.T_NEWS_TEXT_FCDB T --负面新闻
             WHERE t.isvalid = 1 --有效
               and not (t.newslinkhd is null and t.newslink is null)
               and exists (select 1
                      from CHYQ.T_NEWS_COMPANY_FCDB cf
                     inner join chyq.tq_comp_info c
                        on c.compcode = cf.compcode
                     where (c.bizlicenseno = v_regno or
                           c.compname = v_entname)
                       and cf.newscodehd = t.newscodehd)
            UNION
            SELECT COUNT(1) COL_NUM,
                   'P_TYNEWS_GSXX_BRANCH' PRO_NAME,
                   '工商信息 -- 分支机构' COL_NAMECHE
              FROM ZTGS.FILIATION T
             WHERE T.eid = v_eid
               AND T.MODIFY_TYPE <> 'D'
            UNION
            SELECT COUNT(1) COL_NUM,
                   'P_TYNEWS_GSXX_CHANGE' PRO_NAME,
                   '工商信息 -- 企业变更' COL_NAMECHE
              FROM ZTGS.E_ALTER_RECODER T
             WHERE T.PRIPID = v_pripid
               AND T.MODIFY_TYPE <> 'D'
            UNION
            SELECT COUNT(1) COL_NUM,
                   'P_TYNEWS_GSXX_CHATTEL' PRO_NAME,
                   '工商信息 -- 动产抵押' COL_NAMECHE
              FROM ZTGS.MORT_REG_INFO T
             WHERE T.EID = v_eid
               AND T.MODIFY_TYPE <> 'D'
            UNION
            SELECT COUNT(1) COL_NUM,
                   'P_TYNEWS_GSXX_FATAL' PRO_NAME,
                   '工商信息 -- 严重违法' COL_NAMECHE
              FROM ZTGS.E_LI_ILLDISDETAIL T
             WHERE T.EID = v_eid
               AND T.MODIFY_TYPE <> 'D'
            UNION
            SELECT COUNT(1) COL_NUM,
                   'P_TYNEWS_GSXX_FREEZE' PRO_NAME,
                   '工商信息 -- 股权冻结' COL_NAMECHE
              FROM ZTGS.e_shares_frost_new T
             WHERE T.EID = v_eid
               AND T.MODIFY_TYPE <> 'D'
            UNION
            SELECT COUNT(1) COL_NUM,
                   'P_TYNEWS_GSXX_HOLDER' PRO_NAME,
                   '工商信息 -- 股东信息' COL_NAMECHE
              FROM ZTGS.E_INV_INVESTMENT T
             WHERE T.PRIPID = v_pripid --'310000000011999081800013'
               AND T.MODIFY_TYPE <> 'D'
            UNION
            SELECT COUNT(1) COL_NUM,
                   'P_TYNEWS_GSXX_MANAGE' PRO_NAME,
                   '工商信息 -- 经营异常' COL_NAMECHE
              FROM ZTGS.BUSINESS_ABNORMAL T
             WHERE T.EID = v_eid
               AND T.MODIFY_TYPE <> 'D'
            UNION
            SELECT COUNT(1) COL_NUM,
                   'P_TYNEWS_GSXX_MEMBERS' PRO_NAME,
                   '工商信息 -- 主体人员' COL_NAMECHE
              FROM ZTGS.E_PRI_PERSON T
             WHERE T.PRIPID = v_pripid --'340200000011997010806031'
               AND T.MODIFY_TYPE <> 'D'
            UNION
            SELECT COUNT(1) COL_NUM,
                   'P_TYNEWS_GSXX_MINFO' PRO_NAME,
                   '工商信息 -- 主体信息' COL_NAMECHE
              FROM ZTGS.ENTERPRISEBASEINFOCOLLECT T
             WHERE T.PRIPID = v_pripid --'430000000012015040100034'
               AND T.MODIFY_TYPE <> 'D'
            UNION
            SELECT COUNT(1) COL_NUM,
                   'P_TYNEWS_GSXX_OUTINVESTA' PRO_NAME,
                   '工商信息 -- 对外投资' COL_NAMECHE
              FROM ZTGS.ENTINVITEM T
             WHERE T.eid = v_eid
               AND T.MODIFY_TYPE <> 'D'
            UNION
            SELECT COUNT(1) COL_NUM,
                   'P_TYNEWS_GSXX_PENALIZE' PRO_NAME,
                   '工商信息 -- 行政处罚' COL_NAMECHE
              FROM ZTGS.CASE_CF_IRREGPUNISHINFO T
             WHERE exists (select 1
                      from ztgs.case_cf_partyinfo x
                     where x.eid = v_eid
                       and x.MODIFY_TYPE <> 'D'
                       and x.case_info_id = t.case_info_id)
               AND T.MODIFY_TYPE <> 'D'
            UNION
            SELECT COUNT(1) COL_NUM,
                   'P_TYNEWS_GSXX_PERMISSION' PRO_NAME,
                   '工商信息 -- 许可信息' COL_NAMECHE
              FROM ZTGS.E_LICENCE_CERTIFICATE T
             WHERE T.EID = v_eid
               AND T.MODIFY_TYPE <> 'D'
            UNION
            SELECT COUNT(1) COL_NUM,
                   'P_TYNEWS_GSXX_PLEDGE' PRO_NAME,
                   '工商信息 -- 股权出质' COL_NAMECHE
              FROM ZTGS.E_SHARES_IMPAWN T
             WHERE T.EID = v_eid
               AND T.MODIFY_TYPE <> 'D'
               AND T.EQUITYNO IS NOT NULL
            UNION
            SELECT COUNT(1) COL_NUM,
                   'P_TYNEWS_GSXX_SETTLE' PRO_NAME,
                   '工商信息 -- 清算信息' COL_NAMECHE
              FROM ZTGS.E_LIQUIDATION T
             WHERE T.EID = v_eid --'510000000012016040100668'
               AND T.MODIFY_TYPE <> 'D');

  commit;

  ------------------------
exception
  when others then
    v_sqlcode := -1 * sqlcode;
    v_err_msg := sqlerrm;
    rollback;
    --记录错误日志
    kingstar.pr_audit_write_errlog(v_pr_task_id, -- 任务标识
                                   0, -- 单位编号
                                   v_tradedate, -- 业务日期
                                   v_function_id, -- 功能标识
                                   v_program_name, -- 程序名
                                   v_error_line_num, -- 程序行号
                                   v_err_msg, -- 错误信息
                                   v_sqlcode, -- SQLCODE
                                   v_sqlstate -- SQLSTATE
                                   );
    commit;
    raise;
end;

Create or Replace PROCEDURE "THJS"."P_COMP_CACHE_TASK" (i_tradedate in char)
/*==============================================================================
  版 本    : 1.0.0
  创建人   : czc
  模块编号 : 0
  日 期    : 2019-04-12
  功能描述 : 投行数据集市 主体信息页记录数缓存 批量任务
  ==============================================================================*/
 as
  v_sqlcode  integer default 0;
  v_sqlstate char(5) default '';
  --v_errcode        integer default 0;
  --v_errstate       char(5) default '';
  v_err_msg varchar2(128) default '';
  --v_not_found      integer default 0;
  --v_last_time      char(8);
  v_function_id    integer default 0; --定义存储过程模块编号
  v_error_line_num integer default 0; --错误行号
  --v_error_level    integer default 0; --错误级别
  v_function_desc varchar2(50) default '主体信息页记录数缓存'; --功能描述
  v_program_name  char(40) default 'p_comp_cache'; --程序名
  v_pr_task_id    number default 0; --任务标示
  -- =======================================================================================================================
  -- 定义业务变量
  -- =======================================================================================================================
  v_tradedate varchar2(8) default to_char(sysdate, 'yyyyMMdd');
  -- =======================================================================================================================
  -- 业务开始
  -- =======================================================================================================================
begin

  --对持续督导，项目信息中涉及的主体进行日终缓存
  --其余主体在查询时计算 并计入缓存
  execute immediate 'truncate table thjs.tmp_enterprisebaseinfocollect';
  insert into thjs.tmp_enterprisebaseinfocollect
    (pripid, entname, regno, credit_code, eid)
    SELECT E.Pripid, E.ENTNAME, E.REGNO, E.Credit_Code, E.EID
      FROM ZTGS.ENTERPRISEBASEINFOCOLLECT E --企业主体表
     WHERE E.PRIPID in
           (select distinct t.pripid
              from (select a.pripid
                      from thjs.tb_cxdd_ashareanency a
                    union all
                    select b.pripid
                      from thjs.tb_cxdd_cbondanency b
                    union all
                    select p.pripid
                      from thjs.tb_thdb_cust_info p) t)
    union
    SELECT E.Pripid, E.ENTNAME, E.REGNO, E.Credit_Code, E.EID
      FROM ZTGS.ENTERPRISEBASEINFOCOLLECT E --企业主体表
     where exists (select 1
              from thjs.tb_aduit_bond_uwinfo t
             inner join zx90.tcl_cbonddescription a1
                on a1.s_info_windcode = t.bond_code
             INNER JOIN ZX90.TCL_COMPINTRODUCTION C
                ON C.COMP_ID = A1.B_INFO_ISSUERCODE
             where e.credit_code = c.registernumber);

  commit;

  --缓存当前主体财汇舆情行业分类
  execute immediate 'truncate table thjs.tmp_chyq_comp_industry';
  insert into thjs.tmp_chyq_comp_industry
    (compcode, mindustryid, level1id, level1name, pripid)
    select distinct c.compcode,
                    m.mindustryid,
                    ci.level1id,
                    ci.level1name,
                    e.pripid
      from CHYQ.TQ_COMP_INDUSTRY ci --行业分类表
     inner join CHYQ.T_IND_MAPPING m --行业对照表
        on m.standard = ci.indclasscode
       and m.industryid = ci.level1id
     inner join chyq.tq_comp_info c
        on c.compcode = ci.compcode
     inner join thjs.tmp_enterprisebaseinfocollect e
        on e.regno = c.bizlicenseno
        or e.entname = c.compname;
  commit;

  delete from thjs.tb_comp_bizcount c;
  commit;

  insert into thjs.tb_comp_bizcount
    (tradedate, col_num, pro_name, col_nameche, pripid)
    SELECT v_tradedate as tradedate,
           COUNT(1) COL_NUM,
           'P_TYNEWS_INFO_XMZL' PRO_NAME,
           '客户及业务信息 --项目总览' COL_NAMECHE,
           e.pripid
      FROM GTJA.TCL_DF_V_CUST_INFO T
     inner join thjs.tmp_enterprisebaseinfocollect e
        on e.credit_code = t.khxycode
     group by e.pripid;

  insert into thjs.tb_comp_bizcount
    (tradedate, col_num, pro_name, col_nameche, pripid)
    SELECT v_tradedate as tradedate,
           COUNT(1) COL_NUM,
           'P_TYNEWS_INFO_FXXX' PRO_NAME,
           '客户及业务信息 --发行信息' COL_NAMECHE,
           e.pripid
      FROM GTJA.TCL_DF_V_CUST_FX T
     inner join thjs.tmp_enterprisebaseinfocollect e
        on e.credit_code = t.tyshxycode
     group by e.pripid;

  insert into thjs.tb_comp_bizcount
    (tradedate, col_num, pro_name, col_nameche, pripid)
    SELECT v_tradedate as tradedate,
           COUNT(1) COL_NUM,
           'P_TYNEWS_INFO_XMSH' PRO_NAME,
           '客户及业务信息 --项目审核' COL_NAMECHE,
           e.pripid
      FROM GTJA.TCL_DF_WF_FK_VOTE_INFO T
     INNER JOIN GTJA.TCL_DF_V_CUST_INFO B
        ON B.PROJID = T.PROJID
     inner join thjs.tmp_enterprisebaseinfocollect e
        on e.credit_code = b.khxycode
     group by e.pripid;

  insert into thjs.tb_comp_bizcount
    (tradedate, col_num, pro_name, col_nameche, pripid)
    SELECT v_tradedate as tradedate,
           COUNT(1) COL_NUM,
           'P_TYNEWS_INFO_JGYCF' PRO_NAME,
           '客户及业务信息 --监管与处罚' COL_NAMECHE,
           e.pripid
      FROM GTJA.TB_IMPORT_1825015140 T
     inner join thjs.tmp_enterprisebaseinfocollect e
        on e.entname = t.ssjg
     group by e.pripid;

  insert into thjs.tb_comp_bizcount
    (tradedate, col_num, pro_name, col_nameche, pripid)
    SELECT v_tradedate as tradedate,
           COUNT(1) COL_NUM,
           'P_TYNEWS_INFO_XYFXPC' PRO_NAME,
           '客户及业务信息 --信用风险排查' COL_NAMECHE,
           e.pripid
      FROM GTJA.TB_IMPORT_1825015150 T
     inner join thjs.tmp_enterprisebaseinfocollect e
        on e.credit_code = t.tyshxydm
     group by e.pripid;

  insert into thjs.tb_comp_bizcount
    (tradedate, col_num, pro_name, col_nameche, pripid)
    SELECT v_tradedate as tradedate,
           COUNT(1) COL_NUM,
           'P_TYNEWS_INFINA_MAIN' PRO_NAME,
           '内部财务数据 -- 财务主信息' COL_NAMECHE,
           p.pripid
      FROM THJS.THDB_V_FINANCE_AFFIRM T
     inner join (select distinct p.projid, p.pripid
                   from thjs.tb_thdb_cust_info p
                  where p.pripid is not null) p
        on p.projid = t.proj_id
     group by p.pripid;

  insert into thjs.tb_comp_bizcount
    (tradedate, col_num, pro_name, col_nameche, pripid)
    SELECT v_tradedate as tradedate,
           COUNT(1) COL_NUM,
           'P_TYNEWS_INFINA_INCOME' PRO_NAME,
           '内部财务数据 -- 收入明细' COL_NAMECHE,
           p.pripid
      FROM THJS.THDB_V_FINANCE_INCOME T
     inner join (select distinct p.projid, p.pripid
                   from thjs.tb_thdb_cust_info p
                  where p.pripid is not null) p
        on p.projid = t.proj_id
     group by p.pripid;

  insert into thjs.tb_comp_bizcount
    (tradedate, col_num, pro_name, col_nameche, pripid)
    SELECT v_tradedate as tradedate,
           COUNT(1) COL_NUM,
           'P_TYNEWS_INFINA_EXPEN' PRO_NAME,
           '内部财务数据 -- 支出明细' COL_NAMECHE,
           p.pripid
      FROM THJS.THDB_V_FINANCE_EXPEND T
     inner join (select distinct p.projid, p.pripid
                   from thjs.tb_thdb_cust_info p
                  where p.pripid is not null) p
        on p.projid = t.proj_id
     group by p.pripid;

  insert into thjs.tb_comp_bizcount
    (tradedate, col_num, pro_name, col_nameche, pripid)
    SELECT v_tradedate as tradedate,
           COUNT(1) COL_NUM,
           'P_TYNEWS_INFINA_INVO' PRO_NAME,
           '内部财务数据 -- 发票明细' COL_NAMECHE,
           p.pripid
      FROM THJS.THDB_V_FINANCE_INVOICE T
     inner join (select distinct p.projid, p.pripid
                   from thjs.tb_thdb_cust_info p
                  where p.pripid is not null) p
        on p.projid = t.proj_id
     group by p.pripid;

  insert into thjs.tb_comp_bizcount
    (tradedate, col_num, pro_name, col_nameche, pripid)
    SELECT v_tradedate as tradedate,
           COUNT(1) COL_NUM,
           'P_TYNEWS_HIS_ADUIT' PRO_NAME,
           '历史数据 -- 审计署数据' COL_NAMECHE,
           e.pripid
      FROM THJS.Tb_Aduit_Bond_Uwinfo T
     inner join zx90.tcl_cbonddescription a1
        on a1.s_info_windcode = t.bond_code
     INNER JOIN ZX90.TCL_COMPINTRODUCTION C
        ON C.COMP_ID = A1.B_INFO_ISSUERCODE
     inner join thjs.tmp_enterprisebaseinfocollect e
        on e.credit_code = c.registernumber
     group by e.pripid;

  insert into thjs.tb_comp_bizcount
    (tradedate, col_num, pro_name, col_nameche, pripid)
    SELECT v_tradedate as tradedate,
           COUNT(1) COL_NUM,
           'P_TYNEWS_ASTOCK_ISSU' PRO_NAME,
           'A股发行情况' COL_NAMECHE,
           e.pripid
      FROM ZX90.TCL_ASHAREDESCRIPTION A1
     INNER JOIN ZX90.TCL_COMPINTRODUCTION C
        ON C.COMP_ID = A1.S_INFO_COMPCODE
     inner join thjs.tmp_enterprisebaseinfocollect e
        on e.credit_code = c.registernumber
     WHERE A1.S_INFO_WINDCODE IN
           (SELECT DISTINCT T1.S_INFO_WINDCODE
              FROM ZX90.TCL_ASHAREAGENCY T1
             WHERE T1.S_AGENCY_NAMEID = '2024680')
     group by e.pripid;

  insert into thjs.tb_comp_bizcount
    (tradedate, col_num, pro_name, col_nameche, pripid)
    SELECT v_tradedate as tradedate,
           COUNT(1) COL_NUM,
           'P_TYNEWS_WIND_ISSU' PRO_NAME,
           'WIND债券发行情况' COL_NAMECHE,
           e.pripid
      FROM ZX90.TCL_CBONDDESCRIPTION A1
     INNER JOIN ZX90.TCL_COMPINTRODUCTION C
        ON C.COMP_ID = A1.B_INFO_ISSUERCODE
     inner join thjs.tmp_enterprisebaseinfocollect e
        on e.credit_code = c.registernumber
     WHERE A1.S_INFO_WINDCODE IN
           (SELECT T1.B_INFO_WINDCODE
              FROM ZX90.TCL_CBONDAGENCY T1
             WHERE T1.B_AGENCY_NAMEID = '2024680')
     group by e.pripid;

  insert into thjs.tb_comp_bizcount
    (tradedate, col_num, pro_name, col_nameche, pripid)
    SELECT v_tradedate as tradedate,
           COUNT(1) COL_NUM,
           'P_TYNEWS_NEEQS_ISSU' PRO_NAME,
           'WIND三板发行情况' COL_NAMECHE,
           e.pripid
      FROM ZX90.Tcl_Neeqsdescription n
     inner join zx90.tcl_neeqsseo s
        on s.s_info_windcode = n.s_info_windcode
     inner join zx90.tcl_windcustomcode_all w
        on w.s_info_windcode = n.s_info_windcode
     inner join zx90.tcl_neeqsintroduction i
        on i.s_info_compcode = w.s_info_compcode
     INNER JOIN ZX90.TCL_COMPINTRODUCTION C
        ON C.COMP_ID = i.s_info_compcode
        or c.comp_name = i.s_info_compname
     inner join thjs.tmp_enterprisebaseinfocollect e
        on e.credit_code = c.registernumber
     WHERE n.S_INFO_WINDCODE IN
           (SELECT T1.S_INFO_WINDCODE
              FROM ZX90.TCL_NEEQSAGENCY T1
             WHERE T1.S_AGENCY_NAMEID = '2024680')
     group by e.pripid;

  insert into thjs.tb_comp_bizcount
    (tradedate, col_num, pro_name, col_nameche, pripid)
    SELECT v_tradedate as tradedate,
           COUNT(1) COL_NUM,
           'P_TYNEWS_YULUN_CXXX' PRO_NAME,
           '舆论信息 -- 诚信信息' COL_NAMECHE,
           t.pripid
      FROM (SELECT IT0026_001,
                   IT0026_002,
                   IT0026_005,
                   TO_CHAR(IT0026_006, 'YYYYMMDD') IT0026_006,
                   TO_CHAR(ENTRYDT, 'YYYYMMDD') ENTRYDT,
                   FLAG,
                   e.pripid
              FROM CHYQ.TIT0026_1 T
             inner join chyq.tq_comp_info c
                on c.compcode = t.it0026_004
             inner join thjs.tmp_enterprisebaseinfocollect e
                on e.regno = c.bizlicenseno
                or e.entname = c.compname
             where t.IT0026_015 is not null
            union
            SELECT IT0026_001,
                   IT0026_002,
                   IT0026_005,
                   TO_CHAR(IT0026_006, 'YYYYMMDD') IT0026_006,
                   TO_CHAR(ENTRYDT, 'YYYYMMDD') ENTRYDT,
                   FLAG,
                   e.pripid
              FROM CHYQ.TIT0026_3 T1
             inner join chyq.tq_comp_info c
                on c.compname = t1.it0026_005
             inner join thjs.tmp_enterprisebaseinfocollect e
                on e.regno = c.bizlicenseno
                or e.entname = c.compname
             WHERE t1.IT0026_032 is not null) t
     group by t.pripid;

  insert into thjs.tb_comp_bizcount
    (tradedate, col_num, pro_name, col_nameche, pripid)
    SELECT v_tradedate as tradedate,
           COUNT(1) COL_NUM,
           'P_TYNEWS_YULUN_HYNEWS' PRO_NAME,
           '舆论信息 -- 行业新闻' COL_NAMECHE,
           m.pripid
      FROM CHYQ.T_NEWS_TEXT_IND T
     inner join CHYQ.T_NEWS_IND b --新闻行业表
        on b.newscode = t.newscode
     inner join thjs.tmp_chyq_comp_industry m
        on m.mindustryid = b.industrycode
     WHERE t.isvalid = 1 --有效
       and t.status = 1 --正常
       and t.newslink is not null
       and t.publishtime > add_months(sysdate, -1) --数据量太大，暂取1个月舆情
     group by m.pripid;

  insert into thjs.tb_comp_bizcount
    (tradedate, col_num, pro_name, col_nameche, pripid)
    SELECT v_tradedate as tradedate,
           COUNT(1) COL_NUM,
           'P_TYNEWS_YULUN_NEWS' PRO_NAME,
           '舆论信息 -- 新闻公告 (负面新闻)' COL_NAMECHE,
           e.pripid
      FROM CHYQ.T_NEWS_TEXT_FCDB T --负面新闻
     inner join chyq.t_news_company_fcdb cf
        on cf.newscodehd = t.newscodehd
     inner join chyq.tq_comp_info c
        on c.compcode = cf.compcode
     inner join thjs.tmp_enterprisebaseinfocollect e
        on e.regno = c.bizlicenseno
        or e.entname = c.compname
     WHERE t.isvalid = 1 --有效
       and not (t.newslinkhd is null and t.newslink is null)
     group by e.pripid;

  insert into thjs.tb_comp_bizcount
    (tradedate, col_num, pro_name, col_nameche, pripid)
    SELECT v_tradedate as tradedate,
           COUNT(1) COL_NUM,
           'P_TYNEWS_GSXX_BRANCH' PRO_NAME,
           '工商信息 -- 分支机构' COL_NAMECHE,
           e.pripid
      FROM ZTGS.FILIATION T
     inner join thjs.tmp_enterprisebaseinfocollect e
        on e.eid = t.eid
     WHERE T.MODIFY_TYPE <> 'D'
     group by e.pripid;
  commit;
  insert into thjs.tb_comp_bizcount
    (tradedate, col_num, pro_name, col_nameche, pripid)
    SELECT v_tradedate as tradedate,
           COUNT(1) COL_NUM,
           'P_TYNEWS_GSXX_CHANGE' PRO_NAME,
           '工商信息 -- 企业变更' COL_NAMECHE,
           e.pripid
      FROM ZTGS.E_ALTER_RECODER T
     inner join thjs.tmp_enterprisebaseinfocollect e
        on e.pripid = t.pripid
     WHERE T.MODIFY_TYPE <> 'D'
     group by e.pripid;

  insert into thjs.tb_comp_bizcount
    (tradedate, col_num, pro_name, col_nameche, pripid)
    SELECT v_tradedate as tradedate,
           COUNT(1) COL_NUM,
           'P_TYNEWS_GSXX_CHATTEL' PRO_NAME,
           '工商信息 -- 动产抵押' COL_NAMECHE,
           e.pripid
      FROM ZTGS.MORT_REG_INFO T
     inner join thjs.tmp_enterprisebaseinfocollect e
        on e.eid = t.eid
     WHERE T.MODIFY_TYPE <> 'D'
     group by e.pripid;

  insert into thjs.tb_comp_bizcount
    (tradedate, col_num, pro_name, col_nameche, pripid)
    SELECT v_tradedate as tradedate,
           COUNT(1) COL_NUM,
           'P_TYNEWS_GSXX_FATAL' PRO_NAME,
           '工商信息 -- 严重违法' COL_NAMECHE,
           e.pripid
      FROM ZTGS.E_LI_ILLDISDETAIL T
     inner join thjs.tmp_enterprisebaseinfocollect e
        on e.eid = t.eid
     WHERE T.MODIFY_TYPE <> 'D'
     group by e.pripid;

  insert into thjs.tb_comp_bizcount
    (tradedate, col_num, pro_name, col_nameche, pripid)
    SELECT v_tradedate as tradedate,
           COUNT(1) COL_NUM,
           'P_TYNEWS_GSXX_FREEZE' PRO_NAME,
           '工商信息 -- 股权冻结' COL_NAMECHE,
           e.pripid
      FROM ZTGS.e_shares_frost_new T
     inner join thjs.tmp_enterprisebaseinfocollect e
        on e.eid = t.eid
     WHERE T.MODIFY_TYPE <> 'D'
     group by e.pripid;

  insert into thjs.tb_comp_bizcount
    (tradedate, col_num, pro_name, col_nameche, pripid)
    SELECT v_tradedate as tradedate,
           COUNT(1) COL_NUM,
           'P_TYNEWS_GSXX_HOLDER' PRO_NAME,
           '工商信息 -- 股东信息' COL_NAMECHE,
           e.pripid
      FROM ZTGS.E_INV_INVESTMENT T
     inner join thjs.tmp_enterprisebaseinfocollect e
        on e.pripid = t.pripid
     WHERE T.MODIFY_TYPE <> 'D'
     group by e.pripid;

  insert into thjs.tb_comp_bizcount
    (tradedate, col_num, pro_name, col_nameche, pripid)
    SELECT v_tradedate as tradedate,
           COUNT(1) COL_NUM,
           'P_TYNEWS_GSXX_MANAGE' PRO_NAME,
           '工商信息 -- 经营异常' COL_NAMECHE,
           e.pripid
      FROM ZTGS.BUSINESS_ABNORMAL T
     inner join thjs.tmp_enterprisebaseinfocollect e
        on e.eid = t.eid
     WHERE T.MODIFY_TYPE <> 'D'
     group by e.pripid;

  insert into thjs.tb_comp_bizcount
    (tradedate, col_num, pro_name, col_nameche, pripid)
    SELECT v_tradedate as tradedate,
           COUNT(1) COL_NUM,
           'P_TYNEWS_GSXX_MEMBERS' PRO_NAME,
           '工商信息 -- 主体人员' COL_NAMECHE,
           e.pripid
      FROM ZTGS.E_PRI_PERSON T
     inner join thjs.tmp_enterprisebaseinfocollect e
        on e.pripid = t.pripid
     WHERE T.MODIFY_TYPE <> 'D'
     group by e.pripid;

  insert into thjs.tb_comp_bizcount
    (tradedate, col_num, pro_name, col_nameche, pripid)
    SELECT v_tradedate as tradedate,
           COUNT(1) COL_NUM,
           'P_TYNEWS_GSXX_MINFO' PRO_NAME,
           '工商信息 -- 主体信息' COL_NAMECHE,
           e.pripid
      FROM ZTGS.ENTERPRISEBASEINFOCOLLECT T
     inner join thjs.tmp_enterprisebaseinfocollect e
        on e.pripid = t.pripid
     WHERE T.MODIFY_TYPE <> 'D'
     group by e.pripid;

  insert into thjs.tb_comp_bizcount
    (tradedate, col_num, pro_name, col_nameche, pripid)
    SELECT v_tradedate as tradedate,
           COUNT(1) COL_NUM,
           'P_TYNEWS_GSXX_OUTINVESTA' PRO_NAME,
           '工商信息 -- 对外投资' COL_NAMECHE,
           e.pripid
      FROM ZTGS.ENTINVITEM T
     inner join thjs.tmp_enterprisebaseinfocollect e
        on e.eid = t.eid
     WHERE T.MODIFY_TYPE <> 'D'
     group by e.pripid;

  insert into thjs.tb_comp_bizcount
    (tradedate, col_num, pro_name, col_nameche, pripid)
    SELECT v_tradedate as tradedate,
           COUNT(1) COL_NUM,
           'P_TYNEWS_GSXX_PENALIZE' PRO_NAME,
           '工商信息 -- 行政处罚' COL_NAMECHE,
           e.pripid
      FROM ZTGS.CASE_CF_IRREGPUNISHINFO T
     inner join ztgs.case_cf_partyinfo x
        on x.MODIFY_TYPE <> 'D'
       and x.case_info_id = t.case_info_id
     inner join thjs.tmp_enterprisebaseinfocollect e
        on e.eid = x.eid
     WHERE T.MODIFY_TYPE <> 'D'
     group by e.pripid;

  insert into thjs.tb_comp_bizcount
    (tradedate, col_num, pro_name, col_nameche, pripid)
    SELECT v_tradedate as tradedate,
           COUNT(1) COL_NUM,
           'P_TYNEWS_GSXX_PERMISSION' PRO_NAME,
           '工商信息 -- 许可信息' COL_NAMECHE,
           e.pripid
      FROM ZTGS.E_LICENCE_CERTIFICATE T
     inner join thjs.tmp_enterprisebaseinfocollect e
        on e.eid = t.eid
     WHERE T.MODIFY_TYPE <> 'D'
     group by e.pripid;

  insert into thjs.tb_comp_bizcount
    (tradedate, col_num, pro_name, col_nameche, pripid)
    SELECT v_tradedate as tradedate,
           COUNT(1) COL_NUM,
           'P_TYNEWS_GSXX_PLEDGE' PRO_NAME,
           '工商信息 -- 股权出质' COL_NAMECHE,
           e.pripid
      FROM ZTGS.E_SHARES_IMPAWN T
     inner join thjs.tmp_enterprisebaseinfocollect e
        on e.eid = t.eid
     WHERE T.MODIFY_TYPE <> 'D'
       AND T.EQUITYNO IS NOT NULL
     group by e.pripid;

  insert into thjs.tb_comp_bizcount
    (tradedate, col_num, pro_name, col_nameche, pripid)
    SELECT v_tradedate as tradedate,
           COUNT(1) COL_NUM,
           'P_TYNEWS_GSXX_SETTLE' PRO_NAME,
           '工商信息 -- 清算信息' COL_NAMECHE,
           e.pripid
      FROM ZTGS.E_LIQUIDATION T
     inner join thjs.tmp_enterprisebaseinfocollect e
        on e.eid = t.eid
     WHERE T.MODIFY_TYPE <> 'D'
     group by e.pripid;

  commit;

  ------------------------
exception
  when others then
    v_sqlcode := -1 * sqlcode;
    v_err_msg := sqlerrm;
    rollback;
    --记录错误日志
    kingstar.pr_audit_write_errlog(v_pr_task_id, -- 任务标识
                                   0, -- 单位编号
                                   v_tradedate, -- 业务日期
                                   v_function_id, -- 功能标识
                                   v_program_name, -- 程序名
                                   v_error_line_num, -- 程序行号
                                   v_err_msg, -- 错误信息
                                   v_sqlcode, -- SQLCODE
                                   v_sqlstate -- SQLSTATE
                                   );
    commit;
    raise;
end;

Create or Replace PROCEDURE "THJS"."P_CXDD_ASTOCK" (RT_CURSOR     OUT TYPES.CURSORTYPE,
                                               I_OBJ_NAME    IN VARCHAR2,
                                               I_STK_NAME    IN VARCHAR2,
                                               I_COMP_NAME   IN VARCHAR2,
                                               I_STAR_DATE   IN VARCHAR2,
                                               I_END_DATE   IN VARCHAR2,
                                               I_PAGE_NUM    IN NUMBER DEFAULT 0, --默认值0,
                                               I_PAGE_SIZE   IN NUMBER DEFAULT 0, --默认值0  如果I_PAGE_NUM，I_PAGE_SIZE都为0 则不分页，查询全部
                                               O_TOTAL_COUNT OUT INTEGER,
                                               O_RETURN_MSG  OUT VARCHAR2,
                                               O_RETURN_CODE OUT INTEGER) IS
  -------------------------------------------------------------------------------------
  -- COPYRIGHT          GTJA
  -- FUNC_ID            THJS.P_CXDD_ASTOCK
  -- VERSION            1.0
  -- FUNC_NAME          A股持续督导
  -- FUNC_REMARK
  -- CREATE_DATE        2019-03-11
  -- CREATE_PROGRAMER   HAIYANG.XU
  -- MODIFY_REMARK
  -- MODIFY_DATE
  --==============================================================================
  --固定变量
  V_FUNCTION_NAME VARCHAR2(64) DEFAULT 'THJS.P_CXDD_ASTOCK'; --存储过程名
  V_ERROR_MSG     VARCHAR2(1000); --返回信息
  V_ERROR_CODE    INTEGER;
  V_ERROR_LINE    INTEGER;
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  V_PAGE_NUM  NUMBER DEFAULT 0;
  V_PAGE_SIZE NUMBER;
  --=============================================================
  -- 业务处理过程
  --=============================================================

  --------------------------业务逻辑开始-----------------------------
BEGIN
  /*
   INSERT INTO THJS.T_TEST(C1,C2,C3,C4) VALUES(V_FUNCTION_NAME,I_OBJ_NAME,I_PAGE_NUM,I_PAGE_SIZE);
    COMMIT;
  */
  IF I_PAGE_NUM IS NOT NULL THEN
    V_PAGE_NUM := I_PAGE_NUM;
  END IF;

  --统计记录条数
  IF V_PAGE_NUM < 1 THEN
    SELECT COUNT(1)
      INTO O_TOTAL_COUNT
      FROM thjs.tb_cxdd_ashareanency T
     WHERE (I_OBJ_NAME IS NULL or T.STOCK_CODE like I_OBJ_NAME || '%')
       and (I_STK_NAME is null or
           t.stock_name like '%' || I_STK_NAME || '%')
       and (I_COMP_NAME is null or
           t.comp_name like '%' || I_COMP_NAME || '%');
  END IF;

  IF I_PAGE_SIZE IS NOT NULL AND I_PAGE_SIZE <> 0 THEN
    V_PAGE_SIZE := I_PAGE_SIZE;
  ELSE
    V_PAGE_SIZE := O_TOTAL_COUNT;
  END IF;

  OPEN RT_CURSOR FOR
    SELECT S_INFO_CODE,
           S_INFO_NAME,
           S_INFO_COMPNAME,
           S_INFO_COMPNAMEENG,
           S_INFO_ISINCODE,
           S_INFO_EXCHMARKET,
           S_INFO_LISTBOARD,
           S_INFO_LISTDATE,
           S_INFO_DELISTDATE,
           S_INFO_SEDOLCODE,
           CRNCY_CODE,
           S_INFO_PINYIN,
           S_INFO_LISTBOARDNAME,
           IS_SHSC,
           PRIPID,
           ENTNAME
      FROM (SELECT A.*, ROWNUM AS RN
              FROM (SELECT T.BUSI_DATE,
                           T.S_INFO_CODE,
                           T.S_INFO_NAME,
                           T.S_INFO_COMPNAME,
                           T.S_INFO_COMPNAMEENG,
                           T.S_INFO_ISINCODE,
                           T.S_INFO_EXCHMARKET,
                           T.S_INFO_LISTBOARD,
                           T.S_INFO_LISTDATE,
                           T.S_INFO_DELISTDATE,
                           T.S_INFO_SEDOLCODE,
                           T.CRNCY_CODE,
                           T.S_INFO_PINYIN,
                           T.S_INFO_LISTBOARDNAME,
                           T.IS_SHSC,
                           a.PRIPID,
                           a.entname
                      FROM thjs.tb_cxdd_ashareanency a
                     inner join ZX90.TCL_ASHAREDESCRIPTION T
                        on t.s_info_windcode = a.s_info_windcode
                     where (I_OBJ_NAME IS NULL or
                           a.STOCK_CODE like I_OBJ_NAME || '%')
                       and T.S_INFO_LISTDATE BETWEEN nvl(I_STAR_DATE,'19600101') AND  I_END_DATE 
                       and (I_STK_NAME is null or
                           a.stock_name like '%' || I_STK_NAME || '%')
                       and (I_COMP_NAME is null or
                           a.comp_name like '%' || I_COMP_NAME || '%')) A) B
     WHERE RN > V_PAGE_NUM
       AND RN <= V_PAGE_NUM + V_PAGE_SIZE;

  O_RETURN_CODE := 0;
  O_RETURN_MSG  := '执行成功';

  -- ============================================================================
  -- 错误处理部分
  -- ============================================================================

EXCEPTION
  WHEN OTHERS THEN
    O_RETURN_CODE := -1;
    O_RETURN_MSG  := V_ERROR_MSG || '--行号:' || TO_CHAR(V_ERROR_LINE) ||
                     '||sqlcode:' || SQLCODE || '||sqlerrm:||' ||
                     SUBSTR(SQLERRM, 1, 200);
    ROLLBACK;
    V_ERROR_MSG  := O_RETURN_MSG;
    V_ERROR_CODE := O_RETURN_CODE;
    P_ERROR_LOG('admin',
                V_FUNCTION_NAME,
                V_ERROR_CODE,
                V_ERROR_MSG,
                '',
                '1',
                O_RETURN_MSG,
                O_RETURN_CODE);
END;

Create or Replace PROCEDURE "THJS"."P_CXDD_BOND" (RT_CURSOR     OUT TYPES.CURSORTYPE,
                                             I_OBJ_NAME    IN VARCHAR2,
                                             I_BOND_NAME   IN VARCHAR2,
                                             I_COMP_NAME   IN VARCHAR2,
                                             I_STAR_DATE   IN VARCHAR2,
                                             I_END_DATE   IN VARCHAR2,
                                             I_PAGE_NUM    IN NUMBER DEFAULT 0, --默认值0,
                                             I_PAGE_SIZE   IN NUMBER DEFAULT 0, --默认值0  如果I_PAGE_NUM，I_PAGE_SIZE都为0 则不分页，查询全部
                                             O_TOTAL_COUNT OUT INTEGER,
                                             O_RETURN_MSG  OUT VARCHAR2,
                                             O_RETURN_CODE OUT INTEGER) IS
  -------------------------------------------------------------------------------------
  -- COPYRIGHT          GTJA
  -- FUNC_ID            THJS.P_CXDD_BOND
  -- VERSION            1.0
  -- FUNC_NAME          债券持续督导
  -- FUNC_REMARK
  -- CREATE_DATE        2019-03-11
  -- CREATE_PROGRAMER   HAIYANG.XU
  -- MODIFY_REMARK
  -- MODIFY_DATE
  --==============================================================================
  --固定变量
  V_FUNCTION_NAME VARCHAR2(64) DEFAULT 'THJS.P_CXDD_BOND'; --存储过程名
  V_ERROR_MSG     VARCHAR2(1000); --返回信息
  V_ERROR_CODE    INTEGER;
  V_ERROR_LINE    INTEGER;
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  V_PAGE_NUM  NUMBER DEFAULT 0;
  V_PAGE_SIZE NUMBER;
  --=============================================================
  -- 业务处理过程
  --=============================================================

  --------------------------业务逻辑开始-----------------------------
BEGIN
  /*
   INSERT INTO THJS.T_TEST(C1,C2,C3,C4) VALUES(V_FUNCTION_NAME,I_OBJ_NAME,I_PAGE_NUM,I_PAGE_SIZE);
    COMMIT;
  */
  IF I_PAGE_NUM IS NOT NULL THEN
    V_PAGE_NUM := I_PAGE_NUM;
  END IF;

  --统计记录条数
  IF V_PAGE_NUM < 1 THEN
    SELECT COUNT(1)
      INTO O_TOTAL_COUNT
      FROM thjs.tb_cxdd_cbondanency T
     WHERE (I_OBJ_NAME IS NULL or t.bond_code like I_OBJ_NAME || '%')
       and (I_BOND_NAME is null or
           t.bond_name like '%' || I_BOND_NAME || '%')
       and (I_COMP_NAME is null or
           t.issuer_name like '%' || I_COMP_NAME || '%');
  END IF;

  IF I_PAGE_SIZE IS NOT NULL AND I_PAGE_SIZE <> 0 THEN
    V_PAGE_SIZE := I_PAGE_SIZE;
  ELSE
    V_PAGE_SIZE := O_TOTAL_COUNT;
  END IF;

  OPEN RT_CURSOR FOR
    SELECT BOND_CODE, --债券代码
           S_INFO_NAME, --  债券简称S_INFO_WINDCODE, --  WIND代码
           B_INFO_FULLNAME, --  债券名称
           B_INFO_ISSUER, --  发行人
           B_ISSUE_ANNOUNCEMENT, --  发行公告日
           B_ISSUE_FIRSTISSUE, --  发行起始日
           B_ISSUE_LASTISSUE, --  发行截止日
           B_ISSUE_AMOUNTPLAN, --  计划发行总量(亿元)
           B_ISSUE_AMOUNTACT, --  实际发行总量(亿元)
           B_INFO_ISSUEPRICE, --  发行价格
           B_INFO_PAR, --  面值
           B_INFO_COUPONRATE, --  发行票面利率(%)
           B_INFO_SPREAD, --  利差(%)
           B_INFO_CARRYDATE, --  计息起始日
           B_INFO_ENDDATE, --  计息截止日
           B_INFO_MATURITYDATE, --  到期日
           B_INFO_TERM_YEAR_, --  债券期限(年)
           B_INFO_TERM_DAY_, --  债券期限(天)
           B_INFO_PAYMENTDATE, --  兑付日
           B_INFO_PAYMENTTYPE, --  计息方式
           B_INFO_INTERESTFREQUENCY, --  付息频率
           B_INFO_FORM, --  债券形式
           B_INFO_COUPON, --  息票品种
           B_INFO_INTERESTTYPE, --  附息利率品种
           B_INFO_ACT, --  特殊年计息天数
           B_ISSUE_FEE, --  发行手续费率(%)
           B_REDEMPTION_FEERATION, --  兑付手续费率(%)
           B_INFO_TAXRATE, --  所得税率
           CRNCY_CODE, --  货币代码
           S_INFO_EXCHMARKET, --  交易所
           B_INFO_GUARANTOR, --  担保人
           B_INFO_GUARTYPE, --  担保方式
           B_INFO_LISTDATE, --  上市日期
           B_INFO_YEARSNUMBER, --  年内序号
           S_DIV_RECORDDATE, --  兑付登记起始日
           B_INFO_CODEBYPLACING, --  上网发行认购代码
           B_INFO_DELISTDATE, --  退市日期
           B_INFO_ISSUETYPE, --  发行方式
           B_INFO_GUARINTRODUCTION, --  担保简介
           B_INFO_BGNDBYPLACING, --  上网发行起始日期
           B_INFO_ENDDBYPLACING, --  上网发行截止日期
           B_INFO_AMOUNTBYPLACING, --  上网发行数量(亿元)
           B_INFO_UNDERWRITINGCODE, --  承销方式代码
           B_INFO_ISSUERCODE, --  发行人编号
           B_INFO_FORMERCODE, --  原债券代码
           B_INFO_COUPONTXT, --  利率说明
           IS_FAILURE, --  是否发行失败
           IS_CROSSMARKET, --  是否跨市场
           B_INFO_COUPONDATETXT, --  付息日说明
           B_INFO_SUBORDINATEORNOT, --  是否次级债或混合资本债
           B_TENDRST_REFERYIELD, --  参考收益率
           B_INFO_CURPAR, --  最新面值
           S_INFO_FORMERWINDCODE, --  原WIND代码
           IS_CORPORATE_BOND, --  是否公司债
           B_INFO_ISSUERTYPE, --  发行人类型
           B_INFO_SPECIALBONDTYPE, --  特殊债券类型
           IS_PAYADVANCED, --  是否可提前兑付
           IS_CALLABLE, --  是否可赎回
           IS_CHOOSERIGHT, --  是否有选择权
           IS_NETPRICE, --  是否净价
           IS_ACT_DAYS, --  是否按实际天数计息
           IS_INCBONDS, --  是否增发债
           ISSUE_OBJECT, --  发行对象
           B_INFO_ACTUALBENCHMARK, --  计息基准
           PRIPID,
           ENTNAME
      FROM (SELECT A.*, ROWNUM AS RN
              FROM (SELECT a.bond_code, --债券代码
                           T.S_INFO_NAME, --  债券简称
                           T.S_INFO_WINDCODE, --  WIND代码                           
                           T.B_INFO_FULLNAME, --  债券名称
                           T.B_INFO_ISSUER, --  发行人
                           T.B_ISSUE_ANNOUNCEMENT, --  发行公告日
                           T.B_ISSUE_FIRSTISSUE, --  发行起始日
                           T.B_ISSUE_LASTISSUE, --  发行截止日
                           T.B_ISSUE_AMOUNTPLAN, --  计划发行总量(亿元)
                           T.B_ISSUE_AMOUNTACT, --  实际发行总量(亿元)
                           T.B_INFO_ISSUEPRICE, --  发行价格
                           T.B_INFO_PAR, --  面值
                           T.B_INFO_COUPONRATE, --  发行票面利率(%)
                           T.B_INFO_SPREAD, --  利差(%)
                           T.B_INFO_CARRYDATE, --  计息起始日
                           T.B_INFO_ENDDATE, --  计息截止日
                           T.B_INFO_MATURITYDATE, --  到期日
                           T.B_INFO_TERM_YEAR_, --  债券期限(年)
                           T.B_INFO_TERM_DAY_, --  债券期限(天)
                           T.B_INFO_PAYMENTDATE, --  兑付日
                           T.B_INFO_PAYMENTTYPE, --  计息方式
                           T.B_INFO_INTERESTFREQUENCY, --  付息频率
                           T.B_INFO_FORM, --  债券形式
                           T.B_INFO_COUPON, --  息票品种
                           T.B_INFO_INTERESTTYPE, --  附息利率品种
                           T.B_INFO_ACT, --  特殊年计息天数
                           T.B_ISSUE_FEE, --  发行手续费率(%)
                           T.B_REDEMPTION_FEERATION, --  兑付手续费率(%)
                           T.B_INFO_TAXRATE, --  所得税率
                           T.CRNCY_CODE, --  货币代码
                           T.S_INFO_EXCHMARKET, --  交易所
                           T.B_INFO_GUARANTOR, --  担保人
                           T.B_INFO_GUARTYPE, --  担保方式
                           T.B_INFO_LISTDATE, --  上市日期
                           T.B_INFO_YEARSNUMBER, --  年内序号
                           T.S_DIV_RECORDDATE, --  兑付登记起始日
                           T.B_INFO_CODEBYPLACING, --  上网发行认购代码
                           T.B_INFO_DELISTDATE, --  退市日期
                           T.B_INFO_ISSUETYPE, --  发行方式
                           T.B_INFO_GUARINTRODUCTION, --  担保简介
                           T.B_INFO_BGNDBYPLACING, --  上网发行起始日期
                           T.B_INFO_ENDDBYPLACING, --  上网发行截止日期
                           T.B_INFO_AMOUNTBYPLACING, --  上网发行数量(亿元)
                           T.B_INFO_UNDERWRITINGCODE, --  承销方式代码
                           T.B_INFO_ISSUERCODE, --  发行人编号
                           T.B_INFO_FORMERCODE, --  原债券代码
                           T.B_INFO_COUPONTXT, --  利率说明
                           T.IS_FAILURE, --  是否发行失败
                           T.IS_CROSSMARKET, --  是否跨市场
                           T.B_INFO_COUPONDATETXT, --  付息日说明
                           T.B_INFO_SUBORDINATEORNOT, --  是否次级债或混合资本债
                           T.B_TENDRST_REFERYIELD, --  参考收益率
                           T.B_INFO_CURPAR, --  最新面值
                           T.S_INFO_FORMERWINDCODE, --  原WIND代码
                           T.IS_CORPORATE_BOND, --  是否公司债
                           T.B_INFO_ISSUERTYPE, --  发行人类型
                           T.B_INFO_SPECIALBONDTYPE, --  特殊债券类型
                           T.IS_PAYADVANCED, --  是否可提前兑付
                           T.IS_CALLABLE, --  是否可赎回
                           T.IS_CHOOSERIGHT, --  是否有选择权
                           T.IS_NETPRICE, --  是否净价
                           T.IS_ACT_DAYS, --  是否按实际天数计息
                           T.IS_INCBONDS, --  是否增发债
                           T.ISSUE_OBJECT, --  发行对象
                           T.B_INFO_ACTUALBENCHMARK, --  计息基准
                           A.PRIPID,
                           A.Entname
                      FROM thjs.tb_cxdd_cbondanency a
                     inner join ZX90.TCL_CBONDDESCRIPTION T
                        on t.s_info_windcode = a.s_info_windcode
                     WHERE (I_OBJ_NAME IS NULL or
                           a.bond_code like I_OBJ_NAME || '%')
                       and T.B_ISSUE_FIRSTISSUE BETWEEN  nvl(I_STAR_DATE,'19600101') AND  I_END_DATE 
                       and (I_BOND_NAME is null or
                           a.bond_name like '%' || I_BOND_NAME || '%')
                       and (I_COMP_NAME is null or
                           a.issuer_name like '%' || I_COMP_NAME || '%')) A) B
     WHERE RN > V_PAGE_NUM
       AND RN <= V_PAGE_NUM + V_PAGE_SIZE;
  O_RETURN_CODE := 0;
  O_RETURN_MSG  := '执行成功';

  -- ============================================================================
  -- 错误处理部分
  -- ============================================================================

EXCEPTION
  WHEN OTHERS THEN
    O_RETURN_CODE := -1;
    O_RETURN_MSG  := V_ERROR_MSG || '--行号:' || TO_CHAR(V_ERROR_LINE) ||
                     '||sqlcode:' || SQLCODE || '||sqlerrm:||' ||
                     SUBSTR(SQLERRM, 1, 200);
    ROLLBACK;
    V_ERROR_MSG  := O_RETURN_MSG;
    V_ERROR_CODE := O_RETURN_CODE;
    P_ERROR_LOG('admin',
                V_FUNCTION_NAME,
                V_ERROR_CODE,
                V_ERROR_MSG,
                '',
                '1',
                O_RETURN_MSG,
                O_RETURN_CODE);
END;

Create or Replace procedure "THJS"."P_ERROR_LOG" (i_user_id     in varchar2, --操作人
                                        i_program     in varchar2, --程序名
                                        i_error_code  in varchar2, --错误码
                                        i_error_msg   in varchar2, --错误信息
                                        i_error_type  in varchar2, --错误类型
                                        i_error_level in varchar2, --错误等级
                                        o_return_msg  out varchar2, --返回信息
                                        o_return_code out varchar2 --返回码
                                        ) is

  ---------------------------------------------------------------------------------

  -- copyright   gtjaapp 1.0
  -- func_create_begin
  -- func_id       功能号
  -- version       1.0
  -- func_name     sp异常日志
  -- func_remark   sp异常日志
  -- create_date   2019-01-17
  -- create_programer  shanshan.Jiang
  -- modify_remark  修改说明
  -- func_create_end

  --------------------------------------------------------------------------------
  --固有变量定义
  --------------------------------------------------------------------------------

  v_error_code    number(10);
  v_error_message varchar2(200);

  --------------------------------------------------------------------------------
  --计算逻辑处理
  --------------------------------------------------------------------------------
BEGIN

  insert into t_error_log
    (OPLOG_ID,
     LOG_DATE,
     PROGRAM,
     USER_ID,
     ERROR_CODE,
     ERROR_MSG,
     ERROR_LEVEL)
  values
    (sys_guid,
     sysdate,
     i_program,
     i_user_id,
     i_error_code,
     i_error_msg,
     i_error_level);

  o_return_code := i_error_code;
  o_return_msg  := i_error_msg;

  commit;
exception
  when others THEN
    v_error_code    := sqlcode;
    v_error_message := sqlerrm;
    o_return_code   := v_error_code;
    o_return_msg    := v_error_message;
    commit;

END;

Create or Replace procedure "THJS"."P_FLOW_APPR_Q" (rt_cursor     out sys_refcursor, --返回游标结果集
                                               i_cust_id     in varchar2, --客户代码
                                               i_busi_date   in varchar2, --业务日期
                                               i_flow_id     in varchar2, --流程实例id
                                               i_usercode    in varchar2, --查询人
                                               o_count       out integer, --0初审 1复核 2审核完成
                                               o_return_msg  out varchar2,
                                               o_return_code out integer) is
  ----------------------------------------------------------------------------------
  --版    权：gtja
  --版    本：1.0.0
  --开发人员：wyf
  --创建日期：20230222
  --模块编号：
  --模块名称：投行合规反洗钱 - 流程审批信息查询
  --功能名称：
  ----------------------------------------------------------------------------------
  --==============================================================================
  --固定变量
  v_userexp exception; -- 用户定义错
  v_tradedate    varchar2(8); -- 任务执行时间(业务日期)
  v_exec_func_id integer default '0'; -- 任务id
  v_func_own     varchar2(20) default 'thjs'; -- 任务归属用户（schema）
  v_func_name    varchar2(2000) default 'p_flow_appr_q'; -- 任务名称(存储过程的名字)
  v_sqlerrm      varchar2(4000); -- 错误提示信息
  v_sqlcode      number; -- 错误代码
  v_sqlerrl      varchar2(4000); -- 错误行号
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  v_count    integer default 0;
  v_nodecode integer;
  --=============================================================
  -- 业务处理过程
  --=============================================================

begin

  v_tradedate := to_char(sysdate, 'yyyyMMdd');

  --传给前端判断当前节点在初审or复核
  select count(1)
    into v_count
    from thjs.tb_flow_appr r
   where r.flow_id = i_flow_id;

  if v_count > 0 then  
    --返回最新一笔的node code，告知前端目前在哪个节点
    select x.appr_node
      into v_nodecode
      from (select row_number() over(partition by x.flow_id order by x.appr_date desc) as rn,
                   x.*
              from thjs.tb_flow_appr x
             where x.flow_id = i_flow_id) x
     where x.rn = 1;
  
  elsif v_count = 0 then
    v_nodecode := 0;
  end if;

  open rt_cursor for
    select decode(t.appr_node, '1', '投行初审岗', '2', '投行复核岗') as appr_node, --审批节点（1初审/2复核）
           t.appr_result, --审批意见
           decode(d.user_name, null, t.appr_usercode, d.user_name) as appr_username, --t.appr_username, --审批人
           t.appr_date --审批时间
      from thjs.tb_flow_appr t
      left join lrjack.tb_user_dept d
        on t.appr_usercode = d.user_code
     where t.flow_id = i_flow_id
     order by t.appr_date desc;

  commit;

  o_count       := v_nodecode;
  o_return_msg  := '执行成功';
  o_return_code := 0;

exception
  -- 非预定义异常处理
  when v_userexp then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    hgman.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
    -- 预定义异常处理
  when others then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    hgman.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
end;

Create or Replace procedure "THJS"."P_FLOW_APPR_S" (i_cust_id     in varchar2, --客户代码
                                               i_busi_date   in varchar2, --业务日期
                                               i_flow_id     in varchar2, --流程实例id
                                               i_appr_result in varchar2, --审批意见
                                               i_appr_node   in varchar2, --审批节点（1初审 2复核）
                                               i_usercode    in varchar2, --操作人
                                               o_return_msg  out varchar2,
                                               o_return_code out integer) is
  ----------------------------------------------------------------------------------
  --版    权：gtja
  --版    本：1.0.0
  --开发人员：wyf
  --创建日期：20230224
  --模块编号：
  --模块名称：投行反洗钱 - 流程审批信息保存
  --功能名称：
  ----------------------------------------------------------------------------------

  --==============================================================================
  --固定变量
  v_userexp exception; -- 用户定义错
  v_tradedate    varchar2(8); -- 任务执行时间(业务日期)
  v_exec_func_id integer default '0'; -- 任务id
  v_func_own     varchar2(20) default 'thjs'; -- 任务归属用户（schema）
  v_func_name    varchar2(2000) default 'p_flow_appr_s'; -- 任务名称(存储过程的名字)
  v_sqlerrm      varchar2(4000); -- 错误提示信息
  v_sqlcode      number; -- 错误代码
  v_sqlerrl      varchar2(4000); -- 错误行号
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  v_appr_username varchar2(50);
  v_cust_name     varchar2(200);
  --=============================================================
  -- 业务处理过程
  --=============================================================

begin
  v_tradedate := to_char(sysdate, 'yyyyMMdd');

  insert into thjs.tb_exec_log
    (log_id, proc_name, proc_param, exec_time)
  values
    (thjs.tb_exec_log_id_seq.nextval,
     'p_fxq_risk_flow_s',
     'cust_id:' || i_cust_id || ',busi_date:' || i_busi_date || ',flow_id:' ||
     i_flow_id || ',appr_result:' || i_appr_result || ',appr_node:' ||
     i_appr_node || ',usercode:' || i_usercode,
     sysdate);
  commit;

 /* SELECT t.user_name
    into v_appr_username
    from lrjack.tb_user_dept t
   where t.user_code = i_usercode;
*/
  select t.cust_name
    into v_cust_name
    from thjs.tb_fxq_risk_flow t
   where t.flow_id = i_flow_id;

  --同一folw_id同一节点只能提交一次，不存在多次提交的情况
  insert into thjs.tb_flow_appr
    (busi_date,
     cust_id,
     cust_name,
     flow_id,
     appr_node,
     appr_result,
     --appr_username,
     appr_usercode)
  values
    (v_tradedate,
     i_cust_id,
     v_cust_name,
     i_flow_id,
     i_appr_node, --审批节点（1初审/2复核）
     i_appr_result, --审批意见
     --v_appr_username, --审批人名称
     i_usercode);

  commit;

  o_return_msg  := '执行成功';
  o_return_code := 0;

exception
  -- 非预定义异常处理
  when v_userexp then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    hgman.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
    -- 预定义异常处理
  when others then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    hgman.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
end;

Create or Replace procedure "THJS"."P_FLOW_INST_Q" (rt_cursor     out sys_refcursor, --返回游标结果集
                                               i_usercode    in varchar2, --查询人
                                               o_return_msg  out varchar2,
                                               o_return_code out integer) is
  ----------------------------------------------------------------------------------
  --版    权：GTJA
  --版    本：1.0.0
  --开发人员：CZC@GTJA
  --创建日期：20210318
  --模块编号：
  --模块名称：投行合规 - 待办流程查询
  --功能名称：
  ----------------------------------------------------------------------------------
  --==============================================================================
  --固定变量
  v_userexp exception; -- 用户定义错
  v_tradedate    varchar2(8); -- 任务执行时间(业务日期)
  v_exec_func_id integer default '0'; -- 任务id
  v_func_own     varchar2(20) default 'thjs'; -- 任务归属用户（schema）
  v_func_name    varchar2(2000) default 'p_flow_inst_q'; -- 任务名称(存储过程的名字)
  v_sqlerrm      varchar2(4000); -- 错误提示信息
  v_sqlcode      number; -- 错误代码
  v_sqlerrl      varchar2(4000); -- 错误行号
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  --=============================================================
  -- 业务处理过程
  --=============================================================

begin

  v_tradedate := to_char(sysdate, 'yyyyMMdd');

  open rt_cursor for
    select t.busi_date, --业务日期
           t.flow_id, --流程实例id 
           t.flow_code, --流程代码：fxq_jg 反洗钱机构 fxq_zrr 反洗钱自然人 
           t.raise_code, --流程触发代码：fxq_tbrwh-反洗钱填报人维护 fxq_khsh-反洗钱客户审核 
           t.biz_key, --业务标识：业务数据记录主键 
           t.title, --流程标题 
           t.param_info, --参数列表：冒号分隔字段及值，逗号分组（parama:valuea,paramb:valueb） 
           t.send_status, --流程发送状态（0-未发送 1-已发送 2-错误） 
           t.error_info --错误信息 
      from thjs.tb_flow_inst t
     where t.send_status = '0'; --未发送状态的流程

  commit;

  o_return_msg  := '执行成功';
  o_return_code := 0;

exception
  -- 非预定义异常处理
  when v_userexp then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    hgman.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
    -- 预定义异常处理
  when others then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    hgman.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
end;

