Create or Replace procedure "THJS"."P_FUNCTION_DESC" (I_FUNCTION_ID in varchar2,
                                            I_OWNER       in varchar2,
                                            I_OBJECT_NAME in varchar2,
                                            I_DESCRIPTION in varchar2,
                                            i_user_login  in varchar2,
                                            o_return_msg  in OUT VARCHAR2, --返回信息
                                            o_return_code in OUT INTEGER --返回值 0 成功必须返回；-1 失败
                                            ) is

  ------------------------------------------------------------------------------------

  -- copyright   gtjaapp 1.0
  -- func_create_begin
  -- func_id       P_FUNCTION_DESC
  -- version       1.0
  -- func_name     功能点管理
  -- func_remark   记录功能点基本信息
  -- create_date   2018-03-07
  -- create_programer  shanshan.Jiang
  -- modify_remark  修改说明
  -- func_create_end

  --固有变量----------------------------------------------------------------------------
  v_error_code    number;
  v_cnt           number;
  v_error_message varchar2(200);
  --------------------------------------------------------------------------------
  --计算逻辑处理
  --------------------------------------------------------------------------------
begin
  v_error_code    := o_return_code;
  v_error_message := o_return_msg;
  select count(*)
    into v_cnt
    from wb_function_desc t
   where t.function_id = I_FUNCTION_ID;
  if v_cnt = 0 then
    insert into WB_FUNCTION_DESC
      (OWNER, OBJECT_NAME, FUNCTION_ID, DESCRIPTION)
    values
      (I_OWNER, I_OBJECT_NAME, I_FUNCTION_ID, I_DESCRIPTION);
  else
    update WB_FUNCTION_DESC
       set DESCRIPTION = I_DESCRIPTION
     where FUNCTION_ID = I_FUNCTION_ID;
  end if;

  commit;

exception
  when others THEN
    v_error_code    := sqlcode;
    v_error_message := sqlerrm;
    o_return_code   := v_error_code;
    o_return_msg    := v_error_message;
    p_error_log(i_user_login,
                        'P_FUNCTION_DESC',
                        v_error_code,
                        v_error_message,
                        '',
                        '1',
                        o_return_msg,
                        o_return_code);
    commit;

end;

Create or Replace procedure "THJS"."P_FXQ_APPR_FLOW_TASK" (i_tradedate in varchar2) is
  ----------------------------------------------------------------------------------
  --版    权：GTJA
  --版    本：1.0.0
  --开发人员：CZC@GTJA
  --创建日期：20221102
  --模块编号：
  --模块名称：投行反洗钱 - 反洗钱审核流程任务 -自动生成
  --功能名称：
  ----------------------------------------------------------------------------------
  /*v101 CZC@GTJA 20240918 调整证件到期自动审核流程，审核限制由3个月改为90个自然日，调整备注描述。
  */
  --==============================================================================
  --固定变量
  v_userexp exception; -- 用户定义错
  v_tradedate    varchar2(8); -- 任务执行时间(业务日期)
  v_exec_func_id integer default '0'; -- 任务id
  v_func_own     varchar2(20) default 'thjs'; -- 任务归属用户（schema）
  v_func_name    varchar2(2000) default 'p_fxq_appr_flow_task'; -- 任务名称(存储过程的名字)
  v_sqlerrm      varchar2(4000); -- 错误提示信息
  v_sqlcode      number; -- 错误代码
  v_sqlerrl      varchar2(4000); -- 错误行号
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  v_audit_id    varchar2(80);
  v_appr_num    integer default 1;
  v_return_msg  varchar2(1000);
  v_return_code number;
  --=============================================================
  -- 业务处理过程
  --=============================================================

begin

  --反洗钱客户证件到期邮件提醒=======================
  /*增加限制功能：
  ①非自然人客户中客户本身、法定代表人、受益所有人证照/证件过期3个月，即设置限制标签，并发送待办，
  待办标题为：“xxxx反洗钱审核意见及扣分情况”，
  审核备注：已设置限制状态，完善后请发邮件到合规管理组邮箱（cm_ibd@gtjas.com）抄送反洗钱专员，申请解限。
  
  ②自然人客户证件过期，即设置限制标签，并发送待办，
  待办标题为：“xxxx反洗钱审核意见及扣分情况”，
  审核备注：已设置限制状态，完善后请发邮件到合规管理组邮箱（cm_ibd@gtjas.com）抄送反洗钱专员，申请解限。
  
  
  20240830
  统一判断，证照/证件过期90个自然日后，设置限制标签，发送代办。
  */

  --自动生成审核记录信息
  --机构客户只审核 客户证照，法人代表，受益所有人；过期三个月， 每个类型一条审核记录
  delete from thjs.tb_fxq_cert_remind t where t.busi_date = i_tradedate;
  insert into thjs.tb_fxq_cert_remind
    (busi_date,
     cust_flag,
     cust_id,
     cust_name,
     remind_name,
     cert_enddate,
     cert_flag,
     cert_order,
     op_user,
     remind_date,
     email)
    select i_tradedate,
           t.cust_flag,
           t.cust_id,
           t.cust_name,
           t.remind_name,
           t.cert_enddate,
           t.cert_flag,
           t.cert_order,
           t.op_user,
           t.remind_date,
           u.email
      from (select t.cust_flag,
                   t.cust_id,
                   t.cust_name,
                   t.remind_name,
                   t.cert_enddate,
                   t.cert_flag,
                   t.cert_order,
                   t.op_user,
                   t.status,
                   --v101+
                   case
                     when t.cert_enddate = '9999-12-31' then
                      '99991231'
                     else
                      to_char(to_date(t.cert_enddate, 'yyyy-MM-dd') + 90, --90天                                        
                              'yyyyMMdd')
                   end as remind_date
            /* case
              when t.cert_enddate = '9999-12-31' then
               '99991231'
              when t.cust_flag = '机构' then --机构过期三个月触发流程
               to_char(add_months(to_date(t.cert_enddate, 'yyyy-MM-dd') + 1, --一个月
                                  3),
                       'yyyyMMdd')
              else --个人过期即触发流程
               to_char(to_date(t.cert_enddate, 'yyyy-MM-dd') + 1,
                       'yyyyMMdd')
            end as remind_date*/
            --v101+
              from thjs.vw_fxq_cust_certend t) t --视图已过滤，只查正常非测试客户--状态：0-正常 1-失效 2-限制
      left join BASIC_THJS.wb_user u
        on u.user_name = t.op_user
     where t.remind_date <= i_tradedate
       and t.cert_flag in ('客户证件有效截止',
                           '法人代表证件有效截止',
                           '受益所有人证件有效截止')
     order by t.cert_enddate desc;

  commit;

  for cust in (select t.cust_flag, t.cust_id
                 from thjs.tb_fxq_cert_remind t
                where t.busi_date = i_tradedate
                group by t.cust_flag, t.cust_id
                order by t.cust_id) loop
  
    --设置客户状态为限制  
    thjs.p_fxq_cust_rz_l(cust.cust_id,
                         '2', --操作标识：0-正常（解除限制) 1-失效 2-限制
                         'admin', --操作人
                         v_return_msg,
                         v_return_code);
  
    --生成审核记录
    select sys_guid into v_audit_id from dual;
    insert into thjs.tb_fxq_appr_list
      (cust_id, audit_id, remark)
    values
      (cust.cust_id,
       v_audit_id,
       --v101+
       '已设置限制状态，请及时联系客户更新反洗钱表单信息和底稿，完善后请发邮件到合规管理组邮箱（cm_ibd@gtht.com）抄送反洗钱专员，申请解限。');
       --'已设置限制状态，完善后请发邮件到合规管理组邮箱（cm_ibd@gtht.com）抄送反洗钱专员，申请解限。');
       --v101+
  
    insert into thjs.tb_fxq_appr_detail
      (cust_id, audit_id, audit_seq, audit_desc, dispose_desc)
      select t.cust_id,
             v_audit_id,
             rownum,
             case
               when t.cert_flag = '客户证件有效截止' then
                '客户信息错误'
               when t.cert_flag = '法人代表证件有效截止' then
                '客户信息错误'
               when t.cert_flag = '受益所有人证件有效截止' then
                '受益所有人信息错误'
             end as audit_desc,
             case
               when t.cert_flag = '客户证件有效截止' then
                '客户证照有效期截止过期90个自然日'--'客户证照有效期截止过期三个月'--v101+
               when t.cert_flag = '法人代表证件有效截止' then
                '法人代表' || t.dispose_desc || '证件有效截止过期90个自然日'--'证件有效截止过期三个月'--v101+
               when t.cert_flag = '受益所有人证件有效截止' then
                '受益所有人' || t.dispose_desc || '证件有效截止过期90个自然日'--'证件有效截止过期三个月'--v101+
             end as dispose_desc
        from (select t.cust_id,
                     t.cert_flag,
                     min(t.cert_order) as cert_order,
                     listagg(t.remind_name, '、') within group(order by t.cust_id) dispose_desc
                from thjs.tb_fxq_cert_remind t
               where t.busi_date = i_tradedate
                 and t.cust_id = cust.cust_id
               group by t.cust_id, t.cert_flag) t
       order by t.cert_order;
  
    commit;
  
    --每次审核，将发起客户确认流程
    --保存全连接流程代办记录至待发送表
  
    select t.rn
      into v_appr_num
      from (select l.*,
                   row_number() over(partition by l.cust_id order by l.create_time) as rn
              from thjs.tb_fxq_appr_list l) t
     where t.audit_id = v_audit_id;
  
    insert into thjs.tb_flow_inst
      (busi_date,
       flow_code,
       raise_code,
       biz_key,
       title,
       param_info,
       send_status)
      select i_tradedate,
             decode(t.organ_flag,'0','fxq_zrr','fxq_jg') as flow_code,
             'fxq_khsh' as raise_code, --客户审核
             t.client_id,
             t.client_name || ' 反洗钱审核意见情况' as title,
             'cust_id:' || t.client_id || ',cust_name:' || t.client_name ||
             ',appr_num:' || v_appr_num as param_info,
             '0' as send_status --未发送
        from thjs.t_th_client_info/*(select r.cust_id, 'fxq_jg' as flow_code, r.cust_name
                from thjs.tb_fxq_cust_rz r
              union all
              select z.cust_id, 'fxq_zrr' as flow_code, z.cust_name
                from thjs.tb_fxq_cust_zr z)*/ t
       where t.client_id = cust.cust_id
         and not exists
       (select *
                from thjs.tb_flow_inst i
               where i.biz_key = t.client_id
                 and instr(i.param_info, 'appr_num:' || v_appr_num) > 0);
    commit;
  
  end loop;

exception
  -- 非预定义异常处理
  when v_userexp then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    thjs.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
    -- 预定义异常处理
  when others then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    thjs.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
end;

Create or Replace procedure "THJS"."P_FXQ_CUST_ALL_Q" (rt_cursor     out sys_refcursor, --返回游标结果集
                                                  o_return_msg  out varchar2,
                                                  o_return_code out integer) is
  ----------------------------------------------------------------------------------
  --版    权：GTJA
  --版    本：1.0.0
  --开发人员：CZC@GTJA
  --创建日期：20221024
  --模块编号：
  --模块名称：投行反洗钱 - 全客户信息导出 - 投行合规使用
  --功能名称：
  ----------------------------------------------------------------------------------
  --==============================================================================
  --固定变量
  v_userexp exception; -- 用户定义错
  v_tradedate    varchar2(8); -- 任务执行时间(业务日期)
  v_exec_func_id integer default '0'; -- 任务id
  v_func_own     varchar2(20) default 'thjs'; -- 任务归属用户（schema）
  v_func_name    varchar2(2000) default 'p_fxq_cust_all_q'; -- 任务名称(存储过程的名字)
  v_sqlerrm      varchar2(4000); -- 错误提示信息
  v_sqlcode      number; -- 错误代码
  v_sqlerrl      varchar2(4000); -- 错误行号
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  --=============================================================
  -- 业务处理过程
  --=============================================================

begin

  v_tradedate := to_char(sysdate, 'yyyyMMdd');

  open rt_cursor for
    select r.cust_flag, -- 客户类型,
           decode(r.cust_category,
                  '投资端',
                  r.cust_category || '-' || r.cust_type,
                  r.cust_category) as cust_category,
           r.status_desc as status, --"状态",
           u.user_id as update_userid, --'维护人工号'
           u.staff_id as staff_id,
           nvl(p.user_code, r.update_user) as update_user, --"维护人代码",
           u.display_name as update_username, -- ,--"维护人",
           r.update_time, -- "最近更新时间",
           r.create_time, --"初始填报时间",
           r.cust_id, --"客户ID",
           r.cust_name, --"客户名称",
           d1.entry_content as cert_type, --"证照类型",
           r.cert_no, --"证照号码",
           r.cert_startdate, --"证照有效起始",
           r.cert_enddate, --"证照有效截止",
           r.chair_man, --"法人代表姓名",
           r.chair_birth, --"出生年月",
           d2.entry_content as chair_certtype, --"身份证件类型",
           r.chair_certno, --"身份证件号码",
           r.chair_certstart, --"身份证件有效期起始",
           r.chair_certend, --"身份证件有效期截止",           
           kgfr.name as kgfr_name, --"控股股东(法人)姓名",
           kgfr.certtype as kgfr_certtype, --"控股股东(法人)证件类型",
           kgfr.certno as kgfr_certno, --"控股股东(法人)证件号码",
           kgfr.certstart as kgfr_certstart, --"控股股东(法人)证照有效起始",
           kgfr.certend as kgfr_certend, --"控股股东(法人)证照有效截止",
           kgzrr.name as kgzrr_name, --"控股股东(自然人)姓名",
           kgzrr.birth as kgzrr_birth, --"控股股东(自然人)出生年月",
           kgzrr.certtype as kgzrr_certtype, --"控股股东(自然人)证件类型",
           kgzrr.certno as kgzrr_certno, --"控股股东(自然人)证件号码",
           kgzrr.certstart as kgzrr_certstart, --"控股股东(自然人)证件有效期起始",
           kgzrr.certend as kgzrr_certend, --"控股股东(自然人)证件有效期截止",
           skfr.name as skfr_name, --"实控人(法人)姓名",
           skfr.certtype as skfr_certtype, --"实控人(法人)证件类型",
           skfr.certno as skfr_certno, --"实控人(法人)证件号码",
           skfr.certstart as skfr_certstart, --"实控人(法人)证照有效起始",
           skfr.certend as skfr_certend, --"实控人(法人)证照有效截止",
           skzrr.name as skzrr_name, --"实控人(自然人)姓名",
           skzrr.birth as skzrr_birth, --"实控人(自然人)出生年月",
           skzrr.certtype as skzrr_certtype, --"实控人(自然人)证件类型",
           skzrr.certno as skzrr_certno, --"实控人(自然人)证件号码",
           skzrr.certstart as skzrr_certstart, --"实控人(自然人)证件有效期起始",
           skzrr.certend as skzrr_certend, --"实控人(自然人)证件有效期截止",           
           sqr.name as sqr_name, --"授权代表人姓名",
           sqr.birth as sqr_birth, --"授权代表人出生年月",
           sqr.certtype as sqr_certtype, --"授权代表人证件类型",
           sqr.certno as sqr_certno, --"授权代表人证件号码",
           sqr.certstart as sqr_certstart, --"授权代表人证件有效期起始",
           sqr.certend as sqr_certend, --"授权代表人证件有效期截止",       
           syr.name as syr_name, --"受益所有人姓名",
           syr.nationality as syr_nationality, --"受益所有人国籍",
           syr.certtype as syr_certtype, --"受益所有人证件类型",
           syr.certno as syr_certno, --"受益所有人证件号码",
           syr.certstart as syr_certstart, --"受益所有人证件有效期起始",
           syr.certend as syr_certend, --"受益所有人证件有效期截止",
           syr.address as syr_address, --"受益所有人联系地址",
           syr.type as syr_type, --"受益所有人类型",
           syr.equity_ratio as syr_equity_ratio, --"受益所有人股权比例",
           fj.file_name --"附件名称"
      from thjs.vw_fxq_cust_info r
      left join thjs.tb_fxq_cust_operator p
        on p.cust_id = r.cust_id
      left join BASIC_THJS.wb_user u
        on u.user_name = nvl(p.user_code, r.update_user)
      left join thjs.tb_dict_entry d1
        on d1.entry_code = 'CERT_TYPE'
       and d1.entry_value = r.cert_type
      left join thjs.tb_dict_entry d2
        on d2.entry_code = 'CERT_TYPE'
       and d2.entry_value = r.chair_certtype
      left join (select t.cust_id,
                        replace(listagg(nvl(t.name, '□'), ',' || chr(13))
                                within group(order by t.data_order),
                                '□',
                                '') as name,
                        replace(listagg(nvl(t.entry_content, '□'),
                                        ',' || chr(13)) within
                                group(order by t.data_order),
                                '□',
                                '') as certtype,
                        replace(listagg(nvl(t.certno, '□'), ',' || chr(13))
                                within group(order by t.data_order),
                                '□',
                                '') as certno,
                        replace(listagg(nvl(t.certstart, '□'),
                                        ',' || chr(13)) within
                                group(order by t.data_order),
                                '□',
                                '') as certstart,
                        replace(listagg(nvl(t.certend, '□'), ',' || chr(13))
                                within group(order by t.data_order),
                                '□',
                                '') as certend
                   from (select t.*, d.entry_content
                           from thjs.tb_fxq_cust_shareholder t --控股股东
                           left join thjs.tb_dict_entry d
                             on d.entry_code = 'CERT_TYPE'
                            and d.entry_value = t.certtype) t
                  where t.type = '0' --法人
                  group by t.cust_id) kgfr
        on kgfr.cust_id = r.cust_id
      left join (select t.cust_id,
                        replace(listagg(nvl(t.name, '□'), ',' || chr(13))
                                within group(order by t.data_order),
                                '□',
                                '') as name,
                        replace(listagg(nvl(t.birth, '□'), ',' || chr(13))
                                within group(order by t.data_order),
                                '□',
                                '') as birth,
                        replace(listagg(nvl(t.entry_content, '□'),
                                        ',' || chr(13)) within
                                group(order by t.data_order),
                                '□',
                                '') as certtype,
                        replace(listagg(nvl(t.certno, '□'), ',' || chr(13))
                                within group(order by t.data_order),
                                '□',
                                '') as certno,
                        replace(listagg(nvl(t.certstart, '□'),
                                        ',' || chr(13)) within
                                group(order by t.data_order),
                                '□',
                                '') as certstart,
                        replace(listagg(nvl(t.certend, '□'), ',' || chr(13))
                                within group(order by t.data_order),
                                '□',
                                '') as certend
                   from (select t.*, d.entry_content
                           from thjs.tb_fxq_cust_shareholder t --控股股东
                           left join thjs.tb_dict_entry d
                             on d.entry_code = 'CERT_TYPE'
                            and d.entry_value = t.certtype) t
                  where t.type = '1' --自然人
                  group by t.cust_id) kgzrr
        on kgzrr.cust_id = r.cust_id
      left join (select t.cust_id,
                        replace(listagg(nvl(t.name, '□'), ',' || chr(13))
                                within group(order by t.data_order),
                                '□',
                                '') as name,
                        replace(listagg(nvl(t.entry_content, '□'),
                                        ',' || chr(13)) within
                                group(order by t.data_order),
                                '□',
                                '') as certtype,
                        replace(listagg(nvl(t.certno, '□'), ',' || chr(13))
                                within group(order by t.data_order),
                                '□',
                                '') as certno,
                        replace(listagg(nvl(t.certstart, '□'),
                                        ',' || chr(13)) within
                                group(order by t.data_order),
                                '□',
                                '') as certstart,
                        replace(listagg(nvl(t.certend, '□'), ',' || chr(13))
                                within group(order by t.data_order),
                                '□',
                                '') as certend
                   from (select t.*, d.entry_content
                           from thjs.tb_fxq_cust_controller t --实际控制人
                           left join thjs.tb_dict_entry d
                             on d.entry_code = 'CERT_TYPE'
                            and d.entry_value = t.certtype) t
                  where t.type = '0' --法人
                  group by t.cust_id) skfr
        on skfr.cust_id = r.cust_id
      left join (select t.cust_id,
                        replace(listagg(nvl(t.name, '□'), ',' || chr(13))
                                within group(order by t.data_order),
                                '□',
                                '') as name,
                        replace(listagg(nvl(t.birth, '□'), ',' || chr(13))
                                within group(order by t.data_order),
                                '□',
                                '') as birth,
                        replace(listagg(nvl(t.entry_content, '□'),
                                        ',' || chr(13)) within
                                group(order by t.data_order),
                                '□',
                                '') as certtype,
                        replace(listagg(nvl(t.certno, '□'), ',' || chr(13))
                                within group(order by t.data_order),
                                '□',
                                '') as certno,
                        replace(listagg(nvl(t.certstart, '□'),
                                        ',' || chr(13)) within
                                group(order by t.data_order),
                                '□',
                                '') as certstart,
                        replace(listagg(nvl(t.certend, '□'), ',' || chr(13))
                                within group(order by t.data_order),
                                '□',
                                '') as certend
                   from (select t.*, d.entry_content
                           from thjs.tb_fxq_cust_controller t --实际控制人
                           left join thjs.tb_dict_entry d
                             on d.entry_code = 'CERT_TYPE'
                            and d.entry_value = t.certtype) t
                  where t.type = '1' --自然人
                  group by t.cust_id) skzrr
        on skzrr.cust_id = r.cust_id
      left join (select t.cust_id,
                        replace(listagg(nvl(t.name, '□'), ',' || chr(13))
                                within group(order by t.data_order),
                                '□',
                                '') as name,
                        replace(listagg(nvl(t.birth, '□'), ',' || chr(13))
                                within group(order by t.data_order),
                                '□',
                                '') as birth,
                        replace(listagg(nvl(t.entry_content, '□'),
                                        ',' || chr(13)) within
                                group(order by t.data_order),
                                '□',
                                '') as certtype,
                        replace(listagg(nvl(t.certno, '□'), ',' || chr(13))
                                within group(order by t.data_order),
                                '□',
                                '') as certno,
                        replace(listagg(nvl(t.certstart, '□'),
                                        ',' || chr(13)) within
                                group(order by t.data_order),
                                '□',
                                '') as certstart,
                        replace(listagg(nvl(t.certend, '□'), ',' || chr(13))
                                within group(order by t.data_order),
                                '□',
                                '') as certend
                   from (select t.*, d.entry_content
                           from thjs.tb_fxq_cust_authorizer t --授权代表人
                           left join thjs.tb_dict_entry d
                             on d.entry_code = 'CERT_TYPE'
                            and d.entry_value = t.certtype) t
                  group by t.cust_id) sqr
        on sqr.cust_id = r.cust_id
      left join (select t.cust_id,
                        replace(listagg(nvl(t.name, '□'), ',' || chr(13))
                                within group(order by t.data_order),
                                '□',
                                '') as name,
                        replace(listagg(nvl(t.nationality, '□'),
                                        ',' || chr(13)) within
                                group(order by t.data_order),
                                '□',
                                '') as nationality,
                        replace(listagg(nvl(t.entry_content, '□'),
                                        ',' || chr(13)) within
                                group(order by t.data_order),
                                '□',
                                '') as certtype,
                        replace(listagg(nvl(t.certno, '□'), ',' || chr(13))
                                within group(order by t.data_order),
                                '□',
                                '') as certno,
                        replace(listagg(nvl(t.certstart, '□'),
                                        ',' || chr(13)) within
                                group(order by t.data_order),
                                '□',
                                '') as certstart,
                        replace(listagg(nvl(t.certend, '□'), ',' || chr(13))
                                within group(order by t.data_order),
                                '□',
                                '') as certend,
                        replace(listagg(nvl(t.address, '□'), ',' || chr(13))
                                within group(order by t.data_order),
                                '□',
                                '') as address,
                        replace(listagg(nvl(t.type, '□'), ',' || chr(13))
                                within group(order by t.data_order),
                                '□',
                                '') as type,
                        replace(listagg(nvl(t.equity_ratio, '□'),
                                        ',' || chr(13)) within
                                group(order by t.data_order),
                                '□',
                                '') as equity_ratio
                   from (select t.*, d.entry_content
                           from thjs.tb_fxq_cust_beneficiary t --受益所有人
                           left join thjs.tb_dict_entry d
                             on d.entry_code = 'CERT_TYPE'
                            and d.entry_value = t.certtype) t
                  group by t.cust_id) syr
        on syr.cust_id = r.cust_id
      left join (select t.cust_id,
                        replace(listagg(nvl(t.file_name, '□'),
                                        ',' || chr(13)) within
                                group(order by t.file_type, t.file_name),
                                '□',
                                '') as file_name
                   from thjs.vw_fxq_cust_files t
                  where t.status = '0'
                  group by t.cust_id) fj
        on fj.cust_id = r.cust_id
     where r.cust_biz <> '测试'
     order by r.cust_flag, r.cust_id;

  commit;

  o_return_msg  := '执行成功';
  o_return_code := 0;

exception
  -- 非预定义异常处理
  when v_userexp then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    hgman.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
    -- 预定义异常处理
  when others then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    hgman.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
end;

Create or Replace procedure "THJS"."P_FXQ_CUST_AUTHORIZER_Q" (rt_cursor     out sys_refcursor, --返回游标结果集
                                                    i_cust_id     in varchar2, --客户id
                                                    i_qry_flag    in varchar2, --查询标识：0-草稿 1-提交 v101+
                                                    o_return_msg  out varchar2,
                                                    o_return_code out integer) is
  ----------------------------------------------------------------------------------
  --版    权：GTJA
  --版    本：1.0.0
  --v101 YLT@GTJA 20191031 反洗钱客户填报逻辑优化，加上查询草稿数据处理

  --开发人员：CZC@GTJA
  --创建日期：20190603
  --模块编号：
  --模块名称：投行反洗钱 - 客户基本信息（融资端）授权代表人查询
  --功能名称：
  ----------------------------------------------------------------------------------
  --==============================================================================
  --固定变量
  v_userexp exception; -- 用户定义错
  v_tradedate    varchar2(8); -- 任务执行时间(业务日期)
  v_exec_func_id integer default '0'; -- 任务id
  v_func_own     varchar2(20) default 'thjs'; -- 任务归属用户（schema）
  v_func_name    varchar2(2000) default 'p_fxq_cust_authorizer_q'; -- 任务名称(存储过程的名字)
  v_sqlerrm      varchar2(4000); -- 错误提示信息
  v_sqlcode      number; -- 错误代码
  v_sqlerrl      varchar2(4000); -- 错误行号
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  --=============================================================
  -- 业务处理过程
  --=============================================================

begin

  v_tradedate := to_char(sysdate, 'yyyyMMdd');
  --如果是查草稿数据
  if i_qry_flag = '0' then
    open rt_cursor for
      select r.cust_id, --客户id
             s.name, --姓名
             s.birth, --出生年月
             s.certtype, --证件类型
             s.certno, --证件号码
             s.certstart, --证照有效起始
             s.certend, --证照有效截止
             s.data_order
        from thjs.tb_fxq_cust_rz_draft r
       inner join thjs.tb_fxq_cust_authorizer_draft s
          on s.cust_id = r.cust_id
       where r.cust_id = i_cust_id
       order by s.data_order;

    --如果是查正式数据
  elsif i_qry_flag = '1' then
    open rt_cursor for
      select r.cust_id, --客户id
             s.name, --姓名
             s.birth, --出生年月
             s.certtype, --证件类型
