     'p_fxq_cust_controller_q',
     'i_cust_id:' || i_cust_id || '-' || 'i_type:' || i_type || '-' ||
     'i_qry_flag:' || i_qry_flag,
     sysdate);
  commit;

  v_tradedate := to_char(sysdate, 'yyyyMMdd');
  --如果是查草稿数据
  if i_qry_flag = '0' then
    open rt_cursor for
      select r.cust_id, --客户id
             s.type, --股东类型：0-法人 1-自然人
             s.name, --姓名
             s.birth, --出生年月
             s.certtype, --证件类型
             s.certno, --证件号码
             s.certstart, --证照有效起始
             s.certend, --证照有效截止
             s.data_order
        from thjs.tb_fxq_cust_rz_draft r
       inner join thjs.tb_fxq_cust_controller_draft s
          on s.cust_id = r.cust_id
         and (i_type is null or s.type = i_type)
       where r.cust_id = i_cust_id
       order by s.data_order;
    --如果是查正式数据
  elsif i_qry_flag = '1' then
    open rt_cursor for
      select r.cust_id, --客户id
             s.type, --股东类型：0-法人 1-自然人
             s.name, --姓名
             s.birth, --出生年月
             s.certtype, --证件类型
             s.certno, --证件号码
             s.certstart, --证照有效起始
             s.certend, --证照有效截止
             s.data_order
        from thjs.tb_fxq_cust_rz r
       inner join thjs.tb_fxq_cust_controller s
          on s.cust_id = r.cust_id
         and (i_type is null or s.type = i_type)
       where r.cust_id = i_cust_id
       order by s.data_order;
  else
    --万一前端没有传入i_qry_flag标识，查询返回空
    open rt_cursor for
      select '' cust_id, --客户id
             '' type, --股东类型：0-法人 1-自然人
             '' name, --姓名
             '' birth, --出生年月
             '' certtype, --证件类型
             '' certno, --证件号码
             '' certstart, --证照有效起始
             '' certend --证照有效截止
        from dual;
  end if;
  commit;

  o_return_msg  := '执行成功';
  o_return_code := 0;

exception
  -- 非预定义异常处理
  when v_userexp then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    hgman.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
    -- 预定义异常处理
  when others then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    hgman.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
end;

Create or Replace procedure "THJS"."P_FXQ_CUST_CONTROLLER_S" (i_cust_id     in varchar2, --客户id
                                                         i_type        in varchar2, --实际控制人类型：0-法人 1-自然人
                                                         i_name        in varchar2, --姓名
                                                         i_birth       in varchar2, --出生年月
                                                         i_certtype    in varchar2, --证件类型
                                                         i_certno      in varchar2, --证件号码
                                                         i_certstart   in varchar2, --证照有效起始
                                                         i_certend     in varchar2, --证照有效截止
                                                         i_submit_flag in varchar2, --提交标识：0-草稿 1-提交 v101+
                                                         i_order       in varchar2, --用于区分数据展示顺序 v101+
                                                         o_return_msg  out varchar2,
                                                         o_return_code out integer) is
  ----------------------------------------------------------------------------------
  --版    权：GTJA
  --版    本：1.0.0
  --v101 YLT@GTJA 20191031 反洗钱客户填报逻辑优化，加上保存草稿处理

  --开发人员：CZC@GTJA
  --创建日期：20190603
  --模块编号：
  --模块名称：投行反洗钱 - 客户基本信息（融资端）实际控制人填报增删改
  --功能名称：
  ----------------------------------------------------------------------------------
  --==============================================================================
  --固定变量
  v_userexp exception; -- 用户定义错
  v_tradedate    varchar2(8); -- 任务执行时间(业务日期)
  v_exec_func_id integer default '0'; -- 任务id
  v_func_own     varchar2(20) default 'thjs'; -- 任务归属用户（schema）
  v_func_name    varchar2(2000) default 'p_fxq_cust_controller_s'; -- 任务名称(存储过程的名字)
  v_sqlerrm      varchar2(4000); -- 错误提示信息
  v_sqlcode      number; -- 错误代码
  v_sqlerrl      varchar2(4000); -- 错误行号
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  --=============================================================
  -- 业务处理过程
  --=============================================================

begin

  v_tradedate := to_char(sysdate, 'yyyyMMdd');

  /* insert into thjs.tb_test
    (id, text)
  values
    (96,
     'cust_id:' || i_cust_id || ',type:' || i_type || ',name:' || i_name ||
     ',birth:' || i_birth || ',certtype:' || i_certtype || ',certno:' ||
     i_certno || ',certstart:' || i_certstart || ',certend:' || i_certend ||
     ',submit_flag:' || i_submit_flag || ',order:' || i_order);
  commit;*/
  insert into thjs.tb_exec_log
    (log_id, proc_name, proc_param, exec_time)
  values
    (thjs.tb_exec_log_id_seq.nextval,
     'p_fxq_cust_controller_s',
     'cust_id:' || i_cust_id || ',type:' || i_type || ',name:' || i_name ||
     ',birth:' || i_birth || ',certtype:' || i_certtype || ',certno:' ||
     i_certno || ',certstart:' || i_certstart || ',certend:' || i_certend ||
     ',submit_flag:' || i_submit_flag || ',order:' || i_order,
     sysdate);
  commit;

  --如果是保存草稿操作
  if i_submit_flag = '0' then
    insert into thjs.tb_fxq_cust_controller_draft
      (busi_date,
       cust_id,
       type,
       name,
       birth,
       certtype,
       certno,
       certstart,
       certend,
       data_order)
    values
      (v_tradedate,
       i_cust_id,
       i_type,
       i_name,
       to_char(to_date(replace(i_birth, '/', '-'), 'YYYY-MM-DD'),
               'YYYY-MM-DD'),
       i_certtype,
       i_certno,
       to_char(to_date(replace(i_certstart, '/', '-'), 'YYYY-MM-DD'),
               'YYYY-MM-DD'),
       to_char(to_date(replace(i_certend, '/', '-'), 'YYYY-MM-DD'),
               'YYYY-MM-DD'),
       i_order);
  end if;
  --点击‘正式提交’操作时
  if i_submit_flag = '1' then
    insert into thjs.tb_fxq_cust_controller
      (busi_date,
       cust_id,
       type,
       name,
       birth,
       certtype,
       certno,
       certstart,
       certend,
       data_order)
    values
      (v_tradedate,
       i_cust_id,
       i_type,
       i_name,
       to_char(to_date(replace(i_birth, '/', '-'), 'YYYY-MM-DD'),
               'YYYY-MM-DD'),
       i_certtype,
       i_certno,
       to_char(to_date(replace(i_certstart, '/', '-'), 'YYYY-MM-DD'),
               'YYYY-MM-DD'),
       to_char(to_date(replace(i_certend, '/', '-'), 'YYYY-MM-DD'),
               'YYYY-MM-DD'),
       i_order);
    commit;
  
    --KEY:CUST_ID, CATEGORY, CUST_NAME, CERT_TYPE, CERT_NO
    thjs.p_fxq_cust_rsk_zhlc_s(i_cust_id     => i_cust_id,
                               i_name        => i_name,
                               i_submit_flag => i_submit_flag,
                               i_category    => '实际控制人',
                               o_return_msg  => o_return_msg,
                               o_return_code => o_return_code);
  
  end if;
  commit;

  o_return_msg  := '执行成功';
  o_return_code := 0;

exception
  -- 非预定义异常处理
  when v_userexp then
    rollback;
  
    v_sqlerrm := 'cust_id:' || i_cust_id || ',name:' || i_name || ',' ||
                 sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    hgman.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
    -- 预定义异常处理
  when others then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    hgman.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
end;

create or replace procedure thjs.p_fxq_cust_interface_q(rt_cursor     out sys_refcursor, --返回游标结果集
                                                        i_entname     in varchar2, --新增填报业务人员输入客户名称时传入
                                                        i_usercode    in varchar2, --查询人
                                                        o_return_msg  out varchar2,
                                                        o_return_code out integer) is
  ----------------------------------------------------------------------------------
  --版    权：GTJA
  --版    本：1.0.0
  --开发人员：CZC@GTJA
  --创建日期：20190603
  --模块编号：
  --模块名称：投行反洗钱 - 投行智能平台-项目工作室接口 客户基本信息查询
  --功能名称：
  ----------------------------------------------------------------------------------
  --==============================================================================
  --固定变量
  v_userexp exception; -- 用户定义错
  v_tradedate    varchar2(8); -- 任务执行时间(业务日期)
  v_exec_func_id integer default '0'; -- 任务id
  v_func_own     varchar2(20) default 'thjs'; -- 任务归属用户（schema）
  v_func_name    varchar2(2000) default 'p_fxq_cust_interface_q'; -- 任务名称(存储过程的名字)
  v_sqlerrm      varchar2(4000); -- 错误提示信息
  v_sqlcode      number; -- 错误代码
  v_sqlerrl      varchar2(4000); -- 错误行号
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  v_prvlge integer default 0;
  v_count  integer default 0;
  --=============================================================
  -- 业务处理过程
  --=============================================================

begin

  v_tradedate := to_char(sysdate, 'yyyyMMdd');

  --v102+ start
  insert into thjs.tb_exec_log
    (log_id, proc_name, proc_param, exec_time)
  values
    (thjs.tb_exec_log_id_seq.nextval,
     'p_fxq_cust_interface_q',
     'i_entname:' || i_entname || ' -' || 'i_usercode:' || i_usercode,
     sysdate);
  commit;
  --v102+ end

  --检查反洗钱客户是否具有填报权限，无权限直接返回
  select count(1)
    into v_prvlge
    from basic_thjs.wb_user u
   inner join basic_thjs.wb_user_role r
      on u.user_id = r.user_id or u.staff_id = r.user_id --edit by chengjing260326 加了or条件，user表数据差距，兼容两种传参
     and r.role_id in ('fxq_cust_wh', 'fxqtb-th', 'fxqgl') --反洗钱客户维护人，投行反洗钱客户填报人，反洗钱客户管理员
   where u.user_name = i_usercode or u.staff_id = i_usercode; --edit by chengjing260326 加了or条件，user表数据差距，兼容两种传参

  if v_prvlge = 0 then
    open rt_cursor for
      select '0' as user_flag from dual;
    o_return_code := -1;
    o_return_msg  := '当前用户无反洗钱客户填报权限，请联系合规管理员！';
    return;
  end if;

  --20240524  i_entname 可按冒号:分隔客户名称，证件代码传递

  --检查客户类型及是否存在
  open rt_cursor for
    select t.cust_id,
           t.cust_name,
           t.cust_type,
           decode(t.cust_id, null, '0', '1') as is_exists
      from dual
      left join (select *
                   from (select t.client_id as cust_id,
      				    		t.client_name as cust_name,
      				    		t.id_no as cert_no,
      				    		decode(t.organ_flag,'0','1','0') as cust_type
      			   		   from thjs.t_th_client_info t
      			   /*select r.cust_id,
                                r.cust_name,
                                r.cert_no,
                                '0' as cust_type
                           from thjs.tb_fxq_cust_rz r
                          where r.cust_biz <> '测试'
                         union all
                         select z.cust_id,
                                z.cust_name,
                                z.cert_no,
                                '1' as cust_type
                           from thjs.tb_fxq_cust_zr z
                          where z.cust_biz <> '测试'*/) t
                  where exists (select column_value
                           from table(THJS.splitstr(i_entname, ':'))
                          where column_value = t.cert_no
                             or column_value = t.cust_name
                             )) t
        on 1 = 1;

  commit;

  o_return_msg  := '执行成功';
  o_return_code := 0;

exception
  -- 非预定义异常处理
  when v_userexp then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    thjs.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
    -- 预定义异常处理
  when others then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    thjs.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
end;

/***Manager***//***Manager***/CREATE OR REPLACE PROCEDURE "THJS"."P_FXQ_CUST_OPERATOR_Q" (rt_cursor       out sys_refcursor, --返回游标结果集
                                                       i_client_name       in varchar2, --客户名称
                                                       i_new_maintainer    in varchar2, --填报人
                                                       i_usercode          in varchar2, --操作人
                                                       i_page_num          in number default 0, --默认值0,
                                                       i_page_size         in number default 0, --默认值0  如果i_page_num，i_page_size都为0 则不分页，查询全部
                                                       o_total_count       out integer,
                                                       o_return_msg        out varchar2,
                                                       o_return_code       out integer)
AS
  ----------------------------------------------------------------------------------
  --版    权：gtja
  --版    本：1.0.0
  --开发人员：czc@gtja
  --创建日期：20191206
  --模块编号：
  --模块名称：投行反洗钱 - 客户填报人维护信息查询
  --功能名称：
  ----------------------------------------------------------------------------------
  --==============================================================================
  --固定变量
  v_userexp exception; -- 用户定义错
  v_tradedate    varchar2(8); -- 任务执行时间(业务日期)
  v_exec_func_id integer default '0'; -- 任务id
  v_func_own     varchar2(20) default 'amlconfig'; -- 任务归属用户（schema）
  v_func_name    varchar2(2000) default 'p_fxq_cust_rz_qry'; -- 任务名称(存储过程的名字)
  v_sqlerrm      varchar2(4000); -- 错误提示信息
  v_sqlcode      number; -- 错误代码
  v_sqlerrl      varchar2(4000); -- 错误行号
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  v_page_num  number default 0;
  v_page_size number;

  v_fk_flag char(1) default '0'; --反馈结果查看权限标识
  --=============================================================
  -- 业务处理过程
  --=============================================================

BEGIN

  v_tradedate := to_char(sysdate, 'yyyyMMdd');

  if i_page_num is not null then
    v_page_num := i_page_num;
  end if;

  --统计记录条数
  if v_page_num < 1 then
  
    select count(1)
      into o_total_count
      from amlconfig.t_maintainer_info p
     inner join amldata.vw_fxq_cust_info r
        on /*r.cust_biz <> '测试'
       and*/ r.client_id = p.client_id
      left join app.wb_user u
        on p.new_maintainer = u.user_name
     where (i_client_name is null or instr(r.client_name, i_client_name) > 0)
       and (i_new_maintainer is null or instr(p.new_maintainer, i_new_maintainer) > 0 or
           instr(u.display_name, i_new_maintainer) > 0);
  
  end if;

  if i_page_size is not null and i_page_size <> 0 then
    v_page_size := i_page_size;
  else
    v_page_size := o_total_count;
  end if;

  open rt_cursor for
    select p.client_id,
           p.client_name,
           decode(p.status,
                  '0',
                  '正常',
                  '1',
                  '失效',
                  '2',
                  '强限制',
                  '3',
                  '弱限制') as client_status, --客户状态：0-正常 1-失效 2-限制
           p.new_maintainer,
           p.user_name,
           p.update_user,
           p.update_time,
           p.staff_id,
           p.update_staff_id,
           p.update_user_name
      from (select p.*,
                   row_number() over(partition by null order by p.client_id) as rn
              from (select p.client_id,
                           r.client_name,
                           r.status,
                           p.new_maintainer,
                           u.user_name,
                           p.update_user,
                           p.update_time,
                           u.staff_id,
                           uu.staff_id as update_staff_id,
                           uu.display_name as update_user_name
                      from amlconfig.t_maintainer_info p
                      left join app.wb_user u
                        on p.new_maintainer = u.user_name
                      left join app.wb_user uu
                        on p.update_user = uu.user_name
                     inner join amldata.vw_fxq_cust_info r
                        on /*r.cust_biz <> '测试'
                       and*/ r.client_id = p.client_id) p
             where (i_client_name is null or
                   instr(p.client_name, i_client_name) > 0)
               and (i_new_maintainer is null or instr(p.new_maintainer, i_new_maintainer) > 0 or
                   instr(p.user_name, i_new_maintainer) > 0)) p
     where p.rn > v_page_num
       and p.rn <= v_page_num + v_page_size
     order by p.rn;

  commit;

  o_return_msg  := '执行成功';
  o_return_code := 0;

exception
  -- 非预定义异常处理
  when v_userexp then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    amlconfig.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
    -- 预定义异常处理
  when others then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    amlconfig.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
END;

Create or Replace procedure "THJS"."P_FXQ_CUST_OPERATOR_ROLE_Q" (rt_cursor     out types.cursorType,
                                                            i_director    in varchar2,
                                                            i_usercode    in varchar2, --查询人
                                                            o_return_msg  out varchar2,
                                                            o_return_code out integer) is
  ----------------------------------------------------------------------------------
  --版    权：GTJA
  --版    本：1.0.0
  --开发人员：CZC@GTJA
  --创建日期：20191206
  --模块编号：
  --模块名称：投行反洗钱 - 客户填报人维护角色人员信息查询
  --功能名称：
  ----------------------------------------------------------------------------------
  --==============================================================================
  --固定变量
  v_userexp exception; -- 用户定义错
  v_tradedate    varchar2(8); -- 任务执行时间(业务日期)
  v_exec_func_id integer default '0'; -- 任务id
  v_func_own     varchar2(20) default 'thjs'; -- 任务归属用户（schema）
  v_func_name    varchar2(2000) default 'p_fxq_cust_operator_role_q'; -- 任务名称(存储过程的名字)
  v_sqlerrm      varchar2(4000); -- 错误提示信息
  v_sqlcode      number; -- 错误代码
  v_sqlerrl      varchar2(4000); -- 错误行号
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  --=============================================================
  -- 业务处理过程
  --=============================================================

begin

  v_tradedate := to_char(sysdate, 'yyyyMMdd');

  open rt_cursor for
    select u.user_id, u.user_name, u.display_name, u.staff_id
      from BASIC_THJS.wb_user u
     where (i_director is null or instr(u.user_id, i_director) > 0 or
           instr(u.user_name, i_director) > 0 or
           instr(u.display_name, i_director) > 0 or
           instr(u.staff_id, i_director) > 0)
       and exists (select 1
              from BASIC_THJS.wb_user_role r
             where r.role_id = 'fxqtb-th'
               and r.user_id = u.user_id)
     order by u.user_name;

  commit;

  o_return_msg  := '执行成功';
  o_return_code := 0;

exception
  -- 非预定义异常处理
  when v_userexp then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    hgman.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
    -- 预定义异常处理
  when others then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    hgman.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
end;

CREATE OR REPLACE PROCEDURE "THJS"."P_FXQ_CUST_PROJ_LATEST" (rt_cursor     out sys_refcursor, --返回游标结果集
                                                   i_client_id     in integer, --客户id
                                                   i_client_name   in varchar2, --客户名称
                                                   i_page_num in number default 0,  --默认值0,
                                              	   i_page_size in number default 0, --默认值0  如果i_page_num，i_page_size都为0 则不分页，查询全部
                                                   o_total_count out integer,
                                                   o_return_msg  out varchar2,
                                                   o_return_code out integer)
AS
  --版    权：
  --版    本：1.0.0
  --开发人员：
  --创建日期：20260408
  --模块编号：
  --模块名称：投行反洗钱 - 查询客户最新的项目信息
  --功能名称：
  ----------------------------------------------------------------------------------
  --==============================================================================
  --固定变量
  v_userexp      exception;                                  -- 用户定义错
  v_tradedate    varchar2(8);   
  v_exec_func_id integer default '0';                        -- 任务id
  v_func_own     varchar2(20) default 'thjs';           -- 任务归属用户（schema）
  v_func_name    varchar2(2000) default 'p_fxq_cust_rz_qry'; -- 任务名称(存储过程的名字)
  v_sqlerrm      varchar2(4000);                             -- 错误提示信息
  v_sqlcode      number;                                     -- 错误代码
  v_sqlerrl      varchar2(4000);                             -- 错误行号
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  v_page_num  number default 0;
  v_page_size number;
  --=============================================================
  -- 业务处理过程
  --=============================================================

BEGIN

  v_tradedate := to_char(sysdate, 'yyyyMMdd');

  insert into thjs.tb_exec_log
    (log_id, proc_name, proc_param, exec_time)
  values
    (thjs.tb_exec_log_id_seq.nextval,
     'p_fxq_cust_proj_latest',
     'i_cust_id:' || i_client_id || ' -' || 'i_cust_name:' || i_client_name,
     sysdate);
  commit;
  
    --v102+ end
    if i_page_num is not null then
        v_page_num := i_page_num;
    end if;
    
    --统计记录条数
    if v_page_num < 1 then
      select count(1) into o_total_count
        from (select b.client_id,
      		 		 b.client_name,
      		 		 a.projname,
      		 		 a.projtype,
      		 		 a.prostatus,
      		 		 a.projphase,
      		 		 a.createtime,
      		 		 row_number() over(partition by b.client_id order by a.createtime desc) as rn
        		from thjs.ib_v_cust_info a
       		   inner join thjs.t_th_client_info b --thjs.tb_fxq_cust_rz t
          		  on replace(replace(a.khname,'(','（'),')','）') = replace(replace(b.client_name,'(','（'),')','）')) t
       WHERE (t.client_id = i_client_id or i_client_id is null)
         and (t.client_name = i_client_name or i_client_name is null);
    
    end if;
    
    if i_page_size is not null and i_page_size <> 0 then
        v_page_size := i_page_size;
    else
        v_page_size := o_total_count;
    end if;
    
    open rt_cursor for
      select t.client_id,
      		 t.client_name,
      		 t.projname,
      		 t.projtype,
      		 t.prostatus,
      		 t.projphase,
      		 t.createtime,
             t.rn
        from (select b.client_id,
      		 		 b.client_name,
      		 		 a.projname,
      		 		 a.projtype,
      		 		 a.prostatus,
      		 		 a.projphase,
      		 		 a.createtime,
                     row_number() over(partition by null order by a.createtime desc) as rn
        		from thjs.ib_v_cust_info a
       		   inner join thjs.t_th_client_info b --thjs.tb_fxq_cust_rz t
          		  on replace(replace(a.khname,'(','（'),')','）') = replace(replace(b.client_name,'(','（'),')','）')
               WHERE (b.client_id = i_client_id or i_client_id is null)
                 and (b.client_name = i_client_name or i_client_name is null)) t
       WHERE t.rn > v_page_num
         and t.rn <= v_page_num*v_page_size + v_page_size
    order by t.rn;
    
    commit;
    o_return_msg  := '执行成功';
    o_return_code := 0;
exception
    -- 非预定义异常处理
when v_userexp then
    rollback;
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
    thjs.p_write_error_log(i_tradedate    => v_tradedate,
                                i_exec_func_id => v_exec_func_id,
                                i_func_own     => v_func_own,
                                i_func_name    => v_func_name,
                                i_occur_time   => sysdate,
                                i_sqlerrm      => v_sqlerrm,
                                i_sqlcode      => v_sqlcode,
                                i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
    -- 预定义异常处理
when others then
    rollback;
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
    thjs.p_write_error_log(i_tradedate    => v_tradedate,
                                i_exec_func_id => v_exec_func_id,
                                i_func_own     => v_func_own,
                                i_func_name    => v_func_name,
                                i_occur_time   => sysdate,
                                i_sqlerrm      => v_sqlerrm,
                                i_sqlcode      => v_sqlcode,
                                i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
END;

CREATE OR REPLACE PROCEDURE "THJS"."P_FXQ_CUST_PROJ_Q" (rt_cursor     out sys_refcursor, --返回游标结果集
                                                   i_client_id     in integer, --客户id
                                                   i_client_name   in varchar2, --客户名称
                                                   i_usercode    in varchar2, --查询人
                                                   o_return_msg  out varchar2,
                                                   o_return_code out integer)
AS
  --版    权：gtja
  --版    本：1.0.0
  --开发人员：ylt@gtja
  --创建日期：20201104
  --模块编号：
  --模块名称：投行反洗钱 - 客户基本信息（融资端）填报增删改，将客户置为“失效”时，核查该客户关联的项目
  --功能名称：
  ----------------------------------------------------------------------------------
  --v101 ylt@gtja 20201207 项目状态为‘有效’对应逻辑修改

  --==============================================================================
  --固定变量
  v_userexp exception; -- 用户定义错
  v_tradedate    varchar2(8); -- 任务执行时间(业务日期)
  v_exec_func_id integer default '0'; -- 任务id
  v_func_own     varchar2(20) default 'thjs'; -- 任务归属用户（schema）
  v_func_name    varchar2(2000) default 'p_fxq_cust_proj_q'; -- 任务名称(存储过程的名字)
  v_sqlerrm      varchar2(4000); -- 错误提示信息
  v_sqlcode      number; -- 错误代码
  v_sqlerrl      varchar2(4000); -- 错误行号
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  v_count    number; --用于记录返回的项目数量
  v_projname varchar2(2000);
  --=============================================================
  -- 业务处理过程
  --=============================================================

BEGIN

  v_tradedate := to_char(sysdate, 'yyyyMMdd');

  insert into thjs.tb_exec_log
    (log_id, proc_name, proc_param, exec_time)
  values
    (thjs.tb_exec_log_id_seq.nextval,
     'p_fxq_cust_proj_q',
     'i_cust_id:' || i_client_id || ' -' || 'i_cust_name:' || i_client_name ||
     'i_usercode:' || i_usercode,
     sysdate);
  commit;

  select t.cn, t.projnames
    into v_count, v_projname
    from thjs.vw_fxq_cust_proj t --多处使用，抽象为视图
   where t.client_id = i_client_id
      or t.client_name = i_client_name;
  /*from thjs.tb_ib_cust_info proj, thjs.tb_fxq_cust_rz t
  where proj.khname = t.cust_name
       --and proj.pro_is_valid = '1' --项目状态为有效的 v101-
       --v101+ start
    and (proj.pro_status not in ('终止', '冻结', '完成') or
        proj.projphase not in ('项目终止', '项目完成', '兑付完成'))
    and proj.pro_is_valid = '1'
       --v101+ end
    and t.cust_name = i_cust_name
    and exists (select *
           from thjs.tb_projlist_busitype b
          where b.proj_type = proj.projtype
            and b.is_limit_fxq = '1') --只判断作用于反洗钱限制的项目类型*/

  if v_count > 0 then
    open rt_cursor for
      select '该客户关联多个项目，请核查！' || chr(13) || reason /*v_projname*/ message
        from (select t.client_id,
                     t.client_name,
                     t.id_no,
                      count(1) as cn,
                     --wm_concat('<br>'||p.projname||p.projphase||'/'||p.pro_status||'/阶段和状态不符合失效条件,请联系: 信息管理员-'||tt1.i||'/项目负责人-'||tt1.r||'/团队负责人-'||tt1.z||' 处理') as reason
               	     wm_concat('<br>"'||p.projname||'" 工作室状态为'||p.pro_status||', 阶段为'||p.projphase||', 不符合失效条件,请联系: 信息管理员-'||tt1.i||'/项目负责人-'||tt1.r||'/团队负责人-'||tt1.z||' 处理') as reason
               from thjs.tb_ib_cust_info p
              inner join thjs.t_th_client_info t
                 ON replace(REPLACE(p.khname,'(','（'),')','）')=t.client_name
               LEFT join(SELECT t.PROJ_ID,max(CASE WHEN PROJROLE='项目负责人' THEN vals end) AS r,
    max(CASE WHEN PROJROLE='信息管理员' THEN vals end) AS i,
    max(CASE WHEN PROJROLE='业务组长' THEN vals end) AS z 
   from (SELECT m.PROJ_ID,m.PROJROLE,LISTAGG(m.EMPNAME||'('||m.WORKNO||')',',') WITHIN group(ORDER BY 1) AS vals
   FROM thjs.TB_IB_V_FINANCE_PROJMEMBER m
          GROUP BY m.PROJ_ID,m.PROJROLE)t 
  GROUP BY t.proj_id)tt1
 ON p.PROJID=tt1.PROJ_ID
              where (
                     p.pro_status not in ('冻结') AND 
                    (p.pro_status not in ('终止', '完成') or
                    p.projphase not in ('项目终止', '项目完成', '兑付完成')))
                and p.pro_is_valid = '1'
                and exists (select *
                       from thjs.tb_projlist_busitype b
                      where b.proj_type = p.projtype
                        and b.is_limit_fxq = '1')
              group by t.client_id, t.client_name, t.id_no) p 
   WHERE p.client_id in(SELECT client_id FROM thjs.vw_fxq_cust_info t WHERE t.client_id = i_client_id or t.client_name = i_client_name);
  else
    open rt_cursor for
      select '' message from dual;
  end if;

  o_return_msg  := '执行成功';
  o_return_code := 0;

exception
  -- 非预定义异常处理
  when v_userexp then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    thjs.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
    -- 预定义异常处理
  when others then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    thjs.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;

END;

CREATE OR REPLACE PROCEDURE "THJS"."P_FXQ_CUST_REPORT_Q" (rt_cursor     out sys_refcursor, --返回游标结果集

   i_client_name in varchar2, --新增填报业务人员输入客户名称时传入

   i_client_id   in integer, --客户id

   i_usercode  in varchar2, --查询人

                                                       o_return_msg  out varchar2,

                                                       o_return_code out integer

   )

AS

  ----------------------------------------------------------------------------------

  --版    权：gtja

  --版    本：1.0.0

  --开发人员：ylt@gtja

  --创建日期：20200624

  --模块编号：

  --模块名称：投行反洗钱 - 反洗钱客户填报，根据【公司名称】或【统一社会信用代码】进行检索

  --功能名称：

  ----------------------------------------------------------------------------------

  --v101 ylt@gtja 20200724 职业分类选择“其他”时，保存输入框的值

  --v102 ylt@gtja 20201029 客户状态要保存至历史表中

  --v101 ylt@gtja 20201102 填报联系地址分“省市区县”分开保存



  --==============================================================================

  --固定变量

  v_userexp exception; -- 用户定义错

  v_tradedate    varchar2(8); -- 任务执行时间(业务日期)

  v_exec_func_id integer default '0'; -- 任务id

  v_func_own     varchar2(20) default 'thjs'; -- 任务归属用户（schema）

  v_func_name    varchar2(2000) default 'p_fxq_cust_report_q'; -- 任务名称(存储过程的名字)

  v_sqlerrm      varchar2(4000); -- 错误提示信息

  v_sqlcode      number; -- 错误代码

  v_sqlerrl      varchar2(4000); -- 错误行号

  --==============================================================================

  ---------------------------------------------------------------------------------------

  --业务变量

  v_prvlge      integer default 0;

  v_client_id     varchar2(100);

  v_ztgs_count  integer default 0;

  v_ztgs_name   varchar2(200);

  v_fk_flag     char(1) default '0'; --反馈结果查看权限标识

  v_bill_flag   char(1) default '0'; --存托客户EXCEL导入页面查看权限

  v_rz_cnt_byid integer default 0; --记录根据客户id查询 客户类型为'机构'的客户数量

  v_zr_cnt_byid integer default 0; --记录根据客户id查询 客户类型为'自然人'的客户数量

  v_rz_cust_cnt integer default 0; --记录根据客户名称查询 客户类型为'机构'的客户数量

  v_zr_cust_cnt integer default 0; --记录根据客户名称查询 客户类型为'自然人'的客户数量

  v_cnt_byid    integer default 0;

  v_client_cnt    integer default 0;

  --=============================================================

  -- 业务处理过程

  --=============================================================

BEGIN



  v_tradedate := to_char(sysdate, 'yyyyMMdd');



  --v102+ start

  insert into thjs.tb_exec_log

    (log_id, proc_name, proc_param, exec_time)

  values

    (thjs.tb_exec_log_id_seq.nextval,

     'p_fxq_cust_report_q',

     'i_client_name:' || i_client_name || ' -' || 'i_client_id:' || i_client_id || ' -' ||

     'i_usercode:' || i_usercode,

     sysdate);

  commit;

  --v102+ end



  --检查反洗钱客户是否具有填报权限，无权限直接返回

  select count(1)

    into v_prvlge

    from basic_thjs.wb_user u

   inner join basic_thjs.wb_user_role r

      on u.user_id = r.user_id

     and r.role_id in ('fxq_cust_wh ', 'fxqtb-th', 'fxqgl') --反洗钱客户维护人，投行反洗钱客户填报人，反洗钱客户管理员

   where u.user_name = i_usercode;



  /*if v_prvlge = 0 then

    open rt_cursor for

      select '0' as user_flag from dual;

    o_return_code := -1;

    o_return_msg  := '当前用户无反洗钱客户填报权限，请联系合规管理员！';

    return;

  end if;*/

  --检查是否保存过此客户

   

  select count(1)

    into v_cnt_byid

    from thjs.t_th_client_info r

   where r.client_id = i_client_id;



  --反洗钱风险等级划分及筛查结果查询权限

  select case

           when count(1) > 0 then

            '1'

           else

            '0'

         end

    into v_fk_flag

    from basic_thjs.wb_user u

   inner join basic_thjs.wb_user_role r

      on u.user_id = r.user_id

     and r.role_id = 'fxqrisk-th'

   where u.user_name = i_usercode;



  --存托客户EXCEL导入页面查看权限

  select count(1)

    into v_bill_flag

    from dual

   where instr('admin,chenzhengkuan,zhangqilong,' || i_usercode, i_usercode) > 0;



  --如果根据传入的i_client_id在反洗钱客户表中查询不到对应客户

  if v_cnt_byid = 0 then

    --检查该客户名称是否存在反洗钱客户主表中

    if i_client_name is not null then

      

      select count(1)

        into v_client_cnt

        from thjs.t_th_client_info r

       where translate(r.client_name,'()-','（）——') = i_client_name;

    

    end if;

  

    --如果根据客户名称查询到该客户不存在反洗钱客户主表中

    if v_client_cnt = 0 then

      select thjs.seq_fxq_custid.nextval into v_client_id from dual;

    

      --未保存过此客户信息

      --第一次填报，通过所选项目id 查询工商主体表，默认展示相关信息。依次通过客户名称或工商注册号，统一社会信用代码进行匹配查询

      if i_client_name is not null then

      

        --首先根据传入的客户名称与企业名称进行第一次匹配

        select count(1)

          into v_ztgs_count

          from thjs.enterprisebaseinfocollect_v3 e

         where e.entname like i_client_name || '%';

      

        --如果根据 传入的客户名称与注册号 再一次匹配仍未查询到对应的客户数据，

        --则根据 传入的客户名称与统一社会信用代码进行三次匹配

        if v_ztgs_count = 0 then

          select count(1)

            into v_ztgs_count

            from thjs.enterprisebaseinfocollect_v3 e

           where e.credit_code = i_client_name;

        

          --如果根据 传入的客户名称与统一社会信用代码 三次匹配仍未查询到对应的客户数据，

          --那么，给 v_ztgs_name 置空

          if v_ztgs_count = 0 then

            v_ztgs_name := '';

          else

            --如果根据 传入的客户名称与统一社会信用代码 三次匹配查询到对应的客户数据，将对应企业名称值返回给 v_ztgs_name

            select e.entname

              into v_ztgs_name

              from thjs.enterprisebaseinfocollect_v3 e

             where e.credit_code = i_client_name;

          end if;

          

          --根据传入的客户名称直接查询到对应客户数据，则直接将查询到的企业名称值返回给 v_ztgs_name

        elsif v_ztgs_count = 1 then

          select e.entname

            into v_ztgs_name

            from thjs.enterprisebaseinfocollect_v3 e

           where e.entname like i_client_name || '%';

        

          --否则，如果根据传入的客户名称与工商主体表中的企业名称匹配查询到多条数据时，直接将入参的客户名称返回给 v_ztgs_name

        else

          v_ztgs_name := i_client_name;

       end if;

      

        --根据处理后得到的v_ztgs_name查询对应的企业基本信息

        open rt_cursor for

          select nvl(r.client_id, v_client_id) as client_id, --客户id

                 nvl(e.entname,i_client_name) as client_name, --客户名称

                 e.regorg_prov as province, --省

                 e.regorg_city as city, --市

                 e.regorg_county as district, --区

                 regexp_replace(e.dom,

                                e.regorg_prov || '|' || e.regorg_city || '|' ||

                                e.regorg_county) as office_address,

                 --e.address as office_adr, --办公住所exist

                 '0' as industry_type, --行业分类

                 e.industryphy_name as industry_name, --行业分类名称（或其他）

                 to_char(e.opscope) as busi_scope, --经营范围

                 decode(e.regcap,null,'',e.regcap) as register_fund,

                 nvl(d.comments, '0') as register_money_type, --注册资本金币种

                 '3' as id_type, --证件类型

                 e.credit_code as id_no, --证件号码

                 '' as id_begindate, --证照有效起始

                 '' as id_enddate, --证照有效截止

                 e.legal_person as chair_man, --法人代表姓名

                 '' as chair_birth, --法人出生年月

                 '0' as chair_certtype, --法人证件类型

                 '' as chair_certno, --法人证件号码

                 '' chair_certstart, --法人证照有效起始

                 '' as chair_certend, --法人证照有效截止

                 '' as fillin_date, --填写日期

                 decode(r.client_id, null, '0', '1') as is_exists, --客户信息是否已存在：0 否 1 是

                 '1' data_status,

                 '' associatied_date,

                 '' as remark,

                 decode(r.client_id, null, '0', v_fk_flag) as fk_flag

                 --v_bill_flag as bill_flagm --是否具有存托客户EXCEL导入页面查看权限

                 --is_depository_cus --是否存托客户  --

            from dual

            left join thjs.enterprisebaseinfocollect_v3 e

              on e.entname = v_ztgs_name

            left join thjs.t_th_client_info r

              on r.client_name = e.entname

            left join thjs.t_dict_subentry d

              on d.entry_no = 'CURRENCY_CODE'

             and instr(',' || d.comments || ',',

                       ',' || e.regcapcur_name || ',') > 0;

      end if;

    

      --如果根据客户名称查询到该客户已经存在反洗钱客户主表中，直接将该反洗钱客户信息查询出来

    else 

      if v_client_cnt > 0 then

       open rt_cursor for

          select r.client_id, --客户id-系统唯一ID

                 r.client_name, --客户名称

                 r.organ_flag, --客户类型 0个人 1机构

                 r.gender, --性别：男/女

                 r.nationality, --国籍

                 r.birthday, --出生年月

                 r.id_type, --身份证件类型

                 r.id_no, --证件号码

                 r.id_begindate, --证件有效期起始

                 r.id_enddate, --证件有效期截止

                 r.id_address, --身份证证件地址

                 --v103+ start

                 r.province1, --省

                 r.city1, --市

                 r.district1, --区县

                 --v103+ end

                 r.address, --联系地址

                 r.tel, --联系电话

                 r.zipcode, --邮政编码

                 r.profession_code, --职业分类

                 '' as vocation_name, --职称分类名称（或其他） v101+  --字典

                 r.position, --职务

                 r.work_place, --工作单位

                 r.income, --收入

                 r.fillin_date, --填写日期

                 '1' as is_exists, --客户信息是否已存在：0 否 1 是

                 '1' data_status, --数据类型：0-草稿 1-正式数据

                 r.associated_date, --建议业务关系日期

                 r.remark, --填报备注

                 r.province,

                 r.city,

                 r.district,

                 r.office_address, --办公住所

                 r.industry_type, --行业分类

                 d.comments, --行业分类名称（或其他）  --字典

                 r.busi_scope, --经营范围

                 r.register_fund, --注册资本金

                 r.register_money_type, --注册资本金币种

                 a.related_name, --法人代表姓名

                 a.birthday as birthday1, --法人出生年月

                 a.id_type as id_type1, --法人证件类型

                 a.id_no as id_no1, --法人证件号码

                 a.id_begindate as id_begindate1, --法人证照有效起始

                 a.id_enddate as id_enddate1, --法人证照有效截止

                 decode(r.client_id, null, '0', v_fk_flag) as fk_flag,

                 '' as bill_flag --是否具有存托客户EXCEL导入页面查看权限

                 --'' is_depository_cus --是否存托客户

            from thjs.t_th_client_info r --thjs.tb_fxq_cust_zr r

            left join thjs.t_th_relat_info a

              on a.client_id = r.client_id

             and a.related_type = '1'

            left join thjs.t_dict_subentry d

              on d.entry_no = 'INDUSTRY_TYPE'

             and d.subentry = r.industry_type

           where translate(r.client_name,'()-','（）——') = i_client_name;

      end if;

    end if;

  

    --如果根据传入的i_cust_id在反洗钱客户表中查询到对应客户，直接根据i_cust_id查询反洗钱客户主表将该反洗钱客户信息返回

  else

    if v_cnt_byid > 0 then 

     open rt_cursor for

        select r.client_id, --客户id-系统唯一ID

               r.client_name, --客户名称

               r.organ_flag, --客户类型

               r.gender, --性别：男/女

               r.nationality, --国籍

               r.birthday, --出生年月

               r.id_type, --身份证件类型

               r.id_no, --证件号码

               r.id_begindate, --证件有效期起始

               r.id_enddate, --证件有效期截止

               r.id_address, --身份证证件地址

               --v103+ start

               r.province1, --省

               r.city1, --市

               r.district1, --区县

               --v103+ end

               r.address, --联系地址

               r.tel, --联系电话

               r.zipcode, --邮政编码

               r.profession_code, --职业分类

               '' as vocation_name, --职称分类名称（或其他） v101+   --字典

               r.position, --职务

               r.work_place, --工作单位

               r.income, --收入

               r.fillin_date, --填写日期

               '1' as is_exists, --客户信息是否已存在：0 否 1 是

               '1' date_status, --数据类型：0-草稿 1-正式数据

               r.associated_date, --建议业务关系日期

               r.remark, --填报备注

               r.province,

               r.city,

               r.district,

               r.office_address, --办公住所

               r.industry_type, --行业分类

               d.comments, --行业分类名称（或其他）

               r.busi_scope, --经营范围

               r.register_fund, --注册资本金

               r.register_money_type, --注册资本金币种

               a.related_name, --法人代表姓名

               a.birthday as birthday1, --法人出生年月

               a.id_type as id_type1, --法人证件类型

               a.id_no as id_no1, --法人证件号码

               a.id_begindate as id_begindate1, --法人证照有效起始

               a.id_enddate as id_enddate1, --法人证照有效截止

               decode(r.client_id, null, '0', v_fk_flag) as fk_flag,

               '' as bill_flag --是否具有存托客户EXCEL导入页面查看权限

               --'' is_depository_cus --是否存托客户

          from thjs.t_th_client_info r

          left join thjs.t_th_relat_info a

            on r.client_id = a.client_id

           and a.related_type = '1'

          left join thjs.t_dict_subentry d

            on d.entry_no = 'INDUSTRY_TYPE'

           and d.subentry = r.industry_type

         where r.client_id = i_client_id;

    end if; 

  end if;



  commit;



  o_return_msg  := '执行成功';

  o_return_code := 0;



exception

  -- 非预定义异常处理

  when v_userexp then

    rollback;

  

    v_sqlerrm := sqlerrm;

    v_sqlcode := sqlcode;

    v_sqlerrl := dbms_utility.format_error_backtrace();

  

    thjs.p_write_error_log(i_tradedate    => v_tradedate,

                           i_exec_func_id => v_exec_func_id,

                           i_func_own     => v_func_own,

                           i_func_name    => v_func_name,

                           i_occur_time   => sysdate,

                           i_sqlerrm      => v_sqlerrm,

                           i_sqlcode      => v_sqlcode,

                           i_sqlerrl      => v_sqlerrl);

    commit;

    raise;

    -- 预定义异常处理

  when others then

    rollback;

  

    v_sqlerrm := sqlerrm;

    v_sqlcode := sqlcode;

    v_sqlerrl := dbms_utility.format_error_backtrace();

  

   thjs.p_write_error_log(i_tradedate    => v_tradedate,

                           i_exec_func_id => v_exec_func_id,

                           i_func_own     => v_func_own,

                           i_func_name    => v_func_name,

                           i_occur_time   => sysdate,

                           i_sqlerrm      => v_sqlerrm,

                           i_sqlcode      => v_sqlcode,

                           i_sqlerrl      => v_sqlerrl);

    commit;

    raise;



END;

CREATE OR REPLACE PROCEDURE "THJS"."P_FXQ_CUST_REPORT_Q_bf" (rt_cursor     out sys_refcursor, --返回游标结果集
															   i_client_name in varchar2, --新增填报业务人员输入客户名称时传入
															   i_client_id   in integer, --客户id
															   i_usercode	 in varchar2, --查询人
                                                   			   o_return_msg  out varchar2,
                                                   			   o_return_code out integer
															   )
AS
  ----------------------------------------------------------------------------------
  --版    权：gtja
  --版    本：1.0.0
  --开发人员：ylt@gtja
  --创建日期：20200624
  --模块编号：
  --模块名称：投行反洗钱 - 反洗钱客户填报，根据【公司名称】或【统一社会信用代码】进行检索
  --功能名称：
  ----------------------------------------------------------------------------------
  --v101 ylt@gtja 20200724 职业分类选择“其他”时，保存输入框的值
  --v102 ylt@gtja 20201029 客户状态要保存至历史表中
  --v101 ylt@gtja 20201102 填报联系地址分“省市区县”分开保存

  --==============================================================================
  --固定变量
  v_userexp exception; -- 用户定义错
  v_tradedate    varchar2(8); -- 任务执行时间(业务日期)
  v_exec_func_id integer default '0'; -- 任务id
  v_func_own     varchar2(20) default 'THJS'; -- 任务归属用户（schema）
  v_func_name    varchar2(2000) default 'p_fxq_cust_report_q'; -- 任务名称(存储过程的名字)
  v_sqlerrm      varchar2(4000); -- 错误提示信息
  v_sqlcode      number; -- 错误代码
  v_sqlerrl      varchar2(4000); -- 错误行号
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  v_prvlge      integer default 0;
  v_client_id     varchar2(100);
  v_ztgs_count  integer default 0;
  v_ztgs_name   varchar2(200);
  v_fk_flag     char(1) default '0'; --反馈结果查看权限标识
  v_bill_flag   char(1) default '0'; --存托客户EXCEL导入页面查看权限
  v_rz_cnt_byid integer default 0; --记录根据客户id查询 客户类型为'机构'的客户数量
  v_zr_cnt_byid integer default 0; --记录根据客户id查询 客户类型为'自然人'的客户数量
  v_rz_cust_cnt integer default 0; --记录根据客户名称查询 客户类型为'机构'的客户数量
  v_zr_cust_cnt integer default 0; --记录根据客户名称查询 客户类型为'自然人'的客户数量
  v_cnt_byid    integer default 0;
  v_client_cnt    integer default 0;
  --=============================================================
  -- 业务处理过程
  --=============================================================
BEGIN

  v_tradedate := to_char(sysdate, 'yyyyMMdd');

  --v102+ start
  insert into thjs.tb_exec_log
    (log_id, proc_name, proc_param, exec_time)
  values
    (thjs.tb_exec_log_id_seq.nextval,
     'p_fxq_cust_report_q',
     'i_client_name:' || i_client_name || ' -' || 'i_client_id:' || i_client_id || ' -' ||
     'i_usercode:' || i_usercode,
     sysdate);
  commit;
  --v102+ end

  --检查反洗钱客户是否具有填报权限，无权限直接返回
  select count(1)
    into v_prvlge
    from basic_thjs.wb_user u
   inner join basic_thjs.wb_user_role r
      on u.user_id = r.user_id
     and r.role_id in ('fxq_cust_wh', 'fxqtb-th', 'fxqgl') --反洗钱客户维护人，投行反洗钱客户填报人，反洗钱客户管理员
   where u.user_name = i_usercode;

  if v_prvlge = 0 then
    open rt_cursor for
      select '0' as user_flag from dual;
    o_return_code := -1;
    o_return_msg  := '当前用户无反洗钱客户填报权限，请联系合规管理员！';
    return;
  end if;
  --检查是否保存过此客户
   
  select count(1)
    into v_cnt_byid
    from thjs.t_th_client_info r
   where r.client_id = i_client_id;

  --反洗钱风险等级划分及筛查结果查询权限
  select case
           when count(1) > 0 then
            '1'
           else
            '0'
         end
    into v_fk_flag
    from basic_thjs.wb_user u
   inner join basic_thjs.wb_user_role r
      on u.user_id = r.user_id
     and r.role_id = 'fxqrisk-th'
   where u.user_name = i_usercode;

  --存托客户EXCEL导入页面查看权限
  select count(1)
    into v_bill_flag
    from dual
   where instr('admin,chenzhengkuan,zhangqilong,' || i_usercode, i_usercode) > 0;

  --如果根据传入的i_client_id在反洗钱客户表中查询不到对应客户
  if v_cnt_byid = 0 then
    --检查该客户名称是否存在反洗钱客户主表中
    if i_client_name is not null then
      
      select count(1)
        into v_client_cnt
        from thjs.t_th_client_info r
       where r.client_name = i_client_name;
    
    end if;
  
    --如果根据客户名称查询到该客户不存在反洗钱客户主表中
    if v_client_cnt = 0 then
      select thjs.seq_fxq_custid.nextval into v_client_id from dual;
    
      --未保存过此客户信息
      --第一次填报，通过所选项目id 查询工商主体表，默认展示相关信息。依次通过客户名称或工商注册号，统一社会信用代码进行匹配查询
      if i_client_name is not null then
      
        --首先根据传入的客户名称与企业名称进行第一次匹配
        select count(1)
          into v_ztgs_count
          from thjs.enterprisebaseinfocollect_v3 e
         where e.entname like i_client_name || '%';
      
        --如果根据 传入的客户名称与注册号 再一次匹配仍未查询到对应的客户数据，
        --则根据 传入的客户名称与统一社会信用代码进行三次匹配
        if v_ztgs_count = 0 then
          select count(1)
            into v_ztgs_count
            from thjs.enterprisebaseinfocollect_v3 e
           where e.credit_code = i_client_name;
        
          --如果根据 传入的客户名称与统一社会信用代码 三次匹配仍未查询到对应的客户数据，
          --那么，给 v_ztgs_name 置空
          if v_ztgs_count = 0 then
            v_ztgs_name := '';
          else
            --如果根据 传入的客户名称与统一社会信用代码 三次匹配查询到对应的客户数据，将对应企业名称值返回给 v_ztgs_name
            select e.entname
              into v_ztgs_name
              from thjs.enterprisebaseinfocollect_v3 e
             where e.credit_code = i_client_name;
          end if;
          
          --根据传入的客户名称直接查询到对应客户数据，则直接将查询到的企业名称值返回给 v_ztgs_name
        elsif v_ztgs_count = 1 then
          select e.entname
            into v_ztgs_name
            from thjs.enterprisebaseinfocollect_v3 e
           where e.entname like i_client_name || '%';
        
          --否则，如果根据传入的客户名称与工商主体表中的企业名称匹配查询到多条数据时，直接将入参的客户名称返回给 v_ztgs_name
        else
          v_ztgs_name := i_client_name;
       end if;
      
        --根据处理后得到的v_ztgs_name查询对应的企业基本信息
        open rt_cursor for
          select nvl(r.client_id, v_client_id) as client_id, --客户id
                 nvl(e.entname, i_client_name) as clientt_name, --客户名称
                 e.regorg_prov as province, --省
                 e.regorg_city as city, --市
                 e.regorg_county as district, --区
                 regexp_replace(e.dom,
                                e.regorg_prov || '|' || e.regorg_city || '|' ||
                                e.regorg_county) as office_address,
                 --e.address as office_adr, --办公住所exist
                 '0' as industry_type, --行业分类
                 e.industryphy_name as industry_name, --行业分类名称（或其他）
                 to_char(e.opscope) as busi_scope, --经营范围
                 decode(e.regcap,null,'',e.regcap) as register_fund,
                 nvl(d.comments, '0') as register_money_type, --注册资本金币种
                 '3' as id_type, --证件类型
                 e.credit_code as id_no, --证件号码
                 '' as id_begindate, --证照有效起始
                 '' as id_enddate, --证照有效截止
                 e.legal_person as chair_man, --法人代表姓名
                 '' as chair_birth, --法人出生年月
                 '0' as chair_certtype, --法人证件类型
                 '' as chair_certno, --法人证件号码
                 '' chair_certstart, --法人证照有效起始
                 '' as chair_certend, --法人证照有效截止
                 '' as fillin_date, --填写日期
                 decode(r.client_id, null, '0', '1') as is_exists, --客户信息是否已存在：0 否 1 是
                 '1' data_status,
                 '' associatied_date,
                 '' as remark,
                 decode(r.client_id, null, '0', v_fk_flag) as fk_flag
                 --v_bill_flag as bill_flagm --是否具有存托客户EXCEL导入页面查看权限
                 --is_depository_cus --是否存托客户  --
            from dual
            left join thjs.enterprisebaseinfocollect_v3 e
              on e.entname = v_ztgs_name
            left join thjs.t_th_client_info r
              on r.client_name = e.entname
            left join thjs.t_dict_subentry d
              on d.entry_no = 'CURRENCY_CODE'
             and instr(',' || d.comments || ',',
                       ',' || e.regcapcur_name || ',') > 0;
      end if;
    
      --如果根据客户名称查询到该客户已经存在反洗钱客户主表中，直接将该反洗钱客户信息查询出来
    else 
      if v_client_cnt > 0 then
      	open rt_cursor for
          select r.client_id, --客户id-系统唯一ID
                 r.client_name, --客户名称
                 r.gender, --性别：男/女
                 r.nationality, --国籍
                 r.birthday, --出生年月
                 r.id_type, --身份证件类型
                 r.id_no, --证件号码
                 r.id_begindate, --证件有效期起始
                 r.id_enddate, --证件有效期截止
                 r.id_address, --身份证证件地址
                 --v103+ start
                 r.province1, --省
                 r.city1, --市
                 r.district1, --区县
                 --v103+ end
                 r.address, --联系地址
                 r.tel, --联系电话
                 r.zipcode, --邮政编码
                 r.profession_code, --职业分类
                 '' as vocation_name, --职称分类名称（或其他） v101+  --字典
                 r.position, --职务
                 r.work_place, --工作单位
                 r.income, --收入
                 r.fillin_date, --填写日期
                 '1' as is_exists, --客户信息是否已存在：0 否 1 是
                 '1' data_status, --数据类型：0-草稿 1-正式数据
                 r.associated_date, --建议业务关系日期
                 r.remark, --填报备注
                 r.province,
                 r.city,
                 r.district,
                 r.office_address, --办公住所
                 r.industry_type, --行业分类
                 d.comments, --行业分类名称（或其他）  --字典
                 r.busi_scope, --经营范围
                 r.register_fund, --注册资本金
                 r.register_money_type, --注册资本金币种
                 a.related_name, --法人代表姓名
                 a.birthday, --法人出生年月
                 a.id_type, --法人证件类型
                 a.id_no, --法人证件号码
                 a.id_begindate, --法人证照有效起始
                 a.id_enddate, --法人证照有效截止
                 '' as fk_flag,
                 '' as bill_flag --是否具有存托客户EXCEL导入页面查看权限
                 --'' is_depository_cus --是否存托客户
            from thjs.t_th_client_info r --thjs.tb_fxq_cust_zr r
            left join thjs.t_th_relat_info a
              on a.client_id = r.client_id
             and a.related_type = '1'
            left join thjs.t_dict_subentry d
              on d.entry_no = 'INDUSTRY_TYPE'
             and d.subentry = r.industry_type
           where r.client_name = i_client_name;
      end if;
    end if;
  
    --如果根据传入的i_cust_id在反洗钱客户表中查询到对应客户，直接根据i_cust_id查询反洗钱客户主表将该反洗钱客户信息返回
  else
    if v_cnt_byid > 0 then 
    	open rt_cursor for
        select r.client_id, --客户id-系统唯一ID
               r.client_name, --客户名称
               r.gender, --性别：男/女
               r.nationality, --国籍
               r.birthday, --出生年月
               r.id_type, --身份证件类型
               r.id_no, --证件号码
               r.id_begindate, --证件有效期起始
               r.id_enddate, --证件有效期截止
               r.id_address, --身份证证件地址
               --v103+ start
               r.province1, --省
               r.city1, --市
               r.district1, --区县
               --v103+ end
               r.address, --联系地址
               r.tel, --联系电话
               r.zipcode, --邮政编码
               r.profession_code, --职业分类
               '' as vocation_name, --职称分类名称（或其他） v101+   --字典
               r.position, --职务
               r.work_place, --工作单位
               r.income, --收入
               r.fillin_date, --填写日期
               '1' as is_exists, --客户信息是否已存在：0 否 1 是
               '1' date_status, --数据类型：0-草稿 1-正式数据
               r.associated_date, --建议业务关系日期
               r.remark, --填报备注
               r.province,
               r.city,
               r.district,
               r.office_address, --办公住所
               r.industry_type, --行业分类
               d.comments, --行业分类名称（或其他）
               r.busi_scope, --经营范围
               r.register_fund, --注册资本金
               r.register_money_type, --注册资本金币种
               a.related_name, --法人代表姓名
               a.birthday, --法人出生年月
               a.id_type, --法人证件类型
               a.id_no, --法人证件号码
               a.id_begindate, --法人证照有效起始
               a.id_enddate, --法人证照有效截止
               '' as fk_flag,
               '' as bill_flag --是否具有存托客户EXCEL导入页面查看权限
               --'' is_depository_cus --是否存托客户
          from thjs.t_th_client_info r
          left join thjs.t_th_relat_info a
            on r.client_id = a.client_id
           and a.related_type = '1'
          left join thjs.t_dict_subentry d
            on d.entry_no = 'INDUSTRY_TYPE'
           and d.subentry = r.industry_type
         where r.client_id = i_client_id;
    end if; 
  end if;

  commit;

  o_return_msg  := '执行成功';
  o_return_code := 0;

exception
  -- 非预定义异常处理
  when v_userexp then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    THJS.p_write_error_log(i_tradedate    => v_tradedate,
                           i_exec_func_id => v_exec_func_id,
                           i_func_own     => v_func_own,
                           i_func_name    => v_func_name,
                           i_occur_time   => sysdate,
                           i_sqlerrm      => v_sqlerrm,
                           i_sqlcode      => v_sqlcode,
                           i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
    -- 预定义异常处理
  when others then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
   THJS.p_write_error_log(i_tradedate    => v_tradedate,
                           i_exec_func_id => v_exec_func_id,
                           i_func_own     => v_func_own,
                           i_func_name    => v_func_name,
                           i_occur_time   => sysdate,
                           i_sqlerrm      => v_sqlerrm,
                           i_sqlcode      => v_sqlcode,
                           i_sqlerrl      => v_sqlerrl);
    commit;
    raise;

END;

Create or Replace procedure "THJS"."P_FXQ_CUST_RSK_ZHLC_S" (i_cust_id     in varchar2, --客户id
                                                       i_name        in varchar2, --姓名
                                                       i_submit_flag in varchar2, --提交标识：0-草稿 1-提交 
                                                       i_category    in varchar2,
                                                       o_return_msg  out varchar2,
                                                       o_return_code out integer) is
  ----------------------------------------------------------------------------------
  --版    权：GTJA
  --版    本：1.0.0
  --开发人员：CZC@GTJA
  --创建日期：20210728
  --模块编号：
  --模块名称：投行反洗钱 - 客户实时风险核查 综合理财接口数据保存
  --功能名称：
  ----------------------------------------------------------------------------------
  --==============================================================================
  --固定变量
  v_userexp exception; -- 用户定义错
  v_tradedate    varchar2(8); -- 任务执行时间(业务日期)
  v_exec_func_id integer default '0'; -- 任务id
  v_func_own     varchar2(20) default 'thjs'; -- 任务归属用户（schema）
  v_func_name    varchar2(2000) default 'p_fxq_cust_shareholder_s'; -- 任务名称(存储过程的名字)
  v_sqlerrm      varchar2(4000); -- 错误提示信息
  v_sqlcode      number; -- 错误代码
  v_sqlerrl      varchar2(4000); -- 错误行号
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  --=============================================================
  -- 业务处理过程
  --=============================================================

begin

  v_tradedate := to_char(sysdate, 'yyyyMMdd');

  --点击‘正式提交’操作时
  if i_submit_flag = '1' then
  
    --KEY:CUST_ID, CATEGORY, CUST_NAME, CERT_TYPE, CERT_NO
    insert into thjs.tb_fxq_cust_rsk_zhlc
      (cust_type,
       cust_id,
       cust_flag,
       category,
       cust_name,
       country,
       cert_type,
       cert_no,
       birthday,
       create_date,
       update_date)
      select r.cust_type,
             r.cust_id,
             r.cust_flag,
             r.category,
             r.cust_name,
             r.country,
             r.cert_type,
             r.cert_no,
             r.birthday,
             sysdate, --r.create_time,
             sysdate --r.update_time
        from thjs.vw_fxq_cust_effect r
       where r.cust_id = i_cust_id
         and exists (select 1
                from thjs.tb_fxq_cust_rz c
               where c.cust_id = r.cust_id
                 and c.busi_date = v_tradedate --实时数据，当日新增
                 and c.update_time = c.create_time)
         and instr(i_category, r.category) > 0
         and r.cert_type is not null
         and r.cert_no is not null
         and not exists (select 1
                from thjs.tb_fxq_cust_rsk_zhlc t
               where t.cust_id = r.cust_id
                 and t.category = r.category
                 and t.cust_name = r.cust_name
                 and t.cert_type = r.cert_type
                 and t.cert_no = r.cert_no);
    commit;
  
  end if;
  commit;

  o_return_msg  := '执行成功';
  o_return_code := 0;

exception
  -- 非预定义异常处理
  when v_userexp then
    rollback;
  
    v_sqlerrm := 'cust_id:' || i_cust_id || ',name:' || i_name || ',' ||
                 sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    hgman.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    --raise;
  -- 预定义异常处理
  when others then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    hgman.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    --raise;
end;

Create or Replace procedure "THJS"."P_FXQ_CUST_RZ_APPR_MAIN_S" (i_cust_id     in varchar2,
                                                           i_audit_id    in varchar2,
                                                           i_remark      in varchar2,
                                                           i_create_user in varchar2,
                                                           i_update_user in varchar2,
                                                           i_usercode    in varchar2, --查询用户
                                                           o_return_msg  out varchar2,
                                                           o_return_code out integer) is
  ----------------------------------------------------------------------------------
  --版    权：GTJA
  --版    本：1.0.0
  --开发人员：YLT@GTJA
  --创建日期：20210119
  --模块编号：
  --模块名称：反洗钱客户管理 - 机构填报审核 - 审核主记录信息保存
  --功能名称：机构填报审核信息保存
  ----------------------------------------------------------------------------------

  --==============================================================================
  --固定变量
  v_userexp exception; -- 用户定义错
  v_tradedate    varchar2(8); -- 任务执行时间(业务日期)
  v_exec_func_id integer default '0'; -- 任务id
  v_func_own     varchar2(20) default 'thjs'; -- 任务归属用户（schema）
  v_func_name    varchar2(2000) default 'p_fxq_cust_rz_appr_main_s'; -- 任务名称(存储过程的名字)
  v_sqlerrm      varchar2(4000); -- 错误提示信息
  v_sqlcode      number; -- 错误代码
  v_sqlerrl      varchar2(4000); -- 错误行号
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  v_count    integer default 0;
  v_appr_num integer default 1;
  --=============================================================
  -- 业务处理过程
  --=============================================================

begin

  v_tradedate := to_char(sysdate, 'yyyyMMdd');

  insert into thjs.tb_exec_log
    (log_id, proc_name, proc_param, exec_time)
  values
    (thjs.tb_exec_log_id_seq.nextval,
     'p_fxq_cust_rz_appr_main_s',
     'i_cust_id:' || i_cust_id || '-i_audit_id:' || i_audit_id ||
     '-i_remark:' || i_remark || '-i_usercode:' || i_usercode,
     sysdate);
  commit;

  select count(1)
    into v_count
    from thjs.tb_fxq_appr_list t
   where t.cust_id = i_cust_id
     and t.audit_id = i_audit_id;

  --同一次审核多次提交
  --主记录保存时删除所有历史保存项
  if v_count > 0 then
  
    delete from thjs.tb_fxq_appr_detail d
     where d.cust_id = i_cust_id
       and d.audit_id = i_audit_id;
  
    delete from THJS.TB_FXQ_APPR_LIST t
     where t.cust_id = i_cust_id
       and t.audit_id = i_audit_id;
  
    commit;
  
  end if;

  insert into THJS.TB_FXQ_APPR_LIST
    (CUST_ID,
     AUDIT_ID,
     REMARK,
     CREATE_USER,
     CREATE_TIME,
     UPDATE_USER,
     UPDATE_TIME)
  values
    (i_cust_id,
     i_audit_id,
     i_remark,
     nvl(i_create_user, i_usercode),
     sysdate,
     nvl(i_update_user, i_usercode),
     sysdate);
  commit;

  select t.rn
    into v_appr_num
    from (select l.*,
                 row_number() over(partition by l.cust_id order by l.create_time) as rn
            from THJS.TB_FXQ_APPR_LIST l) t
   where t.audit_id = i_audit_id;

  --20210419-每次审核，将发起客户确认流程
  --保存全连接流程代办记录至待发送表
  insert into thjs.tb_flow_inst
    (busi_date,
     flow_code,
     raise_code,
     biz_key,
     title,
     param_info,
     send_status)
    select v_tradedate,
           t.flow_code,
           'fxq_khsh' as raise_code, --客户审核
           t.cust_id,
           t.cust_name || ' 反洗钱审核意见情况' as title,
           'cust_id:' || t.cust_id || ',cust_name:' || t.cust_name ||
           ',appr_num:' || v_appr_num as param_info,
           '0' as send_status --未发送
      from (select r.cust_id, 'fxq_jg' as flow_code, r.cust_name
              from thjs.tb_fxq_cust_rz r
            union all
            select z.cust_id, 'fxq_zrr' as flow_code, z.cust_name
              from thjs.tb_fxq_cust_zr z) t
     where t.cust_id = i_cust_id;
  commit;

  o_return_msg  := '执行成功';
  o_return_code := 0;

exception
  -- 非预定义异常处理
  when v_userexp then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    hgman.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
    -- 预定义异常处理
  when others then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    hgman.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
end;

Create or Replace procedure "THJS"."P_FXQ_CUST_RZ_APPR_S" (i_cust_id      in varchar2,
                                                      i_audit_id     in varchar2,
                                                      i_audit_seq    in varchar2,
                                                      i_audit_desc   in varchar2,
                                                      i_dispose_desc in varchar2,
