     i_audit_id,
     i_audit_seq,
     i_audit_desc,
     i_dispose_desc,
     i_score,
     sys_guid(),
     nvl(i_create_user, i_usercode),
     sysdate,
     nvl(i_update_user, i_usercode),
     sysdate);
  commit;

  o_return_msg  := '执行成功';
  o_return_code := 0;

exception
  -- 非预定义异常处理
  when v_userexp then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    hgman.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
    -- 预定义异常处理
  when others then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    hgman.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
end;

Create or Replace procedure "THJS"."P_FXQ_CUST_RZ_BILLRST_Q" (rt_cursor        out sys_refcursor, --返回游标结果集
                                                    i_sno            in integer, --序号
                                                    i_comp_name      in varchar2, --公司名称
                                                    i_cert_no        in varchar2, --统一社会信用代码
                                                    i_chair_man      in varchar2, --法定代表人姓名
                                                    i_chair_certtype in varchar2, --法定代表人证件类型
                                                    i_chair_certno   in varchar2, --法定代表人证件号码
                                                    o_return_msg     out varchar2,
                                                    o_return_code    out integer) is
  ----------------------------------------------------------------------------------
  --版    权：GTJA
  --版    本：1.0.0
  --开发人员：YLT@GTJA
  --创建日期：20200420
  --模块编号：
  --模块名称：投行反洗钱 - 客户基本信息（融资端）存托客户风险核查（道琼斯黑名单筛查）
  --功能名称：
  ----------------------------------------------------------------------------------
  --==============================================================================
  --固定变量
  v_userexp exception; -- 用户定义错
  v_tradedate    varchar2(8); -- 任务执行时间(业务日期)
  v_exec_func_id integer default '0'; -- 任务id
  v_func_own     varchar2(20) default 'thjs'; -- 任务归属用户（schema）
  v_func_name    varchar2(2000) default 'p_fxq_cust_rz_billrst_q'; -- 任务名称(存储过程的名字)
  v_sqlerrm      varchar2(4000); -- 错误提示信息
  v_sqlcode      number; -- 错误代码
  v_sqlerrl      varchar2(4000); -- 错误行号
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  v_count integer default 0;
  v_if_a1 varchar2(200);
  v_if_a2 varchar2(200);
  v_if_a3 varchar2(200);
  --=============================================================
  -- 业务处理过程
  --=============================================================

begin

  /*v_tradedate := to_char(sysdate, 'yyyyMMdd');
  
  --保存反洗钱系统道琼斯黑名单至临时表
  select count(1)
    into v_count
    from thjs.tmp_cust_rz_billrst_1 t
   where t.busi_date = v_tradedate;
  if v_count = 0 then
    execute immediate 'truncate table thjs.tmp_cust_rz_billrst_1';
    insert into thjs.tmp_cust_rz_billrst_1
      (busi_date,
       id,
       type,
       first_name,
       middle_name,
       surname,
       suffix,
       fms_name,
       fsm_name,
       mfs_name,
       msf_name,
       sfm_name,
       smf_name,
       entityname,
       other_name,
       birth_day,
       active_status,
       image_url,
       biz_date,
       idnumber_type,
       idnumber,
       idnotes,
       country_type,
       country_code,
       country_name,
       addressline,
       addresscity,
       addresscountry,
       countrycode,
       countryname,
       adderss_countrycode,
       if_a1,
       if_a2,
       if_a3)
      SELECT \*+materialize parallel(t,4)*\
       v_tradedate,
       ID,
       TYPE,
       FIRST_NAME,
       MIDDLE_NAME,
       SURNAME,
       upper(SUFFIX) SUFFIX,
       UPPER(T.FIRST_NAME || T.MIDDLE_NAME || T.SURNAME) FMS_NAME,
       upper(t.first_name || t.surname || t.middle_name) FSM_NAME,
       upper(t.middle_name || t.first_name || t.surname) MFS_NAME,
       upper(t.middle_name || t.surname || t.first_name) MSF_NAME,
       upper(t.surname || t.first_name || t.middle_name) SFM_NAME,
       upper(t.surname || t.middle_name || t.first_name) SMF_NAME,
       upper(ENTITYNAME) ENTITYNAME,
       upper(OTHER_NAME) OTHER_NAME,
       BIRTH_DAY,
       ACTIVE_STATUS,
       IMAGE_URL,
       BIZ_DATE,
       IDNUMBER_TYPE,
       replace(idnumber, '-') idnumber,
       IDNOTES,
       COUNTRY_TYPE,
       COUNTRY_CODE,
       COUNTRY_NAME,
       ADDRESSLINE,
       ADDRESSCITY,
       ADDRESSCOUNTRY,
       COUNTRYCODE,
       COUNTRYNAME,
       --LIST_INFO,
       --RELATION_INFO,
       ADDERSS_COUNTRYCODE,
       t.if_a1,
       t.if_a2,
       t.if_a3
        FROM AMLCONFIG.T_EXPOSED_PEOPLE_DOWJONES_his@fxqdb_247 T
       where t.active_status <> 'Inactive';
    commit;
  end if;*/

  --分步骤匹配 
  /*with tmp as
   (select i_sno            as sno,
           i_comp_name      as comp_name,
           i_cert_no        as cert_no,
           i_chair_man      as chair_man,
           i_chair_certtype as chair_certtype,
           i_chair_certno   as chair_certno
      from dual);
  
  commit;
  */
  --thjs.tb_fxq_cust_rz_rst;--IF_A【风险名单分类：A1-黑名单 A2-特定自然人及其特定关系人 A3-高风险国家或者地区】
  --thjs.fxq_dowjones_his /thjs.fxq_dowjones_tmp
  with temp as
   (SELECT distinct if_a1, if_a2, if_a3
      FROM ( /*SELECT '' if_a1, '' if_a2, '' if_a3
                                                                                                  FROM dual
                                                                                                union all*/
            --机构客户名称匹配
            select b.if_a1, b.if_a2, b.if_a3
              from thjs.fxq_dowjones_his b
             WHERE (b.fms_name = i_comp_name or b.mfs_name = i_comp_name or
                   b.sfm_name = i_comp_name or b.smf_name = i_comp_name or
                   b.entityname = i_comp_name or
                   b.fms_name = upper(i_comp_name) or
                   b.mfs_name = upper(i_comp_name) or
                   b.sfm_name = upper(i_comp_name) or
                   b.smf_name = upper(i_comp_name) or
                   b.entityname = upper(i_comp_name))
               and b.type = 'entity'
            union all
            --机构客户证件号码匹配
            select b.if_a1, b.if_a2, b.if_a3
              from thjs.fxq_dowjones_his b
             WHERE b.idnumber = i_cert_no
               and b.type = 'entity'
            /*--法定代表人姓名匹配  因仅根据姓名匹配肯定会有同名问题，但取不到国籍信息和客户出生日期，故该匹配暂时去掉
            union all
            select b.if_a1, b.if_a2, b.if_a3
              from thjs.fxq_dowjones_his b
             WHERE (b.fms_name = i_chair_man or b.mfs_name = i_chair_man or
                   b.sfm_name = i_chair_man or b.smf_name = i_chair_man or
                   b.entityname = i_chair_man or
                   b.fms_name = upper(i_chair_man) or
                   b.mfs_name = upper(i_chair_man) or
                   b.sfm_name = upper(i_chair_man) or
                   b.smf_name = upper(i_chair_man) or
                   b.entityname = upper(i_chair_man))
               and b.birth_day = ?
               and (b.adderss_countrycode = ? or b.country_code = ?)
               and b.type = 'person'*/
            /*union all
            --个人客户证件类型匹配 反洗钱端未提供客户证件类型匹配逻辑，此段匹配可能存在问题，暂时注释
            SELECT b.if_a1, b.if_a2, b.if_a3
              from thjs.fxq_dowjones_his b
             where b.idnumber_type = i_chair_certtype
               and b.type = 'person'*/
            union all
            --个人客户证件匹配
            SELECT b.if_a1, b.if_a2, b.if_a3
              from thjs.fxq_dowjones_his b
             where b.idnumber = i_chair_certno
               and b.type = 'person') t)
  SELECT LISTAGG(if_a1, ',') WITHIN GROUP(ORDER BY NULL) AS if_a1,
         LISTAGG(if_a2, ',') WITHIN GROUP(ORDER BY NULL) AS if_a2,
         LISTAGG(if_a3, ',') WITHIN GROUP(ORDER BY NULL) AS if_a3
    into v_if_a1, v_if_a2, v_if_a3
    FROM temp;

  open RT_CURSOR for
    SELECT case
             when instr(v_if_a1, '1') > 0 and instr(v_if_a2, '1') > 0 and
                  instr(v_if_a3, '1') > 0 then
              'A1,A2,A3'
             when instr(v_if_a1, '1') > 0 and instr(v_if_a2, '1') > 0 then
              'A1,A2'
             when instr(v_if_a1, '1') > 0 and instr(v_if_a3, '1') > 0 then
              'A1,A3'
             when instr(v_if_a2, '1') > 0 and instr(v_if_a3, '1') > 0 then
              'A2,A3'
             when instr(v_if_a1, '1') > 0 then
              'A1'
             when instr(v_if_a2, '1') > 0 then
              'A2'
             when instr(v_if_a3, '1') > 0 then
              'A3'
             else
              ''
           end if_a_val,
           i_sno as sno
      FROM dual;

  o_return_msg  := '执行成功';
  o_return_code := 0;

exception
  -- 非预定义异常处理
  when v_userexp then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    hgman.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
    -- 预定义异常处理
  when others then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    hgman.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
end;

Create or Replace procedure "THJS"."P_FXQ_CUST_RZ_BILL_Q" (rt_cursor     out sys_refcursor, --返回游标结果集
                                                      i_cust_id     in varchar2, --客户id
                                                      i_qry_flag    in varchar2, --查询标识：0-草稿 1-提交 v101+
                                                      i_user_code   in varchar2, --查询人员
                                                      o_return_msg  out varchar2,
                                                      o_return_code out integer) is
  ----------------------------------------------------------------------------------
  --版    权：GTJA
  --版    本：1.0.0
  --开发人员：YLT@GTJA
  --创建日期：20200420
  --模块编号：
  --模块名称：投行反洗钱 - 客户基本信息（融资端）存托客户信息查询
  --功能名称：
  ----------------------------------------------------------------------------------
  --==============================================================================
  --固定变量
  v_userexp exception; -- 用户定义错
  v_tradedate    varchar2(8); -- 任务执行时间(业务日期)
  v_exec_func_id integer default '0'; -- 任务id
  v_func_own     varchar2(20) default 'thjs'; -- 任务归属用户（schema）
  v_func_name    varchar2(2000) default 'p_fxq_cust_rz_bill_q'; -- 任务名称(存储过程的名字)
  v_sqlerrm      varchar2(4000); -- 错误提示信息
  v_sqlcode      number; -- 错误代码
  v_sqlerrl      varchar2(4000); -- 错误行号
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  --=============================================================
  -- 业务处理过程
  --=============================================================

begin

  v_tradedate := to_char(sysdate, 'yyyyMMdd');

  --风险名单筛查结果 列数据暂定只有填报人可以查看

  --如果是查草稿数据
  if i_qry_flag = '0' then
    open rt_cursor for
      select r.cust_id, --客户id
             s.sno, --序号
             s.comp_name, --公司名称
             s.cert_no, --统一社会信用代码
             s.chair_man, --法定代表人姓名
             s.chair_certtype, --法定代表人证件类型
             s.chair_certno, --法定代表人证件号码
             case
               when s.create_user = i_user_code then
                s.rst_desc
               else
                ''
             end as rst_desc --风险名单筛查结果
        from thjs.tb_fxq_cust_rz_draft r
       inner join thjs.tb_fxq_cust_rz_bill_draft s
          on s.cust_id = r.cust_id
       where r.cust_id = i_cust_id
       order by s.sno;
    --如果是查正式数据
  elsif i_qry_flag = '1' then
    open rt_cursor for
      select r.cust_id, --客户id
             s.sno,
             s.comp_name,
             s.cert_no,
             s.chair_man,
             s.chair_certtype,
             s.chair_certno,
             case
               when s.create_user = i_user_code then
                s.rst_desc
               else
                ''
             end as rst_desc --风险名单筛查结果
        from thjs.tb_fxq_cust_rz r
       inner join thjs.tb_fxq_cust_rz_bill s
          on s.cust_id = r.cust_id
       where r.cust_id = i_cust_id
       order by s.sno;
  else
    --万一前端没有传入i_qry_flag标识，查询返回空
    open rt_cursor for
      select '' cust_id, --客户id
             '' as sno,
             '' as comp_name,
             '' as cert_no,
             '' as chair_man,
             '' as chair_certtype,
             '' as chair_certno,
             '' as rst_desc
        from dual;
  end if;
  commit;

  o_return_msg  := '执行成功';
  o_return_code := 0;

exception
  -- 非预定义异常处理
  when v_userexp then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    hgman.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
    -- 预定义异常处理
  when others then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    hgman.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
end;

Create or Replace procedure "THJS"."P_FXQ_CUST_RZ_BILL_S" (i_cust_id        in varchar2, --客户id
                                                      i_sno            in varchar2, --序号
                                                      i_comp_name      in varchar2, --公司名称
                                                      i_cert_no        in varchar2, --统一社会信用代码
                                                      i_chair_man      in varchar2, --法定代表人姓名
                                                      i_chair_certtype in varchar2, --法定代表人证件类型
                                                      i_chair_certno   in varchar2, --法定代表人证件号码
                                                      i_rst_desc       in varchar2, --风险名单筛查结果                                                          
                                                      i_submit_flag    in varchar2, --提交标识：0-草稿 1-提交
                                                      i_user_code      in varchar2, --操作人员                                               
                                                      o_return_msg     out varchar2,
                                                      o_return_code    out integer) is
  ----------------------------------------------------------------------------------
  --版    权：GTJA
  --版    本：1.0.0
  --开发人员：YLT@GTJA
  --创建日期：20200420
  --模块编号：
  --模块名称：投行反洗钱 - 客户基本信息（融资端）存托客户信息填报增删改
  --功能名称：
  ----------------------------------------------------------------------------------
  --==============================================================================
  --固定变量
  v_userexp exception; -- 用户定义错
  v_tradedate    varchar2(8); -- 任务执行时间(业务日期)
  v_exec_func_id integer default '0'; -- 任务id
  v_func_own     varchar2(20) default 'thjs'; -- 任务归属用户（schema）
  v_func_name    varchar2(2000) default 'p_fxq_cust_rz_bill_s'; -- 任务名称(存储过程的名字)
  v_sqlerrm      varchar2(4000); -- 错误提示信息
  v_sqlcode      number; -- 错误代码
  v_sqlerrl      varchar2(4000); -- 错误行号
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  --=============================================================
  -- 业务处理过程
  --=============================================================

begin

  v_tradedate := to_char(sysdate, 'yyyyMMdd');

  insert into thjs.tb_test
    (id, text)
  values
    (i_cust_id,
     'cust_id:' || i_cust_id || '-' || 'sno:' || i_sno || '-' ||
     'comp_name:' || i_comp_name || '-' || 'cert_no:' || i_cert_no || '-' ||
     'chair_man:' || i_chair_man || '-' || 'chair_certtype:' ||
     i_chair_certtype || '-' || 'chair_certno:' || i_chair_certno || '-' ||
     'rst_desc:' || i_rst_desc || '-' || 'i_submit_flag:' || i_submit_flag || '-' ||
     'user_code:' || i_user_code);
  commit;

  --如果是保存草稿操作
  if i_submit_flag = '0' then
    insert into thjs.tb_fxq_cust_rz_bill_draft
      (busi_date,
       cust_id,
       sno, --序号
       comp_name, --公司名称
       cert_no, --统一社会信用代码
       chair_man, --法定代表人姓名
       chair_certtype, --法定代表人证件类型
       chair_certno, --法定代表人证件号码
       rst_desc, --风险名单筛查结果
       create_user)
    values
      (v_tradedate,
       i_cust_id,
       i_sno,
       i_comp_name,
       i_cert_no,
       i_chair_man,
       i_chair_certtype,
       i_chair_certno,
       i_rst_desc,
       i_user_code);
  end if;
  --点击‘正式提交’操作时
  if i_submit_flag = '1' then
    insert into thjs.tb_fxq_cust_rz_bill
      (busi_date,
       cust_id,
       sno, --序号
       comp_name, --公司名称
       cert_no, --统一社会信用代码
       chair_man, --法定代表人姓名
       chair_certtype, --法定代表人证件类型
       chair_certno, --法定代表人证件号码
       rst_desc, --风险名单筛查结果
       create_user)
    values
      (v_tradedate,
       i_cust_id,
       i_sno,
       i_comp_name,
       i_cert_no,
       i_chair_man,
       i_chair_certtype,
       i_chair_certno,
       i_rst_desc,
       i_user_code);
    commit;
  
    thjs.p_fxq_cust_rsk_zhlc_s(i_cust_id     => i_cust_id,
                               i_name        => i_comp_name,
                               i_submit_flag => i_submit_flag,
                               i_category    => '存托客户,存托客户法人',
                               o_return_msg  => o_return_msg,
                               o_return_code => o_return_code);
  
  end if;

  o_return_msg  := '执行成功';
  o_return_code := 0;
  commit;

exception
  -- 非预定义异常处理
  when v_userexp then
    rollback;
  
    v_sqlerrm := 'cust_id:' || i_cust_id || ',name:' || i_comp_name || ',' ||
                 sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    hgman.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
    -- 预定义异常处理
  when others then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    hgman.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
end;

Create or Replace procedure "THJS"."P_FXQ_CUST_RZ_D" (i_cust_id     in integer, --客户id
                                                 i_opflag      in varchar2, --操作标识：0-恢复 1-删除
                                                 i_usercode    in varchar2, --操作人
                                                 o_return_msg  out varchar2,
                                                 o_return_code out integer) is
  ----------------------------------------------------------------------------------
  --版    权：GTJA
  --版    本：1.0.0
  --开发人员：CZC@GTJA
  --创建日期：20190718
  --模块编号：
  --模块名称：投行反洗钱 - 客户基本信息（融资端+自然人）填报删除及恢复
  --功能名称：
  ----------------------------------------------------------------------------------
  --v101 2020/10/29 YLT@GTJA 将原先‘删除’状态的客户调整为‘失效’状态

  --==============================================================================
  --固定变量
  v_userexp exception; -- 用户定义错
  v_tradedate    varchar2(8); -- 任务执行时间(业务日期)
  v_exec_func_id integer default '0'; -- 任务id
  v_func_own     varchar2(20) default 'thjs'; -- 任务归属用户（schema）
  v_func_name    varchar2(2000) default 'p_fxq_cust_rz_d'; -- 任务名称(存储过程的名字)
  v_sqlerrm      varchar2(4000); -- 错误提示信息
  v_sqlcode      number; -- 错误代码
  v_sqlerrl      varchar2(4000); -- 错误行号
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  v_count       integer default 0;
  v_zr_count    integer default 0; --v101+
  v_tz_count    integer default 0;
  v_tz_zr_count integer default 0;
  --=============================================================
  -- 业务处理过程
  --=============================================================

begin

  v_tradedate := to_char(sysdate, 'yyyyMMdd');

  --v101+ start
  insert into thjs.tb_exec_log
    (log_id, proc_name, proc_param, exec_time)
  values
    (thjs.tb_exec_log_id_seq.nextval,
     'p_fxq_cust_rz_d',
     'i_cust_id:' || i_cust_id || ' -' || 'i_opflag:' || i_opflag || ' -' ||
     'i_usercode:' || i_usercode,
     sysdate);
  commit;
  --v101+ end

  --检查是否保存过此客户（机构）
  select count(1)
    into v_count
    from thjs.tb_fxq_cust_rz r
   where r.cust_id = i_cust_id;

  --v101+ start
  ----检查是否保存过此客户（自然人）
  select count(1)
    into v_zr_count
    from thjs.tb_fxq_cust_zr r
   where r.cust_id = i_cust_id;
  --v101+ end

  --检查是否保存过此客户（机构）-投资端
  select count(1)
    into v_tz_count
    from thjs.tb_fxq_cust_tz r
   where r.cust_id = i_cust_id;

  --v101+ start
  ----检查是否保存过此客户（自然人）-投资端
  select count(1)
    into v_tz_zr_count
    from thjs.tb_fxq_cust_tz_zr r
   where r.cust_id = i_cust_id;
  --v101+ end

  --if v_count = 0 then--v101-
  if v_count = 0 and v_zr_count = 0 and v_tz_count = 0 and
     v_tz_zr_count = 0 then
    --v101+
    o_return_msg  := '未找到此客户，请重新查询！';
    o_return_code := -1;
    return;
    --else--v101-
  elsif v_count > 0 then
    --机构 保存过此客户信息 --v101+
    --更新状态
    update thjs.tb_fxq_cust_rz r
       set r.status = i_opflag, r.update_time = sysdate
     where r.cust_id = i_cust_id
       and not exists
     (select 1
              from thjs.tb_fxq_cust_limit l
             where l.cust_id = r.cust_id
               and v_tradedate between l.begin_date and l.end_date); --状态限制表中客户不作更新
  
    --插入流水表
    insert into thjs.tb_fxq_cust_active_log
      (busi_date, cust_type, cust_id, cust_name, status, op_user)
      select v_tradedate,
             2 as cust_type,
             r.cust_id,
             r.cust_name,
             i_opflag,
             i_usercode
        from thjs.tb_fxq_cust_rz r
       where r.cust_id = i_cust_id;
    commit;
  
    --v101+ start
  elsif v_zr_count > 0 then
    --自然人 保存过此客户信息
    --更新状态
    update thjs.tb_fxq_cust_zr r
       set r.status = i_opflag, r.update_time = sysdate
     where r.cust_id = i_cust_id
       and not exists
     (select 1
              from thjs.tb_fxq_cust_limit l
             where l.cust_id = r.cust_id
               and v_tradedate between l.begin_date and l.end_date); --状态限制表中客户不作更新
    --v101+ end
  
    --插入流水表
    insert into thjs.tb_fxq_cust_active_log
      (busi_date, cust_type, cust_id, cust_name, status, op_user)
      select v_tradedate,
             1 as cust_type,
             r.cust_id,
             r.cust_name,
             i_opflag,
             i_usercode
        from thjs.tb_fxq_cust_zr r
       where r.cust_id = i_cust_id;
    commit;
  elsif v_tz_count > 0 then
    --机构 保存过此客户信息 --v101+
    --更新状态
    update thjs.tb_fxq_cust_tz r
       set r.status = i_opflag, r.update_time = sysdate
     where r.cust_id = i_cust_id
       and not exists
     (select 1
              from thjs.tb_fxq_cust_limit l
             where l.cust_id = r.cust_id
               and v_tradedate between l.begin_date and l.end_date); --状态限制表中客户不作更新
  
    --插入流水表
    insert into thjs.tb_fxq_cust_active_log
      (busi_date, cust_type, cust_id, cust_name, status, op_user)
      select v_tradedate,
             2 as cust_type,
             r.cust_id,
             r.cust_name,
             i_opflag,
             i_usercode
        from thjs.tb_fxq_cust_tz r
       where r.cust_id = i_cust_id;
    commit;
  
    --v101+ start
  elsif v_tz_zr_count > 0 then
    --自然人 保存过此客户信息
    --更新状态
    update thjs.tb_fxq_cust_tz_zr r
       set r.status = i_opflag, r.update_time = sysdate
     where r.cust_id = i_cust_id
       and not exists
     (select 1
              from thjs.tb_fxq_cust_limit l
             where l.cust_id = r.cust_id
               and v_tradedate between l.begin_date and l.end_date); --状态限制表中客户不作更新
    --v101+ end
  
    --插入流水表
    insert into thjs.tb_fxq_cust_active_log
      (busi_date, cust_type, cust_id, cust_name, status, op_user)
      select v_tradedate,
             1 as cust_type,
             r.cust_id,
             r.cust_name,
             i_opflag,
             i_usercode
        from thjs.tb_fxq_cust_tz_zr r
       where r.cust_id = i_cust_id;
    commit;
  end if;

  commit;

  o_return_msg  := '执行成功';
  o_return_code := 0;

exception
  -- 非预定义异常处理
  when v_userexp then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    hgman.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
    -- 预定义异常处理
  when others then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    hgman.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
end;

Create or Replace procedure "THJS"."P_FXQ_CUST_RZ_D_TOHIS" (i_cust_id     in integer, --客户id
                                                       i_usercode    in varchar2, --操作人
                                                       o_return_msg  out varchar2,
                                                       o_return_code out integer) is
  ----------------------------------------------------------------------------------
  --版    权：GTJA
  --版    本：1.0.0
  --开发人员：CZC@GTJA
  --创建日期：20220928
  --模块编号：
  --模块名称：投行反洗钱 - 客户记录删除，留存历史
  --功能名称：
  ----------------------------------------------------------------------------------
  --==============================================================================
  --固定变量
  v_userexp exception; -- 用户定义错
  v_tradedate    varchar2(8); -- 任务执行时间(业务日期)
  v_exec_func_id integer default '0'; -- 任务id
  v_func_own     varchar2(20) default 'thjs'; -- 任务归属用户（schema）
  v_func_name    varchar2(2000) default 'p_fxq_cust_rz_d_tohis'; -- 任务名称(存储过程的名字)
  v_sqlerrm      varchar2(4000); -- 错误提示信息
  v_sqlcode      number; -- 错误代码
  v_sqlerrl      varchar2(4000); -- 错误行号
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  v_his_id varchar2(100);
  --=============================================================
  -- 业务处理过程
  --=============================================================

begin

  v_tradedate := to_char(sysdate, 'yyyyMMdd');

  select sys_guid() into v_his_id from dual;

  --如果正式表中有该客户信息，将正式表数据存至历史表中
  insert into thjs.tb_fxq_cust_rz_his
    (busi_date,
     cust_biz,
     cust_id,
     cust_name,
     office_adr,
     industry_id,
     industry_name,
     busi_scope,
     reg_capital,
     reg_currency,
     telphone, --v105+
     fund_date, --v106+
     cert_type,
     cert_no,
     cert_startdate,
     cert_enddate,
     chair_man,
     chair_birth,
     chair_certtype,
     chair_certno,
     chair_certstart,
     chair_certend,
     write_date,
     update_user,
     update_time,
     create_user,
     create_time,
     work_type,
     associatied_date,
     remark,
     his_id,
     his_user,
     is_depository_cus, --v102+
     source_flag, --v103
     status --v104+
     )
    SELECT busi_date,
           cust_biz,
           cust_id,
           cust_name,
           office_adr,
           industry_id,
           industry_name,
           busi_scope,
           reg_capital,
           reg_currency,
           r.telphone, --v105+
           r.fund_date, --v106+
           cert_type,
           cert_no,
           cert_startdate,
           cert_enddate,
           chair_man,
           chair_birth,
           chair_certtype,
           chair_certno,
           chair_certstart,
           chair_certend,
           write_date,
           update_user,
           update_time,
           create_user,
           create_time,
           r.work_type,
           associatied_date,
           remark,
           v_his_id,
           i_usercode,
           is_depository_cus, --v102+
           source_flag, --v103
           r.status --v104+
      FROM thjs.tb_fxq_cust_rz r
     where r.cust_id = i_cust_id;

  --将[控股股东、实际控制人、授权代表人、受益所有人]的正式表数据也存一份到历史表中
  --控股股东
  insert into thjs.tb_fxq_cust_shareholder_his
    SELECT t.*, v_his_id, sysdate
      FROM thjs.tb_fxq_cust_shareholder t
     WHERE cust_id = i_cust_id;
  --实际控制人
  insert into thjs.tb_fxq_cust_controller_his
    SELECT t.*, v_his_id, sysdate
      FROM thjs.tb_fxq_cust_controller t
     WHERE cust_id = i_cust_id;
  --授权代表人
  insert into thjs.tb_fxq_cust_authorizer_his
    SELECT t.*, v_his_id, sysdate
      FROM thjs.tb_fxq_cust_authorizer t
     WHERE cust_id = i_cust_id;
  --受益所有人
  insert into thjs.tb_fxq_cust_beneficiary_his
    SELECT t.*, v_his_id, sysdate
      FROM thjs.tb_fxq_cust_beneficiary t
     WHERE cust_id = i_cust_id;
  --存托客户
  insert into thjs.tb_fxq_cust_rz_bill_his
    SELECT t.*, v_his_id, sysdate
      FROM thjs.tb_fxq_cust_rz_bill t
     WHERE cust_id = i_cust_id;
  commit;

  delete from thjs.tb_fxq_cust_rz t where t.cust_id = i_cust_id;
  delete from thjs.tb_fxq_cust_shareholder t where t.cust_id = i_cust_id; --控股股东
  delete from thjs.tb_fxq_cust_controller t where t.cust_id = i_cust_id; --实际控制人
  delete from thjs.tb_fxq_cust_authorizer t where t.cust_id = i_cust_id; --授权代表人
  delete from thjs.tb_fxq_cust_beneficiary t where t.cust_id = i_cust_id; --受益所有人
  delete from thjs.tb_fxq_cust_rz_bill t where t.cust_id = i_cust_id; --票据存托客户
  commit;

  --草稿数据
  delete from thjs.tb_fxq_cust_rz_draft t where t.cust_id = i_cust_id;
  delete from thjs.tb_fxq_cust_shareholder_draft t
   where t.cust_id = i_cust_id; --控股股东
  delete from thjs.tb_fxq_cust_controller_draft t
   where t.cust_id = i_cust_id; --实际控制人
  delete from thjs.tb_fxq_cust_authorizer_draft t
   where t.cust_id = i_cust_id; --授权代表人
  delete from thjs.tb_fxq_cust_beneficiary_draft t
   where t.cust_id = i_cust_id; --受益所有人
  delete from thjs.tb_fxq_cust_rz_bill_draft t where t.cust_id = i_cust_id; --票据存托客户
  commit;

  --自然人===============================================================================================
  --如果正式表中有该客户信息，将正式表数据存至历史表中
  insert into thjs.tb_fxq_cust_zr_his
    (busi_date,
     cust_biz,
     cust_sno,
     cust_id,
     cust_name,
     sex,
     country,
     birth_date,
     cert_type,
     cert_no,
     cert_startdate,
     cert_enddate,
     cert_address,
     --v102+ start
     province,
     city,
     district,
     --v102+ end
     address,
     phone,
     zip_code,
     vocation,
     vocation_name, --v101+
     post,
     work_unit,
     income,
     write_date,
     status,
     update_user,
     update_time,
     create_user,
     create_time,
     work_type,
     associatied_date,
     remark,
     his_id,
     source_flag)
    SELECT r.busi_date,
           r.cust_biz,
           r.cust_sno,
           r.cust_id,
           r.cust_name,
           r.sex,
           r.country,
           r.birth_date,
           r.cert_type,
           r.cert_no,
           r.cert_startdate,
           r.cert_enddate,
           r.cert_address,
           --v102+ start
           r.province,
           r.city,
           r.district,
           --v102+ end
           r.address,
           r.phone,
           r.zip_code,
           r.vocation,
           r.vocation_name, --v101+
           r.post,
           r.work_unit,
           r.income,
           r.write_date,
           r.status,
           r.update_user,
           r.update_time,
           r.create_user,
           r.create_time,
           r.work_type,
           r.associatied_date,
           r.remark,
           v_his_id,
           r.source_flag
      FROM thjs.tb_fxq_cust_zr r
     where r.cust_id = i_cust_id;
  commit;

  delete from thjs.tb_fxq_cust_zr t where t.cust_id = i_cust_id; --客户基本信息（自然人)
  delete from thjs.tb_fxq_cust_zr_draft t where t.cust_id = i_cust_id; --客户基本信息（自然人)

  commit;

  o_return_msg  := '执行成功';
  o_return_code := 0;

exception
  -- 非预定义异常处理
  when v_userexp then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    hgman.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
    -- 预定义异常处理
  when others then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    hgman.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
end;

Create or Replace procedure "THJS"."P_FXQ_CUST_RZ_FILES_Q" (rt_cursor     out sys_refcursor, --返回游标结果集
                                                       i_cust_id     in integer, --客户id
                                                       i_usercode    in varchar2, --查询人
                                                       o_return_msg  out varchar2,
                                                       o_return_code out integer) is
  ----------------------------------------------------------------------------------
  --版    权：GTJA
  --版    本：1.0.0
  --开发人员：YLT@GTJA
  --创建日期：20200805
  --模块编号：
  --模块名称：投行反洗钱 - 机构客户底稿信息查询
  --功能名称：
  ----------------------------------------------------------------------------------

  --==============================================================================
  --固定变量
  v_userexp exception; -- 用户定义错
  v_tradedate    varchar2(8); -- 任务执行时间(业务日期)
  v_exec_func_id integer default '0'; -- 任务id
  v_func_own     varchar2(20) default 'thjs'; -- 任务归属用户（schema）
  v_func_name    varchar2(2000) default 'p_fxq_cust_rz_files_q'; -- 任务名称(存储过程的名字)
  v_sqlerrm      varchar2(4000); -- 错误提示信息
  v_sqlcode      number; -- 错误代码
  v_sqlerrl      varchar2(4000); -- 错误行号
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  v_count integer default 0;
  --=============================================================
  -- 业务处理过程
  --=============================================================

begin

  v_tradedate := to_char(sysdate, 'yyyyMMdd');

  insert into thjs.tb_exec_log
    (log_id, proc_name, proc_param, exec_time)
  values
    (thjs.tb_exec_log_id_seq.nextval,
     'p_fxq_cust_rz_files_q',
     'i_cust_id:' || i_cust_id || ' -' || 'i_usercode:' || i_usercode,
     sysdate);
  commit;

  select count(1)
    into v_count
    from thjs.tb_fxq_cust_rz_files r
   where r.cust_id = i_cust_id;

  open rt_cursor for
    select *
      from (select ROW_NUMBER() OVER(PARTITION BY r.file_type, r.file_name, r.file_path ORDER BY r.update_time DESC) AS RN,
                   r.cust_id,
                   trim(r.file_type) file_type,
                   r.file_name,
                   r.file_path,
                   r.upload_user,
                   r.upload_time,
                   r.update_user,
                   r.update_time
              from thjs.tb_fxq_cust_rz_files r
             where r.cust_id = i_cust_id
             and r.status='0') r
     where rn = 1
     order by r.upload_time;

  commit;

  o_return_msg  := '执行成功';
  o_return_code := 0;

exception
  -- 非预定义异常处理
  when v_userexp then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    hgman.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
    -- 预定义异常处理
  when others then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    hgman.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
end;

Create or Replace procedure "THJS"."P_FXQ_CUST_RZ_FILES_S" (i_cust_id     in integer, --客户id
                                                       i_usercode    in varchar2, --操作人
                                                       i_file_type   in varchar2, --类型
                                                       i_file_name   in varchar2, --名称
                                                       i_file_path   in varchar2, --文件路径
                                                       i_create_user in varchar2, --上传人员
                                                       o_return_msg  out varchar2,
                                                       o_return_code out integer) is
  ----------------------------------------------------------------------------------
  --版    权：GTJA
  --版    本：1.0.0
  --开发人员：YLT@GTJA
  --创建日期：20200804
  --模块编号：
  --模块名称：投行反洗钱 - 机构客户底稿信息保存
  --功能名称：
  ----------------------------------------------------------------------------------

  --==============================================================================
  --固定变量
  v_userexp exception; -- 用户定义错
  v_tradedate    varchar2(8); -- 任务执行时间(业务日期)
  v_exec_func_id integer default '0'; -- 任务id
  v_func_own     varchar2(20) default 'thjs'; -- 任务归属用户（schema）
  v_func_name    varchar2(2000) default 'p_fxq_cust_rz_files_s'; -- 任务名称(存储过程的名字)
  v_sqlerrm      varchar2(4000); -- 错误提示信息
  v_sqlcode      number; -- 错误代码
  v_sqlerrl      varchar2(4000); -- 错误行号
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  --v_cust_id varchar2(100);
  --=============================================================
  -- 业务处理过程
  --=============================================================

begin

  v_tradedate := to_char(sysdate, 'yyyyMMdd');

  insert into thjs.tb_exec_log
    (log_id, proc_name, proc_param, exec_time)
  values
    (thjs.tb_exec_log_id_seq.nextval,
     'p_fxq_cust_rz_files_s',
     'cust_id:' || i_cust_id || ',file_type:' || i_file_type ||
     ',file_name:' || i_file_name || ',file_path:' || i_file_path ||
     ',create_user:' || i_create_user || ',usercode:' || i_usercode,
     sysdate);
  commit;

  /*insert into thjs.tb_test
    (id, text)
  values
    (20200804,
     'i_cust_id:[' || i_cust_id || ']i_file_type:[' || i_file_type ||
     ']i_file_name:[' || i_file_name || ']' || 'i_file_path:[' ||
     i_file_path || ']' || 'i_file_path:[' || i_file_path || ']' ||
     'i_create_user:[' || i_create_user || ']');
  commit;*/

  insert into thjs.tb_fxq_cust_rz_files
    (cust_id,
     file_type,
     file_name,
     file_path,
     upload_user,
     upload_time,
     update_user,
     update_time)
  values
    (i_cust_id,
     i_file_type,
     i_file_name,
     i_file_path,
     i_create_user,
     sysdate,
     i_create_user,
     sysdate);
  commit;

  o_return_msg  := '执行成功';
  o_return_code := 0;

exception
  -- 非预定义异常处理
  when v_userexp then
    rollback;
  
    v_sqlerrm := 'cust_id:' || i_cust_id || ',name:' || i_file_name || ',' ||
                 sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    hgman.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
    -- 预定义异常处理
  when others then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    hgman.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
