Create or Replace procedure "THJS"."P_FXQ_CUST_RZ_TEST_D" (i_cust_id     in integer, --客户id
                                                      i_usercode    in varchar2, --操作人
                                                      o_return_msg  out varchar2,
                                                      o_return_code out integer) is
  ----------------------------------------------------------------------------------
  --版    权：GTJA
  --版    本：1.0.0
  --开发人员：CZC@GTJA
  --创建日期：20190718
  --模块编号：
  --模块名称：投行反洗钱 - 客户基本信息（融资端）填报测试用户记录删除
  --功能名称：
  ----------------------------------------------------------------------------------
  --==============================================================================
  --固定变量
  v_userexp exception; -- 用户定义错
  v_tradedate    varchar2(8); -- 任务执行时间(业务日期)
  v_exec_func_id integer default '0'; -- 任务id
  v_func_own     varchar2(20) default 'thjs'; -- 任务归属用户（schema）
  v_func_name    varchar2(2000) default 'p_fxq_cust_rz_test_d'; -- 任务名称(存储过程的名字)
  v_sqlerrm      varchar2(4000); -- 错误提示信息
  v_sqlcode      number; -- 错误代码
  v_sqlerrl      varchar2(4000); -- 错误行号
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  v_count integer default 0;
  --=============================================================
  -- 业务处理过程
  --=============================================================

begin

  v_tradedate := to_char(sysdate, 'yyyyMMdd');

  delete from thjs.tb_fxq_cust_rz t
   where t.cust_id = i_cust_id
     and t.cust_biz = '测试'; --客户基本信息（融资端)
  delete from thjs.tb_fxq_cust_shareholder t where t.cust_id = i_cust_id; --控股股东
  delete from thjs.tb_fxq_cust_controller t where t.cust_id = i_cust_id; --实际控制人
  delete from thjs.tb_fxq_cust_authorizer t where t.cust_id = i_cust_id; --授权代表人
  delete from thjs.tb_fxq_cust_beneficiary t where t.cust_id = i_cust_id; --受益所有人
  delete from thjs.tb_fxq_cust_rz_bill t where t.cust_id = i_cust_id; --票据存托客户

  --历史提交数据
  delete from thjs.tb_fxq_cust_rz_his t
   where t.cust_id = i_cust_id
     and t.cust_biz = '测试'; --客户基本信息（融资端)
  delete from thjs.tb_fxq_cust_shareholder_his t
   where t.cust_id = i_cust_id; --控股股东
  delete from thjs.tb_fxq_cust_controller_his t
   where t.cust_id = i_cust_id; --实际控制人
  delete from thjs.tb_fxq_cust_authorizer_his t
   where t.cust_id = i_cust_id; --授权代表人
  delete from thjs.tb_fxq_cust_beneficiary_his t
   where t.cust_id = i_cust_id; --受益所有人
  delete from thjs.tb_fxq_cust_rz_bill_his t where t.cust_id = i_cust_id; --票据存托客户

  --草稿数据
  delete from thjs.tb_fxq_cust_rz_draft t
   where t.cust_id = i_cust_id
     and t.cust_biz = '测试'; --客户基本信息（融资端)
  delete from thjs.tb_fxq_cust_shareholder_draft t
   where t.cust_id = i_cust_id; --控股股东
  delete from thjs.tb_fxq_cust_controller_draft t
   where t.cust_id = i_cust_id; --实际控制人
  delete from thjs.tb_fxq_cust_authorizer_draft t
   where t.cust_id = i_cust_id; --授权代表人
  delete from thjs.tb_fxq_cust_beneficiary_draft t
   where t.cust_id = i_cust_id; --受益所有人
  delete from thjs.tb_fxq_cust_rz_bill_draft t where t.cust_id = i_cust_id; --票据存托客户

  delete from thjs.tb_fxq_cust_zr t
   where t.cust_id = i_cust_id
     and t.cust_biz = '测试'; --客户基本信息（自然人)
  delete from thjs.tb_fxq_cust_zr_his t
   where t.cust_id = i_cust_id
     and t.cust_biz = '测试'; --客户基本信息（自然人)
  delete from thjs.tb_fxq_cust_zr_draft t
   where t.cust_id = i_cust_id
     and t.cust_biz = '测试'; --客户基本信息（自然人)

  commit;

  o_return_msg  := '执行成功';
  o_return_code := 0;

exception
  -- 非预定义异常处理
  when v_userexp then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    hgman.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
    -- 预定义异常处理
  when others then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    hgman.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
