       'admin',
       sysdate);
    commit;
    --修改标签
  elsif v_count > 0 then
    update thjs.tb_fxq_cust_zr_files t
       set t.file_type = i_file_type
     where t.cust_id = i_cust_id
       and t.file_name = i_file_name;
