Create or Replace procedure "THJS"."P_FXQ_CUST_ZR_FKD_Q" (rt_cursor     out sys_refcursor, --返回游标结果集
                                                     i_cust_id     in integer, --客户id
                                                     i_usercode    in varchar2, --查询人
                                                     o_return_msg  out varchar2,
                                                     o_return_code out integer) is
  ----------------------------------------------------------------------------------
  --版    权：GTJA
  --版    本：1.0.0
  --开发人员：YLT@GTJA
  --创建日期：20210303
  --模块编号：
  --模块名称：投行反洗钱 - 客户基本信息（自然人）-反馈结果描述查询
  --功能名称：
  ----------------------------------------------------------------------------------
  --==============================================================================
  --固定变量
  v_userexp exception; -- 用户定义错
  v_tradedate    varchar2(8); -- 任务执行时间(业务日期)
  v_exec_func_id integer default '0'; -- 任务id
  v_func_own     varchar2(20) default 'thjs'; -- 任务归属用户（schema）
  v_func_name    varchar2(2000) default 'p_fxq_cust_zr_fkd_q'; -- 任务名称(存储过程的名字)
  v_sqlerrm      varchar2(4000); -- 错误提示信息
  v_sqlcode      number; -- 错误代码
  v_sqlerrl      varchar2(4000); -- 错误行号
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量

  --=============================================================
  -- 业务处理过程
  --=============================================================

begin

  v_tradedate := to_char(sysdate, 'yyyyMMdd');

  insert into thjs.tb_exec_log
    (log_id, proc_name, proc_param, exec_time)
  values
    (thjs.tb_exec_log_id_seq.nextval,
     'p_fxq_cust_zr_fkd_q',
     'i_cust_id:' || i_cust_id || '-i_usercode:' || i_usercode,
     sysdate);
  commit;

  open rt_cursor for
    select r.cust_id,
           r.cust_name,
           case
             when rst.if_a is null then
              '0'
             else
              '1'
           end as screen_code, --风险名单筛查 0/1
           case
             when rst.if_a is null then
              '不涉及'
             else
              '涉及'
           end as screen_name, --风险名单筛查描述 不涉及/涉及
           case
             when rst.if_a is null then
              ''
             else
              decode(rst.if_a,
                     'A1',
                     '黑名单',
                     'A2',
                     '特定自然人及其特定关系人',
                     'A3',
                     '高风险国家或者地区',
                     'A4',
                     '其他国际制裁名单',
                     'A5',
                     '国内政要',
                     'A6',
                     '其他',
                     '')
           end as screen_desc
      from thjs.tb_fxq_cust_zr r
      left join (select t.sc_client_id,
                        regexp_substr(t.if_a, '[^,]+', 1, l) as if_a
                   from (select t.sc_client_id, t.if_a
                           from thjs.tb_fxq_cust_rz_rst t) t
                   left join (select level as l
                               from dual
                             connect by level <= 3)
                     on l <=
                        length(t.if_a) - length(replace(t.if_a, ',', '')) + 1) rst
        on rst.sc_client_id = r.cust_id
     where r.cust_id = i_cust_id;

  commit;

  o_return_msg  := '执行成功';
  o_return_code := 0;

exception
  -- 非预定义异常处理
  when v_userexp then
    rollback;

    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();

    hgman.p_write_error_log(i_tradedate    => v_tradedate,
                           i_exec_func_id => v_exec_func_id,
                           i_func_own     => v_func_own,
                           i_func_name    => v_func_name,
                           i_occur_time   => sysdate,
                           i_sqlerrm      => v_sqlerrm,
                           i_sqlcode      => v_sqlcode,
                           i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
    -- 预定义异常处理
  when others then
    rollback;

    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();

    hgman.p_write_error_log(i_tradedate    => v_tradedate,
                           i_exec_func_id => v_exec_func_id,
                           i_func_own     => v_func_own,
                           i_func_name    => v_func_name,
                           i_occur_time   => sysdate,
                           i_sqlerrm      => v_sqlerrm,
                           i_sqlcode      => v_sqlcode,
                           i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
end;

