  v_func_name    varchar2(2000) default 'p_fxq_cust_zr_fk_q'; -- 任务名称(存储过程的名字)
  v_sqlerrm      varchar2(4000); -- 错误提示信息
  v_sqlcode      number; -- 错误代码
  v_sqlerrl      varchar2(4000); -- 错误行号
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  --=============================================================
  -- 业务处理过程
  --=============================================================

begin

  v_tradedate := to_char(sysdate, 'yyyyMMdd');

  insert into thjs.tb_exec_log
    (log_id, proc_name, proc_param, exec_time)
  values
    (thjs.tb_exec_log_id_seq.nextval,
     'p_fxq_cust_zr_fk_q',
     'i_cust_id:' || i_cust_id || '-i_usercode:' || i_usercode,
     sysdate);
  commit;

  open rt_cursor for
    select r.cust_id,
           r.cust_name,
           case
             when rst.if_a is null then
              '0'
             else
              '1'
           end as screen_code, --风险名单筛查 0/1
           case
             when rst.if_a is null then
              '不涉及'
             else
              '涉及'
           end as screen_name, --风险名单筛查描述 不涉及/涉及
           rsk.grade_code, --风险等级 1/2/3/4/5
           rsk.grade_name --风险等级描述 低/较低/中/较高/高
      from thjs.tb_fxq_cust_zr r
      left join thjs.tb_fxq_cust_rz_rst rst
        on rst.sc_client_id = r.cust_id
      left join thjs.tb_fxq_cust_rz_rsk rsk
        on rsk.sc_client_id = r.cust_id
     where r.cust_id = i_cust_id;

  commit;

  o_return_msg  := '执行成功';
  o_return_code := 0;

exception
  -- 非预定义异常处理
  when v_userexp then
    rollback;

    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();

    hgman.p_write_error_log(i_tradedate    => v_tradedate,
                           i_exec_func_id => v_exec_func_id,
                           i_func_own     => v_func_own,
                           i_func_name    => v_func_name,
                           i_occur_time   => sysdate,
                           i_sqlerrm      => v_sqlerrm,
                           i_sqlcode      => v_sqlcode,
                           i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
    -- 预定义异常处理
  when others then
    rollback;

    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();

    hgman.p_write_error_log(i_tradedate    => v_tradedate,
                           i_exec_func_id => v_exec_func_id,
                           i_func_own     => v_func_own,
                           i_func_name    => v_func_name,
                           i_occur_time   => sysdate,
                           i_sqlerrm      => v_sqlerrm,
                           i_sqlcode      => v_sqlcode,
                           i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
end;

Create or Replace procedure "THJS"."P_FXQ_CUST_ZTGS" (o_return_msg  out varchar2,
                                                 o_return_code out integer) is
  ----------------------------------------------------------------------------------
  --版    权：GTJA
  --版    本：1.0.0
  --开发人员：CZC@GTJA
  --创建日期：20210420
  --模块编号：
  --模块名称：投行反洗钱 - 客户政通工商信息匹配
  --功能名称：
  ----------------------------------------------------------------------------------

  --==============================================================================
  --固定变量
  v_userexp exception; -- 用户定义错
  v_tradedate    varchar2(8); -- 任务执行时间(业务日期)
  v_exec_func_id integer default '0'; -- 任务id
  v_func_own     varchar2(20) default 'thjs'; -- 任务归属用户（schema）
  v_func_name    varchar2(2000) default 'p_fxq_cust_ztgs'; -- 任务名称(存储过程的名字)
  v_sqlerrm      varchar2(4000); -- 错误提示信息
  v_sqlcode      number; -- 错误代码
  v_sqlerrl      varchar2(4000); -- 错误行号
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  v_ztgs_pripid varchar2(200);
  v_index_count integer default 0;
  v_ztgs_count  integer default 0;
  --=============================================================
  -- 业务处理过程
  --=============================================================

begin

  v_tradedate := to_char(sysdate, 'yyyyMMdd');

  execute immediate 'truncate table thjs.tb_fxq_cust_ztgs';
  insert into thjs.tb_fxq_cust_ztgs
    (cust_id,
     cust_name,
     fund_date,
     cert_type,
     cert_no,
     cert_startdate,
     cert_enddate,
     chair_man,
     chair_certtype,
     chair_certno,
     chair_certstart,
     chair_certend)
    select r.cust_id,
           r.cust_name,
           r.fund_date,
           r.cert_type,
           r.cert_no,
           r.cert_startdate,
           r.cert_enddate,
           r.chair_man,
           r.chair_certtype,
           r.chair_certno,
           r.chair_certstart,
           r.chair_certend
      from thjs.tb_fxq_cust_rz r
      left join edw00.pty_main_info t
        on t.credit_code = r.cert_no
     where r.status = '0'
       and r.cust_biz <> '测试'
     order by r.cust_id;

  for cust_info in (select r.cust_id,
                           r.cust_name,
                           r.fund_date,
                           r.cert_no,
                           r.cert_startdate,
                           r.chair_man,
                           r.chair_certno,
                           r.chair_certstart
                      from thjs.tb_fxq_cust_rz r
                      left join edw00.pty_main_info t
                        on t.credit_code = r.cert_no
                     where r.status = '0'
                       and r.cust_biz <> '测试'
                     order by r.cust_id) loop
  
    v_ztgs_pripid := null;
  
    --检查是否有索引,无索引不进行查询，防止前端卡死超时          
    select count(1)
      into v_index_count
      from all_indexes i
     where i.OWNER = 'EDW00'
       and i.TABLE_NAME = 'PTY_MAIN_INFO'
       and i.INDEX_NAME = 'IDX_PTY_MAIN_INFO_CREDIT_CODE';
  
    if v_index_count > 0 then
    
      select count(1)
        into v_ztgs_count
        from edw00.pty_main_info e
       where e.credit_code = cust_info.cert_no;
    
      if v_ztgs_count = 1 then
        select e.prip_id
          into v_ztgs_pripid
          from edw00.pty_main_info e
         where e.credit_code = cust_info.cert_no;
      end if;
    
    end if;
  
    if v_ztgs_count = 0 then
      --传入的客户名称与统一社会信用代码进行二次匹配
      select count(1)
        into v_index_count
        from all_indexes i
       where i.OWNER = 'EDW00'
         and i.TABLE_NAME = 'PTY_MAIN_INFO'
         and i.INDEX_NAME = 'IDX_PTY_MAIN_INFO_COMP_NAME';
    
      if v_index_count > 0 then
      
        select count(1)
          into v_ztgs_count
          from edw00.pty_main_info e
         where e.comp_name = cust_info.cust_name; --能够精确匹配到
      
        if v_ztgs_count = 1 then
          select e.prip_id
            into v_ztgs_pripid
            from edw00.pty_main_info e
           where e.comp_name = cust_info.cust_name;
        else
        
          select count(1)
            into v_ztgs_count
            from edw00.pty_main_info e
           where e.comp_name like cust_info.cust_name || '%'; --能够模糊匹配到
        
          if v_ztgs_count > 1 then
            select e.prip_id
              into v_ztgs_pripid
              from (select e.prip_id,
                           e.comp_name,
                           row_number() over(partition by null order by e.score desc) as rn
                      from (select e.prip_id,
                                   e.comp_name,
                                   utl_match.edit_distance_similarity(e.comp_name,
                                                                      cust_info.cust_name) as score
                              from edw00.pty_main_info e
                             where e.comp_name like
                                   cust_info.cust_name || '%') e) e
             where e.rn = 1; --模糊匹配取匹配率大的数据
          end if;
        end if;
      
      end if;
    end if;
  
    if v_ztgs_pripid is not null then
      update thjs.tb_fxq_cust_ztgs t
         set (t.ztgs_fund_date,
              t.ztgs_cert_no,
              t.ztgs_cert_startdate,
              t.ztgs_cert_enddate,
              t.ztgs_chair_man,
              t.ztgs_pripid) =
             (select case
                       when length(e.fund_date) = 8 then
                        to_char(to_date(e.fund_date, 'yyyyMMdd'), 'yyyy-MM-dd')
                       else
                        ''
                     end as fund_date,
                     e.credit_code,
                     case
                       when length(e.appr_date) = 8 then
                        to_char(to_date(e.appr_date, 'yyyyMMdd'), 'yyyy-MM-dd')
                       else
                        ''
                     end cert_startdate, --证照有效起始
                     case
                       when length(e.op_end) = 8 then
                        to_char(to_date(e.op_end, 'yyyyMMdd'), 'yyyy-MM-dd')
                       else
                        '2100-12-31' --如为9999-12-31，匹配为2100-12-31
                     end as cert_enddate, --证照有效截止
                     e.legal_person as chair_man, --法人代表姓名
                     e.prip_id
                from edw00.pty_main_info e
               where e.prip_id = v_ztgs_pripid)
       where t.cust_id = cust_info.cust_id;
    end if;
  
  end loop;

  commit;

  o_return_msg  := '执行成功';
  o_return_code := 0;

exception
  -- 非预定义异常处理
  when v_userexp then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    hgman.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
    -- 预定义异常处理
  when others then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    hgman.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
end;

Create or Replace procedure "THJS"."P_FXQ_DOWJONES_TASK" (i_tradedate in char) is
  ----------------------------------------------------------------------------------
  --版    权：GTJA
  --版    本：1.0.0
  --开发人员：YLT@GTJA
  --创建日期：20200428
  --模块编号：
  --模块名称：投行反洗钱 - 道琼斯黑名单数据增量转换
  --功能名称：
  ----------------------------------------------------------------------------------
  --==============================================================================
  --固定变量
  v_userexp exception; -- 用户定义错
  v_tradedate    varchar2(8); -- 任务执行时间(业务日期)
  v_exec_func_id integer default '0'; -- 任务id
  v_func_own     varchar2(20) default 'thjs'; -- 任务归属用户（schema）
  v_func_name    varchar2(2000) default 'p_fxq_cust_rz_fk_trans'; -- 任务名称(存储过程的名字)
  v_sqlerrm      varchar2(4000); -- 错误提示信息
  v_sqlcode      number; -- 错误代码
  v_sqlerrl      varchar2(4000); -- 错误行号
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  v_count integer default 0;
  --=============================================================
  -- 业务处理过程
  --=============================================================

begin

  --将道琼斯黑名单临时表数据结转至历史表
  select count(1)
    into v_count
    from thjs.fxq_dowjones_tmp t
   where t.busi_date = i_tradedate;

  if v_count > 0 then
  
    delete from thjs.fxq_dowjones_his t
     where exists
     (select 1 from thjs.fxq_dowjones_tmp x where x.id = t.id);
  
    insert into thjs.fxq_dowjones_his
      (busi_date,
       id,
       type,
       first_name,
       middle_name,
       surname,
       suffix,
       fms_name,
       fsm_name,
       mfs_name,
       msf_name,
       sfm_name,
       smf_name,
       entityname,
       other_name,
       birth_day,
       active_status,
       image_url,
       biz_date,
       idnumber_type,
       idnumber,
       idnotes,
       country_type,
       country_code,
       country_name,
       addressline,
       addresscity,
       addresscountry,
       countrycode,
       countryname,
       adderss_countrycode,
       if_a1,
       if_a2,
       if_a3,
       ground_time)
      select t.busi_date,
             t.id,
             t.type,
             t.first_name,
             t.middle_name,
             t.surname,
             t.suffix,
             t.fms_name,
             t.fsm_name,
             t.mfs_name,
             t.msf_name,
             t.sfm_name,
             t.smf_name,
             t.entityname,
             t.other_name,
             t.birth_day,
             t.active_status,
             t.image_url,
             t.biz_date,
             t.idnumber_type,
             t.idnumber,
             t.idnotes,
             t.country_type,
             t.country_code,
             t.country_name,
             t.addressline,
             t.addresscity,
             t.addresscountry,
             t.countrycode,
             t.countryname,
             t.adderss_countrycode,
             t.if_a1,
             t.if_a2,
             t.if_a3,
             t.ground_time
        from thjs.fxq_dowjones_tmp t;
  
  end if;

  commit;

exception
  -- 非预定义异常处理
  when v_userexp then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    hgman.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
    -- 预定义异常处理
  when others then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    hgman.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
end;

CREATE OR REPLACE PROCEDURE "THJS"."P_FXQ_INTERFACE_LOG_S"("I_TYPE" IN VARCHAR2(32767),"I_ENTNAME" IN VARCHAR2(32767),"I_KEY" IN VARCHAR2(32767),"I_PROJ_TYPE" IN VARCHAR2(32767),"I_USERCODE" IN VARCHAR2(32767),"O_RETURN_MSG" OUT VARCHAR2(32767),"O_RETURN_CODE" OUT INTEGER)
AUTHID DEFINER
 is
  ----------------------------------------------------------------------------------
  --版    权：GTJA
  --版    本：1.0.0
  --开发人员：CZC@GTJA
  --创建日期：20190731
  --模块编号：
  --模块名称：反洗钱客户管理 - 投行智能平台反洗钱查询调用回调日志
  --功能名称：
  ----------------------------------------------------------------------------------
  --==============================================================================
  --固定变量
  v_userexp exception; -- 用户定义错
  v_tradedate    varchar2(8); -- 任务执行时间(业务日期)
  v_exec_func_id integer default '0'; -- 任务id
  v_func_own     varchar2(20) default 'thjs'; -- 任务归属用户（schema）
  v_func_name    varchar2(2000) default 'p_fxq_interface_log_s'; -- 任务名称(存储过程的名字)
  v_sqlerrm      varchar2(4000); -- 错误提示信息
  v_sqlcode      number; -- 错误代码
  v_sqlerrl      varchar2(4000); -- 错误行号
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  v_count integer default 0;
  --=============================================================
  -- 业务处理过程
  --=============================================================

begin

  insert into thjs.tb_exec_log
    (log_id, proc_name, proc_param, exec_time)
  values
    (thjs.tb_exec_log_id_seq.nextval,
     'p_fxq_interface_log_s',
     'type:' || i_type || ',entname:' || i_entname || ',key:' || i_key ||
     ',proj_type:' || i_proj_type || ',usercode:' || i_usercode,
     sysdate);
  commit;

  v_tradedate := to_char(sysdate, 'yyyyMMdd');

  --20240524  i_entname 可按冒号:分隔客户名称，证件代码传递

  --回调前验证客户是否存在
  if i_type = '1' and i_entname is not null then
    select count(1)
      into v_count
      from (select t.client_id as cust_id,
      			   t.client_name as cust_name,
      			   t.id_no as cert_no,
      			   decode(t.organ_flag,'0','1','0') as cust_type
      		  from thjs.t_th_client_info t
      		/*select r.cust_id, r.cust_name, r.cert_no, '0' as cust_type
              from thjs.tb_fxq_cust_rz r
             where r.cust_biz <> '测试'
            union all
            select z.cust_id, z.cust_name, z.cert_no, '1' as cust_type
              from thjs.tb_fxq_cust_zr z
             where z.cust_biz <> '测试'*/) r
     where exists (select column_value
              from table(thjs.splitstr(i_entname, ':')) t
             where column_value = r.cert_no
                or column_value = r.cust_name);
  
    if v_count = 0 then
      o_return_msg  := '客户不存在！';
      o_return_code := -1;
      return;
    end if;
  
  end if;

  insert into thjs.tb_fxq_interface_log
    (log_key, log_type, entname, proj_type, user_code, log_time)
  values
    (i_key, i_type, i_entname, i_proj_type， i_usercode, sysdate);

  commit;

  o_return_msg  := '执行成功';
  o_return_code := 0;

exception
  -- 非预定义异常处理
  when v_userexp then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    thjs.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
    -- 预定义异常处理
  when others then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    thjs.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
end;

Create or Replace procedure "THJS"."P_FXQ_INTERFACE_Q" (rt_cursor     out sys_refcursor, --返回游标结果集
                                                   i_userflag    in varchar2, --用户标识：0-我填报的反洗钱客户
                                                   i_entname     in varchar2, --客户统一社会信用代码/客户名称
                                                   i_usercode    in varchar2, --操作人
                                                   o_return_msg  out varchar2,
                                                   o_return_code out integer) is
  ----------------------------------------------------------------------------------
  --版    权：GTJA
  --版    本：1.0.0
  --开发人员：CZC@GTJA
  --创建日期：20220714
  --模块编号：
  --模块名称：投行反洗钱 - 投行智能平台-项目工作室接口 我填报的反洗钱客户 查询验证
  --功能名称：
  ----------------------------------------------------------------------------------
  --==============================================================================
  --固定变量
  v_userexp exception; -- 用户定义错
  v_tradedate    varchar2(8); -- 任务执行时间(业务日期)
  v_exec_func_id integer default '0'; -- 任务id
  v_func_own     varchar2(20) default 'thjs'; -- 任务归属用户（schema）
  v_func_name    varchar2(2000) default 'p_fxq_interface_q'; -- 任务名称(存储过程的名字)
  v_sqlerrm      varchar2(4000); -- 错误提示信息
  v_sqlcode      number; -- 错误代码
  v_sqlerrl      varchar2(4000); -- 错误行号
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  v_prvlge integer default 0;
  --=============================================================
  -- 业务处理过程
  --=============================================================

begin

  v_tradedate := to_char(sysdate, 'yyyyMMdd');

  --v102+ start
  insert into thjs.tb_exec_log
    (log_id, proc_name, proc_param, exec_time)
  values
    (thjs.tb_exec_log_id_seq.nextval,
     'p_fxq_inteface_q',
     'i_userflag:' || i_userflag || ',i_entname:' || i_entname ||
     ',i_usercode:' || i_usercode,
     sysdate);
  commit;
  --v102+ end

  --暂不控制查询权限，查询以登陆用户为条件
  /*--检查用户是否具有对应权限
  select count(1)
    into v_prvlge
    from BASIC_THJS.wb_user u
   inner join BASIC_THJS.wb_user_role r
      on u.user_id = r.user_id
     and r.role_id in ('admin-th', 'fxqtb-th', 'fxqgl') --投行管理员角色，投行反洗钱客户填报人，反洗钱客户管理员
   where u.user_name = i_usercode;
  
  if v_prvlge = 0 then
    open rt_cursor for
      select '0' as user_flag from dual;
    o_return_code := -1;
    o_return_msg  := '当前用户无反洗钱客户查询权限，请联系合规管理员！';
    return;
  end if;*/

  --检查项目是否存在
  open rt_cursor for
    select '1' as user_flag from dual;

  commit;

  o_return_msg  := '执行成功';
  o_return_code := 0;

exception
  -- 非预定义异常处理
  when v_userexp then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    thjs.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
    -- 预定义异常处理
  when others then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    thjs.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
end;

Create or Replace procedure "THJS"."P_FXQ_MAIL_TASK" (i_tradedate in varchar2) is
  ----------------------------------------------------------------------------------
  --版    权：GTJA
  --版    本：1.0.0
  --开发人员：CZC@GTJA
  --创建日期：20210722
  --模块编号：
  --模块名称：投行反洗钱 - 反洗钱邮件提醒待发送列表生成
  --功能名称：
  ----------------------------------------------------------------------------------
  /*v101 CZC@GTJA 20240819 调整证件/证照到期提醒邮件描述
  */

  --==============================================================================
  --固定变量
  v_userexp exception; -- 用户定义错
  v_tradedate    varchar2(8); -- 任务执行时间(业务日期)
  v_exec_func_id integer default '0'; -- 任务id
  v_func_own     varchar2(20) default 'thjs'; -- 任务归属用户（schema）
  v_func_name    varchar2(2000) default 'p_fxq_mail_task'; -- 任务名称(存储过程的名字)
  v_sqlerrm      varchar2(4000); -- 错误提示信息
  v_sqlcode      number; -- 错误代码
  v_sqlerrl      varchar2(4000); -- 错误行号
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  v_flow_count integer;
  v_return_msg  varchar2(1000);
  v_return_code number;
  --=============================================================
  -- 业务处理过程
  --=============================================================

begin

  --反洗钱客户证件到期邮件提醒=======================
  /*"身份证件/证照有效期截止”到期前一个月、半个月、七天
  （涉及表单客户信息之证照有效期截止、身份证件有效期截止处；
    控股股东信息之证照有效期截止、身份证件有效期截止处；
    实际控制人信息之证照有效期截止、身份证件有效期截止处；
    授权代表人信息之身份证件有效期截止处；
    受益所有人信息之证件有效期截止处）
  提醒：维护人、孔娟娟
  邮件、短信 "您填报的反洗钱客户中有主体xx证件/证照即将过期，请登录合规大数据平台查看，提醒客户及时更新证件/证照，并及时更新反洗钱表单信息和底稿。"
  
  20220914
  您填报的反洗钱客户“xxxxx”中有主体“xxxx”证件/证照即将过期、“xxxxx”中有主体“xxxx”证件/证照即将过期，
  请登录合规大数据平台查看，提醒客户及时更新证照/证件，并及时更新反洗钱表单信息和底稿。以免反洗钱客户被设置限制标签，影响协议流程、内核申请等。
  
  20240819 v101+
  您填报的反洗钱客户“xxxxx”中有主体“xxxx”证件/证照还有一个月/半个月/7天过期。
  请登录合规大数据平台查看，提醒客户及时更新证照/证件，并及时更新反洗钱表单信息和底稿。以免反洗钱客户被设置限制标签，影响协议流程、内核申请等。
  */

  delete from thjs.tmp_fxq_cert_remind t where t.busi_date = i_tradedate;
  insert into thjs.tmp_fxq_cert_remind
    (busi_date,
     cust_flag,
     cust_id,
     cust_name,
     remind_name,
     cert_enddate,
     cert_flag,
     op_user,
     remind_date1,
     remind_date2,
     remind_date3,
     email)
    select i_tradedate,
           t.cust_flag,
           t.cust_id,
           t.cust_name,
           t.remind_name,
           t.cert_enddate,
           t.cert_flag,
           t.op_user,
           t.remind_date1,
           t.remind_date2,
           t.remind_date3,
           nvl(u.email,u1.email) as email
      from (select t.cust_flag,
                   t.cust_id,
                   t.cust_name,
                   t.remind_name,
                   t.cert_enddate,
                   t.cert_flag,
                   t.op_user,
                   to_char(to_date(t.cert_enddate, 'yyyy-MM-dd') - 7, --7天
                           'yyyyMMdd') as remind_date1,
                   to_char(to_date(t.cert_enddate, 'yyyy-MM-dd') - 15, --半个月
                           'yyyyMMdd') as remind_date2,
                   to_char(add_months(to_date(t.cert_enddate, 'yyyy-MM-dd'), --一个月
                                      -1),
                           'yyyyMMdd') as remind_date3
              from thjs.vw_fxq_cust_certend t
             --20260516 新老系统邮件分开发送
             where t.cust_id >= '80000') t
      left join BASIC_THJS.wb_user u
        on u.user_name = t.op_user
      left join BASIC_THJS.wb_user_hg u1
        on u1.user_name = t.op_user
     where t.remind_date1 = i_tradedate
        or t.remind_date2 = i_tradedate
        or t.remind_date3 = i_tradedate;
  commit;

  insert into thjs.tb_fxq_mail
    (mail_id,
     send_user,
     receive_user,
     cc_user,
     mail_title,
     mail_content,
     remark)
    select t.receive_user || t.busi_date as mail_id, --每个客户每天汇总提醒一次
           --'投行委合规管理组' as send_user,
           'cm_ibd@gtht.com' as send_user,
           t.receive_email,
           --'chenhaiyang@gtht.com' as receive_email,
           --'caizhicai@gtht.com' as receive_email,
           'hechuan@gtht.com' as cc_user,
           --'chenhaiyang@gtht.com' as cc_user,
           '反洗钱客户证照过期提醒！' as mail_title,
           --v101+
           /*'<p><span style="font-family:Arial;font-size:14px;">         您填报的反洗钱客户' ||
           t.cust_names ||
           '，请登录合规大数据平台查看，提醒客户及时更新证照/证件，并及时更新反洗钱表单信息和底稿。以免反洗钱客户被设置限制标签，影响协议流程、内核申请等。</span></p>   ' as mail_content,
           '' as cust_names --t.cust_names */
           '<p><span style="font-family:Arial;font-size:16px;">          您填报的反洗钱客户' ||
           t.cust_names ||
           '。<br><br>请登录<a href="http://10.181.135.22:8080/thhg/home">投行合规管理系统</a>查看，提醒客户及时更新证照/证件，并及时更新反洗钱表单信息和底稿。以免反洗钱客户被设置限制标签，影响协议流程、内核申请等。</span></p>   ' as mail_content,
           '' as cust_names --t.cust_names 
    --v101+
      from (select t.busi_date,
                   t.receive_user,
                   t.receive_email,
                   --v101+
                   /*listagg('“' || t.cust_name || '”中有主体“' || t.remind_names ||
                   '”证件/证照即将过期',
                   '、') within group(order by t.cust_id) cust_names */
                   listagg('“' || t.cust_name || '”中有主体' || t.remind_names,
                           '；') within group(order by t.cust_id) cust_names
            --v101+
              from (select t.busi_date,
                           t.cust_id,
                           t.cust_name,
                           t.op_user,
                           t.email,
                           --nvl(t.op_user, 'lijin028105') as receive_user,
                           --nvl(t.email, 'lijin4@gtht.com') as receive_email,
                           nvl(t.op_user, 'chenhaiyang') as receive_user,
                           nvl(t.email, 'chenhaiyang@gtht.com') as receive_email,
                           --v101+
                           --listagg(t.remind_name, '、') within group(order by t.cust_id) remind_names
                           listagg('“' || t.remind_name || '”证件/证照<b>还有' ||
                                   t.remind_days || '</b>过期',
                                   '、') within group(order by t.cust_id) remind_names
                    --v101+
                      from (select distinct t.busi_date,
                                            t.cust_id,
                                            t.cust_name,
                                            t.remind_name,
                                            t.op_user,
                                            t.email,
                                            case
                                              when t.remind_date1 = t.busi_date then
                                               '7天'
                                              when t.remind_date2 = t.busi_date then
                                               '半个月'
                                              when t.remind_date3 = t.busi_date then
                                               '一个月'
                                            end as remind_days
                              from thjs.tmp_fxq_cert_remind t
                             where t.busi_date = i_tradedate) t
                     group by t.busi_date,
                              t.cust_id,
                              t.cust_name,
                              t.op_user,
                              t.email) t
             group by t.busi_date, t.receive_user, t.receive_email) t;
  commit;
  
  -- 自然人、非自然人客户本身、法定代表人、受益所有人证件过期90个自然日
  delete from thjs.tb_fxq_cert_remind t where t.busi_date = i_tradedate;
  insert into thjs.tb_fxq_cert_remind
    (busi_date,
     cust_flag,
     cust_id,
     cust_name,
     remind_name,
     cert_enddate,
     cert_flag,
     cert_order,
     op_user,
     remind_date,
     email)
    select i_tradedate,
           t.cust_flag,
           t.cust_id,
           t.cust_name,
           t.remind_name,
           t.cert_enddate,
           t.cert_flag,
           t.cert_order,
           t.op_user,
           t.remind_date,
           u.email
      from (select t.cust_flag,
                   t.cust_id,
                   t.cust_name,
                   t.remind_name,
                   t.cert_enddate,
                   t.cert_flag,
                   t.cert_order,
                   t.op_user,
                   t.status,
                   --v101+
                   case
                     when t.cert_enddate is null THEN
                      '99991231'
                     when t.cert_enddate = '9999-12-31' then
                      '99991231'
                     else
                      to_char(to_date(t.cert_enddate, 'yyyy-MM-dd') + 90, --90天                                        
                              'yyyyMMdd')
                   end as remind_date
            --v101+
              from thjs.vw_fxq_cust_certend t
             --20260516 新老系统邮件分开发送
             where t.cust_id >= '80000') t --视图已过滤，只查正常非测试客户--状态：0-正常 1-失效 2-限制
      left join BASIC_THJS.wb_user u
        on u.user_name = t.op_user
     where t.remind_date <= i_tradedate
       and t.cert_flag in ('客户证件有效截止',
                           '法人代表证件有效截止',
                           '受益所有人证件有效截止')
     order by t.cert_enddate desc;

  commit;

  for cust in (select t.cust_flag, t.cust_id
                 from thjs.tb_fxq_cert_remind t
                where t.busi_date = i_tradedate
                group by t.cust_flag, t.cust_id
                order by t.cust_id) loop
  
    --设置客户状态为限制  
    thjs.p_fxq_cust_rz_l(cust.cust_id,
                         '2', --操作标识：0-正常（解除限制) 1-失效 2-限制
                         'admin', --操作人
                         v_return_msg,
                         v_return_code);
    commit;
  end loop;
  

  insert into thjs.tb_fxq_mail
    (mail_id,
     send_user,
     receive_user,
     cc_user,
     mail_title,
     mail_content,
     remark)
  select sys_guid() as mail_id, --每个客户每天汇总提醒一次
          -- '投行委合规管理组' as send_user,
           'cm_ibd@gtht.com' as send_user,
           nvl(u.email,u1.email),
           'hechuan@gtht.com' as cc_user,
           t.cust_name || '反洗钱审核意见及扣分情况' as mail_title,
           --v101+
           '<p><span style="font-family:Arial;font-size:16px;">          您填报的反洗钱客户' ||
           t.cust_name || case
           					      when t.cert_flag in ('法人代表证件有效截止','受益所有人证件有效截止') then
           					        '因主体'||t.cust_name||'证件/证照过期90个自然日未及时更新，已被设置限制标签。请及时联系客户更新反洗钱表单信息和底稿。'
           					      when t.cust_flag = '0' then
           					        '因证件过期90个自然日未及时更新，已被设置限制标签。请及时联系客户更新反洗钱表单信息和底稿。'
           					      when t.cust_flag = '1' then
           					        '因证件/证照过期90个自然日未及时更新，已被设置限制标签。请及时联系客户更新反洗钱表单信息和底稿。'
           					    end ||
           '</span></p>   ' as mail_content,
           '' as cust_names --t.cust_names 
      from (select t.cust_flag,
                   t.cust_id,
                   t.cust_name,
                   t.remind_name,
                   t.cert_enddate,
                   t.cert_flag,
                   t.cert_order,
                   t.op_user,
                   t.status,
                   --v101+
                   case
                     when t.cert_enddate is null THEN
                       '99991231'
                     when t.cert_enddate = '9999-12-31' then
                      '99991231'
                     else
                      to_char(to_date(t.cert_enddate, 'yyyy-MM-dd') + 90, --90天                                        
                              'yyyyMMdd')
                   end as remind_date
            --v101+
              from thjs.vw_fxq_cust_certend t
             --20260516 新老系统邮件分开发送
             where t.cust_id >= '80000') t --视图已过滤，只查正常非测试客户--状态：0-正常 1-失效 2-限制
      left join BASIC_THJS.wb_user u
        on u.user_name = t.op_user
      left join BASIC_THJS.wb_user_hg u1
        on u1.user_name = t.op_user
     where t.remind_date <= i_tradedate
       and t.cert_flag in ('客户证件有效截止',
                           '法人代表证件有效截止',
                           '受益所有人证件有效截止')
     order by t.cert_enddate desc;
  commit;
  --=======================================================
  /*--20230410 检查反洗钱代办流程是否存在隔日未发送情况，发送提醒邮件
  select count(1)
    into v_flow_count
    from thjs.tb_flow_inst t
   where t.send_status = '0'
     and to_char(t.op_time, 'yyyyMMdd') < to_char(sysdate, 'yyyyMMdd');

  if v_flow_count > 0 then
  
    insert into thjs.tb_fxq_mail
      (mail_id,
       send_user,
       receive_user,
       cc_user,
       mail_title,
       mail_content,
       remark)
      select 'fxqflownosend' || i_tradedate as mail_id, --每个客户每天汇总提醒一次
             '投行委合规管理组' as send_user,
             'chenhaiyang@gtht.com' as receive_email,
             --'lijin4@gtht.com' as receive_email,
             '' as cc_user,
             '反洗钱流程隔日未发送，请检查！' as mail_title,
             '反洗钱流程隔日未发送：' || v_flow_count || '个' as mail_content， ''
        from dual;
  
    commit;
  end if;*/

exception
  -- 非预定义异常处理
  when v_userexp then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    thjs.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
    -- 预定义异常处理
  when others then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    thjs.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
end;

Create or Replace procedure "THJS"."P_FXQ_RISK_FLOW_C" (i_flow_id     in varchar2, --流程实例id
                                                   i_usercode    in varchar2, --操作人
                                                   o_return_msg  out varchar2,
                                                   o_return_code out integer) is
  ----------------------------------------------------------------------------------
  --版    权：gtja
  --版    本：1.0.0
  --开发人员：wyf
  --创建日期：20230220
  --模块编号：
  --模块名称：投行反洗钱 - 风险核查流程提交，流程结束保持sp
  --功能名称：
  ----------------------------------------------------------------------------------

  --==============================================================================
  --固定变量
  v_userexp exception; -- 用户定义错
  v_tradedate    varchar2(8); -- 任务执行时间(业务日期)
  v_exec_func_id integer default '0'; -- 任务id
  v_func_own     varchar2(20) default 'thjs'; -- 任务归属用户（schema）
  v_func_name    varchar2(2000) default 'p_fxq_risk_flow_c'; -- 任务名称(存储过程的名字)
  v_sqlerrm      varchar2(4000); -- 错误提示信息
  v_sqlcode      number; -- 错误代码
  v_sqlerrl      varchar2(4000); -- 错误行号
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量

  --=============================================================
  -- 业务处理过程
  --=============================================================

begin
  v_tradedate := to_char(sysdate, 'yyyyMMdd');

  insert into thjs.tb_exec_log
    (log_id, proc_name, proc_param, exec_time)
  values
    (thjs.tb_exec_log_id_seq.nextval,
     'p_fxq_risk_flow_s',
     'flow_id:' || i_flow_id || ',usercode:' || i_usercode,
     sysdate);
  commit;

  update thjs.tb_fxq_risk_flow t
     set t.flow_staus  = '1',
         t.update_user = i_usercode,
         t.update_time = sysdate
   where t.flow_id = i_flow_id;
  commit;

  o_return_msg  := '执行成功';
  o_return_code := 0;

exception
  -- 非预定义异常处理
  when v_userexp then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    hgman.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
    -- 预定义异常处理
  when others then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    hgman.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
end;

Create or Replace procedure "THJS"."P_FXQ_RISK_FLOW_CUST_Q" (rt_cursor     out sys_refcursor, --返回游标结果集
                                                        i_cust_id     in varchar2, --客户代码
                                                        i_busi_date   in varchar2, --业务日期
                                                        i_usercode    in varchar2, --查询人
                                                        o_return_msg  out varchar2,
                                                        o_return_code out integer) is
  ----------------------------------------------------------------------------------
  --版    权：gtja
  --版    本：1.0.0
  --开发人员：wyf
  --创建日期：20230220
  --模块编号：
  --模块名称：投行合规反洗钱 - 流程表单客户信息查询（客户信息+核查信息）
  --功能名称：
  ----------------------------------------------------------------------------------
  --==============================================================================
  --固定变量
  v_userexp exception; -- 用户定义错
