Create or Replace procedure "THJS"."P_FXQ_RISK_FLOW_FILES_Q" (rt_cursor     out sys_refcursor, --返回游标结果集
                                                         i_cust_id     in integer, --客户id
                                                         i_flow_id     in varchar2, --流程id
                                                         i_usercode    in varchar2, --查询人
                                                         o_return_msg  out varchar2,
                                                         o_return_code out integer) is
  ----------------------------------------------------------------------------------
  --版    权：gtja
  --版    本：1.0.0
  --开发人员：wyf
  --创建日期：20230227
  --模块编号：
  --模块名称：投行反洗钱 - 反洗钱客户风险核查审批信息附件查询
  --功能名称：
  ----------------------------------------------------------------------------------

  --==============================================================================
  --固定变量
  v_userexp exception; -- 用户定义错
  v_tradedate    varchar2(8); -- 任务执行时间(业务日期)
  v_exec_func_id integer default '0'; -- 任务id
  v_func_own     varchar2(20) default 'thjs'; -- 任务归属用户（schema）
  v_func_name    varchar2(2000) default 'p_fxq_risk_flow_files_q'; -- 任务名称(存储过程的名字)
  v_sqlerrm      varchar2(4000); -- 错误提示信息
  v_sqlcode      number; -- 错误代码
  v_sqlerrl      varchar2(4000); -- 错误行号
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  v_count integer default 0;
  --=============================================================
  -- 业务处理过程
  --=============================================================

begin

  v_tradedate := to_char(sysdate, 'yyyyMMdd');

  insert into thjs.tb_exec_log
    (log_id, proc_name, proc_param, exec_time)
  values
    (thjs.tb_exec_log_id_seq.nextval,
     'p_fxq_risk_flow_files_q',
     'i_cust_id:' || i_cust_id || ' -' || 'i_flow_id:' || i_flow_id || ' -' ||
     'i_usercode:' || i_usercode,
     sysdate);
  commit;

  select count(1)
    into v_count
    from thjs.tb_fxq_risk_flow_files r
   where r.cust_id = i_cust_id
     and r.flow_id = i_flow_id;

  open rt_cursor for
    select *
      from (select row_number() over(partition by r.file_name, r.file_path order by r.update_time desc) as rn,
                   r.cust_id,
                   r.file_name,
                   r.file_path,
                   r.upload_user,
                   r.upload_time,
                   r.update_user,
                   r.update_time
              from thjs.tb_fxq_risk_flow_files r
             where r.cust_id = i_cust_id
               and r.flow_id = i_flow_id
               and r.status = '0') r
     where rn = 1
     order by r.upload_time;

  commit;

  o_return_msg  := '执行成功';
  o_return_code := 0;

exception
  -- 非预定义异常处理
  when v_userexp then
    rollback;

    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();

    hgman.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
    -- 预定义异常处理
  when others then
    rollback;

    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();

    hgman.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
end;

