Create or Replace procedure "THJS"."P_FXQ_RISK_FLOW_TASK" (i_tradedate in varchar2) is
  ----------------------------------------------------------------------------------
  --版    权：gtja
  --版    本：1.0.0
  --开发人员：wyf
  --创建日期：20230214
  --模块编号：
  --模块名称：投行反洗钱 - 风险核查提醒生成，流程表插入处理sp
  --功能名称：
  ----------------------------------------------------------------------------------

  --==============================================================================
  --固定变量
  v_userexp exception; -- 用户定义错
  v_tradedate    varchar2(8); -- 任务执行时间(业务日期)
  v_exec_func_id integer default '0'; -- 任务id
  v_func_own     varchar2(20) default 'thjs'; -- 任务归属用户（schema）
  v_func_name    varchar2(2000) default 'p_fxq_risk_flow_task'; -- 任务名称(存储过程的名字)
  v_sqlerrm      varchar2(4000); -- 错误提示信息
  v_sqlcode      number; -- 错误代码
  v_sqlerrl      varchar2(4000); -- 错误行号
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  v_cur_date varchar2(8);
  --=============================================================
  -- 业务处理过程
  --=============================================================

begin

  v_tradedate := i_tradedate;

  insert into thjs.tb_exec_log
    (log_id, proc_name, proc_param, exec_time)
  values
    (thjs.tb_exec_log_id_seq.nextval,
     'p_fxq_risk_flow_task',
     'i_tradedate:' || i_tradedate,
     sysdate);
  commit;

  select to_char(sysdate, 'yyyyMMdd') into v_cur_date from dual;

  --风险核查盘后隔日执行（依赖盘后风险核查表采集任务）每日任务执行一次
  --实时任务执行（处理实时核查结果） 30分钟执行一次

  --非实时日期处理（过滤前一日实时核查相同的数据）
  if v_tradedate <> v_cur_date then
  
    insert into thjs.tb_fxq_risk_flow_rst
      (busi_date,
       cust_id,
       cust_name,
       entity_type,
       entity_name,
       cert_type,
       cert_no,
       risk_id,
       risk_type,
       realtime_flag)
      select distinct t.busi_date,
                      t.cust_id,
                      t.cust_name,
                      t.entity_type,
                      t.entity_name,
                      t.cert_type,
                      t.cert_no,
                      t.risk_id,
                      t.risk_type,
                      '0'
        from (select t.busi_date,
                     d.client_id as cust_id,--d.cust_id,
                     t.client_name as cust_name,
                     decode(t.entity_type,
                            '0',
                            '机构客户本人',
                            '1',
                            '控股股东',
                            '2',
                            '实际控制人',
                            '3',
                            '受益所有人',
                            '4',
                            '法定代表人',
                            '5',
                            '授权代表人',
                            '6',
                            '机构客户联系人') as entity_type,
                     t.entity_name,
                     /*decode(t.id_type,
                     '0',
                     '中国居民身份证',
                     '1',
                     '护照',
                     '2',
                     '营业执照',
                     t.id_type) as cert_type,*/
                     x.entry_content as cert_type,
                     t.id_no         as cert_no,
                     t.exposed_id    as risk_id,
                     t.if_a          as risk_type
                from thjs.tb_fxq_cust_rz_rst t --盘后
                left join thjs.vw_fxq_cust_info d
                  on t.sc_client_id = d.client_id--d.cust_id
                LEFT JOIN thjs.tb_dict_entry x
                  ON t.id_type = x.entry_content_match
                 AND x.entry_code = 'CERT_TYPE'
               where not exists
               (select *
                        from thjs.tb_fxq_risk_flow_rst c --盘后前一日实时已核查出结果的，t日盘后数据不插入
                       where c.busi_date =
                             to_char(to_date(t.busi_date, 'yyyyMMdd') - 1,
                                     'yyyyMMdd')
                         and c.realtime_flag = '1'
                         and c.cust_id = t.sc_client_id
                         and c.entity_type = t.entity_type
                         and c.entity_name = t.entity_name)) t
       where not exists (select *
                from thjs.tb_fxq_risk_flow_rst r
               where r.busi_date = t.busi_date
                 and r.cust_id = t.cust_id
                 and r.entity_type = t.entity_type
                 and r.entity_name = t.entity_name); --已存在的不插入
    commit;
  end if;

  --实时数据处理
  if v_tradedate = v_cur_date then
  
    insert into thjs.tb_fxq_risk_flow_rst
      (busi_date,
       cust_id,
       cust_name,
       entity_type,
       entity_name,
       cert_type,
       cert_no,
       risk_id,
       risk_type,
       realtime_flag)
      select distinct v_tradedate,
                      t.cust_id,
                      t.cust_name,
                      t.entity_type,
                      t.entity_name,
                      t.cert_type,
                      t.cert_no,
                      t.risk_id,
                      t.risk_type,
                      '1'
        from (select t.cust_id,
                     d.cust_name,
                     d.cert_no as cust_certno,
                     t.country,
                     d.open_date,
                     case
                       when t.category in ('机构', '自然人') then
                        '客户本人'
                       when t.category = '控股股东' then
                        '机构客户控股股东'
                       when t.category = '法人' then
                        '法定代表人'
                       else
                        t.category
                     end as entity_type,
                     t.cust_name as entity_name,
                     t.cert_type,
                     t.cert_no,
                     t.risk_id,
                     t.risk_type
                from thjs.tb_fxq_cust_rsk_zhlc t --实时
                left join (select d.cust_id,
                                 d.cust_name,
                                 d.cert_no,
                                 d.fund_date as open_date
                            from thjs.tb_fxq_cust_rz d
                          union all
                          select x.cust_id,
                                 x.cust_name,
                                 x.cert_no,
                                 x.birth_date as open_date
                            from thjs.tb_fxq_cust_zr x) d
                  on t.cust_id = d.cust_id
               where to_char(t.check_time, 'yyyyMMdd') = v_cur_date --当日新增客户
                 and t.risk_id is not null) t --存在风险
       where not exists (select *
                from thjs.tb_fxq_risk_flow_rst r
               where r.busi_date = v_tradedate
                 and r.cust_id = t.cust_id
                 and r.entity_type = t.entity_type
                 and r.entity_name = t.entity_name); --已存在的不插入
    commit;
  
  end if;

  --保存流程数据至流程主表 
  INSERT INTO thjs.tb_fxq_risk_flow
    (busi_date,
     cust_id,
     cust_name,
     cust_certno,
     country,
     open_date,
     flow_code,
     param_info
     --is_riskcust,
     --risk_type,
     --remark,
     --update_user,
     --update_time  
     )
    select d.busi_date,
           t.client_id as cust_id,--t.cust_id,
           t.client_name as cust_name,--cust_name,
           t.id_no as cert_no,
           --t.country,
           c.comments as country_name,
           t.setup_date as fund_date,
           decode(t.organ_flag, '机构', 'fxq_jg', 'fxq_zrr') as flow_code,
           'cust_id:' || t.client_id || ',cust_name:' || t.client_name ||
           ',busi_date:' || d.busi_date as param_info
      from thjs.vw_fxq_cust_info t
      left join thjs.t_dict_subentry c--thjs.tb_fxq_country c
        on c.subentry = t.country
        and c.entry_no = '1040'
     inner join (select d.cust_id, d.busi_date
                   from thjs.tb_fxq_risk_flow_rst d
                  group by d.cust_id, d.busi_date) d
        on d.cust_id = t.client_id --cust_id
     where t.status <> '1' --非失效客户
       and not exists (select *
              from thjs.tb_fxq_risk_flow f
             where f.busi_date >= d.busi_date
               and f.cust_id = t.client_id); --同一客户每天最多只有一个流程（当日新增客户多次修改，暂不考虑)
  --d.busi_date = v_tradedateand --风险核查数据业务日期不一定为隔日，不判断日期，只判断业务日是否发起过流程

  commit;

  --保存流程待发送记录至流程实例表
  insert into thjs.tb_flow_inst
    (busi_date,
     flow_id,
     flow_code,
     raise_code,
     biz_key,
     title,
     param_info,
     send_status)
    select f.busi_date,
           f.flow_id,
           f.flow_code,
           'fxq_fxhc' as raise_code, --风险核查
           f.cust_id,
           f.cust_name || ' 风险核查' as title,
           f.param_info,
           '0'
      from thjs.tb_fxq_risk_flow f
     where not exists (select *
              from thjs.tb_flow_inst t
             where t.raise_code = 'fxq_fxhc'
               and t.biz_key = f.cust_id
               and t.busi_date >= f.busi_date);
  commit;

exception
  -- 非预定义异常处理
  when v_userexp then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    thjs.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
    -- 预定义异常处理
  when others then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    thjs.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
end;

Create or Replace procedure "THJS"."P_FXQ_TEST_LOG_S" (i_xwl_name    in varchar2, --测试文件名称
