Create or Replace procedure "THJS"."P_G_MAIL_ZYZS" (i_tradedate   in char,
                                               o_return_code out integer)
/*==============================================================================
  版    本 : 1.0.0
  创建人员 : lxb
  模块编号 : thjs.p_g_mail_zyzs
  创建日期 : 2025/5/7
  功能描述 : 自营做市清单邮件发送
  修改内容：
  ==============================================================================*/
  --以调用者身份（invoker right）运行
 as
  v_sqlcode       integer default 0; --错误代码
  v_sqlerrm       varchar2(500) default ''; --错误信息
  v_function_id   integer default 0; --功能号
  v_function_desc varchar2(50) default ''; --功能描述
  v_program_name  varchar2(40) default 'p_g_mail_zyzs'; --存储过程名
  -- ============================================================================
  -- 定义业务变量
  v_date_flag number; --是否交易日标志
  v_count1    number;
  v_count2    number;
  iflag       number;
  v_receiver  varchar2(2000);
  v_text      clob;
  v_date   varchar2(10) default ''; --错误信息
begin
  ----1. 日期转换
  v_date  := kingstar.get_last_n_tradedate(i_tradedate, -1);
  o_return_code := 1;
  --1.1 交易日执行
  select count(1)
    into v_date_flag
    from params.tb_exchange_date t
   where t.market_code = '1'
     and t.date_flag = '1' --交易日
     and t.tradedate = i_tradedate;
  if v_date_flag > 0 then
    ----判断上一交易日自营做市数据是否已结转
    select count(1)
      into v_count1
      from hgpt.tb_hg_xx_070403_all t
     where t.busi_date = v_date;
  
    select count(1)
      into v_count2
      from htzq.t_htzq_zyzs h
     where h.hdate = v_date;
    if v_count1 > 0 and v_count2 > 0 then
      ----当日是否已经发送
      select count(1)
        into iflag
        from thjs.tb_errorlog e
       where e.operate_date = i_tradedate
         and e.function_id = 'p_g_mail_zyzs'
         and e.error_sqlcode = '0';
      if iflag = 0 then
        --查询人员
        v_receiver := '';
        select to_char(wm_concat(a.email))
          into v_receiver
          from (select distinct to_char(e.staff_email) as email
                  from BASIC_THJS.wb_user_role r
                 inner join ehr01.tcl_v_emp_info_hgfk e
                    on (r.user_id = e.ehr_id or r.user_id = e.staff_id)
                 where r.role_id = 'mail_zyzs') a;
        insert into ycmon.tb_ycjk_mail
          (mail_id,
           receive_user,
           cc_user,
           mail_title,
           mail_content,
           mail_file_path,
           send_mark,
           send_time,
           send_user,
           flow_id,
           project_id,
           return_msg,
           send_type,
           create_time,
           content_data,
           file_flag,
           mail_type)
          select sys_guid(),
                 v_receiver,
                 'qiuhuijun@gtht.com;',
                 '做市清单_' || i_tradedate || '，请查看',
                 '<p style="font-size:16pt">各位老师好，附件为最新做市清单数据，请查看!</p>',
                 '',
                 '0',
                 '',
                 'hgglpt@gtht.com',
                 '',
                 '',
                 '',
                 '4',
                 to_char(sysdate, 'YYYY-MM-DD HH24:MI:SS'),
                 '',
                 '',
                 '4'
            from dual;
      
        INSERT INTO THJS.TB_ERRORLOG
          (OPERATE_DATE,
           OPERATE_TIME,
           FUNCTION_ID,
           ERROR_SQLCODE,
           ERROR_SQLERRM)
        VALUES
          (i_tradedate,
           TO_CHAR(SYSDATE, 'HH24MiSS'),
           'p_g_mail_zyzs',
           '0',
           '执行成功');
        commit;
        o_return_code := 0;
      end if;
    end if;
  end if;
  --------------------异常处理-----------------------
exception
  when others then
    v_sqlcode := sqlcode;
    v_sqlerrm := substr(sqlerrm, 1, 500);
    rollback;
end;

Create or Replace procedure "THJS"."P_IB_V_FINANCE_PROJMEMBER" (i_tradedate in char)
/*==============================================================================
  版 本    : 1.0.0
  创建人   : czc
  模块编号 : 0
  日 期    : 2019-03-18
  功能描述 : 投行数据集市 投行系统财务数据采集
  ==============================================================================*/
 as
  v_sqlcode  integer default 0;
  v_sqlstate char(5) default '';
  --v_errcode        integer default 0;
  --v_errstate       char(5) default '';
  v_err_msg varchar2(128) default '';
  --v_not_found      integer default 0;
  --v_last_time      char(8);
  v_function_id    integer default 0; --定义存储过程模块编号
  v_error_line_num integer default 0; --错误行号
  --v_error_level    integer default 0; --错误级别
  v_function_desc varchar2(50) default '投行系统财务数据采集'; --功能描述
  v_program_name  char(40) default 'p_ib_v_finance_projmember'; --程序名
  v_pr_task_id    number default 0; --任务标示
  -- =======================================================================================================================
  -- 定义业务变量
  -- =======================================================================================================================

  -- =======================================================================================================================
  -- 业务开始
  -- =======================================================================================================================
begin

  --每日8点dblink全量采集

  delete from thjs.tb_ib_v_finance_projmember;

  insert into thjs.tb_ib_v_finance_projmember
    (proj_id, projname, projrole, workno, empname, ground_time)
    select t.proj_id,
           t.projname,
           t.projrole,
           t.workno,
           t.empname,
           t.ground_time
      from thjs.ib_v_finance_projmember t;
  commit;

  ------------------------
exception
  when others then
    v_sqlcode := -1 * sqlcode;
    v_err_msg := sqlerrm;
    rollback;
    --记录错误日志
    /*thjs.p_write_error_log(v_pr_task_id, -- 任务标识
                                   0, -- 单位编号
                                   i_tradedate, -- 业务日期
                                   v_function_id, -- 功能标识
                                   v_program_name, -- 程序名
                                   v_error_line_num, -- 程序行号
                                   v_err_msg, -- 错误信息
                                   v_sqlcode, -- sqlcode
                                   v_sqlstate -- sqlstate
                                   );*/
    --记录错误日志
    thjs.p_write_error_log(i_tradedate    => i_tradedate,
                           i_exec_func_id => v_function_id,
                           i_func_own     => 'THJS',
                           i_func_name    => v_program_name,
                           i_occur_time   => sysdate,
                           i_sqlerrm      => v_err_msg,
                           i_sqlcode      => v_sqlcode,
                           i_sqlerrl      => v_error_line_num);
    commit;
    raise;
end;

Create or Replace procedure "THJS"."P_IB_V_GTJA_EMPNAME" (i_tradedate in char)
/*==============================================================================
  版 本    : 1.0.0
  创建人   : czc
  模块编号 : 0
  日 期    : 2019-03-18
  功能描述 : 投行数据集市 投行系统财务数据采集
  ==============================================================================*/
 as
  v_sqlcode  integer default 0;
  v_sqlstate char(5) default '';
  --v_errcode        integer default 0;
  --v_errstate       char(5) default '';
  v_err_msg varchar2(128) default '';
  --v_not_found      integer default 0;
  --v_last_time      char(8);
  v_function_id    integer default 0; --定义存储过程模块编号
  v_error_line_num integer default 0; --错误行号
  --v_error_level    integer default 0; --错误级别
  v_function_desc varchar2(50) default '投行系统财务数据采集'; --功能描述
  v_program_name  char(40) default 'p_ib_v_gtja_empname'; --程序名
  v_pr_task_id    number default 0; --任务标示
  -- =======================================================================================================================
  -- 定义业务变量
  -- =======================================================================================================================

  -- =======================================================================================================================
  -- 业务开始
  -- =======================================================================================================================
begin

  --每日8点dblink全量采集

  delete from thjs.tb_ib_v_gtja_empname;

  insert into thjs.tb_ib_v_gtja_empname
    (emp_id,
     dept_id,
     workno,
     emp_name,
     dept_code,
     dept_name,
     dept_par_id,
     username,
     ground_time)
    select t.emp_id,
           t.dept_id,
           t.workno,
           t.emp_name,
           t.dept_code,
           t.dept_name,
           t.dept_par_id,
           t.username,
           t.ground_time
      from thjs.ib_v_gtja_empname t;
  commit;

  ------------------------
exception
  when others then
    v_sqlcode := -1 * sqlcode;
    v_err_msg := sqlerrm;
    rollback;
    --记录错误日志
    kingstar.pr_audit_write_errlog(v_pr_task_id, -- 任务标识
                                   0, -- 单位编号
                                   i_tradedate, -- 业务日期
                                   v_function_id, -- 功能标识
                                   v_program_name, -- 程序名
                                   v_error_line_num, -- 程序行号
                                   v_err_msg, -- 错误信息
                                   v_sqlcode, -- sqlcode
                                   v_sqlstate -- sqlstate
                                   );
    commit;
    raise;
end;

Create or Replace PROCEDURE "THJS"."P_MANAGERINFO" (rt_cursor       out types.cursortype, --返回游标结果集
                                          i_begindate     in char, --统计开始日期
                                          i_enddate       in char, --统计结束日期
                                          i_datetype      in char, --日期范围类型   0-三月，1-最近半年，2-最近一年
                                          i_deptcode      in char, --部门代码
                                          o_return_status out integer,
                                          I_PAGE_NUM      IN NUMBER DEFAULT 0, --默认值0,
                                          I_PAGE_SIZE     IN NUMBER DEFAULT 0, --默认值0  如果I_PAGE_NUM，I_PAGE_SIZE都为0 则不分页，查询全部
                                          O_TOTAL_COUNT   OUT INTEGER) IS
  --结果状态
  -------------------------------------------------------------------------------------
  -- 版    本： 7.0.0
  -- 开发人员： LIJIANYU
  -- 创建日期： 20190706
  -- 模块编号： 
  -- 模块名称： 部门负责人汇总信息查询
  -- 功能名称： 部门负责人汇总信息查询
  ---------------------------------------------------------------------------------------
  ---------------------------------------------------------------------------------------
  v_sqlcode        integer default 0;
  v_sqlerrm        varchar2(500) default ' ';
  v_err_msg        varchar2(100) default '';
  v_function_id    integer default 0; --定义存储过程模块编号
  v_task_id        number default 0; --定义任务号
  v_error_line_num integer default 0; --错误行号
  v_error_level    integer default 0; --错误级别
  v_program_name   char(40) default 'p_managerinfo'; --存储过程名
  v_userExp exception;

  v_page_num  NUMBER default 0;
  v_page_size NUMBER;

  --=============================================================
  -- 业务处理过程
  --=============================================================
begin

  /*insert into a_test_lijianyu
  values
    (i_organcode || '~' || i_product_orient || '~' || i_product_type || '~' ||
     i_datadate);
  commit;*/

  if I_PAGE_NUM is not null then
    v_page_num := I_PAGE_NUM;
  end if;
  
  
  
  open rt_cursor for
    select a.deptcode,
           a.deptname,
           a.deptmanacode,
           a.deptmananame,
           a.deptmanamobile,
           count(distinct b.id), --股权质押数量
           count(distinct c.id), --行政处罚数量
           count(distinct d.id) --股东信息数量
      from (select distinct t.deptcode, --部门编号
                            t.deptname, --部门名称
                            t.deptmanacode, --部门负责人工号
                            t.deptmananame, --部门负责人姓名
                            t.deptmanamobile, --部门负责人手机号  
                            t.eid --企业ID
              from thjs.tb_thdb_cust_info t
             where t.deptmananame is not null) a
      left join ztgs.e_shares_impawn b
        on a.eid = b.EID --股权质押
      left join ztgs.case_cf_partyinfo c
        on a.eid = c.eid ----行政处罚
      left join ztgs.e_inv_investment d
        on a.eid = d.inv_eid ----股东信息
     group by a.deptcode,
              a.deptname,
              a.deptmanacode,
              a.deptmananame,
              a.deptmanamobile;

  commit;

  o_return_status := 0;

  -- =======================================================================================================================
  -- 错误处理
  -- =======================================================================================================================
exception

  WHEN OTHERS THEN
    o_return_status := -1;
    v_err_msg       := 'sqlcode:' || sqlcode || '||sqlerrm:||' ||
                       substr(sqlerrm, 1, 200);
    ROLLBACK;
    framedp.p_error_log('admin',
                        v_program_name,
                        o_return_status,
                        v_err_msg,
                        '',
                        '1',
                        v_err_msg,
                        o_return_status);
  
end;

Create or Replace PROCEDURE "THJS"."P_PROJINFO_GQ_DETAILS_QUERY" (rt_cursor       out types.cursortype, --返回游标结果集
                                                        i_deptmananame    in char, --责任人姓名
                                                         o_return_msg  out varchar2,
                                                         o_return_code out integer,
                                                        I_PAGE_NUM      IN NUMBER DEFAULT 0, --默认值0,
                                                        I_PAGE_SIZE     IN NUMBER DEFAULT 0, --默认值0  如果I_PAGE_NUM，I_PAGE_SIZE都为0 则不分页，查询全部
                                                        O_TOTAL_COUNT   OUT INTEGER) IS
  --结果状态
  -------------------------------------------------------------------------------------
  -- 版    本： 7.0.0
  -- 开发人员： LIJIANYU
  -- 创建日期： 20190706
