  -- 模块名称： 部门负责人对应项目详细信息查询
  -- 功能名称： 部门负责人对应项目详细信息查询
  ---------------------------------------------------------------------------------------
  ---------------------------------------------------------------------------------------
  v_sqlcode        integer default 0;
  v_sqlerrm        varchar2(500) default ' ';
  v_err_msg        varchar2(100) default '';
  v_function_id    integer default 0; --定义存储过程模块编号
  v_task_id        number default 0; --定义任务号
  v_error_line_num integer default 0; --错误行号
  v_error_level    integer default 0; --错误级别
  v_program_name   char(40) default 'p_projinfo_gq_details_query'; --存储过程名
  v_userExp exception;

  v_page_num  NUMBER default 0;
  v_page_size NUMBER;
  v_maxdate   varchar(8) default '';

  --=============================================================
  -- 业务处理过程
  --=============================================================
begin
  

  if I_PAGE_NUM is not null then
    v_page_num := I_PAGE_NUM;
  end if;

  select max(t.busi_date)
    into v_maxdate
    from thjs.tb_proj_charge_gq_details t;

  open rt_cursor for
    select a.entname, --企业(机构)名称
           a.pripid, --企业ID
           a.deptmanacode, --部门负责人工号
           a.deptmananame, --部门负责人姓名
           a.credit_code, --主体统一社会信用代码
           a.projtype, --项目类型
           a.projphase, --项目阶段
           a.islx, --是否立项
           a.projid, --项目ID
           a.projname, --项目名称
           a.gdinfocount --股东信息
      from thjs.tb_proj_charge_gq_details a
     where a.busi_date = v_maxdate
       and (i_deptmananame is null or a.deptmananame = i_deptmananame);

  commit;

  o_return_code := 0;

  -- =======================================================================================================================
  -- 错误处理
  -- =======================================================================================================================
exception

  WHEN OTHERS THEN
    o_return_code := -1;
    v_err_msg       := 'sqlcode:' || sqlcode || '||sqlerrm:||' ||
                       substr(sqlerrm, 1, 200);
    ROLLBACK;
    framedp.p_error_log('admin',
                        v_program_name,
                        o_return_code,
                        v_err_msg,
                        '',
                        '1',
                        v_err_msg,
                        o_return_code);
  
end;

