Create or Replace PROCEDURE "THJS"."P_PROJINFO_SUM" (i_tradedate in char)
/*==============================================================================
  版 本    : 1.0.0
  创建人   : lijianyu
  模块编号 : 0
  日 期    : 20190708
  功能描述 : 项目信息汇总--批量汇总各纬度数据信息 
  ==============================================================================*/
 as
  v_sqlcode  integer default 0;
  v_sqlstate char(5) default '';
  --v_errcode        integer default 0;
  --v_errstate       char(5) default '';
  v_err_msg varchar2(128) default '';
  --v_not_found      integer default 0;
  --v_last_time      char(8);
  v_function_id    integer default 0; --定义存储过程模块编号
  v_error_line_num integer default 0; --错误行号
  --v_error_level    integer default 0; --错误级别
  v_function_desc varchar2(50) default '项目信息汇总'; --功能描述
  v_program_name  char(40) default 'p_projinfo_gq_sum'; --程序名
  v_pr_task_id    number default 0; --任务标示
  -- =======================================================================================================================
  -- 定义业务变量
  -- =======================================================================================================================

  -- =======================================================================================================================
  -- 业务开始
  -- =======================================================================================================================
begin




--------------------------------股权汇总信息批量加工  以项目负责人纬度进行汇总--------------------------------------------
  delete from thjs.tb_proj_charge_gq_sum e where e.busi_date = i_tradedate;
  insert into thjs.tb_proj_charge_gq_sum
    (BUSI_DATE,
     DEPTCODE,
     DEPTNAME,
     DEPTMANACODE,
     DEPTMANANAME,
     DEPTMANAMOBILE,
     GQZYCOUNT,
     XZCFCOUNT,
     GDXXCOUNT)
    select i_tradedate,
           a.deptcode,
           a.deptname,
           a.deptmanacode,
           a.deptmananame,
           a.deptmanamobile,
           count(distinct b.id), --股权质押数量
           count(distinct c.id), --行政处罚数量
           count(distinct d.id) --股东信息数量
      from (select distinct t.deptcode, --部门编号
                            t.deptname, --部门名称
                            t.deptmanacode, --部门负责人工号
                            t.deptmananame, --部门负责人姓名
                            t.deptmanamobile, --部门负责人手机号  
                            t.eid, --企业ID
                            t.pripid
              from thjs.tb_thdb_cust_info t
             where t.deptmananame is not null) a
      left join ztgs.e_shares_impawn b
        on a.eid = b.EID --股权质押
      left join ztgs.case_cf_partyinfo c
        on a.eid = c.eid ----行政处罚
      left join ztgs.e_inv_investment d
        on a.pripid = d.PRIPID ----股东信息
     group by a.deptcode,
              a.deptname,
              a.deptmanacode,
              a.deptmananame,
              a.deptmanamobile;
  commit;


  --股权项目详细信息批量加工   以项目纬度进行汇总
  delete from thjs.tb_proj_charge_gq_details e where e.busi_date = i_tradedate;
  insert into thjs.tb_proj_charge_gq_details
    (BUSI_DATE,
     ENTNAME,
     PRIPID,
     DEPTMANACODE,
     DEPTMANANAME,
     CREDIT_CODE,
     PROJTYPE,
     PROJPHASE,
     ISLX,
     PROJID,
     PROJNAME,
     GDINFOCOUNT,
     GQINFOCOUNT,
     XZINFOCOUNT,
     eid)
    select i_tradedate,
           a.KHNAME, --企业(机构)名称
           a.pripid, --企业ID
           a.deptmanacode, --部门负责人工号
           a.deptmananame, --部门负责人姓名
           a.credit_code, --主体统一社会信用代码
           a.projtype, --项目类型
           a.projphase, --项目阶段
           a.islx, --是否立项
           a.projid, --项目ID
           a.projname, --项目名称
           count(distinct d.id) gdinfocount, --股东信息
           count(distinct b.id),--股权信息数量
           count(distinct c.id), --行政主罚信息数量
           a.eid
      from (select distinct t.KHNAME, --企业(机构)名称
                            t.pripid, --主体身份代码
                            t.eid, --企业ID
                            t.credit_code, --主体统一社会信用代码
                            t.deptmanacode, --部门负责人工号
                            t.deptmananame, --部门负责人姓名
                            t.projtype, --项目类型
                            t.projphase, --项目阶段
                            t.islx, --是否立项
                            t.projid, --项目ID
                            t.projname --项目名称
              from thjs.tb_thdb_cust_info t
             where t.deptmananame is not null) a
      left join ztgs.e_inv_investment d
        on a.pripid = d.PRIPID ----股东信息
       left join ztgs.e_shares_impawn b
        on a.eid = b.EID --股权质押
      left join ztgs.case_cf_partyinfo c
        on a.eid = c.eid ----行政处罚  
     group by a.KHNAME,
              a.pripid,
              a.eid,
              a.deptmanacode,
              a.deptmananame,
