Create or Replace PROCEDURE "THJS"."P_PROJINFO_ZZ_SUM_QUERY" (rt_cursor       out types.cursortype, --返回游标结果集
                                          i_deptname      in char, --部门名称
                                          o_return_status out integer,
                                          I_PAGE_NUM      IN NUMBER DEFAULT 0, --默认值0,
                                          I_PAGE_SIZE     IN NUMBER DEFAULT 0, --默认值0  如果I_PAGE_NUM，I_PAGE_SIZE都为0 则不分页，查询全部
                                          O_TOTAL_COUNT   OUT INTEGER) IS
  --结果状态
  -------------------------------------------------------------------------------------
  -- 版    本： 7.0.0
  -- 开发人员： LIJIANYU
  -- 创建日期： 20190706
  -- 模块编号： 
  -- 模块名称： 部门负责人汇总信息查询(债质)
  -- 功能名称： 部门负责人汇总信息查询
  ---------------------------------------------------------------------------------------
  ---------------------------------------------------------------------------------------
  v_sqlcode        integer default 0;
  v_sqlerrm        varchar2(500) default ' ';
  v_err_msg        varchar2(100) default '';
  v_function_id    integer default 0; --定义存储过程模块编号
  v_task_id        number default 0; --定义任务号
  v_error_line_num integer default 0; --错误行号
  v_error_level    integer default 0; --错误级别
  v_program_name   char(40) default 'p_projinfo_gq_sum_query'; --存储过程名
  v_userExp exception;

  v_page_num  NUMBER default 0;
  v_page_size NUMBER;
  v_maxdate   varchar(8) default '';

  --=============================================================
  -- 业务处理过程
  --=============================================================
begin


  if I_PAGE_NUM is not null then
    v_page_num := I_PAGE_NUM;
  end if;
  
  
  select max(t.busi_date) into v_maxdate from thjs.tb_proj_charge_zz_sum t;
  
  
  open rt_cursor for
    select a.deptcode,--部门编号
           a.deptname,--部门名称
           a.deptmanacode,--部门负责人工号
           a.deptmananame,--部门负责人姓名
           a.DEPTMANAMOBILE,--部门负责人手机号
           GQZYCOUNT, --股权质押数量
           XZCFCOUNT, --行政处罚数量
           GDXXCOUNT --股东信息数量
      from thjs.tb_proj_charge_zz_sum a 
      where a.busi_date=v_maxdate 
      and (i_deptname is null or a.deptname like '%'||i_deptname||'%');

  commit;

  o_return_status := 0;

  -- =======================================================================================================================
  -- 错误处理
  -- =======================================================================================================================
exception

  WHEN OTHERS THEN
    o_return_status := -1;
    v_err_msg       := 'sqlcode:' || sqlcode || '||sqlerrm:||' ||
                       substr(sqlerrm, 1, 200);
    ROLLBACK;
    framedp.p_error_log('admin',
                        v_program_name,
                        o_return_status,
                        v_err_msg,
                        '',
                        '1',
                        v_err_msg,
                        o_return_status);
  
end;

Create or Replace PROCEDURE "THJS"."P_PROJLIST_BD_HGMAIL_Q" (O_CURSOR out types.cursorType) as

  ----------------------------------------------------------------------------------
  --版    权：GTJA
  --版    本：1.0.0
  --开发人员：CZC@GTJA
  --创建日期：20191119
  --模块编号：
  --模块名称：清单管理
  --功能名称：清单管理-限制清单变动合规邮件提醒查询
  ----------------------------------------------------------------------------------
  --==============================================================================
  --固定变量
  v_userexp exception; -- 用户定义错
  v_tradedate    varchar2(8); -- 任务执行时间(业务日期)
  v_exec_func_id integer default '0'; -- 任务id
  v_func_own     varchar2(20) default 'thjs'; -- 任务归属用户（schema）
  v_func_name    varchar2(2000) default 'P_PROJLIST_BD_HGMAIL_Q'; -- 任务名称(存储过程的名字)
  v_sqlerrm      varchar2(4000); -- 错误提示信息
  v_sqlcode      number; -- 错误代码
  v_sqlerrl      varchar2(4000); -- 错误行号
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  v_lastsend_time date;
  --=============================================================
  -- 业务处理过程
  --=============================================================

begin

  --获取变动邮件上次发生时间
  select to_date(max(l.send_time), 'YYYY-MM-DD HH24:MI:SS')
    into v_lastsend_time
    from dual
    left join thjs.tb_mail_log l
      on l.mail_code = 'XZQD007'
     and to_date(l.send_time, 'YYYY-MM-DD HH24:MI:SS') < sysdate - 2 / 24; --日志保存在前，设置2个小时的间隔

  --初始时，取当日变化的
  if v_lastsend_time is null then
  
    v_lastsend_time := to_date(to_char(sysdate, 'yyyy-MM-dd') || '00:00:00',
                               'YYYY-MM-DD HH24:MI:SS');
  end if;

  open O_CURSOR for
    select row_number() over(partition by null order by t.source_type, t.projid, t.stkcode) as rowno, --序号
           t.custname,
           t.projname,
           t.stkcode,
           t.stkname,
           t.projtype,
           t.fill_time,
           t.inout_type,
           t.source_type
      from (select t.projid,
                   t.custname, --客户名称
                   c.projname,
                   case
                     when t.stkcode is null or t.stkcode like 'A%' then --剔除A开头股票
                      null
                     else
                      t.windcode --20201026 邮件输出带市场的wind代码 t.stkcode
                   end as stkcode, --证券代码
                   case
                     when t.stkcode is null or t.stkcode like 'A%' then --剔除A开头股票
                      null
                     else
                      t.stkname
                   end as stkname, --股票简称
                   t.projtype, --业务类型
                   case
                     when t.cl_fill_time > v_lastsend_time then
                      to_char(t.cl_fill_time, 'YYYY-MM-DD HH24:MI:SS')
                     else
                      to_char(t.rl_fill_time, 'YYYY-MM-DD HH24:MI:SS')
                   end as fill_time, --入限制清单填报日期
                   case
                     when t.cl_fill_time > v_lastsend_time then
                      '新出单'
                     else
                      '新入单'
                   end as inout_type,
                   '母公司投行' as source_type
              from thjs.vw_projlist_stk t LEFT JOIN thjs.tb_ib_cust_info c on c.projid = t.projid
             where t.stkcode is not null
               and t.stkcode not like 'A%'
               and (t.rl_fill_time > v_lastsend_time or
                   t.cl_fill_time > v_lastsend_time) --筛选在上次发送时间之后入限制，出限制的数据
            union all
            select to_char(x.seqno),
                   x.companyname,
                   '',
                   x.windcode,
                   x.stkname,
                   x.projtype,
                   case
                     when x.in_date >= v_lastsend_time then
                      to_char(x.in_date, 'YYYY-MM-DD')
                     else
                      to_char(x.out_date, 'YYYY-MM-DD')
                   end as fill_time, --入限制清单填报日期                   
                   case
                     when x.in_date >= v_lastsend_time then
                      '新入单'
                     else
                      '新出单'
                   end as inout_type,
                   '香港国际' as source_type
              from (select x.seqno,
                           x.companyname,
                           x.windcode,
                           x.stkname,
                           x.projtype,
                           x.projlist_type,
                           x.projlist_status,
                           to_date(to_char(x.in_date, 'yyyy-mm-dd') ||
                                   ' 20:00:00',
                                   'yyyy-MM-dd HH24:MI:SS') as in_date, --香港国际只有日期，当日数据后续财汇采集到，默认为晚上8点
                           case
                             when to_char(x.out_date, 'yyyy') = '2099' then
                              null
                             else
                              to_date(to_char(x.out_date, 'yyyy-mm-dd') ||
                                      ' 20:00:00',
                                      'yyyy-MM-dd HH24:MI:SS')
                           end as out_date
                      from thjs.vw_projlist_xggj x) x
             where x.projlist_status in ('rl', 'cl')
               and ((x.in_date >= v_lastsend_time and x.in_date <= sysdate) or
                   (x.out_date >= v_lastsend_time and x.out_date <= sysdate)) --筛选在上次发送时间之后入限制，出限制的数据
            ) t;

  commit;

  ------------------------
exception
  -- 非预定义异常处理
  when v_userexp then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    hgman.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
