CREATE OR REPLACE PROCEDURE "THJS"."P_PROJLIST_CHECK_RESULT_S" (i_process_id in varchar2, --流程id
													i_projid        in varchar2, --项目id
                                                    i_batch_id      in varchar2, --清单填报批次id
                                                    i_inout_id      in varchar2, --出入单id
                                                    i_check_date    in varchar2, --自查日期
                                                    i_check_result  in varchar2, --自查结果 1-准确  2-已更正
                                                    i_remark        in varchar2, --备注说明
                                                    i_upload_id     in varchar2, --附件id
                                                    i_usercode      in varchar2, --操作员
                                                    o_return_msg    out varchar2,
                                                    o_return_code   out integer)
AS
  ----------------------------------------------------------------------------------
  --版    权：GTJA
  --版    本：1.0.0
  --开发人员：
  --创建日期：20260414
  --模块编号：
  --模块名称：清单自查流程 - 自查结果保存
  --功能名称：清单填报页面信息保存
  ----------------------------------------------------------------------------------

  --==============================================================================
  --固定变量
  v_userexp exception; -- 用户定义错
  v_tradedate    varchar2(8); -- 任务执行时间(业务日期)
  v_exec_func_id integer default '0'; -- 任务id
  v_func_own     varchar2(20) default 'thjs'; -- 任务归属用户（schema）
  v_func_name    varchar2(2000) default 'p_projlist_check_result_s'; -- 任务名称(存储过程的名字)
  v_sqlerrm      varchar2(4000); -- 错误提示信息
  v_sqlcode      number; -- 错误代码
  v_sqlerrl      varchar2(4000); -- 错误行号
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  --=============================================================
  -- 业务处理过程
  --=============================================================

BEGIN
	

  --刷新清单所有入出单记录检查结果
  merge into thjs.tb_projlist_check_result c
  using (select i_process_id as process_id,
  				i_projid as projid,
  				i_batch_id as batch_id,
  				i_inout_id as inout_id,
  				i_check_date as check_date,
  				i_check_result as check_result,
  				i_remark as remark,
  				i_upload_id as upload_id,
  				i_usercode as usercode
           from dual )i
  on (c.process_id = i.process_id and c.projid = i.projid and c.inout_id = i.inout_id)
  when matched then
    update set c.batch_id = i.batch_id,
    		   c.check_result = i.check_result, 
    		   c.remark = i.remark,
    		   c.upload_id = i.upload_id,
    		   c.update_user = i.usercode,
    		   c.update_time = sysdate
  when not matched then
    insert
      (process_id,
       projid,
       inout_id,
       batch_id,
       check_result,
       remark,
       upload_id,
       create_user,
       create_time,
       update_user,
       update_time)
    values
      (i.process_id,
       i.projid,
       i.inout_id,
       i.batch_id,
       i.check_result,
       i.remark,
       i.upload_id,
       i.usercode,
       sysdate,
       i.usercode,
       sysdate);
       
  commit;
END;

Create or Replace procedure "THJS"."P_PROJLIST_DIRECTOR_Q" (rt_cursor     out types.cursorType,
                                                       i_director    in varchar2,
                                                       i_usercode    in varchar2, --查询人
                                                       o_return_msg  out varchar2,
                                                       o_return_code out integer) is
  ----------------------------------------------------------------------------------
  --版    权：GTJA
  --版    本：1.0.0
  --开发人员：CZC@GTJA
  --创建日期：20191209
  --模块编号：
  --模块名称：投行清单管理-我管理的清单列表 项目负责人查询
  --功能名称：
  ----------------------------------------------------------------------------------
  --==============================================================================
  --固定变量
  v_userexp exception; -- 用户定义错
  v_tradedate    varchar2(8); -- 任务执行时间(业务日期)
  v_exec_func_id integer default '0'; -- 任务id
  v_func_own     varchar2(20) default 'thjs'; -- 任务归属用户（schema）
  v_func_name    varchar2(2000) default 'p_projlist_director_q'; -- 任务名称(存储过程的名字)
  v_sqlerrm      varchar2(4000); -- 错误提示信息
  v_sqlcode      number; -- 错误代码
  v_sqlerrl      varchar2(4000); -- 错误行号
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  --=============================================================
  -- 业务处理过程
  --=============================================================

begin

  v_tradedate := to_char(sysdate, 'yyyyMMdd');

  open rt_cursor for
    select distinct u.user_id,
                    u.user_name,
                    u.display_name,
                    e.fir_deptname as dept_name
      from BASIC_THJS.wb_user u
     inner join thjs.ib_v_finance_projmember p
        on p.workno = u.user_id
       and p.projrole = '项目负责人'
      left join thjs.ib_v_userinfo e
        on e.username = u.user_name
     where (i_director is null or instr(u.user_id, i_director) > 0 or
           instr(u.user_name, i_director) > 0 or
           instr(u.display_name, i_director) > 0)
       and u.user_name not like '%-loff'; --已离职的不展示

  commit;

  o_return_msg  := '执行成功';
  o_return_code := 0;

exception
  -- 非预定义异常处理
  when v_userexp then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    thjs.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
    -- 预定义异常处理
  when others then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    thjs.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
end;

