Create or Replace procedure "THJS"."P_PROJLIST_ERROR_MQ" (rt_cursor     out sys_refcursor, --返回游标结果集
                                                     i_khname      in varchar2, --客户名称
                                                     i_busidate    in varchar2, --日期                                                   
                                                     i_reason      in varchar2, --事由
                                                     i_status      in varchar2, --状态
                                                     i_username    in varchar2, --登录人
                                                     o_return_msg  out varchar2,
                                                     o_return_code out integer) is
  ----------------------------------------------------------------------------------
  --版    权：GTJA
  --版    本：1.0.0
  --开发人员：CZC@GTJA
  --创建日期：20190726
  --模块编号：
  --模块名称：清单报错 - 我管理的清单报错查询
  --功能名称：我管理的清单报错查询
  ----------------------------------------------------------------------------------
  --==============================================================================
  --固定变量
  v_userexp exception; -- 用户定义错
  v_tradedate    varchar2(8); -- 任务执行时间(业务日期)
  v_exec_func_id integer default '0'; -- 任务id
  v_func_own     varchar2(20) default 'thjs'; -- 任务归属用户（schema）
  v_func_name    varchar2(2000) default 'p_projlist_error_mq'; -- 任务名称(存储过程的名字)
  v_sqlerrm      varchar2(4000); -- 错误提示信息
  v_sqlcode      number; -- 错误代码
  v_sqlerrl      varchar2(4000); -- 错误行号
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  v_superuser integer default 0;
  --=============================================================
  -- 业务处理过程
  --=============================================================

begin

  v_tradedate := to_char(sysdate, 'yyyyMMdd');

  --判断是否超级用户
  select count(1)
    into v_superuser
    from table(thjs.splitstr('admin,zhangqilong', ',')) t
   where instr(',' || t.column_value || ',', ',' || i_username || ',') > 0;

  --暂展示所有报错申请
  open rt_cursor for
    select e.busi_date, --报错日期
           e.errorid, --报错记录id
           e.projid, --项目id
           m.custname, --客户名称
           e.error_reason, --报错事由
           e.error_content, --申请内容
           e.check_user, --审核人
           e.check_time, --审核时间
           e.check_result, --驳回反馈
           e.status, --状态：0-未提交 1-已提交 2-审核通过 3-驳回 4-已修正
           e.update_user, --最近更新人
           e.update_time, --最近更新时间
           e.create_user, --创建人/报错人
           e.create_time --创建时间
      from thjs.tb_projlist_error e
     inner join thjs.vw_projlist_main m
        on m.projid = e.projid
     where --((v_superuser > 0) or (e.create_user = i_username))
    --and 
     (i_khname is null or instr(m.custname, i_khname) > 0)
     and (i_busidate is null or e.busi_date = i_busidate)
     and (i_reason is null or instr(e.error_reason, i_reason) > 0)
     and (i_status is null or
     instr(',' || i_status || ',', ',' || e.status || ',') > 0)
     and e.status <> '0'; --不显示未提交的

  commit;

  o_return_msg  := '执行成功';
  o_return_code := 0;

exception
  -- 非预定义异常处理
  when v_userexp then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    thjs.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
    -- 预定义异常处理
  when others then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    thjs.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
end;

Create or Replace procedure "THJS"."P_PROJLIST_ERROR_Q" (rt_cursor     out sys_refcursor, --返回游标结果集
                                                    i_khname      in varchar2, --客户名称
                                                    i_busidate    in varchar2, --日期                                                   
                                                    i_reason      in varchar2, --事由
                                                    i_status      in varchar2, --状态
                                                    i_username    in varchar2, --登录人
                                                    o_return_msg  out varchar2,
                                                    o_return_code out integer) is
  ----------------------------------------------------------------------------------
  --版    权：GTJA
  --版    本：1.0.0
  --开发人员：CZC@GTJA
  --创建日期：20190726
  --模块编号：
