  --==============================================================================
  --固定变量
  v_userexp exception; -- 用户定义错
  v_tradedate    varchar2(8); -- 任务执行时间(业务日期)
  v_exec_func_id integer default '0'; -- 任务id
  v_func_own     varchar2(20) default 'thjs'; -- 任务归属用户（schema）
  v_func_name    varchar2(2000) default 'p_projlist_error_q'; -- 任务名称(存储过程的名字)
  v_sqlerrm      varchar2(4000); -- 错误提示信息
  v_sqlcode      number; -- 错误代码
  v_sqlerrl      varchar2(4000); -- 错误行号
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  v_superuser integer default 0;
  --=============================================================
  -- 业务处理过程
  --=============================================================

begin

  v_tradedate := to_char(sysdate, 'yyyyMMdd');

  --判断是否超级用户
  select count(1)
    into v_superuser
    from table(thjs.splitstr('admin,zhangqilong', ',')) t
   where instr(',' || t.column_value || ',', ',' || i_username || ',') > 0;

  open rt_cursor for
    select e.busi_date, --报错日期
           e.errorid, --报错记录id
           e.projid, --项目id
           m.custname, --客户名称
           e.error_reason, --报错事由
           e.error_content, --申请内容
           e.check_user, --审核人
           e.check_time, --审核时间
           e.check_result, --驳回反馈
           e.status, --状态：0-未提交 1-已提交 2-审核通过 3-驳回 4-已修正
           e.update_user, --最近更新人
           e.update_time, --最近更新时间
           e.create_user, --创建人
           e.create_time --创建时间
      from thjs.tb_projlist_error e
     inner join thjs.vw_projlist_main m
        on m.projid = e.projid
     where ((v_superuser > 0) or (e.create_user = i_username))
       and (i_khname is null or instr(m.custname, i_khname) > 0)
       and (i_busidate is null or e.busi_date = i_busidate)
       and (i_reason is null or instr(e.error_reason, i_reason) > 0)
       and (i_status is null or
           instr(',' || i_status || ',', ',' || e.status || ',') > 0);

  commit;

  o_return_msg  := '执行成功';
  o_return_code := 0;

exception
  -- 非预定义异常处理
  when v_userexp then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    thjs.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
    -- 预定义异常处理
  when others then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    thjs.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
end;

Create or Replace procedure "THJS"."P_PROJLIST_ERROR_S" (i_projid        in varchar2, --项目id
                                                    i_errorid       in varchar2, --清单报错id
                                                    i_error_reason  in varchar2, --入观察清单事由
                                                    i_error_content in varchar2, --入观察清单备注
                                                    i_submit_status in varchar2, --提交状态 0 保存/修改 1 提交  4
                                                    i_usercode      in varchar2, --操作员
                                                    o_return_msg    out varchar2,
                                                    o_return_code   out integer) is
  ----------------------------------------------------------------------------------
  --版    权：GTJA
  --版    本：1.0.0
  --开发人员：CZC@GTJA
  --创建日期：20190726
  --模块编号：
  --模块名称：清单管理 - 清单报错页面信息保存
  --功能名称：清单报错页面信息保存
  ----------------------------------------------------------------------------------
  --==============================================================================
  --固定变量
  v_userexp exception; -- 用户定义错
  v_tradedate    varchar2(8); -- 任务执行时间(业务日期)
  v_exec_func_id integer default '0'; -- 任务id
  v_func_own     varchar2(20) default 'thjs'; -- 任务归属用户（schema）
  v_func_name    varchar2(2000) default 'p_projlist_error_s'; -- 任务名称(存储过程的名字)
  v_sqlerrm      varchar2(4000); -- 错误提示信息
  v_sqlcode      number; -- 错误代码
  v_sqlerrl      varchar2(4000); -- 错误行号
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  v_count integer default 0;
  --=============================================================
  -- 业务处理过程
  --=============================================================

begin

  v_tradedate := to_char(sysdate, 'yyyyMMdd');

  select count(1)
    into v_count
    from thjs.tb_projlist_error e
   where e.errorid = i_errorid;

  if v_count = 0 then
  
    --新增
    insert into thjs.tb_projlist_error
      (busi_date,
       errorid,
       projid,
       error_reason,
       error_content,
       status,
       update_user,
       create_user)
    values
      (v_tradedate,
       sys_guid(),
       i_projid,
       i_error_reason,
       i_error_content,
       i_submit_status,
       i_usercode,
       i_usercode);
  else
  
    if i_submit_status = '4' then
      --清单修正
      update thjs.tb_projlist_error e
         set e.status      = i_submit_status,
             e.update_user = i_usercode,
             e.update_time = sysdate
       where e.errorid = i_errorid;
    else
    
      --清单修改/提交
    
      update thjs.tb_projlist_error e
         set e.error_reason  = i_error_reason,
             e.error_content = i_error_content,
             e.status        = i_submit_status,
             e.update_user   = i_usercode,
             e.update_time   = sysdate
       where e.errorid = i_errorid;
    
    end if;
  end if;

  commit;

  o_return_msg  := '执行成功';
  o_return_code := 0;

exception
  -- 非预定义异常处理
  when v_userexp then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    thjs.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
    -- 预定义异常处理
  when others then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    thjs.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
end;

Create or Replace procedure "THJS"."P_PROJLIST_ERROR_SQ" (rt_cursor     out sys_refcursor, --返回游标结果集
                                                     i_projid      in varchar2, --项目id
                                                     i_errorid     in varchar2, --报错记录id
                                                     i_username    in varchar2, --登录人
                                                     o_return_msg  out varchar2,
                                                     o_return_code out integer) is
  ----------------------------------------------------------------------------------
  --版    权：GTJA
  --版    本：1.0.0
  --开发人员：CZC@GTJA
  --创建日期：20190726
  --模块编号：
  --模块名称：清单报错 - 我的清单报错
  --功能名称：我的清单报错
  ----------------------------------------------------------------------------------
  --==============================================================================
  --固定变量
  v_userexp exception; -- 用户定义错
  v_tradedate    varchar2(8); -- 任务执行时间(业务日期)
  v_exec_func_id integer default '0'; -- 任务id
  v_func_own     varchar2(20) default 'thjs'; -- 任务归属用户（schema）
  v_func_name    varchar2(2000) default 'p_projlist_error_sq'; -- 任务名称(存储过程的名字)
  v_sqlerrm      varchar2(4000); -- 错误提示信息
  v_sqlcode      number; -- 错误代码
  v_sqlerrl      varchar2(4000); -- 错误行号
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  --=============================================================
  -- 业务处理过程
  --=============================================================

begin

  v_tradedate := to_char(sysdate, 'yyyyMMdd');

  if i_errorid is null and i_projid is not null then
  
    open rt_cursor for
      select m.projid, --项目id
             sys_guid() as errorid, --报错记录id
             m.custname, --客户名称
             '' as error_reason, --报错事由
             '' as error_content --申请内容
        from thjs.tb_projlist_main m
       where m.projid = i_projid;
  
  elsif i_errorid is not null then
  
    open rt_cursor for
      select e.projid, --项目id
             e.errorid, --报错记录id
             m.custname, --客户名称
             e.error_reason, --报错事由
             e.error_content --申请内容
        from thjs.tb_projlist_error e
       inner join thjs.tb_projlist_main m
          on m.projid = e.projid
       where m.projid = i_projid;
  
  else
    o_return_msg  := '未找到相关清单填报记录，请联系系统管理员！';
    o_return_code := -1;
  
  end if;

  commit;

  o_return_msg  := '执行成功';
  o_return_code := 0;

exception
  -- 非预定义异常处理
  when v_userexp then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    hgman.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
    -- 预定义异常处理
  when others then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    hgman.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
end;

Create or Replace procedure "THJS"."P_PROJLIST_FILE_Q" (rt_cursor     out sys_refcursor, --返回游标结果集
                                                   i_projid      in varchar2,
                                                   i_usercode    in varchar2, --查询用户
                                                   o_return_msg  out varchar2,
                                                   o_return_code out integer) is
  ----------------------------------------------------------------------------------
  --版    权：GTJA
  --版    本：1.0.0
  --开发人员：CZC@GTJA
  --创建日期：20240129
  --模块编号：
  --模块名称：清单管理 - 清单填报附件信息查询
  --功能名称：清单填报 - 附件补充填报
  ----------------------------------------------------------------------------------
  --==============================================================================
  --固定变量
  v_userexp exception; -- 用户定义错
  v_tradedate    varchar2(8); -- 任务执行时间(业务日期)
  v_exec_func_id integer default '0'; -- 任务id
  v_func_own     varchar2(20) default 'thjs'; -- 任务归属用户（schema）
  v_func_name    varchar2(2000) default 'p_projlist_file_q'; -- 任务名称(存储过程的名字)
  v_sqlerrm      varchar2(4000); -- 错误提示信息
  v_sqlcode      number; -- 错误代码
  v_sqlerrl      varchar2(4000); -- 错误行号
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  --=============================================================
  -- 业务处理过程
  --=============================================================

begin

  v_tradedate := to_char(sysdate, 'yyyyMMdd');

  insert into thjs.tb_exec_log
    (log_id, proc_name, proc_param, exec_time)
  values
    (thjs.tb_exec_log_id_seq.nextval,
     v_func_name,
     'i_projid:' || i_projid || ' -' || 'i_usercode:' || i_usercode,
     sysdate);
  commit;

  --返回项目清单填报所有附件信息

  open rt_cursor for
    select x.busidate, --业务日期
           x.projid, --项目ID（隐藏）
           x.batch_id, --批次ID（隐藏）
           '批次' || b.batch_num as batch_desc, --批次
           x.inout_id, --出入单ID（隐藏）      
           decode(x.inout_direct || x.inout_type,
                  'io',
                  '入观察期',
                  'oo',
                  '出观察期',
                  'il',
                  '入限制期',
                  'ol',
                  '出限制期',
                  'iq',
                  '入静默期',
                  'oq',
                  '出静默期') as inout_desc, --出入单阶段描述
           x.filepath, --文件路径（隐藏，下载使用）
           substr(x.filepath, instr(x.filepath, '/', -1) + 1) as file_name, --文件名称
           x.update_user, --操作人
           x.update_time --操作时间
      from thjs.tb_projlist_inout x
      left join (select row_number() over(partition by t.projid order by t.batch_time) as batch_num,
                        t.*
                   from (select min(t.create_time) as batch_time,
                                t.projid,
                                t.batch_id
                           from THJS.TB_PROJLIST_INOUT t
                          group by t.projid, t.batch_id) t) b
        on b.projid = x.projid
       and b.batch_id = x.batch_id
     where x.projid = i_projid
       and x.inout_status = '1'
       --and x.filepath is not null
     order by x.inout_date,decode(x.inout_type,'o',1,'l',2,'q',3);

  commit;

  o_return_msg  := '执行成功';
  o_return_code := 0;

exception
  -- 非预定义异常处理
  when v_userexp then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    thjs.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
    -- 预定义异常处理
  when others then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    thjs.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
end;

Create or Replace procedure "THJS"."P_PROJLIST_FILE_S" (i_projid      in varchar2, --项目id
                                                   i_batch_id    in varchar2, --清单填报批次ID
                                                   i_inout_id    in varchar2, --清单出入单ID
                                                   i_filepath    in varchar2, --清单附件
                                                   i_usercode    in varchar2, --操作员
                                                   o_return_msg  out varchar2,
                                                   o_return_code out integer) is
  ----------------------------------------------------------------------------------
  --版    权：GTJA
  --版    本：1.0.0
  --开发人员：CZC@GTJA
  --创建日期：20240129
  --模块编号：
  --模块名称：清单管理 - 清单附件信息补充上传
  --功能名称：清单填报页面信息保存
  ----------------------------------------------------------------------------------

  --==============================================================================
  --固定变量
  v_userexp exception; -- 用户定义错
  v_tradedate    varchar2(8); -- 任务执行时间(业务日期)
  v_exec_func_id integer default '0'; -- 任务id
  v_func_own     varchar2(20) default 'thjs'; -- 任务归属用户（schema）
  v_func_name    varchar2(2000) default 'p_projlist_file_s'; -- 任务名称(存储过程的名字)
  v_sqlerrm      varchar2(4000); -- 错误提示信息
  v_sqlcode      number; -- 错误代码
  v_sqlerrl      varchar2(4000); -- 错误行号
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  --=============================================================
  -- 业务处理过程
  --=============================================================

begin

  v_tradedate := to_char(sysdate, 'yyyyMMdd');

  insert into thjs.tb_exec_log
    (log_id, proc_name, proc_param, exec_time)
  values
    (thjs.tb_exec_log_id_seq.nextval,
     v_func_name,
     i_projid || ',' || i_batch_id || ',' || i_inout_id || ',' ||
     i_filepath || ',' || i_usercode,
     sysdate);
  commit;

  --非填报操作外，直接修改操作存历史，附件补充
  insert into thjs.tb_projlist_inout_his
    (busidate,
     batch_id,
     inout_id,
     projid,
     inout_type,
     inout_direct,
     fill_date,
     inout_date,
     inout_reason,
     inout_remark,
     filepath,
     inout_user,
     inout_status,
     update_user,
     update_time,
     create_time,
     debug_info,
     his_type,
     his_id,
     his_time)
    select t.busidate,
           t.batch_id,
           t.inout_id,
           t.projid,
           t.inout_type,
           t.inout_direct,
           t.fill_date,
           t.inout_date,
           t.inout_reason,
           t.inout_remark,
           t.filepath,
           t.inout_user,
           t.inout_status,
           t.update_user,
           t.update_time,
           t.create_time,
           t.debug_info,
           '附件补充' as his_type,
           sys_guid,
           sysdate
      from thjs.tb_projlist_inout t
     where t.projid = i_projid
       and t.batch_id = i_batch_id
       and t.inout_id = i_inout_id;

  update thjs.tb_projlist_inout t
     set t.filepath    = i_filepath,
         t.update_user = i_usercode,
         t.update_time = sysdate
   where t.projid = i_projid
     and t.batch_id = i_batch_id
     and t.inout_id = i_inout_id;

  commit;

  o_return_msg  := '执行成功';
  o_return_code := 0;

exception
  -- 非预定义异常处理
  when v_userexp then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    thjs.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
    -- 预定义异常处理
  when others then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    thjs.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
end;

Create or Replace procedure "THJS"."P_PROJLIST_INOUT_BATCH_Q" (rt_cursor     out sys_refcursor, --返回游标结果集
                                                          i_projid      in varchar2,
                                                          i_batch_num   in integer,
                                                          i_usercode    in varchar2, --查询用户
                                                          o_return_msg  out varchar2,
                                                          o_return_code out integer) is
  ----------------------------------------------------------------------------------
  --版    权：GTJA
  --版    本：1.0.0
  --开发人员：CZC@GTJA
  --创建日期：20210427
  --模块编号：
  --模块名称：清单管理 - 清单填报页清单批次信息查询
  --功能名称：清单填报页信息查询
  ----------------------------------------------------------------------------------
  --==============================================================================
  --固定变量
  v_userexp exception; -- 用户定义错
  v_tradedate    varchar2(8); -- 任务执行时间(业务日期)
  v_exec_func_id integer default '0'; -- 任务id
  v_func_own     varchar2(20) default 'thjs'; -- 任务归属用户（schema）
  v_func_name    varchar2(2000) default 'p_projlist_inout_batch_q'; -- 任务名称(存储过程的名字)
  v_sqlerrm      varchar2(4000); -- 错误提示信息
  v_sqlcode      number; -- 错误代码
  v_sqlerrl      varchar2(4000); -- 错误行号
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  v_batch_id varchar2(100);
  --=============================================================
  -- 业务处理过程
  --=============================================================

begin

  v_tradedate := to_char(sysdate, 'yyyyMMdd');

  select t.batch_id
    into v_batch_id
    from dual
    left join (select t.projid,
                      t.batch_id,
                      t.first_inout_time,
                      row_number() over(partition by t.projid order by t.first_inout_time) as batch_num
                 from (select t.projid,
                              t.batch_id,
                              min(t.create_time) as first_inout_time
                         from thjs.tb_projlist_inout t
                        where t.projid = i_projid
                        group by t.projid, t.batch_id) t) t
      on t.batch_num = i_batch_num;

  open rt_cursor for
    select c.projid, --项目编号
           c.projname, --项目名称           
           ro.inout_date as ro_inout_date, --入观察清单日期
           ro.inout_reason as ro_inout_reason, --入观察清单事由
           ro.fill_date as ro_report_date, --入观察清单填报日期
           ro.inout_remark as ro_inout_remark, --入观察清单备注
           ro.filepath as ro_filepath, --入观察清单附件
           co.inout_date as co_inout_date, --出观察清单日期
           co.fill_date as co_report_date, --出观察清单填报日期
           co.inout_reason as co_inout_reason, --出观察清单事由
           co.inout_remark as co_inout_remark, --出观察清单备注
           co.filepath as co_filepath, --出观察清单附件
           rl.inout_date as rl_inout_date, --入限制清单日期
           rl.fill_date as rl_report_date, --入限制清单填报日期
           rl.inout_reason as rl_inout_reason, --入限制清单事由
           rl.inout_remark as rl_inout_remark, --入限制清单备注
           rl.filepath as rl_filepath, --入限制清单附件
           cl.inout_date as cl_inout_date, --出限制清单日期
           cl.fill_date as cl_report_date, --出限制清单填报日期
           cl.inout_reason as cl_inout_reason, --出限制清单事由
           cl.inout_remark as cl_inout_remark, --出限制清单备注
           cl.filepath as cl_filepath, --出限制清单附件
           rq.inout_date as rq_inout_date, --入静默期日期
           rq.fill_date as rq_report_date, --入静默期填报日期
           rq.inout_reason as rq_inout_reason, --入静默期事由
           rq.inout_remark as rq_inout_remark, --入静默期备注
           rq.filepath as rq_filepath, --入静默期附件
           cq.inout_date as cq_inout_date, --出静默期日期
           cq.fill_date as cq_report_date, --出静默期填报日期
           cq.inout_reason as cq_inout_reason, --出静默期事由
           cq.inout_remark as cq_inout_remark, --出静默期备注
           cq.filepath as cq_filepath, --出静默期附件
           nvl(pb.projlist_status, '0') as projlist_status --清单状态
      from thjs.tb_ib_cust_info c
      left join thjs.vw_projlist_main p
        on p.projid = c.projid
      left join (select *
                   from thjs.tb_projlist_main
                 union all
                 select *
                   from thjs.tb_projlist_main_batch) pb
        on pb.projid = p.projid
       and pb.batch_id = v_batch_id
      left join thjs.tb_projlist_inout ro
        on ro.projid = p.projid
       and ro.batch_id = v_batch_id
       and ro.inout_id = pb.robserve_id
      left join thjs.tb_projlist_inout co
        on co.projid = p.projid
       and co.batch_id = v_batch_id
       and co.inout_id = pb.cobserve_id
      left join thjs.tb_projlist_inout rl
        on rl.projid = p.projid
       and rl.batch_id = v_batch_id
       and rl.inout_id = pb.rlimit_id
      left join thjs.tb_projlist_inout cl
        on cl.projid = p.projid
       and cl.batch_id = v_batch_id
       and cl.inout_id = pb.climit_id
      left join thjs.tb_projlist_inout rq
        on rq.projid = p.projid
       and rq.batch_id = v_batch_id
       and rq.inout_id = pb.rquiet_id
      left join thjs.tb_projlist_inout cq
        on cq.projid = p.projid
       and cq.batch_id = v_batch_id
       and cq.inout_id = pb.cquiet_id
     where c.projid = i_projid;

  commit;

  o_return_msg  := '执行成功';
  o_return_code := 0;

exception
  -- 非预定义异常处理
  when v_userexp then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    thjs.p_write_error_log(i_tradedate    => v_tradedate,
                           i_exec_func_id => v_exec_func_id,
                           i_func_own     => v_func_own,
                           i_func_name    => v_func_name,
                           i_occur_time   => sysdate,
                           i_sqlerrm      => v_sqlerrm,
                           i_sqlcode      => v_sqlcode,
                           i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
    -- 预定义异常处理
  when others then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    thjs.p_write_error_log(i_tradedate    => v_tradedate,
                           i_exec_func_id => v_exec_func_id,
                           i_func_own     => v_func_own,
                           i_func_name    => v_func_name,
                           i_occur_time   => sysdate,
                           i_sqlerrm      => v_sqlerrm,
                           i_sqlcode      => v_sqlcode,
                           i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
end;

Create or Replace procedure "THJS"."P_PROJLIST_INOUT_CHK_S" (i_projid in varchar2) is
  ----------------------------------------------------------------------------------
  --版    权：GTJA
  --版    本：1.0.0
  --开发人员：CZC@GTJA
  --创建日期：20190510
  --模块编号：
  --模块名称：清单管理 - 清单检查更新
  --功能名称：
  ----------------------------------------------------------------------------------

  --==============================================================================
  --固定变量
  v_userexp exception; -- 用户定义错
  v_tradedate    varchar2(8); -- 任务执行时间(业务日期)
  v_exec_func_id integer default '0'; -- 任务id
  v_func_own     varchar2(20) default 'thjs'; -- 任务归属用户（schema）
  v_func_name    varchar2(2000) default 'p_projlist_inout_chk_s'; -- 任务名称(存储过程的名字)
  v_sqlerrm      varchar2(4000); -- 错误提示信息
  v_sqlcode      number; -- 错误代码
  v_sqlerrl      varchar2(4000); -- 错误行号
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  --=============================================================
  -- 业务处理过程
  --=============================================================

begin

  --刷新清单所有入出单记录检查结果
  merge into thjs.tb_projlist_check c
  using (select i.busidate,
                i.projid,
                i.inout_id,
                case
                  when date_diff <= 0 then
                   '0'
                  else
                   '1'
                end as check_flag,
                case
                  when date_diff < 0 then
                   '早' || abs(i.date_diff) || '天'
                  when date_diff = 0 then
                   '准确'
                  else
                   '晚' || abs(i.date_diff) || '天'
                end as check_result
           from (select i.*,
                        to_date(i.fill_date, 'yyyy-MM-dd') -
                        to_date(i.inout_date, 'yyyy-MM-dd') as date_diff
                   from thjs.tb_projlist_inout i
                  where i.projid = i_projid) i) i
  on (c.projid = i.projid and c.inout_id = i.inout_id)
  when matched then
    update set c.check_flag = i.check_flag, c.check_result = i.check_result
  when not matched then
    insert
      (BUSIDATE,
       PROJID,
       INOUT_ID,
       CHECK_FLAG,
       CHECK_RESULT,
       CHECK_USER,
       CREATE_TIME)
    values
      (i.busidate,
       i.projid,
       i.inout_id,
       i.check_flag,
       i.check_result,
       'admin',
       sysdate);

  commit;

  /*insert into thjs.tb_test
    (id, text)
  values
    (95, o_return_msg || '-' || o_return_code);*/

exception
  -- 非预定义异常处理
  when v_userexp then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    thjs.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
    -- 预定义异常处理
  when others then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    thjs.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
end;

Create or Replace procedure "THJS"."P_PROJLIST_INOUT_COPY" (i_projid     in varchar2,
                                                       i_projid_new in varchar2) is
  ----------------------------------------------------------------------------------
  --版    权：GTJA
  --版    本：1.0.0
  --开发人员：CZC@GTJA
  --创建日期：20240730
  --模块编号：
  --模块名称：清单管理 - 清单填报复制
  --功能名称：
  ----------------------------------------------------------------------------------

  --==============================================================================
  --固定变量
  v_userexp exception; -- 用户定义错
  v_tradedate    varchar2(8); -- 任务执行时间(业务日期)
  v_exec_func_id integer default '0'; -- 任务id
  v_func_own     varchar2(20) default 'thjs'; -- 任务归属用户（schema）
  v_func_name    varchar2(2000) default 'p_projlist_inout_copy'; -- 任务名称(存储过程的名字)
  v_sqlerrm      varchar2(4000); -- 错误提示信息
  v_sqlcode      number; -- 错误代码
  v_sqlerrl      varchar2(4000); -- 错误行号
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  v_count     integer;
  v_count_new integer;
  v_batchid   varchar2(100);
  --=============================================================
  -- 业务处理过程
  --=============================================================

begin

  --判断，原项目存在清单，新项目未填报过清单
  select count(1)
    into v_count
    from thjs.tb_projlist_main m
   where m.projid = i_projid;

  select count(1)
    into v_count_new
    from thjs.tb_projlist_main m
   where m.projid = i_projid_new;

  if v_count = 1 and v_count_new = 0 then
  
    select sys_guid() into v_batchid from dual;
  
    insert into THJS.TB_PROJLIST_MAIN
      (BUSIDATE,
       PROJID,
       GTJAROLE,
       MULTISTK_ID,
       BATCH_ID,
       ROBSERVE_ID,
       COBSERVE_ID,
       RLIMIT_ID,
       CLIMIT_ID,
       RQUIET_ID,
       CQUIET_ID,
       CHECK_ID,
       PROJLIST_STATUS,
       UPDATE_USER,
       UPDATE_TIME,
       CREATE_USER,
       CREATE_TIME,
       SOURCE_FLAG)
      select t.busidate,
             i_projid_new, --t.projid,
             t.gtjarole,
             t.multistk_id,
             v_batchid, --t.batch_id,
             '', --t.robserve_id,
             '', --t.cobserve_id,
             '', --t.rlimit_id,
             '', --t.climit_id,
             '', --t.rquiet_id,
             '', --t.cquiet_id,
             t.check_id,
             t.projlist_status,
             t.update_user,
             t.update_time,
             t.create_user,
             t.create_time,
             t.source_flag
        from THJS.TB_PROJLIST_MAIN t
       where t.projid = i_projid;
  
    insert into THJS.TB_PROJLIST_inout
      (BUSIDATE,
       BATCH_ID,
       INOUT_ID,
       PROJID,
       INOUT_TYPE,
       INOUT_DIRECT,
       FILL_DATE,
       INOUT_DATE,
       INOUT_REASON,
       INOUT_REMARK,
       FILEPATH,
       INOUT_USER,
       INOUT_STATUS,
       UPDATE_USER,
       UPDATE_TIME,
       CREATE_TIME,
       DEBUG_INFO)
      select i.busidate,
             v_batchid, --i.batch_id,
             sys_guid(), --i.inout_id,
             i_projid_new, --i.projid,
             i.inout_type,
             i.inout_direct,
             i.fill_date,
             i.inout_date,
             i.inout_reason,
             i.inout_remark,
             i.filepath,
             i.inout_user,
             i.inout_status,
             i.update_user,
             i.update_time,
             i.create_time,
             i.debug_info
        from THJS.TB_PROJLIST_inout i
       where i.projid = i_projid;
  
    update THJS.TB_PROJLIST_MAIN t
       set (t.robserve_id,
            t.cobserve_id,
            t.rlimit_id,
            t.climit_id,
            t.rquiet_id,
            t.cquiet_id) =
           (select i.ro_id, i.co_id, i.rl_id, i.cl_id, i.rq_id, i.cq_id
              from thjs.vw_projlist_inout_row i
             where i.projid = t.projid
               and i.batch_id = t.batch_id)
     where t.projid = i_projid_new;
  
    commit;
  
  else
    raise v_userexp;
  end if;

  commit;

  /*insert into thjs.tb_test
    (id, text)
  values
    (95, o_return_msg || '-' || o_return_code);*/

exception
  -- 非预定义异常处理
  when v_userexp then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    hgman.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
    -- 预定义异常处理
  when others then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    hgman.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
end;

Create or Replace procedure "THJS"."P_PROJLIST_INOUT_D" (i_projid      in varchar2, --项目id
                                                    i_usercode    in varchar2, --操作员
                                                    o_return_msg  out varchar2,
                                                    o_return_code out integer) is
  ----------------------------------------------------------------------------------
  --版    权：GTJA
  --版    本：1.0.0
  --开发人员：CZC@GTJA
  --创建日期：20190718
  --模块编号：
  --模块名称：清单管理 - 清单填报页面信息删除
  --功能名称：清单填报页面信息删除
  ----------------------------------------------------------------------------------
  --==============================================================================
  --固定变量
  v_userexp exception; -- 用户定义错
  v_tradedate    varchar2(8); -- 任务执行时间(业务日期)
  v_exec_func_id integer default '0'; -- 任务id
  v_func_own     varchar2(20) default 'thjs'; -- 任务归属用户（schema）
  v_func_name    varchar2(2000) default 'p_projlist_inout_d'; -- 任务名称(存储过程的名字)
  v_sqlerrm      varchar2(4000); -- 错误提示信息
  v_sqlcode      number; -- 错误代码
  v_sqlerrl      varchar2(4000); -- 错误行号
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  v_filldate             varchar2(10);
  v_projlist_status      varchar2(20);
  v_inout_id             varchar2(80); --出入单iD
  v_inout_id_next        varchar2(80); --出单时同时入单id
  v_projlist_status_next varchar2(20); --出入单同时入单状态
  --=============================================================
  -- 业务处理过程
  --=============================================================

begin

  delete from thjs.tb_projlist_main t where t.projid = i_projid;
  delete from thjs.tb_projlist_inout t where t.projid = i_projid;
  delete from thjs.tb_projlist_multistk t where t.projid = i_projid;
  delete from thjs.tb_projlist_emergency t where t.projid = i_projid;
  delete from thjs.tb_projlist_check t where t.projid = i_projid;
  delete from thjs.tb_projlist_error t where t.projid = i_projid;

  commit;

  o_return_msg  := '执行成功';
  o_return_code := 0;

exception
  -- 非预定义异常处理
  when v_userexp then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    thjs.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
    -- 预定义异常处理
  when others then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    thjs.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
end;

Create or Replace PROCEDURE "THJS"."P_PROJLIST_INOUT_FIX" (i_tradedate in char)
/*==============================================================================
  版 本    : 1.0.0
  创建人   : czc
  模块编号 : 0
  日 期    : 2024-07-02
  功能描述 : 合规数据平台 清单管理每日修正任务
  ==============================================================================*/
 as
  v_sqlcode        integer default 0;
  v_sqlstate       char(5) default '';
  v_err_msg        varchar2(128) default '';
  v_function_id    integer default 0; --定义存储过程模块编号
  v_error_line_num integer default 0; --错误行号
  v_function_desc  varchar2(50) default '清单管理每日修正任务'; --功能描述
  v_program_name   char(40) default 'p_projlist_inout_fix'; --程序名
  v_pr_task_id     number default 0; --任务标示
  -- =======================================================================================================================
  -- 定义业务变量
  -- =======================================================================================================================
  -- =======================================================================================================================
  -- 业务开始
  -- =======================================================================================================================
begin

  --自动阶段修正-20240702新增;thjs.p_projlist_inout_s2
  --1、出观察转限制；2、出观察转静默；3、出限制+价格利率确定；4、入静默

  --出观察转限制有误
  insert into thjs.tb_projlist_inout_forfix
    (busidate,
     batch_id,
     inout_id,
     projid,
     inout_type,
     inout_direct,
     fill_date,
     inout_date,
     inout_reason,
     inout_remark,
     filepath,
     inout_user,
     inout_status,
     update_user,
     update_time,
     create_time,
     projcode,
     projname,
     debug_info,
     error_info,
     fix_flag)
    select t.busidate,
           t.batch_id,
           t.inout_id,
           t.projid,
           t.inout_type,
           t.inout_direct,
           t.fill_date,
           t.inout_date,
           t.inout_reason,
           t.inout_remark,
           t.filepath,
           t.inout_user,
           t.inout_status,
           t.update_user,
           t.update_time,
           t.create_time,
           c.projcode,
           c.projname,
           t.debug_info,
           '出观察转限制有误' as error_info,
           '0' as fix_flag
      from thjs.tb_projlist_inout t
      left join thjs.tb_ib_cust_info c
        on c.projid = t.projid
     where t.inout_type = 'o'
       and t.inout_direct = 'o'
       and t.inout_reason = '3'
       and not exists (select *
              from thjs.tb_projlist_inout n
             where n.projid = t.projid
               and n.batch_id = t.batch_id
               and n.inout_type = 'l'
               and n.inout_direct = 'i')
       and exists
     (select *
              from thjs.tb_projlist_main m
              left join thjs.tb_projlist_main_batch b
                on b.projid = m.projid
             where m.projid = t.projid
               and ((m.batch_id = t.batch_id and m.cobserve_id = t.inout_id) or
                   (b.batch_id = t.batch_id and b.cobserve_id = t.inout_id)))
       and not exists (select *
              from thjs.tb_projlist_inout_forfix f
             where f.inout_id = t.inout_id);

  --出观察转静默有误
  insert into thjs.tb_projlist_inout_forfix
    (busidate,
     batch_id,
     inout_id,
     projid,
     inout_type,
     inout_direct,
     fill_date,
     inout_date,
     inout_reason,
     inout_remark,
     filepath,
     inout_user,
     inout_status,
     update_user,
     update_time,
     create_time,
     projcode,
     projname,
     debug_info,
     error_info,
     fix_flag)
    select t.busidate,
           t.batch_id,
           t.inout_id,
           t.projid,
           t.inout_type,
           t.inout_direct,
           t.fill_date,
           t.inout_date,
           t.inout_reason,
           t.inout_remark,
           t.filepath,
           t.inout_user,
           t.inout_status,
           t.update_user,
           t.update_time,
           t.create_time,
           c.projcode,
           c.projname,
           t.debug_info,
           '出观察转静默有误' as error_info,
           '0' as fix_flag
      from thjs.tb_projlist_inout t
      left join thjs.tb_ib_cust_info c
        on c.projid = t.projid
     where t.inout_type = 'o'
       and t.inout_direct = 'o'
       and t.inout_reason = '4'
       and not exists (select *
              from thjs.tb_projlist_inout n
             where n.projid = t.projid
               and n.batch_id = t.batch_id
               and n.inout_type = 'q'
               and n.inout_direct = 'i')
       and exists
     (select *
              from thjs.tb_projlist_main m
              left join thjs.tb_projlist_main_batch b
                on b.projid = m.projid
             where m.projid = t.projid
               and ((m.batch_id = t.batch_id and m.cobserve_id = t.inout_id) or
                   (b.batch_id = t.batch_id and b.cobserve_id = t.inout_id)))
       and not exists (select *
              from thjs.tb_projlist_inout_forfix f
             where f.inout_id = t.inout_id);

  --出限制+价格利率确定入静默有误
  insert into thjs.tb_projlist_inout_forfix
    (busidate,
     batch_id,
     inout_id,
     projid,
     inout_type,
     inout_direct,
     fill_date,
     inout_date,
     inout_reason,
     inout_remark,
     filepath,
     inout_user,
     inout_status,
     update_user,
     update_time,
     create_time,
     projcode,
     projname,
     debug_info,
     error_info,
     fix_flag)
    select t.busidate,
           t.batch_id,
           t.inout_id,
           t.projid,
           t.inout_type,
           t.inout_direct,
           t.fill_date,
           t.inout_date,
           t.inout_reason,
           t.inout_remark,
           t.filepath,
           t.inout_user,
           t.inout_status,
           t.update_user,
           t.update_time,
           t.create_time,
           c.projcode,
           c.projname,
           t.debug_info,
           '出限制+价格利率确定入静默有误' as error_info,
           '0' as fix_flag
      from thjs.tb_projlist_inout t
      left join thjs.tb_ib_cust_info c
        on c.projid = t.projid
     where t.inout_type = 'l'
       and t.inout_direct = 'o'
       and t.inout_reason = '1'
       and not exists (select *
              from thjs.tb_projlist_inout n
             where n.projid = t.projid
               and n.batch_id = t.batch_id
               and n.inout_type = 'q'
               and n.inout_direct = 'i')
       and exists
     (select *
              from thjs.tb_projlist_main m
              left join thjs.tb_projlist_main_batch b
                on b.projid = m.projid
             where m.projid = t.projid
               and ((m.batch_id = t.batch_id and m.climit_id = t.inout_id) or
                   (b.batch_id = t.batch_id and b.climit_id = t.inout_id)))
       and not exists (select *
              from thjs.tb_projlist_inout_forfix f
             where f.inout_id = t.inout_id);

  --自动出静默有误
  insert into thjs.tb_projlist_inout_forfix
    (busidate,
     batch_id,
     inout_id,
     projid,
     inout_type,
     inout_direct,
     fill_date,
     inout_date,
     inout_reason,
     inout_remark,
     filepath,
     inout_user,
     inout_status,
     update_user,
     update_time,
     create_time,
     projcode,
     projname,
     debug_info,
     error_info,
     fix_flag)
    select t.busidate,
           t.batch_id,
           t.inout_id,
           t.projid,
           t.inout_type,
           t.inout_direct,
           t.fill_date,
           t.inout_date,
           t.inout_reason,
           t.inout_remark,
           t.filepath,
           t.inout_user,
           t.inout_status,
           t.update_user,
           t.update_time,
           t.create_time,
           c.projcode,
           c.projname,
           t.debug_info,
           '自动出静默有误' as error_info,
           '0' as fix_flag
      from thjs.tb_projlist_inout t
      left join thjs.tb_ib_cust_info c
        on c.projid = t.projid
     where t.inout_type = 'q'
       and t.inout_direct = 'i'
       and not exists (select *
              from thjs.tb_projlist_inout n
             where n.projid = t.projid
               and n.batch_id = t.batch_id
               and n.inout_type = 'q'
               and n.inout_direct = 'o')
       and exists
     (select *
              from thjs.tb_projlist_main m
              left join thjs.tb_projlist_main_batch b
                on b.projid = m.projid
             where m.projid = t.projid
               and ((m.batch_id = t.batch_id and m.rquiet_id = t.inout_id) or
                   (b.batch_id = t.batch_id and b.rquiet_id = t.inout_id)))
       and not exists (select *
              from thjs.tb_projlist_inout_forfix f
             where f.inout_id = t.inout_id);
  commit;

  --自动修正处理
  /*for inout in (select *
                  from thjs.tb_projlist_inout_forfix f
                 where f.fix_flag = '0') loop
  
  if inout.error_info='出观察转限制有误' then
    
  
  end if;
  
  end loop;*/

  ------------------------
exception
  when others then
    v_sqlcode := -1 * sqlcode;
    v_err_msg := sqlerrm;
    rollback;
    --记录错误日志
    kingstar.pr_audit_write_errlog(v_pr_task_id, -- 任务标识
                                   0, -- 单位编号
                                   i_tradedate, -- 业务日期
                                   v_function_id, -- 功能标识
                                   v_program_name, -- 程序名
                                   v_error_line_num, -- 程序行号
                                   v_err_msg, -- 错误信息
                                   v_sqlcode, -- SQLCODE
                                   v_sqlstate -- SQLSTATE
                                   );
    commit;
    raise;
end;

CREATE OR REPLACE PROCEDURE "THJS"."P_PROJLIST_INOUT_Q" (rt_cursor     out sys_refcursor, --返回游标结果集
                                                    i_projid      in varchar2,
                                                    i_usercode    in varchar2, --查询用户
                                                    o_return_msg  out varchar2,
                                                    o_return_code out integer)
AS
  ----------------------------------------------------------------------------------
  --版    权：GTJA
  --版    本：1.0.0
  --开发人员：CZC@GTJA
  --创建日期：20190426
  --模块编号：
  --模块名称：清单管理 - 清单填报页信息查询
  --功能名称：清单填报页信息查询
  ----------------------------------------------------------------------------------
  --==============================================================================
  --固定变量
  v_userexp exception; -- 用户定义错
  v_tradedate    varchar2(8); -- 任务执行时间(业务日期)
  v_exec_func_id integer default '0'; -- 任务id
  v_func_own     varchar2(20) default 'thjs'; -- 任务归属用户（schema）
  v_func_name    varchar2(2000) default 'p_projlist_inout_q'; -- 任务名称(存储过程的名字)
  v_sqlerrm      varchar2(4000); -- 错误提示信息
  v_sqlcode      number; -- 错误代码
  v_sqlerrl      varchar2(4000); -- 错误行号
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量

  v_role_flag varchar2(200); --角色数据权限标识
  v_po_flag   varchar2(2); --观察清单数据权限标识
  v_pl_flag   varchar2(2); --限制清单数据权限标识
  --=============================================================
  -- 业务处理过程
  --=============================================================

BEGIN

  v_tradedate := to_char(sysdate, 'yyyyMMdd');
  
  insert into thjs.tb_exec_log
    (log_id, proc_name, proc_param, exec_time)
  values
    (thjs.tb_exec_log_id_seq.nextval,
     'p_projlist_inout_q',
     'i_projid:' || i_projid || ' -' || 'i_usercode:' || i_usercode,
     sysdate);
  commit;

  --管理人员 角色部分数据权限实现
  --“投行管理员”角色具有全部数据权限           
  --“观察清单管理角色”仅具有观察阶段数据权限
  --“限制清单管理角色”仅具有限制阶段数据权限
  --权限标识区分：ALL，PO，PL  

  select to_char(wm_concat(decode(r.role_name,
                                  'admin',
                                  'ALL',
                                  'admin-th',
                                  'ALL',
                                  'projlist_o',
                                  'PO',
                                  'projlist_l',
                                  'PL',
                                  ''))) as role_flag
    into v_role_flag
    from basic_thjs.wb_user u
    left join basic_thjs.wb_user_role ur
      on ur.user_id = u.user_id
    left join basic_thjs.wb_role r
      on r.role_id = ur.role_id
   where u.user_name = i_usercode;

  v_po_flag := case
                 when instr(v_role_flag, 'ALL') > 0 or
                      instr(v_role_flag, 'PO') > 0 then
                  '1'
                 else
                  '0'
               end;

  v_pl_flag := case
                 when instr(v_role_flag, 'ALL') > 0 or
                      instr(v_role_flag, 'PL') > 0 then
                  '1'
                 else
                  '0'
               end;

  open rt_cursor for
    select c.projid, --项目编号
           c.projname, --项目名称
           c.projtype, --项目类型
           c.projcode,
           c.khxycode as custid, --客户编号
           c.khname   as custname, --客户名称
           --c.stockcode as stkcode, --证券代码
           c.windcode as stkcode,
           c.stockname as stkname, --证券名称
           p.gtjarole, --我司角色
           p.batch_id, --批次ID
           case
             when nvl(p.projlist_status, '0') = '0' then
              to_char(sysdate, 'YYYYMMDD') --未出单状态默认日期
             else
              ro.inout_date
           end as ro_inout_date, --入观察清单日期
           case
             when nvl(p.projlist_status, '0') = '0' then
              '0' --未出单状态默认选中
             else
              ro.inout_reason
           end as ro_inout_reason, --入观察清单事由
           ro.fill_date as ro_report_date, --入观察清单填报日期
           ro.inout_remark as ro_inout_remark, --入观察清单备注
           ro.filepath as ro_filepath, --入观察清单附件
           co.inout_date as co_inout_date, --出观察清单日期
           co.fill_date as co_report_date, --出观察清单填报日期
           co.inout_reason as co_inout_reason, --出观察清单事由
           co.inout_remark as co_inout_remark, --出观察清单备注
           co.filepath as co_filepath, --出观察清单附件
           rl.inout_date as rl_inout_date, --入限制清单日期
           rl.fill_date as rl_report_date, --入限制清单填报日期
           rl.inout_reason as rl_inout_reason, --入限制清单事由
           rl.inout_remark as rl_inout_remark, --入限制清单备注
           rl.filepath as rl_filepath, --入限制清单附件
           cl.inout_date as cl_inout_date, --出限制清单日期
           cl.fill_date as cl_report_date, --出限制清单填报日期
           cl.inout_reason as cl_inout_reason, --出限制清单事由
           cl.inout_remark as cl_inout_remark, --出限制清单备注
           cl.filepath as cl_filepath, --出限制清单附件
           rq.inout_date as rq_inout_date, --入静默期日期
           rq.fill_date as rq_report_date, --入静默期填报日期
           rq.inout_reason as rq_inout_reason, --入静默期事由
           rq.inout_remark as rq_inout_remark, --入静默期备注
           rq.filepath as rq_filepath, --入静默期附件
           cq.inout_date as cq_inout_date, --出静默期日期
           cq.fill_date as cq_report_date, --出静默期填报日期
           cq.inout_reason as cq_inout_reason, --出静默期事由
           cq.inout_remark as cq_inout_remark, --出静默期备注
           cq.filepath as cq_filepath, --出静默期附件
           nvl(p.projlist_status, '0') as projlist_status, --清单状态
           b.batch_count --清单填报批次数量
      from thjs.tb_ib_cust_info c
      left join thjs.vw_projlist_main_all p
        on p.projid = c.projid
      left join thjs.tb_projlist_inout ro
        on ro.projid = p.projid
       and ro.inout_id = p.robserve_id
      left join thjs.tb_projlist_inout co
        on co.projid = p.projid
       and co.inout_id = p.cobserve_id
      left join thjs.tb_projlist_inout rl
        on rl.projid = p.projid
       and rl.inout_id = p.rlimit_id
      left join thjs.tb_projlist_inout cl
        on cl.projid = p.projid
       and cl.inout_id = p.climit_id
      left join thjs.tb_projlist_inout rq
        on rq.projid = p.projid
       and rq.inout_id = p.rquiet_id
      left join thjs.tb_projlist_inout cq
        on cq.projid = p.projid
       and cq.inout_id = p.cquiet_id
      left join (select t.projid, count(distinct t.batch_id) as batch_count
                   from thjs.tb_projlist_inout t
                  group by t.projid) b
        on b.projid = c.projid
     where c.projid = i_projid;

  commit;

  o_return_msg  := '执行成功';
  o_return_code := 0;

exception
  -- 非预定义异常处理
  when v_userexp then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    thjs.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
    -- 预定义异常处理
  when others then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    thjs.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
end;

Create or Replace procedure "THJS"."P_PROJLIST_INOUT_S" (i_projid          in varchar2, --项目id
                                                    i_batch_id        in varchar2, --清单填报批次ID：新增批次默认为空，否则传入当前批次ID
                                                    i_ro_inout_date   in varchar2, --入观察清单日期
                                                    i_ro_inout_reason in varchar2, --入观察清单事由
                                                    i_ro_inout_remark in varchar2, --入观察清单备注
                                                    i_ro_filepath     in varchar2, --入观察清单附件
                                                    i_co_inout_date   in varchar2, --出观察清单日期
                                                    i_co_inout_reason in varchar2, --出观察清单事由
                                                    i_co_inout_remark in varchar2, --出观察清单备注
                                                    i_co_filepath     in varchar2, --出观察清单附件
                                                    i_rl_inout_date   in varchar2, --入限制清单日期
                                                    i_rl_inout_reason in varchar2, --入限制清单事由
                                                    i_rl_inout_remark in varchar2, --入限制清单备注
                                                    i_rl_filepath     in varchar2, --入限制清单附件
                                                    i_cl_inout_date   in varchar2, --出限制清单日期
                                                    i_cl_inout_reason in varchar2, --出限制清单事由
                                                    i_cl_inout_remark in varchar2, --出限制清单备注
                                                    i_cl_filepath     in varchar2, --出限制清单附件
                                                    i_rq_inout_date   in varchar2, --入静默期日期
                                                    i_rq_inout_reason in varchar2, --入静默期事由
                                                    i_rq_inout_remark in varchar2, --入静默期备注
                                                    i_rq_filepath     in varchar2, --入静默期附件
                                                    i_cq_inout_date   in varchar2, --出静默期日期
                                                    i_cq_inout_reason in varchar2, --出静默期事由
                                                    i_cq_inout_remark in varchar2, --出静默期备注
                                                    i_cq_filepath     in varchar2, --出静默期附件
                                                    i_projlist_status in varchar2, --清单状态
                                                    i_submit_status   in varchar2, --提交状态 0 草稿 1 提交  2 修正
                                                    i_usercode        in varchar2, --操作员
                                                    o_return_msg      out varchar2,
                                                    o_return_code     out integer) is
  ----------------------------------------------------------------------------------
  --版    权：GTJA
  --版    本：1.0.0
  --开发人员：CZC@GTJA
  --创建日期：20190510
  --模块编号：
  --模块名称：清单管理 - 清单填报页面信息保存
  --功能名称：清单填报页面信息保存
  ----------------------------------------------------------------------------------

  --==============================================================================
  --固定变量
  v_userexp exception; -- 用户定义错
  v_tradedate    varchar2(8); -- 任务执行时间(业务日期)
  v_exec_func_id integer default '0'; -- 任务id
  v_func_own     varchar2(20) default 'thjs'; -- 任务归属用户（schema）
  v_func_name    varchar2(2000) default 'p_projlist_inout_s'; -- 任务名称(存储过程的名字)
  v_sqlerrm      varchar2(4000); -- 错误提示信息
  v_sqlcode      number; -- 错误代码
  v_sqlerrl      varchar2(4000); -- 错误行号
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  v_filldate              varchar2(10);
  v_projlist_status       varchar2(20);
  v_inout_id              varchar2(80); --出入单iD
  v_inout_id_next         varchar2(80); --出单时同时入单id
  v_inout_id_third        varchar2(80); --出单时同时入单后出的id
  v_projlist_status_next  varchar2(20); --出入单同时入单状态
  v_projlist_status_third varchar2(20);
  v_projlist_status_four  varchar2(20);
  v_proj_type             varchar2(50); --项目类型

  p_ro_inout_date varchar2(10);
  p_co_inout_date varchar2(10);
  p_rl_inout_date varchar2(10);
  p_cl_inout_date varchar2(10);
  p_rq_inout_date varchar2(10);
  p_cq_inout_date varchar2(10);

  v_ro_inout_date varchar2(10);
  v_co_inout_date varchar2(10);
  v_rl_inout_date varchar2(10);
  v_cl_inout_date varchar2(10);
  v_rq_inout_date varchar2(10);
  v_cq_inout_date varchar2(10);

  v_ro_id varchar2(80);
  v_co_id varchar2(80);
  v_rl_id varchar2(80);
  v_cl_id varchar2(80);
  v_rq_id varchar2(80);
  v_cq_id varchar2(80);

  v_batch_id varchar2(80); --批次ID

  v_co_filepath varchar2(1000);
  --=============================================================
  -- 业务处理过程
  --=============================================================

begin

  v_tradedate := to_char(sysdate, 'yyyyMMdd');
  v_filldate  := to_char(sysdate, 'yyyy-MM-dd');

  insert into thjs.tb_exec_log
    (log_id, proc_name, proc_param, exec_time)
  values
    (thjs.tb_exec_log_id_seq.nextval,
     'p_projlist_inout_s',
     i_projid || ',' || i_batch_id || ',' || i_ro_inout_date || ',' ||
     i_ro_inout_reason || ',' || i_ro_inout_remark || ',' || i_ro_filepath || ',' ||
     i_co_inout_date || ',' || i_co_inout_reason || ',' ||
     i_co_inout_remark || ',' || i_co_filepath || ',' || i_rl_inout_date || ',' ||
     i_rl_inout_reason || ',' || i_rl_inout_remark || ',' || i_rl_filepath || ',' ||
     i_cl_inout_date || ',' || i_cl_inout_reason || ',' ||
     i_cl_inout_remark || ',' || i_cl_filepath || ',' || i_rq_inout_date || ',' ||
     i_rq_inout_reason || ',' || i_rq_inout_remark || ',' || i_rq_filepath || ',' ||
     i_cq_inout_date || ',' || i_cq_inout_reason || ',' ||
     i_cq_inout_remark || ',' || i_cq_filepath || ',' || i_projlist_status || ',' ||
     i_submit_status || ',' || i_usercode,
     sysdate);
  commit;

  v_co_filepath := i_co_filepath;
  --测试代码
  /*if i_projid='D1D9967EE60F4DAD9A4AB95000CDE228' and i_co_filepath is not null then
    v_co_filepath:=substr(i_co_filepath,instr(i_co_filepath,'/',-1,1))||'undefined';   
  end if;*/
  --=======================================================

  select nvl(m.projlist_status, '0')
    into v_projlist_status
    from dual
    left join thjs.tb_projlist_main m
      on m.projid = i_projid;

  --项目类型
  select m.projtype
    into v_proj_type
    from thjs.tb_ib_cust_info m
   where m.projid = i_projid;

  select t.ro_inout_date,
         t.co_inout_date,
         t.rl_inout_date,
         t.cl_inout_date,
         nvl(t.rq_inout_date, i_rq_inout_date),
         nvl(t.cq_inout_date, i_cq_inout_date)
    into p_ro_inout_date,
         p_co_inout_date,
         p_rl_inout_date,
         p_cl_inout_date,
         p_rq_inout_date,
         p_cq_inout_date
    from dual
    left join thjs.vw_projlist_main_inout t
      on t.projid = i_projid
     and t.batch_id = i_batch_id;

  --=========有效性验证========================================
  --批次处理：为空时，表示新批次，验证清单状态（必须为出单状态）
  if i_batch_id is null and
     v_projlist_status not in ('0', 'co', 'cl', 'cq') then
    o_return_msg  := '清单非出单状态，无法填报新批次！';
    o_return_code := -1;
    return;
  end if;

  --判断清单状态是否匹配，如不匹配返回错误（已有其他提交）
  if i_projlist_status <> v_projlist_status then
    o_return_msg  := '清单状态不匹配，请重新打开页面填报！';
    o_return_code := -1;
    return;
  end if;

  if i_co_inout_date is not null and i_co_inout_date < p_ro_inout_date then
    o_return_msg  := '出观察清单日期不应早于入观察清单日期！';
    o_return_code := -1;
    return;
  end if;

  if i_cl_inout_date is not null and i_cl_inout_date < p_rl_inout_date then
    o_return_msg  := '出限制清单日期不应早于入限制清单日期！';
    o_return_code := -1;
    return;
  end if;

  if i_cq_inout_date is not null and i_cq_inout_date < p_rq_inout_date then
    o_return_msg  := '出静默期日期不应早于入静默期日期！';
    o_return_code := -1;
    return;
  end if;

  if i_projlist_status = 'ro' and i_co_inout_reason = '4' and
     (i_rq_inout_date is null or i_cq_inout_date is null) then
    o_return_msg  := '出观察转静默期有误，请联系系统管理员！';
    o_return_code := -1;
    return;
  end if;

  if i_projlist_status = 'rl' and i_cl_inout_reason = '1' and
     (i_rq_inout_date is null or i_cq_inout_date is null) then
    o_return_msg  := '出限制转静默期有误，请联系系统管理员！';
    o_return_code := -1;
    return;
  end if;

  if (i_ro_filepath is not null and i_ro_filepath like '%undefined') or
     (v_co_filepath is not null and v_co_filepath like '%undefined') or
     (i_rl_filepath is not null and i_rl_filepath like '%undefined') or
     (i_cl_filepath is not null and i_cl_filepath like '%undefined') or
     (i_rq_filepath is not null and i_rq_filepath like '%undefined') or
     (i_cq_filepath is not null and i_cq_filepath like '%undefined') then
    o_return_msg  := '附件上传有误，请联系系统管理员！';
    o_return_code := -1;
    return;
  end if;

  --===========================================================
  --为防止日期控件在不同浏览器中传入格式不同，统一重新截止日期格式为YYYY-MM-DD
  v_ro_inout_date := to_char(to_date(regexp_replace(i_ro_inout_date,
                                                    '[^0-9]',
                                                    ''),
                                     'YYYYMMDD'),
                             'YYYY-MM-DD');
  v_co_inout_date := to_char(to_date(regexp_replace(i_co_inout_date,
                                                    '[^0-9]',
                                                    ''),
                                     'YYYYMMDD'),
                             'YYYY-MM-DD');
  v_rl_inout_date := to_char(to_date(regexp_replace(i_rl_inout_date,
                                                    '[^0-9]',
                                                    ''),
                                     'YYYYMMDD'),
                             'YYYY-MM-DD');
  v_cl_inout_date := to_char(to_date(regexp_replace(i_cl_inout_date,
                                                    '[^0-9]',
                                                    ''),
                                     'YYYYMMDD'),
                             'YYYY-MM-DD');
  v_rq_inout_date := to_char(to_date(regexp_replace(i_rq_inout_date,
                                                    '[^0-9]',
                                                    ''),
                                     'YYYYMMDD'),
                             'YYYY-MM-DD');
  v_cq_inout_date := to_char(to_date(regexp_replace(i_cq_inout_date,
                                                    '[^0-9]',
                                                    ''),
                                     'YYYYMMDD'),
                             'YYYY-MM-DD');

  --======================
  --20240708 清单阶段及自动化核验
  --
  if v_projlist_status = '0' then
    --未入单
    v_projlist_status_next := case
                                when v_ro_inout_date is not null then
                                 'ro'
                                when v_rl_inout_date is not null then
                                 'rl'
                                when v_rq_inout_date is not null then
                                 'rq'
                                else
                                 null
                              end;
  
  elsif v_projlist_status in ('ro', 'rl', 'rq') then
    --入观察清单，入限制清单，入静默期       
  
    v_projlist_status_next := 'c' || substr(v_projlist_status, 2);
  
  elsif v_projlist_status in ('co', 'cl', 'cq') then
    --出观察清单，出限制清单，出静默期
  
    --入清单,获取选中的入清单阶段
    v_projlist_status_next := case
                                when v_ro_inout_date is not null then
                                 'ro'
                                when v_rl_inout_date is not null then
                                 'rl'
                                when v_rq_inout_date is not null then
                                 'rq'
                                else
                                 null
                              end;
  
  else
    o_return_msg  := '清单状态有误，请联系系统管理员！';
    o_return_code := -1;
    return;
  
  end if;

  --清单填报实际阶段状态
  if v_projlist_status_next is not null then
  
    if (v_projlist_status_next = 'ro' and v_ro_inout_date is null) or
       (v_projlist_status_next = 'co' and v_co_inout_date is null) or
       (v_projlist_status_next = 'rl' and v_rl_inout_date is null) or
       (v_projlist_status_next = 'cl' and v_cl_inout_date is null) or
       (v_projlist_status_next = 'rq' and v_rq_inout_date is null) or
       (v_projlist_status_next = 'cq' and v_cq_inout_date is null) then
    
      o_return_msg  := '清单填报日期有误，请联系系统管理员！';
      o_return_code := -1;
      return;
    
    end if;
  
    --自动逻辑处理  
    if v_projlist_status_next = 'co' and i_co_inout_reason = '3' then
      --出观察转限制清单
    
      v_projlist_status_third := 'rl';
      v_rl_inout_date         := nvl(v_rl_inout_date, v_co_inout_date);
    
      if v_rl_inout_date is null then
        o_return_msg  := '转限制清单有误，请联系系统管理员！';
        o_return_code := -1;
        return;
      end if;
    elsif v_projlist_status_next = 'co' and i_co_inout_reason = '4' then
      --出观察转静默期
      v_projlist_status_third := 'rq';
      v_projlist_status_four  := 'cq';
    
      --自动静默期处理
      v_rq_inout_date := nvl(v_rq_inout_date, v_co_inout_date);
      if v_cq_inout_date is null or v_cq_inout_date = v_rq_inout_date then
      
        v_cq_inout_date := to_char(to_date(v_rq_inout_date, 'yyyy-MM-dd') +
                                   (case
                                      when v_proj_type like '%IPO%' then
                                       40
                                      else
                                       10
                                    end),
                                   'yyyy-MM-dd');
      end if;
    
    elsif v_projlist_status_next = 'cl' and i_co_inout_reason = '1' then
      --出限制，事由=价格利率确定
    
      v_projlist_status_third := 'rq';
      v_projlist_status_four  := 'cq';
    
      --自动静默期处理
      v_rq_inout_date := nvl(v_rq_inout_date, v_cl_inout_date);
      if v_cq_inout_date is null or v_cq_inout_date = v_rq_inout_date then
      
        v_cq_inout_date := to_char(to_date(v_rq_inout_date, 'yyyy-MM-dd') +
                                   (case
                                      when v_proj_type like '%IPO%' then
                                       40
                                      else
                                       10
                                    end),
                                   'yyyy-MM-dd');
      end if;
    
    elsif v_projlist_status_next = 'rq' then
      --手工入静默期
      v_projlist_status_third := 'cq';
    
      --自动静默期处理
      if v_cq_inout_date is null or v_cq_inout_date = v_rq_inout_date then
      
        v_cq_inout_date := to_char(to_date(v_rq_inout_date, 'yyyy-MM-dd') +
                                   (case
                                      when v_proj_type like '%IPO%' then
                                       40
                                      else
                                       10
                                    end),
                                   'yyyy-MM-dd');
      
      end if;
    
    end if;
  
  else
    o_return_msg  := '清单状态有误，请联系系统管理员！';
    o_return_code := -1;
    return;
  end if;

  --====================================================================
  --生成新的批次号
  if i_batch_id is null then
    v_batch_id := sys_guid();
    --新批次时，保存原批次，清空主表出入单绑定ID
    insert into thjs.tb_projlist_main_batch
      select * from thjs.tb_projlist_main t where t.projid = i_projid;
  
    update thjs.tb_projlist_main t
       set t.batch_id    = v_batch_id,
           t.robserve_id = null,
           t.cobserve_id = null,
           t.rlimit_id   = null,
           t.climit_id   = null,
           t.rquiet_id   = null,
           t.cquiet_id   = null
     where t.projid = i_projid;
    commit;
  else
    v_batch_id := i_batch_id;
  end if;

  if i_submit_status <> '2' then
    --草稿，提交
  
    --根据清单状态，判断填报阶段，保存填报信息，更新主表 
    v_inout_id       := sys_guid();
    v_inout_id_next  := sys_guid();
    v_inout_id_third := sys_guid();
  
    if v_projlist_status = '0' then
      --未入单
      v_projlist_status_next := case
                                  when v_ro_inout_date is not null then
                                   'ro'
                                  when v_rl_inout_date is not null then
                                   'rl'
                                  when v_rq_inout_date is not null then
                                   'rq'
                                  else
                                   null
                                end;
    
      if v_projlist_status_next is not null then
      
        insert into thjs.tb_projlist_inout
          (busidate,
           batch_id,
           inout_id,
           projid,
           inout_type,
           inout_direct,
           fill_date,
           inout_date,
           inout_reason,
           inout_remark,
           filepath,
           inout_user,
           inout_status,
           update_user,
           update_time)
        values
          (v_tradedate,
           v_batch_id,
           v_inout_id,
           i_projid,
           substr(v_projlist_status_next, 2), --取清单类型       
           'i', --入观察清单
           v_filldate,
           decode(v_projlist_status_next,
                  'ro',
                  v_ro_inout_date,
                  'rl',
                  v_rl_inout_date,
                  'rq',
                  v_rq_inout_date),
           decode(v_projlist_status_next,
                  'ro',
                  i_ro_inout_reason,
                  'rl',
                  i_rl_inout_reason,
                  'rq',
                  i_rq_inout_reason),
           decode(v_projlist_status_next,
                  'ro',
                  i_ro_inout_remark,
                  'rl',
                  i_rl_inout_remark,
                  'rq',
                  i_rq_inout_remark),
           decode(v_projlist_status_next,
                  'ro',
                  i_ro_filepath,
                  'rl',
                  i_rl_filepath,
                  'rq',
                  i_rq_filepath),
           i_usercode,
           i_submit_status,
           i_usercode,
           sysdate);
           
        -----------------------
         insert into thjs.tb_tmp_0406          
          select v_tradedate,
                 c.projid,
                 '',
                 v_batch_id,
                 decode(v_projlist_status_next, 'ro', v_inout_id, ''),
                 decode(v_projlist_status_next, 'rl', v_inout_id, ''),
                 decode(v_projlist_status_next, 'rq', v_inout_id, ''),
                 v_projlist_status_next,
                 i_usercode,
                 i_usercode
            from thjs.tb_ib_cust_info c
           where c.projid = i_projid; 
        commit;                   
        -----------------------
           
      
        --根据清单状态更新主表
        insert into thjs.tb_projlist_main
          (busidate,
           projid,
           gtjarole,
           --multistk_id,
           batch_id,
           robserve_id,
           rlimit_id,
           rquiet_id,
           projlist_status,
           update_user,
           create_user)
          select v_tradedate,
                 c.projid,
                 '',
                 v_batch_id,
                 decode(v_projlist_status_next, 'ro', v_inout_id, ''),
                 decode(v_projlist_status_next, 'rl', v_inout_id, ''),
                 decode(v_projlist_status_next, 'rq', v_inout_id, ''),
                 v_projlist_status_next,
                 i_usercode,
                 i_usercode
            from thjs.tb_ib_cust_info c
           where c.projid = i_projid;
        commit;
      
        --直接入静默期时，自动出静默期
        if v_projlist_status_next = 'rq' then
        
          --入静默期
          --处理页面有误，入静默期日期未传递/出静默=入静默时，根据出限制日期自动计算日期
          if v_cq_inout_date is null or v_rq_inout_date = v_cq_inout_date then
            --v_rq_inout_date,v_cq_inout_date
            select to_char(to_date(v_rq_inout_date, 'yyyy-MM-dd') + case
                             when v_proj_type like '%IPO%' then
                              40
                             else
                              10
                           end,
                           'yyyy-MM-dd')
              into v_cq_inout_date
              from dual;
          end if;
        
          if v_cq_inout_date is not null then
          
            insert into thjs.tb_projlist_inout
              (busidate,
               batch_id,
               inout_id,
               projid,
               inout_type,
               inout_direct,
               fill_date,
               inout_date,
               inout_reason,
               inout_remark,
               filepath,
               inout_user,
               inout_status,
               update_user,
               update_time)
            values
              (v_tradedate,
               v_batch_id,
               v_inout_id_next,
               i_projid,
               'q', --静默期
               'o', --出清单
               v_filldate,
               v_cq_inout_date,
               i_cq_inout_reason,
               i_cq_inout_remark,
               i_cq_filepath,
               i_usercode,
               i_submit_status,
               i_usercode,
               sysdate);
          
            update thjs.tb_projlist_main p
               set p.cquiet_id       = v_inout_id_next,
                   p.projlist_status = case
                                         when v_cq_inout_date >
                                              to_char(sysdate, 'YYYY-MM-DD') then
                                          'rq'
                                         else
                                          'cq'
                                       end,
                   p.update_user     = i_usercode,
                   p.update_time     = sysdate
             where p.projid = i_projid;
          
            commit;
          else
          
            o_return_msg  := '静默期自动出单有误，请联系系统管理员！';
            o_return_code := -1;
            rollback;
            return;
          end if;
        
        end if;
      
      else
      
        o_return_msg  := '入单有误，请联系系统管理员！';
        o_return_code := -1;
        return;
      
      end if;
    
    elsif v_projlist_status in ('ro', 'rl', 'rq') then
      --入观察清单，入限制清单，入静默期
    
      --出清单
      insert into thjs.tb_projlist_inout
        (busidate,
         batch_id,
         inout_id,
         projid,
         inout_type,
         inout_direct,
         fill_date,
         inout_date,
         inout_reason,
         inout_remark,
         filepath,
         inout_user,
         inout_status,
         update_user,
         update_time,
         debug_info)
      values
        (v_tradedate,
         v_batch_id,
         v_inout_id,
         i_projid,
         substr(v_projlist_status, 2), --取清单类型
         'o', --出清单
         v_filldate,
         decode(v_projlist_status,
                'ro',
                v_co_inout_date,
                'rl',
                v_cl_inout_date,
                'rq',
                v_cq_inout_date),
         decode(v_projlist_status,
                'ro',
                i_co_inout_reason,
                'rl',
                i_cl_inout_reason,
                'rq',
                i_cq_inout_reason),
         decode(v_projlist_status,
                'ro',
                i_co_inout_remark,
                'rl',
                i_cl_inout_remark,
                'rq',
                i_cq_inout_remark),
         decode(v_projlist_status,
                'ro',
                i_co_filepath,
                'rl',
                i_cl_filepath,
                'rq',
                i_cq_filepath),
         i_usercode,
         i_submit_status,
         i_usercode,
         sysdate,
         'projtype:' || v_proj_type);
    
      --根据清单状态更新主表
      --出单记录id及状态更新
      update thjs.tb_projlist_main p
         set p.cobserve_id     = decode(v_projlist_status,
                                        'ro',
                                        v_inout_id,
                                        p.cobserve_id),
             p.climit_id       = decode(v_projlist_status,
                                        'rl',
                                        v_inout_id,
                                        p.climit_id),
             p.cquiet_id       = decode(v_projlist_status,
                                        'rq',
                                        v_inout_id,
                                        p.cquiet_id),
             p.projlist_status = 'c' || substr(v_projlist_status, 2),
             p.update_user     = i_usercode,
             p.update_time     = sysdate
       where p.projid = i_projid;
      commit;
    
      --出观察清单同时入其他清单
      if v_projlist_status = 'ro' and i_co_inout_reason in ('3', '4') then
        --3 转限制清单 4 转静默期
      
        v_projlist_status_next := case
                                    when v_projlist_status <> 'ro' and v_ro_inout_date is not null then
                                     'ro'
                                    when v_projlist_status <> 'rl' and v_rl_inout_date is not null then
                                     'rl'
                                    when v_projlist_status <> 'rq' and v_rq_inout_date is not null then
                                     'rq'
                                    else
                                     null
                                  end;
      
        --入清单
        if v_projlist_status_next is not null then
        
          insert into thjs.tb_projlist_inout
            (busidate,
             batch_id,
             inout_id,
             projid,
             inout_type,
             inout_direct,
             fill_date,
             inout_date,
             inout_reason,
             inout_remark,
             filepath,
             inout_user,
             inout_status,
             update_user,
             update_time)
          values
            (v_tradedate,
             v_batch_id,
             v_inout_id_next,
             i_projid,
             substr(v_projlist_status_next, 2), --取清单类型       
             'i', --入清单
             v_filldate,
             decode(v_projlist_status_next,
                    'ro',
                    v_ro_inout_date,
                    'rl',
                    v_rl_inout_date,
                    'rq',
                    v_rq_inout_date),
             decode(v_projlist_status_next,
                    'ro',
                    i_ro_inout_reason,
                    'rl',
                    i_rl_inout_reason,
                    'rq',
                    i_rq_inout_reason),
             decode(v_projlist_status_next,
                    'ro',
                    i_ro_inout_remark,
                    'rl',
                    i_rl_inout_remark,
                    'rq',
                    i_rq_inout_remark),
             decode(v_projlist_status_next,
                    'ro',
                    i_ro_filepath,
                    'rl',
                    i_rl_filepath,
                    'rq',
                    i_rq_filepath),
             i_usercode,
             i_submit_status,
             i_usercode,
             sysdate);
        
          --同时入单记录id及状态二次更新
          update thjs.tb_projlist_main p
             set p.robserve_id     = decode(v_projlist_status_next,
                                            'ro',
                                            v_inout_id_next,
                                            p.robserve_id),
                 p.rlimit_id       = decode(v_projlist_status_next,
                                            'rl',
                                            v_inout_id_next,
                                            p.rlimit_id),
                 p.rquiet_id       = decode(v_projlist_status_next,
                                            'rq',
                                            v_inout_id_next,
                                            p.rquiet_id),
                 p.projlist_status = v_projlist_status_next,
                 p.update_user     = i_usercode,
                 p.update_time     = sysdate
           where p.projid = i_projid;
          commit;
        
          --观察转静默，静默期自动完成
          if v_projlist_status_next = 'rq' then
          
            --入静默期
            --处理页面有误，入静默期日期未传递/出静默=入静默时，根据出限制日期自动计算日期
            if v_cq_inout_date is null or v_rq_inout_date = v_cq_inout_date then
              --v_rq_inout_date,v_cq_inout_date
              select to_char(to_date(v_rq_inout_date, 'yyyy-MM-dd') + case
                               when v_proj_type like '%IPO%' then
                                40
                               else
                                10
                             end,
                             'yyyy-MM-dd')
                into v_cq_inout_date
                from dual;
            end if;
          
            --自动静默期有误时，错误提醒
            if v_cq_inout_date is null then
              o_return_msg  := '静默期自动入出单有误，请联系系统管理员！';
              o_return_code := -1;
              rollback;
              return;
            end if;
          
          end if;
        
        else
          --转限制，静默时日期 未成功返回
          o_return_msg  := '观察清单转限制/静默有误，请联系系统管理员！';
          o_return_code := -1;
          rollback;
          return;
        
        end if;
      
      end if;
    
      --出限制清单时，选择价格/利率确定 自动完成静默期阶段
      if v_projlist_status = 'rl' and i_cl_inout_reason = '1' then
      
        --IPO类型  入静默期日期+40日后自动出静默期
        --其余类型 入静默期日期+10日后自动出静默期
      
        --入静默期
        --处理页面有误，入静默期日期未传递/出静默=入静默时，根据出限制日期自动计算日期
        if v_rq_inout_date is null or v_rq_inout_date = v_cq_inout_date then
          --v_rq_inout_date,v_cq_inout_date
          select v_cl_inout_date,
                 to_char(to_date(v_cl_inout_date, 'yyyy-MM-dd') + case
                           when v_proj_type like '%IPO%' then
                            40
                           else
                            10
                         end,
                         'yyyy-MM-dd')
            into v_rq_inout_date, v_cq_inout_date
            from dual;
        end if;
      
        --自动静默期有误时，错误提醒
        if v_rq_inout_date is null or v_cq_inout_date is null then
          o_return_msg  := '静默期自动入出单有误，请联系系统管理员！';
          o_return_code := -1;
          rollback;
          return;
        end if;
      
        if v_rq_inout_date is not null then
        
          insert into thjs.tb_projlist_inout
            (busidate,
             batch_id,
             inout_id,
             projid,
             inout_type,
             inout_direct,
             fill_date,
             inout_date,
             inout_reason,
             inout_remark,
             filepath,
             inout_user,
             inout_status,
             update_user,
             update_time)
          values
            (v_tradedate,
             v_batch_id,
             v_inout_id_next,
             i_projid,
             'q', --静默期
             'i', --入清单
             v_filldate,
             v_rq_inout_date,
             i_rq_inout_reason,
             i_rq_inout_remark,
             i_rq_filepath,
             i_usercode,
             i_submit_status,
             i_usercode,
             sysdate);
        
          update thjs.tb_projlist_main p
             set p.rquiet_id       = v_inout_id_next,
                 p.projlist_status = 'rq',
                 p.update_user     = i_usercode,
                 p.update_time     = sysdate
           where p.projid = i_projid;
        
        end if;
      
        commit;
      
      end if;
    
      --自动出静默期
      if v_projlist_status <> 'rq' and v_cq_inout_date is not null then
      
        insert into thjs.tb_projlist_inout
          (busidate,
           batch_id,
           inout_id,
           projid,
           inout_type,
           inout_direct,
           fill_date,
           inout_date,
           inout_reason,
           inout_remark,
           filepath,
           inout_user,
           inout_status,
           update_user,
           update_time)
        values
          (v_tradedate,
           v_batch_id,
           v_inout_id_third,
           i_projid,
           'q', --静默期
           'o', --出清单
           v_filldate,
           v_cq_inout_date,
           i_cq_inout_reason,
           i_cq_inout_remark,
           i_cq_filepath,
           i_usercode,
           i_submit_status,
           i_usercode,
           sysdate);
      
        update thjs.tb_projlist_main p
           set p.cquiet_id       = v_inout_id_third,
               p.projlist_status = case
                                     when v_cq_inout_date >
                                          to_char(sysdate, 'YYYY-MM-DD') then
                                      'rq'
                                     else
                                      'cq'
                                   end,
               p.update_user     = i_usercode,
               p.update_time     = sysdate
         where p.projid = i_projid;
      
        commit;
      
      end if;
    
    elsif v_projlist_status in ('co', 'cl', 'cq') then
      --出观察清单，出限制清单，出静默期
    
      --入清单,获取选中的入清单阶段
      v_projlist_status_next := case
                                  when v_ro_inout_date is not null then
                                   'ro'
                                  when v_rl_inout_date is not null then
                                   'rl'
                                  when v_rq_inout_date is not null then
                                   'rq'
                                  else
                                   null
                                end;
    
      --入清单
      if v_projlist_status_next is not null then
      
        insert into thjs.tb_projlist_inout
          (busidate,
           batch_id,
           inout_id,
           projid,
           inout_type,
           inout_direct,
           fill_date,
           inout_date,
           inout_reason,
           inout_remark,
           filepath,
           inout_user,
           inout_status,
           update_user,
           update_time)
        values
          (v_tradedate,
           v_batch_id,
           v_inout_id_next,
           i_projid,
           substr(v_projlist_status_next, 2), --取清单类型       
           'i', --入清单
           v_filldate,
           decode(v_projlist_status_next,
                  'ro',
                  v_ro_inout_date,
                  'rl',
                  v_rl_inout_date,
                  'rq',
                  v_rq_inout_date),
           decode(v_projlist_status_next,
                  'ro',
                  i_ro_inout_reason,
                  'rl',
                  i_rl_inout_reason,
                  'rq',
                  i_rq_inout_reason),
           decode(v_projlist_status_next,
                  'ro',
                  i_ro_inout_remark,
                  'rl',
                  i_rl_inout_remark,
                  'rq',
                  i_rq_inout_remark),
           decode(v_projlist_status_next,
                  'ro',
                  i_ro_filepath,
                  'rl',
                  i_rl_filepath,
                  'rq',
                  i_rq_filepath),
           i_usercode,
           i_submit_status,
           i_usercode,
           sysdate);
      
        --入单记录id及状态更新
        update thjs.tb_projlist_main p
           set p.robserve_id     = decode(v_projlist_status_next,
                                          'ro',
                                          v_inout_id_next,
                                          p.robserve_id),
               p.rlimit_id       = decode(v_projlist_status_next,
                                          'rl',
                                          v_inout_id_next,
                                          p.rlimit_id),
               p.rquiet_id       = decode(v_projlist_status_next,
                                          'rq',
                                          v_inout_id_next,
                                          p.rquiet_id),
               p.projlist_status = v_projlist_status_next,
               p.update_user     = i_usercode,
               p.update_time     = sysdate
         where p.projid = i_projid;
        commit;
      
      end if;
    
      --自动出静默期
      if v_projlist_status_next = 'rq' then
      
        --入静默期
        --处理页面有误，入静默期日期未传递/出静默=入静默时，根据出限制日期自动计算日期
        if v_cq_inout_date is null or v_rq_inout_date = v_cq_inout_date then
          --v_rq_inout_date,v_cq_inout_date
          select to_char(to_date(v_rq_inout_date, 'yyyy-MM-dd') + case
                           when v_proj_type like '%IPO%' then
                            40
                           else
                            10
                         end,
                         'yyyy-MM-dd')
            into v_cq_inout_date
            from dual;
        end if;
      
        if v_cq_inout_date is not null then
          insert into thjs.tb_projlist_inout
            (busidate,
             batch_id,
             inout_id,
             projid,
             inout_type,
             inout_direct,
             fill_date,
             inout_date,
             inout_reason,
             inout_remark,
             filepath,
             inout_user,
             inout_status,
             update_user,
             update_time)
          values
            (v_tradedate,
             v_batch_id,
             v_inout_id_third,
             i_projid,
             'q', --静默期
             'o', --出清单
             v_filldate,
             v_cq_inout_date,
             i_cq_inout_reason,
             i_cq_inout_remark,
             i_cq_filepath,
             i_usercode,
             i_submit_status,
             i_usercode,
             sysdate);
        
          update thjs.tb_projlist_main p
             set p.cquiet_id       = v_inout_id_third,
                 p.projlist_status = case
                                       when v_cq_inout_date >
                                            to_char(sysdate, 'YYYY-MM-DD') then
                                        'rq'
                                       else
                                        'cq'
                                     end,
                 p.update_user     = i_usercode,
                 p.update_time     = sysdate
           where p.projid = i_projid;
        
          commit;
        
        else
        
          o_return_msg  := '静默期自动入出单有误，请联系系统管理员！';
          o_return_code := -1;
          rollback;
          return;
        
        end if;
      
      end if;
    
    end if;
  
  elsif i_submit_status = '2' then
    --修正
  
    update thjs.tb_projlist_main p
       set p.update_user = i_usercode, p.update_time = sysdate
     where p.projid = i_projid;
  
    v_inout_id       := sys_guid();
    v_inout_id_next  := sys_guid();
    v_inout_id_third := sys_guid();
  
    --判断存在的清单阶段
    --针对存在的阶段数据作更新操作
    --不存在的阶段，有值传入（出观察时入其他阶段），视作清单填报处理
    select p.robserve_id,
           p.cobserve_id,
           p.rlimit_id,
           p.climit_id,
           p.rquiet_id,
           p.cquiet_id
      into v_ro_id, v_co_id, v_rl_id, v_cl_id, v_rq_id, v_cq_id
      from thjs.tb_projlist_main p
     where p.projid = i_projid;
  
    --入观察
    if v_ro_id is not null and v_ro_inout_date is not null then
    
      update thjs.tb_projlist_inout i
         set i.inout_date   = v_ro_inout_date,
             i.inout_reason = i_ro_inout_reason,
             i.inout_remark = i_ro_inout_remark,
             i.filepath     = i_ro_filepath,
             i.update_user  = i_usercode,
             i.update_time  = sysdate
       where i.inout_id = v_ro_id;
    
    end if;
  
    --出观察
    if v_co_id is not null and v_co_inout_date is not null then
    
      update thjs.tb_projlist_inout i
         set i.inout_date   = v_co_inout_date,
             i.inout_reason = i_co_inout_reason,
             i.inout_remark = i_co_inout_remark,
             i.filepath     = i_co_filepath,
             i.update_user  = i_usercode,
             i.update_time  = sysdate
       where i.inout_id = v_co_id;
    
    end if;
  
    --入限制
    if v_rl_inout_date is not null then
    
      if v_rl_id is not null then
        update thjs.tb_projlist_inout i
           set i.inout_date   = v_rl_inout_date,
               i.inout_reason = i_rl_inout_reason,
               i.inout_remark = i_rl_inout_remark,
               i.filepath     = i_rl_filepath,
               i.update_user  = i_usercode,
               i.update_time  = sysdate
         where i.inout_id = v_rl_id;
      
      else
        insert into thjs.tb_projlist_inout
          (busidate,
           batch_id,
           inout_id,
           projid,
           inout_type,
           inout_direct,
           fill_date,
           inout_date,
           inout_reason,
           inout_remark,
           filepath,
           inout_user,
           inout_status,
           update_user,
           update_time)
        values
          (v_tradedate,
           v_batch_id,
           v_inout_id,
           i_projid,
           'l',
           'i',
           v_tradedate,
           v_rl_inout_date,
           i_rl_inout_reason,
           i_rl_inout_remark,
           i_rl_filepath,
           i_usercode,
           '1',
           i_usercode,
           sysdate);
      
        update thjs.tb_projlist_main p
           set p.rlimit_id = v_inout_id
         where p.projid = i_projid;
      
      end if;
    
    end if;
  
    --出限制
    if v_cl_id is not null and v_cl_inout_date is not null then
    
      update thjs.tb_projlist_inout i
         set i.inout_date   = v_cl_inout_date,
             i.inout_reason = i_cl_inout_reason,
             i.inout_remark = i_cl_inout_remark,
             i.filepath     = i_cl_filepath,
             i.update_user  = i_usercode,
             i.update_time  = sysdate
       where i.inout_id = v_cl_id;
    
    end if;
  
    --入静默
    if v_rq_inout_date is not null then
    
      if v_rq_id is not null then
        update thjs.tb_projlist_inout i
           set i.inout_date   = v_rq_inout_date,
               i.inout_reason = i_rq_inout_reason,
               i.inout_remark = i_rq_inout_remark,
               i.filepath     = i_rq_filepath,
               i.update_user  = i_usercode,
               i.update_time  = sysdate
         where i.inout_id = v_rq_id;
      
      else
      
        insert into thjs.tb_projlist_inout
          (busidate,
           batch_id,
           inout_id,
           projid,
           inout_type,
           inout_direct,
           fill_date,
           inout_date,
           inout_reason,
           inout_remark,
           filepath,
           inout_user,
           inout_status,
           update_user,
           update_time)
        values
          (v_tradedate,
           v_batch_id,
           v_inout_id_next,
           i_projid,
           'q',
           'i',
           v_tradedate,
           v_rq_inout_date,
           i_rq_inout_reason,
           i_rq_inout_remark,
           i_rq_filepath,
           i_usercode,
           '1',
           i_usercode,
           sysdate);
      
        update thjs.tb_projlist_main p
           set p.rquiet_id = v_inout_id_next
         where p.projid = i_projid;
      
      end if;
    
    end if;
  
    --出静默
    if v_cq_inout_date is not null then
    
      if v_cq_id is not null then
        update thjs.tb_projlist_inout i
           set i.inout_date   = v_cq_inout_date,
               i.inout_reason = i_cq_inout_reason,
               i.inout_remark = i_cq_inout_remark,
               i.filepath     = i_cq_filepath,
               i.update_user  = i_usercode,
               i.update_time  = sysdate
         where i.inout_id = v_cq_id;
      
      else
      
        insert into thjs.tb_projlist_inout
          (busidate,
           batch_id,
           inout_id,
           projid,
           inout_type,
           inout_direct,
           fill_date,
           inout_date,
           inout_reason,
           inout_remark,
           filepath,
           inout_user,
           inout_status,
           update_user,
           update_time)
        values
          (v_tradedate,
           v_batch_id,
           v_inout_id_third,
           i_projid,
           'q',
           'o',
           v_tradedate,
           v_cq_inout_date,
           i_cq_inout_reason,
           i_cq_inout_remark,
           i_cq_filepath,
           i_usercode,
           '1',
           i_usercode,
           sysdate);
      
        update thjs.tb_projlist_main p
           set p.cquiet_id = v_inout_id_third
         where p.projid = i_projid;
      
      end if;
    
    end if;
  
    commit;
  
  end if;

  --因关联信息存在置空情况，故关联信息批次代码fill_id应主动清空。并由关联信息修改sp去更新
  update thjs.tb_projlist_main p
     set p.multistk_id = ''
   where p.projid = i_projid;
  commit;

  --由于实际操作日期与出入单发生日期（页面输入）不一定一致，需根据清单各阶段日期取值，重新计算状态字段
  merge into thjs.tb_projlist_main p
  using (select t.projid,
                t.projname,
                t.ro_inout_date,
                t.co_inout_date,
                t.rl_inout_date,
                t.cl_inout_date,
                t.rq_inout_date,
                t.cq_inout_date,
                case
                  when (t.ro_inout_date is not null and
                       t.ro_inout_date <= to_char(sysdate, 'yyyy-MM-dd')) and
                       (t.co_inout_date is null or
                       t.co_inout_date > to_char(sysdate, 'yyyy-MM-dd')) and
                       t.rl_inout_date is null and t.rq_inout_date is null then
                   'ro'
                  when (t.rl_inout_date is null or
                       t.rl_inout_date > to_char(sysdate, 'yyyy-MM-dd')) and
                       (t.co_inout_date is not null and
                       t.co_inout_date <= to_char(sysdate, 'yyyy-MM-dd')) and
                       (t.rq_inout_date is null or
                       t.rq_inout_date > to_char(sysdate, 'yyyy-MM-dd')) then
                   'co'
                  when (t.rl_inout_date is not null and
                       t.rl_inout_date <= to_char(sysdate, 'yyyy-MM-dd')) and
                       (t.cl_inout_date is null or
                       t.cl_inout_date > to_char(sysdate, 'yyyy-MM-dd')) then
                   'rl'
                  when (t.rq_inout_date is null or
                       t.rq_inout_date > to_char(sysdate, 'yyyy-MM-dd')) and
                       (t.cl_inout_date is not null and
                       t.cl_inout_date <= to_char(sysdate, 'yyyy-MM-dd')) and
                       t.rq_inout_date is null then
                   'cl'
                  when (t.rq_inout_date is not null and
                       t.rq_inout_date <= to_char(sysdate, 'yyyy-MM-dd')) and
                       (t.cq_inout_date is null or
                       t.cq_inout_date > to_char(sysdate, 'yyyy-MM-dd')) then
                   'rq'
                  when t.cq_inout_date is not null and
                       t.cq_inout_date <= to_char(sysdate, 'yyyy-MM-dd') then
                   'cq'
                  else
                   '0'
                end as calc_status,
                t.projlist_status
           from THJS.VW_PROJLIST_MAIN_INOUT t
          where t.projid = i_projid) t
  on (p.projid = t.projid)
  when matched then
    update set p.projlist_status = t.calc_status;
  commit;

  --刷新清单所有入出单记录检查结果
  merge into thjs.tb_projlist_check c
  using (select i.busidate,
                i.projid,
                i.inout_id,
                case
                  when date_diff <= 0 then
                   '0'
                  else
                   '1'
                end as check_flag,
                case
                  when date_diff < 0 then
                   '早' || abs(i.date_diff) || '天'
                  when date_diff = 0 then
                   '准确'
                  else
                   '晚' || abs(i.date_diff) || '天'
                end as check_result
           from (select i.*,
                        to_date(i.fill_date, 'yyyy-MM-dd') -
                        to_date(i.inout_date, 'yyyy-MM-dd') as date_diff
                   from thjs.tb_projlist_inout i
                  where i.projid = i_projid) i) i
  on (c.projid = i.projid and c.inout_id = i.inout_id)
  when matched then
    update set c.check_flag = i.check_flag, c.check_result = i.check_result
  when not matched then
    insert
      (BUSIDATE,
       PROJID,
       INOUT_ID,
       CHECK_FLAG,
       CHECK_RESULT,
       CHECK_USER,
       CREATE_TIME)
    values
      (i.busidate,
       i.projid,
       i.inout_id,
       i.check_flag,
       i.check_result,
       'admin',
       sysdate);

  commit;

  o_return_msg  := '执行成功';
  o_return_code := 0;

  /*insert into thjs.tb_test
    (id, text)
  values
    (95, o_return_msg || '-' || o_return_code);*/

exception
  -- 非预定义异常处理
  when v_userexp then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    thjs.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
    -- 预定义异常处理
  when others then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    thjs.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
end;

Create or Replace procedure "THJS"."P_PROJLIST_INOUT_S2" (i_projid          in varchar2, --项目id
                                                     i_batch_id        in varchar2, --清单填报批次ID：新增批次默认为空，否则传入当前批次ID
                                                     i_ro_inout_date   in varchar2, --入观察清单日期
                                                     i_ro_inout_reason in varchar2, --入观察清单事由
                                                     i_ro_inout_remark in varchar2, --入观察清单备注
                                                     i_ro_filepath     in varchar2, --入观察清单附件
                                                     i_co_inout_date   in varchar2, --出观察清单日期
                                                     i_co_inout_reason in varchar2, --出观察清单事由
                                                     i_co_inout_remark in varchar2, --出观察清单备注
                                                     i_co_filepath     in varchar2, --出观察清单附件
                                                     i_rl_inout_date   in varchar2, --入限制清单日期
                                                     i_rl_inout_reason in varchar2, --入限制清单事由
                                                     i_rl_inout_remark in varchar2, --入限制清单备注
                                                     i_rl_filepath     in varchar2, --入限制清单附件
                                                     i_cl_inout_date   in varchar2, --出限制清单日期
                                                     i_cl_inout_reason in varchar2, --出限制清单事由
                                                     i_cl_inout_remark in varchar2, --出限制清单备注
                                                     i_cl_filepath     in varchar2, --出限制清单附件
                                                     i_rq_inout_date   in varchar2, --入静默期日期
                                                     i_rq_inout_reason in varchar2, --入静默期事由
                                                     i_rq_inout_remark in varchar2, --入静默期备注
                                                     i_rq_filepath     in varchar2, --入静默期附件
                                                     i_cq_inout_date   in varchar2, --出静默期日期
                                                     i_cq_inout_reason in varchar2, --出静默期事由
                                                     i_cq_inout_remark in varchar2, --出静默期备注
                                                     i_cq_filepath     in varchar2, --出静默期附件
                                                     i_projlist_status in varchar2, --清单状态
                                                     i_submit_status   in varchar2, --提交状态 [0 草稿] 1 提交  [2 修正]
                                                     i_usercode        in varchar2, --操作员
                                                     o_return_msg      out varchar2,
                                                     o_return_code     out integer) is
  ----------------------------------------------------------------------------------
  --版    权：GTJA
  --版    本：1.0.0
  --开发人员：CZC@GTJA
  --创建日期：20190510
  --模块编号：
  --模块名称：清单管理 - 清单填报页面信息保存
  --功能名称：清单填报页面信息保存
  ----------------------------------------------------------------------------------
  --20240702 【暂未启用】重新改造，因自动化逻辑历史问题，提前验证报错预警
  --==============================================================================
  --固定变量
  v_userexp exception; -- 用户定义错
  v_tradedate    varchar2(8); -- 任务执行时间(业务日期)
  v_exec_func_id integer default '0'; -- 任务id
  v_func_own     varchar2(20) default 'thjs'; -- 任务归属用户（schema）
  v_func_name    varchar2(2000) default 'p_projlist_inout_s'; -- 任务名称(存储过程的名字)
  v_sqlerrm      varchar2(4000); -- 错误提示信息
  v_sqlcode      number; -- 错误代码
  v_sqlerrl      varchar2(4000); -- 错误行号
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  v_filldate              varchar2(10);
  v_projlist_status       varchar2(20);
  v_projlist_status_next  varchar2(20); --出入单同时入单状态  
  v_projlist_status_third varchar2(20); --出入单同时入单状态
  v_projlist_status_four  varchar2(20); --出入单同时入单状态
  v_inout_id_next         varchar2(80); --出入单iD
  v_inout_id_third        varchar2(80); --出单时同时入单id
  v_inout_id_four         varchar2(80); --出单时同时入单后出的id
  v_proj_type             varchar2(50); --项目类型

  v_ro_inout_date varchar2(10);
  v_co_inout_date varchar2(10);
  v_rl_inout_date varchar2(10);
  v_cl_inout_date varchar2(10);
  v_rq_inout_date varchar2(10);
  v_cq_inout_date varchar2(10);

  v_batch_id varchar2(80); --批次ID

  v_co_filepath varchar2(1000);
  --=============================================================
  -- 业务处理过程
  --=============================================================

begin

  v_tradedate := to_char(sysdate, 'yyyyMMdd');
  v_filldate  := to_char(sysdate, 'yyyy-MM-dd');

  insert into thjs.tb_exec_log
    (log_id, proc_name, proc_param, exec_time)
  values
    (thjs.tb_exec_log_id_seq.nextval,
     'p_projlist_inout_s',
     i_projid || ',' || i_batch_id || ',' || i_ro_inout_date || ',' ||
     i_ro_inout_reason || ',' || i_ro_inout_remark || ',' || i_ro_filepath || ',' ||
     i_co_inout_date || ',' || i_co_inout_reason || ',' ||
     i_co_inout_remark || ',' || i_co_filepath || ',' || i_rl_inout_date || ',' ||
     i_rl_inout_reason || ',' || i_rl_inout_remark || ',' || i_rl_filepath || ',' ||
     i_cl_inout_date || ',' || i_cl_inout_reason || ',' ||
     i_cl_inout_remark || ',' || i_cl_filepath || ',' || i_rq_inout_date || ',' ||
     i_rq_inout_reason || ',' || i_rq_inout_remark || ',' || i_rq_filepath ||
     i_cq_inout_date || ',' || i_cq_inout_reason || ',' ||
     i_cq_inout_remark || ',' || i_cq_filepath || ',' || i_projlist_status || ',' ||
     i_submit_status || ',' || i_usercode,
     sysdate);
  commit;

  v_co_filepath := i_co_filepath;
  --测试代码
  /*if i_projid='D1D9967EE60F4DAD9A4AB95000CDE228' and i_co_filepath is not null then
    v_co_filepath:=substr(i_co_filepath,instr(i_co_filepath,'/',-1,1))||'undefined';   
  end if;*/
  --=======================================================

  select nvl(m.projlist_status, '0')
    into v_projlist_status
    from dual
    left join thjs.tb_projlist_main m
      on m.projid = i_projid;

  --项目类型
  select m.projtype
    into v_proj_type
    from thjs.tb_ib_cust_info m
   where m.projid = i_projid;

  --=========有效性验证========================================
  --批次处理：为空时，表示新批次，验证清单状态（必须为出单状态）
  if i_batch_id is null and
     v_projlist_status not in ('0', 'co', 'cl', 'cq') then
    o_return_msg  := '清单非出单状态，无法填报新批次！';
    o_return_code := -1;
    return;
  end if;

  --判断清单状态是否匹配，如不匹配返回错误（已有其他提交）
  if i_projlist_status <> v_projlist_status then
    o_return_msg  := '清单状态不匹配，请重新打开页面填报！';
    o_return_code := -1;
    return;
  end if;

  if i_ro_inout_date is not null and i_co_inout_date is not null and
     i_co_inout_date < i_ro_inout_date then
    o_return_msg  := '出观察清单日期不应早于入观察清单日期！';
    o_return_code := -1;
    return;
  end if;

  if i_rl_inout_date is not null and i_cl_inout_date is not null and
     i_cl_inout_date < i_rl_inout_date then
    o_return_msg  := '出限制清单日期不应早于入限制清单日期！';
    o_return_code := -1;
    return;
  end if;

  if i_rq_inout_date is not null and i_cq_inout_date is not null and
     i_cq_inout_date < i_rq_inout_date then
    o_return_msg  := '出静默期日期不应早于入静默期日期！';
    o_return_code := -1;
    return;
  end if;

  if i_projlist_status = 'ro' and i_co_inout_reason = '4' and
     (i_rq_inout_date is null or i_cq_inout_date is null) then
    o_return_msg  := '出观察转静默期有误，请联系系统管理员！';
    o_return_code := -1;
    return;
  end if;

  if i_projlist_status = 'rl' and i_cl_inout_reason = '4' and
     (i_rq_inout_date is null or i_cq_inout_date is null) then
    o_return_msg  := '出限制转静默期有误，请联系系统管理员！';
    o_return_code := -1;
    return;
  end if;

  if (i_ro_filepath is not null and i_ro_filepath like '%undefined') or
     (v_co_filepath is not null and v_co_filepath like '%undefined') or
     (i_rl_filepath is not null and i_rl_filepath like '%undefined') or
     (i_cl_filepath is not null and i_cl_filepath like '%undefined') or
     (i_rq_filepath is not null and i_rq_filepath like '%undefined') or
     (i_cq_filepath is not null and i_cq_filepath like '%undefined') then
    o_return_msg  := '附件上传有误，请联系系统管理员！';
    o_return_code := -1;
    return;
  end if;

  --为防止日期控件在不同浏览器中传入格式不同，统一重新截止日期格式为YYYY-MM-DD
  v_ro_inout_date := to_char(to_date(regexp_replace(i_ro_inout_date,
                                                    '[^0-9]',
                                                    ''),
                                     'YYYYMMDD'),
                             'YYYY-MM-DD');
  v_co_inout_date := to_char(to_date(regexp_replace(i_co_inout_date,
                                                    '[^0-9]',
                                                    ''),
                                     'YYYYMMDD'),
                             'YYYY-MM-DD');
  v_rl_inout_date := to_char(to_date(regexp_replace(i_rl_inout_date,
                                                    '[^0-9]',
                                                    ''),
                                     'YYYYMMDD'),
                             'YYYY-MM-DD');
  v_cl_inout_date := to_char(to_date(regexp_replace(i_cl_inout_date,
                                                    '[^0-9]',
                                                    ''),
                                     'YYYYMMDD'),
                             'YYYY-MM-DD');
  v_rq_inout_date := to_char(to_date(regexp_replace(i_rq_inout_date,
                                                    '[^0-9]',
                                                    ''),
                                     'YYYYMMDD'),
                             'YYYY-MM-DD');
  v_cq_inout_date := to_char(to_date(regexp_replace(i_cq_inout_date,
                                                    '[^0-9]',
                                                    ''),
                                     'YYYYMMDD'),
                             'YYYY-MM-DD');

  --
  if v_projlist_status = '0' then
    --未入单
    v_projlist_status_next := case
                                when v_ro_inout_date is not null then
                                 'ro'
                                when v_rl_inout_date is not null then
                                 'rl'
                                when v_rq_inout_date is not null then
                                 'rq'
                                else
                                 null
                              end;
  
  elsif v_projlist_status in ('ro', 'rl', 'rq') then
    --入观察清单，入限制清单，入静默期       
  
    v_projlist_status_next := 'c' || substr(v_projlist_status, 2);
  
  elsif v_projlist_status in ('co', 'cl', 'cq') then
    --出观察清单，出限制清单，出静默期
  
    --入清单,获取选中的入清单阶段
    v_projlist_status_next := case
                                when v_ro_inout_date is not null then
                                 'ro'
                                when v_rl_inout_date is not null then
                                 'rl'
                                when v_rq_inout_date is not null then
                                 'rq'
                                else
                                 null
                              end;
  
  else
    o_return_msg  := '清单状态有误，请联系系统管理员！';
    o_return_code := -1;
    return;
  
  end if;

  --清单填报实际阶段状态
  if v_projlist_status_next is not null then
  
    if (v_projlist_status_next = 'ro' and v_ro_inout_date is null) or
       (v_projlist_status_next = 'co' and v_co_inout_date is null) or
       (v_projlist_status_next = 'rl' and v_rl_inout_date is null) or
       (v_projlist_status_next = 'cl' and v_cl_inout_date is null) or
       (v_projlist_status_next = 'rq' and v_rq_inout_date is null) or
       (v_projlist_status_next = 'cq' and v_cq_inout_date is null) then
    
      o_return_msg  := '清单填报日期有误，请联系系统管理员！';
      o_return_code := -1;
      return;
    
    end if;
  
    --自动逻辑处理  
    if v_projlist_status_next = 'co' and i_co_inout_reason = '3' then
      --出观察转限制清单
    
      v_projlist_status_third := 'rl';
      v_rl_inout_date         := nvl(v_rl_inout_date, v_co_inout_date);
    
      if v_rl_inout_date is null then
        o_return_msg  := '转限制清单有误，请联系系统管理员！';
        o_return_code := -1;
        return;
      end if;
    elsif v_projlist_status_next = 'co' and i_co_inout_reason = '4' then
      --出观察转静默期
      v_projlist_status_third := 'rq';
      v_projlist_status_four  := 'cq';
    
      --自动静默期处理
      v_rq_inout_date := nvl(v_rq_inout_date, v_co_inout_date);
      if v_cq_inout_date is null or v_cq_inout_date = v_rq_inout_date then
      
        v_cq_inout_date := to_char(to_date(v_rq_inout_date, 'yyyy-MM-dd') +
                                   (case
                                      when v_proj_type like '%IPO%' then
                                       40
                                      else
                                       10
                                    end),
                                   'yyyy-MM-dd');
      end if;
    
    elsif v_projlist_status_next = 'cl' and i_co_inout_reason = '1' then
      --出限制，事由=价格利率确定
    
      v_projlist_status_third := 'rq';
      v_projlist_status_four  := 'cq';
    
      --自动静默期处理
      v_rq_inout_date := nvl(v_rq_inout_date, v_cl_inout_date);
      if v_cq_inout_date is null or v_cq_inout_date = v_rq_inout_date then
      
        v_cq_inout_date := to_char(to_date(v_rq_inout_date, 'yyyy-MM-dd') +
                                   (case
                                      when v_proj_type like '%IPO%' then
                                       40
                                      else
                                       10
                                    end),
                                   'yyyy-MM-dd');
      end if;
    
    elsif v_projlist_status_next = 'rq' then
      --手工入静默期
      v_projlist_status_third := 'cq';
    
      --自动静默期处理
      if v_cq_inout_date is null or v_cq_inout_date = v_rq_inout_date then
      
        v_cq_inout_date := to_char(to_date(v_rq_inout_date, 'yyyy-MM-dd') +
                                   (case
                                      when v_proj_type like '%IPO%' then
                                       40
                                      else
                                       10
                                    end),
                                   'yyyy-MM-dd');
      
      end if;
    
    end if;
  
  else
    o_return_msg  := '清单状态有误，请联系系统管理员！';
    o_return_code := -1;
    return;
  end if;

  --===========================================================
  --生成新的批次号
  if i_batch_id is null then
    v_batch_id := sys_guid();
    --新批次时，保存原批次，清空主表出入单绑定ID
    insert into thjs.tb_projlist_main_batch
      select * from thjs.tb_projlist_main t where t.projid = i_projid;
  
    update thjs.tb_projlist_main t
       set t.batch_id    = v_batch_id,
           t.robserve_id = null,
           t.cobserve_id = null,
           t.rlimit_id   = null,
           t.climit_id   = null,
           t.rquiet_id   = null,
           t.cquiet_id   = null
     where t.projid = i_projid;
    commit;
  else
    v_batch_id := i_batch_id;
  end if;

  if i_submit_status = '1' then
    --提交
  
    --根据清单状态，判断填报阶段，保存填报信息，更新主表 
    v_inout_id_next  := sys_guid();
    v_inout_id_third := sys_guid();
    v_inout_id_four  := sys_guid();
  
    --填报阶段
    if v_projlist_status_next is not null then
    
      insert into thjs.tb_projlist_inout
        (busidate,
         batch_id,
         inout_id,
         projid,
         inout_type,
         inout_direct,
         fill_date,
         inout_date,
         inout_reason,
         inout_remark,
         filepath,
         inout_user,
         inout_status,
         update_user,
         update_time)
      values
        (v_tradedate,
         v_batch_id,
         v_inout_id_next,
         i_projid,
         substr(v_projlist_status_next, 2), --取清单类型       
         decode(substr(v_projlist_status_next, 2), 'r', 'i', 'c', 'o'), --入出单
         v_filldate,
         decode(v_projlist_status_next,
                'ro',
                v_ro_inout_date,
                'rl',
                v_rl_inout_date,
                'rq',
                v_rq_inout_date,
                'co',
                v_co_inout_date,
                'cl',
                v_cl_inout_date,
                'cq',
                v_cq_inout_date),
         decode(v_projlist_status_next,
                'ro',
                i_ro_inout_reason,
                'rl',
                i_rl_inout_reason,
                'rq',
                i_rq_inout_reason,
                'co',
                i_co_inout_reason,
                'cl',
                i_cl_inout_reason,
                'cq',
                i_cq_inout_reason),
         decode(v_projlist_status_next,
                'ro',
                i_ro_inout_remark,
                'rl',
                i_rl_inout_remark,
                'rq',
                i_rq_inout_remark,
                'co',
                i_co_inout_remark,
                'cl',
                i_cl_inout_remark,
                'cq',
                i_cq_inout_remark),
         decode(v_projlist_status_next,
                'ro',
                i_ro_filepath,
                'rl',
                i_rl_filepath,
                'rq',
                i_rq_filepath,
                'co',
                i_co_filepath,
                'cl',
                i_cl_filepath,
                'cq',
                i_cq_filepath),
         i_usercode,
         i_submit_status,
         i_usercode,
         sysdate);
    
      --根据清单状态更新主表
      if v_projlist_status = '0' then
        --未入单
        insert into thjs.tb_projlist_main
          (busidate,
           projid,
           gtjarole,
           --multistk_id,
           batch_id,
           robserve_id,
           rlimit_id,
           rquiet_id,
           projlist_status,
           update_user,
           create_user)
          select v_tradedate,
                 c.projid,
                 '',
                 v_batch_id,
                 decode(v_projlist_status_next, 'ro', v_inout_id_next, ''),
                 decode(v_projlist_status_next, 'rl', v_inout_id_next, ''),
                 decode(v_projlist_status_next, 'rq', v_inout_id_next, ''),
                 v_projlist_status_next,
                 i_usercode,
                 i_usercode
            from thjs.tb_ib_cust_info c
           where c.projid = i_projid;
        commit;
      
      else
        --已入单，更新主表
        update thjs.tb_projlist_main p
           set p.robserve_id     = decode(v_projlist_status_next,
                                          'ro',
                                          v_inout_id_next,
                                          p.robserve_id),
               p.cobserve_id     = decode(v_projlist_status_next,
                                          'co',
                                          v_inout_id_next,
                                          p.cobserve_id),
               p.rlimit_id       = decode(v_projlist_status_next,
                                          'rl',
                                          v_inout_id_next,
                                          p.rlimit_id),
               p.climit_id       = decode(v_projlist_status_next,
                                          'cl',
                                          v_inout_id_next,
                                          p.climit_id),
               p.rquiet_id       = decode(v_projlist_status_next,
                                          'rq',
                                          v_inout_id_next,
                                          p.rquiet_id),
               p.cquiet_id       = decode(v_projlist_status_next,
                                          'cq',
                                          v_inout_id_next,
                                          p.cquiet_id),
               p.projlist_status = v_projlist_status_next,
               p.update_user     = i_usercode,
               p.update_time     = sysdate
         where p.projid = i_projid;
      
        commit;
      
      end if;
    
    end if;
  
    --自动阶段1
    if v_projlist_status_third is not null then
    
      insert into thjs.tb_projlist_inout
        (busidate,
         batch_id,
         inout_id,
         projid,
         inout_type,
         inout_direct,
         fill_date,
         inout_date,
         inout_reason,
         inout_remark,
         filepath,
         inout_user,
         inout_status,
         update_user,
         update_time)
      values
        (v_tradedate,
         v_batch_id,
         v_inout_id_third,
         i_projid,
         substr(v_projlist_status_third, 2), --取清单类型       
         decode(substr(v_projlist_status_third, 2), 'r', 'i', 'c', 'o'), --入出单
         v_filldate,
         decode(v_projlist_status_third,
                'ro',
                v_ro_inout_date,
                'rl',
                v_rl_inout_date,
                'rq',
                v_rq_inout_date,
                'co',
                v_co_inout_date,
                'cl',
                v_cl_inout_date,
                'cq',
                v_cq_inout_date),
         decode(v_projlist_status_third,
                'ro',
                i_ro_inout_reason,
                'rl',
                i_rl_inout_reason,
                'rq',
                i_rq_inout_reason,
                'co',
                i_co_inout_reason,
                'cl',
                i_cl_inout_reason,
                'cq',
                i_cq_inout_reason),
         decode(v_projlist_status_third,
                'ro',
                i_ro_inout_remark,
                'rl',
                i_rl_inout_remark,
                'rq',
                i_rq_inout_remark,
                'co',
                i_co_inout_remark,
                'cl',
                i_cl_inout_remark,
                'cq',
                i_cq_inout_remark),
         decode(v_projlist_status_third,
                'ro',
                i_ro_filepath,
                'rl',
                i_rl_filepath,
                'rq',
                i_rq_filepath,
                'co',
                i_co_filepath,
                'cl',
                i_cl_filepath,
                'cq',
                i_cq_filepath),
         i_usercode,
         i_submit_status,
         i_usercode,
         sysdate);
    
      --已入单，更新主表
      update thjs.tb_projlist_main p
         set p.robserve_id     = decode(v_projlist_status_third,
                                        'ro',
                                        v_inout_id_third,
                                        p.robserve_id),
             p.cobserve_id     = decode(v_projlist_status_third,
                                        'co',
                                        v_inout_id_third,
                                        p.cobserve_id),
             p.rlimit_id       = decode(v_projlist_status_third,
                                        'rl',
                                        v_inout_id_third,
                                        p.rlimit_id),
             p.climit_id       = decode(v_projlist_status_third,
                                        'cl',
                                        v_inout_id_third,
                                        p.climit_id),
             p.rquiet_id       = decode(v_projlist_status_third,
                                        'rq',
                                        v_inout_id_third,
                                        p.rquiet_id),
             p.cquiet_id       = decode(v_projlist_status_third,
                                        'cq',
                                        v_inout_id_third,
                                        p.cquiet_id),
             p.projlist_status = v_projlist_status_third,
             p.update_user     = i_usercode,
             p.update_time     = sysdate
       where p.projid = i_projid;
    
      commit;
    
    end if;
  
    --自动阶段2
    if v_projlist_status_four is not null then
    
      insert into thjs.tb_projlist_inout
        (busidate,
         batch_id,
         inout_id,
         projid,
         inout_type,
         inout_direct,
         fill_date,
         inout_date,
         inout_reason,
         inout_remark,
         filepath,
         inout_user,
         inout_status,
         update_user,
         update_time)
      values
        (v_tradedate,
         v_batch_id,
         v_inout_id_four,
         i_projid,
         substr(v_projlist_status_four, 2), --取清单类型       
         decode(substr(v_projlist_status_four, 2), 'r', 'i', 'c', 'o'), --入出单
         v_filldate,
         decode(v_projlist_status_four,
                'ro',
                v_ro_inout_date,
                'rl',
                v_rl_inout_date,
                'rq',
                v_rq_inout_date,
                'co',
                v_co_inout_date,
                'cl',
                v_cl_inout_date,
                'cq',
                v_cq_inout_date),
         decode(v_projlist_status_four,
                'ro',
                i_ro_inout_reason,
                'rl',
                i_rl_inout_reason,
                'rq',
                i_rq_inout_reason,
                'co',
                i_co_inout_reason,
                'cl',
                i_cl_inout_reason,
                'cq',
                i_cq_inout_reason),
         decode(v_projlist_status_four,
                'ro',
                i_ro_inout_remark,
                'rl',
                i_rl_inout_remark,
                'rq',
                i_rq_inout_remark,
                'co',
                i_co_inout_remark,
                'cl',
                i_cl_inout_remark,
                'cq',
                i_cq_inout_remark),
         decode(v_projlist_status_four,
                'ro',
                i_ro_filepath,
                'rl',
                i_rl_filepath,
                'rq',
                i_rq_filepath,
                'co',
                i_co_filepath,
                'cl',
                i_cl_filepath,
                'cq',
                i_cq_filepath),
         i_usercode,
         i_submit_status,
         i_usercode,
         sysdate);
    
      --已入单，更新主表
      update thjs.tb_projlist_main p
         set p.robserve_id     = decode(v_projlist_status_four,
                                        'ro',
                                        v_inout_id_third,
                                        p.robserve_id),
             p.cobserve_id     = decode(v_projlist_status_four,
                                        'co',
                                        v_inout_id_third,
                                        p.cobserve_id),
             p.rlimit_id       = decode(v_projlist_status_four,
                                        'rl',
                                        v_inout_id_third,
                                        p.rlimit_id),
             p.climit_id       = decode(v_projlist_status_four,
                                        'cl',
                                        v_inout_id_third,
                                        p.climit_id),
             p.rquiet_id       = decode(v_projlist_status_four,
                                        'rq',
                                        v_inout_id_third,
                                        p.rquiet_id),
             p.cquiet_id       = decode(v_projlist_status_four,
                                        'cq',
                                        v_inout_id_third,
                                        p.cquiet_id),
             p.projlist_status = v_projlist_status_four,
             p.update_user     = i_usercode,
             p.update_time     = sysdate
       where p.projid = i_projid;
    
      commit;
    
    end if;
  
  end if;

  --因关联信息存在置空情况，故关联信息批次代码fill_id应主动清空。并由关联信息修改sp去更新
  update thjs.tb_projlist_main p
     set p.multistk_id = ''
   where p.projid = i_projid;
  commit;

  --由于实际操作日期与出入单发生日期（页面输入）不一定一致，需根据清单各阶段日期取值，重新计算状态字段
  merge into thjs.tb_projlist_main p
  using (select t.projid,
                t.projname,
                t.ro_inout_date,
                t.co_inout_date,
                t.rl_inout_date,
                t.cl_inout_date,
                t.rq_inout_date,
                t.cq_inout_date,
                case
                  when (t.ro_inout_date is not null and
                       t.ro_inout_date <= to_char(sysdate, 'yyyy-MM-dd')) and
                       (t.co_inout_date is null or
                       t.co_inout_date > to_char(sysdate, 'yyyy-MM-dd')) and
                       t.rl_inout_date is null and t.rq_inout_date is null then
                   'ro'
                  when (t.rl_inout_date is null or
                       t.rl_inout_date > to_char(sysdate, 'yyyy-MM-dd')) and
                       (t.co_inout_date is not null and
                       t.co_inout_date <= to_char(sysdate, 'yyyy-MM-dd')) and
                       (t.rq_inout_date is null or
                       t.rq_inout_date > to_char(sysdate, 'yyyy-MM-dd')) then
                   'co'
                  when (t.rl_inout_date is not null and
                       t.rl_inout_date <= to_char(sysdate, 'yyyy-MM-dd')) and
                       (t.cl_inout_date is null or
                       t.cl_inout_date > to_char(sysdate, 'yyyy-MM-dd')) then
                   'rl'
                  when (t.rq_inout_date is null or
                       t.rq_inout_date > to_char(sysdate, 'yyyy-MM-dd')) and
                       (t.cl_inout_date is not null and
                       t.cl_inout_date <= to_char(sysdate, 'yyyy-MM-dd')) and
                       t.rq_inout_date is null then
                   'cl'
                  when (t.rq_inout_date is not null and
                       t.rq_inout_date <= to_char(sysdate, 'yyyy-MM-dd')) and
                       (t.cq_inout_date is null or
                       t.cq_inout_date > to_char(sysdate, 'yyyy-MM-dd')) then
                   'rq'
                  when t.cq_inout_date is not null and
                       t.cq_inout_date <= to_char(sysdate, 'yyyy-MM-dd') then
                   'cq'
                  else
                   '0'
                end as calc_status,
                t.projlist_status
           from THJS.VW_PROJLIST_MAIN_INOUT t
          where t.projid = i_projid) t
  on (p.projid = t.projid)
  when matched then
    update set p.projlist_status = t.calc_status;
  commit;

  --刷新清单所有入出单记录检查结果
  merge into thjs.tb_projlist_check c
  using (select i.busidate,
                i.projid,
                i.inout_id,
                case
                  when date_diff <= 0 then
                   '0'
                  else
                   '1'
                end as check_flag,
                case
                  when date_diff < 0 then
                   '早' || abs(i.date_diff) || '天'
                  when date_diff = 0 then
                   '准确'
                  else
                   '晚' || abs(i.date_diff) || '天'
                end as check_result
           from (select i.*,
                        to_date(i.fill_date, 'yyyy-MM-dd') -
                        to_date(i.inout_date, 'yyyy-MM-dd') as date_diff
                   from thjs.tb_projlist_inout i
                  where i.projid = i_projid) i) i
  on (c.projid = i.projid and c.inout_id = i.inout_id)
  when matched then
    update set c.check_flag = i.check_flag, c.check_result = i.check_result
  when not matched then
    insert
      (BUSIDATE,
       PROJID,
       INOUT_ID,
       CHECK_FLAG,
       CHECK_RESULT,
       CHECK_USER,
       CREATE_TIME)
    values
      (i.busidate,
       i.projid,
       i.inout_id,
       i.check_flag,
       i.check_result,
       'admin',
       sysdate);

  commit;

  o_return_msg  := '执行成功';
  o_return_code := 0;

  /*insert into thjs.tb_test
    (id, text)
  values
    (95, o_return_msg || '-' || o_return_code);*/

exception
  -- 非预定义异常处理
  when v_userexp then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    thjs.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
    -- 预定义异常处理
  when others then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    thjs.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
end;

