                                'rlf',
                                t.rl_fill_date,
                                'cli',
                                t.cl_inout_date,
                                'clf',
                                t.cl_fill_date,
                                'rqi',
                                t.rq_inout_date,
                                'rqf',
                                t.rq_fill_date,
                                'cqi',
                                t.cq_inout_date,
                                'cqf',
                                t.cq_fill_date),
                         '-',
                         '') between v_begindate and v_enddate;
  end if;

  if i_page_size is not null and i_page_size <> 0 then
    v_page_size := i_page_size;
  else
    v_page_size := o_total_count;
  end if;
  
        open rt_cursor for
        select * from (
          select t.*,t.DEPTNAME AS STAFF_DEPT_NAME,rownum as rn 
            from thjs.tmp_projlist_main_mq_v2 t 
           where replace(decode(v_projstatus_flag,
                                'roi',
                                t.ro_inout_date,
                                'rof',
                                t.ro_fill_date,
                                'coi',
                                t.co_inout_date,
                                'cof',
                                t.co_fill_date,
                                'rli',
                                t.rl_inout_date,
                                'rlf',
                                t.rl_fill_date,
                                'cli',
                                t.cl_inout_date,
                                'clf',
                                t.cl_fill_date,
                                'rqi',
                                t.rq_inout_date,
                                'rqf',
                                t.rq_fill_date,
                                'cqi',
                                t.cq_inout_date,
                                'cqf',
                                t.cq_fill_date),
                         '-',
                         '') between v_begindate and v_enddate)
     where rn > v_page_num
       and rn <= v_page_num + v_page_size;
      
      end if;
    end if;
  
  end if;

  commit;

  o_return_msg  := '执行成功';
  o_return_code := 0;

exception
  -- 非预定义异常处理
  when v_userexp then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    thjs.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
    -- 预定义异常处理
  when others then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    thjs.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
end;

Create or Replace procedure "THJS"."P_PROJLIST_MAIN_MQ_TEST" (rt_cursor out sys_refcursor, --返回游标结果集
                                                         --i_projname    in varchar2,--项目名称 
                                                         i_khname      in varchar2, --客户名称
                                                         i_stkcode     in varchar2, --证券代码
                                                         i_stkname     in varchar2, --股票简称
                                                         i_projtype    in varchar2, --业务类型
                                                         i_director    in varchar2, --项目负责人
                                                         i_deptname    in varchar2, --部门名称
                                                         i_listtype    in varchar2, --清单类型：0 所有，1 观察清单，2 限制清单，3 静默期
                                                         i_inouttype   in varchar2, --出入单类型：0 全部 1 入单 2 出单
                                                         i_datetype    in varchar2, --日期类型：0 全部 1 发生日期 2 填报日期
                                                         i_begindate   in varchar2, --起始日期
                                                         i_enddate     in varchar2, --截止日期
                                                         i_username    in varchar2, --登录人
                                                         o_return_msg  out varchar2,
                                                         o_return_code out integer) is
  ----------------------------------------------------------------------------------
  --版    权：GTJA
  --版    本：1.0.0
  --开发人员：CZC@GTJA
  --创建日期：20191029
  --模块编号：
  --模块名称：清单管理 - 我管理的清单信息查询 更新
  --功能名称：我管理的清单信息查询
  ----------------------------------------------------------------------------------
  --==============================================================================
  --固定变量
  v_userexp exception; -- 用户定义错
  v_tradedate    varchar2(8); -- 任务执行时间(业务日期)
  v_exec_func_id integer default '0'; -- 任务id
  v_func_own     varchar2(20) default 'thjs'; -- 任务归属用户（schema）
  v_func_name    varchar2(2000) default 'p_projlist_main_mq_test'; -- 任务名称(存储过程的名字)
  v_sqlerrm      varchar2(4000); -- 错误提示信息
  v_sqlcode      number; -- 错误代码
  v_sqlerrl      varchar2(4000); -- 错误行号
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  v_superuser  integer default 0;
  v_user_pcode varchar2(100);
  v_pcode      varchar2(100);

  v_role_flag        varchar2(200); --角色数据权限标识
  v_po_flag          varchar2(4); --观察清单数据权限标识
  v_pl_flag          varchar2(4); --限制清单数据权限标识
  v_pq_flag          varchar2(4); --静默期数据权限标识
  v_listtype_status  varchar2(4); --清单类型
  v_inouttype_status varchar2(4); --出入单类型
  v_projlist_status  varchar2(4); --出入单状态

  v_date_flag       varchar2(4); --日期条件标识
  v_begindate       varchar2(8); --起始日期YYYYMMDD
  v_enddate         varchar2(8); --截止日期YYYYMMDD
  v_listdate_flag   varchar2(4); --阶段日期类型
  v_inoutdate_flag  varchar2(4); --出入日期类型
  v_projstatus_flag varchar2(4); --阶段出入日期类型
  --=============================================================
  -- 业务处理过程
  --=============================================================

begin

  v_tradedate := to_char(sysdate, 'yyyyMMdd');
  v_begindate := nvl(replace(i_begindate, '-', ''), '19000101');
  v_enddate   := nvl(replace(i_enddate, '-', ''), '29991231');

  --判断是否超级用户
  select count(1)
    into v_superuser
    from table(kingstar.splitstr('admin', ',')) t
   where instr(',' || t.column_value || ',', ',' || i_username || ',') > 0;

  --获取用户角色
  --业务人员：本人所填项目
  --团队/部门负责人：团队/本部门全部项目
  --投行合规组人员：投行部门全部项目
  --合规部专门人员：全部部门

  --暂时展示所有数据，等待数据权限确认

  --角色部分数据权限实现
  --“观察清单管理角色”仅具有观察阶段数据权限
  --“限制清单管理角色”仅具有限制阶段数据权限
  --“静默期管理角色”仅具有静默阶段数据权限
  --其余默认视为全部，由菜单本身控制查询权限
  --权限标识区分：ALL，PO，PL，PQ

  select to_char(wm_concat(decode(r.role_id,
                                  'projlist_o',
                                  'PO',
                                  'projlist_l',
                                  'PL',
                                  'projlist_q',
                                  'PQ',
                                  'ALL'))) as role_flag
    into v_role_flag
    from BASIC_THJS.wb_user u
    left join BASIC_THJS.wb_user_role ur
      on ur.user_id = u.user_id
    left join BASIC_THJS.wb_role r
      on r.role_id = ur.role_id
   where u.user_name = i_username;

  --权限标识 含有上述三种其中一种权限配置的角色，查询时过滤
  if instr(v_role_flag, 'PO') > 0 or instr(v_role_flag, 'PL') > 0 or
     instr(v_role_flag, 'PQ') > 0 then
  
    v_po_flag := case
                   when instr(v_role_flag, 'PO') > 0 then
                    '1'
                   else
                    '0'
                 end;
  
    v_pl_flag := case
                   when instr(v_role_flag, 'PL') > 0 then
                    '1'
                   else
                    '0'
                 end;
  
    v_pq_flag := case
                   when instr(v_role_flag, 'PQ') > 0 then
                    '1'
                   else
                    '0'
                 end;
  else
    v_po_flag := '2';
    v_pl_flag := '2';
    v_pq_flag := '2';
  end if;

  /**
  清单类型，出入单类型，日期类型，起始截止日期  过滤逻辑
  如选择了起始截止日期，清单类型、出入单类型、日期类型，优先作用于对应状态的发生或填报日期，如其中一项未选择，默认作用于所有日期
  如未选择起始截止日期，清单类型、出入单类型直接作用于清单状态，日期类型无效
  **/

  --根据清单类型及出入单类型，确认查询的清单状态及比较日期
  --ro,co,rl,cl,rq,cq
  v_listtype_status := case
                         when i_listtype = '1' then
                          'o'
                         when i_listtype = '2' then
                          'l'
                         when i_listtype = '3' then
                          'q'
                         else
                          '0'
                       end;
  v_inouttype_status := case
                          when i_inouttype = '1' then
                           'r'
                          when i_inouttype = '2' then
                           'c'
                          else
                           '0'
                        end;
  v_projlist_status  := v_inouttype_status || v_listtype_status;
  v_date_flag := case
                   when v_begindate is null and v_enddate is null then
                    '0'
                   else
                    '1'
                 end;

  --条件判断复杂，插入临时表，根据不同条件，进行不同过滤返回
  execute immediate 'truncate table thjs.tmp_projlist_main_mq';

  insert into thjs.tmp_projlist_main_mq
    select p.projid, --项目编号
           p.projname, --项目名称
           p.projtype, --项目类型
           p.deptname, --部门名称
           p.deptmananame, --项目负责人
           p.update_user as report_user, --填报人员
           p.custid, --客户编号
           p.custname, --客户名称
           case
             when p.stkcode is not null and p.stkcode not like 'A%' and --剔除临时代码A开头
                  m.stkcode is not null then
              p.stkcode || ',' || m.stkcode
             when p.stkcode is not null and p.stkcode not like 'A%' and
                  m.stkcode is null then
              p.stkcode
             else
              m.stkcode
           end as stkcode, --证券代码
           case
             when p.stkname is not null and p.stkcode not like 'A%' and
                  m.stkname is not null then
              p.stkname || ',' || m.stkname
             when p.stkname is not null and p.stkcode not like 'A%' and
                  m.stkname is null then
              p.stkname
             else
              m.stkname
           end as stkname, --证券名称
           p.gtjarole, --我司角色
           p.projlist_status, --清单状态
           ro.inout_date as ro_inout_date, --入观察清单日期
           ro.fill_date as ro_fill_date, --入观察清单填报日期
           ro.check_result as ro_check_result, --入观察清单检查结果
           co.inout_date as co_inout_date, --出观察清单日期
           co.fill_date as co_fill_date, --出观察清单填报日期
           co.check_result as co_check_result, --出观察清单检查结果           
           rl.inout_date as rl_inout_date, --入限制清单日期
           rl.fill_date as rl_fill_date, --入限制清单填报日期
           rl.check_result as rl_check_result, --入限制清单检查结果           
           cl.inout_date as cl_inout_date, --出限制清单日期
           cl.fill_date as cl_fill_date, --出限制清单填报日期
           cl.check_result as cl_check_result, --出限制清单检查结果 
           rq.inout_date as rq_inout_date, --静默期起始日期
           rq.fill_date as rq_fill_date, --静默期起始日期
           cq.inout_date as cq_inout_date, --静默期截止日期
           cq.fill_date as cq_fill_date --静默期截止日期
      from thjs.vw_projlist_main p
      left join thjs.vw_projlist_inout ro
        on ro.inout_id = p.robserve_id
       and v_po_flag <> '0' --有观察清单权限
      left join thjs.vw_projlist_inout co
        on co.inout_id = p.cobserve_id
       and v_po_flag <> '0'
      left join thjs.vw_projlist_inout rl
        on rl.inout_id = p.rlimit_id
       and v_pl_flag <> '0' --有限制清单权限
      left join thjs.vw_projlist_inout cl
        on cl.inout_id = p.climit_id
       and v_pl_flag <> '0'
      left join thjs.vw_projlist_inout rq
        on rq.inout_id = p.rquiet_id
       and v_pq_flag <> '0' --有静默期权限
      left join thjs.vw_projlist_inout cq
        on cq.inout_id = p.cquiet_id
       and v_pq_flag <> '0'
      left join (select m.projid,
                        m.fill_id，to_char(wm_concat(m.stk_code)) as stkcode,
                        to_char(wm_concat(m.stk_name)) as stkname
                   from thjs.tb_projlist_multistk m
                  where not exists (select 1
                           from thjs.vw_projlist_main p
                          where p.projid = m.projid
                            and p.multistk_id = m.fill_id
                            and p.stkcode = m.stk_code) --与客户主表代码一致的不显示
                  group by m.projid, m.fill_id) m
        on m.projid = p.projid
       and m.fill_id = p.multistk_id
     where (i_khname is null or instr(p.custname, i_khname) > 0)
       and (i_stkcode is null or instr(p.stkcode, i_stkcode) > 0)
       and (i_stkname is null or instr(p.stkname, i_stkname) > 0)
       and (i_projtype is null or p.projtype = i_projtype)
       and (i_director is null or exists
            (select 1
               from thjs.ib_v_finance_projmember fp
              inner join BASIC_THJS.wb_user u
                 on u.user_id = fp.workno
              where fp.proj_id = p.projid
                and fp.projrole = '项目负责人'
                and u.user_name = i_director))
       and (i_deptname is null or instr(p.deptname, i_deptname) > 0)
       and ((v_po_flag = '2' or
           (v_po_flag = '1' and p.projlist_status = 'ro')) or
           (v_pl_flag = '2' or
           (v_pl_flag = '1' and p.projlist_status = 'rl')) or
           (v_pq_flag = '2' or
           (v_pq_flag = '1' and p.projlist_status = 'rq')))
     order by p.source_flag, p.update_time desc;
  commit;

  if v_date_flag = '0' then
    --无日期条件，日期类型条件无效
    --清单类型、出入单类型作用于清单状态
    open rt_cursor for
      select *
        from thjs.tmp_projlist_main_mq t
       where (v_listtype_status = '0' or
             instr(t.projlist_status, v_listtype_status) > 0) --无清单类型条件，或作用于状态过滤
         and (v_inouttype_status = '0' or
             instr(t.projlist_status, v_inouttype_status) > 0); --无出入单类型条件，或作用于状态过滤
  
  else
    --有日期条件，日期类型决定使用发生日期还是填报日期
    --清单类型、出入单类型作用于具体日期
  
    if v_listtype_status = '0' and v_inouttype_status = '0' then
      --无清单类型、出入单类型作用于多日期
    
      --根据日期类型决定，作用于那些日期
      if i_datetype is null or i_datetype = '0' then
        open rt_cursor for
          select *
            from thjs.tmp_projlist_main_mq t
           where replace(t.ro_inout_date, '-', '') between v_begindate and
                 v_enddate
              or replace(t.ro_fill_date, '-', '') between v_begindate and
                 v_enddate
              or replace(t.co_inout_date, '-', '') between v_begindate and
                 v_enddate
              or replace(t.co_fill_date, '-', '') between v_begindate and
                 v_enddate
              or replace(t.rl_inout_date, '-', '') between v_begindate and
                 v_enddate
              or replace(t.rl_fill_date, '-', '') between v_begindate and
                 v_enddate
              or replace(t.cl_inout_date, '-', '') between v_begindate and
                 v_enddate
              or replace(t.cl_fill_date, '-', '') between v_begindate and
                 v_enddate
              or replace(t.rq_inout_date, '-', '') between v_begindate and
                 v_enddate
              or replace(t.rq_fill_date, '-', '') between v_begindate and
                 v_enddate
              or replace(t.cq_inout_date, '-', '') between v_begindate and
                 v_enddate
              or replace(t.cq_fill_date, '-', '') between v_begindate and
                 v_enddate;
      
      else
        open rt_cursor for
          select *
            from thjs.tmp_projlist_main_mq t
           where replace(decode(i_datetype,
                                '1',
                                t.ro_inout_date,
                                t.ro_fill_date),
                         '-',
                         '') between v_begindate and v_enddate
              or replace(decode(i_datetype,
                                '1',
                                t.co_inout_date,
                                t.co_fill_date),
                         '-',
                         '') between v_begindate and v_enddate
              or replace(decode(i_datetype,
                                '1',
                                t.rl_inout_date,
                                t.rl_fill_date),
                         '-',
                         '') between v_begindate and v_enddate
              or replace(decode(i_datetype,
                                '1',
                                t.cl_inout_date,
                                t.cl_fill_date),
                         '-',
                         '') between v_begindate and v_enddate
              or replace(decode(i_datetype,
                                '1',
                                t.rq_inout_date,
                                t.rq_fill_date),
                         '-',
                         '') between v_begindate and v_enddate
              or replace(decode(i_datetype,
                                '1',
                                t.cq_inout_date,
                                t.cq_fill_date),
                         '-',
                         '') between v_begindate and v_enddate;
      end if;
    elsif v_listtype_status <> '0' and v_inouttype_status = '0' then
      --有清单类型、无出入单类型作用于对应清单日期
    
      --根据日期类型决定，作用于那些日期
      if i_datetype is null or i_datetype = '0' then
        open rt_cursor for
          select *
            from thjs.tmp_projlist_main_mq t
           where replace(decode(v_listtype_status,
                                'o',
                                t.ro_inout_date,
                                'l',
                                t.rl_inout_date,
                                'q',
                                t.rq_inout_date),
                         '-',
                         '') between v_begindate and v_enddate
              or replace(decode(v_listtype_status,
                                'o',
                                t.ro_fill_date,
                                'l',
                                t.rl_fill_date,
                                'q',
                                t.rq_fill_date),
                         '-',
                         '') between v_begindate and v_enddate
              or replace(decode(v_listtype_status,
                                'o',
                                t.co_inout_date,
                                'l',
                                t.cl_inout_date,
                                'q',
                                t.cq_inout_date),
                         '-',
                         '') between v_begindate and v_enddate
              or replace(decode(v_listtype_status,
                                'o',
                                t.co_fill_date,
                                'l',
                                t.cl_fill_date,
                                'q',
                                t.cq_fill_date),
                         '-',
                         '') between v_begindate and v_enddate;
      
      else
      
        v_listdate_flag := v_listtype_status || case
                             when i_datetype = '1' then
                              'i'
                             else
                              'f'
                           end;
        open rt_cursor for
          select *
            from thjs.tmp_projlist_main_mq t
           where replace(decode(v_listdate_flag,
                                'oi',
                                t.ro_inout_date,
                                'of',
                                t.ro_fill_date,
                                'li',
                                t.rl_inout_date,
                                'lf',
                                t.rl_fill_date,
                                'qi',
                                t.rq_inout_date,
                                'qf',
                                t.rq_fill_date),
                         '-',
                         '') between v_begindate and v_enddate
              or replace(decode(v_listdate_flag,
                                'oi',
                                t.co_inout_date,
                                'of',
                                t.co_fill_date,
                                'li',
                                t.cl_inout_date,
                                'lf',
                                t.cl_fill_date,
                                'qi',
                                t.cq_inout_date,
                                'qf',
                                t.cq_fill_date),
                         '-',
                         '') between v_begindate and v_enddate;
      
      end if;
    elsif v_listtype_status = '0' and v_inouttype_status <> '0' then
      --无清单类型、有出入单类型作用于对应清单日期
    
      --根据日期类型决定，作用于那些日期
      if i_datetype is null or i_datetype = '0' then
        open rt_cursor for
          select *
            from thjs.tmp_projlist_main_mq t
           where replace(decode(v_inouttype_status,
                                'r',
                                t.ro_inout_date,
                                'c',
                                t.co_inout_date),
                         '-',
                         '') between v_begindate and v_enddate
              or replace(decode(v_inouttype_status,
                                'r',
                                t.ro_fill_date,
                                'c',
                                t.co_fill_date),
                         '-',
                         '') between v_begindate and v_enddate
              or replace(decode(v_inouttype_status,
                                'r',
                                t.rl_inout_date,
                                'c',
                                t.cl_inout_date),
                         '-',
                         '') between v_begindate and v_enddate
              or replace(decode(v_inouttype_status,
                                'r',
                                t.rl_fill_date,
                                'c',
                                t.cl_fill_date),
                         '-',
                         '') between v_begindate and v_enddate
              or replace(decode(v_inouttype_status,
                                'r',
                                t.rq_inout_date,
                                'c',
                                t.cq_inout_date),
                         '-',
                         '') between v_begindate and v_enddate
              or replace(decode(v_inouttype_status,
                                'r',
                                t.rq_fill_date,
                                'c',
                                t.cq_fill_date),
                         '-',
                         '') between v_begindate and v_enddate;
      
      else
      
        v_inoutdate_flag := v_inouttype_status || case
                              when i_datetype = '1' then
                               'i'
                              else
                               'f'
                            end;
      
        open rt_cursor for
          select *
            from thjs.tmp_projlist_main_mq t
           where replace(decode(v_inoutdate_flag,
                                'ri',
                                t.ro_inout_date,
                                'rf',
                                t.ro_fill_date,
                                'ci',
                                t.co_inout_date,
                                'cf',
                                t.co_fill_date),
                         '-',
                         '') between v_begindate and v_enddate
              or replace(decode(v_inoutdate_flag,
                                'ri',
                                t.rl_inout_date,
                                'rf',
                                t.rl_fill_date,
                                'ci',
                                t.cl_inout_date,
                                'cf',
                                t.cl_fill_date),
                         '-',
                         '') between v_begindate and v_enddate
              or replace(decode(v_inoutdate_flag,
                                'ri',
                                t.rq_inout_date,
                                'rf',
                                t.rq_fill_date,
                                'ci',
                                t.cq_inout_date,
                                'cf',
                                t.cq_fill_date),
                         '-',
                         '') between v_begindate and v_enddate;
      
      end if;
    else
      --有清单类型、有出入单类型作用于对应清单日期
    
      --根据日期类型决定，作用于那些日期
      if i_datetype is null or i_datetype = '0' then
        open rt_cursor for
          select *
            from thjs.tmp_projlist_main_mq t
           where replace(decode(v_projlist_status,
                                'ro',
                                t.ro_inout_date,
                                'co',
                                t.co_inout_date,
                                'rl',
                                t.rl_inout_date,
                                'cl',
                                t.cl_inout_date,
                                'rq',
                                t.rq_inout_date,
                                'cq',
                                t.rq_inout_date),
                         '-',
                         '') between v_begindate and v_enddate
              or replace(decode(v_projlist_status,
                                'ro',
                                t.ro_fill_date,
                                'co',
                                t.co_fill_date,
                                'rl',
                                t.rl_fill_date,
                                'cl',
                                t.cl_fill_date,
                                'rq',
                                t.rq_fill_date,
                                'cq',
                                t.rq_fill_date),
                         '-',
                         '') between v_begindate and v_enddate;
      
      else
      
        v_projstatus_flag := v_projlist_status || case
                               when i_datetype = '1' then
                                'i'
                               else
                                'f'
                             end;
      
        open rt_cursor for
          select *
            from thjs.tmp_projlist_main_mq t
           where replace(decode(v_projstatus_flag,
                                'roi',
                                t.ro_inout_date,
                                'rof',
                                t.ro_fill_date,
                                'coi',
                                t.co_inout_date,
                                'cof',
                                t.co_fill_date,
                                'rli',
                                t.rl_inout_date,
                                'rlf',
                                t.rl_fill_date,
                                'cli',
                                t.cl_inout_date,
                                'clf',
                                t.cl_fill_date,
                                'rqi',
                                t.rq_inout_date,
                                'rqf',
                                t.rq_fill_date,
                                'cqi',
                                t.rq_inout_date,
                                'cqf',
                                t.rq_fill_date),
                         '-',
                         '') between v_begindate and v_enddate;
      
      end if;
    end if;
  
  end if;

  commit;

  o_return_msg  := '执行成功';
  o_return_code := 0;

exception
  -- 非预定义异常处理
  when v_userexp then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    hgman.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
    -- 预定义异常处理
  when others then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    hgman.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
end;

Create or Replace procedure "THJS"."P_PROJLIST_MAIN_Q" (rt_cursor     out sys_refcursor, --返回游标结果集

                                                   i_projid      in varchar2, --项目编号，接口传入指定项目

                                                   i_username    in varchar2,

                                                   i_projname    in varchar2,

                                                   i_khname      in varchar2,

                                                   i_page_num    in number default 0, --默认值0,

                                                   i_page_size   in number default 0, --默认值0  如果i_page_num，i_page_size都为0 则不分页，查询全部

                                                   o_total_count out integer,

                                                   o_return_msg  out varchar2,

                                                   o_return_code out integer) is

  ----------------------------------------------------------------------------------

  --版    权：GTJA

  --版    本：1.0.0

  --开发人员：CZC@GTJA

  --创建日期：20190426

  --模块编号：

  --模块名称：清单管理 - 清单信息查询

  --功能名称：清单信息查询

  ----------------------------------------------------------------------------------

  --==============================================================================

  --固定变量

  v_userexp exception; -- 用户定义错

  v_tradedate    varchar2(8); -- 任务执行时间(业务日期)

  v_exec_func_id integer default '0'; -- 任务id

  v_func_own     varchar2(20) default 'thjs'; -- 任务归属用户（schema）

  v_func_name    varchar2(2000) default 'p_projlist_main_q'; -- 任务名称(存储过程的名字)

  v_sqlerrm      varchar2(4000); -- 错误提示信息

  v_sqlcode      number; -- 错误代码

  v_sqlerrl      varchar2(4000); -- 错误行号

  --==============================================================================

  ---------------------------------------------------------------------------------------

  --业务变量

  v_superuser  integer default 0;

  v_user_pcode varchar2(100);

  v_pcode      varchar2(100);

  v_page_num  number default 0;

  v_page_size number;

  --=============================================================

  -- 业务处理过程

  --=============================================================



begin



  v_tradedate := to_char(sysdate, 'yyyyMMdd');



  --判断是否超级用户

  select count(1)
    into v_superuser
    from table(thjs.splitstr('admin,zhangqilong', ',')) t
   where instr(',' || t.column_value || ',', ',' || i_username || ',') > 0;

  delete from thjs.TMP_USER_PROJID;
  
  commit;

  --获取用户所在组

  if v_superuser = 0 then
    /*select t.p_code
     into v_user_pcode
     from thjs.vw_userinfo_tree t
    where t.ccode = i_username;*/
    delete from thjs.TMP_USER_PROJINFO t where t.username = i_username;
    insert into thjs.TMP_USER_PROJINFO
      (username, projid)
      select u.user_name, t.proj_id
        from THJS.IB_V_FINANCE_PROJMEMBER t
       inner join BASIC_THJS.wb_user u
          on u.user_id = t.workno
      /*inner join thjs.ib_v_gtja_empname e
         on e.workno = t.workno
      where e.username = i_username*/
       where u.user_name = i_username
         and t.projrole = '项目负责人'; --只有项目负责人可以填报清单
    /*where exists (select *
     from thjs.vw_userinfo_tree_root r
    where r.root_code = v_user_pcode
      and r.ccode = e.username);*/  

  end if;

  if i_page_num is not null then
    v_page_num := i_page_num;
  end if;

  if v_superuser = 0 then
  
  --统计记录条数
  if v_page_num < 1 then 
    SELECT sum(cnt)
      into o_total_count
      FROM (select count(1) cnt
              from thjs.vw_projlist_main_all p
        left join thjs.tb_ib_cust_info c
          on c.projid = p.projid
        left join thjs.tb_projlist_inout ro
          on ro.projid = p.projid
         and ro.inout_id = p.robserve_id
        left join thjs.tb_projlist_inout co
          on co.projid = p.projid
         and co.inout_id = p.cobserve_id
        left join thjs.tb_projlist_inout rl
          on rl.projid = p.projid
         and rl.inout_id = p.rlimit_id
        left join thjs.tb_projlist_inout cl
          on cl.projid = p.projid
         and cl.inout_id = p.climit_id
        left join thjs.tb_projlist_inout rq
          on rq.projid = p.projid
         and rq.inout_id = p.rquiet_id
        left join thjs.tb_projlist_inout cq
          on cq.projid = p.projid
         and cq.inout_id = p.cquiet_id
        left join (select m.projid, m.fill_id, count(1) as cn
                     from thjs.tb_projlist_multistk m
                    group by m.projid, m.fill_id) m
          on m.projid = p.projid
         and m.fill_id = p.multistk_ID
       where (i_projid is null or p.projid = i_projid)
         and (i_projname is null or instr(p.projname, i_projname) > 0)
         and (i_khname is null or instr(p.custname, i_khname) > 0)
         and exists (select t.projid
                from thjs.TMP_USER_PROJINFO t
               where t.username = i_username
                 and t.projid = p.projid)); --用户相关， 用户所在上级下属所有  

  end if;

  if i_page_size is not null and i_page_size <> 0 then
    v_page_size := i_page_size;
  else
    v_page_size := o_total_count;
  end if;

    --非超级用户 根据登录用户 显示用户及用户所属组权限项目   

    open rt_cursor for
      select r.*
        from (

            select t.*,

                    row_number() over(partition by null order by t.update_time desc) as rn

              from (

      select decode(p.source_flag, '0', '新增', '历史') as source_flag, --来源标志

             p.projid, --项目编号

             p.projname, --项目名称

             p.projtype, --项目类型

             p.custid, --客户编号

             p.custname, --客户名称

             p.stkcode, --证券代码

             p.stkname, --证券名称

             p.gtjarole, --我司角色

             ro.inout_date as ro_inout_date, --入观察清单日期

             ro.inout_reason as ro_inout_reason, --入观察清单事由

             ro.inout_remark as ro_inout_remark, --入观察清单备注

             ro.filepath as ro_filepath, --入观察清单附件

             co.inout_date as co_inout_date, --出观察清单日期

             co.inout_reason as co_inout_reason, --出观察清单事由

             co.inout_remark as co_inout_remark, --出观察清单备注

             co.filepath as co_filepath, --出观察清单附件

             rl.inout_date as rl_inout_date, --入限制清单日期

             rl.inout_reason as rl_inout_reason, --入限制清单事由

             rl.inout_remark as rl_inout_remark, --入限制清单备注

             rl.filepath as rl_filepath, --入限制清单附件

             cl.inout_date as cl_inout_date, --出限制清单日期

             cl.inout_reason as cl_inout_reason, --出限制清单事由

             cl.inout_remark as cl_inout_remark, --出限制清单备注

             cl.filepath as cl_filepath, --出限制清单附件

             rq.inout_date as rq_inout_date, --入静默期日期

             --rq.inout_reason   as rq_inout_reason, --入静默期事由

             --rq.inout_remark   as rq_inout_remark, --入静默期备注

             --rq.filepath       as rq_filepath, --入静默期附件

             cq.inout_date as cq_inout_date, --出静默期日期

             --cq.inout_reason   as cq_inout_reason, --出静默期事由

             --cq.inout_remark   as cq_inout_remark, --出静默期备注

             --cq.filepath       as cq_filepath, --出静默期附件

             decode(c.pro_is_valid,

                    '1',

                    p.projlist_status,

                    '失效项目-' || p.projlist_status) as projlist_status, --清单状态

             nvl(m.cn, 0) as multi_stk, --项目是否关联多家上市公司 0 否 1 是

             p.update_time

        from thjs.vw_projlist_main_all p

        left join thjs.tb_ib_cust_info c

          on c.projid = p.projid

        left join thjs.tb_projlist_inout ro

          on ro.projid = p.projid

         and ro.inout_id = p.robserve_id

        left join thjs.tb_projlist_inout co

          on co.projid = p.projid

         and co.inout_id = p.cobserve_id

        left join thjs.tb_projlist_inout rl

          on rl.projid = p.projid

         and rl.inout_id = p.rlimit_id

        left join thjs.tb_projlist_inout cl

          on cl.projid = p.projid

         and cl.inout_id = p.climit_id

        left join thjs.tb_projlist_inout rq

          on rq.projid = p.projid

         and rq.inout_id = p.rquiet_id

        left join thjs.tb_projlist_inout cq

          on cq.projid = p.projid

         and cq.inout_id = p.cquiet_id

        left join (select m.projid, m.fill_id, count(1) as cn

                     from thjs.tb_projlist_multistk m

                    group by m.projid, m.fill_id) m

          on m.projid = p.projid

         and m.fill_id = p.multistk_ID

       where (i_projid is null or p.projid = i_projid)

         and (i_projname is null or instr(p.projname, i_projname) > 0)

         and (i_khname is null or instr(p.custname, i_khname) > 0)

         and exists (select t.projid

                from thjs.TMP_USER_PROJINFO t

               where t.username = i_username

                 and t.projid = p.projid) --用户相关， 用户所在上级下属所有         

       order by p.source_flag, p.update_time desc) t)r

     where r.rn > v_page_num

       and r.rn <= v_page_num + v_page_size

     order by r.rn;

  

  else

  

  --统计记录条数

  if v_page_num < 1 then

  

    SELECT sum(cnt)

      into o_total_count

      FROM (select count(1) cnt

              from thjs.vw_projlist_main_all p

        left join thjs.tb_ib_cust_info c

          on c.projid = p.projid

        left join thjs.tb_projlist_inout ro

          on ro.projid = p.projid

         and ro.inout_id = p.robserve_id

        left join thjs.tb_projlist_inout co

          on co.projid = p.projid

         and co.inout_id = p.cobserve_id

        left join thjs.tb_projlist_inout rl

          on rl.projid = p.projid

         and rl.inout_id = p.rlimit_id

        left join thjs.tb_projlist_inout cl

          on cl.projid = p.projid

         and cl.inout_id = p.climit_id

        left join thjs.tb_projlist_inout rq

          on rq.projid = p.projid

         and rq.inout_id = p.rquiet_id

        left join thjs.tb_projlist_inout cq

          on cq.projid = p.projid

         and cq.inout_id = p.cquiet_id

        left join (select m.projid, m.fill_id, count(1) as cn

                     from thjs.tb_projlist_multistk m

                    group by m.projid, m.fill_id) m

          on m.projid = p.projid

         and m.fill_id = p.multistk_ID

       where (i_projid is null or p.projid = i_projid)

         and (i_projname is null or instr(p.projname, i_projname) > 0)

         and (i_khname is null or instr(p.custname, i_khname) > 0) --超级用户查询所选节点，管理人员权限待确定

         );

  

  end if;



  if i_page_size is not null and i_page_size <> 0 then

    v_page_size := i_page_size;

  else

    v_page_size := o_total_count;

  end if;

  

    --超级用户根据所选择用户组或用户 查询

    open rt_cursor for

      select r.*

        from (

            select t.*,

                    row_number() over(partition by null order by t.update_time desc) as rn

              from (

      select decode(p.source_flag, '0', '新增', '历史') as source_flag, --来源标志

             p.projid, --项目编号

             p.projname, --项目名称

             p.projtype, --项目类型

             p.custid, --客户编号

             p.custname, --客户名称

             p.stkcode, --证券代码

             p.stkname, --证券名称

             p.gtjarole, --我司角色

             ro.inout_date as ro_inout_date, --入观察清单日期

             ro.inout_reason as ro_inout_reason, --入观察清单事由

             ro.inout_remark as ro_inout_remark, --入观察清单备注

             ro.filepath as ro_filepath, --入观察清单附件

             co.inout_date as co_inout_date, --出观察清单日期

             co.inout_reason as co_inout_reason, --出观察清单事由

             co.inout_remark as co_inout_remark, --出观察清单备注

             co.filepath as co_filepath, --出观察清单附件

             rl.inout_date as rl_inout_date, --入限制清单日期

             rl.inout_reason as rl_inout_reason, --入限制清单事由

             rl.inout_remark as rl_inout_remark, --入限制清单备注

             rl.filepath as rl_filepath, --入限制清单附件

             cl.inout_date as cl_inout_date, --出限制清单日期

             cl.inout_reason as cl_inout_reason, --出限制清单事由

             cl.inout_remark as cl_inout_remark, --出限制清单备注

             cl.filepath as cl_filepath, --出限制清单附件

             rq.inout_date as rq_inout_date, --入静默期日期

             --rq.inout_reason   as rq_inout_reason, --入静默期事由

             --rq.inout_remark   as rq_inout_remark, --入静默期备注

             --rq.filepath       as rq_filepath, --入静默期附件

             cq.inout_date as cq_inout_date, --出静默期日期

             --cq.inout_reason   as cq_inout_reason, --出静默期事由

             --cq.inout_remark   as cq_inout_remark, --出静默期备注

             --cq.filepath       as cq_filepath, --出静默期附件

             decode(c.pro_is_valid,

                    '1',

                    p.projlist_status,

                    '失效项目-' || p.projlist_status) as projlist_status, --清单状态

             nvl(m.cn, 0) as multi_stk, --项目是否关联多家上市公司 0 否 1 是

             p.update_time

        from thjs.vw_projlist_main_all p

        left join thjs.tb_ib_cust_info c

          on c.projid = p.projid

        left join thjs.tb_projlist_inout ro

          on ro.projid = p.projid

         and ro.inout_id = p.robserve_id

        left join thjs.tb_projlist_inout co

          on co.projid = p.projid

         and co.inout_id = p.cobserve_id

        left join thjs.tb_projlist_inout rl

          on rl.projid = p.projid

         and rl.inout_id = p.rlimit_id

        left join thjs.tb_projlist_inout cl

          on cl.projid = p.projid

         and cl.inout_id = p.climit_id

        left join thjs.tb_projlist_inout rq

          on rq.projid = p.projid

         and rq.inout_id = p.rquiet_id

        left join thjs.tb_projlist_inout cq

          on cq.projid = p.projid

         and cq.inout_id = p.cquiet_id

        left join (select m.projid, m.fill_id, count(1) as cn

                     from thjs.tb_projlist_multistk m

                    group by m.projid, m.fill_id) m

          on m.projid = p.projid

         and m.fill_id = p.multistk_ID

       where (i_projid is null or p.projid = i_projid)

         and (i_projname is null or instr(p.projname, i_projname) > 0)

         and (i_khname is null or instr(p.custname, i_khname) > 0) --超级用户查询所选节点，管理人员权限待确定 

       order by p.source_flag, p.update_time desc) t)r

     where r.rn > v_page_num

       and r.rn <= v_page_num + v_page_size

     order by r.rn;

  

  end if;



  commit;



  o_return_msg  := '执行成功';

  o_return_code := 0;



exception

  -- 非预定义异常处理

  when v_userexp then

    rollback;

  

    v_sqlerrm := sqlerrm;

    v_sqlcode := sqlcode;

    v_sqlerrl := dbms_utility.format_error_backtrace();

  

    thjs.p_write_error_log(i_tradedate    => v_tradedate,

                            i_exec_func_id => v_exec_func_id,

                            i_func_own     => v_func_own,

                            i_func_name    => v_func_name,

                            i_occur_time   => sysdate,

                            i_sqlerrm      => v_sqlerrm,

                            i_sqlcode      => v_sqlcode,

                            i_sqlerrl      => v_sqlerrl);

    commit;

    raise;

    -- 预定义异常处理

  when others then

    rollback;

  

    v_sqlerrm := sqlerrm;

    v_sqlcode := sqlcode;

    v_sqlerrl := dbms_utility.format_error_backtrace();

  

    thjs.p_write_error_log(i_tradedate    => v_tradedate,

                            i_exec_func_id => v_exec_func_id,

                            i_func_own     => v_func_own,

                            i_func_name    => v_func_name,

                            i_occur_time   => sysdate,

                            i_sqlerrm      => v_sqlerrm,

                            i_sqlcode      => v_sqlcode,

                            i_sqlerrl      => v_sqlerrl);

    commit;

    raise;

end;

Create or Replace procedure "THJS"."P_PROJLIST_MULTISTK_Q" (rt_cursor     out sys_refcursor, --返回游标结果集
                                                       i_projid      in varchar2,
                                                       i_usercode    in varchar2, --查询用户
                                                       o_return_msg  out varchar2,
                                                       o_return_code out integer) is
  ----------------------------------------------------------------------------------
  --版    权：GTJA
  --版    本：1.0.0
  --开发人员：CZC@GTJA
  --创建日期：20190510
  --模块编号：
  --模块名称：清单管理 - 清单填报页信息查询 - 关联多上市公司信息查询
  --功能名称：清单填报页信息查询
  ----------------------------------------------------------------------------------
  --v101 ylt 20201022 新增带市场信息的股票代码
  --v102 ylt 20201113 关联多家上市公司信息，新增【关联性质】及【备注】字段
  
  --==============================================================================
  --固定变量
  v_userexp exception; -- 用户定义错
  v_tradedate    varchar2(8); -- 任务执行时间(业务日期)
  v_exec_func_id integer default '0'; -- 任务id
  v_func_own     varchar2(20) default 'thjs'; -- 任务归属用户（schema）
  v_func_name    varchar2(2000) default 'p_projlist_multistk_q'; -- 任务名称(存储过程的名字)
  v_sqlerrm      varchar2(4000); -- 错误提示信息
  v_sqlcode      number; -- 错误代码
  v_sqlerrl      varchar2(4000); -- 错误行号
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  --=============================================================
  -- 业务处理过程
  --=============================================================

begin

  v_tradedate := to_char(sysdate, 'yyyyMMdd');

  open rt_cursor for
    select m.busidate, --填业务日期
           m.projid, --项目id
           m.fill_id, --填报批次id
           m.comp_name, --上市公司名称
           m.stk_name, --股票简称
           m.stk_code, --证券代码
           m.write_date, --填报日期
           m.create_user, --操作人员
           m.create_time --操作时间
           ,m.windcode--带市场信息的股票代码 v101+
            --v102+ start
           ,m.related_property, --关联性质：1-客户其他代码/2-交易对手方/3-交易标的/4-其他
           m.ralated_ramark, --关联性质为4-其他时填写备注信息
           1 data_flag
           --v102+ end
      from thjs.tb_projlist_multistk m
     inner join thjs.tb_projlist_main p
        on p.projid = m.projid
       and p.multistk_id = m.fill_id
     where m.projid = i_projid
     order by m.create_time--v102+
     ;

  commit;

  o_return_msg  := '执行成功';
  o_return_code := 0;

exception
  -- 非预定义异常处理
  when v_userexp then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    thjs.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
    -- 预定义异常处理
  when others then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    thjs.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
end;

