     'i_projid:' || i_projid || '-' || 'i_fill_id:' || i_fill_id || '-' ||
     'i_comp_name:' || i_comp_name || '-' || 'i_stk_name:' || i_stk_name || '-' ||
     'i_stk_code:' || i_stk_code || '-' || 'i_write_date:' || i_write_date || '-' ||
     'i_projlist_status:' || i_projlist_status || '-' || 'i_submit_status:' ||
     i_submit_status || '-' || 'i_related_property:' || i_related_property || '-' ||
     'i_ralated_ramark:' || i_ralated_ramark || '-' || 'i_usercode:' ||
     i_usercode,
     sysdate);
  commit;
  --v101+ end

  select count(1)
    into v_count
    from thjs.tb_projlist_main m
   where m.projid = i_projid;

  if v_count = 1 and i_comp_name is not null then
  
    --v101+ start
    v_stk_code := i_stk_code;
    if i_stk_code is not null then
      select case
               when instr(v_stk_code, '.') > 0 then
                substr(v_stk_code, 0, instr(v_stk_code, '.') - 1)
               else
                v_stk_code
             end stk_code
        into v_stk_code
        from dual;
    end if;
  
    --获取带市场信息的股票代码
    thjs.p_projlist_stk_q(rcursor,
                          i_comp_name,
                          v_stk_code,
                          i_stk_name,
                          return_msg,
                          return_code);
    loop
      fetch rcursor
        into r;
      exit when rcursor%notfound;
      v_windcode := r.s_info_windcode;
    end loop;
    --v101+ end
  
    --保存关联多上市公司信息
    insert into thjs.tb_projlist_multistk_ylt
      (busidate,
       projid,
       fill_id,
       comp_name,
       stk_name,
       stk_code,
       write_date,
       create_user,
       create_time,--v102+
       windcode --v101+
       --v102+ start
      ,
       related_property,
       ralated_ramark
       --v102+ end
       )
    values
      (v_tradedate,
       i_projid,
       i_fill_id,
       i_comp_name,
       i_stk_name,
       i_stk_code,
       i_write_date,
       --i_usercode,--v102-
       nvl(i_create_user,i_usercode),--v102+
       i_create_time,--v102+
       v_windcode --v101+
       --v102+ start
      ,
       decode(i_related_property,'null','',i_related_property),
       i_ralated_ramark
       --v102+ end
       );
    commit;
  
    --v102- start 避免改到主表数据，测试暂时去掉此逻辑
    update thjs.tb_projlist_main_ylt m
       set m.multistk_id = i_fill_id
     where m.projid = i_projid;
     commit;
    
    --v102- end
  
    --v101+ start
    --首次全量更新tb_projlist_multistk中的windcode
    /*
    merge into thjs.tb_projlist_multistk t
    using (select d.s_info_windcode, --带市场信息的股票代码
                  d.s_info_compname, --上市公司名称
                  d.s_info_code, --股票代码
                  d.s_info_name, --证券名称
                  t.fill_id， t.stk_code
             from --主板A股
                  (select d.s_info_windcode,
                          d.s_info_code,
                          d.s_info_name,
                          d.s_info_compname
                     from zx90.tcl_asharedescription d
                   union all
                   --科创板
                   select x.s_info_windcode,
                          x.s_info_code,
                          x.s_info_name,
                          c.comp_name
                     from wind.neeqsdescription x
                     left join wind.compintroduction c
                       on c.comp_id = x.s_info_compcode
                   union all
                   select s.s_info_windcode,
                          s.s_info_code,
                          s.s_info_name,
                          c.s_info_compname
                     from zx90.tcl_hksharedescription s
                    inner join zx90.tcl_hkcompanyinfo c
                       on c.s_info_compcode = s.s_info_compcode
                   union all
                   select b.s_info_windcode,
                          b.s_info_code,
                          b.s_info_name,
                          b.s_info_compname
                     from zx90.tcl_bsharedescription b) d
            inner join thjs.tb_projlist_multistk t
               on case
                    when instr(t.stk_code, '.') > 0 then
                     substr(substr('00000', length(t.stk_code) + 1) || t.stk_code,
                            0,
                            instr(t.stk_code, '.') - 1)
                    else
                     substr('00000', length(t.stk_code) + 1) || t.stk_code
                  end =
                  substr('00000', length(d.s_info_code) + 1) || d.s_info_code) d
    on (t.fill_id = d.fill_id and t.stk_code = d.stk_code)
    when matched then
      update set t.windcode = nvl(d.s_info_windcode, t.stk_code);
    commit;
    */
  
    --没有匹配上的将输入的stkcode更新为windcode
    update thjs.tb_projlist_multistk_ylt t
       set t.windcode = t.stk_code
     where t.windcode is null;
    commit;
    --v101+ end
  
  end if;

  commit;

  o_return_msg  := '执行成功';
  o_return_code := 0;

exception
  -- 非预定义异常处理
  when v_userexp then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    hgman.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
    -- 预定义异常处理
  when others then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    hgman.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
end;

Create or Replace procedure "THJS"."P_PROJLIST_PROJTYPE_Q" (rt_cursor     out sys_refcursor, --返回游标结果集
                                                       i_username    in varchar2, --登录人
                                                       o_return_msg  out varchar2,
                                                       o_return_code out integer) is
  ----------------------------------------------------------------------------------
  --版    权：GTJA
  --版    本：1.0.0
  --开发人员：CZC@GTJA
  --创建日期：20191029
  --模块编号：
  --模块名称：清单管理 - 我管理的清单列表 
  --功能名称：业务类型查询
  ----------------------------------------------------------------------------------
  --==============================================================================
  --固定变量
  v_userexp exception; -- 用户定义错
  v_tradedate    varchar2(8); -- 任务执行时间(业务日期)
  v_exec_func_id integer default '0'; -- 任务id
  v_func_own     varchar2(20) default 'thjs'; -- 任务归属用户（schema）
  v_func_name    varchar2(2000) default 'p_projlist_projtype_q'; -- 任务名称(存储过程的名字)
  v_sqlerrm      varchar2(4000); -- 错误提示信息
  v_sqlcode      number; -- 错误代码
  v_sqlerrl      varchar2(4000); -- 错误行号
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  --=============================================================
  -- 业务处理过程
  --=============================================================

begin

  --查询所有存在清单的业务类型，暂不根据登录人员区分
  open rt_cursor for
    select t.projtype, t.projtype_desc
      from (select '' projtype, '全部' as projtype_desc, '0' as order_cl
              from dual
            union all
            select distinct m.projtype,
                            m.projtype as projtype_desc,
                            m.projtype as order_cl
              from thjs.vw_projlist_main m) t
     order by t.order_cl;

  commit;

  o_return_msg  := '执行成功';
  o_return_code := 0;

exception
  -- 非预定义异常处理
  when v_userexp then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    thjs.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
    -- 预定义异常处理
  when others then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    thjs.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
end;

Create or Replace procedure "THJS"."P_PROJLIST_REMIND_ALLCONFIRM_Q" (rt_cursor     out sys_refcursor, --返回游标结果集
                                                                i_username    in varchar2, --登录人
                                                                i_principal   in varchar2, --负责人
                                                                i_user_code   in varchar2,
                                                                o_return_msg  out varchar2,
                                                                o_return_code out integer) is
  ----------------------------------------------------------------------------------
  --版    权：GTJA
  --版    本：1.0.0
  --开发人员：YLT@GTJA
  --创建日期：20200604
  --模块编号：
  --模块名称：清单管理 - 清单任务查询
  --功能名称：查询所有清单负责人最新一条确认记录
  ----------------------------------------------------------------------------------
  --==============================================================================
  --固定变量
  v_userexp exception; -- 用户定义错
  v_tradedate    varchar2(8); -- 任务执行时间(业务日期)
  v_exec_func_id integer default '0'; -- 任务id
  v_func_own     varchar2(20) default 'thjs'; -- 任务归属用户（schema）
  v_func_name    varchar2(2000) default 'p_projlist_remind_allconfirm_q'; -- 任务名称(存储过程的名字)
  v_sqlerrm      varchar2(4000); -- 错误提示信息
  v_sqlcode      number; -- 错误代码
  v_sqlerrl      varchar2(4000); -- 错误行号
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  --=============================================================
  -- 业务处理过程
  --=============================================================

begin

  insert into thjs.tb_exec_log
    (log_id, proc_name, proc_param, exec_time)
  values
    (thjs.tb_exec_log_id_seq.nextval,
     'p_projlist_remind_allconfirm_q',
     'i_username:' || i_username || ' -' || 'i_principal:' || i_principal || ' -' ||
     'i_user_code:' || i_user_code,
     sysdate);
  commit;

  open rt_cursor for
    select t.user_name, --清单现场负责人
           t.user_code, --员工工号
           decode(t.confirm_flag,
                  '0',
                  '全部已确认',
                  '1',
                  '部分已确认',
                  '2',
                  '全部未确认') confirm_flag, --清单任务确认状态
           t.deptname, --所属部门
           t.confirm_time, --确认时间
           t.remind_date, --返回当次确认函提醒日期 --t.confirm_date, --确认日期
           t.begin_date, --确认区间起始日期 
           t.end_date --确认区间结束日期 
      from (select row_number() over(partition by t.user_code order by t.remind_date desc) rn,
                   t.*,
                   u.fir_deptname deptname
              from thjs.tb_projlist_remind_log t
              left join thjs.ib_v_userinfo u
                on replace(t.user_code, '-loff', '') = u.username) t
     where t.rn = 1 and（i_principal is null
        or t.user_name like '%' || i_principal || '%'
        or t.user_code like '%' || i_principal || '%' ） --投行清单提醒日志表
     order by t.remind_date desc, t.deptname, t.user_name;

  commit;

  o_return_msg  := '执行成功';
  o_return_code := 0;

exception
  -- 非预定义异常处理
  when v_userexp then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    thjs.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
    -- 预定义异常处理
  when others then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    thjs.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
end;

