           t.confirm_time, --确认时间
           t.remind_date, --返回当次确认函提醒日期 --t.confirm_date, --确认日期
           t.begin_date, --确认区间起始日期 
           t.end_date --确认区间结束日期 
      from thjs.tb_projlist_remind_log t
      left join thjs.ib_v_userinfo u
        on replace(t.user_code, '-loff', '') = u.username
     where t.user_code = i_user_code
