Create or Replace PROCEDURE "THJS"."P_PROJLIST_REMIND_LOG" (i_tradedate in char) as

  ----------------------------------------------------------------------------------
  --版    权：GTJA
  --版    本：1.0.0
  --开发人员：CZC@GTJA
  --创建日期：20191206
  --模块编号：
  --模块名称：清单管理
  --功能名称：清单管理-投行清单提醒日志处理
  ----------------------------------------------------------------------------------
  --v101 YLT@GTJA 20200602 

  --==============================================================================
  --固定变量
  v_userexp exception; -- 用户定义错
  v_tradedate    varchar2(8); -- 任务执行时间(业务日期)
  v_exec_func_id integer default '0'; -- 任务id
  v_func_own     varchar2(20) default 'thjs'; -- 任务归属用户（schema）
  v_func_name    varchar2(2000) default 'p_projlist_remind_log'; -- 任务名称(存储过程的名字)
  v_sqlerrm      varchar2(4000); -- 错误提示信息
  v_sqlcode      number; -- 错误代码
  v_sqlerrl      varchar2(4000); -- 错误行号
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  v_last_tradedate varchar2(8);
  v_remind_id      varchar2(100);
  v_remind_flag    char(1);
  v_begin_date     varchar2(8); --确认期间起始日期
  v_end_date       varchar2(8); --确认期间结束日期
  v_valid_cn       integer; --0 无效日期 1 有效日期
  --=============================================================
  -- 业务处理过程
  --=============================================================

begin

  /*
  remind_flag: 1 (15日前三个交易日） 2（月底前三个交易日）
  根据T-1日提醒确认情况，决定T日提醒人员名单（未提交的人）
  确认期间：xxxx年xx月1日至xxxx年xx月15日
           xxxx年xx月16日至xxxx年xx月[月底]日
  
  --20200420 只在前一个交易日提醒, 仅当项目类型为股权融资、债券融资_可交换债时提醒
  */

  --根据传入日期确定提醒周期 期间起始日期结束日期
  v_remind_flag := case
                     when i_tradedate <= substr(i_tradedate, 0, 6) || '15' then
                      '1'
                     else
                      '2'
                   end;

  v_begin_date := case
                    when v_remind_flag = '1' then
                     substr(i_tradedate, 0, 6) || '01'
                    else
                     substr(i_tradedate, 0, 6) || '16'
                  end;
  v_end_date := case
                  when v_remind_flag = '1' then
                   substr(i_tradedate, 0, 6) || '15'
                  else
                   to_char(last_day(to_date(i_tradedate, 'yyyyMMdd')),
                           'yyyyMMdd')
                end;

  --判断当前传入日期是否在提醒周期（3个交易日内） 不在返回错误
  select count(1)
    into v_valid_cn
    from (select *
            from params.tb_exchange_date d
           where d.market_code = '1'
             and d.date_flag = '1'
             and d.tradedate <= v_end_date
             and rownum <= 1
           order by d.tradedate desc) t
   where t.tradedate = i_tradedate;

  if v_valid_cn = 0 then
    raise v_userexp;
  else
  
    v_last_tradedate := kingstar.get_last_n_tradedate(i_tradedate, -1);
  
    --更新提醒日志表及提醒项目表
    delete from thjs.tb_projlist_remind_log l
     where l.remind_date = i_tradedate;
    delete from thjs.tb_projlist_remind_proj p
     where p.remind_date = i_tradedate;
  
    --根据T-1日确认情况，插入T日提醒日志信息
    for re in (select p.workno, u.user_name, u.display_name, u.email, p.p_cn
                 from (select p.workno, count(1) as p_cn
                         from thjs.ib_v_finance_projmember p
                        where p.projrole = '项目负责人'
                          and exists
                        (select 1
                                 from thjs.tb_projlist_main m
                                inner join thjs.tb_ib_cust_info c
                                   on c.projid = m.projid
                                where m.projlist_status in ('ro', 'rl')
                                  and (substr(c.projtype, 0, 4) = '股权融资' or
                                      c.projtype = '债券融资_可交换债')
                                  and m.projid = p.proj_id)
                        group by p.workno) p
                inner join BASIC_THJS.wb_user u
                   on u.user_id = p.workno
                where not exists (select 1
                         from thjs.tb_projlist_remind_log l
                        where l.remind_date = v_last_tradedate
                          and l.user_code = u.user_name
                          and l.confirm_flag = '1')) loop
    
      v_remind_id := sys_guid();
    
      insert into thjs.tb_projlist_remind_log
        (remind_flag,
         remind_date,
         user_code,
         user_name,
         email,
         proj_num,
         begin_date,
         end_date,
         --confirm_date,
         --confirm_flag,
         --confirm_time,
         reimind_id)
      values
        (v_remind_flag,
         i_tradedate,
         re.user_name,
         re.display_name,
         re.email,
         re.p_cn,
         v_begin_date,
         v_end_date,
         v_remind_id);
    
      insert into thjs.tb_projlist_remind_proj
        (reimind_id,
         remind_date,
         cust_name,
         proj_id,
         proj_name,
         user_code,
         user_name,
         projlist_status,
         inout_date,
         proj_type)
      --v101- start
      /*select v_remind_id,
            i_tradedate,
            c.khname,
            p.proj_id,
            p.projname,
            u.user_name,
            u.display_name,
            m.projlist_status,
            decode(m.projlist_status,
                   'ro',
                   m.ro_inout_date,
                   'rl',
                   m.rl_inout_date,
                   '') as inout_date
       from thjs.ib_v_finance_projmember p
      inner join thjs.tb_ib_cust_info c
         on c.projid = p.proj_id
      inner join BASIC_THJS.wb_user u
         on u.user_id = p.workno
      inner join thjs.vw_projlist_main_inout m
         on m.projlist_status in ('ro', 'rl')
        and m.projid = p.proj_id
      where p.projrole = '项目负责人'
        and p.workno = re.workno;*/
      --v101- end
      
      --v101+ start
        select v_remind_id,
               i_tradedate,
               c.khname,
               p.proj_id,
               p.projname,
               u.user_name,
               u.display_name,
               nvl(m.projlist_status, 0), --如果没有确认，项目状态为空则置为0
               decode(m.projlist_status,
                      'ro',
                      m.ro_inout_date,
                      'rl',
                      m.rl_inout_date,
                      '') as inout_date,
               c.projtype
          from thjs.ib_v_finance_projmember p
         inner join thjs.tb_ib_cust_info c
            on c.projid = p.proj_id
           and (substr(c.projtype, 0, 4) = '股权融资' or
               c.projtype = '债券融资_可交换债')
         inner join BASIC_THJS.wb_user u
            on u.user_id = p.workno
          left join thjs.vw_projlist_main_inout m --m表中只有已确认的项目数据，还需取未确认的项目数据，故使用left jion
            on m.projlist_status in ('ro', 'rl')
           and m.projid = p.proj_id
         where p.projrole = '项目负责人'
           and p.workno = re.workno
              --20210415 判断项目是否完成，是否有效
           and c.pro_status not in ('终止', '冻结', '完成')
           and c.projphase not in ('项目终止', '项目完成')
           and c.pro_is_valid = '1';
      --v101+ end
    
    end loop;
  
    commit;
  
  end if;

  ------------------------
exception
  -- 非预定义异常处理
  when v_userexp then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    thjs.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
    -- 预定义异常处理
  when others then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    thjs.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
end;

Create or Replace PROCEDURE "THJS"."P_PROJLIST_REMIND_LOG_YLT" (i_tradedate in char) as

  --v101 2020/06/02 清单管理功能修改
  ----------------------------------------------------------------------------------
  --版    权：GTJA
  --版    本：1.0.0
  --开发人员：CZC@GTJA
  --创建日期：20191206
  --模块编号：
  --模块名称：清单管理
  --功能名称：清单管理-投行清单提醒日志处理
  ----------------------------------------------------------------------------------
  --==============================================================================
  --固定变量
  v_userexp exception; -- 用户定义错
  v_tradedate    varchar2(8); -- 任务执行时间(业务日期)
  v_exec_func_id integer default '0'; -- 任务id
  v_func_own     varchar2(20) default 'thjs'; -- 任务归属用户（schema）
  v_func_name    varchar2(2000) default 'p_projlist_remind_log_ylt'; -- 任务名称(存储过程的名字)
  v_sqlerrm      varchar2(4000); -- 错误提示信息
  v_sqlcode      number; -- 错误代码
  v_sqlerrl      varchar2(4000); -- 错误行号
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  v_last_tradedate varchar2(8);
  v_remind_id      varchar2(100);
  v_remind_flag    char(1);
  v_begin_date     varchar2(8); --确认期间起始日期
  v_end_date       varchar2(8); --确认期间结束日期
  v_valid_cn       integer; --0 无效日期 1 有效日期
  --=============================================================
  -- 业务处理过程
  --=============================================================

begin

  /*
  remind_flag: 1 (15日前三个交易日） 2（月底前三个交易日）
  根据T-1日提醒确认情况，决定T日提醒人员名单（未提交的人）
  确认期间：xxxx年xx月1日至xxxx年xx月15日
           xxxx年xx月16日至xxxx年xx月[月底]日
  
  --20200420 只在前一个交易日提醒, 仅当项目类型为股权融资、债券融资_可交换债时提醒
  */

  --根据传入日期确定提醒周期 期间起始日期结束日期
  v_remind_flag := case
                     when i_tradedate <= substr(i_tradedate, 0, 6) || '15' then
                      '1'
                     else
                      '2'
                   end;

  v_begin_date := case
                    when v_remind_flag = '1' then
                     substr(i_tradedate, 0, 6) || '01'
                    else
                     substr(i_tradedate, 0, 6) || '16'
                  end;
  v_end_date := case
                  when v_remind_flag = '1' then
                   substr(i_tradedate, 0, 6) || '15'
                  else
                   to_char(last_day(to_date(i_tradedate, 'yyyyMMdd')),
                           'yyyyMMdd')
                end;

  --判断当前传入日期是否在提醒周期（3个交易日内） 不在返回错误
  select count(1)
    into v_valid_cn
    from (select *
            from params.tb_exchange_date d
           where d.market_code = '1'
             and d.date_flag = '1'
             and d.tradedate <= v_end_date
             and rownum <= 1
           order by d.tradedate desc) t
   where t.tradedate = i_tradedate;

  if v_valid_cn = 0 then
    raise v_userexp;
  else
  
    v_last_tradedate := kingstar.get_last_n_tradedate(i_tradedate, -1);
  
    --v101- start
    --更新提醒日志表及提醒项目表
    /*delete from thjs.tb_projlist_remind_log l
     where l.remind_date = i_tradedate;
    delete from thjs.tb_projlist_remind_proj p
     where p.remind_date = i_tradedate;*/
    --v101- end
    --v101+ start
    delete from thjs.tb_projlist_remind_log_ylt l
     where l.remind_date = i_tradedate;
    delete from thjs.tb_projlist_remind_proj_ylt p
     where p.remind_date = i_tradedate;
    --v101+ end
  
    --根据T-1日确认情况，插入T日提醒日志信息
    for re in (select p.workno, u.user_name, u.display_name, u.email, p.p_cn
                 from (select p.workno, count(1) as p_cn
                         from thjs.ib_v_finance_projmember p
                        where p.projrole = '项目负责人'
                          and exists
                        (select 1
                                 from thjs.tb_projlist_main m
                                inner join thjs.tb_ib_cust_info c
                                   on c.projid = m.projid
                                where m.projlist_status in ('ro', 'rl')
                                  and (substr(c.projtype, 0, 4) = '股权融资' or
                                      c.projtype = '债券融资_可交换债')
                                  and m.projid = p.proj_id)
                        group by p.workno) p
                inner join BASIC_THJS.wb_user u
                   on u.user_id = p.workno
                where not exists (select 1
                         from thjs.tb_projlist_remind_log l
                        where l.remind_date = v_last_tradedate
                          and l.user_code = u.user_name
                          and l.confirm_flag = '1')) loop
    
      v_remind_id := sys_guid();
    
      --v101- start
      /*insert into thjs.tb_projlist_remind_log
        (remind_flag,
         remind_date,
         user_code,
         user_name,
         email,
         proj_num,
         begin_date,
         end_date,
         --confirm_date,
         --confirm_flag,
         --confirm_time,
         reimind_id)
      values
        (v_remind_flag,
         i_tradedate,
         re.user_name,
         re.display_name,
         re.email,
         re.p_cn,
         v_begin_date,
         v_end_date,
         v_remind_id);
      
      insert into thjs.tb_projlist_remind_proj
        (reimind_id,
         remind_date,
         cust_name,
         proj_id,
         proj_name,
         user_code,
         user_name,
         projlist_status,
         inout_date)
        select v_remind_id,
               i_tradedate,
               c.khname,
               p.proj_id,
               p.projname,
               u.user_name,
               u.display_name,
               m.projlist_status,
               decode(m.projlist_status,
                      'ro',
                      m.ro_inout_date,
                      'rl',
                      m.rl_inout_date,
                      '') as inout_date
          from thjs.ib_v_finance_projmember p
         inner join thjs.tb_ib_cust_info c
            on c.projid = p.proj_id
         inner join BASIC_THJS.wb_user u
            on u.user_id = p.workno
         inner join thjs.vw_projlist_main_inout m
            on m.projlist_status in ('ro', 'rl')
           and m.projid = p.proj_id
         where p.projrole = '项目负责人'
           and p.workno = re.workno;*/
      --v101- end
    
      --v101+ start
      insert into thjs.tb_projlist_remind_log_ylt --投行清单提醒日志表
        (remind_flag,
         remind_date,
         user_code,
         user_name,
         email,
         proj_num,
         begin_date,
         end_date,
         --confirm_date,
         --confirm_flag,
         --confirm_time,
         reimind_id)
      values
        (v_remind_flag,
         i_tradedate,
         re.user_name,
         re.display_name,
         re.email,
         re.p_cn,
         v_begin_date,
         v_end_date,
         v_remind_id);
    
      insert into thjs.tb_projlist_remind_proj_ylt --投行清单提醒项目表
        (reimind_id,
         remind_date,
         cust_name,
         proj_id,
         proj_name,
         user_code,
         user_name,
         projlist_status,
         inout_date
         --,confirm_date,
         --confirm_flag,
         --confirm_time
         )
        select v_remind_id,
               i_tradedate,
               c.khname,
               p.proj_id,
               p.projname,
               u.user_name,
               u.display_name,
               nvl(m.projlist_status, 0), --如果没有确认，项目状态为空则置为0
               decode(m.projlist_status,
                      'ro',
                      m.ro_inout_date,
                      'rl',
                      m.rl_inout_date,
                      '') as inout_date
          from thjs.ib_v_finance_projmember p
         inner join thjs.tb_ib_cust_info c
            on c.projid = p.proj_id
           and (substr(c.projtype, 0, 4) = '股权融资' or
               c.projtype = '债券融资_可交换债')
         inner join BASIC_THJS.wb_user u
            on u.user_id = p.workno
          left join thjs.vw_projlist_main_inout m --m表中只有已确认的项目数据，还需取未确认的项目数据，故使用left jion
            on m.projlist_status in ('ro', 'rl')
           and m.projid = p.proj_id
         where p.projrole = '项目负责人'
           and p.workno = re.workno;
      --v101+ end
    
    end loop;
  
    commit;
  
  end if;

  ------------------------
exception
  -- 非预定义异常处理
  when v_userexp then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    hgman.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
    -- 预定义异常处理
  when others then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    hgman.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
end;

Create or Replace procedure "THJS"."P_PROJLIST_REMIND_PROJ_Q" (rt_cursor     out sys_refcursor, --返回游标结果集
                                                          i_remind_id   in varchar2,
                                                          i_proj_status in varchar2, --根据清单项目状态分别查询。0-无出入单状态的项目/ro-入观察/rl-入限制 v101+
                                                          i_username    in varchar2, --登录人
                                                          o_return_msg  out varchar2,
                                                          o_return_code out integer) is
  ----------------------------------------------------------------------------------
  --版    权：GTJA
  --版    本：1.0.0
  --开发人员：CZC@GTJA
  --创建日期：20191210
  --模块编号：
  --模块名称：清单管理 - 清单提醒项目明细查询
  --功能名称：清单提醒项目明细查询
  ----------------------------------------------------------------------------------
  --v101 YLT@GTJA 20200602 
  
  --==============================================================================
  --固定变量
  v_userexp exception; -- 用户定义错
  v_tradedate    varchar2(8); -- 任务执行时间(业务日期)
  v_exec_func_id integer default '0'; -- 任务id
  v_func_own     varchar2(20) default 'thjs'; -- 任务归属用户（schema）
  v_func_name    varchar2(2000) default 'p_projlist_remind_proj_q'; -- 任务名称(存储过程的名字)
  v_sqlerrm      varchar2(4000); -- 错误提示信息
  v_sqlcode      number; -- 错误代码
  v_sqlerrl      varchar2(4000); -- 错误行号
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  --=============================================================
  -- 业务处理过程
  --=============================================================

begin

  --查询当前登录人作为项目负责人的最新清单提醒项目信息
  open rt_cursor for
    select p.reimind_id, --提醒ID
           p.remind_date, --提醒日期
           p.cust_name, --客户名称
           p.proj_id, --项目编号
           p.proj_name, --项目名称
           c.projtype, --项目类型
           p.user_code, --负责人
           p.user_name, --负责人姓名
           p.projlist_status, --清单状态
           p.inout_date --入单日期
           ,nvl(p.confirm_flag, 0) as confirm_flag --确认标识 0-未操作 1-已确认无变化 2-已编辑 v101+
      from thjs.tb_projlist_remind_proj p
      left join thjs.tb_ib_cust_info c
        on c.projid = p.proj_id
     where p.reimind_id = i_remind_id
     --v101+ start
     and (i_proj_status is null or
           p.projlist_status in
           (select regexp_substr(i_proj_status, '[^,]+', 1, level)
               from dual
             connect by regexp_substr(i_proj_status, '[^,]+', 1, level) is not null))
     order by p.projlist_status;
     --v101+ end

  commit;

  o_return_msg  := '执行成功';
  o_return_code := 0;

exception
  -- 非预定义异常处理
  when v_userexp then
    rollback;

    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();

    thjs.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
    -- 预定义异常处理
  when others then
    rollback;

    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();

    thjs.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
end;

Create or Replace procedure "THJS"."P_PROJLIST_REMIND_PROJ_Q_YLT" (rt_cursor     out sys_refcursor, --返回游标结果集
                                                         i_remind_id   in varchar2,
                                                         i_proj_status in varchar2, --根据清单项目状态分别查询。0-无出入单状态的项目/ro-入观察/rl-入限制
                                                         i_username    in varchar2, --登录人
                                                         o_return_msg  out varchar2,
                                                         o_return_code out integer) is
  ----------------------------------------------------------------------------------
  --版    权：GTJA
  --版    本：1.0.0
  --开发人员：CZC@GTJA
  --创建日期：20191210
  --模块编号：
  --模块名称：清单管理 - 清单提醒项目明细查询
  --功能名称：清单提醒项目明细查询
  ----------------------------------------------------------------------------------
  --==============================================================================
  --固定变量
  v_userexp exception; -- 用户定义错
  v_tradedate    varchar2(8); -- 任务执行时间(业务日期)
  v_exec_func_id integer default '0'; -- 任务id
  v_func_own     varchar2(20) default 'thjs'; -- 任务归属用户（schema）
  v_func_name    varchar2(2000) default 'p_projlist_remind_proj_q_ylt'; -- 任务名称(存储过程的名字)
  v_sqlerrm      varchar2(4000); -- 错误提示信息
  v_sqlcode      number; -- 错误代码
  v_sqlerrl      varchar2(4000); -- 错误行号
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  --=============================================================
  -- 业务处理过程
  --=============================================================

begin

  --查询当前登录人作为项目负责人的最新清单提醒项目信息
  open rt_cursor for
    select p.reimind_id, --提醒ID
           p.remind_date, --提醒日期
           p.cust_name, --客户名称
           p.proj_id, --项目编号
           p.proj_name, --项目名称
           c.projtype, --项目类型
           p.user_code, --负责人
           p.user_name, --负责人姓名
           p.projlist_status, --清单状态
           p.inout_date, --入单日期
           nvl(p.confirm_flag, 0) as confirm_flag --确认标识 0-未操作 1-已确认无变化 2-已编辑
      from thjs.tb_projlist_remind_proj_ylt p
      left join thjs.tb_ib_cust_info c
        on c.projid = p.proj_id
     where p.reimind_id = i_remind_id
          --and p.projlist_status = i_proj_status
       and (i_proj_status is null or
           p.projlist_status in
           (select regexp_substr(i_proj_status, '[^,]+', 1, level)
               from dual
             connect by regexp_substr(i_proj_status, '[^,]+', 1, level) is not null))
