Create or Replace PROCEDURE "THJS"."P_PROJLIST_RL2_HGMAIL_Q" (O_CURSOR out types.cursorType) as

  ----------------------------------------------------------------------------------
  --版    权：GTJA
  --版    本：1.0.0
  --开发人员：CZC@GTJA
  --创建日期：20191119
  --模块编号：
  --模块名称：清单管理
  --功能名称：清单管理-限制清单合规邮件2提醒查询 填报时间 含时分秒
  ----------------------------------------------------------------------------------
  --==============================================================================
  --固定变量
  v_userexp exception; -- 用户定义错
  v_tradedate    varchar2(8); -- 任务执行时间(业务日期)
  v_exec_func_id integer default '0'; -- 任务id
  v_func_own     varchar2(20) default 'thjs'; -- 任务归属用户（schema）
  v_func_name    varchar2(2000) default 'P_PROJLIST_RL2_HGMAIL_Q'; -- 任务名称(存储过程的名字)
  v_sqlerrm      varchar2(4000); -- 错误提示信息
  v_sqlcode      number; -- 错误代码
  v_sqlerrl      varchar2(4000); -- 错误行号
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  --=============================================================
  -- 业务处理过程
  --=============================================================

begin
  open O_CURSOR for
    select row_number() over(partition by null order by t.source_type, t.projid, t.stkcode) as rowno, --序号
           t.custname,
           t.projname,
           t.stkcode,
           t.stkname,
           t.projtype,
           t.rl_fill_time,
           t.source_type
      from (select t.projid,
                   t.custname, --客户名称
                   c.projname,
                   case
                     when t.stkcode is null or t.stkcode like 'A%' then --剔除A开头股票
                      null
                     else
                      t.windcode --20201026 邮件输出带市场的wind代码 t.stkcode
                   end as stkcode, --证券代码
                   case
                     when t.stkcode is null or t.stkcode like 'A%' then --剔除A开头股票
                      null
                     else
                      t.stkname
                   end as stkname, --股票简称
                   t.projtype, --业务类型
                   to_char(t.rl_fill_time, 'YYYY-MM-DD HH24:MI:SS') as rl_fill_time, --入限制清单填报日期           
                   '母公司投行' as source_type
              from thjs.vw_projlist_stk t LEFT JOIN thjs.tb_ib_cust_info c on c.projid = t.projid
             where t.projlist_status = 'rl'
            union all
            select to_char(x.seqno),
                   x.companyname,
                   '',
                   x.windcode,
                   x.stkname,
                   x.projtype,
                   to_char(x.in_date, 'YYYY-MM-DD') as rl_fill_time,
                   '香港国际' as source_type
              from (select max(x.seqno) as seqno, --20231108 除去重复数据（香港国际入单部门不同？）
                           x.companyname,
                           x.windcode,
                           x.stkname,
                           x.projtype,
                           x.in_date
                      from thjs.vw_projlist_xggj x
                     where x.projlist_status = 'rl'
                     group by x.companyname,
                              x.windcode,
                              x.stkname,
                              x.projtype,
                              x.in_date) x
            union all
            select cast(sys_guid() as varchar2(50)) as projid,
                   h.project_name,
                   '',
                   h.stock_code,
                   h.stock_name,
                   h.project_type,
                   h.begin_date,
                   h.source_type
              from thjs.v_hgpt_list_th_ht_all h
             where h.status in ('rl', 'rly') AND h.SOURCE_TYPE ='Y公司'
             UNION ALL
             SELECT
	CAST(sys_guid() AS varchar2(50)) AS projid,
	h.COMPANYNAME,
	'',
	CASE
		WHEN h.market = 'HKG' AND length(h.STKCODE)<5 THEN 
lpad(h.STKCODE, 5, '0')
		ELSE h.STKCODE
	END AS STKCODECODE,
	h.STKNAME,
	CASE
		WHEN h.projtype = 16 THEN 'Take Code Financial Advisor / Financing Provider'
		WHEN h.projtype = 17 THEN 'Non Takeover code Financial Advisor / Financing Provider'
		WHEN h.projtype = 18 THEN 'Independent Financial Advisor'
		WHEN h.projtype = 19 THEN 'Sponsor'
		WHEN h.projtype = 20 THEN 'Compliance Advisor'
		WHEN h.projtype = 21 THEN 'Financial Advisor / Rating Advisor'
		WHEN h.projtype = 22 THEN 'Underwriter'
		WHEN h.projtype = 23 THEN 'IPO Underwriter'
		WHEN h.projtype = 24 THEN 'IPO Underwriter + Stabilizing Manager'
		WHEN h.projtype = 25 THEN 'Non IPO Underwriter'
		WHEN h.projtype = 26 THEN 'IPO Placing Agent / Lead Manager / Others'
		WHEN h.projtype = 27 THEN 'Non IPO Placing Agent / Lead Manager / Others'
	END AS projtype,
	to_char（h.IN_DATE,
	'YYYY-MM-DD'),
	'Y国际'
FROM
	HGPT.TB_HG_XX_070501_XGGJ_NEW h
WHERE
	PROJLIST_STATUS IN('rl', 'rly')
           union all
           select a.projid,
       a.custname,
       a.PROJNAME,
       m.security_id_bj as stkcode,
       a.stkname,
       a.projtype,
       a.rl_fill_time,
       a.source_type
 from (
select t.projid,
                   t.custname, --客户名称
                   c.projname,
                   case
                     when t.stkcode is null or t.stkcode like 'A%' then --剔除A开头股票
                      null
                     else
                      t.windcode --20201026 邮件输出带市场的wind代码 t.stkcode
                   end as stkcode, --证券代码
                   case
                     when t.stkcode is null or t.stkcode like 'A%' then --剔除A开头股票
                      null
                     else
                      t.stkname
                   end as stkname, --股票简称
                   t.projtype, --业务类型
                   to_char(t.rl_fill_time, 'YYYY-MM-DD HH24:MI:SS') as rl_fill_time, --入限制清单填报日期           
                   '母公司投行' as source_type
              from thjs.vw_projlist_stk t  LEFT JOIN thjs.tb_ib_cust_info c on c.projid = t.projid
             where t.projlist_status = 'rl'
            union all
            select to_char(x.seqno),
                   x.companyname,
                   '',
                   x.windcode,
                   x.stkname,
                   x.projtype,
                   to_char(x.in_date, 'YYYY-MM-DD') as rl_fill_time,
                   '香港国际' as source_type
              from (select max(x.seqno) as seqno, --20231108 除去重复数据（香港国际入单部门不同？）
                           x.companyname,
                           x.windcode,
                           x.stkname,
                           x.projtype,
                           x.in_date
                      from thjs.vw_projlist_xggj x
                     where x.projlist_status = 'rl'
                     group by x.companyname,
                              x.windcode,
                              x.stkname,
                              x.projtype,
                              x.in_date) x
            union all
            select cast(sys_guid() as varchar2(50)) as projid,
                   h.project_name,
                   '',
                   h.stock_code,
                   h.stock_name,
                   h.project_type,
                   h.begin_date,
                   h.source_type
              from thjs.v_hgpt_list_th_ht_all h
             where h.status in ('rl', 'rly') AND h.SOURCE_TYPE ='Y公司' 
             UNION ALL
             SELECT
	CAST(sys_guid() AS varchar2(50)) AS projid,
	h.COMPANYNAME,
	'',
	CASE
		WHEN h.market = 'HKG'  AND length(h.STKCODE)<5 THEN 
lpad(h.STKCODE, 5, '0')
		ELSE h.STKCODE
	END AS STKCODECODE,
	h.STKNAME,
	CASE
		WHEN h.projtype = 16 THEN 'Take Code Financial Advisor / Financing Provider'
		WHEN h.projtype = 17 THEN 'Non Takeover code Financial Advisor / Financing Provider'
		WHEN h.projtype = 18 THEN 'Independent Financial Advisor'
		WHEN h.projtype = 19 THEN 'Sponsor'
		WHEN h.projtype = 20 THEN 'Compliance Advisor'
		WHEN h.projtype = 21 THEN 'Financial Advisor / Rating Advisor'
		WHEN h.projtype = 22 THEN 'Underwriter'
		WHEN h.projtype = 23 THEN 'IPO Underwriter'
		WHEN h.projtype = 24 THEN 'IPO Underwriter + Stabilizing Manager'
		WHEN h.projtype = 25 THEN 'Non IPO Underwriter'
		WHEN h.projtype = 26 THEN 'IPO Placing Agent / Lead Manager / Others'
		WHEN h.projtype = 27 THEN 'Non IPO Placing Agent / Lead Manager / Others'
	END AS projtype,
	to_char（h.IN_DATE,
	'YYYY-MM-DD'),
	'Y国际'
FROM
	HGPT.TB_HG_XX_070501_XGGJ_NEW h
WHERE
	h.PROJLIST_STATUS IN('rl', 'rly')
             ) a inner join thjs.tb_security_map_gz_bj m
             on substr(a.stkcode,0, instr(a.stkcode,'.')-1) = m.security_id_gz
              where a.stkcode is not null) t;

  commit;

  ------------------------
exception
  -- 非预定义异常处理
  when v_userexp then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    thjs.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
    -- 预定义异常处理
  when others then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    thjs.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
