  v_func_name    varchar2(2000) default 'P_PROJLIST_RL_QY_HKSTK_Q'; -- 任务名称(存储过程的名字)
  v_sqlerrm      varchar2(4000); -- 错误提示信息
  v_sqlcode      number; -- 错误代码
  v_sqlerrl      varchar2(4000); -- 错误行号
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  --=============================================================
  -- 业务处理过程
  --=============================================================

begin
  open O_CURSOR for
    /*select distinct t.stock_name, --as "证券名称",
                    ltrim(t.stock_code, '0') as stock_code, --as "证券代码",
                    '' as op_type, --as "操作类型",
                    t.market_code, --as "市场名称",
                    '' as remark, --as "备注",
                    --20200701 日期置空 格式不对O32导入不好处理
                    '' as begin_date, --as "有效开始日期",
                    '' as end_date --as "有效截止日期"
      from thjs.vw_projlist_rl_qy_hkstk t
     where t.market = 'HKG' --只需要港股
       and t.stock_code <> 'NO CODE'; --只需要有股票代码的*/
      select distinct s.stock_name, --as "证券名称",
                    ltrim(s.stock_code, '0') as stock_code, --as "证券代码",
