                    '' as begin_date, --as "有效开始日期",
                    '' as end_date --as "有效截止日期"
      from 
     (select t.stock_name,t.stock_code,t.market_code from thjs.vw_projlist_rl_qy_hkstk t 
     where t.market = 'HKG' --只需要港股
       and t.stock_code <> 'NO CODE' --只需要有股票代码的
     union all
     select h.stock_name,h.stock_code,h.market as market_code from thjs.v_hgpt_list_th_ht h where h.status in('rl','rly') and h.market in ('11','27')) s; 

  commit;

  ------------------------
exception
  -- 非预定义异常处理
  when v_userexp then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    thjs.p_write_error_log(i_tradedate    => v_tradedate,
