                      '' as end_date --t.end_date --as "有效截止日期"
        from thjs.vw_projlist_rl_zy_allstk t;*/
  
    select distinct s.stock_name, --as "证券名称",
                    s.stock_code, --as "证券代码",
                    '' as op_type, --as "操作类型",
                    s.market_code, --as "市场名称",
                    '' as remark, --as "备注",
                    --20200701 日期置空 格式不对O32导入不好处理
