                    '' as end_date --as "有效截止日期"
      from (select t.stock_name, t.stock_code, t.market_code
              from thjs.vw_projlist_rl_zy_allstk t where t.market_code in ('1', '2', 'n', 'o', 'r', 'j')
            union all
            select t.stock_name,
                   m.security_id_bj as stock_code,
