              from thjs.vw_projlist_rl_zy_allstk t
             inner join thjs.tb_security_map_gz_bj m
                on t.stock_code = m.security_id_gz
            union all
            select h.stock_name, h.stock_code, h.market as market_code
              from thjs.v_hgpt_list_th_ht h
             where h.status in ('rl', 'rly')
               and h.market in ('1', '2', 'n', 'o', 'r', 'j')
            union all
            select h.stock_name,
                   m.security_id_bj as stock_code,
                   h.market         as market_code
              from thjs.v_hgpt_list_th_ht h
             inner join thjs.tb_security_map_gz_bj m
                on h.stock_code = m.security_id_gz
             where h.status in ('rl', 'rly')
