Create or Replace PROCEDURE "THJS"."P_PROJLIST_TASK" (i_tradedate in char)
/*==============================================================================
  版 本    : 1.0.0
  创建人   : czc
  模块编号 : 0
  日 期    : 2019-10-22
  功能描述 : 合规数据平台 清单管理每日任务
  ==============================================================================*/
 as
  v_sqlcode  integer default 0;
  v_sqlstate char(5) default '';
  --v_errcode        integer default 0;
  --v_errstate       char(5) default '';
  v_err_msg varchar2(128) default '';
  --v_not_found      integer default 0;
  --v_last_time      char(8);
  v_function_id    integer default 0; --定义存储过程模块编号
  v_error_line_num integer default 0; --错误行号
  --v_error_level    integer default 0; --错误级别
  v_function_desc varchar2(50) default '清单管理每日任务'; --功能描述
  v_program_name  char(40) default 'p_projlist_task'; --程序名
  v_pr_task_id    number default 0; --任务标示
  -- =======================================================================================================================
  -- 定义业务变量
  -- =======================================================================================================================
  -- =======================================================================================================================
  -- 业务开始
  -- =======================================================================================================================
begin

  --自动阶段修正-20240702新增;thjs.p_projlist_inout_s2
  --1、出观察转限制；2、出观察转静默；3、出限制+价格利率确定；4、入静默
  thjs.p_projlist_inout_fix(i_tradedate => i_tradedate);

  --每日8点检查,更新清单状态
  --由于实际操作日期与出入单发生日期（页面输入）不一定一致，需根据清单各阶段日期取值，重新计算状态字段
  merge into thjs.tb_projlist_main p
  using (select t.projid,
                t.projname,
                t.ro_inout_date,
                t.co_inout_date,
                t.rl_inout_date,
                t.cl_inout_date,
                t.rq_inout_date,
                t.cq_inout_date,
                case
                  when (t.ro_inout_date is not null and
                       t.ro_inout_date <= to_char(sysdate, 'yyyy-MM-dd')) and
                       (t.co_inout_date is null or
                       t.co_inout_date > to_char(sysdate, 'yyyy-MM-dd')) and
                       t.rl_inout_date is null and t.rq_inout_date is null then
                   'ro'
                  when (t.rl_inout_date is null or
                       t.rl_inout_date > to_char(sysdate, 'yyyy-MM-dd')) and
                       (t.co_inout_date is not null and
                       t.co_inout_date <= to_char(sysdate, 'yyyy-MM-dd')) and
                       (t.rq_inout_date is null or
                       t.rq_inout_date > to_char(sysdate, 'yyyy-MM-dd')) then
                   'co'
                  when (t.rl_inout_date is not null and
                       t.rl_inout_date <= to_char(sysdate, 'yyyy-MM-dd')) and
                       (t.cl_inout_date is null or
                       t.cl_inout_date > to_char(sysdate, 'yyyy-MM-dd')) then
                   'rl'
                  when (t.rq_inout_date is null or
                       t.rq_inout_date > to_char(sysdate, 'yyyy-MM-dd')) and
                       (t.cl_inout_date is not null and
                       t.cl_inout_date <= to_char(sysdate, 'yyyy-MM-dd')) and
                       t.rq_inout_date is null then
                   'cl'
                  when (t.rq_inout_date is not null and
                       t.rq_inout_date <= to_char(sysdate, 'yyyy-MM-dd')) and
                       (t.cq_inout_date is null or
                       t.cq_inout_date > to_char(sysdate, 'yyyy-MM-dd')) then
                   'rq'
                  when t.cq_inout_date is not null and
                       t.cq_inout_date <= to_char(sysdate, 'yyyy-MM-dd') then
                   'cq'
                  else
                   '0'
                end as calc_status,
                t.projlist_status
           from THJS.VW_PROJLIST_MAIN_INOUT t) t
  on (p.projid = t.projid)
  when matched then
    update set p.projlist_status = t.calc_status;

  commit;

  ------------------------
exception
  when others then
    v_sqlcode := -1 * sqlcode;
    v_err_msg := sqlerrm;
    rollback;
    --记录错误日志
    kingstar.pr_audit_write_errlog(v_pr_task_id, -- 任务标识
                                   0, -- 单位编号
                                   i_tradedate, -- 业务日期
                                   v_function_id, -- 功能标识
                                   v_program_name, -- 程序名
                                   v_error_line_num, -- 程序行号
                                   v_err_msg, -- 错误信息
                                   v_sqlcode, -- SQLCODE
                                   v_sqlstate -- SQLSTATE
                                   );
    commit;
    raise;
end;

Create or Replace procedure "THJS"."P_PROJLIST_TRANS_TONEW" (i_oldprojid   in varchar2, --旧项目编号
                                                        i_newprojid   in varchar2, --新项目编号
                                                        i_usercode    in varchar2, --操作人
                                                        o_return_msg  out varchar2,
                                                        o_return_code out integer) is
  ----------------------------------------------------------------------------------
  --版    权：GTJA
  --版    本：1.0.0
  --开发人员：CZC@GTJA
  --创建日期：20220624
  --模块编号：
  --模块名称：投行清单管理 - 系统内清单信息由失效或终止项目迁移至新项目
  --功能名称：
  ----------------------------------------------------------------------------------
  --==============================================================================
  --固定变量
  v_userexp exception; -- 用户定义错
  v_tradedate    varchar2(8); -- 任务执行时间(业务日期)
  v_exec_func_id integer default '0'; -- 任务id
  v_func_own     varchar2(20) default 'thjs'; -- 任务归属用户（schema）
  v_func_name    varchar2(2000) default 'p_projlist_trans_tonew'; -- 任务名称(存储过程的名字)
  v_sqlerrm      varchar2(4000); -- 错误提示信息
  v_sqlcode      number; -- 错误代码
  v_sqlerrl      varchar2(4000); -- 错误行号
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  v_count       integer default 0;
  --=============================================================
  -- 业务处理过程
  --=============================================================

begin

  v_tradedate := to_char(sysdate, 'yyyyMMdd');

  select count(1)
    into v_count
    from thjs.tb_projlist_main t
   where t.projid = i_newprojid;

  if v_count = 0 then
  
    insert into thjs.tb_projlist_inout
      (busidate,
       batch_id,
       --inout_id,
       projid,
       inout_type,
       inout_direct,
       fill_date,
       inout_date,
       inout_reason,
       inout_remark,
       filepath,
       inout_user,
       inout_status,
       update_user,
       update_time,
       create_time,
       debug_info)
      select t.busidate,
             t.batch_id,
             --t.inout_id,
             i_newprojid, --t.projid,
             t.inout_type,
             t.inout_direct,
             t.fill_date,
             t.inout_date,
             t.inout_reason,
             t.inout_remark,
             t.filepath,
             t.inout_user,
             t.inout_status,
             t.update_user,
             t.update_time,
             t.create_time,
             t.debug_info
        from thjs.tb_projlist_inout t
       where t.projid = i_oldprojid;
    commit;
  
    insert into thjs.tb_projlist_multistk
      (busidate,
       projid,
       fill_id,
       comp_name,
       stk_name,
       stk_code,
       write_date,
       pk_id,
       create_user,
       create_time,
       windcode,
       related_property,
       ralated_ramark)
      select t.busidate,
             i_newprojid, --t.projid,
             t.fill_id,
             t.comp_name,
             t.stk_name,
             t.stk_code,
             t.write_date,
             t.pk_id,
             t.create_user,
             t.create_time,
             t.windcode,
             t.related_property,
             t.ralated_ramark
        from thjs.tb_projlist_multistk t
       where t.projid = i_oldprojid;
    commit;
  
    insert into thjs.tb_projlist_main
      (busidate,
       projid,
       gtjarole,
       multistk_id,
       batch_id,
       robserve_id,
       cobserve_id,
       rlimit_id,
       climit_id,
       rquiet_id,
       cquiet_id,
       check_id,
       projlist_status,
       update_user,
       update_time,
       create_user,
       create_time,
       source_flag)
      select t.busidate,
             i_newprojid, --t.projid,
             t.gtjarole,
             t.multistk_id,
             t.batch_id,
             t.robserve_id,
             t.cobserve_id,
             t.rlimit_id,
             t.climit_id,
             t.rquiet_id,
             t.cquiet_id,
             t.check_id,
             t.projlist_status,
             t.update_user,
             t.update_time,
             t.create_user,
             t.create_time,
             t.source_flag
        from thjs.tb_projlist_main t
       where t.projid = i_oldprojid;
  
    commit;
  
    update thjs.tb_projlist_main t
       set (t.robserve_id,
            t.cobserve_id,
            t.rlimit_id,
            t.climit_id,
            t.rquiet_id,
            t.cquiet_id) =
           (select x.ro_id, x.co_id, x.rl_id, x.cl_id, x.rq_id, x.cq_id
              from thjs.Vw_Projlist_Inout_Row x
             where x.projid = i_newprojid)
     where t.projid = i_newprojid;
    commit;
  
    --刷新清单所有入出单记录检查结果
    merge into thjs.tb_projlist_check c
    using (select i.busidate,
                  i.projid,
                  i.inout_id,
                  case
                    when date_diff <= 0 then
                     '0'
                    else
                     '1'
                  end as check_flag,
                  case
                    when date_diff < 0 then
                     '早' || abs(i.date_diff) || '天'
                    when date_diff = 0 then
                     '准确'
                    else
                     '晚' || abs(i.date_diff) || '天'
                  end as check_result
             from (select i.*,
                          to_date(i.fill_date, 'yyyy-MM-dd') -
                          to_date(i.inout_date, 'yyyy-MM-dd') as date_diff
                     from thjs.tb_projlist_inout i
                    where i.projid = i_newprojid) i) i
    on (c.projid = i.projid and c.inout_id = i.inout_id)
    when matched then
      update
         set c.check_flag = i.check_flag, c.check_result = i.check_result
    when not matched then
      insert
        (BUSIDATE,
         PROJID,
         INOUT_ID,
         CHECK_FLAG,
         CHECK_RESULT,
         CHECK_USER,
         CREATE_TIME)
      values
        (i.busidate,
         i.projid,
         i.inout_id,
         i.check_flag,
         i.check_result,
         'admin',
         sysdate);
  
    commit;
  
  end if;

  o_return_msg  := '执行成功';
  o_return_code := 0;

exception
  -- 非预定义异常处理
  when v_userexp then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    thjs.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
    -- 预定义异常处理
  when others then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    thjs.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
end;

