Create or Replace PROCEDURE "THJS"."P_PROJLIST_ZYQD_HGMAIL_Q" (O_CURSOR out types.cursorType) as

  ----------------------------------------------------------------------------------
  --版    权：GTJA
  --版    本：1.0.0
  --开发人员：CZC@GTJA
  --创建日期：20210903
  --模块编号：
  --模块名称：清单管理
  --功能名称：清单管理-静默期合规邮件提醒查询
  ----------------------------------------------------------------------------------
  --==============================================================================
  --固定变量
  v_userexp exception; -- 用户定义错
  v_tradedate    varchar2(8); -- 任务执行时间(业务日期)
  v_exec_func_id integer default '0'; -- 任务id
  v_func_own     varchar2(20) default 'thjs'; -- 任务归属用户（schema）
  v_func_name    varchar2(2000) default 'P_PROJLIST_ZYQD_HGMAIL_Q'; -- 任务名称(存储过程的名字)
  v_sqlerrm      varchar2(4000); -- 错误提示信息
  v_sqlcode      number; -- 错误代码
  v_sqlerrl      varchar2(4000); -- 错误行号
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量

  v_busidate varchar2(8);
  --=============================================================
  -- 业务处理过程
  --=============================================================

begin

  select max(t.busi_date) into v_busidate from hgpt.tb_hg_xx_070402 t;

  open O_CURSOR for
    select row_number() over(partition by null order by t.stk_code) as rowno, --序号
           t.busi_date,
           t.stk_code,
           t.stk_name,
           t.qty,
           to_char(t.hold_ratio * 100, 'FM990.0000') || '%' hold_ratio,
           t.zy_qty,
           t.has_gtcc
    --t.lock_desc
      from hgpt.tb_hg_xx_070404 t --hgpt.tb_hg_xx_070402 20241211-财务大额持仓去掉做市数据，需恢复到tb_hg_xx_070402
     where t.busi_date = v_busidate;

  /*select row_number() over(partition by null order by t.l_sclb, t.vc_zqdm) as rowno, --序号
        t.vc_zqjc as stkname,
        t.vc_zqdm as stkcode,
        sum(t.en_ccbl * 100) as holdratio
   from hgpt.tb_hg_xx_070401_zyqd t
  where t.busi_date = v_busidate
  group by t.l_sclb, t.vc_zqjc, t.vc_zqdm;*/

  commit;

  ------------------------
exception
  -- 非预定义异常处理
  when v_userexp then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    thjs.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
    -- 预定义异常处理
  when others then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    thjs.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
