    raise;
end;

Create or Replace PROCEDURE "THJS"."P_PROJ_ISALLOWREPORT" (rt_cursor     out sys_refcursor, --返回游标结果集
                                                      i_proj_id     in varchar2,
                                                      i_proj_type   in varchar2,
                                                      i_username    in varchar2,
                                                      o_return_msg  out varchar2,
                                                      o_return_code out integer) is

  ----------------------------------------------------------------------------------
  --版    权：GTJA
  --版    本：1.0.0
  --开发人员：YLT@GTJA
  --创建日期：20200825
  --模块编号：
  --模块名称：投行系统-清单管理 清单变更校验项目类型
  --功能名称：清单变更校验项目类型
  ----------------------------------------------------------------------------------
  --固定变量
  v_userexp exception; -- 用户定义错
  v_tradedate    varchar2(8); -- 任务执行时间(业务日期)
  v_exec_func_id integer default '0'; -- 任务id
  v_func_own     varchar2(20) default 'thjs'; -- 任务归属用户（schema）
  v_func_name    varchar2(2000) default 'p_proj_isallowreport'; -- 任务名称(存储过程的名字)
  v_sqlerrm      varchar2(4000); -- 错误提示信息
  v_sqlcode      number; -- 错误代码
  v_sqlerrl      varchar2(4000); -- 错误行号
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  --=============================================================
  -- 业务处理过程
  --=============================================================

begin

  --清单变更前，先校验该清单对应的业务类型是否允许 清单填报
  if i_proj_type is null then
    open rt_cursor for
      select '0' is_allow_report,
             '此项目类型无需填报项目清单' as error_info
        from dual;
  elsif i_proj_type is not null and i_proj_type <> '债券融资_可交换债' then
    open rt_cursor for
      select t.is_allow_report, --是否允许填报清单(0-否/1-是) 
             decode(t.is_allow_report,
                    '0',
                    '此项目类型无需填报项目清单',
                    '-') as error_info
        from thjs.tb_projlist_busitype t
       where t.proj_type = i_proj_type;
  elsif i_proj_type is not null and i_proj_type = '债券融资_可交换债' then
    open rt_cursor for
      select case
               when (m.stock_code is not null or m.is_listed = 1) and
                    t.is_allow_report = 1 then
                '1'
               else
                '0'
             end is_allow_report,
             case
               when (m.stock_code is not null or m.is_listed = 1) and
                    t.is_allow_report = 1 then
                '-'
               else
                '非上市公司“债券融资_可交换债”无需填报项目清单'
             end error_info
        from thjs.tb_ib_cust_info      p,
             thjs.tb_projlist_busitype t,
             thjs.pty_main_info       m
       where t.proj_type = p.projtype
         and p.pripid = m.prip_id
         and p.projid = i_proj_id
         and t.proj_type = i_proj_type
         and t.proj_type = '债券融资_可交换债';
  end if;

  o_return_msg  := '执行成功';
  o_return_code := 0;

exception
  -- 非预定义异常处理
  when v_userexp then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    thjs.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
    -- 预定义异常处理
  when others then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    thjs.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
end;

Create or Replace PROCEDURE "THJS"."P_TEST" (RT_CURSOR  OUT SYS_REFCURSOR, --返回游标结果集
                                   I_USERNAME IN VARCHAR2,
                                   /*\*i_STOCKCODE   in varchar2,--证券代码*\
                                                                      I_KHNAME IN VARCHAR2, --客户名称
                                                                      --i_STOCKNAME  IN  varchar2,   --股票简称
                                                                      I_PROJTYPE IN VARCHAR2, --业务类型
                                                                      \*i_deptmanname   IN  VARCHAR2 ,  -- 项目负责人
                                                                                                                                              i_deptname  IN  VARCHAR2 ,   --部门名称
                                                                                                                                            --i_start_date  IN DATE,  --起止日期*\
                                                                      --i_end_date    IN DATE   --截止日期*/
                                   O_RETURN_MSG  OUT VARCHAR2,
                                   O_RETURN_CODE OUT INTEGER) IS
  ----------------------------------------------------------------------------------
  --版    权：GTJA
  --版    本：1.0.0
  --开发人员：zyy@GTJA
  --创建日期：20191029
  --模块编号：
  --模块名称：清单报错 - 我管理的清单报错查询
  --功能名称：我管理的清单报错查询
  ----------------------------------------------------------------------------------
  --==============================================================================
  --固定变量
  V_USEREXP EXCEPTION; -- 用户定义错
  V_TRADEDATE    VARCHAR2(8); -- 任务执行时间(业务日期)
  V_EXEC_FUNC_ID INTEGER DEFAULT '0'; -- 任务id
  V_FUNC_OWN     VARCHAR2(20) DEFAULT 'thjs'; -- 任务归属用户（schema）
  V_FUNC_NAME    VARCHAR2(2000) DEFAULT 'p_test'; -- 任务名称(存储过程的名字)
  V_SQLERRM      VARCHAR2(4000); -- 错误提示信息
  V_SQLCODE      NUMBER; -- 错误代码
  V_SQLERRL      VARCHAR2(4000); -- 错误行号
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  V_SUPERUSER INTEGER DEFAULT 0;
  V_ROLE_FLAG VARCHAR2(200); --角色数据权限标识
  V_PO_FLAG   VARCHAR2(2); --观察清单数据权限标识
  V_PL_FLAG   VARCHAR2(2); --限制清单数据权限标识
  V_PQ_FLAG   VARCHAR2(2); --静默期数据权限标识
  -------------------------------------------------------------------------------------
BEGIN
  V_TRADEDATE := TO_CHAR(SYSDATE, 'yyyyMMdd');

  --判断是否超级用户
  SELECT COUNT(1)
    INTO V_SUPERUSER
    FROM TABLE(KINGSTAR.SPLITSTR('admin', ',')) T
   WHERE INSTR(',' || T.COLUMN_VALUE || ',', ',' || I_USERNAME || ',') > 0;

  --权限获取
  --获取观察，静默，限制权限

  SELECT TO_CHAR(WM_CONCAT(DECODE(R.ROLE_ID,
                                  'projlist_o',
                                  'PO',
                                  'projlist_l',
                                  'PL',
                                  'projlist_q',
                                  'PQ',
                                  'ALL'))) AS ROLE_FLAG
    INTO V_ROLE_FLAG
    FROM BASIC_THJS.WB_USER U
    LEFT JOIN BASIC_THJS.WB_USER_ROLE UR
      ON UR.USER_ID = U.USER_ID
    LEFT JOIN BASIC_THJS.WB_ROLE R
      ON R.ROLE_ID = UR.ROLE_ID
   WHERE U.USER_NAME = I_USERNAME;

  V_PO_FLAG := CASE
                 WHEN INSTR(V_ROLE_FLAG, 'ALL') > 0 THEN
                  '2'
                 WHEN INSTR(V_ROLE_FLAG, 'PO') > 0 AND
                      INSTR(V_ROLE_FLAG, 'ALL') = 0 THEN
                  '1'
                 ELSE
                  '0'
               END;

  V_PL_FLAG := CASE
                 WHEN INSTR(V_ROLE_FLAG, 'ALL') > 0 THEN
                  '2'
                 WHEN INSTR(V_ROLE_FLAG, 'PL') > 0 AND
                      INSTR(V_ROLE_FLAG, 'ALL') = 0 THEN
                  '1'
                 ELSE
                  '0'
               END;
  V_PQ_FLAG := CASE
                 WHEN INSTR(V_ROLE_FLAG, 'ALL') > 0 THEN
                  '2'
                 WHEN INSTR(V_ROLE_FLAG, 'PQ') > 0 AND
                      INSTR(V_ROLE_FLAG, 'ALL') = 0 THEN
                  '1'
                 ELSE
                  '0'
               END;
  --根据权限分别获取数据
  OPEN RT_CURSOR FOR
    SELECT P.CUSTNAME, --客户名称
           P.PROJTYPE, --业务类型
           P.PROJID, --项目编号
           C.DEPTNAME, --部门名称
           C.DEPTMANANAME, --项目负责人
           P.STKCODE, --证券代码
           P.STKNAME, --证券名称
           DECODE(V_PO_FLAG, '0', '', RO.INOUT_DATE) AS RO_INOUT_DATE, --入观察清单日期
           DECODE(V_PO_FLAG, '0', '', RO.FILL_DATE) AS RO_FILL_DATE, --入观察清单填报日期
           DECODE(V_PO_FLAG, '0', '', RO.CHECK_RESULT) AS RO_CHECK_RESULT, --入观察清单检查结果
           DECODE(V_PO_FLAG, '0', '', CO.INOUT_DATE) AS CO_INOUT_DATE, --出观察清单日期
           DECODE(V_PO_FLAG, '0', '', CO.FILL_DATE) AS CO_FILL_DATE, --出观察清单填报日期
           DECODE(V_PO_FLAG, '0', '', CO.CHECK_RESULT) AS CO_CHECK_RESULT, --出观察清单检查结果
           DECODE(V_PL_FLAG, '0', '', RL.INOUT_DATE) AS RL_INOUT_DATE, --入限制清单日期
           DECODE(V_PL_FLAG, '0', '', RL.FILL_DATE) AS RL_FILL_DATE, --入限制清单填报日期
           DECODE(V_PL_FLAG, '0', '', RL.CHECK_RESULT) AS RL_CHECK_RESULT, --入限制清单检查结果
           DECODE(V_PL_FLAG, '0', '', CL.INOUT_DATE) AS CL_INOUT_DATE, --出限制清单日期
           DECODE(V_PL_FLAG, '0', '', CL.FILL_DATE) AS CL_FILL_DATE, --出限制清单填报日期
           DECODE(V_PL_FLAG, '0', '', CL.CHECK_RESULT) AS CL_CHECK_RESULT, --出限制清单检查结果
           DECODE(V_PQ_FLAG, '0', '', RQ.INOUT_DATE) AS RQ_INOUT_DATE, --静默期起始日期
           DECODE(V_PQ_FLAG, '0', '', CQ.INOUT_DATE) AS CQ_INOUT_DATE, --静默期截止日期
           P.PROJLIST_STATUS --清单状态
      FROM THJS.VW_PROJLIST_MAIN P
      LEFT JOIN THJS.TB_THDB_CUST_INFO C
        ON C.PROJID = P.PROJID
      LEFT JOIN THJS.VW_PROJLIST_INOUT RO
        ON RO.INOUT_ID = P.ROBSERVE_ID
      LEFT JOIN THJS.VW_PROJLIST_INOUT CO
        ON CO.INOUT_ID = P.COBSERVE_ID
      LEFT JOIN THJS.VW_PROJLIST_INOUT RL
        ON RL.INOUT_ID = P.RLIMIT_ID
      LEFT JOIN THJS.VW_PROJLIST_INOUT CL
        ON CL.INOUT_ID = P.CLIMIT_ID
      LEFT JOIN THJS.VW_PROJLIST_INOUT RQ
        ON RQ.INOUT_ID = P.RQUIET_ID
      LEFT JOIN THJS.VW_PROJLIST_INOUT CQ
        ON CQ.INOUT_ID = P.CQUIET_ID
    WHERE ((V_PO_FLAG = '2' OR
           (V_PO_FLAG = '1' AND P.PROJLIST_STATUS = 'ro')) OR
           (V_PL_FLAG = '2' OR
           (V_PL_FLAG = '1' AND P.PROJLIST_STATUS = 'rl')) OR
           (V_PQ_FLAG = '2' OR
           (V_PQ_FLAG = '1' AND P.PROJLIST_STATUS = 'rq')))
     ORDER BY P.SOURCE_FLAG, P.UPDATE_TIME DESC;

  O_RETURN_MSG  := '执行成功';
  O_RETURN_CODE := 0;

EXCEPTION
  -- 非预定义异常处理
  WHEN V_USEREXP THEN
    ROLLBACK;
  
    V_SQLERRM := SQLERRM;
    V_SQLCODE := SQLCODE;
    V_SQLERRL := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE();
  
    HGMAN.P_WRITE_ERROR_LOG(I_TRADEDATE    => V_TRADEDATE,
                            I_EXEC_FUNC_ID => V_EXEC_FUNC_ID,
                            I_FUNC_OWN     => V_FUNC_OWN,
                            I_FUNC_NAME    => V_FUNC_NAME,
                            I_OCCUR_TIME   => SYSDATE,
                            I_SQLERRM      => V_SQLERRM,
                            I_SQLCODE      => V_SQLCODE,
                            I_SQLERRL      => V_SQLERRL);
    COMMIT;
    RAISE;
    -- 预定义异常处理
  WHEN OTHERS THEN
    ROLLBACK;
  
    V_SQLERRM := SQLERRM;
    V_SQLCODE := SQLCODE;
    V_SQLERRL := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE();
  
    HGMAN.P_WRITE_ERROR_LOG(I_TRADEDATE    => V_TRADEDATE,
                            I_EXEC_FUNC_ID => V_EXEC_FUNC_ID,
                            I_FUNC_OWN     => V_FUNC_OWN,
                            I_FUNC_NAME    => V_FUNC_NAME,
                            I_OCCUR_TIME   => SYSDATE,
                            I_SQLERRM      => V_SQLERRM,
                            I_SQLCODE      => V_SQLCODE,
                            I_SQLERRL      => V_SQLERRL);
    COMMIT;
    RAISE;
END;

Create or Replace PROCEDURE "THJS"."P_THDB_DATA_DAILY" (i_tradedate in char)
/*==============================================================================
  版 本    : 1.0.0
  创建人   : czc
  模块编号 : 0
  日 期    : 2019-02-19
  功能描述 : 投行数据集市 投行系统财务数据采集
  ==============================================================================*/
 as
