     sec_deptcode,
     sec_deptname)
    select username,
           nickname,
           fir_deptcode,
           fir_deptname,
           sec_deptcode,
           sec_deptname
      from gtth.df_v_userinfo@thdb2; --
  commit;

  ------------------------
exception
  when others then
    v_sqlcode := -1 * sqlcode;
    v_err_msg := sqlerrm;
    rollback;
    --记录错误日志
    kingstar.pr_audit_write_errlog(v_pr_task_id, -- 任务标识
                                   0, -- 单位编号
                                   i_tradedate, -- 业务日期
                                   v_function_id, -- 功能标识
                                   v_program_name, -- 程序名
                                   v_error_line_num, -- 程序行号
                                   v_err_msg, -- 错误信息
                                   v_sqlcode, -- SQLCODE
                                   v_sqlstate -- SQLSTATE
                                   );
    commit;
    raise;
end;

CREATE OR REPLACE
PROCEDURE "THJS"."P_TH_CLIENT_INFO_S" (I_CLIENT_ID IN VARCHAR2,
                                            I_CLIENT_NAME IN VARCHAR2,
                                            I_ORGAN_FLAG IN VARCHAR2,
                                            I_ID_TYPE IN VARCHAR2,
                                            I_ID_NO IN VARCHAR2,
                                            I_ID_BEGINDATE IN VARCHAR2,
                                            I_ID_ENDDATE IN VARCHAR2,
                                            I_CLIENT_BELONG IN VARCHAR2,
                                            I_NATIONALITY IN VARCHAR2,
                                            I_BIRTHDAY IN VARCHAR2,
                                            I_OFFICE_ADDRESS IN VARCHAR2,
                                            I_PROVINCE IN VARCHAR2,
                                            I_CITY IN VARCHAR2,
                                            I_DISTRICT IN VARCHAR2,
                                            I_REGISTER_COUNTRY IN VARCHAR2,
                                            I_REGISTER_MONEY_TYPE IN VARCHAR2,
                                            I_REGISTER_FUND IN VARCHAR2,
                                            I_INDUSTRY_TYPE IN VARCHAR2,
                                            I_TEL IN VARCHAR2,
                                            I_SETUP_DATE IN VARCHAR2,
                                            I_BUSI_SCOPE IN VARCHAR2,
                                            I_IS_OBJECT_REPORT IN VARCHAR2,
                                            I_ASSOCIATED_DATE IN VARCHAR2,
                                            I_REMARK IN VARCHAR2,
                                            I_CREATE_USER IN VARCHAR2,
                                            I_CREATE_TIME IN VARCHAR2,
                                            I_UPDATE_USER IN VARCHAR2,
                                            I_UPDATE_TIME IN VARCHAR2,
                                            I_IS_SPECIAL IN VARCHAR2,
                                            I_CLIENT_TYPE IN VARCHAR2,
                                            I_CLIENT_TYPE_OTHER IN VARCHAR2,
                                            I_SPECIAL_MATTERS IN VARCHAR2,
                                            I_MISSING_INFORMATION IN VARCHAR2,
                                            I_MISSING_DRAFT IN VARCHAR2,
                                            I_SPECIAL_MATTERS_OTHER IN VARCHAR2,
                                            I_SPECIAL_REASON IN VARCHAR2,
                                            I_COMPLETED_CDD IN VARCHAR2,
                                            I_LOW_RISK_EXPLANATION IN VARCHAR2,
                                            I_TAKE_MEASURES IN VARCHAR2,
                                            I_COMMUNICATION_RECORDS IN VARCHAR2,
                                            I_AGREE_RECORDS IN VARCHAR2,
                                            I_OTHER_RECORDS IN VARCHAR2,
                                            I_INDUSTRY_TYPE1 IN VARCHAR2,
                                            I_WORK_TYPE IN VARCHAR2,
                                            I_CLIENT_STATUS IN VARCHAR2,
                                            I_DATA_STATUS IN VARCHAR2,
                                            I_RELATED_PROJ IN VARCHAR2,
                                            I_IF_RISK_CLIENT IN VARCHAR2,
                                            I_RISK_LIST_TYPE IN VARCHAR2,
                                            I_PROBLEM_DESC IN VARCHAR2,
                                            I_GRADE_VALUE IN VARCHAR2,
                                            I_GENDER IN VARCHAR2,
                                            I_INCOME IN VARCHAR2,
                                            I_PROFESSION_CODE IN VARCHAR2,
                                            I_POSITION IN VARCHAR2,
                                            I_WORK_PLACE IN VARCHAR2,
                                            I_ZIPCODE IN VARCHAR2,
                                            I_FILLIN_DATE IN VARCHAR2,
                                            I_ID_ADDRESS IN VARCHAR2,
                                            I_PROVINCE1 IN VARCHAR2,
                                            I_CITY1 IN VARCHAR2,
                                            I_DISTRICT1 IN VARCHAR2,
                                            I_ADDRESS IN VARCHAR2,
                                            I_PROVINCE2 IN VARCHAR2,
                                            I_CITY2 IN VARCHAR2,
                                            I_DISTRICT2 IN VARCHAR2,
                                            I_IF_RISK_LIST IN VARCHAR2,
                                            o_return_msg out varchar2,
                                            o_return_code out integer)
AS
    --==============================================================================
    ----------------------------------------------------------------------------------
    --固定变量
    v_userexp      exception;                                   -- 用户定义错
    v_tradedate    varchar2(8);                                 -- 任务执行时间(业务日期)
    v_exec_func_id integer default '0';                         -- 任务id
    v_func_own     varchar2(20) default 'THJS';            -- 任务归属用户（schema）
    v_func_name    varchar2(2000) default 'p_th_client_info_s'; -- 任务名称(存储过程的名字)
    v_sqlerrm      varchar2(4000);                              -- 错误提示信息
    v_sqlcode      number;                                      -- 错误代码
    v_sqlerrl      varchar2(4000);                              -- 错误行号
    --业务变量
    v_exists number; --判断是是否已填写 add by chengjing 20251205
    v_update_name  varchar2(20);                                -- 客户信息更新人update_user在user表的user_name --add by chengjing全链接生产获取不到userInfo.username
    v_count  number;
    --==============================================================================
    ---------------------------------------------------------------------------------------
BEGIN
    SELECT COUNT(*)
      INTO
           v_exists
      FROM thjs.T_TH_CLIENT_INFO
     WHERE client_id = I_CLIENT_ID;
     
    select count(1)
    into v_count
    from basic_thjs.wb_user u
    where u.user_id = I_UPDATE_USER;
    
    if v_count > 0 THEN
    	select u.user_name 
    	INTO v_update_name
        from basic_thjs.WB_USER u
        where u.user_id = I_UPDATE_USER;
    end if;
     
    -- 将关联人临时表数据存入正式表
    INSERT INTO thjs.T_TH_RELAT_INFO
		SELECT * FROM thjs.t_th_relat_info_tmp b
    	WHERE b.client_id = I_CLIENT_ID;
    	
    -- 更新关联人正式表数据状态
    UPDATE thjs.T_TH_RELAT_INFO
    SET DATA_STATUS = '1'
    WHERE CLIENT_ID = I_CLIENT_ID;
    
    -- 删除关联人临时表中该客户的关联人信息
    DELETE FROM THJS.T_TH_RELAT_INFO_TMP WHERE client_id = I_CLIENT_ID;
    
    
    -- 初次新增客户信息
    IF v_exists = 0 THEN
        INSERT INTO thjs.T_TH_CLIENT_INFO (CLIENT_ID,
               CLIENT_NAME,
               ORGAN_FLAG,
               ID_TYPE,
               ID_NO,
               ID_BEGINDATE,
               ID_ENDDATE,
               CLIENT_BELONG,
               NATIONALITY,
               OFFICE_ADDRESS,
               PROVINCE,
               CITY,
               DISTRICT,
               REGISTER_COUNTRY,
               REGISTER_MONEY_TYPE,
               REGISTER_FUND,
               INDUSTRY_TYPE,
               TEL,
               SETUP_DATE,
               BUSI_SCOPE,
               IS_OBJECT_REPORT,
               ASSOCIATED_DATE,
               REMARK,
               CREATE_USER,
               CREATE_TIME,
               UPDATE_USER,
               UPDATE_TIME,
               IS_SPECIAL,
               CLIENT_TYPE,
               CLIENT_TYPE_OTHER,
               SPECIAL_MATTERS,
               MISSING_INFORMATION,
               MISSING_DRAFT,
               SPECIAL_MATTERS_OTHER,
               SPECIAL_REASON,
               COMPLETED_CDD,
               LOW_RISK_EXPLANATION,
               TAKE_MEASURES,
               COMMUNICATION_RECORDS,
               AGREE_RECORDS,
               OTHER_RECORDS,
               INDUSTRY_TYPE1,
               WORK_TYPE,
               CLIENT_STATUS,
               DATA_STATUS,
               RELATED_PROJ,
               IF_RISK_CLIENT,
               RISK_LIST_TYPE,
               PROBLEM_DESC,
               GRADE_VALUE,
               GENDER,
               INCOME,
               PROFESSION_CODE,
               POSITION,
               WORK_PLACE,
               ZIPCODE,
               FILLIN_DATE,
               ID_ADDRESS,
               PROVINCE1,
               CITY1,
               DISTRICT1,
               ADDRESS,
               PROVINCE2,
               CITY2,
               DISTRICT2,
               IF_RISK_LIST,
               CUST_BIZ)
               VALUES (I_CLIENT_ID,
               I_CLIENT_NAME,
               I_ORGAN_FLAG,
               I_ID_TYPE,
               I_ID_NO,
               I_ID_BEGINDATE,
               I_ID_ENDDATE,
               I_CLIENT_BELONG,
               I_NATIONALITY,
               I_OFFICE_ADDRESS,
               I_PROVINCE,
               I_CITY,
               I_DISTRICT,
               I_REGISTER_COUNTRY,
               I_REGISTER_MONEY_TYPE,
               I_REGISTER_FUND,
               I_INDUSTRY_TYPE,
               I_TEL,
               I_SETUP_DATE,
               I_BUSI_SCOPE,
               I_IS_OBJECT_REPORT,
               I_ASSOCIATED_DATE,
               I_REMARK,
               I_CREATE_USER,
               sysdate,
               I_UPDATE_USER,
               sysdate,
               I_IS_SPECIAL,
               I_CLIENT_TYPE,
               I_CLIENT_TYPE_OTHER,
               I_SPECIAL_MATTERS,
               I_MISSING_INFORMATION,
               I_MISSING_DRAFT,
               I_SPECIAL_MATTERS_OTHER,
               I_SPECIAL_REASON,
               I_COMPLETED_CDD,
               I_LOW_RISK_EXPLANATION,
               I_TAKE_MEASURES,
               I_COMMUNICATION_RECORDS,
               I_AGREE_RECORDS,
               I_OTHER_RECORDS,
               I_INDUSTRY_TYPE1,
               I_WORK_TYPE,
               I_CLIENT_STATUS,
               I_DATA_STATUS,
               I_RELATED_PROJ,
               I_IF_RISK_CLIENT,
               I_RISK_LIST_TYPE,
               I_PROBLEM_DESC,
               I_GRADE_VALUE,
               I_GENDER,
               I_INCOME,
               I_PROFESSION_CODE,
               I_POSITION,
               I_WORK_PLACE,
               I_ZIPCODE,
               I_FILLIN_DATE,
               I_ID_ADDRESS,
               I_PROVINCE1,
               I_CITY1,
               I_DISTRICT1,
               I_ADDRESS,
               I_PROVINCE2,
               I_CITY2,
               I_DISTRICT2,
               I_IF_RISK_LIST,
               case
               	when I_CREATE_USER = 'admin' then '测试'
               	else '投行'
               end
               );
        
        COMMIT;
        -- 初次填报时插入填报人维护表 add by chengjing 20251127
        INSERT INTO THJS.T_MAINTAINER_INFO (CLIENT_ID,
               MAINTAINER,
               NEW_MAINTAINER,
               UPDATE_USER,
               UPDATE_TIME)
               VALUES( I_CLIENT_ID,
               I_CREATE_USER,
               I_CREATE_USER,
               'admin',
               sysdate);
        
        COMMIT;
    ELSE
        UPDATE 
               thjs.T_TH_CLIENT_INFO A
           SET A.CLIENT_NAME = I_CLIENT_NAME,
               A.ORGAN_FLAG = I_ORGAN_FLAG,
               A.ID_TYPE = I_ID_TYPE,
               A.ID_NO = I_ID_NO,
               A.ID_BEGINDATE = I_ID_BEGINDATE,
               A.ID_ENDDATE = I_ID_ENDDATE,
               A.CLIENT_BELONG = I_CLIENT_BELONG,
               A.NATIONALITY = I_NATIONALITY,
               A.BIRTHDAY = I_BIRTHDAY,
               A.OFFICE_ADDRESS = I_OFFICE_ADDRESS,
               A.PROVINCE = I_PROVINCE,
               A.CITY = I_CITY,
               A.DISTRICT = I_DISTRICT,
               A.REGISTER_COUNTRY = I_REGISTER_COUNTRY,
               A.REGISTER_MONEY_TYPE = I_REGISTER_MONEY_TYPE,
               A.REGISTER_FUND = I_REGISTER_FUND,
               A.INDUSTRY_TYPE = I_INDUSTRY_TYPE,
               A.TEL = I_TEL,
               A.SETUP_DATE = I_SETUP_DATE,
               A.BUSI_SCOPE = I_BUSI_SCOPE,
               A.IS_OBJECT_REPORT = I_IS_OBJECT_REPORT,
               A.ASSOCIATED_DATE = I_ASSOCIATED_DATE,
               A.REMARK = I_REMARK,
               A.UPDATE_USER = I_UPDATE_USER,
               A.UPDATE_TIME = sysdate,
               A.IS_SPECIAL = I_IS_SPECIAL,
               A.CLIENT_TYPE = I_CLIENT_TYPE,
               A.CLIENT_TYPE_OTHER = I_CLIENT_TYPE_OTHER,
               A.SPECIAL_MATTERS = I_SPECIAL_MATTERS,
               A.MISSING_INFORMATION = I_MISSING_INFORMATION,
               A.MISSING_DRAFT = I_MISSING_DRAFT,
               A.SPECIAL_MATTERS_OTHER = I_SPECIAL_MATTERS_OTHER,
               A.SPECIAL_REASON = I_SPECIAL_REASON,
               A.COMPLETED_CDD = I_COMPLETED_CDD,
               A.LOW_RISK_EXPLANATION = I_LOW_RISK_EXPLANATION,
               A.TAKE_MEASURES = I_TAKE_MEASURES,
               A.COMMUNICATION_RECORDS = I_COMMUNICATION_RECORDS,
               A.AGREE_RECORDS = I_AGREE_RECORDS,
               A.OTHER_RECORDS = I_OTHER_RECORDS,
               A.INDUSTRY_TYPE1 = I_INDUSTRY_TYPE1,
               A.WORK_TYPE = I_WORK_TYPE,
               A.CLIENT_STATUS = I_CLIENT_STATUS,
               A.DATA_STATUS = I_DATA_STATUS,
               A.RELATED_PROJ = I_RELATED_PROJ,
               A.IF_RISK_CLIENT = I_IF_RISK_CLIENT,
               A.RISK_LIST_TYPE = I_RISK_LIST_TYPE,
               A.PROBLEM_DESC = I_PROBLEM_DESC,
               A.GRADE_VALUE = I_GRADE_VALUE,
               A.GENDER = I_GENDER,
               A.INCOME = I_INCOME,
               A.PROFESSION_CODE = I_PROFESSION_CODE,
               A.POSITION = I_POSITION,
               A.WORK_PLACE = WORK_PLACE,
               A.ZIPCODE = I_ZIPCODE,
               A.FILLIN_DATE = I_FILLIN_DATE,
               A.ID_ADDRESS = I_ID_ADDRESS,
               A.PROVINCE1 = I_PROVINCE1,
               A.CITY1 = I_CITY1,
               A.DISTRICT1 = I_DISTRICT1,
               A.ADDRESS = I_ADDRESS,
               A.PROVINCE2 = I_PROVINCE2,
               A.CITY2 = I_CITY2,
               A.DISTRICT2 = I_DISTRICT2,
               A.IF_RISK_LIST = I_IF_RISK_LIST
         where A.CLIENT_ID = I_CLIENT_ID;
        COMMIT;
               
        -- 编辑客户信息时更新填报人维护表数据 add by chengjing 20260330
        UPDATE THJS.T_MAINTAINER_INFO 
        SET NEW_MAINTAINER = (case when v_count > 0 then v_update_name else I_UPDATE_USER end),--I_UPDATE_USER,--nvl(v_update_name,I_UPDATE_USER),
			UPDATE_TIME = sysdate
        where client_id = I_CLIENT_ID;
        COMMIT;
    END IF;
    o_return_msg  := '执行成功';
    o_return_code := 0;
exception
    -- 非预定义异常处理
when v_userexp then
    rollback;
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
    THJS.p_write_error_log(i_tradedate    => v_tradedate,
                                i_exec_func_id => v_exec_func_id,
                                i_func_own     => v_func_own,
                                i_func_name    => v_func_name,
                                i_occur_time   => sysdate,
                                i_sqlerrm      => v_sqlerrm,
                                i_sqlcode      => v_sqlcode,
                                i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
    -- 预定义异常处理
when others then
    rollback;
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
    THJS.p_write_error_log(i_tradedate    => v_tradedate,
                                i_exec_func_id => v_exec_func_id,
                                i_func_own     => v_func_own,
                                i_func_name    => v_func_name,
                                i_occur_time   => sysdate,
                                i_sqlerrm      => v_sqlerrm,
                                i_sqlcode      => v_sqlcode,
                                i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
END;

Create or Replace PROCEDURE "THJS"."P_TYNEWS_ASTOCK_COMPANY" (RT_CURSOR  OUT TYPES.CURSORTYPE,
                                                      I_OBJ_NAME IN VARCHAR2,
                                                      --I_PAGE_NUM    IN NUMBER DEFAULT 0, --默认值0,
                                                      --I_PAGE_SIZE   IN NUMBER DEFAULT 0, --默认值0  如果I_PAGE_NUM，I_PAGE_SIZE都为0 则不分页，查询全部
                                                      --O_TOTAL_COUNT OUT INTEGER,
                                                      O_RETURN_MSG  OUT VARCHAR2,
                                                      O_RETURN_CODE OUT INTEGER) IS
  -------------------------------------------------------------------------------------
  -- COPYRIGHT          GTJA
  -- FUNC_ID            THJS.P_TYNEWS_ASTOCK_COMPANY
  -- VERSION            1.0
  -- FUNC_NAME          三版公司简介
  -- FUNC_REMARK
  -- CREATE_DATE        2019-07-23
  -- CREATE_PROGRAMER   yongyong.zhang
  -- MODIFY_REMARK
  -- MODIFY_DATE
  --==============================================================================
  --固定变量
  V_FUNCTION_NAME VARCHAR2(64) DEFAULT 'THJS.P_TYNEWS_ASTOCK_COMPANY'; --存储过程名
  V_ERROR_MSG     VARCHAR2(1000); --返回信息
  V_ERROR_CODE    INTEGER;
  V_ERROR_LINE    INTEGER;
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  V_PAGE_NUM  NUMBER DEFAULT 0;
  V_PAGE_SIZE NUMBER;
  --=============================================================
  -- 业务处理过程
  --=============================================================

  --------------------------业务逻辑开始-----------------------------
  begin
    open  RT_CURSOR for
      select  A1.S_INFO_COMPCODE, --公司id
              A1.S_INFO_COMPNAME,--公司名称
              A1.S_INFO_COMPNAMEENG, --英文名称
              A1.S_INFO_COUNTRY,-- 国家及地区
              A1.S_INFO_PROVINCE, --省份
              A1.S_INFO_CITY, --城市
              A1.S_INFO_CHAIRMAN,-- 姓名
              A1.S_INFO_PRESIDENT,  --姓名
              A1.S_INFO_BDSECRETARY, --姓名
              A1.S_INFO_REGCAPITAL, --注册资本(万元)
              A1.S_INFO_FOUNDDATE,-- 成立日期
              A1.S_INFO_WEBSITE,-- 主页
              A1.S_INFO_EMAIL,-- 电子邮箱
              A1.S_INFO_OFFICE,-- 办公地址
              A1.ANN_DT, --公告日期
              A1.S_INFO_TOTALEMPLOYEES, -- 员工总数(人)
              A1.S_INFO_BUSINESSSCOPE,  --经营范围
              A1.S_INFO_MAIN_BUSINESS, -- 主要产品及业务
              A1.S_INFO_CHINESEINTRODUCTION --公司简介
            from zx90.tcl_neeqsintroduction A1
            join ZX90.TCL_COMPINTRODUCTION X1
          on A1.S_INFO_COMPCODE = x1.COMP_ID
       where x1.REGISTERNUMBER =
             (select E.CREDIT_CODE -- 统一社会信用代码
                from ZTGS.ENTERPRISEBASEINFOCOLLECT E --企业主体表
               where E.PRIPID = I_OBJ_NAME); --主体身份证代码
  O_RETURN_CODE := 0;
  O_RETURN_MSG  := '执行成功';

  commit;
  -- ============================================================================
  -- 错误处理部分
  -- ============================================================================

EXCEPTION
  WHEN OTHERS THEN
    O_RETURN_CODE := -1;
    O_RETURN_MSG  := V_ERROR_MSG || '--行号:' || TO_CHAR(V_ERROR_LINE) ||
                     '||sqlcode:' || SQLCODE || '||sqlerrm:||' ||
                     SUBSTR(SQLERRM, 1, 200);
    ROLLBACK;
    V_ERROR_MSG  := O_RETURN_MSG;
    V_ERROR_CODE := O_RETURN_CODE;
    P_ERROR_LOG('admin',
                V_FUNCTION_NAME,
                V_ERROR_CODE,
                V_ERROR_MSG,
                '',
                '1',
                O_RETURN_MSG,
                O_RETURN_CODE);
END;

Create or Replace PROCEDURE "THJS"."P_TYNEWS_ASTOCK_FEINI" (RT_CURSOR  OUT TYPES.CURSORTYPE,
                                                      I_OBJ_NAME IN VARCHAR2,
                                                      --I_PAGE_NUM    IN NUMBER DEFAULT 0, --默认值0,
                                                      --I_PAGE_SIZE   IN NUMBER DEFAULT 0, --默认值0  如果I_PAGE_NUM，I_PAGE_SIZE都为0 则不分页，查询全部
                                                      --O_TOTAL_COUNT OUT INTEGER,
                                                      O_RETURN_MSG  OUT VARCHAR2,
                                                      O_RETURN_CODE OUT INTEGER) IS
  -------------------------------------------------------------------------------------
  -- COPYRIGHT          GTJA
  -- FUNC_ID            THJS.P_TYNEWS_ASTOCK_COMPANY
  -- VERSION            1.0
  -- FUNC_NAME          财务数据
  -- FUNC_REMARK
  -- CREATE_DATE        2019-07-23
  -- CREATE_PROGRAMER   yongyong.zhang
  -- MODIFY_REMARK
  -- MODIFY_DATE
  --==============================================================================
  --固定变量
  V_FUNCTION_NAME VARCHAR2(64) DEFAULT 'THJS.P_TYNEWS_ASTOCK_COMPANY'; --存储过程名
  V_ERROR_MSG     VARCHAR2(1000); --返回信息
  V_ERROR_CODE    INTEGER;
  V_ERROR_LINE    INTEGER;
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  V_PAGE_NUM  NUMBER DEFAULT 0;
  V_PAGE_SIZE NUMBER;
  --=============================================================
  -- 业务处理过程
  --=============================================================

  --------------------------业务逻辑开始-----------------------------
  begin
    open  RT_CURSOR for
    select 
               CUST_FULL_NAME ,--客户全称 
               CUST_PRE_INCOME,--净收入 
               CUST_INCOME,--收入 
               CUST_EXPEND,--支出 
               ENTER_MONTH, --入账月份 
               DEPT_NAME, --业务部门 
               FGOUP_NAME,-- 大组 
               SGOUP_NAME,-- 小组 
               ACOUNT_DATE,-- 记账日期 
               PROJ_SNAME,-- 项目简称 
               WIND_COD,-- wind代码  
               FINANCE_BORE, --财务口径 
               INNER_BORE,--内劲口径 
               PROJ_TYPE_NEW, --业务类型（新） 
               PROJ_TYPE,  --业务类型（旧） 
               COMPANY_UNICODE,--公司统一社会信用代码 
               STATUS --  是否有效
             from 
             thjs.thdb_v_cust_finance_hisinfo A1
             where A1.CUST_FULL_NAME =
             (select E.ENTNAME -- 统一社会信用代码
                from ZTGS.ENTERPRISEBASEINFOCOLLECT E --企业主体表
               where E.PRIPID = I_OBJ_NAME); --主体身份证代码
  O_RETURN_CODE := 0;
  O_RETURN_MSG  := '执行成功';

  commit;
  -- ============================================================================
  -- 错误处理部分
  -- ============================================================================

EXCEPTION
  WHEN OTHERS THEN
    O_RETURN_CODE := -1;
    O_RETURN_MSG  := V_ERROR_MSG || '--行号:' || TO_CHAR(V_ERROR_LINE) ||
                     '||sqlcode:' || SQLCODE || '||sqlerrm:||' ||
                     SUBSTR(SQLERRM, 1, 200);
    ROLLBACK;
    V_ERROR_MSG  := O_RETURN_MSG;
    V_ERROR_CODE := O_RETURN_CODE;
    P_ERROR_LOG('admin',
                V_FUNCTION_NAME,
                V_ERROR_CODE,
                V_ERROR_MSG,
                '',
                '1',
                O_RETURN_MSG,
                O_RETURN_CODE);
END;

Create or Replace PROCEDURE "THJS"."P_TYNEWS_ASTOCK_IPO" (RT_CURSOR  OUT TYPES.CURSORTYPE,
                                                      I_OBJ_NAME IN VARCHAR2,
                                                      --I_PAGE_NUM    IN NUMBER DEFAULT 0, --默认值0,
                                                      --I_PAGE_SIZE   IN NUMBER DEFAULT 0, --默认值0  如果I_PAGE_NUM，I_PAGE_SIZE都为0 则不分页，查询全部
                                                      --O_TOTAL_COUNT OUT INTEGER,
                                                      O_RETURN_MSG  OUT VARCHAR2,
                                                      O_RETURN_CODE OUT INTEGER) IS
  -------------------------------------------------------------------------------------
  -- COPYRIGHT          GTJA
  -- FUNC_ID            THJS.P_TYNEWS_ASTOCK_ISSU
  -- VERSION            1.0
  -- FUNC_NAME          IPO发行情况
  -- FUNC_REMARK
  -- CREATE_DATE        2019-07-23
  -- CREATE_PROGRAMER   yongyong.zhang
  -- MODIFY_REMARK
  -- MODIFY_DATE
  --==============================================================================
  --固定变量
  V_FUNCTION_NAME VARCHAR2(64) DEFAULT 'THJS.P_TYNEWS_ASTOCK_IPO'; --存储过程名
  V_ERROR_MSG     VARCHAR2(1000); --返回信息
  V_ERROR_CODE    INTEGER;
  V_ERROR_LINE    INTEGER;
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  V_PAGE_NUM  NUMBER DEFAULT 0;
  V_PAGE_SIZE NUMBER;
  --=============================================================
  -- 业务处理过程
  --=============================================================

  --------------------------业务逻辑开始-----------------------------
  begin
    open  RT_CURSOR for
   select S_INFO_WINDCODE, --WIND代码
          S_INFO_COMPANYNAME, --公司名称
          S_INFO_COMPANYID, --公司ID
          REGADDR, --注册地
          SECTORS, --所属行业
          SPONSOR, --保荐机构
          SPON_REP, --保荐代表人
          ACC_FIRM, --会计师事务所
          CPA, --签字会计师
          LAW_FIRM, --律师事务所
          SOL_SIG, --签字律师
          y1.S_CLASSIFICATION APP_CODE, --申请事项代码
          y2.S_CLASSIFICATION SCH_CODE, --进度类型代码*/
          y3.S_CLASSIFICATION TBLISTED, --拟上市板块代码*/
          ST_DATE, --状态起始日期
          END_DATE, --状态终止日期
          EST_ISSUENO, --预计发行股数（万股）
          EST_ISSUESHARES, --预计发行后总股本（万股）
          PRO_TOLALINV --募投项目投资总额
     from zx90.tcl_ipocomprfa A1
      join zx90.tcl_asharetypecode Y1
       ON Y1.S_CLASSIFICATION = '事件类型代码'
      and y1.s_origin_typcode = A1.app_code
      join zx90.tcl_asharetypecode y2
       on y2.S_CLASSIFICATION = '进度类型代码'
      and y2.s_origin_typcode = A1.SCH_CODE
     join zx90.tcl_asharetypecode y3
       on y3.S_CLASSIFICATION = '上市板配置表'
      and  y3.s_origin_typcode =  A1.TBLISTED
     join ZX90.TCL_COMPINTRODUCTION X1
       on A1.S_INFO_COMPANYID =  x1.COMP_ID
        where x1.REGISTERNUMBER =
             (select E.CREDIT_CODE -- 统一社会信用代码
                from ZTGS.ENTERPRISEBASEINFOCOLLECT E --企业主体表
               where E.PRIPID = I_OBJ_NAME); --主体身份证代码
  O_RETURN_CODE := 0;
  O_RETURN_MSG  := '执行成功';

  commit;
  -- ============================================================================
  -- 错误处理部分
  -- ============================================================================

EXCEPTION
  WHEN OTHERS THEN
    O_RETURN_CODE := -1;
    O_RETURN_MSG  := V_ERROR_MSG || '--行号:' || TO_CHAR(V_ERROR_LINE) ||
                     '||sqlcode:' || SQLCODE || '||sqlerrm:||' ||
                     SUBSTR(SQLERRM, 1, 200);
    ROLLBACK;
    V_ERROR_MSG  := O_RETURN_MSG;
    V_ERROR_CODE := O_RETURN_CODE;
    P_ERROR_LOG('admin',
                V_FUNCTION_NAME,
                V_ERROR_CODE,
                V_ERROR_MSG,
                '',
                '1',
                O_RETURN_MSG,
                O_RETURN_CODE);
END;

Create or Replace PROCEDURE "THJS"."P_TYNEWS_ASTOCK_ISSU" (RT_CURSOR  OUT TYPES.CURSORTYPE,
