  --------------------------业务逻辑开始-----------------------------
BEGIN
  /*
   INSERT INTO THJS.T_TEST(C1,C2,C3,C4) VALUES(V_FUNCTION_NAME,I_OBJ_NAME,I_PAGE_NUM,I_PAGE_SIZE);
    COMMIT;
  */
  OPEN RT_CURSOR FOR
    SELECT S_INFO_WINDCODE, --wind代码
           S_INFO_NAME, -- 证券简称
           S_INFO_COMPNAME, -- 公司中文名称
           S_INFO_COMPNAMEENG, -- 公司英文名称
           S_INFO_ISINCODE, -- ISIN代码
           S_INFO_EXCHMARKET, -- 交易所
           S_INFO_LISTBOARD, -- 上市板类型
