           S_INFO_DELISTDATE, -- 退市日期
           CRNCY_CODE, -- 货币代码
           S_INFO_LISTBOARDNAME -- 上市板
      FROM ZX90.TCL_ASHAREDESCRIPTION A1
     INNER JOIN ZX90.TCL_COMPINTRODUCTION C
        ON C.COMP_ID = A1.S_INFO_COMPCODE
     WHERE C.REGISTERNUMBER =
           (SELECT E.CREDIT_CODE
              FROM ZTGS.ENTERPRISEBASEINFOCOLLECT E --企业主体表
             WHERE E.PRIPID = I_OBJ_NAME)
       AND A1.S_INFO_WINDCODE IN
           (SELECT DISTINCT T1.S_INFO_WINDCODE
              FROM ZX90.TCL_ASHAREAGENCY T1
             WHERE T1.S_AGENCY_NAMEID = '2024680');

  /*IF I_PAGE_NUM IS NOT NULL THEN
    V_PAGE_NUM := I_PAGE_NUM;
  END IF;
  
  --统计记录条数
  IF V_PAGE_NUM < 1 THEN
    SELECT COUNT(1)
      INTO O_TOTAL_COUNT
      FROM ZX90.TCL_ASHAREDESCRIPTION A1
     INNER JOIN ZX90.TCL_COMPINTRODUCTION C
        ON C.COMP_ID = A1.S_INFO_COMPCODE
     WHERE C.REGISTERNUMBER =
           (SELECT E.CREDIT_CODE
              FROM ZTGS.ENTERPRISEBASEINFOCOLLECT E --企业主体表
             WHERE E.PRIPID = I_OBJ_NAME)
       AND A1.S_INFO_WINDCODE IN
           (SELECT DISTINCT T1.S_INFO_WINDCODE
              FROM ZX90.TCL_ASHAREAGENCY T1
             WHERE T1.S_AGENCY_NAMEID = '2024680');
  END IF;
  
  IF I_PAGE_SIZE IS NOT NULL AND I_PAGE_SIZE <> 0 THEN
    V_PAGE_SIZE := I_PAGE_SIZE;
  ELSE
    V_PAGE_SIZE := O_TOTAL_COUNT;
  END IF;
  
  OPEN RT_CURSOR FOR
    SELECT S_INFO_NAME, -- 证券简称
           S_INFO_COMPNAME, -- 公司中文名称
           S_INFO_COMPNAMEENG, -- 公司英文名称
           S_INFO_ISINCODE, -- ISIN代码
           S_INFO_EXCHMARKET, -- 交易所
           S_INFO_LISTBOARD, -- 上市板类型
           S_INFO_LISTDATE, -- 上市日期
           S_INFO_DELISTDATE, -- 退市日期
           CRNCY_CODE, -- 货币代码
           S_INFO_LISTBOARDNAME -- 上市板
      FROM (SELECT A.*, ROWNUM AS RN
              FROM (SELECT S_INFO_NAME, -- 证券简称
                           S_INFO_COMPNAME, -- 公司中文名称
                           S_INFO_COMPNAMEENG, -- 公司英文名称
                           S_INFO_ISINCODE, -- ISIN代码
                           S_INFO_EXCHMARKET, -- 交易所
                           S_INFO_LISTBOARD, -- 上市板类型
                           S_INFO_LISTDATE, -- 上市日期
                           S_INFO_DELISTDATE, -- 退市日期
                           CRNCY_CODE, -- 货币代码
                           S_INFO_LISTBOARDNAME -- 上市板
                      FROM ZX90.TCL_ASHAREDESCRIPTION A1
                     INNER JOIN ZX90.TCL_COMPINTRODUCTION C
                        ON C.COMP_ID = A1.S_INFO_COMPCODE
                     WHERE C.REGISTERNUMBER =
                           (SELECT E.CREDIT_CODE
                              FROM ZTGS.ENTERPRISEBASEINFOCOLLECT E --企业主体表
                             WHERE E.PRIPID = I_OBJ_NAME)
                       AND A1.S_INFO_WINDCODE IN
                           (SELECT DISTINCT T1.S_INFO_WINDCODE
                              FROM ZX90.TCL_ASHAREAGENCY T1
                             WHERE T1.S_AGENCY_NAMEID = '2024680')) A) B
     WHERE RN > V_PAGE_NUM
       AND RN <= V_PAGE_NUM + V_PAGE_SIZE;*/
  O_RETURN_CODE := 0;
  O_RETURN_MSG  := '执行成功';

  commit;
  -- ============================================================================
  -- 错误处理部分
  -- ============================================================================

EXCEPTION
  WHEN OTHERS THEN
    O_RETURN_CODE := -1;
    O_RETURN_MSG  := V_ERROR_MSG || '--行号:' || TO_CHAR(V_ERROR_LINE) ||
                     '||sqlcode:' || SQLCODE || '||sqlerrm:||' ||
                     SUBSTR(SQLERRM, 1, 200);
    ROLLBACK;
    V_ERROR_MSG  := O_RETURN_MSG;
    V_ERROR_CODE := O_RETURN_CODE;
    P_ERROR_LOG('admin',
                V_FUNCTION_NAME,
                V_ERROR_CODE,
                V_ERROR_MSG,
                '',
                '1',
                O_RETURN_MSG,
                O_RETURN_CODE);
END;

Create or Replace PROCEDURE "THJS"."P_TYNEWS_ASTOCK_NAME" (RT_CURSOR  OUT TYPES.CURSORTYPE,
                                                      I_OBJ_NAME IN VARCHAR2,
