                                                      --I_PAGE_SIZE   IN NUMBER DEFAULT 0, --默认值0  如果I_PAGE_NUM，I_PAGE_SIZE都为0 则不分页，查询全部
                                                      --O_TOTAL_COUNT OUT INTEGER,
                                                      O_RETURN_MSG  OUT VARCHAR2,
                                                      O_RETURN_CODE OUT INTEGER) IS
  -------------------------------------------------------------------------------------
  -- COPYRIGHT          GTJA
  -- FUNC_ID            THJS.P_TYNEWS_ASTOCK_NAME
  -- VERSION            1.0
  -- FUNC_NAME          A股发行情况--公司简介
  -- FUNC_REMARK
  -- CREATE_DATE        2019-03-08
  -- CREATE_PROGRAMER   HAIYANG.XU
  -- MODIFY_REMARK
  -- MODIFY_DATE
  --==============================================================================
  --固定变量
  V_FUNCTION_NAME VARCHAR2(64) DEFAULT 'THJS.P_TYNEWS_ASTOCK_NAME'; --存储过程名
  V_ERROR_MSG     VARCHAR2(1000); --返回信息
  V_ERROR_CODE    INTEGER;
  V_ERROR_LINE    INTEGER;
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  V_PAGE_NUM  NUMBER DEFAULT 0;
  V_PAGE_SIZE NUMBER;
  --=============================================================
  -- 业务处理过程
  --=============================================================

  --------------------------业务逻辑开始-----------------------------
BEGIN
  /*
   INSERT INTO THJS.T_TEST(C1,C2,C3,C4) VALUES(V_FUNCTION_NAME,I_OBJ_NAME,I_PAGE_NUM,I_PAGE_SIZE);
    COMMIT;
  */
  OPEN RT_CURSOR FOR
    SELECT B1.S_INFO_PROVINCE, -- 省份
           B1.S_INFO_CITY, -- 城市
           B1.S_INFO_CHAIRMAN, -- 法人代表
           B1.S_INFO_PRESIDENT, -- 总经理
           B1.S_INFO_BDSECRETARY, -- 董事会秘书
           B1.S_INFO_REGCAPITAL, -- 注册资本(万元)
           B1.S_INFO_FOUNDDATE, -- 成立日期
           B1.S_INFO_CHINESEINTRODUCTION, -- 公司中文简介
           B1.S_INFO_COMPTYPE, -- 公司类型
           B1.S_INFO_WEBSITE, -- 主页
           B1.S_INFO_EMAIL, -- 电子邮箱
           B1.S_INFO_OFFICE, -- 办公地址
           B1.ANN_DT, -- 公告日期
           B1.S_INFO_COUNTRY, -- 国籍
           B1.S_INFO_BUSINESSSCOPE, -- 经营范围
           B1.S_INFO_COMPANY_TYPE, -- 公司类别
           B1.S_INFO_TOTALEMPLOYEES, -- 员工总数(人)
           B1.S_INFO_MAIN_BUSINESS -- 主要产品及业务
      FROM ZX90.TCL_ASHAREINTRODUCTION B1
     INNER JOIN ZX90.TCL_ASHAREDESCRIPTION A1
        ON A1.S_INFO_WINDCODE = B1.S_INFO_WINDCODE
     INNER JOIN ZX90.TCL_COMPINTRODUCTION C
        ON C.COMP_ID = A1.S_INFO_COMPCODE
     WHERE exists (SELECT 1
              FROM ZTGS.ENTERPRISEBASEINFOCOLLECT E --企业主体表
             WHERE E.PRIPID = I_OBJ_NAME
               and e.credit_code = C.REGISTERNUMBER);

  /*IF I_PAGE_NUM IS NOT NULL THEN
    V_PAGE_NUM := I_PAGE_NUM;
  END IF;
  
  --统计记录条数
  IF V_PAGE_NUM < 1 THEN
    SELECT COUNT(1)
      INTO O_TOTAL_COUNT
      FROM ZX90.TCL_ASHAREINTRODUCTION B1
     INNER JOIN ZX90.TCL_ASHAREDESCRIPTION A
        ON A.S_INFO_WINDCODE = B1.S_INFO_WINDCODE
     INNER JOIN ZX90.TCL_COMPINTRODUCTION C
        ON C.COMP_ID = A.S_INFO_COMPCODE
     WHERE exists (SELECT 1
              FROM ZTGS.ENTERPRISEBASEINFOCOLLECT E --企业主体表
             WHERE E.PRIPID = I_OBJ_NAME
               and e.credit_code = C.REGISTERNUMBER);
  END IF;
  
  IF I_PAGE_SIZE IS NOT NULL AND I_PAGE_SIZE <> 0 THEN
    V_PAGE_SIZE := I_PAGE_SIZE;
  ELSE
    V_PAGE_SIZE := O_TOTAL_COUNT;
  END IF;
  
  OPEN RT_CURSOR FOR
    SELECT
    
     B.S_INFO_PROVINCE, -- 省份
     B.S_INFO_CITY, -- 城市
     B.S_INFO_CHAIRMAN, -- 法人代表
     B.S_INFO_PRESIDENT, -- 总经理
     B.S_INFO_BDSECRETARY, -- 董事会秘书
     B.S_INFO_REGCAPITAL, -- 注册资本(万元)
     B.S_INFO_FOUNDDATE, -- 成立日期
     B.S_INFO_CHINESEINTRODUCTION, -- 公司中文简介
     B.S_INFO_COMPTYPE, -- 公司类型
     B.S_INFO_WEBSITE, -- 主页
     B.S_INFO_EMAIL, -- 电子邮箱
     B.S_INFO_OFFICE, -- 办公地址
     B.ANN_DT, -- 公告日期
     B.S_INFO_COUNTRY, -- 国籍
     B.S_INFO_BUSINESSSCOPE, -- 经营范围
     B.S_INFO_COMPANY_TYPE, -- 公司类别
     B.S_INFO_TOTALEMPLOYEES, -- 员工总数(人)
     B.S_INFO_MAIN_BUSINESS -- 主要产品及业务
      FROM (SELECT A.*, ROWNUM AS RN
              FROM (SELECT B1.S_INFO_PROVINCE, -- 省份
                           B1.S_INFO_CITY, -- 城市
                           B1.S_INFO_CHAIRMAN, -- 法人代表
                           B1.S_INFO_PRESIDENT, -- 总经理
                           B1.S_INFO_BDSECRETARY, -- 董事会秘书
                           B1.S_INFO_REGCAPITAL, -- 注册资本(万元)
                           B1.S_INFO_FOUNDDATE, -- 成立日期
                           B1.S_INFO_CHINESEINTRODUCTION, -- 公司中文简介
                           B1.S_INFO_COMPTYPE, -- 公司类型
                           B1.S_INFO_WEBSITE, -- 主页
                           B1.S_INFO_EMAIL, -- 电子邮箱
                           B1.S_INFO_OFFICE, -- 办公地址
                           B1.ANN_DT, -- 公告日期
                           B1.S_INFO_COUNTRY, -- 国籍
                           B1.S_INFO_BUSINESSSCOPE, -- 经营范围
                           B1.S_INFO_COMPANY_TYPE, -- 公司类别
                           B1.S_INFO_TOTALEMPLOYEES, -- 员工总数(人)
                           B1.S_INFO_MAIN_BUSINESS -- 主要产品及业务
                      FROM ZX90.TCL_ASHAREINTRODUCTION B1
                     INNER JOIN ZX90.TCL_ASHAREDESCRIPTION A1
                        ON A1.S_INFO_WINDCODE = B1.S_INFO_WINDCODE
                     INNER JOIN ZX90.TCL_COMPINTRODUCTION C
                        ON C.COMP_ID = A1.S_INFO_COMPCODE
                     WHERE exists
                     (SELECT 1
                              FROM ZTGS.ENTERPRISEBASEINFOCOLLECT E --企业主体表
                             WHERE E.PRIPID = I_OBJ_NAME
                               and e.credit_code = C.REGISTERNUMBER)
                    
                    ) A) B
     WHERE RN > V_PAGE_NUM
       AND RN <= V_PAGE_NUM + V_PAGE_SIZE;*/

  commit;

  O_RETURN_CODE := 0;
  O_RETURN_MSG  := '执行成功';

  -- ============================================================================
  -- 错误处理部分
  -- ============================================================================

EXCEPTION
