    V_ERROR_CODE := O_RETURN_CODE;
    P_ERROR_LOG('admin',
                V_FUNCTION_NAME,
                V_ERROR_CODE,
                V_ERROR_MSG,
                '',
                '1',
                O_RETURN_MSG,
                O_RETURN_CODE);
