Create or Replace PROCEDURE "THJS"."P_TYNEWS_ASTOCK_WITER" (RT_CURSOR  OUT TYPES.CURSORTYPE,
                                                      I_OBJ_NAME IN VARCHAR2,
                                                      --I_PAGE_NUM    IN NUMBER DEFAULT 0, --默认值0,
                                                      --I_PAGE_SIZE   IN NUMBER DEFAULT 0, --默认值0  如果I_PAGE_NUM，I_PAGE_SIZE都为0 则不分页，查询全部
                                                      --O_TOTAL_COUNT OUT INTEGER,
                                                      O_RETURN_MSG  OUT VARCHAR2,
                                                      O_RETURN_CODE OUT INTEGER) IS
  -------------------------------------------------------------------------------------
  -- COPYRIGHT          GTJA
  -- FUNC_ID            THJS.P_TYNEWS_ASTOCK_ISSU
  -- VERSION            1.0
  -- FUNC_NAME          主承销商
  -- FUNC_REMARK
  -- CREATE_DATE        2019-07-23
  -- CREATE_PROGRAMER   yongyong.zhang
  -- MODIFY_REMARK
  -- MODIFY_DATE
  --==============================================================================
  --固定变量
  V_FUNCTION_NAME VARCHAR2(64) DEFAULT 'THJS.P_TYNEWS_ASTOCK_witer'; --存储过程名
  V_ERROR_MSG     VARCHAR2(1000); --返回信息
  V_ERROR_CODE    INTEGER;
  V_ERROR_LINE    INTEGER;
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  V_PAGE_NUM  NUMBER DEFAULT 0;
  V_PAGE_SIZE NUMBER;
  --=============================================================
  -- 业务处理过程
  --=============================================================

  --------------------------业务逻辑开始-----------------------------
  begin
    open  RT_CURSOR for
      select s_info_windcode, --wind 代码
             s_lu_annissuedate, --发行公告日
             s_lu_issuedate, --发行日期
             s_lu_issuetype, --发行类型
             s_lu_totalissuecollection, --募集资金合计(万元)
             s_lu_totalissueexpenses, --发行费用合计(万元)
             s_lu_totaluderandsponefee, --承销与保荐费用(万元)
             s_lu_number, --  参与主承销商个数
             s_lu_name, -- 参与主承销商名称
             s_lu_institype, --  主承销商类型
             s_lu_aux_type, --辅助类型
             s_info_compcode, -- 主承销商id
             all_lu, --全部参与主承销商名称
             meeting_dt, -- 发审委会议日期
             pass_dt, -- 发审委通过公告日
             s_info_listdate, -- 上市日期
             type, --发行类型
             netcollection, --  募资净额合计(万元)
             avg_totalcoll, --募集总额算术平均 (万元)
             avg_netcoll -- 募资净额算术平均 (万元)
        from zx90.tcl_ashareleadunderwriter A1 --主承销商表
        join ZX90.TCL_COMPINTRODUCTION X1
          on A1.S_INFO_COMPCODE = x1.COMP_ID
       where x1.REGISTERNUMBER =
             (select E.CREDIT_CODE -- 统一社会信用代码
                from ZTGS.ENTERPRISEBASEINFOCOLLECT E --企业主体表
               where E.PRIPID = I_OBJ_NAME); --主体身份证代码
  O_RETURN_CODE := 0;
  O_RETURN_MSG  := '执行成功';

  commit;
  -- ============================================================================
  -- 错误处理部分
  -- ============================================================================

EXCEPTION
  WHEN OTHERS THEN
    O_RETURN_CODE := -1;
    O_RETURN_MSG  := V_ERROR_MSG || '--行号:' || TO_CHAR(V_ERROR_LINE) ||
                     '||sqlcode:' || SQLCODE || '||sqlerrm:||' ||
                     SUBSTR(SQLERRM, 1, 200);
    ROLLBACK;
    V_ERROR_MSG  := O_RETURN_MSG;
    V_ERROR_CODE := O_RETURN_CODE;
    P_ERROR_LOG('admin',
                V_FUNCTION_NAME,
                V_ERROR_CODE,
                V_ERROR_MSG,
                '',
                '1',
                O_RETURN_MSG,
                O_RETURN_CODE);
END;

Create or Replace PROCEDURE "THJS"."P_TYNEWS_GSXX_BRANCH" (RT_CURSOR     OUT TYPES.CURSORTYPE,
                                                      I_OBJ_NAME    IN VARCHAR2,
                                                      I_PAGE_NUM    IN NUMBER DEFAULT 0, --默认值0,
                                                      I_PAGE_SIZE   IN NUMBER DEFAULT 0, --默认值0  如果I_PAGE_NUM，I_PAGE_SIZE都为0 则不分页，查询全部
                                                      O_TOTAL_COUNT OUT INTEGER,
                                                      O_RETURN_MSG  OUT VARCHAR2,
                                                      O_RETURN_CODE OUT INTEGER) IS
  -------------------------------------------------------------------------------------
  -- COPYRIGHT          GTJA
  -- FUNC_ID            THJS.P_TYNEWS_GSXX_BRANCH
  -- VERSION            1.0
  -- FUNC_NAME          工商信息 -- 分支机构
  -- FUNC_REMARK
  -- CREATE_DATE        2019-01-28
  -- CREATE_PROGRAMER   HAIYANG.XU
  -- MODIFY_REMARK
  -- MODIFY_DATE
  --==============================================================================
  --固定变量
  V_FUNCTION_NAME VARCHAR2(64) DEFAULT 'THJS.P_TYNEWS_GSXX_BRANCH'; --存储过程名
  V_ERROR_MSG     VARCHAR2(1000); --返回信息
  V_ERROR_CODE    INTEGER;
  V_ERROR_LINE    INTEGER;
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  V_PAGE_NUM  NUMBER DEFAULT 0;
  V_PAGE_SIZE NUMBER;
  v_eid       varchar2(200);
  --=============================================================
  -- 业务处理过程
  --=============================================================

  --------------------------业务逻辑开始-----------------------------
BEGIN
  /*
   INSERT INTO THJS.T_TEST(C1,C2,C3,C4) VALUES(V_FUNCTION_NAME,I_OBJ_NAME,I_PAGE_NUM,I_PAGE_SIZE);
    COMMIT;
  */
  IF I_PAGE_NUM IS NOT NULL THEN
    V_PAGE_NUM := I_PAGE_NUM;
  END IF;

  select nvl(e.eid, '')
    into v_eid
    from dual
    left join ztgs.enterprisebaseinfocollect e
      on e.pripid = I_OBJ_NAME;

  --统计记录条数
  IF V_PAGE_NUM < 1 THEN
    SELECT COUNT(1)
      INTO O_TOTAL_COUNT
      FROM ZTGS.FILIATION T
     WHERE T.Eid = v_eid --'310000000081994112400013'
       AND T.MODIFY_TYPE <> 'D';
  END IF;

  IF I_PAGE_SIZE IS NOT NULL AND I_PAGE_SIZE <> 0 THEN
    V_PAGE_SIZE := I_PAGE_SIZE;
  ELSE
    V_PAGE_SIZE := O_TOTAL_COUNT;
  END IF;

  OPEN RT_CURSOR FOR
    SELECT B.PRIPID AS ENT_ID, --企业唯一id
           B.ENTNAME, --企业（机构）名称
           B.CREDIT_CODE, --统一社会信用代码
           B.REGNO, --注册号
           --B.BR_NO,            --序号
           B.BR_EID         AS BR_ENT_ID, --分支机构唯一id
           B.BR_CREDIT_CODE, --分支机构统一社会信用代码
           B.BR_REGNO, --分支机构注册号
           B.BR_ENTNAME, --分支机构名称
           B.BR_REGORG_NAME, --分支机构工商登记机关
           B.BR_PRINCIPAL, --分支机构负责人
           B.BR_OPSCOPE, --分支机构经营范围
           B.BR_ADDR, --分支机构地址
           B.BR_ESDATE, --分支机构成立日期
           B.UPDATE_TIME    AS UPDATETIME, --创建时间
           B.CREATE_TIME    AS CREATETIME, --更新时间
           B.MODIFY_TYPE --操作类型：i新增 u更新 d删除
    
      FROM (SELECT A.*, ROWNUM AS RN
              FROM (SELECT T.PRIPID, --企业唯一id
                           T.ENTNAME, --企业（机构）名称
                           T.CREDIT_CODE, --统一社会信用代码
                           T.REGNO, --注册号
                           --T.BR_NO,            --序号
                           T.BR_EID, --分支机构唯一id
                           T.BR_CREDIT_CODE, --分支机构统一社会信用代码
                           T.BR_REGNO, --分支机构注册号
                           T.BR_ENTNAME, --分支机构名称
                           T.BR_REGORG_NAME, --分支机构工商登记机关
                           T.BR_PRINCIPAL, --分支机构负责人
                           T.BR_OPSCOPE, --分支机构经营范围
                           T.BR_ADDR, --分支机构地址
                           REPLACE(T.BR_ESDATE, '-', '') BR_ESDATE, --分支机构成立日期
                           REPLACE(T.UPDATE_TIME, '-', '') UPDATE_TIME, --创建时间
                           REPLACE(T.CREATE_TIME, '-', '') CREATE_TIME, --更新时间
                           T.MODIFY_TYPE --操作类型：i新增 u更新 d删除
                      FROM ZTGS.FILIATION T
                     WHERE T.Eid = v_eid --'310000000081994112400013'
                       AND T.MODIFY_TYPE <> 'D'
                     ORDER BY CREATE_TIME DESC) A) B
     WHERE RN > V_PAGE_NUM
       AND RN <= V_PAGE_NUM + V_PAGE_SIZE;
  O_RETURN_CODE := 0;
  O_RETURN_MSG  := '执行成功';

  -- ============================================================================
  -- 错误处理部分
  -- ============================================================================

EXCEPTION
  WHEN OTHERS THEN
    O_RETURN_CODE := -1;
    O_RETURN_MSG  := V_ERROR_MSG || '--行号:' || TO_CHAR(V_ERROR_LINE) ||
                     '||sqlcode:' || SQLCODE || '||sqlerrm:||' ||
                     SUBSTR(SQLERRM, 1, 200);
    ROLLBACK;
    V_ERROR_MSG  := O_RETURN_MSG;
    V_ERROR_CODE := O_RETURN_CODE;
    P_ERROR_LOG('admin',
                V_FUNCTION_NAME,
                V_ERROR_CODE,
                V_ERROR_MSG,
                '',
                '1',
                O_RETURN_MSG,
                O_RETURN_CODE);
END;

Create or Replace PROCEDURE "THJS"."P_TYNEWS_GSXX_CHANGE" (RT_CURSOR     OUT TYPES.CURSORTYPE,
                                                      I_OBJ_NAME    IN VARCHAR2,
                                                      I_PAGE_NUM    IN NUMBER DEFAULT 0, --默认值0,
