  /*
   INSERT INTO THJS.T_TEST(C1,C2,C3,C4) VALUES(V_FUNCTION_NAME,I_OBJ_NAME,I_PAGE_NUM,I_PAGE_SIZE);
    COMMIT;
  */
  IF I_PAGE_NUM IS NOT NULL THEN
    V_PAGE_NUM := I_PAGE_NUM;
  END IF;

  --统计记录条数
  IF V_PAGE_NUM < 1 THEN
    SELECT COUNT(1)
      INTO O_TOTAL_COUNT
      FROM ZTGS.E_ALTER_RECODER T
     WHERE T.PRIPID = I_OBJ_NAME --'3300006000006418'
       AND T.MODIFY_TYPE <> 'D';
  END IF;

  IF I_PAGE_SIZE IS NOT NULL AND I_PAGE_SIZE <> 0 THEN
    V_PAGE_SIZE := I_PAGE_SIZE;
  ELSE
    V_PAGE_SIZE := O_TOTAL_COUNT;
  END IF;

  OPEN RT_CURSOR FOR
    SELECT B.PRIPID, --主体身份代码
           B.ALTBE, --变更前内容
           B.ALTAF, --变更后内容
           B.ALTDATE, --变更时间
           B.update_time as S_EXT_TIMESTAMP, --数据更新时间
           B.ALTITEM_NAME, --变更类型事项_中文
           B.MODIFY_TYPE --操作类型：I新增 U更新 D删除
    
      FROM (SELECT A.*, ROWNUM AS RN
              FROM (SELECT T.PRIPID, --主体身份代码
                           TO_CHAR(T.ALTBE) ALTBE, --变更前内容
                           TO_CHAR(T.ALTAF) ALTAF, --变更后内容
                           REPLACE(T.ALTDATE, '-', '') ALTDATE, --变更时间
                           REPLACE(T.update_time, '-', '') update_time, --数据更新时间
                           T.ALTITEM_NAME, --变更类型事项_中文
                           T.MODIFY_TYPE --操作类型：I新增 U更新 D删除
                      FROM ZTGS.E_ALTER_RECODER T
                     WHERE T.PRIPID = I_OBJ_NAME --'3300006000006418'
                       AND T.MODIFY_TYPE <> 'D'
                     ORDER BY T.ALTDATE DESC) A) B
     WHERE RN > V_PAGE_NUM
       AND RN <= V_PAGE_NUM + V_PAGE_SIZE;
  O_RETURN_CODE := 0;
  O_RETURN_MSG  := '执行成功';

  -- ============================================================================
  -- 错误处理部分
  -- ============================================================================

EXCEPTION
  WHEN OTHERS THEN
    O_RETURN_CODE := -1;
    O_RETURN_MSG  := V_ERROR_MSG || '--行号:' || TO_CHAR(V_ERROR_LINE) ||
                     '||sqlcode:' || SQLCODE || '||sqlerrm:||' ||
                     SUBSTR(SQLERRM, 1, 200);
    ROLLBACK;
    V_ERROR_MSG  := O_RETURN_MSG;
    V_ERROR_CODE := O_RETURN_CODE;
    P_ERROR_LOG('admin',
                V_FUNCTION_NAME,
                V_ERROR_CODE,
                V_ERROR_MSG,
                '',
                '1',
                O_RETURN_MSG,
                O_RETURN_CODE);
END;

Create or Replace PROCEDURE "THJS"."P_TYNEWS_GSXX_CHATTEL" (RT_CURSOR     OUT TYPES.CURSORTYPE,
                                                       I_OBJ_NAME    IN VARCHAR2,
                                                       I_PAGE_NUM    IN NUMBER DEFAULT 0, --默认值0,
                                                       I_PAGE_SIZE   IN NUMBER DEFAULT 0, --默认值0  如果I_PAGE_NUM，I_PAGE_SIZE都为0 则不分页，查询全部
                                                       O_TOTAL_COUNT OUT INTEGER,
                                                       O_RETURN_MSG  OUT VARCHAR2,
                                                       O_RETURN_CODE OUT INTEGER) IS
  -------------------------------------------------------------------------------------
  -- COPYRIGHT          GTJA
  -- FUNC_ID            THJS.P_TYNEWS_GSXX_CHATTEL
  -- VERSION            1.0
  -- FUNC_NAME          工商信息 -- 动产抵押
  -- FUNC_REMARK
  -- CREATE_DATE        2019-01-29
  -- CREATE_PROGRAMER   HAIYANG.XU
  -- MODIFY_REMARK
  -- MODIFY_DATE
  --==============================================================================
  --固定变量
  V_FUNCTION_NAME VARCHAR2(64) DEFAULT 'THJS.P_TYNEWS_GSXX_CHATTEL'; --存储过程名
  V_ERROR_MSG     VARCHAR2(1000); --返回信息
  V_ERROR_CODE    INTEGER;
  V_ERROR_LINE    INTEGER;
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  V_PAGE_NUM  NUMBER DEFAULT 0;
  V_PAGE_SIZE NUMBER;
  --=============================================================
  -- 业务处理过程
  --=============================================================

  --------------------------业务逻辑开始-----------------------------
BEGIN
  /*
   INSERT INTO THJS.T_TEST(C1,C2,C3,C4) VALUES(V_FUNCTION_NAME,I_OBJ_NAME,I_PAGE_NUM,I_PAGE_SIZE);
    COMMIT;
  */
  IF I_PAGE_NUM IS NOT NULL THEN
    V_PAGE_NUM := I_PAGE_NUM;
  END IF;

  --统计记录条数
  IF V_PAGE_NUM < 1 THEN
    SELECT COUNT(1)
      INTO O_TOTAL_COUNT
      FROM ZTGS.MORT_REG_INFO T
     WHERE T.EID = (SELECT E.EID
                      FROM ZTGS.ENTERPRISEBASEINFOCOLLECT E --企业主体表
                     WHERE E.PRIPID = I_OBJ_NAME)
       AND T.MODIFY_TYPE <> 'D';
  END IF;

  IF I_PAGE_SIZE IS NOT NULL AND I_PAGE_SIZE <> 0 THEN
    V_PAGE_SIZE := I_PAGE_SIZE;
  ELSE
    V_PAGE_SIZE := O_TOTAL_COUNT;
  END IF;

  OPEN RT_CURSOR FOR
    SELECT B.MORT_REG_ID, --抵押登记id
           B.MORT_REGCNO, --动产抵押登记编号
           B.REGORG, --登记机关
           B.STATUS      AS TYPE, --状态
           B.REGDATE, --登记日期
           B.MORT_CANREA, --抵押注销原因
           B.CANDATE, --注销日期
           B.EID, --企业id
           B.MORT_GAGOR, --抵押人
           B.UPDATE_TIME AS S_EXT_TIMESTAMP, --数据更新时间
           B.MODIFY_TYPE --操作类型：i新增 u更新 d删除
    
      FROM (SELECT A.*, ROWNUM AS RN
              FROM (SELECT T.MORT_REG_ID, --抵押登记id
                           T.MORT_REGCNO, --动产抵押登记编号
                           T.REGORG, --登记机关
                           T.STATUS, --状态
                           REPLACE(T.REGDATE, '-', '') REGDATE, --登记日期
                           T.MORT_CANREA, --抵押注销原因
                           T.CANDATE, --注销日期
                           T.EID, --企业id
                           T.MORT_GAGOR, --抵押人
                           REPLACE(T.UPDATE_TIME, '-', '') UPDATE_TIME, --数据更新时间
                           T.MODIFY_TYPE --操作类型：i新增 u更新 d删除
                      FROM ZTGS.MORT_REG_INFO T
                     WHERE T.EID = (SELECT E.EID
                                      FROM ZTGS.ENTERPRISEBASEINFOCOLLECT E --企业主体表
                                     WHERE E.PRIPID = I_OBJ_NAME)
                       AND T.MODIFY_TYPE <> 'D'
                     ORDER BY T.REGDATE DESC) A) B
     WHERE RN > V_PAGE_NUM
       AND RN <= V_PAGE_NUM + V_PAGE_SIZE;
  O_RETURN_CODE := 0;
  O_RETURN_MSG  := '执行成功';

  -- ============================================================================
  -- 错误处理部分
  -- ============================================================================

EXCEPTION
  WHEN OTHERS THEN
    O_RETURN_CODE := -1;
    O_RETURN_MSG  := V_ERROR_MSG || '--行号:' || TO_CHAR(V_ERROR_LINE) ||
                     '||sqlcode:' || SQLCODE || '||sqlerrm:||' ||
                     SUBSTR(SQLERRM, 1, 200);
    ROLLBACK;
    V_ERROR_MSG  := O_RETURN_MSG;
    V_ERROR_CODE := O_RETURN_CODE;
    P_ERROR_LOG('admin',
                V_FUNCTION_NAME,
                V_ERROR_CODE,
                V_ERROR_MSG,
                '',
                '1',
                O_RETURN_MSG,
                O_RETURN_CODE);
END;

Create or Replace PROCEDURE "THJS"."P_TYNEWS_GSXX_FATAL" (RT_CURSOR     OUT TYPES.CURSORTYPE,
                                                     I_OBJ_NAME    IN VARCHAR2,
                                                     I_PAGE_NUM    IN NUMBER DEFAULT 0, --默认值0,
                                                     I_PAGE_SIZE   IN NUMBER DEFAULT 0, --默认值0  如果I_PAGE_NUM，I_PAGE_SIZE都为0 则不分页，查询全部
                                                     O_TOTAL_COUNT OUT INTEGER,
                                                     O_RETURN_MSG  OUT VARCHAR2,
                                                     O_RETURN_CODE OUT INTEGER) IS
  -------------------------------------------------------------------------------------
  -- COPYRIGHT          GTJA
  -- FUNC_ID            THJS.P_TYNEWS_GSXX_FATAL
  -- VERSION            1.0
  -- FUNC_NAME          工商信息 -- 严重违法
  -- FUNC_REMARK
  -- CREATE_DATE        2019-01-29
  -- CREATE_PROGRAMER   HAIYANG.XU
  -- MODIFY_REMARK
  -- MODIFY_DATE
  --==============================================================================
  --固定变量
  V_FUNCTION_NAME VARCHAR2(64) DEFAULT 'THJS.P_TYNEWS_GSXX_FATAL'; --存储过程名
  V_ERROR_MSG     VARCHAR2(1000); --返回信息
  V_ERROR_CODE    INTEGER;
  V_ERROR_LINE    INTEGER;
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  V_PAGE_NUM  NUMBER DEFAULT 0;
  V_PAGE_SIZE NUMBER;
  --=============================================================
  -- 业务处理过程
  --=============================================================
  --'430000000022011122900047'
  --------------------------业务逻辑开始-----------------------------
BEGIN
  /*
   INSERT INTO THJS.T_TEST(C1,C2,C3,C4) VALUES(V_FUNCTION_NAME,I_OBJ_NAME,I_PAGE_NUM,I_PAGE_SIZE);
    COMMIT;
  */
  IF I_PAGE_NUM IS NOT NULL THEN
    V_PAGE_NUM := I_PAGE_NUM;
  END IF;

  --统计记录条数
  IF V_PAGE_NUM < 1 THEN
    SELECT COUNT(1)
      INTO O_TOTAL_COUNT
      FROM ZTGS.E_LI_ILLDISDETAIL T
     WHERE T.EID = (SELECT E.EID
                      FROM ZTGS.ENTERPRISEBASEINFOCOLLECT E --企业主体表
                     WHERE E.PRIPID = I_OBJ_NAME)
       AND T.MODIFY_TYPE <> 'D';
  END IF;

  IF I_PAGE_SIZE IS NOT NULL AND I_PAGE_SIZE <> 0 THEN
    V_PAGE_SIZE := I_PAGE_SIZE;
  ELSE
    V_PAGE_SIZE := O_TOTAL_COUNT;
  END IF;

  OPEN RT_CURSOR FOR
    SELECT B.EID, --企业id
           B.REGNO, --注册号
           B.ENTNAME, --企业名
           B.CREDIT_CODE, --统一社会信用代码
           B.LEGAL_PERSON  AS NAME, --法人姓名
           B.SERILLREA_CN, --列入事由/情形（中文名称）
           B.ABNTIME, --列入日期
           B.DECORG_CN, --列入作出决定机关（中文名称）
           B.DEDOCNUM, --列入文号
           B.REMEXCPRES_CN, --移出事由（中文名称）
           B.REMDATE, --移出日期
           B.RECORG_CN, --移出作出决定机关（中文名称）
           B.REDOCNUM, --移出文号
           B.IS_MOVE, --是否移出
           B.PROV          AS PRO, --省份
           B.CREATE_TIME, --更新时间
           B.MODIFY_TYPE --操作类型：i新增 u更新 d删除
    
      FROM (SELECT A.*, ROWNUM AS RN
              FROM (SELECT T.EID, --企业id
                           T.REGNO, --注册号
                           T.ENTNAME, --企业名
                           T.CREDIT_CODE, --统一社会信用代码
                           T.LEGAL_PERSON, --法人姓名
                           T.SERILLREA_CN, --列入事由/情形（中文名称）
                           REPLACE(T.ABNTIME, '-', '') ABNTIME, --列入日期
                           T.DECORG_CN, --列入作出决定机关（中文名称）
                           T.DEDOCNUM, --列入文号
                           T.REMEXCPRES_CN, --移出事由（中文名称）
                           REPLACE(T.REMDATE, '-', '') REMDATE, --移出日期
                           T.RECORG_CN, --移出作出决定机关（中文名称）
                           T.REDOCNUM, --移出文号
                           DECODE(T.IS_MOVE, 0, '否', 1, '是') IS_MOVE, --是否移出
                           T.PROV, --省份
                           REPLACE(T.CREATE_TIME, '-', '') CREATE_TIME, --更新时间
                           T.MODIFY_TYPE --操作类型：i新增 u更新 d删除
                      FROM ZTGS.E_LI_ILLDISDETAIL T
                     WHERE T.EID = (SELECT E.EID
                                      FROM ZTGS.ENTERPRISEBASEINFOCOLLECT E --企业主体表
                                     WHERE E.PRIPID = I_OBJ_NAME)
                       AND T.MODIFY_TYPE <> 'D'
                     ORDER BY T.ABNTIME DESC) A) B
     WHERE RN > V_PAGE_NUM
       AND RN <= V_PAGE_NUM + V_PAGE_SIZE;
  O_RETURN_CODE := 0;
  O_RETURN_MSG  := '执行成功';

  -- ============================================================================
  -- 错误处理部分
  -- ============================================================================

EXCEPTION
  WHEN OTHERS THEN
    O_RETURN_CODE := -1;
    O_RETURN_MSG  := V_ERROR_MSG || '--行号:' || TO_CHAR(V_ERROR_LINE) ||
                     '||sqlcode:' || SQLCODE || '||sqlerrm:||' ||
                     SUBSTR(SQLERRM, 1, 200);
    ROLLBACK;
    V_ERROR_MSG  := O_RETURN_MSG;
    V_ERROR_CODE := O_RETURN_CODE;
    P_ERROR_LOG('admin',
                V_FUNCTION_NAME,
                V_ERROR_CODE,
                V_ERROR_MSG,
                '',
                '1',
                O_RETURN_MSG,
                O_RETURN_CODE);
END;

Create or Replace PROCEDURE "THJS"."P_TYNEWS_GSXX_FREEZE" (RT_CURSOR     OUT TYPES.CURSORTYPE,
                                                      I_OBJ_NAME    IN VARCHAR2,
                                                      I_PAGE_NUM    IN NUMBER DEFAULT 0, --默认值0,
                                                      I_PAGE_SIZE   IN NUMBER DEFAULT 0, --默认值0  如果I_PAGE_NUM，I_PAGE_SIZE都为0 则不分页，查询全部
                                                      O_TOTAL_COUNT OUT INTEGER,
                                                      O_RETURN_MSG  OUT VARCHAR2,
                                                      O_RETURN_CODE OUT INTEGER) IS
  -------------------------------------------------------------------------------------
  -- COPYRIGHT          GTJA
  -- FUNC_ID            THJS.P_TYNEWS_GSXX_FREEZE
  -- VERSION            1.0
  -- FUNC_NAME          工商信息 -- 股权冻结
  -- FUNC_REMARK
  -- CREATE_DATE        2019-01-29
  -- CREATE_PROGRAMER   HAIYANG.XU
  -- MODIFY_REMARK
  -- MODIFY_DATE
  --==============================================================================
  --固定变量
  V_FUNCTION_NAME VARCHAR2(64) DEFAULT 'THJS.P_TYNEWS_GSXX_FREEZE'; --存储过程名
  V_ERROR_MSG     VARCHAR2(1000); --返回信息
  V_ERROR_CODE    INTEGER;
  V_ERROR_LINE    INTEGER;
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  V_PAGE_NUM  NUMBER DEFAULT 0;
  V_PAGE_SIZE NUMBER;
  --=============================================================
  -- 业务处理过程
  --=============================================================

  --------------------------业务逻辑开始-----------------------------
BEGIN
  /*
   INSERT INTO THJS.T_TEST(C1,C2,C3,C4) VALUES(V_FUNCTION_NAME,I_OBJ_NAME,I_PAGE_NUM,I_PAGE_SIZE);
    COMMIT;
  */
  IF I_PAGE_NUM IS NOT NULL THEN
    V_PAGE_NUM := I_PAGE_NUM;
  END IF;

  --统计记录条数
  IF V_PAGE_NUM < 1 THEN
    SELECT COUNT(1)
      INTO O_TOTAL_COUNT
      FROM ZTGS.e_shares_frost_new T
     WHERE T.EID = (SELECT DISTINCT E.EID
                      FROM ZTGS.ENTERPRISEBASEINFOCOLLECT E --企业主体表
                     WHERE E.PRIPID = I_OBJ_NAME) --'130000000012000122100030')
       AND T.MODIFY_TYPE <> 'D';
  END IF;

  IF I_PAGE_SIZE IS NOT NULL AND I_PAGE_SIZE <> 0 THEN
    V_PAGE_SIZE := I_PAGE_SIZE;
  ELSE
    V_PAGE_SIZE := O_TOTAL_COUNT;
  END IF;

  OPEN RT_CURSOR FOR
    SELECT B.EID, --企业ID     
           B.FROST_ID, --股权冻结ID
           TO_NUMBER(B.JUDICIALNO) JUDICIALNO, --序号
           B.JUDICIALINV, --被执行人
           B.JUDICIALFROAM, --股权数额
           B.JUDICIALFROAUTH, --执行法院
           B.JUDICIALEXECUTENO, --执行通知书文号
           B.JUDICIALFROZSTATE, --类型|状态
           B.FROAUTH, --冻结执行法院
           B.EXECUTEITEMNAME, --执行事项
           B.FRODOCNO, --冻结执行裁定书文号
           B.EXECUTENO, --冻结执行通知书文号
           B.FXT_INV, --被执行人
           B.FXT_FROAM, --被执行人持有股权、其它投资权益的数额
           B.FXT_CERTYPENAME, --被执行人证件种类
           B.FXT_CERNO, --被执行人证件号码
           REPLACE(B.FROFROMSTRING, '-', '') FROFROMSTRING, --冻结期限自
           REPLACE(B.FROTOSTRING, '-', '') FROTOSTRING, --冻结期限至
           B.FROZDEADLINESTRING, --冻结期限
           REPLACE(B.PUBLICDATESTRING, '-', '') PUBLICDATESTRING, --冻结公示日期
           B.THAWAUTH, --解冻执行法院
           B.THAWEXECUTEITEMNAME, --解冻执行事项
           B.THAWDOCNO, --解冻执行裁定书文号
           B.THAWEXECUTENO, --解冻执行通知书文号
           REPLACE(B.THAWDATESTRING, '-', '') THAWDATESTRING, --解除冻结日期
           REPLACE(B.THAWPUBLICDATESTRING, '-', '') THAWPUBLICDATESTRING, --解冻公示日期
           REPLACE(B.INVALIDTIME, '-', '') INVALIDTIME, --失效时间
           B.INVALIDREASON, --失效原因
           REPLACE(B.KEEPFROZFROM, '-', '') KEEPFROZFROM, --续行冻结期限自
           REPLACE(B.KEEPFROZTO, '-', '') KEEPFROZTO, --续行冻结期限至
           B.KEEPFROZDEADLINE --续行冻结期限
    
      FROM (SELECT A.*, ROWNUM AS RN
              FROM (SELECT DISTINCT T.EID, --企业ID     
                                    T.FROST_ID, --股权冻结ID
                                    TO_NUMBER(T.JUDICIALNO) JUDICIALNO, --序号
                                    T.JUDICIALINV, --被执行人
                                    T.JUDICIALFROAM, --股权数额
                                    T.JUDICIALFROAUTH, --执行法院
                                    T.JUDICIALEXECUTENO, --执行通知书文号
                                    T.JUDICIALFROZSTATE, --类型|状态
                                    T.FROAUTH, --冻结执行法院
                                    T.EXECUTEITEMNAME, --执行事项
                                    T.FRODOCNO, --冻结执行裁定书文号
                                    T.EXECUTENO, --冻结执行通知书文号
                                    T.FXT_INV, --被执行人
                                    T.FXT_FROAM, --被执行人持有股权、其它投资权益的数额
                                    T.FXT_CERTYPENAME, --被执行人证件种类
                                    T.FXT_CERNO, --被执行人证件号码
                                    REPLACE(T.FROFROMSTRING, '-', '') FROFROMSTRING, --冻结期限自
                                    REPLACE(T.FROTOSTRING, '-', '') FROTOSTRING, --冻结期限至
                                    T.FROZDEADLINESTRING, --冻结期限
                                    REPLACE(T.PUBLICDATESTRING, '-', '') PUBLICDATESTRING, --冻结公示日期
                                    T.THAWAUTH, --解冻执行法院
                                    T.THAWEXECUTEITEMNAME, --解冻执行事项
                                    T.THAWDOCNO, --解冻执行裁定书文号
                                    T.THAWEXECUTENO, --解冻执行通知书文号
                                    REPLACE(T.THAWDATESTRING, '-', '') THAWDATESTRING, --解除冻结日期
                                    REPLACE(T.THAWPUBLICDATESTRING, '-', '') THAWPUBLICDATESTRING, --解冻公示日期
                                    REPLACE(T.INVALIDTIME, '-', '') INVALIDTIME, --失效时间
                                    T.INVALIDREASON, --失效原因
                                    REPLACE(T.KEEPFROZFROM, '-', '') KEEPFROZFROM, --续行冻结期限自
                                    REPLACE(T.KEEPFROZTO, '-', '') KEEPFROZTO, --续行冻结期限至
                                    T.KEEPFROZDEADLINE --续行冻结期限
                      FROM ZTGS.e_shares_frost_new T
                     WHERE T.EID = (SELECT DISTINCT E.EID
                                      FROM ZTGS.ENTERPRISEBASEINFOCOLLECT E --企业主体表
                                     WHERE E.PRIPID = I_OBJ_NAME) --'130000000012000122100030')
                       AND T.MODIFY_TYPE <> 'D'
                     ORDER BY JUDICIALNO) A) B
     WHERE RN > V_PAGE_NUM
       AND RN <= V_PAGE_NUM + V_PAGE_SIZE;
  O_RETURN_CODE := 0;
  O_RETURN_MSG  := '执行成功';

  -- ============================================================================
  -- 错误处理部分
  -- ============================================================================

EXCEPTION
  WHEN OTHERS THEN
    O_RETURN_CODE := -1;
    O_RETURN_MSG  := V_ERROR_MSG || '--行号:' || TO_CHAR(V_ERROR_LINE) ||
                     '||sqlcode:' || SQLCODE || '||sqlerrm:||' ||
                     SUBSTR(SQLERRM, 1, 200);
    ROLLBACK;
    V_ERROR_MSG  := O_RETURN_MSG;
    V_ERROR_CODE := O_RETURN_CODE;
    P_ERROR_LOG('admin',
                V_FUNCTION_NAME,
                V_ERROR_CODE,
                V_ERROR_MSG,
                '',
                '1',
                O_RETURN_MSG,
                O_RETURN_CODE);
END;

Create or Replace PROCEDURE "THJS"."P_TYNEWS_GSXX_HOLDER" (RT_CURSOR     OUT TYPES.CURSORTYPE,
                                                      I_OBJ_NAME    IN VARCHAR2,
                                                      I_PAGE_NUM    IN NUMBER DEFAULT 0, --默认值0,
                                                      I_PAGE_SIZE   IN NUMBER DEFAULT 0, --默认值0  如果I_PAGE_NUM，I_PAGE_SIZE都为0 则不分页，查询全部
                                                      O_TOTAL_COUNT OUT INTEGER,
                                                      O_RETURN_MSG  OUT VARCHAR2,
                                                      O_RETURN_CODE OUT INTEGER) IS
  -------------------------------------------------------------------------------------
  -- COPYRIGHT          GTJA
  -- FUNC_ID            THJS.P_TYNEWS_GSXX_HOLDER
  -- VERSION            1.0
  -- FUNC_NAME          工商信息 -- 股东信息
  -- FUNC_REMARK
  -- CREATE_DATE        2019-01-28
  -- CREATE_PROGRAMER   HAIYANG.XU
  -- MODIFY_REMARK
  -- MODIFY_DATE
  --==============================================================================
  --固定变量
  V_FUNCTION_NAME VARCHAR2(64) DEFAULT 'THJS.P_TYNEWS_GSXX_HOLDER'; --存储过程名
  V_ERROR_MSG     VARCHAR2(1000); --返回信息
  V_ERROR_CODE    INTEGER;
  V_ERROR_LINE    INTEGER;
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  V_PAGE_NUM  NUMBER DEFAULT 0;
  V_PAGE_SIZE NUMBER;
  --=============================================================
  -- 业务处理过程
  --=============================================================

  --------------------------业务逻辑开始-----------------------------
BEGIN
  /*
   INSERT INTO THJS.T_TEST(C1,C2,C3,C4) VALUES(V_FUNCTION_NAME,I_OBJ_NAME,I_PAGE_NUM,I_PAGE_SIZE);
    COMMIT;
  */
  IF I_PAGE_NUM IS NOT NULL THEN
    V_PAGE_NUM := I_PAGE_NUM;
  END IF;

  --统计记录条数
  IF V_PAGE_NUM < 1 THEN
    SELECT COUNT(1)
      INTO O_TOTAL_COUNT
      FROM ZTGS.E_INV_INVESTMENT T
     WHERE T.PRIPID = I_OBJ_NAME --'310000000011999081800013'
       AND T.MODIFY_TYPE <> 'D';
  END IF;

  IF I_PAGE_SIZE IS NOT NULL AND I_PAGE_SIZE <> 0 THEN
    V_PAGE_SIZE := I_PAGE_SIZE;
  ELSE
    V_PAGE_SIZE := O_TOTAL_COUNT;
  END IF;

  OPEN RT_CURSOR FOR
    SELECT B.PRIPID, --主体身份代码
           B.INV, --投资人名称
           B.INVTYPE, --投资人类型
           B.BLICTYPE, --证照类型
           B.SUBCONAM, --认缴出资额
           B.ACCONAM, --实缴出资额
           B.CONDATE, --出资日期
           B.update_time as S_EXT_TIMESTAMP, --数据更新时间
           B.CURRENCY_NAME, --币种
           B.MODIFY_TYPE --操作类型：I新增 U更新 D删除
    
      FROM (SELECT A.*, ROWNUM AS RN
              FROM (SELECT T.PRIPID, --主体身份代码
                           T.INV, --投资人名称
                           T.INVTYPE, --投资人类型
                           case T.BLICTYPE
                             when '1' then
                              '内资企业法人'
                             when '11' then
                              '企业法人营业执照(公司)'
                             when '12' then
                              '企业法人营业执照(非公司)'
                             when '13' then
                              '企业集团登记证'
                             when '14' then
                              '营业执照(分公司、营业单位)'
                             when '2' then
                              '外资企业法人'
                             when '21' then
                              '企业法人营业执照(外资)'
                             when '22' then
                              '营业执照(外资)'
                             when '23' then
                              '外国企业常驻代表机构登记证'
                             when '24' then
                              '外商投资企业办事机构注册证'
                             when '25' then
                              '外商投资合伙企业营业执照'
                             when '26' then
                              '外商投资合伙企业分支机构营业执照'
                             when '3' then
                              '非法人企业、个体工商户'
                             when '31' then
                              '个人独资企业营业执照'
                             when '32' then
                              '合伙企业营业执照'
                             when '33' then
                              '个体工商户营业执照'
                             when '36' then
                              '合伙企业分支机构营业执照'
                             when '6' then
                              '机关、事业、社团法人'
                             when '61' then
                              '事业法人登记证'
                             when '62' then
                              '社团法人登记证'
                             when '63' then
                              '机关法人登记证'
                             when '66' then
                              '不需要登记的社团法人'
                             when '7' then
                              '农业专业合作社'
                             when '71' then
                              '农业专业合作社营业执照'
                             when '72' then
                              '农业专业合作社分之机构营业执照'
                             when '8' then
                              '外国（地区）证照'
                             when '9' then
                              T.BLICTYPE
                           end BLICTYPE, -- T.BLICTYPE,         --证照类型
                           T.SUBCONAM, --认缴出资额
                           T.ACCONAM, --实缴出资额
                           T.CONDATE, --出资日期
                           REPLACE(T.update_time, '-', '') update_time, --数据更新时间
                           T.CURRENCY_NAME, --币种
                           T.MODIFY_TYPE --操作类型：I新增 U更新 D删除
                      FROM ZTGS.E_INV_INVESTMENT T
                     WHERE T.PRIPID = I_OBJ_NAME --'310000000011999081800013'
                       AND T.MODIFY_TYPE <> 'D'
                     ORDER BY T.update_time DESC
                    
                    ) A) B
     WHERE RN > V_PAGE_NUM
       AND RN <= V_PAGE_NUM + V_PAGE_SIZE;
  O_RETURN_CODE := 0;
  O_RETURN_MSG  := '执行成功';

  -- ============================================================================
  -- 错误处理部分
  -- ============================================================================

EXCEPTION
  WHEN OTHERS THEN
    O_RETURN_CODE := -1;
    O_RETURN_MSG  := V_ERROR_MSG || '--行号:' || TO_CHAR(V_ERROR_LINE) ||
                     '||sqlcode:' || SQLCODE || '||sqlerrm:||' ||
                     SUBSTR(SQLERRM, 1, 200);
    ROLLBACK;
    V_ERROR_MSG  := O_RETURN_MSG;
    V_ERROR_CODE := O_RETURN_CODE;
    P_ERROR_LOG('admin',
                V_FUNCTION_NAME,
                V_ERROR_CODE,
                V_ERROR_MSG,
                '',
                '1',
                O_RETURN_MSG,
                O_RETURN_CODE);
END;

Create or Replace PROCEDURE "THJS"."P_TYNEWS_GSXX_MANAGE" (RT_CURSOR     OUT TYPES.CURSORTYPE,
                                                      I_OBJ_NAME    IN VARCHAR2,
                                                      I_PAGE_NUM    IN NUMBER DEFAULT 0, --默认值0,
                                                      I_PAGE_SIZE   IN NUMBER DEFAULT 0, --默认值0  如果I_PAGE_NUM，I_PAGE_SIZE都为0 则不分页，查询全部
                                                      O_TOTAL_COUNT OUT INTEGER,
                                                      O_RETURN_MSG  OUT VARCHAR2,
                                                      O_RETURN_CODE OUT INTEGER) IS
  -------------------------------------------------------------------------------------
  -- COPYRIGHT          GTJA
  -- FUNC_ID            THJS.P_TYNEWS_GSXX_MANAGE
  -- VERSION            1.0
  -- FUNC_NAME          工商信息 -- 经营异常
  -- FUNC_REMARK
  -- CREATE_DATE        2019-01-29
  -- CREATE_PROGRAMER   HAIYANG.XU
  -- MODIFY_REMARK
  -- MODIFY_DATE
  --==============================================================================
  --固定变量
  V_FUNCTION_NAME VARCHAR2(64) DEFAULT 'THJS.P_TYNEWS_GSXX_MANAGE'; --存储过程名
  V_ERROR_MSG     VARCHAR2(1000); --返回信息
  V_ERROR_CODE    INTEGER;
  V_ERROR_LINE    INTEGER;
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  V_PAGE_NUM  NUMBER DEFAULT 0;
  V_PAGE_SIZE NUMBER;
  --=============================================================
  -- 业务处理过程
  --=============================================================

  --------------------------业务逻辑开始-----------------------------
BEGIN
  /*
   INSERT INTO THJS.T_TEST(C1,C2,C3,C4) VALUES(V_FUNCTION_NAME,I_OBJ_NAME,I_PAGE_NUM,I_PAGE_SIZE);
    COMMIT;
  */
  IF I_PAGE_NUM IS NOT NULL THEN
    V_PAGE_NUM := I_PAGE_NUM;
  END IF;

  --统计记录条数
  IF V_PAGE_NUM < 1 THEN
    SELECT COUNT(1)
      INTO O_TOTAL_COUNT
      FROM ZTGS.BUSINESS_ABNORMAL T
     WHERE T.EID = (SELECT E.EID
                      FROM ZTGS.ENTERPRISEBASEINFOCOLLECT E --企业主体表
                     WHERE E.PRIPID = I_OBJ_NAME) --'cd834b3b-d280-42c7-9840-ee6be331c295')
       AND T.MODIFY_TYPE <> 'D';
  END IF;

  IF I_PAGE_SIZE IS NOT NULL AND I_PAGE_SIZE <> 0 THEN
    V_PAGE_SIZE := I_PAGE_SIZE;
  ELSE
    V_PAGE_SIZE := O_TOTAL_COUNT;
  END IF;

  OPEN RT_CURSOR FOR
    SELECT B.EID, --企业id
           B.ENTNAME      as ENT_NAME, --企业名称
           B.REGNO        as REG_NO, --注册号
           B.CREDIT_CODE  as SOCIAL_CREDIT_CODE, --信用代码
           B.RESULT_IN, --列入原因
           B.RESULT_OUT, --列出原因
           B.DATE_IN, --列入时间
           B.DATE_OUT, --列出时间
           B.ORG_NAME_IN, --列入机构
           B.ORG_NAME_OUT, --列出机构
           B.IS_MOVE, --是否移出
           B.CRAW_ID, --经营异常id
           B.CREATE_TIME, --创建时间
           B.MODIFY_TYPE --操作类型：i新增 u更新 d删除
      FROM (SELECT A.*, ROWNUM AS RN
              FROM (SELECT T.EID, --企业id
                           T.ENTNAME, --企业名称
                           T.REGNO, --注册号
                           T.CREDIT_CODE, --信用代码
                           T.RESULT_IN, --列入原因
                           T.RESULT_OUT, --列出原因
                           REPLACE(T.DATE_IN, '-', '') DATE_IN, --列入时间
                           REPLACE(T.DATE_OUT, '-', '') DATE_OUT, --列出时间
                           T.ORG_NAME_IN, --列入机构
                           T.ORG_NAME_OUT, --列出机构
                           DECODE(T.IS_MOVE, 0, '否', 1, '是') IS_MOVE, --是否移出
                           T.CRAW_ID, --经营异常id
                           REPLACE(T.CREATE_TIME, '-', '') CREATE_TIME, --创建时间
                           T.MODIFY_TYPE --操作类型：i新增 u更新 d删除
                      FROM ZTGS.BUSINESS_ABNORMAL T
                     WHERE T.EID = (SELECT E.EID
                                      FROM ZTGS.ENTERPRISEBASEINFOCOLLECT E --企业主体表
                                     WHERE E.PRIPID = I_OBJ_NAME) --'cd834b3b-d280-42c7-9840-ee6be331c295')
                       AND T.MODIFY_TYPE <> 'D'
                     ORDER BY T.DATE_IN DESC) A) B
     WHERE RN > V_PAGE_NUM
       AND RN <= V_PAGE_NUM + V_PAGE_SIZE;
  O_RETURN_CODE := 0;
  O_RETURN_MSG  := '执行成功';

  -- ============================================================================
  -- 错误处理部分
  -- ============================================================================

EXCEPTION
  WHEN OTHERS THEN
    O_RETURN_CODE := -1;
    O_RETURN_MSG  := V_ERROR_MSG || '--行号:' || TO_CHAR(V_ERROR_LINE) ||
                     '||sqlcode:' || SQLCODE || '||sqlerrm:||' ||
                     SUBSTR(SQLERRM, 1, 200);
    ROLLBACK;
    V_ERROR_MSG  := O_RETURN_MSG;
    V_ERROR_CODE := O_RETURN_CODE;
    P_ERROR_LOG('admin',
                V_FUNCTION_NAME,
                V_ERROR_CODE,
                V_ERROR_MSG,
                '',
                '1',
                O_RETURN_MSG,
                O_RETURN_CODE);
END;

Create or Replace PROCEDURE "THJS"."P_TYNEWS_GSXX_MEMBERS" (RT_CURSOR     OUT TYPES.CURSORTYPE,
                                                       I_OBJ_NAME    IN VARCHAR2,
