Create or Replace PROCEDURE "THJS"."P_TYNEWS_GSXX_MINFO" (RT_CURSOR     OUT TYPES.CURSORTYPE,
                                                     I_OBJ_NAME    IN VARCHAR2,
                                                     I_PAGE_NUM    IN NUMBER DEFAULT 0, --默认值0,
                                                     I_PAGE_SIZE   IN NUMBER DEFAULT 0, --默认值0  如果I_PAGE_NUM，I_PAGE_SIZE都为0 则不分页，查询全部
                                                     O_TOTAL_COUNT OUT INTEGER,
                                                     O_RETURN_MSG  OUT VARCHAR2,
                                                     O_RETURN_CODE OUT INTEGER) IS
  -------------------------------------------------------------------------------------
  -- COPYRIGHT          GTJA
  -- FUNC_ID            THJS.P_TYNEWS_GSXX_MINFO
  -- VERSION            1.0
  -- FUNC_NAME          工商信息 -- 主体信息
  -- FUNC_REMARK
  -- CREATE_DATE        2019-01-28
  -- CREATE_PROGRAMER   HAIYANG.XU
  -- MODIFY_REMARK
  -- MODIFY_DATE
  --==============================================================================
  --固定变量
  V_FUNCTION_NAME VARCHAR2(64) DEFAULT 'THJS.P_TYNEWS_GSXX_MINFO'; --存储过程名
  V_ERROR_MSG     VARCHAR2(1000); --返回信息
  V_ERROR_CODE    INTEGER;
  V_ERROR_LINE    INTEGER;
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  V_PAGE_NUM  NUMBER DEFAULT 0;
  V_PAGE_SIZE NUMBER;
  --=============================================================
  -- 业务处理过程
  --=============================================================

  --------------------------业务逻辑开始-----------------------------
BEGIN
  /*
   INSERT INTO THJS.T_TEST(C1,C2,C3,C4) VALUES(V_FUNCTION_NAME,I_OBJ_NAME,I_PAGE_NUM,I_PAGE_SIZE);
    COMMIT;
  */
  IF I_PAGE_NUM IS NOT NULL THEN
    V_PAGE_NUM := I_PAGE_NUM;
  END IF;

  --统计记录条数
  IF V_PAGE_NUM < 1 THEN
    SELECT COUNT(1)
      INTO O_TOTAL_COUNT
      FROM ZTGS.ENTERPRISEBASEINFOCOLLECT T
     WHERE T.PRIPID = I_OBJ_NAME --'430000000012015040100034'
       AND T.MODIFY_TYPE <> 'D';
  END IF;

  IF I_PAGE_SIZE IS NOT NULL AND I_PAGE_SIZE <> 0 THEN
    V_PAGE_SIZE := I_PAGE_SIZE;
  ELSE
    V_PAGE_SIZE := O_TOTAL_COUNT;
  END IF;

  OPEN RT_CURSOR FOR
    SELECT B.PRIPID,
           B.ENTNAME,
           B.REGNO,
           B.PPRIPID,
           B.INDUSTRYPHY,
           B.INDUSTRYCO,
           B.OPFROM,
           B.OPTO,
           B.ESDATE,
           B.APPRDATE,
           B.REGCAP,
           B.OPSCOPE,
           B.DOM,
           --B.RECCAP              ,
           B.S_EXT_TIMESTAMP,
           B.ENTTYPE_NAME,
           B.INDUSTRYPHY_NAME,
           B.INDUSTRYCO_NAME,
           B.REGORG_NAME,
           B.REGORG_PROV      AS REGORG_PROVINCE,
           B.REGORG_CITY,
           B.REGORG_COUNTY,
           B.CREDIT_CODE,
           B.REGCAPCUR_NAME,
           B.ENTSTATUS_NAME,
           B.LEGAL_PERSON     AS FRNAME,
           B.CANDATE,
           B.REVDATE,
           B.EID,
           B.REVAN_REA,
           B.MODIFY_TYPE
      FROM (SELECT A.*, ROWNUM AS RN
              FROM (SELECT T.PRIPID, -- 主体身份代码
                           T.ENTNAME, -- 企业(机构)名称
                           T.REGNO, -- 注册号
                           T.PPRIPID, -- 隶属企业主体身份代码
                           T.INDUSTRYPHY, -- 国民经济行业门类代码
                           T.INDUSTRYCO, -- 国民经济行业代码
                           REPLACE(T.OPFROM, '-', '') || ' 至 ' OPFROM, -- 经营(驻在)期限自
                           decode(substr(T.OPTO, 1, 4),
                                  '9999',
                                  '-',
                                  REPLACE(T.OPTO, '-', '')) OPTO, -- 经营(驻在)期限至
                           REPLACE(T.ESDATE, '-', '') ESDATE, -- 成立日期
                           REPLACE(T.APPRDATE, '-', '') APPRDATE, -- 核准日期
                           round(T.REGCAP, 4) || ' 万' REGCAP, -- 注册资本
                           T.OPSCOPE, -- 经营(业务)范围
                           T.DOM, -- 住所
                           --round(T.RECCAP,4)||' 万' RECCAP,         -- 实收资本
                           REPLACE(T.UPDATE_TIME, '-', '') S_EXT_TIMESTAMP, -- 数据更新时间
                           T.ENTTYPE_NAME, -- 企业(机构)类型中文字段
                           T.INDUSTRYPHY_NAME, -- 国民经济行业门类中文字段
                           T.INDUSTRYCO_NAME, -- 国民经济行业中文字段
                           T.REGORG_NAME, -- 登记机关中文
                           T.REGORG_PROV, -- 省
                           T.REGORG_CITY, -- 市
                           T.REGORG_COUNTY, -- 县
                           T.CREDIT_CODE, -- 统一社会信用代码
                           T.REGCAPCUR_NAME, -- 注册资本(金)币种中文字段
                           T.ENTSTATUS_NAME, -- 企业状态中文字段
                           T.LEGAL_PERSON, -- 法人名称
                           T.CANDATE, -- 注销日期
                           T.REVDATE, -- 吊销日期
                           T.EID, -- 企业ID
                           T.REVAN_REA, -- 注吊销原因
                           T.MODIFY_TYPE -- 操作类型：I新增 U更新 D删除                    
                      FROM ZTGS.ENTERPRISEBASEINFOCOLLECT T
                     WHERE T.PRIPID = I_OBJ_NAME --'430000000012015040100034'
                       AND T.MODIFY_TYPE <> 'D'
                     ORDER BY T.ESDATE DESC) A) B
     WHERE RN > V_PAGE_NUM
       AND RN <= V_PAGE_NUM + V_PAGE_SIZE;
  O_RETURN_CODE := 0;
  O_RETURN_MSG  := '执行成功';

  -- ============================================================================
  -- 错误处理部分
  -- ============================================================================

EXCEPTION
  WHEN OTHERS THEN
    O_RETURN_CODE := -1;
    O_RETURN_MSG  := V_ERROR_MSG || '--行号:' || TO_CHAR(V_ERROR_LINE) ||
                     '||sqlcode:' || SQLCODE || '||sqlerrm:||' ||
                     SUBSTR(SQLERRM, 1, 200);
    ROLLBACK;
    V_ERROR_MSG  := O_RETURN_MSG;
    V_ERROR_CODE := O_RETURN_CODE;
    P_ERROR_LOG('admin',
                V_FUNCTION_NAME,
                V_ERROR_CODE,
                V_ERROR_MSG,
                '',
                '1',
                O_RETURN_MSG,
                O_RETURN_CODE);
END;

Create or Replace PROCEDURE "THJS"."P_TYNEWS_GSXX_OUTINVESTA" (RT_CURSOR     OUT TYPES.CURSORTYPE,
                                                          I_OBJ_NAME    IN VARCHAR2,
                                                          I_PAGE_NUM    IN NUMBER DEFAULT 0, --默认值0,
                                                          I_PAGE_SIZE   IN NUMBER DEFAULT 0, --默认值0  如果I_PAGE_NUM，I_PAGE_SIZE都为0 则不分页，查询全部
                                                          O_TOTAL_COUNT OUT INTEGER,
                                                          O_RETURN_MSG  OUT VARCHAR2,
                                                          O_RETURN_CODE OUT INTEGER) IS
  -------------------------------------------------------------------------------------
  -- COPYRIGHT          GTJA
  -- FUNC_ID            THJS.P_TYNEWS_GSXX_OUTINVESTA
  -- VERSION            1.0
  -- FUNC_NAME          工商信息 -- 对外投资
  -- FUNC_REMARK
  -- CREATE_DATE        2019-01-28
  -- CREATE_PROGRAMER   HAIYANG.XU
  -- MODIFY_REMARK
  -- MODIFY_DATE
  --==============================================================================
  --固定变量
  V_FUNCTION_NAME VARCHAR2(64) DEFAULT 'THJS.P_TYNEWS_GSXX_OUTINVESTA'; --存储过程名
  V_ERROR_MSG     VARCHAR2(1000); --返回信息
  V_ERROR_CODE    INTEGER;
  V_ERROR_LINE    INTEGER;
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  V_PAGE_NUM  NUMBER DEFAULT 0;
  V_PAGE_SIZE NUMBER;
  v_eid       varchar2(200);
  --=============================================================
  -- 业务处理过程
  --=============================================================

  --------------------------业务逻辑开始-----------------------------
BEGIN
  /*
   INSERT INTO THJS.T_TEST(C1,C2,C3,C4) VALUES(V_FUNCTION_NAME,I_OBJ_NAME,I_PAGE_NUM,I_PAGE_SIZE);
    COMMIT;
  */
  IF I_PAGE_NUM IS NOT NULL THEN
    V_PAGE_NUM := I_PAGE_NUM;
  END IF;

  select nvl(e.eid, '')
    into v_eid
    from dual
    left join ztgs.enterprisebaseinfocollect e
      on e.pripid = I_OBJ_NAME;

  --统计记录条数
  IF V_PAGE_NUM < 1 THEN
    SELECT COUNT(1)
      INTO O_TOTAL_COUNT
      FROM ZTGS.ENTINVITEM T
     WHERE T.Eid = v_eid
       AND T.MODIFY_TYPE <> 'D';
  END IF;

  IF I_PAGE_SIZE IS NOT NULL AND I_PAGE_SIZE <> 0 THEN
    V_PAGE_SIZE := I_PAGE_SIZE;
  ELSE
    V_PAGE_SIZE := O_TOTAL_COUNT;
  END IF;

  OPEN RT_CURSOR FOR
    SELECT PRIPID AS ENT_ID, -- 企业唯一ID
           ENTNAME, -- 企业（机构）名称
           CREDIT_CODE, -- 统一社会信用代码
           REGNO, -- 注册号
           --B_NO              ,  -- 序号
           B_SUBCONAM, -- 认缴出资额
           B_FUNDED_RATIO, -- 出资比例
           B_EID            AS B_ENT_ID, -- 被投企业唯一ID
           B_ENTNAME, -- 被投企业名称
           B_CREDIT_CODE, -- 被投企业统一社会信用代码
           B_REGNO, -- 被投企业工商注册号
           B_ENTTYPE_NAME, -- 被投企业企业（机构）类型
           B_LEGAL_PERSON   AS B_FRNAME, -- 被投企业法定代表人姓名
           B_REGCAP, -- 被投企业注册资本
           B_REGCAPCUR, -- 被投企业注册资本币种
           B_ESDATE, -- 被投企业成立日期
           B_REGORG_NAME, -- 被投企业工商登记机关
           B_ENTSTATUS_NAME, -- 被投企业经营状态
           B_CANDATE, -- 被投企业注销日期
           B_REVDATE, -- 被投企业吊销日期
           UPDATE_TIME      AS UPDATETIME, -- 更新时间
           CREATE_TIME      AS CREATETIME, -- 创建时间
           MODIFY_TYPE -- 操作类型：I新增 U更新 D删除
    
      FROM (SELECT A.*, ROWNUM AS RN
              FROM (SELECT PRIPID, -- 企业唯一ID
                           ENTNAME, -- 企业（机构）名称
                           CREDIT_CODE, -- 统一社会信用代码
                           REGNO, -- 注册号
                           --B_NO              ,  -- 序号
                           B_SUBCONAM, -- 认缴出资额
                           B_FUNDED_RATIO, -- 出资比例
                           B_EID, -- 被投企业唯一ID
                           B_ENTNAME, -- 被投企业名称
                           B_CREDIT_CODE, -- 被投企业统一社会信用代码
                           B_REGNO, -- 被投企业工商注册号
                           B_ENTTYPE_NAME, -- 被投企业企业（机构）类型
                           B_LEGAL_PERSON, -- 被投企业法定代表人姓名
                           B_REGCAP, -- 被投企业注册资本
                           B_REGCAPCUR, -- 被投企业注册资本币种
                           REPLACE(T.B_ESDATE, '-', '') B_ESDATE, -- 被投企业成立日期
                           B_REGORG_NAME, -- 被投企业工商登记机关
                           B_ENTSTATUS_NAME, -- 被投企业经营状态
                           B_CANDATE, -- 被投企业注销日期
                           B_REVDATE, -- 被投企业吊销日期
                           REPLACE(T.UPDATE_TIME, '-', '') UPDATE_TIME, -- 更新时间
                           REPLACE(T.CREATE_TIME, '-', '') CREATE_TIME, -- 创建时间
                           MODIFY_TYPE -- 操作类型：I新增 U更新 D删除
                      FROM ZTGS.ENTINVITEM T
                     WHERE T.Eid = v_eid
                       AND T.MODIFY_TYPE <> 'D'
                     ORDER BY T.UPDATE_TIME DESC) A) B
     WHERE RN > V_PAGE_NUM
       AND RN <= V_PAGE_NUM + V_PAGE_SIZE;
  O_RETURN_CODE := 0;
  O_RETURN_MSG  := '执行成功';

  -- ============================================================================
  -- 错误处理部分
  -- ============================================================================

EXCEPTION
  WHEN OTHERS THEN
    O_RETURN_CODE := -1;
    O_RETURN_MSG  := V_ERROR_MSG || '--行号:' || TO_CHAR(V_ERROR_LINE) ||
                     '||sqlcode:' || SQLCODE || '||sqlerrm:||' ||
                     SUBSTR(SQLERRM, 1, 200);
    ROLLBACK;
    V_ERROR_MSG  := O_RETURN_MSG;
    V_ERROR_CODE := O_RETURN_CODE;
    P_ERROR_LOG('admin',
                V_FUNCTION_NAME,
                V_ERROR_CODE,
                V_ERROR_MSG,
                '',
                '1',
                O_RETURN_MSG,
                O_RETURN_CODE);
END;

Create or Replace PROCEDURE "THJS"."P_TYNEWS_GSXX_PENALIZE" (RT_CURSOR     OUT TYPES.CURSORTYPE,
                                                        I_OBJ_NAME    IN VARCHAR2,
                                                        I_PAGE_NUM    IN NUMBER DEFAULT 0, --默认值0,
                                                        I_PAGE_SIZE   IN NUMBER DEFAULT 0, --默认值0  如果I_PAGE_NUM，I_PAGE_SIZE都为0 则不分页，查询全部
                                                        O_TOTAL_COUNT OUT INTEGER,
                                                        O_RETURN_MSG  OUT VARCHAR2,
                                                        O_RETURN_CODE OUT INTEGER) IS
  -------------------------------------------------------------------------------------
  -- COPYRIGHT          GTJA
  -- FUNC_ID            THJS.P_TYNEWS_GSXX_PENALIZE
  -- VERSION            1.0
  -- FUNC_NAME          工商信息 -- 行政处罚
  -- FUNC_REMARK
  -- CREATE_DATE        2019-01-29
  -- CREATE_PROGRAMER   HAIYANG.XU
  -- MODIFY_REMARK
  -- MODIFY_DATE
  --==============================================================================
  --固定变量
  V_FUNCTION_NAME VARCHAR2(64) DEFAULT 'THJS.P_TYNEWS_GSXX_PENALIZE'; --存储过程名
  V_ERROR_MSG     VARCHAR2(1000); --返回信息
  V_ERROR_CODE    INTEGER;
  V_ERROR_LINE    INTEGER;
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  V_PAGE_NUM  NUMBER DEFAULT 0;
  V_PAGE_SIZE NUMBER;
  --=============================================================
  -- 业务处理过程
  --=============================================================

  --------------------------业务逻辑开始-----------------------------
BEGIN
  /*
   INSERT INTO THJS.T_TEST(C1,C2,C3,C4) VALUES(V_FUNCTION_NAME,I_OBJ_NAME,I_PAGE_NUM,I_PAGE_SIZE);
    COMMIT;
  */
  IF I_PAGE_NUM IS NOT NULL THEN
    V_PAGE_NUM := I_PAGE_NUM;
  END IF;

  --统计记录条数
  IF V_PAGE_NUM < 1 THEN
    SELECT COUNT(1)
      INTO O_TOTAL_COUNT
      FROM ZTGS.CASE_CF_IRREGPUNISHINFO T
     WHERE T.CASE_INFO_ID = I_OBJ_NAME --'cb_6aeafd00367b4d11ade4a62f5dce51e9'
       AND T.MODIFY_TYPE <> 'D';
  END IF;

  IF I_PAGE_SIZE IS NOT NULL AND I_PAGE_SIZE <> 0 THEN
    V_PAGE_SIZE := I_PAGE_SIZE;
  ELSE
    V_PAGE_SIZE := O_TOTAL_COUNT;
  END IF;

  OPEN RT_CURSOR FOR
    SELECT B.CASE_INFO_ID, --案件记录ID
           --B.ILLEGACT_ID,          --处罚序号
           B.PENDECNO, --处罚决定书文号
           B.ILLEGACTTYPE_NAME, --违法行为种类
           B.PENRESULT_NAME, --处罚结果
           B.PENAUTH_NAME, --处罚机关
           B.CASE_BOOK, --行政处罚文书
           B.UPDATE_TIME, --数据更新时间
           B.MODIFY_TYPE --操作类型：I新增 U更新 D删除
    
      FROM (SELECT A.*, ROWNUM AS RN
              FROM (SELECT T.CASE_INFO_ID, --案件记录ID
                           --T.ILLEGACT_ID,          --处罚序号
                           T.PENDECNO, --处罚决定书文号
                           T.ILLEGACTTYPE_NAME, --违法行为种类
                           TO_CHAR(T.PENRESULT_NAME) PENRESULT_NAME, --处罚结果
                           T.PENAUTH_NAME, --处罚机关
                           TO_CHAR(T.CASE_BOOK) CASE_BOOK, --行政处罚文书
                           REPLACE(T.UPDATE_TIME, '-', '') UPDATE_TIME, --数据更新时间
                           T.MODIFY_TYPE --操作类型：I新增 U更新 D删除
                      FROM ZTGS.CASE_CF_IRREGPUNISHINFO T
                     WHERE T.CASE_INFO_ID = I_OBJ_NAME --'cb_6aeafd00367b4d11ade4a62f5dce51e9'
                       AND T.MODIFY_TYPE <> 'D'
                     ORDER BY T.UPDATE_TIME DESC) A) B
     WHERE RN > V_PAGE_NUM
       AND RN <= V_PAGE_NUM + V_PAGE_SIZE;
  O_RETURN_CODE := 0;
  O_RETURN_MSG  := '执行成功';

  -- ============================================================================
  -- 错误处理部分
  -- ============================================================================

EXCEPTION
  WHEN OTHERS THEN
    O_RETURN_CODE := -1;
    O_RETURN_MSG  := V_ERROR_MSG || '--行号:' || TO_CHAR(V_ERROR_LINE) ||
                     '||sqlcode:' || SQLCODE || '||sqlerrm:||' ||
                     SUBSTR(SQLERRM, 1, 200);
    ROLLBACK;
    V_ERROR_MSG  := O_RETURN_MSG;
    V_ERROR_CODE := O_RETURN_CODE;
    P_ERROR_LOG('admin',
                V_FUNCTION_NAME,
                V_ERROR_CODE,
                V_ERROR_MSG,
                '',
                '1',
                O_RETURN_MSG,
                O_RETURN_CODE);
END;

Create or Replace PROCEDURE "THJS"."P_TYNEWS_GSXX_PERMISSION" (RT_CURSOR     OUT TYPES.CURSORTYPE,
                                                          I_OBJ_NAME    IN VARCHAR2,
                                                          I_PAGE_NUM    IN NUMBER DEFAULT 0, --默认值0,
                                                          I_PAGE_SIZE   IN NUMBER DEFAULT 0, --默认值0  如果I_PAGE_NUM，I_PAGE_SIZE都为0 则不分页，查询全部
                                                          O_TOTAL_COUNT OUT INTEGER,
                                                          O_RETURN_MSG  OUT VARCHAR2,
                                                          O_RETURN_CODE OUT INTEGER) IS
  -------------------------------------------------------------------------------------
  -- COPYRIGHT          GTJA
  -- FUNC_ID            THJS.P_TYNEWS_GSXX_PERMISSION
  -- VERSION            1.0
  -- FUNC_NAME          工商信息 -- 许可信息
  -- FUNC_REMARK
  -- CREATE_DATE        2019-01-29
  -- CREATE_PROGRAMER   HAIYANG.XU
  -- MODIFY_REMARK
  -- MODIFY_DATE
  --==============================================================================
  --固定变量
  V_FUNCTION_NAME VARCHAR2(64) DEFAULT 'THJS.P_TYNEWS_GSXX_PERMISSION'; --存储过程名
  V_ERROR_MSG     VARCHAR2(1000); --返回信息
  V_ERROR_CODE    INTEGER;
  V_ERROR_LINE    INTEGER;
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  V_PAGE_NUM  NUMBER DEFAULT 0;
  V_PAGE_SIZE NUMBER;
  --=============================================================
  -- 业务处理过程
  --=============================================================

  --------------------------业务逻辑开始-----------------------------
BEGIN
  /*
   INSERT INTO THJS.T_TEST(C1,C2,C3,C4) VALUES(V_FUNCTION_NAME,I_OBJ_NAME,I_PAGE_NUM,I_PAGE_SIZE);
    COMMIT;
  */
  IF I_PAGE_NUM IS NOT NULL THEN
    V_PAGE_NUM := I_PAGE_NUM;
  END IF;

  --统计记录条数
  IF V_PAGE_NUM < 1 THEN
    SELECT COUNT(1)
      INTO O_TOTAL_COUNT
      FROM ZTGS.E_LICENCE_CERTIFICATE T
     WHERE T.EID = (SELECT E.EID
                      FROM ZTGS.ENTERPRISEBASEINFOCOLLECT E --企业主体表
                     WHERE E.PRIPID = I_OBJ_NAME) --'A220686')
       AND T.MODIFY_TYPE <> 'D';
  END IF;

  IF I_PAGE_SIZE IS NOT NULL AND I_PAGE_SIZE <> 0 THEN
    V_PAGE_SIZE := I_PAGE_SIZE;
  ELSE
    V_PAGE_SIZE := O_TOTAL_COUNT;
  END IF;

  OPEN RT_CURSOR FOR
    SELECT B.EID, --企业ID
           B.LICNO, --许可文件编号
           B.LICNAME, --许可文件名称
           B.VALFORM, --有效期自
           B.VALTO, --有效期至
           B.LICANTH, --许可机关
           B.LICENSECONTENT, --许可内容
           B.UPDATE_TIME AS S_EXT_TIMESTAMP, --数据更新时间
           B.MODIFY_TYPE --操作类型：I新增 U更新 D删除
    
      FROM (SELECT A.*, ROWNUM AS RN
              FROM (SELECT T.EID, --企业ID
                           T.LICNO, --许可文件编号
                           T.LICNAME, --许可文件名称
                           T.VALFORM, --有效期自
                           REPLACE(T.VALTO, '-', '') VALTO, --有效期至
                           T.LICANTH, --许可机关
                           TO_CHAR(T.LICENSECONTENT) LICENSECONTENT, --许可内容
                           REPLACE(T.UPDATE_TIME, '-', '') UPDATE_TIME, --数据更新时间
                           T.MODIFY_TYPE --操作类型：I新增 U更新 D删除
                      FROM ZTGS.E_LICENCE_CERTIFICATE T
                     WHERE T.EID = (SELECT E.EID
                                      FROM ZTGS.ENTERPRISEBASEINFOCOLLECT E --企业主体表
                                     WHERE E.PRIPID = I_OBJ_NAME) --'A220686')
                       AND T.MODIFY_TYPE <> 'D'
                     ORDER BY T.VALFORM DESC) A) B
     WHERE RN > V_PAGE_NUM
       AND RN <= V_PAGE_NUM + V_PAGE_SIZE;
  O_RETURN_CODE := 0;
  O_RETURN_MSG  := '执行成功';

  -- ============================================================================
  -- 错误处理部分
  -- ============================================================================

EXCEPTION
  WHEN OTHERS THEN
    O_RETURN_CODE := -1;
    O_RETURN_MSG  := V_ERROR_MSG || '--行号:' || TO_CHAR(V_ERROR_LINE) ||
                     '||sqlcode:' || SQLCODE || '||sqlerrm:||' ||
                     SUBSTR(SQLERRM, 1, 200);
    ROLLBACK;
    V_ERROR_MSG  := O_RETURN_MSG;
    V_ERROR_CODE := O_RETURN_CODE;
    P_ERROR_LOG('admin',
                V_FUNCTION_NAME,
                V_ERROR_CODE,
                V_ERROR_MSG,
                '',
                '1',
                O_RETURN_MSG,
                O_RETURN_CODE);
END;

Create or Replace PROCEDURE "THJS"."P_TYNEWS_GSXX_PLEDGE" (RT_CURSOR     OUT TYPES.CURSORTYPE,
                                                      I_OBJ_NAME    IN VARCHAR2,
                                                      I_PAGE_NUM    IN NUMBER DEFAULT 0, --默认值0,
                                                      I_PAGE_SIZE   IN NUMBER DEFAULT 0, --默认值0  如果I_PAGE_NUM，I_PAGE_SIZE都为0 则不分页，查询全部
                                                      O_TOTAL_COUNT OUT INTEGER,
                                                      O_RETURN_MSG  OUT VARCHAR2,
                                                      O_RETURN_CODE OUT INTEGER) IS
  -------------------------------------------------------------------------------------
  -- COPYRIGHT          GTJA
  -- FUNC_ID            THJS.P_TYNEWS_GSXX_PLEDGE
  -- VERSION            1.0
  -- FUNC_NAME          工商信息 -- 股权出质
  -- FUNC_REMARK
  -- CREATE_DATE        2019-01-29
  -- CREATE_PROGRAMER   HAIYANG.XU
  -- MODIFY_REMARK
  -- MODIFY_DATE
  --==============================================================================
  --固定变量
  V_FUNCTION_NAME VARCHAR2(64) DEFAULT 'THJS.P_TYNEWS_GSXX_PLEDGE'; --存储过程名
  V_ERROR_MSG     VARCHAR2(1000); --返回信息
  V_ERROR_CODE    INTEGER;
  V_ERROR_LINE    INTEGER;
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  V_PAGE_NUM  NUMBER DEFAULT 0;
  V_PAGE_SIZE NUMBER;
  --=============================================================
  -- 业务处理过程
  --=============================================================

  --------------------------业务逻辑开始-----------------------------
BEGIN
  /*
   INSERT INTO THJS.T_TEST(C1,C2,C3,C4) VALUES(V_FUNCTION_NAME,I_OBJ_NAME,I_PAGE_NUM,I_PAGE_SIZE);
    COMMIT;
  */
  IF I_PAGE_NUM IS NOT NULL THEN
    V_PAGE_NUM := I_PAGE_NUM;
  END IF;

  --统计记录条数
  IF V_PAGE_NUM < 1 THEN
    SELECT COUNT(1)
      INTO O_TOTAL_COUNT
      FROM ZTGS.E_SHARES_IMPAWN T
     WHERE T.EID = (SELECT E.EID
                      FROM ZTGS.ENTERPRISEBASEINFOCOLLECT E --企业主体表
                     WHERE E.PRIPID = I_OBJ_NAME) --'350100000022003092300002')
       AND T.MODIFY_TYPE <> 'D'
       AND T.EQUITYNO IS NOT NULL;
  END IF;

  IF I_PAGE_SIZE IS NOT NULL AND I_PAGE_SIZE <> 0 THEN
    V_PAGE_SIZE := I_PAGE_SIZE;
  ELSE
    V_PAGE_SIZE := O_TOTAL_COUNT;
  END IF;

  OPEN RT_CURSOR FOR
    SELECT B.EID, --企业ID
           B.IMP_ORG_ID, --质押ID
           B.IMP_ORG, --质权人
           B.IMP_RGLICENSEN, --质权人证照/证件号码
           B.IMP_AM, --出质股权数额
           B.IMP_PLEDGOR, --出质人
           B.IMP_PRLICENSEN, --出质人证照/证件号码
           B.EXESTATE, --执行状态
           B.IMP_PUBDATE, --公示日期
           B.EQUITYNO, --登记编号
           B.EQUPLEDATE, --股权出质登记日期
           B.S_EXT_TIMESTAMP, --数据更新时间
           B.MODIFY_TYPE --操作类型：I新增 U更新 D删除
    
      FROM (SELECT A.*, ROWNUM AS RN
              FROM (SELECT T.EID, --企业ID
                           T.IMP_ORG_ID, --质押ID
                           T.IMP_ORG, --质权人
                           T.IMP_RGLICENSEN, --质权人证照/证件号码
                           T.IMP_AM, --出质股权数额
                           T.IMP_PLEDGOR, --出质人
                           T.IMP_PRLICENSEN, --出质人证照/证件号码
                           T.EXESTATE, --执行状态
                           REPLACE(T.IMP_PUBDATE, '-', '') IMP_PUBDATE, --公示日期
                           T.EQUITYNO, --登记编号
                           REPLACE(T.EQUPLEDATE, '-', '') EQUPLEDATE, --股权出质登记日期
                           REPLACE(T.UPDATE_TIME, '-', '') S_EXT_TIMESTAMP, --数据更新时间
                           T.MODIFY_TYPE --操作类型：I新增 U更新 D删除
                      FROM ZTGS.E_SHARES_IMPAWN T
                     WHERE T.EID = (SELECT E.EID
                                      FROM ZTGS.ENTERPRISEBASEINFOCOLLECT E --企业主体表
                                     WHERE E.PRIPID = I_OBJ_NAME) -- '350100000022003092300002')
                       AND T.MODIFY_TYPE <> 'D'
                       AND T.EQUITYNO IS NOT NULL
                     ORDER BY T.IMP_PUBDATE DESC NULLS LAST) A) B
     WHERE RN > V_PAGE_NUM
       AND RN <= V_PAGE_NUM + V_PAGE_SIZE;
  O_RETURN_CODE := 0;
  O_RETURN_MSG  := '执行成功';

  -- ============================================================================
  -- 错误处理部分
  -- ============================================================================

EXCEPTION
  WHEN OTHERS THEN
    O_RETURN_CODE := -1;
    O_RETURN_MSG  := V_ERROR_MSG || '--行号:' || TO_CHAR(V_ERROR_LINE) ||
                     '||sqlcode:' || SQLCODE || '||sqlerrm:||' ||
                     SUBSTR(SQLERRM, 1, 200);
    ROLLBACK;
    V_ERROR_MSG  := O_RETURN_MSG;
    V_ERROR_CODE := O_RETURN_CODE;
    P_ERROR_LOG('admin',
                V_FUNCTION_NAME,
                V_ERROR_CODE,
                V_ERROR_MSG,
                '',
                '1',
                O_RETURN_MSG,
                O_RETURN_CODE);
END;

Create or Replace PROCEDURE "THJS"."P_TYNEWS_GSXX_SETTLE" (RT_CURSOR     OUT TYPES.CURSORTYPE,
                                                      I_OBJ_NAME    IN VARCHAR2,
                                                      I_PAGE_NUM    IN NUMBER DEFAULT 0, --默认值0,
                                                      I_PAGE_SIZE   IN NUMBER DEFAULT 0, --默认值0  如果I_PAGE_NUM，I_PAGE_SIZE都为0 则不分页，查询全部
                                                      O_TOTAL_COUNT OUT INTEGER,
                                                      O_RETURN_MSG  OUT VARCHAR2,
                                                      O_RETURN_CODE OUT INTEGER) IS
  -------------------------------------------------------------------------------------
  -- COPYRIGHT          GTJA
  -- FUNC_ID            THJS.P_TYNEWS_GSXX_SETTLE
  -- VERSION            1.0
  -- FUNC_NAME          工商信息 -- 清算信息
  -- FUNC_REMARK
  -- CREATE_DATE        2019-01-29
  -- CREATE_PROGRAMER   HAIYANG.XU
  -- MODIFY_REMARK
  -- MODIFY_DATE
  --==============================================================================
  --固定变量
  V_FUNCTION_NAME VARCHAR2(64) DEFAULT 'THJS.P_TYNEWS_GSXX_SETTLE'; --存储过程名
  V_ERROR_MSG     VARCHAR2(1000); --返回信息
  V_ERROR_CODE    INTEGER;
  V_ERROR_LINE    INTEGER;
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  V_PAGE_NUM  NUMBER DEFAULT 0;
  V_PAGE_SIZE NUMBER;
  v_eid       varchar2(200);
  --=============================================================
  -- 业务处理过程
  --=============================================================

  --------------------------业务逻辑开始-----------------------------
BEGIN
  /*
   INSERT INTO THJS.T_TEST(C1,C2,C3,C4) VALUES(V_FUNCTION_NAME,I_OBJ_NAME,I_PAGE_NUM,I_PAGE_SIZE);
    COMMIT;
  */

  select e.eid
    into v_eid
    from dual
    left join ztgs.enterprisebaseinfocollect e
      on e.pripid = I_OBJ_NAME;

  IF I_PAGE_NUM IS NOT NULL THEN
    V_PAGE_NUM := I_PAGE_NUM;
  END IF;

  --统计记录条数
  IF V_PAGE_NUM < 1 THEN
    SELECT COUNT(1)
      INTO O_TOTAL_COUNT
      FROM ZTGS.E_LIQUIDATION T
     WHERE t.eid = v_eid --'510000000012016040100668'
       AND T.MODIFY_TYPE <> 'D';
  END IF;

  IF I_PAGE_SIZE IS NOT NULL AND I_PAGE_SIZE <> 0 THEN
    V_PAGE_SIZE := I_PAGE_SIZE;
  ELSE
    V_PAGE_SIZE := O_TOTAL_COUNT;
  END IF;

  OPEN RT_CURSOR FOR
    SELECT B.PRIPID, --主体身份代码
           B.LIGPRINCIPAL, --清算负责人
           B.LIQMEN, --清算组成员
           B.UPDATE_TIME AS S_EXT_TIMESTAMP, --数据更新时间
           B.MODIFY_TYPE --操作类型：I新增 U更新 D删除
    
      FROM (SELECT A.*, ROWNUM AS RN
              FROM (SELECT T.PRIPID, --主体身份代码
                           T.LIGPRINCIPAL, --清算负责人
                           T.LIQMEN, --清算组成员
                           REPLACE(T.UPDATE_TIME, '-', '') UPDATE_TIME, --数据更新时间
                           T.MODIFY_TYPE --操作类型：I新增 U更新 D删除
                      FROM ZTGS.E_LIQUIDATION T
                     WHERE t.eid = v_eid --'510000000012016040100668'
                       AND T.MODIFY_TYPE <> 'D'
                     ORDER BY T.UPDATE_TIME DESC) A) B
     WHERE RN > V_PAGE_NUM
       AND RN <= V_PAGE_NUM + V_PAGE_SIZE;
  O_RETURN_CODE := 0;
  O_RETURN_MSG  := '执行成功';

  -- ============================================================================
  -- 错误处理部分
  -- ============================================================================

EXCEPTION
  WHEN OTHERS THEN
    O_RETURN_CODE := -1;
    O_RETURN_MSG  := V_ERROR_MSG || '--行号:' || TO_CHAR(V_ERROR_LINE) ||
                     '||sqlcode:' || SQLCODE || '||sqlerrm:||' ||
                     SUBSTR(SQLERRM, 1, 200);
    ROLLBACK;
    V_ERROR_MSG  := O_RETURN_MSG;
    V_ERROR_CODE := O_RETURN_CODE;
    P_ERROR_LOG('admin',
                V_FUNCTION_NAME,
                V_ERROR_CODE,
                V_ERROR_MSG,
                '',
                '1',
                O_RETURN_MSG,
                O_RETURN_CODE);
END;

Create or Replace PROCEDURE "THJS"."P_TYNEWS_HIS_ADUIT" (RT_CURSOR     OUT TYPES.CURSORTYPE,
                                                      I_OBJ_NAME    IN VARCHAR2,
                                                      I_PAGE_NUM    IN NUMBER DEFAULT 0, --默认值0,
                                                      I_PAGE_SIZE   IN NUMBER DEFAULT 0, --默认值0  如果I_PAGE_NUM，I_PAGE_SIZE都为0 则不分页，查询全部
                                                      O_TOTAL_COUNT OUT INTEGER,
                                                      O_RETURN_MSG  OUT VARCHAR2,
                                                      O_RETURN_CODE OUT INTEGER) IS
  -------------------------------------------------------------------------------------
  -- COPYRIGHT          GTJA
  -- FUNC_ID            THJS.P_TYNEWS_HIS_ADUIT
  -- VERSION            1.0
  -- FUNC_NAME          投行历史数据-审计署数据表（债券承销情况）
  -- FUNC_REMARK
  -- CREATE_DATE        2019-01-29
  -- CREATE_PROGRAMER   HAIYANG.XU
  -- MODIFY_REMARK
  -- MODIFY_DATE
  --==============================================================================
  --固定变量
  V_FUNCTION_NAME VARCHAR2(64) DEFAULT 'THJS.P_TYNEWS_HIS_ADUIT'; --存储过程名
  V_ERROR_MSG     VARCHAR2(1000); --返回信息
  V_ERROR_CODE    INTEGER;
  V_ERROR_LINE    INTEGER;
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  V_PAGE_NUM  NUMBER DEFAULT 0;
  V_PAGE_SIZE NUMBER;
  
  V_OBJ_NAME  VARCHAR2(1000) := I_OBJ_NAME;
  --=============================================================
  -- 业务处理过程
  --=============================================================

  --------------------------业务逻辑开始-----------------------------
BEGIN
  /*
   INSERT INTO THJS.T_TEST(C1,C2,C3,C4) VALUES(V_FUNCTION_NAME,I_OBJ_NAME,I_PAGE_NUM,I_PAGE_SIZE);
    COMMIT;
  */
  IF I_PAGE_NUM IS NOT NULL THEN
    V_PAGE_NUM := I_PAGE_NUM;
  END IF;

  --统计记录条数
  IF V_PAGE_NUM < 1 THEN
    SELECT COUNT(1)
      INTO O_TOTAL_COUNT
      FROM THJS.TB_ADUIT_BOND_UWINFO T
     WHERE BOND_CODE IN
           (SELECT A1.S_INFO_WINDCODE
              FROM ZX90.TCL_CBONDDESCRIPTION A1
             INNER JOIN ZX90.TCL_COMPINTRODUCTION C
                ON C.COMP_ID = A1.B_INFO_ISSUERCODE
             INNER JOIN ZTGS.ENTERPRISEBASEINFOCOLLECT D
                ON C.REGISTERNUMBER = D.CREDIT_CODE
             WHERE D.PRIPID = I_OBJ_NAME);
  END IF;

  IF I_PAGE_SIZE IS NOT NULL AND I_PAGE_SIZE <> 0 THEN
    V_PAGE_SIZE := I_PAGE_SIZE;
  ELSE
    V_PAGE_SIZE := O_TOTAL_COUNT;
  END IF;

  OPEN RT_CURSOR FOR
    SELECT B.BUSI_DATE, --维护日期
           B.UNDERWRITER, --承销商
           B.BOND_NAME, --债券名称
           B.BOND_CODE, --债券代码
           B.BOND_FULLNAME, --债券全称
           B.ISSUER, --发行人
           B.ISSUE_TYPE, --发行类型
           B.ISSUE_DATE, --发行日期
           B.LISTING_DATE, --上市日期
           B.ISSUE_SCALE, --发行规模
           B.COUPON_RATE, --票面利率
           B.ISSUE_MARKET, --上市场所
           B.TERM, --期限（年）
           B.UW_SCALE, --承销规模（亿元）
           B.UW_COMMISSION, --承销佣金（万元）
           B.UW_ACCOUNT_NO, --承销佣金收款账号
           B.UW_ACCOUNT_BANK, --承销佣金收款账户开户行
           B.CONSULTANT_NAME, --提供咨询等服务方名称
           B.CONTRACT_NAME, --合同名称
           B.PAY_DATE, --付款时间
           B.PAY_AMT, --付款金额（万元）
           B.PAY_ACCOUNT, --付款账号
           B.PAY_ACCOUNT_BANK, --付款账户开户行
           B.RECV_ACCOUNT_NAME, --收款账户名
           B.RECV_ACCOUNT, --收款账号
           B.RECV_ACCOUNT_BANK, --开户行
           B.REMARK --备注
    
      FROM (SELECT ROW_NUMBER() OVER(ORDER BY A.BUSI_DATE) AS RN, A.*
              FROM (WITH TMP_Z AS (SELECT C.COMP_ID
                                     FROM ZX90.TCL_COMPINTRODUCTION C
                                    WHERE C.REGISTERNUMBER IN
                                          (SELECT D.CREDIT_CODE
                                             FROM ZTGS.ENTERPRISEBASEINFOCOLLECT D
                                            WHERE D.PRIPID = V_OBJ_NAME))
                     SELECT T.BUSI_DATE, --维护日期
                            T.UNDERWRITER, --承销商
                            T.BOND_NAME, --债券名称
                            T.BOND_CODE, --债券代码
                            T.BOND_FULLNAME, --债券全称
                            T.ISSUER, --发行人
                            T.ISSUE_TYPE, --发行类型
                            replace(T.ISSUE_DATE, '-', '') ISSUE_DATE, --发行日期
                            replace(T.LISTING_DATE, '-', '') LISTING_DATE, --上市日期
                            round(T.ISSUE_SCALE, 2) ISSUE_SCALE, --发行规模
                            round(T.COUPON_RATE, 2) COUPON_RATE, --票面利率
                            T.ISSUE_MARKET, --上市场所
                            T.TERM, --期限（年）
                            round(T.UW_SCALE, 2) UW_SCALE, --承销规模（亿元）
                            round(T.UW_COMMISSION, 2) UW_COMMISSION, --承销佣金（万元）
                            T.UW_ACCOUNT_NO, --承销佣金收款账号
                            T.UW_ACCOUNT_BANK, --承销佣金收款账户开户行
                            T.CONSULTANT_NAME, --提供咨询等服务方名称
                            T.CONTRACT_NAME, --合同名称
                            T.PAY_DATE, --付款时间
                            T.PAY_AMT, --付款金额（万元）
                            T.PAY_ACCOUNT, --付款账号
                            T.PAY_ACCOUNT_BANK, --付款账户开户行
                            T.RECV_ACCOUNT_NAME, --收款账户名
                            T.RECV_ACCOUNT, --收款账号
                            T.RECV_ACCOUNT_BANK, --开户行
                            T.REMARK --备注
                     
                       FROM THJS.TB_ADUIT_BOND_UWINFO T
                      WHERE T.BOND_CODE IN
                            (SELECT DISTINCT A1.S_INFO_WINDCODE
                               FROM ZX90.TCL_CBONDDESCRIPTION A1
                              WHERE A1.B_INFO_ISSUERCODE IN
                                    (SELECT COMP_ID FROM TMP_Z))) A
                      ORDER BY A.BUSI_DATE
                     
            
            ) B
     WHERE RN > V_PAGE_NUM
       AND RN <= V_PAGE_NUM + V_PAGE_SIZE;

  O_RETURN_CODE := 0;
  O_RETURN_MSG  := '执行成功';

  -- ============================================================================
  -- 错误处理部分
  -- ============================================================================

EXCEPTION
  WHEN OTHERS THEN
    O_RETURN_CODE := -1;
    O_RETURN_MSG  := V_ERROR_MSG || '--行号:' || TO_CHAR(V_ERROR_LINE) ||
                     '||sqlcode:' || SQLCODE || '||sqlerrm:||' ||
                     SUBSTR(SQLERRM, 1, 200);
    ROLLBACK;
    V_ERROR_MSG  := O_RETURN_MSG;
    V_ERROR_CODE := O_RETURN_CODE;
    P_ERROR_LOG('admin',
                V_FUNCTION_NAME,
                V_ERROR_CODE,
                V_ERROR_MSG,
                '',
                '1',
                O_RETURN_MSG,
                O_RETURN_CODE);
END;

