                           T.PAY_ACCOUNT_BANK, --付款账户开户行
                           T.RECV_ACCOUNT_NAME, --收款账户名
                           T.RECV_ACCOUNT, --收款账号
                           T.RECV_ACCOUNT_BANK, --开户行
                           T.REMARK --备注
                      FROM THJS.TB_ADUIT_BOND_UWINFO T
                     WHERE T.BOND_CODE IN
                           (SELECT DISTINCT A1.S_INFO_WINDCODE
                              FROM ZX90.TCL_CBONDDESCRIPTION A1
                             WHERE A1.B_INFO_ISSUERCODE IN (SELECT COMP_ID FROM TMP_Z))) A) B;

  O_RETURN_CODE := 0;
  O_RETURN_MSG  := '执行成功';

  -- ============================================================================
