                V_FUNCTION_NAME,
                V_ERROR_CODE,
                V_ERROR_MSG,
                '',
                '1',
                O_RETURN_MSG,
                O_RETURN_CODE);
END;

Create or Replace PROCEDURE "THJS"."P_TYNEWS_INFINA_EXPEN" (RT_CURSOR     OUT TYPES.CURSORTYPE,
                                                       I_OBJ_NAME    IN VARCHAR2,
                                                       I_PAGE_NUM    IN NUMBER DEFAULT 0, --默认值0,
                                                       I_PAGE_SIZE   IN NUMBER DEFAULT 0, --默认值0  如果I_PAGE_NUM，I_PAGE_SIZE都为0 则不分页，查询全部
                                                       O_TOTAL_COUNT OUT INTEGER,
                                                       O_RETURN_MSG  OUT VARCHAR2,
                                                       O_RETURN_CODE OUT INTEGER) IS
  -------------------------------------------------------------------------------------
  -- COPYRIGHT          GTJA
  -- FUNC_ID            THJS.P_TYNEWS_INFINA_EXPEN
  -- VERSION            1.0
  -- FUNC_NAME          内部财务数据 -- 支出明细
  -- FUNC_REMARK
  -- CREATE_DATE        2019-03-07
  -- CREATE_PROGRAMER   HAIYANG.XU
  -- MODIFY_REMARK
  -- MODIFY_DATE
  --==============================================================================
  --固定变量
  V_FUNCTION_NAME VARCHAR2(64) DEFAULT 'THJS.P_TYNEWS_INFINA_EXPEN'; --存储过程名
  V_ERROR_MSG     VARCHAR2(1000); --返回信息
  V_ERROR_CODE    INTEGER;
  V_ERROR_LINE    INTEGER;
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  V_PAGE_NUM  NUMBER DEFAULT 0;
  V_PAGE_SIZE NUMBER;
  --=============================================================
  -- 业务处理过程
  --=============================================================

  --------------------------业务逻辑开始-----------------------------
BEGIN
  /*
   INSERT INTO THJS.T_TEST(C1,C2,C3,C4) VALUES(V_FUNCTION_NAME,I_OBJ_NAME,I_PAGE_NUM,I_PAGE_SIZE);
    COMMIT;
  */
  IF I_PAGE_NUM IS NOT NULL THEN
    V_PAGE_NUM := I_PAGE_NUM;
  END IF;

  --统计记录条数
  IF V_PAGE_NUM < 1 THEN
    SELECT COUNT(1)
      INTO O_TOTAL_COUNT
      FROM THJS.THDB_V_FINANCE_EXPEND T
     WHERE exists (select 1
              from thjs.tb_thdb_cust_info p
             where p.pripid = I_OBJ_NAME
               and p.projid = T.PROJ_ID);
  END IF;

  IF I_PAGE_SIZE IS NOT NULL AND I_PAGE_SIZE <> 0 THEN
    V_PAGE_SIZE := I_PAGE_SIZE;
  ELSE
    V_PAGE_SIZE := O_TOTAL_COUNT;
  END IF;

  OPEN RT_CURSOR FOR
    SELECT EXPEND_TYPE, -- 支出类型
           EXPEND_PRICE, -- 支出金额（元）
           ANALOGUE, -- 对手方
           PAY_TIME, -- 付款时间
           IS_EXPEND, -- 发票是否开给我司
           FILE_PATH, -- 发票上传文件物理路径
           UDF_1, -- 我司收入
           UDF_2, -- 是否申请开票
           UDF_4, -- 本期发行金额(元)
           UDF_5 -- 是否结转
      FROM (SELECT A.*, ROWNUM AS RN
              FROM (SELECT EXPEND_TYPE, -- 支出类型
                           EXPEND_PRICE, -- 支出金额（元）
                           ANALOGUE, -- 对手方
                           PAY_TIME, -- 付款时间
                           IS_EXPEND, -- 发票是否开给我司
                           FILE_PATH, -- 发票上传文件物理路径
                           UDF_1, -- 我司收入
                           UDF_2, -- 是否申请开票
                           UDF_4, -- 本期发行金额(元)
                           UDF_5 -- 是否结转
                      FROM THJS.THDB_V_FINANCE_EXPEND T
                     WHERE exists (select 1
                              from thjs.tb_thdb_cust_info p
                             where p.pripid = I_OBJ_NAME
                               and p.projid = T.PROJ_ID)
                    
                    ) A) B
     WHERE RN > V_PAGE_NUM
       AND RN <= V_PAGE_NUM + V_PAGE_SIZE;
  O_RETURN_CODE := 0;
  O_RETURN_MSG  := '执行成功';

  -- ============================================================================
  -- 错误处理部分
  -- ============================================================================

EXCEPTION
  WHEN OTHERS THEN
    O_RETURN_CODE := -1;
    O_RETURN_MSG  := V_ERROR_MSG || '--行号:' || TO_CHAR(V_ERROR_LINE) ||
                     '||sqlcode:' || SQLCODE || '||sqlerrm:||' ||
                     SUBSTR(SQLERRM, 1, 200);
    ROLLBACK;
    V_ERROR_MSG  := O_RETURN_MSG;
    V_ERROR_CODE := O_RETURN_CODE;
    P_ERROR_LOG('admin',
                V_FUNCTION_NAME,
                V_ERROR_CODE,
                V_ERROR_MSG,
                '',
                '1',
                O_RETURN_MSG,
                O_RETURN_CODE);
END;

