Create or Replace PROCEDURE "THJS"."P_TYNEWS_INFINA_MAIN" (RT_CURSOR     OUT TYPES.CURSORTYPE,
                                                      I_OBJ_NAME    IN VARCHAR2,
                                                      I_PAGE_NUM    IN NUMBER DEFAULT 0, --默认值0,
                                                      I_PAGE_SIZE   IN NUMBER DEFAULT 0, --默认值0  如果I_PAGE_NUM，I_PAGE_SIZE都为0 则不分页，查询全部
                                                      O_TOTAL_COUNT OUT INTEGER,
                                                      O_RETURN_MSG  OUT VARCHAR2,
                                                      O_RETURN_CODE OUT INTEGER) IS
  -------------------------------------------------------------------------------------
  -- COPYRIGHT          GTJA
  -- FUNC_ID            THJS.P_TYNEWS_INFINA_MAIN
  -- VERSION            1.0
  -- FUNC_NAME          内部财务数据 -- 财务主信息
  -- FUNC_REMARK
  -- CREATE_DATE        2019-03-07
  -- CREATE_PROGRAMER   HAIYANG.XU
  -- MODIFY_REMARK
  -- MODIFY_DATE
  --==============================================================================
  --固定变量
  V_FUNCTION_NAME VARCHAR2(64) DEFAULT 'THJS.P_TYNEWS_INFINA_MAIN'; --存储过程名
  V_ERROR_MSG     VARCHAR2(1000); --返回信息
  V_ERROR_CODE    INTEGER;
  V_ERROR_LINE    INTEGER;
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  V_PAGE_NUM  NUMBER DEFAULT 0;
  V_PAGE_SIZE NUMBER;
  --=============================================================
  -- 业务处理过程
  --=============================================================

  --------------------------业务逻辑开始-----------------------------
BEGIN
  /*
   INSERT INTO THJS.T_TEST(C1,C2,C3,C4) VALUES(V_FUNCTION_NAME,I_OBJ_NAME,I_PAGE_NUM,I_PAGE_SIZE);
    COMMIT;
  */
  IF I_PAGE_NUM IS NOT NULL THEN
    V_PAGE_NUM := I_PAGE_NUM;
  END IF;

  --统计记录条数
  IF V_PAGE_NUM < 1 THEN
    SELECT COUNT(1)
      INTO O_TOTAL_COUNT
      FROM THJS.THDB_V_FINANCE_AFFIRM T
     WHERE exists (select 1
              from thjs.tb_thdb_cust_info p
             where p.pripid = I_OBJ_NAME
               and p.projid = T.PROJ_ID);
  END IF;

  IF I_PAGE_SIZE IS NOT NULL AND I_PAGE_SIZE <> 0 THEN
    V_PAGE_SIZE := I_PAGE_SIZE;
  ELSE
    V_PAGE_SIZE := O_TOTAL_COUNT;
  END IF;

  OPEN RT_CURSOR FOR
    SELECT PROJ_NAME, --项目全称
           PUBLISHER_NAME, --发行人全称
           DEPT_NAME, --项目所属部门
           DEPT_ID, --项目所属部门ID
           PROJ_PRINCIPAL, --项目组负责人
           PROJ_TYPENAME, --项目类型
           PROJ_TYPECODE, --项目类型编码
           UNDERTAKER, --承担角色
           WIND_CODE, --WIND代码
           SECURITY_NAME, --证券简称
           PUBLISH_AMOUNT, --发行股数（股）
           PUBLISH_PRICE, --发行价格（元）
           UNDERWRITING_AMOUNT, --我司承销金额（元）
           PUBLISH_TIME, --发行时间文本
           CREATE_TIME, --创建时间文本
           UPDATE_TIME, --更新时间文本
           CREATER, --创建人
           UPDATER, --更新人
           UDF_1, --我司收入
           UDF_2, --是否申请开票
           UDF_3, --审批状态
           UDF_4, --本期发行金额(元)
           UDF_5, --是否结转
           RELATE_ID, --历史版本关联业务键
           VERSION_NUM, --版本号
           IS_SAME_VERSION --是否同类型版本
      FROM (SELECT A.*, ROWNUM AS RN
              FROM (SELECT PROJ_NAME, --项目全称
                           PUBLISHER_NAME, --发行人全称
                           DEPT_NAME, --项目所属部门
                           DEPT_ID, --项目所属部门ID
                           PROJ_PRINCIPAL, --项目组负责人
                           PROJ_TYPENAME, --项目类型
                           PROJ_TYPECODE, --项目类型编码
                           UNDERTAKER, --承担角色
                           WIND_CODE, --WIND代码
                           SECURITY_NAME, --证券简称
                           PUBLISH_AMOUNT, --发行股数（股）
                           PUBLISH_PRICE, --发行价格（元）
                           UNDERWRITING_AMOUNT, --我司承销金额（元）
                           REPLACE(PUBLISH_TIME, '-', '') PUBLISH_TIME, --发行时间文本
                           REPLACE(CREATE_TIME, '-', '') CREATE_TIME, --创建时间文本
                           REPLACE(UPDATE_TIME, '-', '') UPDATE_TIME, --更新时间文本
                           CREATER, --创建人
                           UPDATER, --更新人
                           UDF_1, --我司收入
                           UDF_2, --是否申请开票
                           UDF_3, --审批状态
                           UDF_4, --本期发行金额(元)
                           UDF_5, --是否结转
                           RELATE_ID, --历史版本关联业务键
