  -- 业务处理过程
  --=============================================================

  --------------------------业务逻辑开始-----------------------------
BEGIN
  /*
   INSERT INTO THJS.T_TEST(C1,C2,C3,C4) VALUES(V_FUNCTION_NAME,I_OBJ_NAME,I_PAGE_NUM,I_PAGE_SIZE);
    COMMIT;
  */
  OPEN RT_CURSOR FOR
    SELECT B1.S_INFO_COMPCODE, --公司ID
           B1.S_INFO_COMPNAME, --公司名称
           B1.S_INFO_COMPNAMEENG, --英文名称
           B1.S_INFO_COUNTRY, --国家及地区
           B1.S_INFO_PROVINCE, --省份
           B1.S_INFO_CITY, --城市
           B1.S_INFO_CHAIRMAN, --姓名
           B1.S_INFO_PRESIDENT, --姓名
           B1.S_INFO_BDSECRETARY, --姓名
           B1.S_INFO_REGCAPITAL, --注册资本(万元)
           B1.S_INFO_FOUNDDATE, --成立日期
           B1.S_INFO_WEBSITE, --主页
           B1.S_INFO_EMAIL, --电子邮箱
           B1.S_INFO_OFFICE, --办公地址
           B1.ANN_DT, --公告日期
           B1.S_INFO_TOTALEMPLOYEES, --员工总数(人)
           B1.S_INFO_BUSINESSSCOPE, --经营范围
           B1.S_INFO_MAIN_BUSINESS, --主要产品及业务
           B1.S_INFO_CHINESEINTRODUCTION --公司简介
      FROM ZX90.Tcl_Neeqsintroduction B1
     INNER JOIN ZX90.TCL_COMPINTRODUCTION C
        ON C.COMP_ID = B1.S_INFO_COMPCODE
        or c.comp_name = b1.s_info_compname
     WHERE exists (SELECT 1
              FROM ZTGS.ENTERPRISEBASEINFOCOLLECT E --企业主体表
             WHERE E.PRIPID = I_OBJ_NAME
               and e.credit_code = C.REGISTERNUMBER);

  commit;

  O_RETURN_CODE := 0;
  O_RETURN_MSG  := '执行成功';

  -- ============================================================================
  -- 错误处理部分
  -- ============================================================================

EXCEPTION
  WHEN OTHERS THEN
    O_RETURN_CODE := -1;
    O_RETURN_MSG  := V_ERROR_MSG || '--行号:' || TO_CHAR(V_ERROR_LINE) ||
                     '||sqlcode:' || SQLCODE || '||sqlerrm:||' ||
                     SUBSTR(SQLERRM, 1, 200);
    ROLLBACK;
    V_ERROR_MSG  := O_RETURN_MSG;
    V_ERROR_CODE := O_RETURN_CODE;
    P_ERROR_LOG('admin',
                V_FUNCTION_NAME,
                V_ERROR_CODE,
                V_ERROR_MSG,
                '',
                '1',
                O_RETURN_MSG,
                O_RETURN_CODE);
END;

Create or Replace PROCEDURE "THJS"."P_TYNEWS_NEEQS_ISSU" (RT_CURSOR  OUT TYPES.CURSORTYPE,
                                                     I_OBJ_NAME IN VARCHAR2,
                                                     --I_PAGE_NUM    IN NUMBER DEFAULT 0, --默认值0,
                                                     --I_PAGE_SIZE   IN NUMBER DEFAULT 0, --默认值0  如果I_PAGE_NUM，I_PAGE_SIZE都为0 则不分页，查询全部
                                                     --O_TOTAL_COUNT OUT INTEGER,
                                                     O_RETURN_MSG  OUT VARCHAR2,
                                                     O_RETURN_CODE OUT INTEGER) IS
  -------------------------------------------------------------------------------------
  -- COPYRIGHT          GTJA
  -- FUNC_ID            THJS.P_TYNEWS_WIND_COMP
  -- VERSION            1.0
  -- FUNC_NAME          WIND三板发行情况--发行情况
  -- FUNC_REMARK
  -- CREATE_DATE        2019-04-25
  -- CREATE_PROGRAMER   czc
  -- MODIFY_REMARK
  -- MODIFY_DATE
  --==============================================================================
  --固定变量
  V_FUNCTION_NAME VARCHAR2(64) DEFAULT 'THJS.P_TYNEWS_NEEQS_ISSU'; --存储过程名
  V_ERROR_MSG     VARCHAR2(1000); --返回信息
  V_ERROR_CODE    INTEGER;
  V_ERROR_LINE    INTEGER;
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  V_PAGE_NUM  NUMBER DEFAULT 0;
  V_PAGE_SIZE NUMBER;
  --=============================================================
  -- 业务处理过程
  --=============================================================

  --------------------------业务逻辑开始-----------------------------
BEGIN
  /*
   INSERT INTO THJS.T_TEST(C1,C2,C3,C4) VALUES(V_FUNCTION_NAME,I_OBJ_NAME,I_PAGE_NUM,I_PAGE_SIZE);
    COMMIT;
  */

  OPEN RT_CURSOR FOR
    SELECT n.s_info_windcode, --wind代码
           n.s_info_code, --交易代码
           n.s_info_name, --证券简称
           s.s_fellow_amount, --发行数量(万股)
           s.s_fellow_price, --发行价格
           n.s_info_pinyin, --简称拼音
           n.s_info_exchmarket, --交易所代码
           n.s_info_listdate, --上市时间
           n.s_info_delistdate, --摘牌时间
           s.s_fellow_offeringobject --发行对象
      FROM ZX90.Tcl_Neeqsdescription n
      left join zx90.tcl_neeqsseo s --发行信息不全？
        on s.s_info_windcode = n.s_info_windcode
     inner join zx90.tcl_windcustomcode_all w
        on w.s_info_windcode = n.s_info_windcode
     inner join zx90.tcl_neeqsintroduction i
        on i.s_info_compcode = w.s_info_compcode
     INNER JOIN ZX90.TCL_COMPINTRODUCTION C
        ON C.COMP_ID = i.s_info_compcode
        or c.comp_name = i.s_info_compname
     WHERE C.REGISTERNUMBER =
           (SELECT E.CREDIT_CODE
              FROM ZTGS.ENTERPRISEBASEINFOCOLLECT E --企业主体表
             WHERE E.PRIPID = I_OBJ_NAME)
       AND n.S_INFO_WINDCODE IN
           (SELECT T1.S_INFO_WINDCODE
              FROM ZX90.TCL_NEEQSAGENCY T1
             WHERE T1.S_AGENCY_NAMEID = '2024680')
     ORDER BY n.S_INFO_LISTDATE DESC;

  commit;

  O_RETURN_CODE := 0;
  O_RETURN_MSG  := '执行成功';

  -- ============================================================================
  -- 错误处理部分
  -- ============================================================================

EXCEPTION
  WHEN OTHERS THEN
    O_RETURN_CODE := -1;
    O_RETURN_MSG  := V_ERROR_MSG || '--行号:' || TO_CHAR(V_ERROR_LINE) ||
                     '||sqlcode:' || SQLCODE || '||sqlerrm:||' ||
                     SUBSTR(SQLERRM, 1, 200);
    ROLLBACK;
    V_ERROR_MSG  := O_RETURN_MSG;
    V_ERROR_CODE := O_RETURN_CODE;
    P_ERROR_LOG('admin',
                V_FUNCTION_NAME,
                V_ERROR_CODE,
                V_ERROR_MSG,
                '',
                '1',
                O_RETURN_MSG,
                O_RETURN_CODE);
END;

Create or Replace PROCEDURE "THJS"."P_TYNEWS_PRIV" (RT_CURSOR     OUT TYPES.CURSORTYPE,
                                               I_USERNAME    IN VARCHAR2,
                                               I_PRIPID      IN VARCHAR2,
                                               O_RETURN_MSG  OUT VARCHAR2,
                                               O_RETURN_CODE OUT INTEGER) IS
  -------------------------------------------------------------------------------------
  -- COPYRIGHT          GTJA
  -- FUNC_ID            THJS.P_TYNEWS_PRIV
  -- VERSION            1.0
  -- FUNC_NAME          投研大数据--权限控制
  -- FUNC_REMARK
  -- CREATE_DATE        2019-01-28
  -- CREATE_PROGRAMER   HAIYANG.XU
  -- MODIFY_REMARK
  -- MODIFY_DATE
  --==============================================================================
  --固定变量
  V_FUNCTION_NAME VARCHAR2(64) DEFAULT 'THJS.P_TYNEWS_PRIV'; --存储过程名
  V_ERROR_MSG     VARCHAR2(1000); --返回信息
  V_ERROR_CODE    INTEGER;
  V_ERROR_LINE    INTEGER;
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  V_PAGE_NUM  NUMBER DEFAULT 0;
  V_PAGE_SIZE NUMBER;
  v_superuser integer default 0;
  --=============================================================
  -- 业务处理过程
  --=============================================================

  --------------------------业务逻辑开始-----------------------------
BEGIN
  /*
  INSERT INTO THJS.T_TEST
    (C1, C2, C3)
  VALUES
    (V_FUNCTION_NAME, I_USERNAME, I_PRIPID);
  COMMIT;
  */

  --判断是否超级用户
  if i_username = 'admin' then
    v_superuser := 1;
  else
    select count(1)
      into v_superuser
      from BASIC_THJS.wb_role r
     inner join BASIC_THJS.wb_user_role ur
        on ur.role_id = r.role_id
     inner join BASIC_THJS.wb_user u
        on u.user_id = ur.user_id
     where r.role_id = 'admin-th' --具有投行admin权限的用户
       and u.user_name = i_username;
  end if;

  OPEN RT_CURSOR FOR
    select v_superuser AS OPEN_FLAG from DUAL;

  /*if v_superuser = 0 then
    --非权限用户
  
    OPEN RT_CURSOR FOR
      SELECT DECODE(COUNT(1), 0, 0, 1) OPEN_FLAG
        FROM THJS.TB_USER_FOCUS T
       WHERE T.USERNAME = I_USERNAME
         AND T.PRIPID = I_PRIPID;
  else
    OPEN RT_CURSOR FOR
      select 1 AS OPEN_FLAG from DUAL;
  end if;*/

  O_RETURN_CODE := 0;
  O_RETURN_MSG  := '执行成功';

  -- ============================================================================
  -- 错误处理部分
  -- ============================================================================

EXCEPTION
  WHEN OTHERS THEN
    O_RETURN_CODE := -1;
    O_RETURN_MSG  := V_ERROR_MSG || '--行号:' || TO_CHAR(V_ERROR_LINE) ||
                     '||sqlcode:' || SQLCODE || '||sqlerrm:||' ||
                     SUBSTR(SQLERRM, 1, 200);
    ROLLBACK;
    V_ERROR_MSG  := O_RETURN_MSG;
    V_ERROR_CODE := O_RETURN_CODE;
    P_ERROR_LOG('admin',
                V_FUNCTION_NAME,
                V_ERROR_CODE,
                V_ERROR_MSG,
                '',
                '1',
                O_RETURN_MSG,
                O_RETURN_CODE);
END;

Create or Replace PROCEDURE "THJS"."P_TYNEWS_PUBLIS_ATIVE" (RT_CURSOR     OUT TYPES.CURSORTYPE,
                                                        I_OBJ_NAME    IN VARCHAR2,
                                                        I_REPO_TYPE   IN VARCHAR2, --0，最新；1，一季报；2，半年报,；3，三举报；4，年报
                                                        I_UNIT_CONV   IN NUMBER DEFAULT 3, --单位：1，千元；2，万元；3，百万；4，亿；5，十亿
                                                        I_YEAR_TERM   IN NUMBER DEFAULT 10, --年限间隔
                                                        I_PAGE_NUM    IN NUMBER DEFAULT 0, --默认值0,
                                                        I_PAGE_SIZE   IN NUMBER DEFAULT 0, --默认值0  如果I_PAGE_NUM，I_PAGE_SIZE都为0 则不分页，查询全部
                                                        O_TOTAL_COUNT OUT INTEGER,
                                                        O_RETURN_MSG  OUT VARCHAR2,
                                                        O_RETURN_CODE OUT INTEGER) IS
  -------------------------------------------------------------------------------------
  -- COPYRIGHT          GTJA
  -- FUNC_ID            THJS.P_TYNEWS_PUBLIS_ATIVE
  -- VERSION            1.0
  -- FUNC_NAME          发行人财务报表 --财务衍生指标
  -- FUNC_REMARK
  -- CREATE_DATE        2019-07-29
  -- CREATE_PROGRAMER   yongyong.zhang
  -- MODIFY_REMARK
  -- MODIFY_DATE
  --==============================================================================
  --固定变量
  V_FUNCTION_NAME VARCHAR2(64) DEFAULT 'THJS.P_TYNEWS_PUBLIS_ATIVE'; --存储过程名
  V_ERROR_MSG     VARCHAR2(1000); --返回信息
  V_ERROR_CODE    INTEGER;
  V_ERROR_LINE    INTEGER;
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  V_PAGE_NUM      NUMBER DEFAULT 0;
  V_PAGE_SIZE     NUMBER;
  V_COL_NAME      VARCHAR2(4000);
  V_STAR_DATE     VARCHAR2(10);
  V_LAST_DATE     VARCHAR2(10);
  V_OBJ_NAME      VARCHAR2(100);
  V_YEAR_TERM     NUMBER;
  V_UNIT_CONV     NUMBER;
  V_REPO_TYPE     VARCHAR2(20);
  V_WIND_COMPCODE VARCHAR2(100);
  V_SQL           CLOB;
  --=============================================================
  -- 业务处理过程
  --=============================================================

  --------------------------业务逻辑开始-----------------------------
BEGIN
  /*
   INSERT INTO THJS.T_TEST(C1,C2,C3,C4) VALUES(V_FUNCTION_NAME,I_OBJ_NAME,I_PAGE_NUM,I_PAGE_SIZE);
    COMMIT;
  */
  V_OBJ_NAME  := I_OBJ_NAME;
  V_YEAR_TERM := nvl(I_YEAR_TERM, 10);
  V_UNIT_CONV := I_UNIT_CONV;
  V_REPO_TYPE := NVL(I_REPO_TYPE, '0,4');
  IF V_UNIT_CONV = 1 THEN
    V_UNIT_CONV := 1000; --千元
  ELSIF V_UNIT_CONV = 2 THEN
    V_UNIT_CONV := 1000 * 10; --万元
  ELSIF V_UNIT_CONV = 3 THEN
    V_UNIT_CONV := 1000 * 1000; --百万
  ELSIF V_UNIT_CONV = 4 THEN
    V_UNIT_CONV := 1000 * 1000 * 100; --亿元
  ELSIF V_UNIT_CONV = 5 THEN
    V_UNIT_CONV := 1000 * 1000 * 1000; --十亿
  ELSE
    V_UNIT_CONV := 1000 * 1000;
  END IF;
  --查出公司ID

  SELECT c.comp_id
    INTO V_WIND_COMPCODE
    FROM ZTGS.ENTERPRISEBASEINFOCOLLECT T
    left join ZX90.TCL_COMPINTRODUCTION C
      on t.credit_code = c.registernumber
   WHERE T.PRIPID = V_OBJ_NAME;

  --V_WIND_COMPCODE  := '08434FC24D';   ---样例

  IF I_PAGE_NUM IS NOT NULL THEN
    V_PAGE_NUM := I_PAGE_NUM;
  END IF;

  --统计记录条数
  IF V_PAGE_NUM < 1 THEN
    SELECT COUNT(1)
      INTO O_TOTAL_COUNT
      FROM THJS.TB_WIND_FINANCIALDERIVATIVE T1
     WHERE T1.WIND_COMPCODE = V_WIND_COMPCODE;
  END IF;
  --年度期限判别
  SELECT MAX(COLUMN_NAME),
         (SUBSTR(MAX(COLUMN_NAME), 1, 4) - V_YEAR_TERM + 1) || '0101'
    INTO V_LAST_DATE, V_STAR_DATE
    FROM ALL_TAB_COLUMNS T1
   WHERE T1.OWNER = 'THJS'
     AND T1.TABLE_NAME = 'TB_WIND_FINANCIALDERIVATIVE'
     AND REGEXP_LIKE(T1.COLUMN_NAME, '[0-9]+')
     AND MOD(SUBSTR(COLUMN_NAME, 5, 2), 3) = 0;

  IF V_REPO_TYPE = '0' THEN
    V_STAR_DATE := V_LAST_DATE;
  END IF;
  --年度范围筛选

  SELECT 'SELECT COLUMN_TITLE,' ||
         listagg('NVL(TRIM(TO_CHAR("' || COLUMN_NAME || '"/' || V_UNIT_CONV ||
                 ',''99,999,999,999,990.00'')),''-'') AS "' || COLUMN_TEXT || '"',
                 ',') within group(order by COLUMN_NAME desc) || ' FROM THJS.TB_WIND_FINANCIALDERIVATIVE  WHERE  WIND_COMPCODE = ''' || V_WIND_COMPCODE || ''' ORDER BY COLUMN_ID'
    INTO V_SQL
    FROM (

          SELECT COLUMN_NAME,
                  SUBSTR(COLUMN_NAME, 5, 2) / 3 COLUMN_NUM,
                  SUBSTR(COLUMN_NAME, 1, 4) ||
                  DECODE(SUBSTR(COLUMN_NAME, 5, 2) / 3,
                         4,
                         '年报',
                         3,
                         '三季报' ， 2,
                         '半年报' ， 1,
                         '一季报') COLUMN_TEXT
            FROM ALL_TAB_COLUMNS T1
           WHERE T1.OWNER = 'THJS'
             AND T1.TABLE_NAME = 'TB_WIND_FINANCIALDERIVATIVE'
             AND REGEXP_LIKE(T1.COLUMN_NAME, '[0-9]+')
             AND DECODE(MOD(SUBSTR(COLUMN_NAME, 5, 2), 3), 0, 1, NULL) IS NOT NULL
             AND COLUMN_NAME BETWEEN V_STAR_DATE AND V_LAST_DATE) T2
   WHERE DECODE(COLUMN_NAME, V_STAR_DATE, 0, COLUMN_NUM) IN
         (SELECT REGEXP_SUBSTR(V_REPO_TYPE, '[^,]', 1, LEVEL)
            FROM DUAL
          CONNECT BY LEVEL < REGEXP_COUNT(V_REPO_TYPE, '[^,]') + 1);

  IF I_PAGE_SIZE IS NOT NULL AND I_PAGE_SIZE <> 0 THEN
    V_PAGE_SIZE := I_PAGE_SIZE;
  ELSE
    V_PAGE_SIZE := O_TOTAL_COUNT;
  END IF;

  OPEN RT_CURSOR FOR V_SQL;
  O_RETURN_CODE := 0;
  O_RETURN_MSG  := '执行成功';

  -- ============================================================================
  -- 错误处理部分
  -- ============================================================================

EXCEPTION
  WHEN OTHERS THEN
    O_RETURN_CODE := -1;
    O_RETURN_MSG  := V_ERROR_MSG || '--行号:' || TO_CHAR(V_ERROR_LINE) ||
                     '||sqlcode:' || SQLCODE || '||sqlerrm:||' ||
                     SUBSTR(SQLERRM, 1, 200);
    ROLLBACK;
    V_ERROR_MSG  := O_RETURN_MSG;
    V_ERROR_CODE := O_RETURN_CODE;
    P_ERROR_LOG('admin',
                V_FUNCTION_NAME,
                V_ERROR_CODE,
                V_ERROR_MSG,
                '',
                '1',
                O_RETURN_MSG,
                O_RETURN_CODE);
END;

Create or Replace PROCEDURE "THJS"."P_TYNEWS_PUBLIS_ATIVE_TEST" (RT_CURSOR        OUT TYPES.CURSORTYPE,
                                               I_OBJ_NAME       IN VARCHAR2,
                                               I_PAGE_NUM       IN NUMBER DEFAULT 0, --默认值0,
                                               I_PAGE_SIZE      IN NUMBER DEFAULT 0, --默认值0  如果I_PAGE_NUM，I_PAGE_SIZE都为0 则不分页，查询全部
                                               O_TOTAL_COUNT    OUT INTEGER,
                                               O_RETURN_MSG     OUT VARCHAR2,
                                               O_RETURN_CODE    OUT INTEGER
                                               ) IS
  -------------------------------------------------------------------------------------
  -- COPYRIGHT          GTJA
  -- FUNC_ID            THJS.P_TYNEWS_PUBLIS_ATIVE_TEST
  -- VERSION            1.0
  -- FUNC_NAME          发行人财务报表 --财务衍生指标表
  -- FUNC_REMARK
  -- CREATE_DATE        2019-07-25
  -- CREATE_PROGRAMER   yongyong.zhang
  -- MODIFY_REMARK
  -- MODIFY_DATE
  --==============================================================================
  --固定变量
  V_FUNCTION_NAME VARCHAR2(64) DEFAULT 'THJS.P_TYNEWS_PUBLIS_ATIVE_TEST'; --存储过程名
  V_ERROR_MSG         VARCHAR2(1000); --返回信息
  V_ERROR_CODE        INTEGER;
  V_ERROR_LINE        INTEGER;
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  V_PAGE_NUM  NUMBER DEFAULT 0;
  V_PAGE_SIZE NUMBER;
  --=============================================================
  -- 业务处理过程
  --=============================================================

  --------------------------业务逻辑开始-----------------------------
BEGIN
  /*
   INSERT INTO THJS.T_TEST(C1,C2,C3,C4) VALUES(V_FUNCTION_NAME,I_OBJ_NAME,I_PAGE_NUM,I_PAGE_SIZE);
    COMMIT;
  */
  IF I_PAGE_NUM IS NOT NULL THEN
    V_PAGE_NUM := I_PAGE_NUM;
  END IF;

  --统计记录条数
  IF V_PAGE_NUM < 1 THEN
    SELECT COUNT(1)
      INTO O_TOTAL_COUNT
      FROM ZX90.TCL_ASHAREFINANCIALINDICATOR A1,
            ZX90.TCL_CBONDFINANCIALINDICATOR A2
      WHERE A1.S_INFO_COMPCODE = A2.S_INFO_COMPCODE
        AND A1.S_INFO_COMPCODE = '2oU649F33E' ;

  END IF;

  IF I_PAGE_SIZE IS NOT NULL AND I_PAGE_SIZE <> 0 THEN
    V_PAGE_SIZE := I_PAGE_SIZE;
  ELSE
    V_PAGE_SIZE := O_TOTAL_COUNT;
  END IF;
     OPEN RT_CURSOR FOR
         SELECT
                                 S_INFO_WINDCODE                  ,--                 Wind代码
                                 WIND_CODE                        ,--                Wind代码
                                 ANN_DT                           ,--              公告日期
                                 REPORT_PERIOD                    ,--               报告期
                                 CRNCY_CODE                       ,--              货币代码
                                 S_FA_EXTRAORDINARY               ,--             非经常性损益
                                 S_FA_DEDUCTEDPROFIT            ,--                 扣除非经常性损益后的净利润
                                 S_FA_GROSSMARGIN               ,--             毛利
                                 S_FA_OPERATEINCOME               ,--             经营活动净收益
                                 S_FA_INVESTINCOME                ,--             价值变动净收益
                                 S_STMNOTE_FINEXP               ,--             利息费用
                                 S_STM_IS                       ,--             折旧与摊销
                                 S_FA_EBIT                        ,--             息税前利润
                                 S_FA_EBITDA                    ,--                 息税折旧摊销前利润
                                 S_FA_FCFF                        ,--             企业自由现金流量(FCFF)
                                 S_FA_FCFE                        ,--             股权自由现金流量(FCFE)
                                 S_FA_EXINTERESTDEBT_CURRENT    ,--                 无息流动负债
                                 S_FA_EXINTERESTDEBT_NONCURRENT   ,--             无息非流动负债
                                 S_FA_INTERESTDEBT                ,--             带息债务
                                 S_FA_NETDEBT                   ,--              净债务
                                 S_FA_TANGIBLEASSET               ,--            有形资产
                                 S_FA_WORKINGCAPITAL            ,--                营运资金
                                 S_FA_NETWORKINGCAPITAL           ,--        营运流动资本
                                 S_FA_INVESTCAPITAL               ,--           全部投入资本
                                 S_FA_RETAINEDEARNINGS            ,--             留存收益
                                 S_FA_EPS_BASIC                   ,--           基本每股收益
                                 S_FA_EPS_DILUTED               ,--           稀释每股收益
                                 S_FA_EPS_DILUTED2                ,--           期末摊薄每股收益
                                 S_FA_BPS                       ,--          每股净资产
                                 S_FA_OCFPS                       ,--          每股经营活动产生的现金流量净额
                                 S_FA_GRPS                        ,--          每股营业总收入
                                 S_FA_ORPS                        ,--          每股营业收入
                                 S_FA_SURPLUSCAPITALPS            ,--          每股资本公积
                                 S_FA_SURPLUSRESERVEPS            ,--          每股盈余公积
                                 S_FA_UNDISTRIBUTEDPS           ,--          每股未分配利润
                                 S_FA_RETAINEDPS                  ,--         每股留存收益
                                 S_FA_CFPS                        ,--         每股现金流量净额
                                 S_FA_EBITPS                      ,--         每股息税前利润
                                 S_FA_FCFFPS                      ,--         每股企业自由现金流量
                                 S_FA_FCFEPS                      ,--         每股股东自由现金流量
                                 S_FA_NETPROFITMARGIN           ,--         销售净利率
                                 S_FA_GROSSPROFITMARGIN           ,--         销售毛利率
                                 S_FA_COGSTOSALES               ,--       销售成本率
                                 S_FA_EXPENSETOSALES            ,--           销售期间费用率
                                 S_FA_PROFITTOGR                ,--         净利润/营业总收入
                                 S_FA_SALEEXPENSETOGR           ,--         销售费用/营业总收入
                                 S_FA_ADMINEXPENSETOGR            ,--         管理费用/营业总收入
                                 S_FA_FINAEXPENSETOGR           ,--         财务费用/营业总收入
                                 S_FA_IMPAIRTOGR_TTM            ,--            资产减值损失/营业总收入
                                 S_FA_GCTOGR                    ,--            营业总成本/营业总收入
                                 S_FA_OPTOGR                    ,--            营业利润/营业总收入
                                 S_FA_EBITTOGR                    ,--         息税前利润/营业总收入
                                 S_FA_ROE                       ,--         净资产收益率
                                 S_FA_ROE_DEDUCTED                ,--            净资产收益率(扣除非经常损益)
                                 S_FA_ROA2                        ,--        总资产报酬率
                                 S_FA_ROA                       ,--        总资产净利润
                                 S_FA_ROIC                        ,--        投入资本回报率
