                                 A1.S_QFA_FINAEXPENSETOGR           ,--          单季度.财务费用／营业总收入
                                 A1.S_QFA_IMPAIRTOGR_TTM            ,--          单季度.资产减值损失／营业总收
                                 A1.S_QFA_GCTOGR                    ,--     单季度.营业总成本／营业总收入
                                 A1.S_QFA_OPTOGR                    ,--     单季度.营业利润／营业总收入
                                 A1.S_QFA_ROE                       ,--     单季度.净资产收益率
                                 A1.S_QFA_ROE_DEDUCTED                ,--             单季度.净资产收益率(扣除非经常
                                 A1.S_QFA_ROA                       ,--单季度.总资产净利润
                                 A1.S_QFA_OPERATEINCOMETOEBT        ,--              单季度.经营活动净收益／利润总
                                 A1.S_QFA_INVESTINCOMETOEBT       ,--          单季度.价值变动净收益／利润总
                                 A1.S_QFA_DEDUCTEDPROFITTOPROFIT    ,--         单季度.扣除非经常损益后的净利
                                 A1.S_QFA_SALESCASHINTOOR           ,--     单季度.销售商品提供劳务收到的
                                 A1.S_QFA_OCFTOSALES                ,--   单季度.经营活动产生的现金流量
                                 A1.S_QFA_OCFTOOR                   ,--      单季度.经营活动产生的现金流量
                                 A1.S_FA_YOYEPS_BASIC               ,--                                            同比增长率-基本每股收益(%)
                                 A1.S_FA_YOYEPS_DILUTED              ,--             同比增长率-稀释每股收益(%)
                                 A1.S_FA_YOYOCFPS                   ,--       同比增长率-每股经营活动产生的
                                 A1.S_FA_YOYOP                        ,--         同比增长率-营业利润(%)
                                 A1.S_FA_YOYEBT                   ,--             同比增长率-利润总额(%)
                                 A1.S_FA_YOYNETPROFIT               ,--          同比增长率-归属母公司股东的净
                                 A1.S_FA_YOYNETPROFIT_DEDUCTED        ,--          同比增长率-归属母公司股东的净
                                 A1.S_FA_YOYOCF                   ,--             同比增长率-经营活动产生的现金
                                 A1.S_FA_YOYROE                   ,--             同比增长率-净资产收益率(摊薄)(
                                 A1.S_FA_YOYBPS                   ,--             相对年初增长率-每股净资产(%)
                                 A1.S_FA_YOYASSETS                    ,--      相对年初增长率-资产总计(%)
                                 A1.S_FA_YOYEQUITY                    ,--      相对年初增长率-归属母公司的股
                                 A1.S_FA_YOY_TR                   ,--            营业总收入同比增长率(%)
                                 A1.S_FA_YOY_OR                   ,--            营业收入同比增长率(%)
                                 A1.S_QFA_YOYGR                   ,--            单季度.营业总收入同比增长率(%)
                                 A1.S_QFA_CGRGR                   ,--            单季度.营业总收入环比增长率(%)
                                 A1.S_QFA_YOYSALES                    ,--        单季度.营业收入同比增长率(%)
                                 A1.S_QFA_CGRSALES                    ,--        单季度.营业收入环比增长率(%)
                                 A1.S_QFA_YOYOP                      ,--        单季度.营业利润同比增长率(%)
                                 A1.S_QFA_CGROP                      ,--        单季度.营业利润环比增长率(%)
                                 A1.S_QFA_YOYPROFIT               ,--              单季度.净利润同比增长率(%)
                                 A1.S_QFA_CGRPROFIT               ,--              单季度.净利润环比增长率(%)
                                 A1.S_QFA_YOYNETPROFIT                ,--           单季度.归属母公司股东的净利润
                                 A1.S_QFA_CGRNETPROFIT                ,--           单季度.归属母公司股东的净利润
                                 A1.S_FA_YOY_EQUITY               ,--            净资产(同比增长率)
                                 A1.RD_EXPENSE                        ,--    研发费用
                                 A1.WAA_ROE                       ,--         加权平均净资产收益率
                                 A1.S_INFO_COMPCODE            --                     公司ID
FROM ZX90.TCL_ASHAREFINANCIALINDICATOR  A1,
            ZX90.TCL_CBONDFINANCIALINDICATOR A2
      WHERE A1.S_INFO_COMPCODE = A2.S_INFO_COMPCODE
        AND A1.S_INFO_COMPCODE = '2oU649F33E'
                          ORDER BY A1.ANN_DT DESC

                                        ) A) B
     WHERE RN > V_PAGE_NUM
       AND RN <= V_PAGE_NUM + V_PAGE_SIZE;
  O_RETURN_CODE := 0;
  O_RETURN_MSG  := '执行成功';

  -- ============================================================================
  -- 错误处理部分
  -- ============================================================================

EXCEPTION
  WHEN OTHERS THEN
    O_RETURN_CODE := -1;
    O_RETURN_MSG  := V_ERROR_MSG || '--行号:' || TO_CHAR(V_ERROR_LINE) ||
                     '||sqlcode:' || SQLCODE || '||sqlerrm:||' ||
                     SUBSTR(SQLERRM, 1, 200);
    ROLLBACK;
    V_ERROR_MSG  := O_RETURN_MSG;
    V_ERROR_CODE := O_RETURN_CODE;
    P_ERROR_LOG('admin',
                V_FUNCTION_NAME,
                V_ERROR_CODE,
                V_ERROR_MSG,
                '',
                '1',
                O_RETURN_MSG,
                O_RETURN_CODE);
END;

Create or Replace PROCEDURE "THJS"."P_TYNEWS_PUBLIS_BALSHE" (RT_CURSOR     OUT TYPES.CURSORTYPE,
                                                        I_OBJ_NAME    IN VARCHAR2,
                                                        I_REPO_TYPE   IN VARCHAR2, --0，最新；1，一季报；2，半年报,；3，三举报；4，年报
                                                        I_UNIT_CONV   IN NUMBER DEFAULT 3, --单位：1，千元；2，万元；3，百万；4，亿；5，十亿
                                                        I_YEAR_TERM   IN NUMBER DEFAULT 10, --年限间隔
                                                        I_PAGE_NUM    IN NUMBER DEFAULT 0, --默认值0,
                                                        I_PAGE_SIZE   IN NUMBER DEFAULT 0, --默认值0  如果I_PAGE_NUM，I_PAGE_SIZE都为0 则不分页，查询全部
                                                        O_TOTAL_COUNT OUT INTEGER,
                                                        O_RETURN_MSG  OUT VARCHAR2,
                                                        O_RETURN_CODE OUT INTEGER) IS
  -------------------------------------------------------------------------------------
  -- COPYRIGHT          GTJA
  -- FUNC_ID            THJS.P_TYNEWS_PUBLIS_BALSHE
  -- VERSION            1.0
  -- FUNC_NAME          发行人财务报表 --资产负债情况
  -- FUNC_REMARK
  -- CREATE_DATE        2019-03-08
  -- CREATE_PROGRAMER   HAIYANG.XU
  -- MODIFY_REMARK
  -- MODIFY_DATE
  --==============================================================================
  --固定变量
  V_FUNCTION_NAME VARCHAR2(64) DEFAULT 'THJS.P_TYNEWS_PUBLIS_BALSHE'; --存储过程名
  V_ERROR_MSG     VARCHAR2(1000); --返回信息
  V_ERROR_CODE    INTEGER;
  V_ERROR_LINE    INTEGER;
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  V_PAGE_NUM      NUMBER DEFAULT 0;
  V_PAGE_SIZE     NUMBER;
  V_COL_NAME      VARCHAR2(4000);
  V_STAR_DATE     VARCHAR2(10);
  V_LAST_DATE     VARCHAR2(10);
  V_OBJ_NAME      VARCHAR2(100);
  V_YEAR_TERM     NUMBER;
  V_UNIT_CONV     NUMBER;
  V_REPO_TYPE     VARCHAR2(20);
  V_WIND_COMPCODE VARCHAR2(100);
  V_SQL           CLOB;
  --=============================================================
  -- 业务处理过程
  --=============================================================

  --------------------------业务逻辑开始-----------------------------
BEGIN
  /*
   INSERT INTO THJS.T_TEST(C1,C2,C3,C4,C5,C6,C7) VALUES(V_FUNCTION_NAME,I_OBJ_NAME,I_REPO_TYPE,I_UNIT_CONV,I_YEAR_TERM,I_PAGE_NUM,I_PAGE_SIZE);
    COMMIT;
  */
  --变量赋值
  V_OBJ_NAME  := I_OBJ_NAME;
  V_YEAR_TERM := nvl(I_YEAR_TERM, 10);
  V_UNIT_CONV := I_UNIT_CONV;
  V_REPO_TYPE := NVL(I_REPO_TYPE, '0,4');
  IF V_UNIT_CONV = 1 THEN
    V_UNIT_CONV := 1000; --千元
  ELSIF V_UNIT_CONV = 2 THEN
    V_UNIT_CONV := 1000 * 10; --万元
  ELSIF V_UNIT_CONV = 3 THEN
    V_UNIT_CONV := 1000 * 1000; --百万
  ELSIF V_UNIT_CONV = 4 THEN
    V_UNIT_CONV := 1000 * 1000 * 100; --亿元
  ELSIF V_UNIT_CONV = 5 THEN
    V_UNIT_CONV := 1000 * 1000 * 1000; --十亿
  ELSE
    V_UNIT_CONV := 1000 * 1000;
  END IF;
  --查出公司ID

  SELECT c.comp_id
    INTO V_WIND_COMPCODE
    FROM ZTGS.ENTERPRISEBASEINFOCOLLECT T
    left join ZX90.TCL_COMPINTRODUCTION C
      on t.credit_code = c.registernumber
   WHERE T.PRIPID = V_OBJ_NAME;

  --V_WIND_COMPCODE := '08434FC24D'; ---样例

  IF I_PAGE_NUM IS NOT NULL THEN
    V_PAGE_NUM := I_PAGE_NUM;
  END IF;

  --统计记录条数
  IF V_PAGE_NUM < 1 THEN
    SELECT COUNT(1)
      INTO O_TOTAL_COUNT
      FROM THJS.TB_WIND_CBONDBALANCESHEET T1
     WHERE T1.WIND_COMPCODE = V_WIND_COMPCODE;
  END IF;

  --年度期限判别
  SELECT MAX(COLUMN_NAME),
         (SUBSTR(MAX(COLUMN_NAME), 1, 4) - V_YEAR_TERM + 1) || '0101'
    INTO V_LAST_DATE, V_STAR_DATE
    FROM ALL_TAB_COLUMNS T1
   WHERE T1.OWNER = 'THJS'
     AND T1.TABLE_NAME = 'TB_WIND_CBONDBALANCESHEET'
     AND REGEXP_LIKE(T1.COLUMN_NAME, '[0-9]+')
     AND MOD(SUBSTR(COLUMN_NAME, 5, 2), 3) = 0;

  IF V_REPO_TYPE = '0' THEN
    V_STAR_DATE := V_LAST_DATE;
  END IF;
  --年度范围筛选

  SELECT 'SELECT COLUMN_TITLE,' ||
         listagg('NVL(TRIM(TO_CHAR("' || COLUMN_NAME || '"/' || V_UNIT_CONV ||
                 ',''99,999,999,999,990.00'')),''-'') AS "' || COLUMN_TEXT || '"',
                 ',') within group(order by COLUMN_NAME desc) || ' FROM THJS.TB_WIND_CBONDBALANCESHEET  WHERE  WIND_COMPCODE = ''' || V_WIND_COMPCODE || ''' ORDER BY COLUMN_ID'
    INTO V_SQL
    FROM (
          
          SELECT COLUMN_NAME,
                  SUBSTR(COLUMN_NAME, 5, 2) / 3 COLUMN_NUM,
                  SUBSTR(COLUMN_NAME, 1, 4) ||
                  DECODE(SUBSTR(COLUMN_NAME, 5, 2) / 3,
                         4,
                         '年报',
                         3,
                         '三季报' ， 2,
                         '半年报' ， 1,
                         '一季报') COLUMN_TEXT
            FROM ALL_TAB_COLUMNS T1
           WHERE T1.OWNER = 'THJS'
             AND T1.TABLE_NAME = 'TB_WIND_CBONDBALANCESHEET'
             AND REGEXP_LIKE(T1.COLUMN_NAME, '[0-9]+')
             AND DECODE(MOD(SUBSTR(COLUMN_NAME, 5, 2), 3), 0, 1, NULL) IS NOT NULL
             AND COLUMN_NAME BETWEEN V_STAR_DATE AND V_LAST_DATE) T2
   WHERE DECODE(COLUMN_NAME, V_STAR_DATE, 0, COLUMN_NUM) IN
         (SELECT REGEXP_SUBSTR(V_REPO_TYPE, '[^,]', 1, LEVEL)
            FROM DUAL
          CONNECT BY LEVEL < REGEXP_COUNT(V_REPO_TYPE, '[^,]') + 1);

  IF I_PAGE_SIZE IS NOT NULL AND I_PAGE_SIZE <> 0 THEN
    V_PAGE_SIZE := I_PAGE_SIZE;
  ELSE
    V_PAGE_SIZE := O_TOTAL_COUNT;
  END IF;

  OPEN RT_CURSOR FOR V_SQL; --USING V_OBJ_NAME,V_STAR_DATE,V_LAST_DATE,V_LAST_DATE;--I_REPO_TYPE;--V_REPO_TYPE;--,V_COL_NAME;
  O_RETURN_CODE := 0;
  O_RETURN_MSG  := '执行成功';

  -- ============================================================================
  -- 错误处理部分
  -- ============================================================================

EXCEPTION
  WHEN OTHERS THEN
    O_RETURN_CODE := -1;
    O_RETURN_MSG  := V_ERROR_MSG || '--行号:' || TO_CHAR(V_ERROR_LINE) ||
                     '||sqlcode:' || SQLCODE || '||sqlerrm:||' ||
                     SUBSTR(SQLERRM, 1, 200);
    ROLLBACK;
    V_ERROR_MSG  := O_RETURN_MSG;
    V_ERROR_CODE := O_RETURN_CODE;
    P_ERROR_LOG('admin',
                V_FUNCTION_NAME,
                V_ERROR_CODE,
                V_ERROR_MSG,
                '',
                '1',
                O_RETURN_MSG,
                O_RETURN_CODE);
END;

Create or Replace PROCEDURE "THJS"."P_TYNEWS_PUBLIS_BALSHE_TEST" (RT_CURSOR        OUT TYPES.CURSORTYPE,
                                               I_OBJ_NAME       IN VARCHAR2,
                                               I_PAGE_NUM       IN NUMBER DEFAULT 0, --默认值0,
                                               I_PAGE_SIZE      IN NUMBER DEFAULT 0, --默认值0  如果I_PAGE_NUM，I_PAGE_SIZE都为0 则不分页，查询全部
                                               O_TOTAL_COUNT    OUT INTEGER,
                                               O_RETURN_MSG     OUT VARCHAR2,
                                               O_RETURN_CODE    OUT INTEGER
                                               ) IS
  -------------------------------------------------------------------------------------
  -- COPYRIGHT          GTJA
  -- FUNC_ID            THJS.P_TYNEWS_PUBLIS_BALSHE_TEST
  -- VERSION            1.0
  -- FUNC_NAME          发行人财务报表 --资产负债情况
  -- FUNC_REMARK
  -- CREATE_DATE        2019-03-08
  -- CREATE_PROGRAMER   HAIYANG.XU
  -- MODIFY_REMARK
  -- MODIFY_DATE
  --==============================================================================
  --固定变量
  V_FUNCTION_NAME VARCHAR2(64) DEFAULT 'THJS.P_TYNEWS_PUBLIS_BALSHE_TEST'; --存储过程名
  V_ERROR_MSG         VARCHAR2(1000); --返回信息
  V_ERROR_CODE        INTEGER;
  V_ERROR_LINE        INTEGER;
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  V_PAGE_NUM  NUMBER DEFAULT 0;
  V_PAGE_SIZE NUMBER;
  --=============================================================
  -- 业务处理过程
  --=============================================================

  --------------------------业务逻辑开始-----------------------------
BEGIN
  /*
   INSERT INTO THJS.T_TEST(C1,C2,C3,C4) VALUES(V_FUNCTION_NAME,I_OBJ_NAME,I_PAGE_NUM,I_PAGE_SIZE);
    COMMIT;
  */
  IF I_PAGE_NUM IS NOT NULL THEN
    V_PAGE_NUM := I_PAGE_NUM;
  END IF;

  --统计记录条数
  IF V_PAGE_NUM < 1 THEN
    SELECT COUNT(1)
      INTO O_TOTAL_COUNT
      FROM ZX90.TCL_CBONDBALANCESHEET T
    WHERE T.S_INFO_COMPCODE = '2oU649F33E'
    ;
  END IF;

  IF I_PAGE_SIZE IS NOT NULL AND I_PAGE_SIZE <> 0 THEN
    V_PAGE_SIZE := I_PAGE_SIZE;
  ELSE
    V_PAGE_SIZE := O_TOTAL_COUNT;
  END IF;

  OPEN RT_CURSOR FOR
    SELECT
            ANN_DT                            ,-- 公告日期
            REPORT_PERIOD                     ,-- 报告期
            STATEMENT_TYPE                    ,-- 报表类型
            CRNCY_CODE                        ,-- 货币代码
            MONETARY_CAP                      ,-- 货币资金
            TRADABLE_FIN_ASSETS               ,-- 交易性金融资产
            NOTES_RCV                         ,-- 应收票据
            ACCT_RCV                          ,-- 应收账款
            OTH_RCV                           ,-- 其他应收款
            PREPAY                            ,-- 预付款项
            DVD_RCV                           ,-- 应收股利
            INT_RCV                           ,-- 应收利息
            INVENTORIES                       ,-- 存货
            CONSUMPTIVE_BIO_ASSETS            ,-- 消耗性生物资产
            DEFERRED_EXP                      ,-- 待摊费用
            NON_CUR_ASSETS_DUE_WITHIN_1Y      ,-- 一年内到期的非流动资产
            SETTLE_RSRV                       ,-- 结算备付金
            LOANS_TO_OTH_BANKS                ,-- 拆出资金
            PREM_RCV                          ,-- 应收保费
            RCV_FROM_REINSURER                ,-- 应收分保账款
            RCV_FROM_CEDED_INSUR_CONT_RSRV    ,-- 应收分保合同准备金
            RED_MONETARY_CAP_FOR_SALE         ,-- 买入返售金融资产
            OTH_CUR_ASSETS                    ,-- 其他流动资产
            TOT_CUR_ASSETS                    ,-- 流动资产合计
            FIN_ASSETS_AVAIL_FOR_SALE         ,-- 可供出售金融资产
            HELD_TO_MTY_INVEST                ,-- 持有至到期投资
            LONG_TERM_EQY_INVEST              ,-- 长期股权投资
            INVEST_REAL_ESTATE                ,-- 投资性房地产
            TIME_DEPOSITS                     ,-- 定期存款
            OTH_ASSETS                        ,-- 其他资产
            LONG_TERM_REC                     ,-- 长期应收款
            FIX_ASSETS                        ,-- 固定资产
            CONST_IN_PROG                     ,-- 在建工程
            PROJ_MATL                         ,-- 工程物资
            FIX_ASSETS_DISP                   ,-- 固定资产清理
            PRODUCTIVE_BIO_ASSETS             ,-- 生产性生物资产
            OIL_AND_NATURAL_GAS_ASSETS        ,-- 油气资产
            INTANG_ASSETS                     ,-- 无形资产
            R_AND_D_COSTS                     ,-- 开发支出
            GOODWILL                          ,-- 商誉
            LONG_TERM_DEFERRED_EXP            ,-- 长期待摊费用
            DEFERRED_TAX_ASSETS               ,-- 递延所得税资产
            LOANS_AND_ADV_GRANTED             ,-- 发放贷款及垫款
            OTH_NON_CUR_ASSETS                ,-- 其他非流动资产
            TOT_NON_CUR_ASSETS                ,-- 非流动资产合计
            CASH_DEPOSITS_CENTRAL_BANK        ,-- 现金及存放中央银行款项
            ASSET_DEP_OTH_BANKS_FIN_INST      ,-- 存放同业和其它金融机构款项
            PRECIOUS_METALS                   ,-- 贵金属
            DERIVATIVE_FIN_ASSETS             ,-- 衍生金融资产
            AGENCY_BUS_ASSETS                 ,-- 代理业务资产
            SUBR_REC                          ,-- 应收代位追偿款
            RCV_CEDED_UNEARNED_PREM_RSRV      ,-- 应收分保未到期责任准备金
            RCV_CEDED_CLAIM_RSRV              ,-- 应收分保未决赔款准备金
            RCV_CEDED_LIFE_INSUR_RSRV         ,-- 应收分保寿险责任准备金
            RCV_CEDED_LT_HEALTH_INSUR_RSRV    ,-- 应收分保长期健康险责任准备金
            MRGN_PAID                         ,-- 存出保证金
            INSURED_PLEDGE_LOAN               ,-- 保户质押贷款
            CAP_MRGN_PAID                     ,-- 存出资本保证金
            INDEPENDENT_ACCT_ASSETS           ,-- 独立账户资产
            CLIENTS_CAP_DEPOSIT               ,-- 客户资金存款
            CLIENTS_RSRV_SETTLE               ,-- 客户备付金
            INCL_SEAT_FEES_EXCHANGE           ,-- 其中:交易席位费
            RCV_INVEST                        ,-- 应收款项类投资
            TOT_ASSETS                        ,-- 资产总计
            ST_BORROW                         ,-- 短期借款
            BORROW_CENTRAL_BANK               ,-- 向中央银行借款
            DEPOSIT_RECEIVED_IB_DEPOSITS      ,-- 吸收存款及同业存放
            LOANS_OTH_BANKS                   ,-- 拆入资金
            TRADABLE_FIN_LIAB                 ,-- 交易性金融负债
            NOTES_PAYABLE                     ,-- 应付票据
            ACCT_PAYABLE                      ,-- 应付账款
            ADV_FROM_CUST                     ,-- 预收款项
            FUND_SALES_FIN_ASSETS_RP          ,-- 卖出回购金融资产款
            HANDLING_CHARGES_COMM_PAYABLE     ,-- 应付手续费及佣金
            EMPL_BEN_PAYABLE                  ,-- 应付职工薪酬
            TAXES_SURCHARGES_PAYABLE          ,-- 应交税费
            INT_PAYABLE                       ,-- 应付利息
            DVD_PAYABLE                       ,-- 应付股利
            OTH_PAYABLE                       ,-- 其他应付款
            ACC_EXP                           ,-- 预提费用
            DEFERRED_INC                      ,-- 递延收益
            ST_BONDS_PAYABLE                  ,-- 应付短期债券
            PAYABLE_TO_REINSURER              ,-- 应付分保账款
            RSRV_INSUR_CONT                   ,-- 保险合同准备金
            ACTING_TRADING_SEC                ,-- 代理买卖证券款
            ACTING_UW_SEC                     ,-- 代理承销证券款
            NON_CUR_LIAB_DUE_WITHIN_1Y        ,-- 一年内到期的非流动负债
            OTH_CUR_LIAB                      ,-- 其他流动负债
            TOT_CUR_LIAB                      ,-- 流动负债合计
            LT_BORROW                         ,-- 长期借款
            BONDS_PAYABLE                     ,-- 应付债券
            LT_PAYABLE                        ,-- 长期应付款
            SPECIFIC_ITEM_PAYABLE             ,-- 专项应付款
            PROVISIONS                        ,-- 预计负债
            DEFERRED_TAX_LIAB                 ,-- 递延所得税负债
            DEFERRED_INC_NON_CUR_LIAB         ,-- 递延收益-非流动负债
            OTH_NON_CUR_LIAB                  ,-- 其他非流动负债
            TOT_NON_CUR_LIAB                  ,-- 非流动负债合计
            LIAB_DEP_OTH_BANKS_FIN_INST       ,-- 同业和其它金融机构存放款项
            DERIVATIVE_FIN_LIAB               ,-- 衍生金融负债
            CUST_BANK_DEP                     ,-- 吸收存款
            AGENCY_BUS_LIAB                   ,-- 代理业务负债
            OTH_LIAB                          ,-- 其他负债
            PREM_RECEIVED_ADV                 ,-- 预收保费
            DEPOSIT_RECEIVED                  ,-- 存入保证金
            INSURED_DEPOSIT_INVEST            ,-- 保户储金及投资款
            UNEARNED_PREM_RSRV                ,-- 未到期责任准备金
            OUT_LOSS_RSRV                     ,-- 未决赔款准备金
            LIFE_INSUR_RSRV                   ,-- 寿险责任准备金
            LT_HEALTH_INSUR_V                 ,-- 长期健康险责任准备金
            INDEPENDENT_ACCT_LIAB             ,-- 独立账户负债
            INCL_PLEDGE_LOAN                  ,-- 其中:质押借款
            CLAIMS_PAYABLE                    ,-- 应付赔付款
