                                TOT_SHR                           ,-- 期末总股本
                                HFS_ASSETS                        ,-- 持有待售的资产
                                HFS_SALES                         ,-- 持有待售的负债
                                ACCOUNTS_RECEIVABLE_BILL          ,-- 应收票据及应收账款
                                ACCOUNTS_PAYABLE                  ,-- 应付票据及应付账款
                                OTH_RCV_TOT                       ,-- 其他应收款(合计)
                                STM_BS_TOT                        ,-- 固定资产(合计)
                                CONST_IN_PROG_TOT                 ,-- 在建工程(合计)
                                OTH_PAYABLE_TOT                   ,-- 其他应付款(合计)
                                LT_PAYABLE_TOT                    ,-- 长期应付款(合计)
                                DEBT_INVESTMENT                   ,-- 债权投资
                                OTHER_DEBT_INVESTMENT             ,-- 其他债权投资
                                OTHER_EQUITY_INVESTMENT           ,-- 其他权益工具投资
                                OTHER_ILLIQUIDFINANCIAL_ASSETS    ,-- 其他非流动金融资产
                                OTHER_SUSTAINABLE_BOND            ,-- 其他权益工具:永续债
                                CONTRACTUAL_ASSETS                ,-- 合同资产
                                CONTRACT_LIABILITIES              -- 合同负债
                                 FROM ZX90.TCL_CBONDBALANCESHEET T
                                WHERE T.S_INFO_COMPCODE = '2oU649F33E'
                                ORDER BY T.ANN_DT DESC

                                        ) A) B
     WHERE RN > V_PAGE_NUM
       AND RN <= V_PAGE_NUM + V_PAGE_SIZE;
  O_RETURN_CODE := 0;
  O_RETURN_MSG  := '执行成功';

  -- ============================================================================
  -- 错误处理部分
  -- ============================================================================

EXCEPTION
  WHEN OTHERS THEN
    O_RETURN_CODE := -1;
    O_RETURN_MSG  := V_ERROR_MSG || '--行号:' || TO_CHAR(V_ERROR_LINE) ||
                     '||sqlcode:' || SQLCODE || '||sqlerrm:||' ||
                     SUBSTR(SQLERRM, 1, 200);
    ROLLBACK;
    V_ERROR_MSG  := O_RETURN_MSG;
    V_ERROR_CODE := O_RETURN_CODE;
    P_ERROR_LOG('admin',
                V_FUNCTION_NAME,
                V_ERROR_CODE,
                V_ERROR_MSG,
                '',
                '1',
                O_RETURN_MSG,
                O_RETURN_CODE);
END;

Create or Replace PROCEDURE "THJS"."P_TYNEWS_PUBLIS_CASH" (RT_CURSOR     OUT TYPES.CURSORTYPE,
                                                      I_OBJ_NAME    IN VARCHAR2,
                                                      I_REPO_TYPE   IN VARCHAR2, --0，最新；1，一季报；2，半年报,；3，三举报；4，年报
                                                      I_UNIT_CONV   IN NUMBER DEFAULT 3, --单位：1，千元；2，万元；3，百万；4，亿；5，十亿
                                                      I_YEAR_TERM   IN NUMBER DEFAULT 10, --年限间隔
                                                      I_PAGE_NUM    IN NUMBER DEFAULT 0, --默认值0,
                                                      I_PAGE_SIZE   IN NUMBER DEFAULT 0, --默认值0  如果I_PAGE_NUM，I_PAGE_SIZE都为0 则不分页，查询全部
                                                      O_TOTAL_COUNT OUT INTEGER,
                                                      O_RETURN_MSG  OUT VARCHAR2,
                                                      O_RETURN_CODE OUT INTEGER) IS
  -------------------------------------------------------------------------------------
  -- COPYRIGHT          GTJA
  -- FUNC_ID            THJS.P_TYNEWS_PUBLIS_CASH
  -- VERSION            1.0
  -- FUNC_NAME          发行人财务报表 --  现金流量情况
  -- FUNC_REMARK
  -- CREATE_DATE        2019-03-08
  -- CREATE_PROGRAMER   HAIYANG.XU
  -- MODIFY_REMARK
  -- MODIFY_DATE
  --==============================================================================
  --固定变量
  V_FUNCTION_NAME VARCHAR2(64) DEFAULT 'THJS.P_TYNEWS_PUBLIS_CASH'; --存储过程名
  V_ERROR_MSG     VARCHAR2(1000); --返回信息
  V_ERROR_CODE    INTEGER;
  V_ERROR_LINE    INTEGER;
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  V_PAGE_NUM      NUMBER DEFAULT 0;
  V_PAGE_SIZE     NUMBER;
  V_COL_NAME      VARCHAR2(4000);
  V_STAR_DATE     VARCHAR2(10);
  V_LAST_DATE     VARCHAR2(10);
  V_OBJ_NAME      VARCHAR2(100);
  V_YEAR_TERM     NUMBER;
  V_UNIT_CONV     NUMBER;
  V_REPO_TYPE     VARCHAR2(20);
  V_WIND_COMPCODE VARCHAR2(100);
  V_SQL           CLOB;
  --=============================================================
  -- 业务处理过程
  --=============================================================

  --------------------------业务逻辑开始-----------------------------
BEGIN
  /*
   INSERT INTO THJS.T_TEST(C1,C2,C3,C4) VALUES(V_FUNCTION_NAME,I_OBJ_NAME,I_PAGE_NUM,I_PAGE_SIZE);
    COMMIT;
  */
  --变量赋值
  V_OBJ_NAME  := I_OBJ_NAME;
  V_YEAR_TERM := nvl(I_YEAR_TERM, 10);
  V_UNIT_CONV := I_UNIT_CONV;
  V_REPO_TYPE := NVL(I_REPO_TYPE, '0,4');
  IF V_UNIT_CONV = 1 THEN
    V_UNIT_CONV := 1000; --千元
  ELSIF V_UNIT_CONV = 2 THEN
    V_UNIT_CONV := 1000 * 10; --万元
  ELSIF V_UNIT_CONV = 3 THEN
    V_UNIT_CONV := 1000 * 1000; --百万
  ELSIF V_UNIT_CONV = 4 THEN
    V_UNIT_CONV := 1000 * 1000 * 100; --亿元
  ELSIF V_UNIT_CONV = 5 THEN
    V_UNIT_CONV := 1000 * 1000 * 1000; --十亿
  ELSE
    V_UNIT_CONV := 1000 * 1000;
  END IF;
  --查出公司ID

  SELECT c.comp_id
    INTO V_WIND_COMPCODE
    FROM ZTGS.ENTERPRISEBASEINFOCOLLECT T
    left join ZX90.TCL_COMPINTRODUCTION C
      on t.credit_code = c.registernumber
   WHERE T.PRIPID = V_OBJ_NAME;

  --V_WIND_COMPCODE  := '08434FC24D';   ---样例

  IF I_PAGE_NUM IS NOT NULL THEN
    V_PAGE_NUM := I_PAGE_NUM;
  END IF;

  --统计记录条数
  IF V_PAGE_NUM < 1 THEN
    SELECT COUNT(1)
      INTO O_TOTAL_COUNT
      FROM THJS.TB_WIND_CBONDCASHFLOW T1
     WHERE T1.WIND_COMPCODE = V_WIND_COMPCODE;
  END IF;
  --年度期限判别
  SELECT MAX(COLUMN_NAME),
         (SUBSTR(MAX(COLUMN_NAME), 1, 4) - V_YEAR_TERM + 1) || '0101'
    INTO V_LAST_DATE, V_STAR_DATE
    FROM ALL_TAB_COLUMNS T1
   WHERE T1.OWNER = 'THJS'
     AND T1.TABLE_NAME = 'TB_WIND_CBONDCASHFLOW'
     AND REGEXP_LIKE(T1.COLUMN_NAME, '[0-9]+')
     AND MOD(SUBSTR(COLUMN_NAME, 5, 2), 3) = 0;

  IF V_REPO_TYPE = '0' THEN
    V_STAR_DATE := V_LAST_DATE;
  END IF;
  --年度范围筛选

  SELECT 'SELECT COLUMN_TITLE,' ||
         listagg('NVL(TRIM(TO_CHAR("' || COLUMN_NAME || '"/' || V_UNIT_CONV ||
                 ',''99,999,999,999,990.00'')),''-'') AS "' || COLUMN_TEXT || '"',
                 ',') within group(order by COLUMN_NAME desc) || ' FROM THJS.TB_WIND_CBONDCASHFLOW  WHERE  WIND_COMPCODE = ''' || V_WIND_COMPCODE || ''' ORDER BY COLUMN_ID'
    INTO V_SQL
    FROM (
          
          SELECT COLUMN_NAME,
                  SUBSTR(COLUMN_NAME, 5, 2) / 3 COLUMN_NUM,
                  SUBSTR(COLUMN_NAME, 1, 4) ||
                  DECODE(SUBSTR(COLUMN_NAME, 5, 2) / 3,
                         4,
                         '年报',
                         3,
                         '三季报' ， 2,
                         '半年报' ， 1,
                         '一季报') COLUMN_TEXT
            FROM ALL_TAB_COLUMNS T1
           WHERE T1.OWNER = 'THJS'
             AND T1.TABLE_NAME = 'TB_WIND_CBONDCASHFLOW'
             AND REGEXP_LIKE(T1.COLUMN_NAME, '[0-9]+')
             AND DECODE(MOD(SUBSTR(COLUMN_NAME, 5, 2), 3), 0, 1, NULL) IS NOT NULL
             AND COLUMN_NAME BETWEEN V_STAR_DATE AND V_LAST_DATE) T2
   WHERE DECODE(COLUMN_NAME, V_STAR_DATE, 0, COLUMN_NUM) IN
         (SELECT REGEXP_SUBSTR(V_REPO_TYPE, '[^,]', 1, LEVEL)
            FROM DUAL
          CONNECT BY LEVEL < REGEXP_COUNT(V_REPO_TYPE, '[^,]') + 1);

  IF I_PAGE_SIZE IS NOT NULL AND I_PAGE_SIZE <> 0 THEN
    V_PAGE_SIZE := I_PAGE_SIZE;
  ELSE
    V_PAGE_SIZE := O_TOTAL_COUNT;
  END IF;

  OPEN RT_CURSOR FOR V_SQL;

  O_RETURN_CODE := 0;
  O_RETURN_MSG  := '执行成功';

  -- ============================================================================
  -- 错误处理部分
  -- ============================================================================

EXCEPTION
  WHEN OTHERS THEN
    O_RETURN_CODE := -1;
    O_RETURN_MSG  := V_ERROR_MSG || '--行号:' || TO_CHAR(V_ERROR_LINE) ||
                     '||sqlcode:' || SQLCODE || '||sqlerrm:||' ||
                     SUBSTR(SQLERRM, 1, 200);
    ROLLBACK;
    V_ERROR_MSG  := O_RETURN_MSG;
    V_ERROR_CODE := O_RETURN_CODE;
    P_ERROR_LOG('admin',
                V_FUNCTION_NAME,
                V_ERROR_CODE,
                V_ERROR_MSG,
                '',
                '1',
                O_RETURN_MSG,
                O_RETURN_CODE);
END;

Create or Replace PROCEDURE "THJS"."P_TYNEWS_PUBLIS_CASH_TEST" (RT_CURSOR        OUT TYPES.CURSORTYPE,
                                               I_OBJ_NAME       IN VARCHAR2,
                                               I_PAGE_NUM       IN NUMBER DEFAULT 0, --默认值0,
                                               I_PAGE_SIZE      IN NUMBER DEFAULT 0, --默认值0  如果I_PAGE_NUM，I_PAGE_SIZE都为0 则不分页，查询全部
                                               O_TOTAL_COUNT    OUT INTEGER,
                                               O_RETURN_MSG     OUT VARCHAR2,
                                               O_RETURN_CODE    OUT INTEGER
                                               ) IS
  -------------------------------------------------------------------------------------
  -- COPYRIGHT          GTJA
  -- FUNC_ID            THJS.P_TYNEWS_PUBLIS_CASH_TEST
  -- VERSION            1.0
  -- FUNC_NAME          发行人财务报表 --  现金流量情况
  -- FUNC_REMARK
  -- CREATE_DATE        2019-03-08
  -- CREATE_PROGRAMER   HAIYANG.XU
  -- MODIFY_REMARK
  -- MODIFY_DATE
  --==============================================================================
  --固定变量
  V_FUNCTION_NAME VARCHAR2(64) DEFAULT 'THJS.P_TYNEWS_PUBLIS_CASH_TEST'; --存储过程名
  V_ERROR_MSG         VARCHAR2(1000); --返回信息
  V_ERROR_CODE        INTEGER;
  V_ERROR_LINE        INTEGER;
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  V_PAGE_NUM  NUMBER DEFAULT 0;
  V_PAGE_SIZE NUMBER;
  --=============================================================
  -- 业务处理过程
  --=============================================================

  --------------------------业务逻辑开始-----------------------------
BEGIN
  /*
   INSERT INTO THJS.T_TEST(C1,C2,C3,C4) VALUES(V_FUNCTION_NAME,I_OBJ_NAME,I_PAGE_NUM,I_PAGE_SIZE);
    COMMIT;
  */
  IF I_PAGE_NUM IS NOT NULL THEN
    V_PAGE_NUM := I_PAGE_NUM;
  END IF;

  --统计记录条数
  IF V_PAGE_NUM < 1 THEN
    SELECT COUNT(1)
      INTO O_TOTAL_COUNT
      FROM     ZX90.TCL_CBONDCASHFLOW T
    WHERE T.S_INFO_COMPCODE = '2oU649F33E'
    ;
  END IF;

  IF I_PAGE_SIZE IS NOT NULL AND I_PAGE_SIZE <> 0 THEN
    V_PAGE_SIZE := I_PAGE_SIZE;
  ELSE
    V_PAGE_SIZE := O_TOTAL_COUNT;
  END IF;

  OPEN RT_CURSOR FOR
    SELECT
           ANN_DT                            ,-- 公告日期
           REPORT_PERIOD                     ,-- 报告期
           STATEMENT_TYPE                    ,-- 报表类型
           CRNCY_CODE                        ,-- 货币代码
