Create or Replace PROCEDURE "THJS"."P_TYNEWS_PUBLIS_DICATOR_TEST" (RT_CURSOR        OUT TYPES.CURSORTYPE,
                                               I_OBJ_NAME       IN VARCHAR2,
                                               I_PAGE_NUM       IN NUMBER DEFAULT 0, --默认值0,
                                               I_PAGE_SIZE      IN NUMBER DEFAULT 0, --默认值0  如果I_PAGE_NUM，I_PAGE_SIZE都为0 则不分页，查询全部
                                               O_TOTAL_COUNT    OUT INTEGER,
                                               O_RETURN_MSG     OUT VARCHAR2,
                                               O_RETURN_CODE    OUT INTEGER
                                               ) IS
  -------------------------------------------------------------------------------------
  -- COPYRIGHT          GTJA
  -- FUNC_ID            THJS.P_TYNEWS_PUBLIS_ATIVE_TEST
  -- VERSION            1.0
  -- FUNC_NAME          发行人财务报表 --财务指标表
  -- FUNC_REMARK
  -- CREATE_DATE        2019-07-30
  -- CREATE_PROGRAMER   yongyong.zhang
  -- MODIFY_REMARK
  -- MODIFY_DATE
  --==============================================================================
  --固定变量
  V_FUNCTION_NAME VARCHAR2(64) DEFAULT 'THJS.P_TYNEWS_PUBLIS_DICATOR_TEST'; --存储过程名
  V_ERROR_MSG         VARCHAR2(1000); --返回信息
  V_ERROR_CODE        INTEGER;
  V_ERROR_LINE        INTEGER;
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  V_PAGE_NUM  NUMBER DEFAULT 0;
  V_PAGE_SIZE NUMBER;
  --=============================================================
  -- 业务处理过程
  --=============================================================

  --------------------------业务逻辑开始-----------------------------
BEGIN
  /*
   INSERT INTO THJS.T_TEST(C1,C2,C3,C4) VALUES(V_FUNCTION_NAME,I_OBJ_NAME,I_PAGE_NUM,I_PAGE_SIZE);
    COMMIT;
  */
  IF I_PAGE_NUM IS NOT NULL THEN
    V_PAGE_NUM := I_PAGE_NUM;
  END IF;

  --统计记录条数
  IF V_PAGE_NUM < 1 THEN
    SELECT COUNT(1)
      INTO O_TOTAL_COUNT
      FROM ZX90.TCL_ASHAREFINANCIALINDICATOR A1,
       ZX90.TCL_CBONDFINANCIALINDICATOR A2
    where a1.S_INFO_COMPCODE = a2.S_INFO_COMPCODE(+)
   AND A1.S_INFO_COMPCODE = '2oU649F33E' ;

  END IF;

  IF I_PAGE_SIZE IS NOT NULL AND I_PAGE_SIZE <> 0 THEN
    V_PAGE_SIZE := I_PAGE_SIZE;
  ELSE
    V_PAGE_SIZE := O_TOTAL_COUNT;
  END IF;
     OPEN RT_CURSOR FOR
                      SELECT     x.S_INFO_WINDCODE                  ,--                 Wind代码*/
                                 x.WIND_CODE                        ,--                Wind代码
                                 x.ANN_DT                           ,--              公告日期
                                 x.REPORT_PERIOD                    ,--               报告期
                                 x.CRNCY_CODE                       ,--              货币代码
                                 x.S_FA_EXTRAORDINARY               ,--             非经常性损益
                                 x.S_FA_DEDUCTEDPROFIT            ,--                 扣除非经常性损益后的净利润
                                 x.S_FA_GROSSMARGIN               ,--             毛利
                                 x.S_FA_OPERATEINCOME               ,--             经营活动净收益
                                 x.S_FA_INVESTINCOME                ,--             价值变动净收益
                                 x.S_STMNOTE_FINEXP               ,--             利息费用
                                 x.S_STM_IS                       ,--             折旧与摊销
                                 x.S_FA_EBIT                        ,--             息税前利润
                                 x.S_FA_EBITDA                    ,--                 息税折旧摊销前利润
                                 x.S_FA_FCFF                        ,--             企业自由现金流量(FCFF)
                                 x.S_FA_FXFE                        ,--             股权自由现金流量(FCFE)
                                 x.S_FA_EXINTERESTDEBT_CURRENT    ,--                 无息流动负债
                                 x.S_FA_EXINTERESTDEBT_NONCURRENT   ,--             无息非流动负债
                                 x.S_FA_INTERESTDEBT                ,--             带息债务
                                 x.S_FA_NETDEBT                   ,--              净债务
                                 x.S_FA_NETDEBY               ,--            有形资产
                                 x.S_FA_WORKINGCAPITAL            ,--                营运资金
                                 x.S_FA_NETWORKINGCAPITAL           ,--        营运流动资本
                                 x.S_FA_INVESTCAPITAL               ,--           全部投入资本
