            NVL(A.S_QFA_SALEEXPENSETOGR,B.S_QFA_SALEEXPENSETOGR) S_QFA_SALEEXPENSETOGR                                    ,--单季度.销售费用／营业总收入
            NVL(A.S_QFA_ADMINEXPENSETOGR,B.S_QFA_ADMINEXPENSETOGR) S_QFA_ADMINEXPENSETOGR                                 ,--单季度.管理费用／营业总收入
            NVL(A.S_QFA_FINAEXPENSETOGR,B.S_QFA_FINAEXPENSETOGR) S_QFA_FINAEXPENSETOGR                                    ,--单季度.财务费用／营业总收入
            NVL(A.S_QFA_IMPAIRTOGR_TTM,B.S_QFA_IMPAIRTOGR_TTM) S_QFA_IMPAIRTOGR_TTM                                       ,--单季度.资产减值损失／营业总收
