            NVL(A.S_FA_YOYNETPROFIT_DEDUCTED,B.S_FA_YOYNETPROFIT_DEDUCTED) S_FA_YOYNETPROFIT_DEDUCTED                   ,--同比增长率-归属母公司股东的净
            NVL(A.S_FA_YOYOCF,B.S_FA_YOYOCF) S_FA_YOYOCF                                                                ,--同比增长率-经营活动产生的现金
            NVL(A.S_FA_YOYROE,B.S_FA_YOYROE) S_FA_YOYROE5                                                                ,--同比增长率-净资产收益率(摊薄)(
            NVL(A.S_FA_YOYBPS,B.S_FA_YOYBPS) S_FA_YOYBPS                                                                ,--相对年初增长率-每股净资产(%)
            NVL(A.S_FA_YOYASSETS,B.S_FA_YOYASSETS) S_FA_YOYASSETS                                                       ,--相对年初增长率-资产总计(%)
            NVL(A.S_FA_YOYEQUITY,B.S_FA_YOYEQUITY) S_FA_YOYEQUITY                                                       ,--相对年初增长率-归属母公司的股
            NVL(A.S_FA_YOY_TR,B.S_FA_YOY_TR) S_FA_YOY_TR                                                                ,--营业总收入同比增长率(%)
            NVL(A.S_FA_YOY_OR,B.S_FA_YOY_OR) S_FA_YOY_OR                                                                ,--营业收入同比增长率(%)
            NVL(A.S_QFA_YOYGR,B.S_QFA_YOYGR) S_QFA_YOYGR                                                                ,--单季度.营业总收入同比增长率(%)
            NVL(A.S_QFA_CGRGR,B.S_QFA_CGRGR) S_QFA_CGRGR                                                                ,--单季度.营业总收入环比增长率(%)
            NVL(A.S_QFA_YOYSALES,B.S_QFA_YOYSALES) S_QFA_YOYSALES                                                       ,--单季度.营业收入同比增长率(%)
            NVL(A.S_QFA_CGRSALES,B.S_QFA_CGRSALES) S_QFA_CGRSALES                                                       ,--单季度.营业收入环比增长率(%)
            NVL(A.S_QFA_YOYOP,B.S_QFA_YOYOP) S_QFA_YOYOP                                                                ,--单季度.营业利润同比增长率(%)
            NVL(A.S_QFA_CGROP,B.S_QFA_CGROP) S_QFA_CGROP                                                                ,--单季度.营业利润环比增长率(%)
            NVL(A.S_QFA_YOYPROFIT,B.S_QFA_YOYPROFIT) S_QFA_YOYPROFIT                                                   ,--单季度.净利润同比增长率(%)
            NVL(A.S_QFA_CGRPROFIT,B.S_QFA_CGRPROFIT) S_QFA_CGRPROFIT                                                   ,--单季度.净利润环比增长率(%)
            NVL(A.S_QFA_YOYNETPROFIT,B.S_QFA_YOYNETPROFIT) S_QFA_YOYNETPROFIT                                              ,--单季度.归属母公司股东的净利润
            NVL(A.S_QFA_CGRNETPROFIT,B.S_QFA_CGRNETPROFIT) S_QFA_CGRNETPROFIT                                            ,--单季度.归属母公司股东的净利润
            NVL(A.S_FA_YOY_EQUITY,B.S_FA_YOY_EQUITY) S_FA_YOY_EQUITY                                                   ,--净资产(同比增长率)
            NVL(A.RD_EXPENSE,B.RD_EXPENSE) RD_EXPENSE                                                                  --研发费用
           
          FROM ZX90.TCL_ASHAREFINANCIALINDICATOR A,
       ZX90.TCL_CBONDFINANCIALINDICATOR B
    where a.S_INFO_COMPCODE = b.S_INFO_COMPCODE(+)
   AND A.S_INFO_COMPCODE = '2oU649F33E'
                          ORDER BY ANN_DT DESC) C) X
     WHERE RN > V_PAGE_NUM
       AND RN <= V_PAGE_NUM + V_PAGE_SIZE;
  O_RETURN_CODE := 0;
  O_RETURN_MSG  := '执行成功';

  -- ============================================================================
  -- 错误处理部分
  -- ============================================================================

EXCEPTION
  WHEN OTHERS THEN
    O_RETURN_CODE := -1;
    O_RETURN_MSG  := V_ERROR_MSG || '--行号:' || TO_CHAR(V_ERROR_LINE) ||
                     '||sqlcode:' || SQLCODE || '||sqlerrm:||' ||
                     SUBSTR(SQLERRM, 1, 200);
    ROLLBACK;
    V_ERROR_MSG  := O_RETURN_MSG;
    V_ERROR_CODE := O_RETURN_CODE;
    P_ERROR_LOG('admin',
                V_FUNCTION_NAME,
                V_ERROR_CODE,
                V_ERROR_MSG,
                '',
                '1',
                O_RETURN_MSG,
                O_RETURN_CODE);
END;

Create or Replace PROCEDURE "THJS"."P_TYNEWS_PUBLIS_PROFIT" (RT_CURSOR     OUT TYPES.CURSORTYPE,
                                                        I_OBJ_NAME    IN VARCHAR2,
                                                        I_REPO_TYPE   IN VARCHAR2, --0，最新；1，一季报；2，半年报,；3，三举报；4，年报
                                                        I_UNIT_CONV   IN NUMBER DEFAULT 3, --单位：1，千元；2，万元；3，百万；4，亿；5，十亿
                                                        I_YEAR_TERM   IN NUMBER DEFAULT 10, --年限间隔
                                                        I_PAGE_NUM    IN NUMBER DEFAULT 0, --默认值0,
                                                        I_PAGE_SIZE   IN NUMBER DEFAULT 0, --默认值0  如果I_PAGE_NUM，I_PAGE_SIZE都为0 则不分页，查询全部
                                                        O_TOTAL_COUNT OUT INTEGER,
                                                        O_RETURN_MSG  OUT VARCHAR2,
                                                        O_RETURN_CODE OUT INTEGER) IS
  -------------------------------------------------------------------------------------
  -- COPYRIGHT          GTJA
  -- FUNC_ID            THJS.P_TYNEWS_PUBLIS_PROFIT
  -- VERSION            1.0
  -- FUNC_NAME          发行人财务报表 --  利润情况
  -- FUNC_REMARK
  -- CREATE_DATE        2019-03-08
  -- CREATE_PROGRAMER   HAIYANG.XU
  -- MODIFY_REMARK
  -- MODIFY_DATE
  --==============================================================================
  --固定变量
  V_FUNCTION_NAME VARCHAR2(64) DEFAULT 'THJS.P_TYNEWS_PUBLIS_PROFIT'; --存储过程名
  V_ERROR_MSG     VARCHAR2(1000); --返回信息
  V_ERROR_CODE    INTEGER;
  V_ERROR_LINE    INTEGER;
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  V_PAGE_NUM      NUMBER DEFAULT 0;
  V_PAGE_SIZE     NUMBER;
  V_COL_NAME      VARCHAR2(4000);
  V_STAR_DATE     VARCHAR2(10);
  V_LAST_DATE     VARCHAR2(10);
  V_OBJ_NAME      VARCHAR2(100);
  V_YEAR_TERM     NUMBER;
  V_UNIT_CONV     NUMBER;
  V_REPO_TYPE     VARCHAR2(20);
  V_WIND_COMPCODE VARCHAR2(100);
  V_SQL           CLOB;
  --=============================================================
  -- 业务处理过程
  --=============================================================

  --------------------------业务逻辑开始-----------------------------
BEGIN
  /*
   INSERT INTO THJS.T_TEST(C1,C2,C3,C4) VALUES(V_FUNCTION_NAME,I_OBJ_NAME,I_PAGE_NUM,I_PAGE_SIZE);
    COMMIT;
  */
  V_OBJ_NAME  := I_OBJ_NAME;
  V_YEAR_TERM := nvl(I_YEAR_TERM, 10);
  V_UNIT_CONV := I_UNIT_CONV;
  V_REPO_TYPE := NVL(I_REPO_TYPE, '0,4');
  IF V_UNIT_CONV = 1 THEN
    V_UNIT_CONV := 1000; --千元
  ELSIF V_UNIT_CONV = 2 THEN
    V_UNIT_CONV := 1000 * 10; --万元
  ELSIF V_UNIT_CONV = 3 THEN
    V_UNIT_CONV := 1000 * 1000; --百万
  ELSIF V_UNIT_CONV = 4 THEN
    V_UNIT_CONV := 1000 * 1000 * 100; --亿元
  ELSIF V_UNIT_CONV = 5 THEN
    V_UNIT_CONV := 1000 * 1000 * 1000; --十亿
  ELSE
    V_UNIT_CONV := 1000 * 1000;
  END IF;
  --查出公司ID

  SELECT c.comp_id
    INTO V_WIND_COMPCODE
    FROM ZTGS.ENTERPRISEBASEINFOCOLLECT T
    left join ZX90.TCL_COMPINTRODUCTION C
      on t.credit_code = c.registernumber
   WHERE T.PRIPID = V_OBJ_NAME;

  --V_WIND_COMPCODE  := '08434FC24D';   ---样例

  IF I_PAGE_NUM IS NOT NULL THEN
    V_PAGE_NUM := I_PAGE_NUM;
  END IF;

  --统计记录条数
  IF V_PAGE_NUM < 1 THEN
    SELECT COUNT(1)
      INTO O_TOTAL_COUNT
      FROM THJS.TB_WIND_CBONDINCOME T1
     WHERE T1.WIND_COMPCODE = V_WIND_COMPCODE;
  END IF;
  --年度期限判别
  SELECT MAX(COLUMN_NAME),
         (SUBSTR(MAX(COLUMN_NAME), 1, 4) - V_YEAR_TERM + 1) || '0101'
    INTO V_LAST_DATE, V_STAR_DATE
    FROM ALL_TAB_COLUMNS T1
   WHERE T1.OWNER = 'THJS'
     AND T1.TABLE_NAME = 'TB_WIND_CBONDINCOME'
     AND REGEXP_LIKE(T1.COLUMN_NAME, '[0-9]+')
     AND MOD(SUBSTR(COLUMN_NAME, 5, 2), 3) = 0;

  IF V_REPO_TYPE = '0' THEN
    V_STAR_DATE := V_LAST_DATE;
  END IF;
  --年度范围筛选

  SELECT 'SELECT COLUMN_TITLE,' ||
         listagg('NVL(TRIM(TO_CHAR("' || COLUMN_NAME || '"/' || V_UNIT_CONV ||
                 ',''99,999,999,999,990.00'')),''-'') AS "' || COLUMN_TEXT || '"',
                 ',') within group(order by COLUMN_NAME desc) || ' FROM THJS.TB_WIND_CBONDINCOME  WHERE  WIND_COMPCODE = ''' || V_WIND_COMPCODE || ''' ORDER BY COLUMN_ID'
    INTO V_SQL
    FROM (
          
          SELECT COLUMN_NAME,
                  SUBSTR(COLUMN_NAME, 5, 2) / 3 COLUMN_NUM,
                  SUBSTR(COLUMN_NAME, 1, 4) ||
                  DECODE(SUBSTR(COLUMN_NAME, 5, 2) / 3,
                         4,
                         '年报',
                         3,
                         '三季报' ， 2,
                         '半年报' ， 1,
                         '一季报') COLUMN_TEXT
            FROM ALL_TAB_COLUMNS T1
           WHERE T1.OWNER = 'THJS'
             AND T1.TABLE_NAME = 'TB_WIND_CBONDINCOME'
             AND REGEXP_LIKE(T1.COLUMN_NAME, '[0-9]+')
             AND DECODE(MOD(SUBSTR(COLUMN_NAME, 5, 2), 3), 0, 1, NULL) IS NOT NULL
             AND COLUMN_NAME BETWEEN V_STAR_DATE AND V_LAST_DATE) T2
   WHERE DECODE(COLUMN_NAME, V_STAR_DATE, 0, COLUMN_NUM) IN
         (SELECT REGEXP_SUBSTR(V_REPO_TYPE, '[^,]', 1, LEVEL)
            FROM DUAL
          CONNECT BY LEVEL < REGEXP_COUNT(V_REPO_TYPE, '[^,]') + 1);

  IF I_PAGE_SIZE IS NOT NULL AND I_PAGE_SIZE <> 0 THEN
    V_PAGE_SIZE := I_PAGE_SIZE;
  ELSE
    V_PAGE_SIZE := O_TOTAL_COUNT;
  END IF;

  OPEN RT_CURSOR FOR V_SQL;
  O_RETURN_CODE := 0;
  O_RETURN_MSG  := '执行成功';

  -- ============================================================================
  -- 错误处理部分
  -- ============================================================================

EXCEPTION
  WHEN OTHERS THEN
    O_RETURN_CODE := -1;
    O_RETURN_MSG  := V_ERROR_MSG || '--行号:' || TO_CHAR(V_ERROR_LINE) ||
                     '||sqlcode:' || SQLCODE || '||sqlerrm:||' ||
                     SUBSTR(SQLERRM, 1, 200);
    ROLLBACK;
    V_ERROR_MSG  := O_RETURN_MSG;
    V_ERROR_CODE := O_RETURN_CODE;
    P_ERROR_LOG('admin',
                V_FUNCTION_NAME,
                V_ERROR_CODE,
                V_ERROR_MSG,
                '',
                '1',
                O_RETURN_MSG,
                O_RETURN_CODE);
END;

Create or Replace PROCEDURE "THJS"."P_TYNEWS_PUBLIS_PROFIT_TEST" (RT_CURSOR        OUT TYPES.CURSORTYPE,
                                               I_OBJ_NAME       IN VARCHAR2,
                                               I_PAGE_NUM       IN NUMBER DEFAULT 0, --默认值0,
                                               I_PAGE_SIZE      IN NUMBER DEFAULT 0, --默认值0  如果I_PAGE_NUM，I_PAGE_SIZE都为0 则不分页，查询全部
                                               O_TOTAL_COUNT    OUT INTEGER,
                                               O_RETURN_MSG     OUT VARCHAR2,
                                               O_RETURN_CODE    OUT INTEGER
                                               ) IS
  -------------------------------------------------------------------------------------
  -- COPYRIGHT          GTJA
  -- FUNC_ID            THJS.P_TYNEWS_PUBLIS_PROFIT_TEST
  -- VERSION            1.0
  -- FUNC_NAME          发行人财务报表 --  利润情况
  -- FUNC_REMARK
  -- CREATE_DATE        2019-03-08
  -- CREATE_PROGRAMER   HAIYANG.XU
  -- MODIFY_REMARK
  -- MODIFY_DATE
  --==============================================================================
  --固定变量
  V_FUNCTION_NAME VARCHAR2(64) DEFAULT 'THJS.P_TYNEWS_PUBLIS_PROFIT_TEST'; --存储过程名
  V_ERROR_MSG         VARCHAR2(1000); --返回信息
  V_ERROR_CODE        INTEGER;
  V_ERROR_LINE        INTEGER;
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  V_PAGE_NUM  NUMBER DEFAULT 0;
  V_PAGE_SIZE NUMBER;
  --=============================================================
  -- 业务处理过程
  --=============================================================

  --------------------------业务逻辑开始-----------------------------
BEGIN
  /*
   INSERT INTO THJS.T_TEST(C1,C2,C3,C4) VALUES(V_FUNCTION_NAME,I_OBJ_NAME,I_PAGE_NUM,I_PAGE_SIZE);
    COMMIT;
  */
  IF I_PAGE_NUM IS NOT NULL THEN
    V_PAGE_NUM := I_PAGE_NUM;
  END IF;

  --统计记录条数
  IF V_PAGE_NUM < 1 THEN
    SELECT COUNT(1)
      INTO O_TOTAL_COUNT
      FROM     THJS.THDB_V_FINANCE_INCOME T
    WHERE T.PROJ_ID = '36882F79728D464A927EB92FBCC7B5E2'
    ;
  END IF;

  IF I_PAGE_SIZE IS NOT NULL AND I_PAGE_SIZE <> 0 THEN
    V_PAGE_SIZE := I_PAGE_SIZE;
  ELSE
    V_PAGE_SIZE := O_TOTAL_COUNT;
  END IF;

  OPEN RT_CURSOR FOR
    SELECT
            ANN_DT                             ,-- 公告日期
            REPORT_PERIOD                      ,-- 报告期
            STATEMENT_TYPE                     ,-- 报表类型
            CRNCY_CODE                         ,-- 货币代码
            TOT_OPER_REV                       ,-- 营业总收入
            OPER_REV                           ,-- 营业收入
            INT_INC                            ,-- 利息收入
            NET_INT_INC                        ,-- 利息净收入
            INSUR_PREM_UNEARNED                ,-- 已赚保费
            HANDLING_CHRG_COMM_INC             ,-- 手续费及佣金收入
            NET_HANDLING_CHRG_COMM_INC         ,-- 手续费及佣金净收入
            NET_INC_OTHER_OPS                  ,-- 其他经营净收益
            PLUS_NET_INC_OTHER_BUS             ,-- 加:其他业务净收益
            PREM_INC                           ,-- 保费业务收入
            LESS_CEDED_OUT_PREM                ,-- 减:分出保费
            CHG_UNEARNED_PREM_RES              ,-- 提取未到期责任准备金
            INCL_REINSURANCE_PREM_INC          ,-- 其中:分保费收入
            NET_INC_SEC_TRADING_BROK_BUS       ,-- 代理买卖证券业务净收入
            NET_INC_SEC_UW_BUS                 ,-- 证券承销业务净收入
            NET_INC_EC_ASSET_MGMT_BUS          ,-- 受托客户资产管理业务净收入
            OTHER_BUS_INC                      ,-- 其他业务收入
            PLUS_NET_GAIN_CHG_FV               ,-- 加:公允价值变动净收益
            PLUS_NET_INVEST_INC                ,-- 加:投资净收益
            INCL_INC_INVEST_ASSOC_JV_ENTP      ,-- 其中:对联营企业和合营企业的投
            PLUS_NET_GAIN_FX_TRANS             ,-- 加:汇兑净收益
            TOT_OPER_COST                      ,-- 营业总成本
            LESS_OPER_COST                     ,-- 减:营业成本
            LESS_INT_EXP                       ,-- 减:利息支出
            LESS_HANDLING_CHRG_COMM_EXP        ,-- 减:手续费及佣金支出
            LESS_TAXES_SURCHARGES_OPS          ,-- 减:营业税金及附加
            LESS_SELLING_DIST_EXP              ,-- 减:销售费用
            LESS_GERL_ADMIN_EXP                ,-- 减:管理费用
            LESS_FIN_EXP                       ,-- 减:财务费用
            LESS_IMPAIR_LOSS_ASSETS            ,-- 减:资产减值损失
            PREPAY_SURR                        ,-- 退保金
            TOT_CLAIM_EXP                      ,-- 赔付总支出
            CHG_INSUR_CONT_RSRV                ,-- 提取保险责任准备金
            DVD_EXP_INSURED                    ,-- 保户红利支出
            REINSURANCE_EXP                    ,-- 分保费用
            OPER_EXP                           ,-- 营业支出
            LESS_CLAIM_RECB_REINSURER          ,-- 减:摊回赔付支出
            LESS_INS_RSRV_RECB_REINSURER       ,-- 减:摊回保险责任准备金
            LESS_EXP_RECB_REINSURER            ,-- 减:摊回分保费用
            OTHER_BUS_COST                     ,-- 其他业务成本
            OPER_PROFIT                        ,-- 营业利润
            PLUS_NON_OPER_REV                  ,-- 加:营业外收入
            LESS_NON_OPER_EXP                  ,-- 减:营业外支出
            IL_NET_LOSS_DISP_NONCUR_ASSET      ,-- 其中:减:非流动资产处置净损失
            TOT_PROFIT                         ,-- 利润总额
            INC_TAX                            ,-- 所得税
            UNCONFIRMED_INVEST_LOSS            ,-- 未确认投资损失
            NET_PROFIT_INCL_MIN_INT_INC        ,-- 净利润(含少数股东损益)
            NET_PROFIT_EXCL_MIN_INT_INC        ,-- 净利润(不含少数股东损益)
            MINORITY_INT_INC                   ,-- 少数股东损益
            OTHER_COMPREH_INC                  ,-- 其他综合收益
            TOT_COMPREH_INC                    ,-- 综合收益总额
            TOT_COMPREH_INC_PARENT_COMP        ,-- 综合收益总额(母公司)
            TOT_COMPREH_INC_MIN_SHRHLDR        ,-- 综合收益总额(少数股东)
            S_FA_EPS_BASIC                     ,-- 基本每股收益
            S_FA_EPS_DILUTED                   ,-- 稀释每股收益
            ACTUAL_ANN_DT                      ,-- 实际公告日期
            INSURANCE_EXPENSE                  ,-- 保险业务支出
            SPE_BAL_OPER_PROFIT                ,-- 营业利润差额(特殊报表科目)
            TOT_BAL_OPER_PROFIT                ,-- 营业利润差额(合计平衡项目)
            SPE_BAL_TOT_PROFIT                 ,-- 利润总额差额(特殊报表科目)
            TOT_BAL_TOT_PROFIT                 ,-- 利润总额差额(合计平衡项目)
            SPE_BAL_NET_PROFIT                 ,-- 净利润差额(特殊报表科目)
            TOT_BAL_NET_PROFIT                 ,-- 净利润差额(合计平衡项目)
            UNDISTRIBUTED_PROFIT               ,-- 年初未分配利润
            ADJLOSSGAIN_PREVYEAR               ,-- 调整以前年度损益
            TRANSFER_FROM_SURPLUSRESERVE       ,-- 盈余公积转入
            TRANSFER_FROM_HOUSINGIMPREST       ,-- 住房周转金转入
            TRANSFER_FROM_OTHERS               ,-- 其他转入
            DISTRIBUTABLE_PROFIT               ,-- 可分配利润
            WITHDR_LEGALSURPLUS                ,-- 提取法定盈余公积
            WITHDR_LEGALPUBWELFUNDS            ,-- 提取法定公益金
            WORKERS_WELFARE                    ,-- 职工奖金福利
            WITHDR_BUZEXPWELFARE               ,-- 提取企业发展基金
            WITHDR_RESERVEFUND                 ,-- 提取储备基金
            DISTRIBUTABLE_PROFIT_SHRHDER       ,-- 可供股东分配的利润
            PRFSHARE_DVD_PAYABLE               ,-- 应付优先股股利
            WITHDR_OTHERSURPRESERVE            ,-- 提取任意盈余公积金
            COMSHARE_DVD_PAYABLE               ,-- 应付普通股股利
            CAPITALIZED_COMSTOCK_DIV           ,-- 转作股本的普通股股利
            AUDIT_AM                           ,-- 采用会计准则
            OTHER_INCOME                       ,-- 其他收益
            MEMO                               ,-- 备注
            ASSET_DISPOSAL_INCOME              ,-- 资产处置收益
            CONTINUED_NET_PROFIT               ,-- 持续经营净利润
            END_NET_PROFIT                     ,-- 终止经营净利润
            COMP_TYPE_CODE                     ,-- 公司类型代码
            CREDIT_IMPAIRMENT_LOSS             ,-- 信用减值损失
            NET_EXPOSURE_HEDGING_BENEFITS      ,-- 净敞口套期收益
            RD_EXPENSE                         ,-- 研发费用
            STMNOTE_FINEXP                     ,-- 财务费用:利息费用
            FIN_EXP_INT_INC                    -- 财务费用:利息收入

      FROM (SELECT A.*, ROWNUM AS RN
              FROM (
                       SELECT
                              ANN_DT                             ,-- 公告日期
                              REPORT_PERIOD                      ,-- 报告期
                              STATEMENT_TYPE                     ,-- 报表类型
                              CRNCY_CODE                         ,-- 货币代码
                              TOT_OPER_REV                       ,-- 营业总收入
                              OPER_REV                           ,-- 营业收入
                              INT_INC                            ,-- 利息收入
                              NET_INT_INC                        ,-- 利息净收入
                              INSUR_PREM_UNEARNED                ,-- 已赚保费
                              HANDLING_CHRG_COMM_INC             ,-- 手续费及佣金收入
                              NET_HANDLING_CHRG_COMM_INC         ,-- 手续费及佣金净收入
                              NET_INC_OTHER_OPS                  ,-- 其他经营净收益
                              PLUS_NET_INC_OTHER_BUS             ,-- 加:其他业务净收益
                              PREM_INC                           ,-- 保费业务收入
                              LESS_CEDED_OUT_PREM                ,-- 减:分出保费
                              CHG_UNEARNED_PREM_RES              ,-- 提取未到期责任准备金
                              INCL_REINSURANCE_PREM_INC          ,-- 其中:分保费收入
                              NET_INC_SEC_TRADING_BROK_BUS       ,-- 代理买卖证券业务净收入
                              NET_INC_SEC_UW_BUS                 ,-- 证券承销业务净收入
                              NET_INC_EC_ASSET_MGMT_BUS          ,-- 受托客户资产管理业务净收入
                              OTHER_BUS_INC                      ,-- 其他业务收入
                              PLUS_NET_GAIN_CHG_FV               ,-- 加:公允价值变动净收益
                              PLUS_NET_INVEST_INC                ,-- 加:投资净收益
                              INCL_INC_INVEST_ASSOC_JV_ENTP      ,-- 其中:对联营企业和合营企业的投
                              PLUS_NET_GAIN_FX_TRANS             ,-- 加:汇兑净收益
                              TOT_OPER_COST                      ,-- 营业总成本
                              LESS_OPER_COST                     ,-- 减:营业成本
                              LESS_INT_EXP                       ,-- 减:利息支出
                              LESS_HANDLING_CHRG_COMM_EXP        ,-- 减:手续费及佣金支出
                              LESS_TAXES_SURCHARGES_OPS          ,-- 减:营业税金及附加
                              LESS_SELLING_DIST_EXP              ,-- 减:销售费用
                              LESS_GERL_ADMIN_EXP                ,-- 减:管理费用
                              LESS_FIN_EXP                       ,-- 减:财务费用
                              LESS_IMPAIR_LOSS_ASSETS            ,-- 减:资产减值损失
                              PREPAY_SURR                        ,-- 退保金
                              TOT_CLAIM_EXP                      ,-- 赔付总支出
                              CHG_INSUR_CONT_RSRV                ,-- 提取保险责任准备金
                              DVD_EXP_INSURED                    ,-- 保户红利支出
                              REINSURANCE_EXP                    ,-- 分保费用
                              OPER_EXP                           ,-- 营业支出
                              LESS_CLAIM_RECB_REINSURER          ,-- 减:摊回赔付支出
                              LESS_INS_RSRV_RECB_REINSURER       ,-- 减:摊回保险责任准备金
                              LESS_EXP_RECB_REINSURER            ,-- 减:摊回分保费用
                              OTHER_BUS_COST                     ,-- 其他业务成本
                              OPER_PROFIT                        ,-- 营业利润
                              PLUS_NON_OPER_REV                  ,-- 加:营业外收入
                              LESS_NON_OPER_EXP                  ,-- 减:营业外支出
                              IL_NET_LOSS_DISP_NONCUR_ASSET      ,-- 其中:减:非流动资产处置净损失
                              TOT_PROFIT                         ,-- 利润总额
                              INC_TAX                            ,-- 所得税
                              UNCONFIRMED_INVEST_LOSS            ,-- 未确认投资损失
                              NET_PROFIT_INCL_MIN_INT_INC        ,-- 净利润(含少数股东损益)
                              NET_PROFIT_EXCL_MIN_INT_INC        ,-- 净利润(不含少数股东损益)
                              MINORITY_INT_INC                   ,-- 少数股东损益
                              OTHER_COMPREH_INC                  ,-- 其他综合收益
                              TOT_COMPREH_INC                    ,-- 综合收益总额
                              TOT_COMPREH_INC_PARENT_COMP        ,-- 综合收益总额(母公司)
                              TOT_COMPREH_INC_MIN_SHRHLDR        ,-- 综合收益总额(少数股东)
                              S_FA_EPS_BASIC                     ,-- 基本每股收益
                              S_FA_EPS_DILUTED                   ,-- 稀释每股收益
                              ACTUAL_ANN_DT                      ,-- 实际公告日期
                              INSURANCE_EXPENSE                  ,-- 保险业务支出
                              SPE_BAL_OPER_PROFIT                ,-- 营业利润差额(特殊报表科目)
                              TOT_BAL_OPER_PROFIT                ,-- 营业利润差额(合计平衡项目)
                              SPE_BAL_TOT_PROFIT                 ,-- 利润总额差额(特殊报表科目)
                              TOT_BAL_TOT_PROFIT                 ,-- 利润总额差额(合计平衡项目)
                              SPE_BAL_NET_PROFIT                 ,-- 净利润差额(特殊报表科目)
                              TOT_BAL_NET_PROFIT                 ,-- 净利润差额(合计平衡项目)
                              UNDISTRIBUTED_PROFIT               ,-- 年初未分配利润
                              ADJLOSSGAIN_PREVYEAR               ,-- 调整以前年度损益
                              TRANSFER_FROM_SURPLUSRESERVE       ,-- 盈余公积转入
                              TRANSFER_FROM_HOUSINGIMPREST       ,-- 住房周转金转入
                              TRANSFER_FROM_OTHERS               ,-- 其他转入
                              DISTRIBUTABLE_PROFIT               ,-- 可分配利润
                              WITHDR_LEGALSURPLUS                ,-- 提取法定盈余公积
                              WITHDR_LEGALPUBWELFUNDS            ,-- 提取法定公益金
                              WORKERS_WELFARE                    ,-- 职工奖金福利
                              WITHDR_BUZEXPWELFARE               ,-- 提取企业发展基金
                              WITHDR_RESERVEFUND                 ,-- 提取储备基金
                              DISTRIBUTABLE_PROFIT_SHRHDER       ,-- 可供股东分配的利润
                              PRFSHARE_DVD_PAYABLE               ,-- 应付优先股股利
                              WITHDR_OTHERSURPRESERVE            ,-- 提取任意盈余公积金
                              COMSHARE_DVD_PAYABLE               ,-- 应付普通股股利
                              CAPITALIZED_COMSTOCK_DIV           ,-- 转作股本的普通股股利
                              AUDIT_AM                           ,-- 采用会计准则
                              OTHER_INCOME                       ,-- 其他收益
                              MEMO                               ,-- 备注
                              ASSET_DISPOSAL_INCOME              ,-- 资产处置收益
                              CONTINUED_NET_PROFIT               ,-- 持续经营净利润
                              END_NET_PROFIT                     ,-- 终止经营净利润
                              COMP_TYPE_CODE                     ,-- 公司类型代码
                              CREDIT_IMPAIRMENT_LOSS             ,-- 信用减值损失
                              NET_EXPOSURE_HEDGING_BENEFITS      ,-- 净敞口套期收益
                              RD_EXPENSE                         ,-- 研发费用
                              STMNOTE_FINEXP                     ,-- 财务费用:利息费用
                              FIN_EXP_INT_INC                    -- 财务费用:利息收入

                              FROM     ZX90.TCL_CBONDINCOME T
                              WHERE T.S_INFO_COMPCODE = '2oU649F33E'
                              ORDER BY T.ANN_DT DESC

                                        ) A) B
     WHERE RN > V_PAGE_NUM
       AND RN <= V_PAGE_NUM + V_PAGE_SIZE;
  O_RETURN_CODE := 0;
  O_RETURN_MSG  := '执行成功';

  -- ============================================================================
  -- 错误处理部分
  -- ============================================================================

EXCEPTION
  WHEN OTHERS THEN
    O_RETURN_CODE := -1;
    O_RETURN_MSG  := V_ERROR_MSG || '--行号:' || TO_CHAR(V_ERROR_LINE) ||
                     '||sqlcode:' || SQLCODE || '||sqlerrm:||' ||
                     SUBSTR(SQLERRM, 1, 200);
    ROLLBACK;
    V_ERROR_MSG  := O_RETURN_MSG;
    V_ERROR_CODE := O_RETURN_CODE;
    P_ERROR_LOG('admin',
                V_FUNCTION_NAME,
                V_ERROR_CODE,
                V_ERROR_MSG,
                '',
                '1',
                O_RETURN_MSG,
                O_RETURN_CODE);
END;

Create or Replace PROCEDURE "THJS"."P_TYNEWS_SPHZ" (RT_CURSOR     OUT TYPES.CURSORTYPE,
                                               I_OBJ_NAME    IN VARCHAR2,
                                               O_RETURN_MSG  OUT VARCHAR2,
                                               O_RETURN_CODE OUT INTEGER) IS
  -------------------------------------------------------------------------------------
  -- COPYRIGHT          GTJA
  -- FUNC_ID            THJS.P_TYNEWS_GSXX_OUTINVESTA
  -- VERSION            1.0
  -- FUNC_NAME          投研大数据SP记录数汇总
  -- FUNC_REMARK
  -- CREATE_DATE        2019-01-28
  -- CREATE_PROGRAMER   HAIYANG.XU
  -- MODIFY_REMARK
  -- MODIFY_DATE
  --==============================================================================
  --固定变量
  V_FUNCTION_NAME VARCHAR2(64) DEFAULT 'THJS.P_TYNEWS_GSXX_OUTINVESTA'; --存储过程名
  V_ERROR_MSG     VARCHAR2(1000); --返回信息
  V_ERROR_CODE    INTEGER;
  V_ERROR_LINE    INTEGER;
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量

  v_tradedate   varchar2(8);
  v_pripid      varchar2(100); --工商主体编号
  v_entname     varchar2(250); --主体名称
  v_regno       varchar2(100); --工商注册号
  v_credit_code varchar2(100); --统一社会信用代码
  v_eid         varchar2(100); --企业ID
  v_count       integer default 0;
  --=============================================================
  -- 业务处理过程
  --=============================================================

  --------------------------业务逻辑开始-----------------------------
BEGIN
  /*
  INSERT INTO THJS.T_TEST (C1, C2) VALUES (V_FUNCTION_NAME, I_OBJ_NAME);
  COMMIT;
  */
  SELECT count(1)
    into v_count
    FROM ZTGS.ENTERPRISEBASEINFOCOLLECT E --企业主体表
   WHERE E.PRIPID = I_OBJ_NAME;
  --避免无数据造成的错误
  if v_count <> 0 then
    SELECT to_char(sysdate, 'yyyyMMdd'),
           E.Pripid,
           E.ENTNAME,
           E.REGNO,
           E.Credit_Code,
           E.EID
      into v_tradedate, v_pripid, v_entname, v_regno, v_credit_code, v_eid
      FROM ZTGS.ENTERPRISEBASEINFOCOLLECT E --企业主体表
     WHERE E.PRIPID = I_OBJ_NAME;
  end if;

  --判断缓存表中主体记录信息是否存在，否则更新后查询

  select count(1)
    into v_count
    from thjs.tb_comp_bizcount c
   where c.tradedate = v_tradedate
     and c.pripid = v_pripid;

  if v_count = 0 then
  
    thjs.p_comp_cache(i_pripid => v_pripid);
  
  end if;
  /*
  INSERT INTO THJS.T_TEST (C1, C2,c3,c4) VALUES (V_FUNCTION_NAME, I_OBJ_NAME,v_tradedate,v_pripid);
  commit;
  */
  OPEN RT_CURSOR FOR
    SELECT a.pro_name, nvl(c.col_num, 0) as col_num
      FROM (select column_value as pro_name
              from table(kingstar.splitstr('P_TYNEWS_INFO_XMZL,P_TYNEWS_INFO_FXXX,P_TYNEWS_INFO_XMSH,P_TYNEWS_INFO_JGYCF,P_TYNEWS_INFO_XYFXPC,' ||
                                           'P_TYNEWS_INFINA_MAIN,P_TYNEWS_INFINA_INCOME,P_TYNEWS_INFINA_EXPEN,P_TYNEWS_INFINA_INVO,P_TYNEWS_HIS_ADUIT,P_TYNEWS_ASTOCK_ISSU,' ||
                                           'P_TYNEWS_WIND_ISSU,P_TYNEWS_NEEQS_ISSU,P_TYNEWS_YULUN_CXXX,P_TYNEWS_YULUN_HYNEWS,P_TYNEWS_YULUN_NEWS,P_TYNEWS_GSXX_BRANCH,P_TYNEWS_GSXX_CHANGE,' ||
                                           'P_TYNEWS_GSXX_CHATTEL,P_TYNEWS_GSXX_FATAL,P_TYNEWS_GSXX_FREEZE,P_TYNEWS_GSXX_HOLDER,P_TYNEWS_GSXX_MANAGE,P_TYNEWS_GSXX_MEMBERS,P_TYNEWS_GSXX_MINFO,' ||
                                           'P_TYNEWS_GSXX_OUTINVESTA,P_TYNEWS_GSXX_PENALIZE,P_TYNEWS_GSXX_PERMISSION,P_TYNEWS_GSXX_PLEDGE,P_TYNEWS_GSXX_SETTLE',
                                           ','))) a
      left join thjs.tb_comp_bizcount c
        on c.tradedate = v_tradedate
       and c.pripid = v_pripid
       and c.pro_name = a.pro_name;

  O_RETURN_CODE := 0;
  O_RETURN_MSG  := '执行成功';

  -- ============================================================================
  -- 错误处理部分
  -- ============================================================================

EXCEPTION
  WHEN OTHERS THEN
    O_RETURN_CODE := -1;
    O_RETURN_MSG  := V_ERROR_MSG || '--行号:' || TO_CHAR(V_ERROR_LINE) ||
                     '||sqlcode:' || SQLCODE || '||sqlerrm:||' ||
                     SUBSTR(SQLERRM, 1, 200);
    ROLLBACK;
    V_ERROR_MSG  := O_RETURN_MSG;
    V_ERROR_CODE := O_RETURN_CODE;
    P_ERROR_LOG('admin',
                V_FUNCTION_NAME,
                V_ERROR_CODE,
                V_ERROR_MSG,
                '',
                '1',
                O_RETURN_MSG,
                O_RETURN_CODE);
END;

Create or Replace PROCEDURE "THJS"."P_TYNEWS_WIND_COMP" (RT_CURSOR  OUT TYPES.CURSORTYPE,
                                                    I_OBJ_NAME IN VARCHAR2,
                                                    --I_PAGE_NUM    IN NUMBER DEFAULT 0, --默认值0,
                                                    --I_PAGE_SIZE   IN NUMBER DEFAULT 0, --默认值0  如果I_PAGE_NUM，I_PAGE_SIZE都为0 则不分页，查询全部
                                                    --O_TOTAL_COUNT OUT INTEGER,
                                                    O_RETURN_MSG  OUT VARCHAR2,
                                                    O_RETURN_CODE OUT INTEGER) IS
  -------------------------------------------------------------------------------------
  -- COPYRIGHT          GTJA
  -- FUNC_ID            THJS.P_TYNEWS_WIND_COMP
  -- VERSION            1.0
  -- FUNC_NAME          WIND债券发行情况--公司简介
  -- FUNC_REMARK
  -- CREATE_DATE        2019-03-08
  -- CREATE_PROGRAMER   HAIYANG.XU
  -- MODIFY_REMARK
  -- MODIFY_DATE
  --==============================================================================
  --固定变量
  V_FUNCTION_NAME VARCHAR2(64) DEFAULT 'THJS.P_TYNEWS_WIND_COMP'; --存储过程名
  V_ERROR_MSG     VARCHAR2(1000); --返回信息
  V_ERROR_CODE    INTEGER;
  V_ERROR_LINE    INTEGER;
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  V_PAGE_NUM  NUMBER DEFAULT 0;
  V_PAGE_SIZE NUMBER;
  --=============================================================
  -- 业务处理过程
  --=============================================================

  --------------------------业务逻辑开始-----------------------------
BEGIN
  /*
   INSERT INTO THJS.T_TEST(C1,C2,C3,C4) VALUES(V_FUNCTION_NAME,I_OBJ_NAME,I_PAGE_NUM,I_PAGE_SIZE);
    COMMIT;
  */
  OPEN RT_CURSOR FOR
    SELECT B1.COMP_NAME, -- 公司名称
           B1.S_INFO_PROVINCE, -- 省份
           B1.S_INFO_CITY, -- 城市
           B1.S_INFO_CHAIRMAN, -- 法人代表
           B1.S_INFO_PRESIDENT, -- 总经理
           B1.S_INFO_BDSECRETARY, -- 董事会秘书
           B1.S_INFO_REGCAPITAL, -- 注册资本(万元)
           B1.S_INFO_FOUNDDATE, -- 成立日期
           B1.S_INFO_CHINESEINTRODUCTION, -- 公司中文简介
           B1.S_INFO_COMPTYPE, -- 公司类型
           B1.S_INFO_WEBSITE, -- 主页
           B1.S_INFO_EMAIL, -- 电子邮箱
           B1.S_INFO_OFFICE, -- 办公地址
           B1.ANN_DT, -- 公告日期
           B1.S_INFO_COUNTRY, -- 国籍
           B1.S_INFO_BUSINESSSCOPE, -- 经营范围
           B1.S_INFO_COMPANY_TYPE, -- 公司类别
           B1.S_INFO_TOTALEMPLOYEES, -- 员工总数(人)
           B1.S_INFO_MAIN_BUSINESS -- 主要产品及业务
    
      FROM ZX90.TCL_CBONDINTRODUCTION B1
     INNER JOIN ZX90.TCL_COMPINTRODUCTION C
        ON C.COMP_ID = B1.S_INFO_COMPCODE
     WHERE exists (SELECT 1
              FROM ZTGS.ENTERPRISEBASEINFOCOLLECT E --企业主体表
             WHERE E.PRIPID = I_OBJ_NAME
               and e.credit_code = C.REGISTERNUMBER);

  /*IF I_PAGE_NUM IS NOT NULL THEN
    V_PAGE_NUM := I_PAGE_NUM;
  END IF;
  
  --统计记录条数
  IF V_PAGE_NUM < 1 THEN
    SELECT COUNT(1)
      INTO O_TOTAL_COUNT
      FROM ZX90.TCL_CBONDINTRODUCTION B1
     inner join zx90.tcl_compintroduction c
        on c.comp_id = B1.S_INFO_COMPCODE
     WHERE exists (SELECT 1
              FROM ZTGS.ENTERPRISEBASEINFOCOLLECT E --企业主体表
             WHERE E.PRIPID = I_OBJ_NAME
               and e.credit_code = C.REGISTERNUMBER);
  END IF;
  
  IF I_PAGE_SIZE IS NOT NULL AND I_PAGE_SIZE <> 0 THEN
    V_PAGE_SIZE := I_PAGE_SIZE;
  ELSE
    V_PAGE_SIZE := O_TOTAL_COUNT;
  END IF;
  
  OPEN RT_CURSOR FOR
    SELECT B.COMP_NAME, -- 公司名称
           B.S_INFO_PROVINCE, -- 省份
           B.S_INFO_CITY, -- 城市
           B.S_INFO_CHAIRMAN, -- 法人代表
           B.S_INFO_PRESIDENT, -- 总经理
           B.S_INFO_BDSECRETARY, -- 董事会秘书
           B.S_INFO_REGCAPITAL, -- 注册资本(万元)
           B.S_INFO_FOUNDDATE, -- 成立日期
           B.S_INFO_CHINESEINTRODUCTION, -- 公司中文简介
           B.S_INFO_COMPTYPE, -- 公司类型
           B.S_INFO_WEBSITE, -- 主页
           B.S_INFO_EMAIL, -- 电子邮箱
           B.S_INFO_OFFICE, -- 办公地址
           B.ANN_DT, -- 公告日期
           B.S_INFO_COUNTRY, -- 国籍
           B.S_INFO_BUSINESSSCOPE, -- 经营范围
           B.S_INFO_COMPANY_TYPE, -- 公司类别
           B.S_INFO_TOTALEMPLOYEES, -- 员工总数(人)
           B.S_INFO_MAIN_BUSINESS -- 主要产品及业务
      FROM (SELECT A.*, ROWNUM AS RN
              FROM (SELECT B1.COMP_NAME, -- 公司名称
                           B1.S_INFO_PROVINCE, -- 省份
                           B1.S_INFO_CITY, -- 城市
                           B1.S_INFO_CHAIRMAN, -- 法人代表
                           B1.S_INFO_PRESIDENT, -- 总经理
                           B1.S_INFO_BDSECRETARY, -- 董事会秘书
                           B1.S_INFO_REGCAPITAL, -- 注册资本(万元)
                           B1.S_INFO_FOUNDDATE, -- 成立日期
                           B1.S_INFO_CHINESEINTRODUCTION, -- 公司中文简介
                           B1.S_INFO_COMPTYPE, -- 公司类型
                           B1.S_INFO_WEBSITE, -- 主页
                           B1.S_INFO_EMAIL, -- 电子邮箱
                           B1.S_INFO_OFFICE, -- 办公地址
                           B1.ANN_DT, -- 公告日期
                           B1.S_INFO_COUNTRY, -- 国籍
                           B1.S_INFO_BUSINESSSCOPE, -- 经营范围
                           B1.S_INFO_COMPANY_TYPE, -- 公司类别
                           B1.S_INFO_TOTALEMPLOYEES, -- 员工总数(人)
                           B1.S_INFO_MAIN_BUSINESS -- 主要产品及业务
                    
                      FROM ZX90.TCL_CBONDINTRODUCTION B1
                     INNER JOIN ZX90.TCL_COMPINTRODUCTION C
                        ON C.COMP_ID = B1.S_INFO_COMPCODE
                     WHERE exists
                     (SELECT 1
                              FROM ZTGS.ENTERPRISEBASEINFOCOLLECT E --企业主体表
                             WHERE E.PRIPID = I_OBJ_NAME
                               and e.credit_code = C.REGISTERNUMBER)
                    
                    ) A) B
     WHERE RN > V_PAGE_NUM
       AND RN <= V_PAGE_NUM + V_PAGE_SIZE;*/

  commit;

  O_RETURN_CODE := 0;
  O_RETURN_MSG  := '执行成功';

  -- ============================================================================
  -- 错误处理部分
  -- ============================================================================

EXCEPTION
  WHEN OTHERS THEN
    O_RETURN_CODE := -1;
    O_RETURN_MSG  := V_ERROR_MSG || '--行号:' || TO_CHAR(V_ERROR_LINE) ||
                     '||sqlcode:' || SQLCODE || '||sqlerrm:||' ||
                     SUBSTR(SQLERRM, 1, 200);
    ROLLBACK;
    V_ERROR_MSG  := O_RETURN_MSG;
    V_ERROR_CODE := O_RETURN_CODE;
    P_ERROR_LOG('admin',
                V_FUNCTION_NAME,
                V_ERROR_CODE,
                V_ERROR_MSG,
                '',
                '1',
                O_RETURN_MSG,
                O_RETURN_CODE);
END;

Create or Replace PROCEDURE "THJS"."P_TYNEWS_WIND_ISSU" (RT_CURSOR  OUT TYPES.CURSORTYPE,
                                                    I_OBJ_NAME IN VARCHAR2,
                                                    --I_PAGE_NUM       IN NUMBER DEFAULT 0, --默认值0,
                                                    --I_PAGE_SIZE      IN NUMBER DEFAULT 0, --默认值0  如果I_PAGE_NUM，I_PAGE_SIZE都为0 则不分页，查询全部
                                                    --O_TOTAL_COUNT    OUT INTEGER,
                                                    O_RETURN_MSG  OUT VARCHAR2,
                                                    O_RETURN_CODE OUT INTEGER) IS
  -------------------------------------------------------------------------------------
  -- COPYRIGHT          GTJA
  -- FUNC_ID            THJS.P_TYNEWS_WIND_ISSU
  -- VERSION            1.0
  -- FUNC_NAME          WIND债券发行情况
  -- FUNC_REMARK
  -- CREATE_DATE        2019-03-08
  -- CREATE_PROGRAMER   HAIYANG.XU
  -- MODIFY_REMARK
  -- MODIFY_DATE
  --==============================================================================
  --固定变量
  V_FUNCTION_NAME VARCHAR2(64) DEFAULT 'THJS.P_TYNEWS_WIND_ISSU'; --存储过程名
  V_ERROR_MSG     VARCHAR2(1000); --返回信息
