  V_ERROR_LINE    INTEGER;
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  V_PAGE_NUM  NUMBER DEFAULT 0;
  V_PAGE_SIZE NUMBER;
  --=============================================================
  -- 业务处理过程
  --=============================================================

  --------------------------业务逻辑开始-----------------------------
BEGIN
  /*
   INSERT INTO THJS.T_TEST(C1,C2,C3,C4) VALUES(V_FUNCTION_NAME,I_OBJ_NAME,I_PAGE_NUM,I_PAGE_SIZE);
    COMMIT;
  */
  OPEN RT_CURSOR FOR
    SELECT S_INFO_WINDCODE, -- WIND代码
           B_INFO_FULLNAME, -- 债券名称
           B_INFO_ISSUER, -- 发行人
           B_ISSUE_FIRSTISSUE, -- 发行起始日
           B_ISSUE_LASTISSUE, -- 发行截止日
           B_ISSUE_AMOUNTACT, -- 实际发行总量(亿元)
           B_INFO_ISSUEPRICE, -- 发行价格
           B_INFO_PAR, -- 面值
           B_INFO_MATURITYDATE, -- 到期日
           S_INFO_NAME, -- 债券简称
           S_INFO_EXCHMARKET, -- 交易所
           B_INFO_GUARANTOR, -- 担保人
           B_INFO_DELISTDATE, -- 退市日期
           ISSUE_OBJECT -- 发行对象
      FROM ZX90.TCL_CBONDDESCRIPTION A1
     INNER JOIN ZX90.TCL_COMPINTRODUCTION C
        ON C.COMP_ID = A1.B_INFO_ISSUERCODE
     WHERE C.REGISTERNUMBER =
           (SELECT E.CREDIT_CODE
              FROM ZTGS.ENTERPRISEBASEINFOCOLLECT E --企业主体表
             WHERE E.PRIPID = I_OBJ_NAME)
       AND A1.S_INFO_WINDCODE IN
           (SELECT T1.B_INFO_WINDCODE
              FROM ZX90.TCL_CBONDAGENCY T1
             WHERE T1.B_AGENCY_NAMEID = '2024680')
     ORDER BY A1.B_ISSUE_FIRSTISSUE DESC;

  /*IF I_PAGE_NUM IS NOT NULL THEN
    V_PAGE_NUM := I_PAGE_NUM;
  END IF;
  
  --统计记录条数
  IF V_PAGE_NUM < 1 THEN
    SELECT COUNT(1)
      INTO O_TOTAL_COUNT
      FROM ZX90.TCL_CBONDDESCRIPTION A1
   WHERE A1.B_INFO_ISSUERCODE = '1HRDE7433B'
     AND A1.S_INFO_WINDCODE IN
         (SELECT T1.B_INFO_WINDCODE
            FROM ZX90.TCL_CBONDAGENCY T1
           WHERE T1.B_AGENCY_NAMEID = '2024680')
    ;
  END IF;
  
  IF I_PAGE_SIZE IS NOT NULL AND I_PAGE_SIZE <> 0 THEN
    V_PAGE_SIZE := I_PAGE_SIZE;
  ELSE
    V_PAGE_SIZE := O_TOTAL_COUNT;
  END IF;
  
  OPEN RT_CURSOR FOR
    SELECT
           S_INFO_WINDCODE, -- WIND代码
           B_INFO_FULLNAME, -- 债券名称
           B_INFO_ISSUER, -- 发行人
           B_ISSUE_FIRSTISSUE, -- 发行起始日
           B_ISSUE_LASTISSUE, -- 发行截止日
           B_ISSUE_AMOUNTACT, -- 实际发行总量(亿元)
           B_INFO_ISSUEPRICE, -- 发行价格
           B_INFO_PAR, -- 面值
           B_INFO_MATURITYDATE, -- 到期日
           S_INFO_NAME, -- 债券简称
           S_INFO_EXCHMARKET, -- 交易所
           B_INFO_GUARANTOR, -- 担保人
           B_INFO_DELISTDATE, -- 退市日期
           ISSUE_OBJECT -- 发行对象
      FROM (SELECT A.*, ROWNUM AS RN
              FROM (
                       SELECT S_INFO_WINDCODE, -- WIND代码
                       B_INFO_FULLNAME, -- 债券名称
                       B_INFO_ISSUER, -- 发行人
                       B_ISSUE_FIRSTISSUE, -- 发行起始日
                       B_ISSUE_LASTISSUE, -- 发行截止日
                       B_ISSUE_AMOUNTACT, -- 实际发行总量(亿元)
                       B_INFO_ISSUEPRICE, -- 发行价格
                       B_INFO_PAR, -- 面值
                       B_INFO_MATURITYDATE, -- 到期日
                       S_INFO_NAME, -- 债券简称
                       S_INFO_EXCHMARKET, -- 交易所
                       B_INFO_GUARANTOR, -- 担保人
                       B_INFO_DELISTDATE, -- 退市日期
                       ISSUE_OBJECT -- 发行对象
                  FROM ZX90.TCL_CBONDDESCRIPTION A1
                 INNER JOIN ZX90.TCL_COMPINTRODUCTION C
                  ON C.COMP_ID = A1.B_INFO_ISSUERCODE
               WHERE C.REGISTERNUMBER = (SELECT E.CREDIT_CODE
                                           FROM ZTGS.ENTERPRISEBASEINFOCOLLECT E --企业主体表
                                          WHERE E.PRIPID = I_OBJ_NAME)
                   AND A1.S_INFO_WINDCODE IN
                           (SELECT T1.B_INFO_WINDCODE
                              FROM ZX90.TCL_CBONDAGENCY T1
                             WHERE T1.B_AGENCY_NAMEID = '2024680')
                 ORDER BY A1.B_ISSUE_FIRSTISSUE DESC
                                        ) A) B
     WHERE RN > V_PAGE_NUM
       AND RN <= V_PAGE_NUM + V_PAGE_SIZE;*/

  commit;

  O_RETURN_CODE := 0;
  O_RETURN_MSG  := '执行成功';

  -- ============================================================================
  -- 错误处理部分
  -- ============================================================================

EXCEPTION
  WHEN OTHERS THEN
    O_RETURN_CODE := -1;
    O_RETURN_MSG  := V_ERROR_MSG || '--行号:' || TO_CHAR(V_ERROR_LINE) ||
                     '||sqlcode:' || SQLCODE || '||sqlerrm:||' ||
                     SUBSTR(SQLERRM, 1, 200);
    ROLLBACK;
    V_ERROR_MSG  := O_RETURN_MSG;
    V_ERROR_CODE := O_RETURN_CODE;
    P_ERROR_LOG('admin',
                V_FUNCTION_NAME,
                V_ERROR_CODE,
                V_ERROR_MSG,
                '',
                '1',
                O_RETURN_MSG,
                O_RETURN_CODE);
END;

Create or Replace PROCEDURE "THJS"."P_TYNEWS_YULUN_CXXX" (RT_CURSOR     OUT TYPES.CURSORTYPE,
                                                     I_OBJ_NAME    IN VARCHAR2,
                                                     I_PAGE_NUM    IN NUMBER DEFAULT 0, --默认值0,
                                                     I_PAGE_SIZE   IN NUMBER DEFAULT 0, --默认值0  如果I_PAGE_NUM，I_PAGE_SIZE都为0 则不分页，查询全部
                                                     O_TOTAL_COUNT OUT INTEGER,
                                                     O_RETURN_MSG  OUT VARCHAR2,
                                                     O_RETURN_CODE OUT INTEGER) IS
  -------------------------------------------------------------------------------------
  -- COPYRIGHT          GTJA
  -- FUNC_ID            THJS.P_TYNEWS_YULUN_CXXX
  -- VERSION            1.0
  -- FUNC_NAME          舆论信息 -- 诚信信息
  -- FUNC_REMARK
  -- CREATE_DATE        2019-01-17
  -- CREATE_PROGRAMER   HAIYANG.XU
  -- MODIFY_REMARK
  -- MODIFY_DATE
  --==============================================================================
  --固定变量
  V_FUNCTION_NAME VARCHAR2(64) DEFAULT 'THJS.P_TYNEWS_YULUN_CXXX'; --存储过程名
  V_ERROR_MSG     VARCHAR2(1000); --返回信息
  V_ERROR_CODE    INTEGER;
  V_ERROR_LINE    INTEGER;
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  V_PAGE_NUM  NUMBER DEFAULT 0;
  V_PAGE_SIZE NUMBER;

  v_regno   varchar2(100);
  v_entname varchar2(500);
  --=============================================================
  -- 业务处理过程
  --=============================================================

  --------------------------业务逻辑开始-----------------------------
BEGIN
  /*
   INSERT INTO THJS.T_TEST(C1,C2,C3,C4) VALUES(V_FUNCTION_NAME,I_OBJ_NAME,I_PAGE_NUM,I_PAGE_SIZE);
    COMMIT;
  */
  select e.regno, e.entname
    into v_regno, v_entname
    from ztgs.enterprisebaseinfocollect e --企业主体表
   where e.pripid = I_OBJ_NAME;

  IF I_PAGE_NUM IS NOT NULL THEN
    V_PAGE_NUM := I_PAGE_NUM;
  END IF;

  --统计记录条数
  IF V_PAGE_NUM < 1 THEN
    SELECT COUNT(1)
      INTO O_TOTAL_COUNT
      FROM (SELECT IT0026_001,
                   IT0026_002,
                   IT0026_005,
                   TO_CHAR(IT0026_006, 'YYYYMMDD') IT0026_006,
                   TO_CHAR(ENTRYDT, 'YYYYMMDD') ENTRYDT,
                   --ID,
                   FLAG,
                   it0026_015
              FROM CHYQ.TIT0026_1 T
             WHERE t.IT0026_015 is not null
               and T.IT0026_004 =
                   (SELECT C.COMPCODE
                      FROM CHYQ.TQ_COMP_INFO C --机构资料表
                     WHERE C.COMPNAME = v_entname
                        OR C.BIZLICENSENO = v_regno)
            UNION
            SELECT IT0026_001,
                   IT0026_002,
                   IT0026_005,
                   TO_CHAR(IT0026_006, 'YYYYMMDD') IT0026_006,
                   TO_CHAR(ENTRYDT, 'YYYYMMDD') ENTRYDT,
                   --ID,
                   FLAG,
                   it0026_032
              FROM CHYQ.TIT0026_3 T1
             WHERE t1.IT0026_032 is not null
               and T1.IT0026_005 =
                   (SELECT C.Compname
                      FROM CHYQ.TQ_COMP_INFO C --机构资料表
                     WHERE C.COMPNAME = v_entname
                        OR C.BIZLICENSENO = v_regno));
  END IF;

  IF I_PAGE_SIZE IS NOT NULL AND I_PAGE_SIZE <> 0 THEN
    V_PAGE_SIZE := I_PAGE_SIZE;
  ELSE
    V_PAGE_SIZE := O_TOTAL_COUNT;
  END IF;

  OPEN RT_CURSOR FOR
    SELECT IT0026_001,
           IT0026_002,
           IT0026_005,
           IT0026_007,
           IT0026_006,
           ENTRYDT,
           ID as it0026_id,
           FLAG,
           IT0026_015
      FROM (SELECT A.*, ROWNUM AS RN
              FROM (SELECT IT0026_001,
                           IT0026_002,
                           IT0026_005,
                           IT0026_007,
                           TO_CHAR(IT0026_006, 'YYYYMMDD') IT0026_006,
                           TO_CHAR(ENTRYDT, 'YYYYMMDD') ENTRYDT,
                           ID,
                           FLAG,
                           it0026_015
                      FROM CHYQ.TIT0026_1 T
                     WHERE t.IT0026_015 is not null
                       and T.IT0026_004 =
                           (SELECT C.COMPCODE
                              FROM CHYQ.TQ_COMP_INFO C --机构资料表
                             WHERE C.COMPNAME = v_entname
                                OR C.BIZLICENSENO = v_regno)
                    UNION
                    SELECT IT0026_001,
                           IT0026_002,
                           IT0026_005,
                           case
                             when IT0026_009 is null then
                              IT0026_008
                             else
                              IT0026_009
                           end as IT0026_007,
                           TO_CHAR(IT0026_006, 'YYYYMMDD') IT0026_006,
                           TO_CHAR(ENTRYDT, 'YYYYMMDD') ENTRYDT,
                           ID,
                           FLAG,
                           it0026_032
                      FROM CHYQ.TIT0026_3 T1
                     WHERE t1.IT0026_032 is not null
                       and T1.IT0026_005 =
                           (SELECT C.Compname
                              FROM CHYQ.TQ_COMP_INFO C --机构资料表
                             WHERE C.COMPNAME = v_entname
                                OR C.BIZLICENSENO = v_regno)
                     ORDER BY IT0026_006 DESC) A) B
     WHERE RN > V_PAGE_NUM
       AND RN <= V_PAGE_NUM + V_PAGE_SIZE;
  O_RETURN_CODE := 0;
  O_RETURN_MSG  := '执行成功';

  -- ============================================================================
  -- 错误处理部分
  -- ============================================================================

EXCEPTION
  WHEN OTHERS THEN
    O_RETURN_CODE := -1;
    O_RETURN_MSG  := V_ERROR_MSG || '--行号:' || TO_CHAR(V_ERROR_LINE) ||
                     '||sqlcode:' || SQLCODE || '||sqlerrm:||' ||
                     SUBSTR(SQLERRM, 1, 200);
    ROLLBACK;
    V_ERROR_MSG  := O_RETURN_MSG;
    V_ERROR_CODE := O_RETURN_CODE;
    P_ERROR_LOG('admin',
                V_FUNCTION_NAME,
                V_ERROR_CODE,
                V_ERROR_MSG,
                '',
                '1',
                O_RETURN_MSG,
                O_RETURN_CODE);
END;

Create or Replace PROCEDURE "THJS"."P_TYNEWS_YULUN_CXXX_D" (RT_CURSOR     OUT TYPES.CURSORTYPE,
                                                       I_OBJ_NAME    IN VARCHAR2,
                                                       --I_EVE_CODE    IN VARCHAR2,
                                                       O_RETURN_MSG  OUT VARCHAR2,
                                                       O_RETURN_CODE OUT INTEGER) IS
  -------------------------------------------------------------------------------------
  -- COPYRIGHT          GTJA
  -- FUNC_ID            THJS.P_TYNEWS_YULUN_CXXX
  -- VERSION            1.0
  -- FUNC_NAME          舆论信息 -- 诚信信息_详情
  -- FUNC_REMARK
  -- CREATE_DATE        2019-04-15
  -- CREATE_PROGRAMER   HAIYANG.XU
  -- MODIFY_REMARK
  -- MODIFY_DATE
  --==============================================================================
  --固定变量
  V_FUNCTION_NAME VARCHAR2(64) DEFAULT 'THJS.P_TYNEWS_YULUN_CXXX_D'; --存储过程名
