  /*
   INSERT INTO THJS.T_TEST(C1,C2,C3,C4) VALUES(V_FUNCTION_NAME,I_OBJ_NAME,I_PAGE_NUM,I_PAGE_SIZE);
    COMMIT;
  */




  OPEN RT_CURSOR FOR
    SELECT IT0026_001,
           IT0026_002,
           IT0026_005,
           IT0026_006,
           ENTRYDT,
           --ID,
           FLAG,
           IT0026_015
              FROM (SELECT IT0026_001,
                           IT0026_002,
                           IT0026_005,
                           TO_CHAR(IT0026_006, 'YYYYMMDD') IT0026_006,
                           TO_CHAR(ENTRYDT, 'YYYYMMDD') ENTRYDT,
