                             WHERE C.COMPNAME =
                                   (select e.entname
                                      from ztgs.enterprisebaseinfocollect e --企业主体表
                                     where e.pripid = I_OBJ_NAME)
                                OR C.BIZLICENSENO = '19000101')
                                */
                    UNION
                    SELECT IT0026_001,
                           IT0026_002,
                           IT0026_005,
                           TO_CHAR(IT0026_006, 'YYYYMMDD') IT0026_006,
                           TO_CHAR(ENTRYDT, 'YYYYMMDD') ENTRYDT,
                           ID,
                           FLAG,
                           it0026_032
                      FROM CHYQ.TIT0026_3 T1
                     WHERE t1.IT0026_032 is not null
                     /*
                       and T1.IT0026_005 =
                           (SELECT C.Compname
                              FROM CHYQ.TQ_COMP_INFO C --机构资料表
                             WHERE C.COMPNAME =
                                   (select e.entname
                                      from ztgs.enterprisebaseinfocollect e --企业主体表
                                     where e.pripid = I_OBJ_NAME)
                                OR C.BIZLICENSENO = '19000101')
                                */
                     ORDER BY IT0026_006 DESC) A
     WHERE A.ID = I_OBJ_NAME;
  O_RETURN_CODE := 0;
  O_RETURN_MSG  := '执行成功';

  -- ============================================================================
  -- 错误处理部分
  -- ============================================================================

EXCEPTION
  WHEN OTHERS THEN
    O_RETURN_CODE := -1;
    O_RETURN_MSG  := V_ERROR_MSG || '--行号:' || TO_CHAR(V_ERROR_LINE) ||
                     '||sqlcode:' || SQLCODE || '||sqlerrm:||' ||
                     SUBSTR(SQLERRM, 1, 200);
    ROLLBACK;
    V_ERROR_MSG  := O_RETURN_MSG;
    V_ERROR_CODE := O_RETURN_CODE;
    P_ERROR_LOG('admin',
                V_FUNCTION_NAME,
                V_ERROR_CODE,
                V_ERROR_MSG,
                '',
                '1',
                O_RETURN_MSG,
                O_RETURN_CODE);
END;

Create or Replace PROCEDURE "THJS"."P_TYNEWS_YULUN_HYNEWS" (RT_CURSOR     OUT TYPES.CURSORTYPE,
                                                       I_OBJ_NAME    IN VARCHAR2,
                                                       I_PAGE_NUM    IN NUMBER DEFAULT 0, --默认值0,
                                                       I_PAGE_SIZE   IN NUMBER DEFAULT 0, --默认值0  如果I_PAGE_NUM，I_PAGE_SIZE都为0 则不分页，查询全部
                                                       O_TOTAL_COUNT OUT INTEGER,
                                                       O_RETURN_MSG  OUT VARCHAR2,
                                                       O_RETURN_CODE OUT INTEGER) IS
  -------------------------------------------------------------------------------------
  -- COPYRIGHT          GTJA
  -- FUNC_ID            THJS.P_TYNEWS_YULUN_HYNEWS
  -- VERSION            1.0
  -- FUNC_NAME          舆论信息 -- 行业新闻
  -- FUNC_REMARK
  -- CREATE_DATE        2019-01-28
  -- CREATE_PROGRAMER   HAIYANG.XU
  -- MODIFY_REMARK
  -- MODIFY_DATE
  --==============================================================================
  --固定变量
  V_FUNCTION_NAME VARCHAR2(64) DEFAULT 'THJS.P_TYNEWS_YULUN_HYNEWS'; --存储过程名
  V_ERROR_MSG     VARCHAR2(1000); --返回信息
  V_ERROR_CODE    INTEGER;
  V_ERROR_LINE    INTEGER;
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  V_PAGE_NUM  NUMBER DEFAULT 0;
  V_PAGE_SIZE NUMBER;

  v_regno   varchar2(100);
  v_entname varchar2(500);
  --=============================================================
  -- 业务处理过程
  --=============================================================

  --------------------------业务逻辑开始-----------------------------
BEGIN
  /*
   INSERT INTO THJS.T_TEST(C1,C2,C3,C4) VALUES(V_FUNCTION_NAME,I_OBJ_NAME,I_PAGE_NUM,I_PAGE_SIZE);
    COMMIT;
  */
  select e.regno, e.entname
    into v_regno, v_entname
    from ztgs.enterprisebaseinfocollect e --企业主体表
   where e.pripid = I_OBJ_NAME;

  --缓存当前主体财汇舆情行业分类
  execute immediate 'truncate table thjs.tmp_chyq_comp_industry';
  insert into thjs.tmp_chyq_comp_industry
    (compcode, mindustryid, level1id, level1name, pripid)
    select distinct c.compcode,
                    m.mindustryid,
                    ci.level1id,
                    ci.level1name,
                    I_OBJ_NAME
      from CHYQ.TQ_COMP_INDUSTRY ci --行业分类表
     inner join CHYQ.T_IND_MAPPING m --行业对照表
        on m.standard = ci.indclasscode
       and m.industryid = ci.level1id
     inner join chyq.tq_comp_info c
        on c.compcode = ci.compcode
     where (c.bizlicenseno = v_regno or c.compname = v_entname);
  commit;

  --排序查询太慢，插入临时结果表后再排序
  execute immediate 'truncate table thjs.tmp_chyq_news_text_ind';
  insert into thjs.tmp_chyq_news_text_ind
    SELECT T.NEWSCODE, --新闻编码
           T.NEWSTITLE, --新闻标题
           T.NEWSLINK, --新闻链接
           --T.PUBLISHTIME,
           TO_CHAR(T.PUBLISHTIME, 'YYYYMMDD') PUBLISHTIME, --新闻发布时间
           T.NEWSSOURCEID, --新闻来源编码
           T.NEWSSOURCE, --新闻来源
           T.NEWSAUTHOR, --新闻作者
           T.STATUS, --状态
           -- T.UPDATETIME,
           -- T.ENTRYDATE,
           TO_CHAR(T.UPDATETIME, 'YYYYMMDD') UPDATETIME, --更新时间
           TO_CHAR(T.ENTRYDATE, 'YYYYMMDD') ENTRYDATE, --录入日期
           T.ENTRYTIME, --录入时间
           T.TMSTAMP, --时间戳
           T.ISVALID --是否有效
      FROM CHYQ.T_NEWS_TEXT_IND T --新闻主表（行业）
     inner join CHYQ.T_NEWS_IND b --新闻行业表
        on b.newscode = t.newscode
     where t.isvalid = 1 --有效
       and t.status = 1 --正常
       and t.newslink is not null
       and t.publishtime > add_months(sysdate, -1) --数据量太大，暂取1个月舆情
       and exists (select 1
              from thjs.tmp_chyq_comp_industry m
             where m.mindustryid = b.industrycode);
  commit;

  IF I_PAGE_NUM IS NOT NULL THEN
    V_PAGE_NUM := I_PAGE_NUM;
  END IF;

  --统计记录条数
  IF V_PAGE_NUM < 1 THEN
    SELECT COUNT(1) INTO O_TOTAL_COUNT FROM thjs.tmp_chyq_news_text_ind;
  END IF;

  IF I_PAGE_SIZE IS NOT NULL AND I_PAGE_SIZE <> 0 THEN
    V_PAGE_SIZE := I_PAGE_SIZE;
  ELSE
    V_PAGE_SIZE := O_TOTAL_COUNT;
  END IF;

  OPEN RT_CURSOR FOR
    SELECT B.NEWSCODE, --新闻编码
           B.NEWSTITLE, --新闻标题
           B.NEWSLINK, --新闻链接
           B.PUBLISHTIME, --新闻发布时间
           B.NEWSSOURCEID, --新闻来源编码
           B.NEWSSOURCE, --新闻来源
           B.NEWSAUTHOR, --新闻作者
           B.STATUS, --状态
           B.UPDATETIME, --更新时间
           B.ENTRYDATE, --录入日期
           B.ENTRYTIME, --录入时间
           B.TMSTAMP, --时间戳
           B.ISVALID --是否有效
      FROM (SELECT A.*, ROWNUM AS RN
              FROM (SELECT T.NEWSCODE, --新闻编码
                           T.NEWSTITLE, --新闻标题
                           T.NEWSLINK, --新闻链接
                           T.PUBLISHTIME, --新闻发布时间
                           T.NEWSSOURCEID, --新闻来源编码
                           T.NEWSSOURCE, --新闻来源
                           T.NEWSAUTHOR, --新闻作者
                           T.STATUS, --状态
                           T.UPDATETIME, --更新时间
                           T.ENTRYDATE, --录入日期
                           T.ENTRYTIME, --录入时间
                           T.TMSTAMP, --时间戳
                           T.ISVALID --是否有效
                      FROM thjs.tmp_chyq_news_text_ind t
                     ORDER BY T.PUBLISHTIME DESC) A) B
     WHERE RN > V_PAGE_NUM
       AND RN <= V_PAGE_NUM + V_PAGE_SIZE;
  O_RETURN_CODE := 0;
  O_RETURN_MSG  := '执行成功';

  -- ============================================================================
  -- 错误处理部分
  -- ============================================================================

EXCEPTION
  WHEN OTHERS THEN
    O_RETURN_CODE := -1;
    O_RETURN_MSG  := V_ERROR_MSG || '--行号:' || TO_CHAR(V_ERROR_LINE) ||
                     '||sqlcode:' || SQLCODE || '||sqlerrm:||' ||
                     SUBSTR(SQLERRM, 1, 200);
    ROLLBACK;
    V_ERROR_MSG  := O_RETURN_MSG;
    V_ERROR_CODE := O_RETURN_CODE;
    P_ERROR_LOG('admin',
                V_FUNCTION_NAME,
                V_ERROR_CODE,
                V_ERROR_MSG,
                '',
                '1',
                O_RETURN_MSG,
                O_RETURN_CODE);
END;

Create or Replace PROCEDURE "THJS"."P_TYNEWS_YULUN_NEWS" (RT_CURSOR     OUT TYPES.CURSORTYPE,
                                                     I_OBJ_NAME    IN VARCHAR2,
                                                     I_PAGE_NUM    IN NUMBER DEFAULT 0, --默认值0,
                                                     I_PAGE_SIZE   IN NUMBER DEFAULT 0, --默认值0  如果I_PAGE_NUM，I_PAGE_SIZE都为0 则不分页，查询全部
                                                     O_TOTAL_COUNT OUT INTEGER,
                                                     O_RETURN_MSG  OUT VARCHAR2,
                                                     O_RETURN_CODE OUT INTEGER) IS
  -------------------------------------------------------------------------------------
  -- COPYRIGHT          GTJA
  -- FUNC_ID            THJS.P_TYNEWS_YULUN_NEWS
  -- VERSION            1.0
  -- FUNC_NAME          舆论信息 -- 新闻公告 (负面新闻)
  -- FUNC_REMARK
  -- CREATE_DATE        2019-01-17
  -- CREATE_PROGRAMER   HAIYANG.XU
  -- MODIFY_REMARK
  -- MODIFY_DATE
  --==============================================================================
  --固定变量
  V_FUNCTION_NAME VARCHAR2(64) DEFAULT 'THJS.P_TYNEWS_YULUN_NEWS'; --存储过程名
  V_ERROR_MSG     VARCHAR2(1000); --返回信息
  V_ERROR_CODE    INTEGER;
  V_ERROR_LINE    INTEGER;
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  V_PAGE_NUM  NUMBER DEFAULT 0;
  V_PAGE_SIZE NUMBER;

  v_regno   varchar2(100);
  v_entname varchar2(500);
  --=============================================================
  -- 业务处理过程
  --=============================================================

  --------------------------业务逻辑开始-----------------------------
BEGIN
  /*
   INSERT INTO THJS.T_TEST(C1,C2,C3,C4) VALUES(V_FUNCTION_NAME,I_OBJ_NAME,I_PAGE_NUM,I_PAGE_SIZE);
    COMMIT;
  */

  select e.regno, e.entname
    into v_regno, v_entname
    from ztgs.enterprisebaseinfocollect e --企业主体表
   where e.pripid = I_OBJ_NAME;

  IF I_PAGE_NUM IS NOT NULL THEN
    V_PAGE_NUM := I_PAGE_NUM;
  END IF;

  --统计记录条数
  IF V_PAGE_NUM < 1 THEN
    SELECT COUNT(1)
      INTO O_TOTAL_COUNT
      FROM CHYQ.T_NEWS_TEXT_FCDB T
     WHERE t.isvalid = 1 --有效
       and not (t.newslinkhd is null and t.newslink is null)
       and exists
     (select 1
              from CHYQ.T_NEWS_COMPANY_FCDB cf
             inner join chyq.tq_comp_info c
                on c.compcode = cf.compcode
             where (c.bizlicenseno = v_regno or c.compname = v_entname)
               and cf.newscodehd = t.newscodehd);
  END IF;

  IF I_PAGE_SIZE IS NOT NULL AND I_PAGE_SIZE <> 0 THEN
    V_PAGE_SIZE := I_PAGE_SIZE;
  ELSE
    V_PAGE_SIZE := O_TOTAL_COUNT;
  END IF;

  /*
   SELECT A.*
   FROM CHYQ.T_NEWS_TEXT_FCDB A --新闻主表（新版负面）
  INNER JOIN CHYQ.T_NEWS_COMPANY_FCDB B --新闻机构表（新版负面）
     ON B.NEWSCODE = A.NEWSCODE
  WHERE B.COMPCODE =
        (SELECT C.COMPCODE
           FROM CHYQ.TQ_COMP_INFO C --机构资料表
          WHERE C.COMPNAME = '上海临港控股股份有限公司'
             OR C.BIZLICENSENO = '310000400099813')
   */

  OPEN RT_CURSOR FOR
    SELECT B.ID,
           B.NEWSCODE,
           B.PUBLISHTIME,
           B.PUBLISHDATE,
           B.NEWSTITLE,
           B.NEWSLINK,
           B.NEWSSOURCEID,
           B.NEWSSOURCE,
           B.NEWSAUTHOR,
           B.NEWSSOURCETABLE,
           B.FINSERTTIME,
           B.FINSERTDATE,
           B.ISVALID,
           B.TMSTAMP,
           B.ENTRYDATE,
           B.ENTRYTIME,
           B.NEWSCODEHD,
           B.NEWSLINKHD
      FROM (SELECT A.*, ROWNUM AS RN
              FROM (SELECT T.ID,
                           T.NEWSCODE,
                           TO_CHAR(T.PUBLISHTIME, 'YYYYMMDD') PUBLISHTIME,
                           T.PUBLISHDATE,
                           T.NEWSTITLE,
                           T.NEWSLINK,
                           T.NEWSSOURCEID,
                           T.NEWSSOURCE,
                           T.NEWSAUTHOR,
                           T.NEWSSOURCETABLE,
                           TO_CHAR(T.FINSERTTIME, 'YYYYMMDD') FINSERTTIME,
                           T.FINSERTDATE,
                           T.ISVALID,
                           T.TMSTAMP,
                           TO_CHAR(T.ENTRYDATE, 'YYYYMMDD') ENTRYDATE,
                           T.ENTRYTIME,
                           T.NEWSCODEHD,
                           T.NEWSLINKHD
                      FROM CHYQ.T_NEWS_TEXT_FCDB T
                     WHERE t.isvalid = 1 --有效
                       and not (t.newslinkhd is null and t.newslink is null)
                       and exists
                     (select 1
                              from CHYQ.T_NEWS_COMPANY_FCDB cf
                             inner join chyq.tq_comp_info c
                                on c.compcode = cf.compcode
                             where (c.bizlicenseno = v_regno or
                                   c.compname = v_entname)
                               and cf.newscodehd = t.newscodehd)
                     ORDER BY t.publishtime DESC) A) B
     WHERE RN > V_PAGE_NUM
       AND RN <= V_PAGE_NUM + V_PAGE_SIZE;
  O_RETURN_CODE := 0;
  O_RETURN_MSG  := '执行成功';

  -- ============================================================================
  -- 错误处理部分
  -- ============================================================================

EXCEPTION
  WHEN OTHERS THEN
    O_RETURN_CODE := -1;
    O_RETURN_MSG  := V_ERROR_MSG || '--行号:' || TO_CHAR(V_ERROR_LINE) ||
                     '||sqlcode:' || SQLCODE || '||sqlerrm:||' ||
                     SUBSTR(SQLERRM, 1, 200);
    ROLLBACK;
    V_ERROR_MSG  := O_RETURN_MSG;
    V_ERROR_CODE := O_RETURN_CODE;
    P_ERROR_LOG('admin',
                V_FUNCTION_NAME,
                V_ERROR_CODE,
                V_ERROR_MSG,
                '',
                '1',
                O_RETURN_MSG,
                O_RETURN_CODE);
END;

Create or Replace PROCEDURE "THJS"."P_USER_FOCUS" (i_tradedate in char)
/*==============================================================================
  版 本    : 1.0.0
  创建人   : czc
  模块编号 : 0
  日 期    : 2019-03-21
  功能描述 : 投行数据集市 投行系统 业务人员关注公司政通工商映射落地
  ==============================================================================*/
 as
  v_sqlcode  integer default 0;
  v_sqlstate char(5) default '';
  --v_errcode        integer default 0;
  --v_errstate       char(5) default '';
  v_err_msg varchar2(128) default '';
  --v_not_found      integer default 0;
  --v_last_time      char(8);
  v_function_id    integer default 0; --定义存储过程模块编号
  v_error_line_num integer default 0; --错误行号
  --v_error_level    integer default 0; --错误级别
  v_function_desc varchar2(50) default '业务人员关注公司政通工商映射落地'; --功能描述
  v_program_name  char(40) default 'p_user_focus'; --程序名
  v_pr_task_id    number default 0; --任务标示
  -- =======================================================================================================================
  -- 定义业务变量
  -- =======================================================================================================================
  -- =======================================================================================================================
  -- 业务开始
  -- =======================================================================================================================
begin

  delete from thjs.tb_user_focus;

  --每日初始化
  insert into thjs.tb_user_focus
    (workno,
     username,
     empname,
     khname,
     khxycode,
     pripid,
     entname,
     regno,
     eid)
    select distinct t.workno,
                    t.username,
                    t.empname,
                    t.khname,
                    t.khxycode,
                    t.pripid,
                    t.entname,
                    t.regno,
                    t.eid
      from thjs.vw_user_project t
    union all
    select to_char(u.labor),
           to_char(u.user_code),
           to_char(u.user_name),
           '@ALL' as khname,
           '' as khxycode,
           '@ALL' as pripid,
           '' as entname,
           '' as regno,
           '' as eid
      from core.tb_user u
     where u.user_code in ('admin', 'zhangqilong');

  commit;

  --深度匹配

  update thjs.tb_user_focus f
     set (f.pripid, f.entname, f.regno, f.eid) =
         (select x.pripid, x.entname, x.regno, x.eid
            from (select x.*,
                         row_number() over(partition by x.entname order by x.id desc) as rn
                    from ztgs.enterprisebaseinfocollect x) x
           where x.entname = f.khname
             and x.rn = 1)
   where f.pripid is null;

  commit;

  ------------------------
exception
  when others then
    v_sqlcode := -1 * sqlcode;
    v_err_msg := sqlerrm;
    rollback;
    --记录错误日志
    kingstar.pr_audit_write_errlog(v_pr_task_id, -- 任务标识
                                   0, -- 单位编号
                                   i_tradedate, -- 业务日期
                                   v_function_id, -- 功能标识
                                   v_program_name, -- 程序名
                                   v_error_line_num, -- 程序行号
                                   v_err_msg, -- 错误信息
                                   v_sqlcode, -- SQLCODE
                                   v_sqlstate -- SQLSTATE
                                   );
    commit;
    raise;
end;

Create or Replace PROCEDURE "THJS"."P_USER_PROJECT" (i_tradedate in char)
/*==============================================================================
  版 本    : 1.0.0
  创建人   : czc
  模块编号 : 0
  日 期    : 2019-03-23
  功能描述 : 投行数据集市 投行系统 业务人员项目信息-客户政通工商映射落地
  ==============================================================================*/
 as
  v_sqlcode  integer default 0;
  v_sqlstate char(5) default '';
  --v_errcode        integer default 0;
  --v_errstate       char(5) default '';
  v_err_msg varchar2(128) default '';
  --v_not_found      integer default 0;
  --v_last_time      char(8);
  v_function_id    integer default 0; --定义存储过程模块编号
  v_error_line_num integer default 0; --错误行号
  --v_error_level    integer default 0; --错误级别
  v_function_desc varchar2(50) default '业务人员项目信息'; --功能描述
  v_program_name  char(40) default 'p_user_project'; --程序名
  v_pr_task_id    number default 0; --任务标示
  -- =======================================================================================================================
  -- 定义业务变量
  -- =======================================================================================================================
  v_count integer default 0;
  -- =======================================================================================================================
  -- 业务开始
  -- =======================================================================================================================
begin

  /**
  完善更新逻辑：
  1.每日增量更新记录数据，全量更新除projid外的其他数据
  2.全量更新工商主体信息相关字段
  3.股票代码名称，因涉及数据推送，不做全量更新，只更新存在且有变化的数据
  **/

  --投行客户项目信息-对接工商主体落地
  select count(1) into v_count from thjs.vw_thdb_cust_info c;

  if v_count > 0 then
  
    --增量更新记录数
    delete from thjs.tb_thdb_cust_info c
     where not exists
     (select 1 from thjs.vw_thdb_cust_info t where t.projid = c.projid);
  
    commit;
  
    insert into thjs.tb_thdb_cust_info
      (khname,
       projid,
       projname,
       projtype,
       projphase,
       islx,
       khxycode,
       assdeptcode,
       assdeptname,
       deptmanacode,
       deptmananame,
       deptmanamobile,
       deptname,
       deptcode)
      select *
        from thjs.vw_thdb_cust_info c
       where not exists (select 1
                from thjs.tb_thdb_cust_info t
               where t.projid = c.projid);
    commit;
  
    --全量更新其他字段
    merge into thjs.tb_thdb_cust_info c
    using (select u.khname,
                  u.projid,
                  u.projname,
                  u.projtype,
                  u.projphase,
                  u.islx,
                  u.khxycode,
                  u.assdeptcode,
                  u.assdeptname,
                  u.deptmanacode,
                  u.deptmananame,
                  u.deptmanamobile,
                  u.deptname,
                  u.deptcode,
                  x.pripid,
                  x.entname,
                  x.regno,
                  x.eid,
                  x.credit_code
             from thjs.vw_thdb_cust_info u
             left join (select x.*,
                              row_number() over(partition by x.credit_code order by x.id desc) as rn
                         from ztgs.enterprisebaseinfocollect x) x
               on x.credit_code = u.khxycode
              and x.rn = 1) u
    on (u.projid = c.projid)
    when matched then
      update
         set c.khname         = u.khname,
             c.projname       = u.projname,
             c.projtype       = u.projtype,
             c.projphase      = u.projphase,
             c.islx           = u.islx,
             c.khxycode       = u.khxycode,
             c.assdeptcode    = u.assdeptcode,
             c.assdeptname    = u.assdeptname,
             c.deptmanacode   = u.deptmanacode,
             c.deptmananame   = u.deptmananame,
             c.deptmanamobile = u.deptmanamobile,
             c.deptname       = u.deptname,
             c.deptcode       = u.deptcode,
             c.pripid         = u.pripid,
             c.entname        = u.entname,
             c.regno          = u.regno,
             c.eid            = u.eid,
             c.credit_code    = u.credit_code,
             c.gen_time       = sysdate;
  
  end if;

  --全名
  update thjs.tb_thdb_cust_info c
     set (c.pripid, c.entname, c.regno, c.eid, c.credit_code) =
         (select x.pripid, x.entname, x.regno, x.eid, x.credit_code
            from (select x.*,
                         row_number() over(partition by x.entname order by x.id desc) as rn
                    from ztgs.enterprisebaseinfocollect x) x
           where x.entname =
                 (replace(replace(c.khname, '(', '（'), ')', '）'))
             and x.rn = 1)
   where c.pripid is null;
  commit;

  --客户名称修正
  update thjs.tb_thdb_cust_info c
     set c.khname_xz = nvl((select x.khname_xz
                             from thjs.tb_project_khname_xz x
                            where x.khname = c.khname),
                           c.khname_xz)
   where c.pripid is null;
  commit;
  update thjs.tb_thdb_cust_info c
     set (c.khxycode, c.pripid, c.entname, c.regno, c.eid, c.credit_code) =
         (select coalesce(c.khxycode, x.credit_code) as khxycode,
                 x.pripid,
                 x.entname,
                 x.regno,
                 x.eid,
                 x.credit_code
            from (select x.*,
                         row_number() over(partition by x.entname order by x.id desc) as rn
                    from ztgs.enterprisebaseinfocollect x) x
           where x.entname = c.khname_xz
             and x.rn = 1)
   where c.pripid is null;
  commit;

  --股票股票代码，名称匹配； 证券代码使用wind证券代码
  --使用统一社会信用代码匹配
  merge into thjs.tb_thdb_cust_info t
  using (select u.projid,
                nvl(s.s_info_code, u.stockcode) as stockcode,
                nvl(s.s_info_name, u.stockname) as stockname
           from thjs.tb_thdb_cust_info u
           left join zx90.tcl_compintroduction c
             on c.registernumber = u.khxycode
          inner join zx90.vw_wdzx_asharedescription s
             on s.s_info_compcode = c.comp_id) u
  on (t.projid = u.projid)
  when matched then
    update set t.stockcode = u.stockcode, t.stockname = u.stockname;
  commit;

  --使用公司名称匹配
  merge into thjs.tb_thdb_cust_info t
  using (select u.projid,
                nvl(s.s_info_code, u.stockcode) as stockcode,
                nvl(s.s_info_name, u.stockname) as stockname
           from thjs.tb_thdb_cust_info u
           left join zx90.tcl_compintroduction c
             on c.comp_name = u.khname
          inner join zx90.vw_wdzx_asharedescription s
             on s.s_info_compcode = c.comp_id
          where u.stockcode is null) u
  on (t.projid = u.projid)
  when matched then
    update set t.stockcode = u.stockcode, t.stockname = u.stockname;

  commit;

  ------------------------
exception
  when others then
    v_sqlcode := -1 * sqlcode;
    v_err_msg := sqlerrm;
    rollback;
    --记录错误日志
    kingstar.pr_audit_write_errlog(v_pr_task_id, -- 任务标识
                                   0, -- 单位编号
                                   i_tradedate, -- 业务日期
                                   v_function_id, -- 功能标识
                                   v_program_name, -- 程序名
                                   v_error_line_num, -- 程序行号
                                   v_err_msg, -- 错误信息
                                   v_sqlcode, -- SQLCODE
                                   v_sqlstate -- SQLSTATE
                                   );
    commit;
    raise;
end;

Create or Replace PROCEDURE "THJS"."P_USER_PROJECT_IB" (i_tradedate in varchar2)
/*==============================================================================
  版 本    : 1.0.0
  创建人   : czc
  模块编号 : 0
  日 期    : 2019-11-14
  功能描述 : 投行数据集市 投行系统 业务人员项目信息-客户政通工商映射落地
  
             对接新投行数据库
  ==============================================================================*/
  --v101 ylt 20200622 清单填报基础信息中的股票代码信息，目前之关联了主板A股信息，现需要纳入新三板信息
  --v102 ylt 20201021 新增带市场信息的股票代码
  --v103 ylt 20201022 新投行系统数据库的视图ib_v_cust_info 新增pro_is_valid字段
  --v104 ylt 20201207 新投行系统数据库的视图ib_v_cust_info 新增字段
 as
  v_sqlcode  integer default 0;
  v_sqlstate char(5) default '';
  --v_errcode        integer default 0;
  --v_errstate       char(5) default '';
  v_err_msg varchar2(128) default '';
  --v_not_found      integer default 0;
  --v_last_time      char(8);
  v_function_id    integer default 0; --定义存储过程模块编号
  v_error_line_num integer default 0; --错误行号
  --v_error_level    integer default 0; --错误级别
  v_function_desc varchar2(50) default '业务人员项目信息'; --功能描述
  v_program_name  char(40) default 'p_user_project_ib'; --程序名
  v_pr_task_id    number default 0; --任务标示
  -- =======================================================================================================================
  -- 定义业务变量
  -- =======================================================================================================================
  v_count     integer default 0;
  v_eror_line integer default 0;
  v_ncount    integer default 0; --v101+ 记录新三板股票信息数量
  -- =======================================================================================================================
  -- 业务开始
  -- =======================================================================================================================
begin

  --yanglt+ start
  insert into thjs.tb_exec_log
    (log_id, proc_name, proc_param, exec_time)
  values
    (thjs.tb_exec_log_id_seq.nextval,
     'p_user_project_ib',
     'i_tradedate:' || i_tradedate,
     sysdate);
  commit;
  --yanglt+ end

  /**
  完善更新逻辑：
  1.每日增量更新记录数据，全量更新除projid外的其他数据
  2.全量更新工商主体信息相关字段
  3.股票代码名称，因涉及数据推送，不做全量更新，只更新存在且有变化的数据
  **/

  --投行客户项目信息-对接工商主体落地
  select count(1) into v_count from thjs.ib_v_cust_info c;

  if v_count > 0 then
  
    --增量更新记录数
    delete from thjs.tb_ib_cust_info c
     where not exists
     (select 1 from thjs.ib_v_cust_info t where t.projid = c.projid)
       and not exists
     (select 1 from thjs.tb_projlist_main m where m.projid = c.projid);
      
  
    insert into thjs.tb_ib_cust_info
      (khname,
       khxycode,
       cust_type,
       sec_code,
       projid,
       oldprojid,
       projname,
       projcode,
       projtype,
       projphase,
       islx,
       assdeptcode,
       assdeptname,
       deptmanacode,
       deptmananame,
       deptmanamobile,
       deptname,
       deptcode,
       pro_is_valid, --v103+       
       --v104+ start
       dept_code1,
       dept_name1,
       dept_code2,
       dept_name2,
       dept_code3,
       dept_name3,
       pro_status
       --v104+ end
       )
      select trim(c.khname) as khname,
             c.khxycode,
             c.cust_type,
             c.sec_code,
             c.projid,
             c.oldprojid,
             c.projname,
             c.projcode,
             c.projtype,
             c.projphase,
             c.islx,
             c.assdeptcode,
             c.assdeptname,
             c.deptmanacode,
             c.deptmananame,
             c.deptmanamobile,
             c.deptname,
             c.deptcode,
             c.pro_is_valid, --v103+       
             --v104+ start
             c.deptcode1,
             c.deptname1,
             c.deptcode2,
             c.deptname2,
             c.deptcode3,
             c.deptname3,
             c.prostatus
      --v104+ end
        from thjs.ib_v_cust_info c
       where not exists
       (select 1 from thjs.tb_ib_cust_info t where t.projid = c.projid);
    commit;
    
    --删除重复项目
    delete from thjs.tb_ib_cust_info c
     where exists (select t.projid
              from thjs.tb_ib_cust_info t
             where t.projid = c.projid
             group by t.projid
            having count(1) > 1);
  
    commit;
    
    v_error_line_num := 78;
  
    --全量更新其他字段
    merge into thjs.tb_ib_cust_info c
    using (select trim(u.khname) as khname,
                  u.khxycode,
                  u.cust_type,
                  u.sec_code,
                  u.projid,
                  u.oldprojid,
                  u.projname,
                  u.projcode,
                  u.projtype,
                  u.projphase,
                  u.islx,
                  u.assdeptcode,
                  u.assdeptname,
                  u.deptmanacode,
                  u.deptmananame,
                  u.deptmanamobile,
                  u.deptname,
                  u.deptcode,
                  u.pro_is_valid, --v103+       
                  --v104+ start
                  u.deptcode1,
                  u.deptname1,
                  u.deptcode2,
                  u.deptname2,
                  u.deptcode3,
                  u.deptname3,
                  u.prostatus --,
           --v104+ end
           /*x.prip_id     as pripid,
           x.comp_name   as entname,
           x.reg_no      as regno,
           x.comp_id     as eid,
           x.credit_code*/
             from thjs.ib_v_cust_info u
           /*left join (select x.*,
                           row_number() over(partition by x.credit_code order by x.last_modify_date desc) as rn
                      from edw00.pty_main_info x
                     where exists
                     (select 1
                              from thjs.ib_v_cust_info u
                             where u.khxycode is not null
                               and u.khxycode = x.credit_code)) x
            on x.credit_code = u.khxycode
           and x.rn = 1*/
           ) u
    --on (u.projid = c.projid and u.cust_type = c.cust_type)
    on (u.projid = c.projid and u.cust_type = c.cust_type)
    when matched then
      update
         set c.khname   = trim(u.khname),
             c.khxycode = u.khxycode,
             --c.cust_type = u.cust_type,
             c.sec_code = u.sec_code,
             --c.projid         = u.projid,
             c.oldprojid      = u.oldprojid,
             c.projname       = u.projname,
             c.projcode       = u.projcode,
             c.projtype       = u.projtype,
             c.projphase      = u.projphase,
             c.islx           = u.islx,
             c.assdeptcode    = u.assdeptcode,
             c.assdeptname    = u.assdeptname,
             c.deptmanacode   = u.deptmanacode,
             c.deptmananame   = u.deptmananame,
             c.deptmanamobile = u.deptmanamobile,
             c.deptname       = u.deptname,
             c.deptcode       = u.deptcode,
             c.pro_is_valid   = u.pro_is_valid, --v103+
             --v104+ start
             c.dept_code1 = u.deptcode1,
             c.dept_name1 = u.deptname1,
             c.dept_code2 = u.deptcode2,
             c.dept_name2 = u.deptname2,
             c.dept_code3 = u.deptcode3,
             c.dept_name3 = u.deptname3,
             c.pro_status = u.prostatus,
             --v104+ end             
             /*c.pripid      = u.pripid,
             c.entname     = u.entname,
             c.regno       = u.regno,
             c.eid         = u.eid,
             c.credit_code = u.credit_code,*/
             c.update_time = sysdate;
    commit;
    v_error_line_num := 139;
  end if;

  --全名
  /*update thjs.tb_ib_cust_info c
     set (c.pripid, c.entname, c.regno, c.eid, c.credit_code) =
         (select x.prip_id, x.comp_name, x.reg_no, x.comp_id, x.credit_code
            from (select x.*,
                         row_number() over(partition by x.comp_name order by x.last_modify_date desc) as rn
                    from edw00.pty_main_info x) x
           where x.comp_name =
                 (replace(replace(c.khname, '(', '（'), ')', '）'))
             and x.rn = 1)
   where c.pripid is null;
  commit;*/
  v_error_line_num := 220;

  select count(1)
    into v_count
    from dual
    left join wind.tcl_asharedescription t
      on t.s_info_code is not null
   where rownum < 10;

  --v101+ start
  select count(1)
    into v_ncount
    from dual
    left join wind.tcl_neeqsdescription t
      on t.s_info_code is not null
   where rownum < 10;
  --v101+ end

  if v_count > 1 and v_ncount > 1 then
  
    execute immediate 'truncate table  thjs.tmp_projlist_wind_stk_list';
    execute immediate 'truncate table  thjs.tmp_projlist_wind_stk_all';
    execute immediate 'truncate table  thjs.tmp_projlist_wind_stks_list';
  
    --用于项目工作室自带的证券代码匹配，匹配A股，三板，港股
    insert into thjs.tmp_projlist_wind_stk_list
      select t.s_info_windcode,
             t.s_info_code,
             t.s_info_name,
             t.s_info_compcode
        from (select a.s_info_windcode,
                     a.s_info_code,
                     a.s_info_name,
                     a.s_info_compcode
                from wind.tcl_asharedescription a
               where a.s_info_windcode not like 'A%' --已上市 a.s_info_listdate is not null 部分已有非A开头代码即将上市股票视为有效
                 and trim(a.s_info_delistdate) is null --未退市
                 and (a.s_info_exchmarket <>'BSE' or (a.s_info_exchmarket = 'BSE' and
                     a.s_info_listdate is not null)) --剔除新三板转板未上市股票
              union all
              select b.s_info_windcode,
                     b.s_info_code,
                     b.s_info_name,
                     b.s_info_compcode
                from wind.tcl_neeqsdescription b
               where b.s_info_windcode not like 'T%' --已上市 b.s_info_listdate is not null
                 and trim(b.s_info_delistdate) is null --未退市 
              union all
              select c.s_info_windcode,
                     c.s_info_code,
                     c.s_info_name,
                     c.s_info_compcode
                from wind.tcl_hksharedescription c
               where c.s_info_status = 101001000 --有效(L):101001000 发行(N):101003000 摘牌(D):101002000
                 and c.securityclass = 100001000 --品种类型：股票
              ) t;
    commit;
  
    --用于项目工作室自带的证券，自行匹配后，无有效证券信息后；全量证券信息匹配（含退市等），匹配A股，三板，港股
    insert into thjs.tmp_projlist_wind_stk_all
      select t.s_info_windcode,
             t.s_info_code,
             t.s_info_name,
             t.s_info_compcode
        from (select a.s_info_windcode,
                     a.s_info_code,
                     a.s_info_name,
                     a.s_info_compcode
                from wind.tcl_asharedescription a
               where (a.s_info_exchmarket <>'BSE' or (a.s_info_exchmarket = 'BSE' and
                     a.s_info_listdate is not null)) --剔除新三板转板未上市股票
              union all
              select b.s_info_windcode,
                     b.s_info_code,
                     b.s_info_name,
                     b.s_info_compcode
                from wind.tcl_neeqsdescription b
              union all
              select c.s_info_windcode,
                     c.s_info_code,
                     c.s_info_name,
                     c.s_info_compcode
                from wind.tcl_hksharedescription c) t;
    commit;
  
    insert into thjs.tmp_projlist_wind_stks_list
      select listagg(t.s_info_windcode, ',') within group(order by t.s_info_windcode) as s_info_windcode,
             listagg(t.s_info_code, ',') within group(order by t.s_info_windcode) as s_info_code,
             listagg(t.s_info_name, ',') within group(order by t.s_info_windcode) as s_info_name,
             t.s_info_compcode
        from (select a.s_info_windcode,
                     a.s_info_code,
                     a.s_info_name,
                     a.s_info_compcode
                from wind.tcl_asharedescription a
               where a.s_info_windcode not like 'A%' --已上市 a.s_info_listdate is not null 部分已有非A开头代码即将上市股票视为有效
                 and trim(a.s_info_delistdate) is null --未退市    
                 and (a.s_info_exchmarket <>'BSE' or (a.s_info_exchmarket = 'BSE' and
                     a.s_info_listdate is not null)) --剔除新三板转板未上市股票
              union all
              select b.s_info_windcode,
                     b.s_info_code,
                     b.s_info_name,
                     b.s_info_compcode
                from wind.tcl_neeqsdescription b
               where b.s_info_windcode not like 'T%' --已上市 b.s_info_listdate is not null
                 and trim(b.s_info_delistdate) is null --未退市
                 and not exists
               (select *
                        from wind.tcl_asharedescription a 
                       where a.s_info_windcode not like 'A%'
                         and trim(a.s_info_delistdate) is null
                         and a.s_info_code = b.s_info_code) --自行匹配时，剔除同时存在的数据（如832522.BJ 832522.NQ）
              ) t
       group by t.s_info_compcode;
    commit;
  
    --投行项目工作室自带股票信息，剔除未上市已退市信息
    merge into thjs.tb_ib_cust_info t
    using (select t.projid,
                  t.sec_code,
                  listagg(l.s_info_code, ',') within group(order by l.s_info_code) as stkcode,
                  listagg(l.s_info_windcode, ',') within group(order by l.s_info_code) as windcode,
                  listagg(l.s_info_name, ',') within group(order by l.s_info_code) as stkname,
                  l.s_info_compcode as comp_id,
                  'IBDB' as stkflag
             from (select t.projid,
                          regexp_replace(t.sec_code, '[、，,]', ';') as sec_code --项目工作室维护的证券代码分隔符号存在特殊字符，同一替换为;                          
                     from thjs.tb_ib_cust_info t
                    where t.windcode <> t.sec_code --投行项目工作室维护变化
                      and t.stockcode <> t.sec_code) t
            inner join thjs.tmp_projlist_wind_stk_list l
               on (instr(t.sec_code, '.') > 0 and
                  instr(t.sec_code, l.s_info_windcode) > 0)
               or (instr(t.sec_code, '.') = 0 and
                  instr(';' || t.sec_code || ';',
                         ';' || l.s_info_code || ';') > 0)
            where t.sec_code is not null --投行项目工作室自带的
            group by t.projid, t.sec_code, l.s_info_compcode) u
    on (t.projid = u.projid)
    when matched then
      update
         set t.stockcode     = nvl(u.stkcode, t.stockcode),
             t.stockname     = nvl(u.stkname, t.stockname),
             t.windcode      = nvl(u.windcode, t.windcode),
             t.wind_compcode = nvl(u.comp_id, t.wind_compcode),
             t.stockflag     = u.stkflag --v103+
      ;
    commit;
  
    --股票股票代码，名称匹配； 证券代码使用wind证券代码
    --使用统一社会信用代码匹配
    --股票股票代码，名称匹配； 证券代码使用wind证券代码
    --使用统一社会信用代码匹配
    merge into thjs.tb_ib_cust_info t
    using (select u.projid,
                  c.comp_id,
                  l.s_info_windcode, --v103+
                  l.s_info_code,
                  l.s_info_name,
                  'WIND' as stkflag
             from thjs.tb_ib_cust_info u
             left join wind.tcl_compintroduction c
               on c.registernumber = u.khxycode
            inner join thjs.tmp_projlist_wind_stks_list l
               on l.s_info_compcode = c.comp_id
            where exists (select 1
                     from thjs.tb_ib_cust_info x
                    where x.projid = u.projid
                      and x.windcode is null)) u
    on (t.projid = u.projid)
    when matched then
      update
         set t.stockcode     = nvl(u.s_info_code, t.stockcode),
             t.stockname     = nvl(u.s_info_name, t.stockname),
             t.windcode      = nvl(u.s_info_windcode, t.windcode),
             t.wind_compcode = nvl(u.comp_id, t.windcode),
             t.stockflag     = u.stkflag --v103+
      ;
    commit;
  
    v_eror_line := 210;
    --使用公司名称匹配
    merge into thjs.tb_ib_cust_info t
    using (select u.projid,
                  c.comp_id,
                  l.s_info_windcode, --v103+
                  l.s_info_code,
                  l.s_info_name,
                  'WIND' as stkflag
             from thjs.tb_ib_cust_info u
             left join wind.tcl_compintroduction c
               on c.comp_name = u.khname
            inner join thjs.tmp_projlist_wind_stks_list l
               on l.s_info_compcode = c.comp_id
            where u.sec_code is null
              and exists (select 1
                     from thjs.tb_ib_cust_info x
                    where x.projid = u.projid
                      and x.windcode is null)) u
    on (t.projid = u.projid)
    when matched then
      update
         set t.stockcode     = nvl(u.s_info_code, t.stockcode),
             t.stockname     = nvl(u.s_info_name, t.stockname),
             t.windcode      = nvl(u.s_info_windcode, t.windcode),
             t.wind_compcode = nvl(u.comp_id, t.windcode),
             t.stockflag     = u.stkflag --v103+
      ;
  
    commit;
  
    --仍未匹配到，以项目信息匹配所有上市过的信息（包括退市，不包括未上市)
    merge into thjs.tb_ib_cust_info t
    using (select t.projid,
                  t.sec_code,
                  listagg(l.s_info_code, ',') within group(order by l.s_info_code) as stkcode,
                  listagg(l.s_info_windcode, ',') within group(order by l.s_info_code) as windcode,
                  listagg(l.s_info_name, ',') within group(order by l.s_info_code) as stkname,
                  l.s_info_compcode as comp_id,
                  'IBDB' as stkflag
             from (select t.projid,
                          regexp_replace(t.sec_code, '[、，,]', ';') as sec_code --项目工作室维护的证券代码分隔符号存在特殊字符，同一替换为;
                     from thjs.tb_ib_cust_info t
                    where t.windcode <> t.sec_code --投行项目工作室维护变化
                      and t.stockcode <> t.sec_code) t
            inner join thjs.tmp_projlist_wind_stk_all l
               on (instr(t.sec_code, '.') > 0 and
                  instr(t.sec_code, l.s_info_windcode) > 0)
               or (instr(t.sec_code, '.') = 0 and
                  instr(';' || t.sec_code || ';',
                         ';' || l.s_info_code || ';') > 0)
            where exists (select 1
                     from thjs.tb_ib_cust_info x
                    where x.projid = t.projid
                      and x.windcode is null)
            group by t.projid, t.sec_code, l.s_info_compcode) u
    on (t.projid = u.projid)
    when matched then
      update
         set t.stockcode     = nvl(u.stkcode, t.stockcode),
             t.stockname     = nvl(u.stkname, t.stockname),
             t.windcode      = nvl(u.windcode, t.windcode),
             t.wind_compcode = nvl(u.comp_id, t.wind_compcode),
             t.stockflag     = u.stkflag --v103+
      ;
    commit;
  
    --检查，公司与证券不匹配的信息，提醒投行合规人员
    --更新公司所属wind公司代码
    --使用统一社会信用代码匹配
    merge into thjs.tb_ib_cust_info t
    using (select u.projid, c.comp_id
             from thjs.tmp_ib_cust_info u
             left join wind.tcl_compintroduction c
               on c.registernumber = u.khxycode) u
    on (t.projid = u.projid)
    when matched then
      update set t.kh_wind_compcode = u.comp_id;
    commit;
  
    --使用公司名称匹配
    merge into thjs.tb_ib_cust_info t
    using (select u.projid, c.comp_id
             from thjs.tmp_ib_cust_info u
             left join wind.tcl_compintroduction c
               on c.comp_name = u.khname
            where exists (select 1
                     from thjs.tb_ib_cust_info x
                    where x.projid = u.projid
                      and x.kh_wind_compcode is null)) u
    on (t.projid = u.projid)
    when matched then
      update set t.kh_wind_compcode = u.comp_id;
  
    commit;
  
    --临时手工修正
    /*update thjs.tb_ib_cust_info t
       set t.stockcode = '300745',
           t.stockname = '欣锐科技',
           t.windcode  = '300745.SZ'
     where t.projid = '9B9C0CAD61D14F8AA1716A93232A5691';
    commit;*/
  
    --修正IPO项目（北交所上市）  
    /*merge into thjs.tb_ib_cust_info t
    using (select t.projid,
                  nvl(x.s_info_code, t.stockcode) stockcode,
                  nvl(x.s_info_name, t.stockname) stockname,
                  nvl(x.s_info_windcode, t.windcode) windcode
             from thjs.tb_ib_cust_info t
            inner join (select *
                         from ZX90.VW_WDZX_ASHAREDESCRIPTION t
                        where exists
                        (select *
                                 from wind.neeqsdescription n
                                where n.s_info_code = t.s_info_code)) x
               on x.s_info_compcode = t.wind_compcode
            where t.projtype like '%IPO') u
    on (t.projid = u.projid)
    when matched then
      update
         set t.stockcode = nvl(u.stockcode, t.stockcode),
             t.stockname = nvl(u.stockname, t.stockname),
             t.windcode  = nvl(u.windcode, t.windcode);
    commit;*/
  
  end if;

  ------------------------
exception
  when others then
    v_sqlcode := -1 * sqlcode;
    v_err_msg := sqlerrm;
    rollback;
    --记录错误日志
    thjs.p_write_error_log(i_tradedate    => i_tradedate,
                           i_exec_func_id => v_function_id,
                           i_func_own     => 'THJS',
                           i_func_name    => v_program_name,
                           i_occur_time   => sysdate,
                           i_sqlerrm      => v_err_msg,
                           i_sqlcode      => v_sqlcode,
                           i_sqlerrl      => v_error_line_num);
    /*kingstar.pr_audit_write_errlog(v_pr_task_id, -- 任务标识
                                   0, -- 单位编号
                                   i_tradedate, -- 业务日期
                                   v_function_id, -- 功能标识
                                   v_program_name, -- 程序名
                                   v_error_line_num, -- 程序行号
                                   v_err_msg, -- 错误信息
                                   v_sqlcode, -- SQLCODE
                                   v_sqlstate -- SQLSTATE
                                   );*/
    commit;
    raise;
end;

Create or Replace PROCEDURE "THJS"."P_USER_PROJECT_IB_REFRESH" (i_tradedate in varchar2)
/*==============================================================================
  版 本    : 1.0.0
  创建人   : czc
  模块编号 : 0
  日 期    : 2019-11-14
  功能描述 : 投行数据集市 投行系统 业务人员项目信息-实时刷新
             
  ==============================================================================*/
  --v101 ylt 20200623 清单填报基础信息中的股票代码信息，目前之关联了主板A股信息，现需要纳入新三板信息
  --v102 ylt 20200825 如果有新的项目类型，把新的项目类型加入项目类型表中，默认不允许填报清单
  --v103 ylt 20201021 新增带市场信息的股票代码
  --v104 ylt 20201022 新投行系统数据库的视图ib_v_cust_info 新增pro_is_valid字段
 as
  v_sqlcode  integer default 0;
  v_sqlstate char(5) default '';
  --v_errcode        integer default 0;
  --v_errstate       char(5) default '';
  v_err_msg varchar2(128) default '';
  --v_not_found      integer default 0;
  --v_last_time      char(8);
  v_function_id    integer default 0; --定义存储过程模块编号
  v_error_line_num integer default 0; --错误行号
  --v_error_level    integer default 0; --错误级别
  v_function_desc varchar2(50) default '业务人员项目信息'; --功能描述
  v_program_name  char(40) default 'p_user_project_ib_refresh'; --程序名
  v_pr_task_id    number default 0; --任务标示
  -- =======================================================================================================================
  -- 定义业务变量
  -- =======================================================================================================================
  v_log_id    number;
  v_dif_count integer default 0;
  v_count     integer default 0;
  v_eror_line integer default 0;
  v_ncount    integer default 0; --v101+ 记录新三板股票信息数量
  v_pjnames   varchar2(32767);
  -- =======================================================================================================================
  -- 业务开始
  -- =======================================================================================================================
begin

  --投行客户项目信息-对接工商主体落地
  v_eror_line := 37;
  delete from thjs.tmp_ib_cust_info c;
  commit;

  --防止与实时采集任务冲突，锁定表
  lock table thjs.ib_v_cust_info in exclusive mode; -- nowait;

  select count(1), to_char(wm_concat(t.projname)) as pjname
    into v_dif_count, v_pjnames
    from thjs.ib_v_cust_info t
   where not exists
   (select 1 from thjs.tb_ib_cust_info c where c.projid = t.projid);

  v_log_id := thjs.seq_proc_log_id.nextval;

  insert into thjs.tb_proc_log
    (log_id, proc_name, input_text, exec_desc, biz_desc)
  values
    (v_log_id,
     'p_user_project_ib_refresh',
     i_tradedate,
     '更新记录数：' || v_dif_count,
     v_pjnames);

  commit;

  insert into thjs.tmp_ib_cust_info
    (khname,
     khxycode,
     cust_type,
     sec_code,
     projid,
     oldprojid,
     projname,
     projcode,
     projtype,
     projphase,
     islx,
     assdeptcode,
     assdeptname,
     deptmanacode,
     deptmananame,
     deptmanamobile,
     deptname,
     deptcode,
     pro_is_valid, --v103+       
     --v104+ start
     deptcode1,
     deptname1,
     deptcode2,
     deptname2,
     deptcode3,
     deptname3,
     prostatus
     --v104+ end
     )
    select trim(c.khname) as khname,
           c.khxycode,
           c.cust_type,
           c.sec_code,
           c.projid,
           c.oldprojid,
           c.projname,
           c.projcode,
           c.projtype,
           c.projphase,
           c.islx,
           c.assdeptcode,
           c.assdeptname,
           c.deptmanacode,
           c.deptmananame,
           c.deptmanamobile,
           c.deptname,
           c.deptcode,
           c.pro_is_valid, --v103+       
           --v104+ start
           c.deptcode1,
           c.deptname1,
           c.deptcode2,
           c.deptname2,
           c.deptcode3,
           c.deptname3,
           c.prostatus
    --v104+ end
      from thjs.ib_v_cust_info c
     where not exists (select 1
              from thjs.tb_ib_cust_info t
             where t.projid = c.projid
               and t.khname = c.khname
               and t.khxycode = c.khxycode
               and t.sec_code = c.sec_code);
  commit;
  v_eror_line := 95;
  
  --删除重复项目
    delete from thjs.tmp_ib_cust_info c
     where exists (select t.projid
              from thjs.tmp_ib_cust_info t
             where t.projid = c.projid
             group by t.projid
            having count(1) > 1);
  
    commit;

  insert into thjs.tb_ib_cust_info
    (khname,
     khxycode,
     cust_type,
     sec_code,
     projid,
     oldprojid,
     projname,
     projcode,
     projtype,
     projphase,
     islx,
     assdeptcode,
     assdeptname,
     deptmanacode,
     deptmananame,
     deptmanamobile,
     deptname,
     deptcode,
     pro_is_valid, --v103+       
     --v104+ start
     dept_code1,
     dept_name1,
     dept_code2,
     dept_name2,
     dept_code3,
     dept_name3,
     pro_status
     --v104+ end
     )
    select trim(c.khname) as khname,
           c.khxycode,
           c.cust_type,
           c.sec_code,
           c.projid,
           c.oldprojid,
           c.projname,
           c.projcode,
           c.projtype,
           c.projphase,
           c.islx,
           c.assdeptcode,
           c.assdeptname,
           c.deptmanacode,
           c.deptmananame,
           c.deptmanamobile,
           c.deptname,
           c.deptcode,
           c.pro_is_valid, --v103+       
           --v104+ start
           c.deptcode1,
           c.deptname1,
           c.deptcode2,
           c.deptname2,
           c.deptcode3,
           c.deptname3,
           c.prostatus
    --v104+ end
      from thjs.tmp_ib_cust_info c
     where not exists
     (select 1 from thjs.tb_ib_cust_info t where t.projid = c.projid);
  commit;

  --全量更新其他字段
  --全量更新其他字段
  merge into thjs.tb_ib_cust_info c
  using (select trim(u.khname) as khname,
                u.khxycode,
                u.cust_type,
                u.sec_code,
                u.projid,
                u.oldprojid,
                u.projname,
                u.projcode,
                u.projtype,
                u.projphase,
                u.islx,
                u.assdeptcode,
                u.assdeptname,
                u.deptmanacode,
                u.deptmananame,
                u.deptmanamobile,
                u.deptname,
                u.deptcode,
                u.pro_is_valid, --v103+       
                --v104+ start
                u.deptcode1,
                u.deptname1,
                u.deptcode2,
                u.deptname2,
                u.deptcode3,
                u.deptname3,
                u.prostatus --,
         --v104+ end
         /*x.prip_id     as pripid,
         x.comp_name   as entname,
         x.reg_no      as regno,
         x.comp_id     as eid,
         x.credit_code*/
           from thjs.ib_v_cust_info u
         /* left join (select x.*,
                         row_number() over(partition by x.credit_code order by x.last_modify_date desc) as rn
                    from edw00.pty_main_info x
                   where exists (select 1
                            from thjs.ib_v_cust_info u
                           where u.khxycode is not null
                             and u.khxycode = x.credit_code)) x
          on x.credit_code = u.khxycode
         and x.rn = 1*/
         ) u
  on (u.projid = c.projid and u.cust_type = c.cust_type)
  when matched then
    update
       set c.khname   = trim(u.khname),
           c.khxycode = u.khxycode,
           --c.cust_type = u.cust_type,
           c.sec_code = u.sec_code,
           --c.projid         = u.projid,
           c.oldprojid      = u.oldprojid,
           c.projname       = u.projname,
           c.projcode       = u.projcode,
           c.projtype       = u.projtype,
           c.projphase      = u.projphase,
           c.islx           = u.islx,
           c.assdeptcode    = u.assdeptcode,
           c.assdeptname    = u.assdeptname,
           c.deptmanacode   = u.deptmanacode,
           c.deptmananame   = u.deptmananame,
           c.deptmanamobile = u.deptmanamobile,
           c.deptname       = u.deptname,
           c.deptcode       = u.deptcode,
           c.pro_is_valid   = u.pro_is_valid, --v103+
           --v104+ start
           c.dept_code1 = u.deptcode1,
           c.dept_name1 = u.deptname1,
           c.dept_code2 = u.deptcode2,
           c.dept_name2 = u.deptname2,
           c.dept_code3 = u.deptcode3,
           c.dept_name3 = u.deptname3,
           c.pro_status = u.prostatus,
           --v104+ end             
           /*c.pripid      = u.pripid,
           c.entname     = u.entname,
           c.regno       = u.regno,
           c.eid         = u.eid,
           c.credit_code = u.credit_code,*/
           c.update_time = sysdate;

  commit;
  v_eror_line := 185;

  select count(1)
    into v_count
    from dual
    left join wind.tcl_asharedescription t
      on t.s_info_code is not null
   where rownum < 10;

  --v101+ start
  select count(1)
    into v_ncount
    from dual
    left join wind.tcl_neeqsdescription t
      on t.s_info_code is not null
   where rownum < 10;
  --v101+ end

  if v_count > 1 and v_ncount > 1 then
  
    execute immediate 'truncate table  thjs.tmp_projlist_wind_stk_list';
    execute immediate 'truncate table  thjs.tmp_projlist_wind_stk_all';
    execute immediate 'truncate table  thjs.tmp_projlist_wind_stks_list';
  
    --用于项目工作室自带的证券代码匹配，匹配A股，三板，港股
    insert into thjs.tmp_projlist_wind_stk_list
      select t.s_info_windcode,
             t.s_info_code,
             t.s_info_name,
             t.s_info_compcode
        from (select a.s_info_windcode,
                     a.s_info_code,
                     a.s_info_name,
                     a.s_info_compcode
                from wind.tcl_asharedescription a
               where a.s_info_windcode not like 'A%' --已上市 a.s_info_listdate is not null 部分已有非A开头代码即将上市股票视为有效
                 and trim(a.s_info_delistdate) is null --未退市
                 and (a.s_info_exchmarket <>'BSE' or (a.s_info_exchmarket = 'BSE' and
                     a.s_info_listdate is not null)) --剔除新三板转板未上市股票
              union all
              select b.s_info_windcode,
                     b.s_info_code,
                     b.s_info_name,
                     b.s_info_compcode
                from wind.tcl_neeqsdescription b
               where b.s_info_windcode not like 'T%' --已上市 b.s_info_listdate is not null
                 and trim(b.s_info_delistdate) is null --未退市              
              union all
              select c.s_info_windcode,
                     c.s_info_code,
                     c.s_info_name,
                     c.s_info_compcode
                from wind.tcl_hksharedescription c
               where c.s_info_status = 101001000 --有效(L):101001000 发行(N):101003000 摘牌(D):101002000
                 and c.securityclass = 100001000 --品种类型：股票
              ) t;
    commit;
  
    --用于项目工作室自带的证券，自行匹配后，无有效证券信息后；全量证券信息匹配（含退市等），匹配A股，三板，港股
    insert into thjs.tmp_projlist_wind_stk_all
      select t.s_info_windcode,
             t.s_info_code,
             t.s_info_name,
             t.s_info_compcode
        from (select a.s_info_windcode,
                     a.s_info_code,
                     a.s_info_name,
                     a.s_info_compcode
                from wind.tcl_asharedescription a
               where (a.s_info_exchmarket <>'BSE' or (a.s_info_exchmarket = 'BSE' and
                     a.s_info_listdate is not null)) --剔除新三板转板未上市股票
              union all
              select b.s_info_windcode,
                     b.s_info_code,
                     b.s_info_name,
                     b.s_info_compcode
                from wind.tcl_neeqsdescription b
              union all
              select c.s_info_windcode,
                     c.s_info_code,
                     c.s_info_name,
                     c.s_info_compcode
                from wind.tcl_hksharedescription c) t;
    commit;
  
    insert into thjs.tmp_projlist_wind_stks_list
      select listagg(t.s_info_windcode, ',') within group(order by t.s_info_windcode) as s_info_windcode,
             listagg(t.s_info_code, ',') within group(order by t.s_info_windcode) as s_info_code,
             listagg(t.s_info_name, ',') within group(order by t.s_info_windcode) as s_info_name,
             t.s_info_compcode
        from (select a.s_info_windcode,
                     a.s_info_code,
                     a.s_info_name,
                     a.s_info_compcode
                from wind.tcl_asharedescription a
               where a.s_info_windcode not like 'A%' --已上市 a.s_info_listdate is not null 部分已有非A开头代码即将上市股票视为有效
                 and trim(a.s_info_delistdate) is null --未退市                 
                 and (a.s_info_exchmarket <>'BSE' or (a.s_info_exchmarket = 'BSE' and
                     a.s_info_listdate is not null)) --剔除新三板转板未上市股票
              union all
              select b.s_info_windcode,
                     b.s_info_code,
                     b.s_info_name,
                     b.s_info_compcode
                from wind.tcl_neeqsdescription b
               where b.s_info_windcode not like 'T%' --已上市 b.s_info_listdate is not null
                 and trim(b.s_info_delistdate) is null --未退市 
                 and not exists
               (select *
                        from wind.tcl_asharedescription a
                       where a.s_info_windcode not like 'A%'
                         and trim(a.s_info_delistdate) is null
                         and a.s_info_code = b.s_info_code) --自行匹配时，剔除同时存在的数据（如832522.BJ 832522.NQ）
              ) t
       group by t.s_info_compcode;
    commit;
  
    --投行项目工作室自带股票信息，剔除未上市已退市信息
    merge into thjs.tb_ib_cust_info t
    using (select t.projid,
                  t.sec_code,
                  listagg(l.s_info_code, ',') within group(order by l.s_info_code) as stkcode,
                  listagg(l.s_info_windcode, ',') within group(order by l.s_info_code) as windcode,
                  listagg(l.s_info_name, ',') within group(order by l.s_info_code) as stkname,
                  l.s_info_compcode as comp_id,
                  'IBDB' as stkflag
             from (select t.projid,
                          regexp_replace(t.sec_code, '[、，,]', ';') as sec_code --项目工作室维护的证券代码分隔符号存在特殊字符，同一替换为;
                     from thjs.tmp_ib_cust_info t) t
            inner join thjs.tmp_projlist_wind_stk_list l
               on (instr(t.sec_code, '.') > 0 and
                  instr(t.sec_code, l.s_info_windcode) > 0)
               or (instr(t.sec_code, '.') = 0 and
                  instr(';' || t.sec_code || ';',
                         ';' || l.s_info_code || ';') > 0)
            where t.sec_code is not null --投行项目工作室自带的
            group by t.projid, t.sec_code, l.s_info_compcode) u
    on (t.projid = u.projid)
    when matched then
      update
         set t.stockcode     = nvl(u.stkcode, t.stockcode),
             t.stockname     = nvl(u.stkname, t.stockname),
             t.windcode      = nvl(u.windcode, t.windcode),
             t.wind_compcode = nvl(u.comp_id, t.wind_compcode),
             t.stockflag     = u.stkflag --v103+
      ;
    commit;
  
    --股票股票代码，名称匹配； 证券代码使用wind证券代码
    --使用统一社会信用代码匹配
    merge into thjs.tb_ib_cust_info t
    using (select u.projid,
                  c.comp_id,
                  l.s_info_windcode, --v103+
                  l.s_info_code,
                  l.s_info_name,
                  'WIND' as stkflag
             from thjs.tmp_ib_cust_info u
             left join wind.tcl_compintroduction c
               on c.registernumber = u.khxycode
            inner join thjs.tmp_projlist_wind_stks_list l
               on l.s_info_compcode = c.comp_id
            where exists (select 1
                     from thjs.tb_ib_cust_info x
                    where x.projid = u.projid
                      and x.windcode is null)) u
    on (t.projid = u.projid)
    when matched then
      update
         set t.stockcode     = nvl(u.s_info_code, t.stockcode),
             t.stockname     = nvl(u.s_info_name, t.stockname),
             t.windcode      = nvl(u.s_info_windcode, t.windcode),
             t.wind_compcode = nvl(u.comp_id, t.windcode),
             t.stockflag     = u.stkflag --v103+
      ;
    commit;
  
    v_eror_line := 210;
    --使用公司名称匹配
    execute immediate 'truncate table thjs.tmp_merge_result';
    insert into thjs.tmp_merge_result
      (projid, new_stkcode, new_stkname, new_windcode, new_comp_id, new_stkflag)
    select /*+parallel(4)*/u.projid,
                  c.comp_id,
                  l.s_info_windcode, --v103+
                  l.s_info_code,
                  l.s_info_name,
                  'WIND' as stkflag
             from thjs.tmp_ib_cust_info u
             left join wind.tcl_compintroduction c
               on c.comp_name = u.khname
            inner join thjs.tmp_projlist_wind_stks_list l
               on l.s_info_compcode = c.comp_id
            where exists (select 1
                     from thjs.tb_ib_cust_info x
                    where x.projid = u.projid
                      and x.windcode is null);
    
    merge into thjs.tb_ib_cust_info t
    using thjs.tmp_merge_result u
    on (t.projid = u.projid)
    when matched then
      update
         set t.stockcode     = nvl(u.new_stkcode, t.stockcode),
             t.stockname     = nvl(u.new_stkname, t.stockname),
             t.windcode      = nvl(u.new_windcode, t.windcode),
             t.wind_compcode = nvl(u.new_comp_id, t.windcode),
             t.stockflag     = u.new_stkflag --v103+
      ;                  
    /*merge into thjs.tb_ib_cust_info t
    using (select u.projid,
                  c.comp_id,
                  l.s_info_windcode, --v103+
                  l.s_info_code,
                  l.s_info_name,
                  'WIND' as stkflag
             from thjs.tmp_ib_cust_info u
             left join wind.tcl_compintroduction c
               on c.comp_name = u.khname
            inner join thjs.tmp_projlist_wind_stks_list l
               on l.s_info_compcode = c.comp_id
            where exists (select 1
                     from thjs.tb_ib_cust_info x
                    where x.projid = u.projid
                      and x.windcode is null)) u
    on (t.projid = u.projid)
    when matched then
      update
         set t.stockcode     = nvl(u.s_info_code, t.stockcode),
             t.stockname     = nvl(u.s_info_name, t.stockname),
             t.windcode      = nvl(u.s_info_windcode, t.windcode),
             t.wind_compcode = nvl(u.comp_id, t.windcode),
             t.stockflag     = u.stkflag --v103+
      ;*/
  
    commit;
  
    --仍未匹配到，以项目信息匹配所有上市过的信息（包括退市，不包括未上市)
    /*merge into thjs.tb_ib_cust_info t
    using (select t.projid,
                  t.sec_code,
                  listagg(l.s_info_code, ',') within group(order by l.s_info_code) as stkcode,
                  listagg(l.s_info_windcode, ',') within group(order by l.s_info_code) as windcode,
                  listagg(l.s_info_name, ',') within group(order by l.s_info_code) as stkname,
                  l.s_info_compcode as comp_id,
                  'IBDB' as stkflag
             from thjs.tmp_ib_cust_info t
            inner join thjs.tmp_projlist_wind_stk_all l
               on instr(t.sec_code, l.s_info_windcode) > 0
               or instr(t.sec_code, l.s_info_code) > 0
            where exists (select 1
                     from thjs.tb_ib_cust_info x
                    where x.projid = t.projid
                      and x.windcode is null)
            group by t.projid, t.sec_code, l.s_info_compcode) u
    on (t.projid = u.projid)
    when matched then
      update
         set t.stockcode     = nvl(u.stkcode, t.stockcode),
             t.stockname     = nvl(u.stkname, t.stockname),
             t.windcode      = nvl(u.windcode, t.windcode),
             t.wind_compcode = nvl(u.comp_id, t.wind_compcode),
             t.stockflag     = u.stkflag --v103+
      ;
    commit;*/
  
    --检查，公司与证券不匹配的信息，提醒投行合规人员
    --更新公司所属wind公司代码
    --使用统一社会信用代码匹配
    merge into thjs.tb_ib_cust_info t
    using (select u.projid, c.comp_id
             from thjs.tmp_ib_cust_info u
             left join wind.tcl_compintroduction c
               on c.registernumber = u.khxycode) u
    on (t.projid = u.projid)
    when matched then
      update set t.kh_wind_compcode = u.comp_id;
    commit;
  
    --使用公司名称匹配
    merge into thjs.tb_ib_cust_info t
    using (select u.projid, c.comp_id
             from thjs.tmp_ib_cust_info u
             left join wind.tcl_compintroduction c
               on c.comp_name = u.khname
            where exists (select 1
                     from thjs.tb_ib_cust_info x
                    where x.projid = u.projid
                      and x.kh_wind_compcode is null)) u
    on (t.projid = u.projid)
    when matched then
      update set t.kh_wind_compcode = u.comp_id;
  
    commit;
  
    --临时手工修正
    /*update thjs.tb_ib_cust_info t
       set t.stockcode = '300745',
           t.stockname = '欣锐科技',
           t.windcode  = '300745.SZ'
     where t.projid = '9B9C0CAD61D14F8AA1716A93232A5691';
    commit;*/
  
    --修正IPO项目（北交所上市）  
    /*merge into thjs.tb_ib_cust_info t
    using (select t.projid,
                  nvl(x.s_info_code, t.stockcode) stockcode,
                  nvl(x.s_info_name, t.stockname) stockname,
                  nvl(x.s_info_windcode, t.windcode) windcode
             from thjs.tb_ib_cust_info t
            inner join (select *
                         from ZX90.VW_WDZX_ASHAREDESCRIPTION t
                        where exists
                        (select *
                                 from zx90.tcl_neeqsdescription n
                                where n.s_info_code = t.s_info_code)) x
               on x.s_info_compcode = t.wind_compcode
            where t.projtype like '%IPO') u
    on (t.projid = u.projid)
    when matched then
      update
         set t.stockcode = nvl(u.stockcode, t.stockcode),
             t.stockname = nvl(u.stockname, t.stockname),
             t.windcode  = nvl(u.windcode, t.windcode);
    commit;*/
  
  end if;

  --v102+ start
  --将新增加的项目类型保存至临时表中
  execute immediate 'truncate table thjs.tb_projlist_projtype_tmp';
  insert into thjs.tb_projlist_projtype_tmp
    select distinct t.projtype
      from thjs.tb_ib_cust_info t
     where not exists (select *
              from thjs.tb_projlist_busitype m
             where t.projtype = m.proj_type);
  commit;

  --把新增加的项目类型更新至 项目类型是否允许清单填报表中
  --20240422 新增项目类型是否影响反洗钱客户失效处理设置
  insert into thjs.tb_projlist_busitype
    (busi_type1, busi_type2, proj_type, is_allow_report, is_limit_fxq)
    select substr(t.projtype, 0, instr(t.projtype, '_') - 1) busi_type1,
           substr(t.projtype,
                  instr(t.projtype, '_') + 1,
                  length(t.projtype)) busi_type2,
           t.projtype,
           '1' is_allow_report, --默认 1-允许20240508--暂移除默认限制
           '1' is_limit_fxq --是否限制反洗钱失效：默认1-是，0-否
      from thjs.tb_projlist_projtype_tmp t
     where not exists (select 1
              from thjs.tb_projlist_busitype c
             where c.proj_type = t.projtype);
  commit;
  --v102+ end

  update thjs.tb_proc_log l
     set l.end_time  = sysdate,
         l.exec_cost = ceil((sysdate - l.start_time) * 86400)
   where l.log_id = v_log_id;

  commit;

  ------------------------
exception
  when others then
    v_sqlcode := -1 * sqlcode;
    v_err_msg := v_eror_line || '-' || sqlerrm;
    rollback;
    --记录错误日志
    --记录错误日志
    thjs.p_write_error_log(i_tradedate    => i_tradedate,
                           i_exec_func_id => v_function_id,
                           i_func_own     => 'THJS',
                           i_func_name    => v_program_name,
                           i_occur_time   => sysdate,
                           i_sqlerrm      => v_err_msg,
                           i_sqlcode      => v_sqlcode,
                           i_sqlerrl      => v_error_line_num);
    /*kingstar.pr_audit_write_errlog(v_pr_task_id, -- 任务标识
                                   0, -- 单位编号
                                   i_tradedate, -- 业务日期
                                   v_function_id, -- 功能标识
                                   v_program_name, -- 程序名
                                   v_error_line_num, -- 程序行号
                                   v_err_msg, -- 错误信息
                                   v_sqlcode, -- SQLCODE
                                   v_sqlstate -- SQLSTATE
                                   );*/
    commit;
    raise;
end;

Create or Replace PROCEDURE "THJS"."P_USER_PROJECT_IB_REFRESH_YLT" (i_tradedate in varchar2)
/*==============================================================================
  版 本    : 1.0.0
  创建人   : czc
  模块编号 : 0
  日 期    : 2019-11-14
  功能描述 : 投行数据集市 投行系统 业务人员项目信息-实时刷新
  
  ==============================================================================*/
  --v101 ylt 20200623 清单填报基础信息中的股票代码信息，目前之关联了主板A股信息，现需要纳入新三板信息
  --v102 ylt 20200825 如果有新的项目类型，把新的项目类型加入项目类型表中，默认允许填报清单
 as
  v_sqlcode  integer default 0;
  v_sqlstate char(5) default '';
  --v_errcode        integer default 0;
  --v_errstate       char(5) default '';
  v_err_msg varchar2(128) default '';
  --v_not_found      integer default 0;
  --v_last_time      char(8);
  v_function_id    integer default 0; --定义存储过程模块编号
  v_error_line_num integer default 0; --错误行号
  --v_error_level    integer default 0; --错误级别
  v_function_desc varchar2(50) default '业务人员项目信息'; --功能描述
  v_program_name  char(40) default 'p_user_project_ib_refresh_ylt'; --程序名
  v_pr_task_id    number default 0; --任务标示
  -- =======================================================================================================================
  -- 定义业务变量
  -- =======================================================================================================================
  v_log_id    number;
  v_dif_count integer default 0;
  v_count     integer default 0;
  v_eror_line integer default 0;
  v_ncount    integer default 0; --v101+ 记录新三板股票信息数量
  v_pjnames   varchar2(4000);
  -- =======================================================================================================================
  -- 业务开始
  -- =======================================================================================================================
begin

  --投行客户项目信息-对接工商主体落地
  v_eror_line := 37;
  delete from thjs.tmp_ib_cust_info c;
  commit;

  --防止与实时采集任务冲突，锁定表
  lock table thjs.ib_v_cust_info in exclusive mode; -- nowait;

  select count(1), to_char(wm_concat(t.projname)) as pjname
    into v_dif_count, v_pjnames
    from thjs.ib_v_cust_info t
   where not exists
   (select 1 from thjs.tb_ib_cust_info c where c.projid = t.projid);

  v_log_id := thjs.seq_proc_log_id.nextval;

  insert into thjs.tb_proc_log
    (log_id, proc_name, input_text, exec_desc, biz_desc)
  values
    (v_log_id,
     'p_user_project_ib_refresh_ylt',
     i_tradedate,
     '更新记录数：' || v_dif_count,
     v_pjnames);

  commit;

  insert into thjs.tmp_ib_cust_info
    (khname,
     projid,
     projname,
     projtype,
     projphase,
     islx,
     khxycode,
     assdeptcode,
     assdeptname,
     deptmanacode,
     deptmananame,
     deptmanamobile,
     deptname,
     deptcode)
    select t.khname,
           t.projid,
           t.projname,
           t.projtype,
           t.projphase,
           t.islx,
           t.khxycode,
           t.assdeptcode,
           t.assdeptname,
           t.deptmanacode,
           t.deptmananame,
           t.deptmanamobile,
           t.deptname,
           t.deptcode
      from thjs.ib_v_cust_info t
     where not exists
     (select 1 from thjs.tb_ib_cust_info c where c.projid = t.projid);
  commit;
  v_eror_line := 95;
  insert into thjs.tb_ib_cust_info
    (khname,
     projid,
     projname,
     projtype,
     projphase,
     islx,
     khxycode,
     assdeptcode,
     assdeptname,
     deptmanacode,
     deptmananame,
     deptmanamobile,
     deptname,
     deptcode)
    select c.khname,
           c.projid,
           c.projname,
           c.projtype,
           c.projphase,
           c.islx,
           c.khxycode,
           c.assdeptcode,
           c.assdeptname,
           c.deptmanacode,
           c.deptmananame,
           c.deptmanamobile,
           c.deptname,
           c.deptcode
      from thjs.tmp_ib_cust_info c;
  commit;
  v_eror_line := 127;

  --全量更新其他字段
  --全量更新其他字段
  merge into thjs.tb_ib_cust_info c
  using (select u.khname,
                u.projid,
                u.projname,
                u.projtype,
                u.projphase,
                u.islx,
                u.khxycode,
                u.assdeptcode,
                u.assdeptname,
                u.deptmanacode,
                u.deptmananame,
                u.deptmanamobile,
                u.deptname,
                u.deptcode,
                x.prip_id        as pripid,
                x.comp_name      as entname,
                x.reg_no         as regno,
                x.comp_id        as eid,
                x.credit_code
           from thjs.ib_v_cust_info u
           left join (select x.*,
                            row_number() over(partition by x.credit_code order by x.last_modify_date desc) as rn
                       from thjs.tcl_edw00_pty_main_info x
                      where exists (select 1
                               from thjs.ib_v_cust_info u
                              where u.khxycode is not null
                                and u.khxycode = x.credit_code)) x
             on x.credit_code = u.khxycode
            and x.rn = 1) u
  on (u.projid = c.projid)
  when matched then
    update
       set c.khname         = u.khname,
           c.projname       = u.projname,
           c.projtype       = u.projtype,
           c.projphase      = u.projphase,
           c.islx           = u.islx,
           c.khxycode       = u.khxycode,
           c.assdeptcode    = u.assdeptcode,
           c.assdeptname    = u.assdeptname,
           c.deptmanacode   = u.deptmanacode,
           c.deptmananame   = u.deptmananame,
           c.deptmanamobile = u.deptmanamobile,
           c.deptname       = u.deptname,
           c.deptcode       = u.deptcode,
           c.pripid         = u.pripid,
           c.entname        = u.entname,
           c.regno          = u.regno,
           c.eid            = u.eid,
           c.credit_code    = u.credit_code,
           c.update_time    = sysdate;

  commit;
  v_eror_line := 185;

  select count(1)
    into v_count
    from dual
    left join wind.tcl_asharedescription t
      on t.s_info_code is not null
   where rownum < 10;

  --v101+ start
  select count(1)
    into v_ncount
    from dual
    left join wind.tcl_neeqsdescription t
      on t.s_info_code is not null
   where rownum < 10;
  --v101+ end

  if v_count > 1 and v_ncount > 1 then
  
    --股票股票代码，名称匹配； 证券代码使用wind证券代码
    --使用统一社会信用代码匹配
    merge into thjs.tb_ib_cust_info t
    using (select u.projid, s.s_info_code, s.s_info_name
             from thjs.tmp_ib_cust_info u
             left join wind.tcl_compintroduction c
               on c.registernumber = u.khxycode
           --inner join zx90.vw_wdzx_asharedescription s--v101-
           --v101+ start
            inner join (select t.s_info_windcode,
                              t.s_info_code,
                              t.s_info_name,
                              t.s_info_compcode
                         from thjs.vw_wdzx_asharedescription t
                        where not exists
                        (select 1
                                 from wind.tcl_neeqsdescription x
                                where x.s_info_compcode = t.s_info_compcode
                                  and trim(x.s_info_delistdate) is null
                                  and x.s_info_code not like 'T%')
                       union all
                       select to_char(wm_concat(x.s_info_windcode)) as s_info_windcode,
                              to_char(wm_concat(x.s_info_code)) as s_info_code,
                              to_char(wm_concat(x.s_info_name)) as s_info_name,
                              x.s_info_compcode
                         from wind.tcl_neeqsdescription x
                        where trim(x.s_info_delistdate) is null --未退市
                          and x.s_info_code not like 'T%' --未挂牌终止
                        group by x.s_info_compcode) s
           --v101+ end
               on s.s_info_compcode = c.comp_id) u
    on (t.projid = u.projid)
    when matched then
      update
         set t.stockcode = nvl(u.s_info_code, t.stockcode),
             t.stockname = nvl(u.s_info_name, t.stockname);
    commit;
  
    v_eror_line := 210;
    --使用公司名称匹配
    merge into thjs.tb_ib_cust_info t
    using (select u.projid, s.s_info_code, s.s_info_name
             from thjs.tmp_ib_cust_info u
             left join wind.tcl_compintroduction c
               on c.comp_name = u.khname
           --inner join zx90.vw_wdzx_asharedescription s--v101-
           --v101+ start
            inner join (select t.s_info_windcode,
                              t.s_info_code,
                              t.s_info_name,
                              t.s_info_compcode
                         from thjs.vw_wdzx_asharedescription t
                        where not exists
                        (select 1
                                 from wind.tcl_neeqsdescription x
                                where x.s_info_compcode = t.s_info_compcode
                                  and trim(x.s_info_delistdate) is null
                                  and x.s_info_code not like 'T%')
                       union all
                       select to_char(wm_concat(x.s_info_windcode)) as s_info_windcode,
                              to_char(wm_concat(x.s_info_code)) as s_info_code,
                              to_char(wm_concat(x.s_info_name)) as s_info_name,
                              x.s_info_compcode
                         from wind.tcl_neeqsdescription x
                        where trim(x.s_info_delistdate) is null --未退市
                          and x.s_info_code not like 'T%' --未挂牌终止
                        group by x.s_info_compcode) s
           --v101+ end
               on s.s_info_compcode = c.comp_id
            where exists (select 1
                     from thjs.tb_ib_cust_info x
                    where x.projid = u.projid
                      and x.stockcode is null)) u
    on (t.projid = u.projid)
    when matched then
      update
         set t.stockcode = nvl(u.s_info_code, t.stockcode),
             t.stockname = nvl(u.s_info_name, t.stockname);
  
    commit;
  
  end if;

  --v102+ start
  --将新增加的项目类型保存至临时表中
  execute immediate 'truncate table thjs.tb_projlist_projtype_tmp';
  insert into thjs.tb_projlist_projtype_tmp
    select distinct t.projtype
      from thjs.tb_ib_cust_info t
     where not exists (select *
              from thjs.tb_projlist_busitype m
             where t.projtype = m.proj_type);
  commit;

  --把新增加的项目类型更新至 项目类型是否允许清单填报表中
  insert into thjs.tb_projlist_busitype
    (busi_type1, busi_type2, proj_type, is_allow_report)
    select substr(t.projtype, 0, instr(t.projtype, '_') - 1) busi_type1,
           substr(t.projtype,
                  instr(t.projtype, '_') + 1,
                  length(t.projtype)) busi_type2,
           t.projtype,
           '0' is_allow_report --默认 0-不允许
      from thjs.tb_projlist_projtype_tmp t
     where not exists (select 1
              from thjs.tb_projlist_busitype c
             where c.proj_type = t.projtype);
  commit;
  --v102+ end

  update thjs.tb_proc_log l
     set l.end_time  = sysdate,
         l.exec_cost = ceil((sysdate - l.start_time) * 86400)
   where l.log_id = v_log_id;

  commit;

  ------------------------
exception
  when others then
    v_sqlcode := -1 * sqlcode;
    v_err_msg := v_eror_line || '-' || sqlerrm;
    rollback;
    --记录错误日志
    thjs.p_write_error_log(i_tradedate    => i_tradedate,
                           i_exec_func_id => v_function_id,
                           i_func_own     => 'THJS',
                           i_func_name    => v_program_name,
                           i_occur_time   => sysdate,
                           i_sqlerrm      => v_err_msg,
                           i_sqlcode      => v_sqlcode,
                           i_sqlerrl      => v_error_line_num);
    --记录错误日志
    /*kingstar.pr_audit_write_errlog(v_pr_task_id, -- 任务标识
                                   0, -- 单位编号
                                   i_tradedate, -- 业务日期
                                   v_function_id, -- 功能标识
                                   v_program_name, -- 程序名
                                   v_error_line_num, -- 程序行号
                                   v_err_msg, -- 错误信息
                                   v_sqlcode, -- SQLCODE
                                   v_sqlstate -- SQLSTATE
                                   );*/
    commit;
    raise;
end;

CREATE OR REPLACE PROCEDURE "THJS"."P_USER_PROJECT_Q" (rt_cursor     out sys_refcursor, --返回游标结果集
                                                  i_username    in varchar2,
                                                  i_projname    in varchar2,
                                                  i_khname      in varchar2,
                                                  i_userpath    in varchar2, --业务组路径 //AAA/BBB/ccc
                                                  i_page_num    in number default 0, --默认值0,
                                                  i_page_size   in number default 0, --默认值0  如果i_page_num，i_page_size都为0 则不分页，查询全部
                                                  o_total_count out integer,
                                                  o_return_msg  out varchar2,
                                                  o_return_code out integer)
AS
  ----------------------------------------------------------------------------------
  --版    权：GTJA
  --版    本：1.0.0
  --开发人员：CZC@GTJA
  --创建日期：20190323
  --模块编号：
  --模块名称：投行信息查询 - 业务人员项目查询
  --功能名称：业务人员项目查询
  ----------------------------------------------------------------------------------
  --==============================================================================
  --固定变量
  v_userexp exception; -- 用户定义错
  v_tradedate    varchar2(8); -- 任务执行时间(业务日期)
  v_exec_func_id integer default '0'; -- 任务id
  v_func_own     varchar2(20) default 'thjs'; -- 任务归属用户（schema）
  v_func_name    varchar2(2000) default 'p_user_project_q'; -- 任务名称(存储过程的名字)
  v_sqlerrm      varchar2(4000); -- 错误提示信息
  v_sqlcode      number; -- 错误代码
  v_sqlerrl      varchar2(4000); -- 错误行号
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  v_page_num   number default 0;
  v_page_size  number;
  v_superuser  integer default 0;
  v_user_pcode varchar2(100);
  --v_ccode      varchar2(100);
  v_pcode    varchar2(100);
  v_userpath varchar2(1000);

  --=============================================================
  -- 业务处理过程
  --=============================================================
BEGIN

  v_tradedate := to_char(sysdate, 'yyyyMMdd');
  /*insert into thjs.tb_test
    (id, text)
  values
    (99, i_username || '-' || i_projname || '-' || i_khname);*/
  --insert into thjs.tb_test (id, text) values (99, i_userpath);

  /**********************************************************
  只有投行业务人员（全局人员） 拥有部门查询条件
  部门查询条件，作用于项目客户表部门数据列
  
  非上述人员，隐藏部门查询条件，只查询与自己相关的项目信息
  20201022- thhgz（投行合规组）及flhgb（法律合规部）具有所有项目查询权限
  ***********************************************************/

  v_userpath := i_userpath;

  --判断是否超级用户及开发人员
  select count(1)
    into v_superuser
    from (select to_char(u.user_name) as user_name
            from basic_thjs.wb_user_role r
            left join basic_thjs.wb_user u
              on u.user_id = r.user_id
           where r.role_id in ('thhgz', 'flhgb')
          union all
          select column_value
            from table(thjs.splitstr('admin,zhangqilong,yangluting,zhangyongyong',
                                         ','))) t
   where instr(',' || t.user_name || ',', ',' || i_username || ',') > 0;

  delete from thjs.TMP_USER_PROJID;
  commit;

  --获取用户所在组
  if v_superuser = 0 then
  
    select nvl(t.p_code, '')
      into v_user_pcode
      from dual
      left join thjs.vw_userinfo_tree t
        on t.ccode = i_username;
  
    insert into thjs.TMP_USER_PROJID
      (projid)
      select t.proj_id
        from THJS.IB_V_FINANCE_PROJMEMBER t
       inner join thjs.ib_v_gtja_empname e
          on e.workno = t.workno
       where e.username = i_username;
  
  else
    --超级用户或者全局人員 获取用户组选择项
    if v_userpath is not null then
    
      select substr(i_userpath, instr(i_userpath, '/', -1) + 1)
        into v_pcode
        from dual;
    
      if v_pcode is null then
        v_userpath := null;
      else
      
        insert into thjs.TMP_USER_PROJID
          (projid)
          select c.projid
            from thjs.tb_ib_cust_info c
           where c.pro_is_valid = '1'
             and exists (select 1
                    from (select t.CCODE, t.CNAME, t.P_CODE
                            from THJS.VW_CUST_INFO_TREE t
                           start with t.ccode = v_pcode
                          connect by prior t.CCODE = t.P_CODE) t
                   where t.CNAME = c.deptmananame);
      
      end if;
    end if;
  
  end if;

  if i_page_num is not null then
    v_page_num := i_page_num;
  end if;

  --统计记录条数
  if v_page_num < 1 then
  
    if v_superuser = 0 then
      select count(1)
        into o_total_count
        from thjs.tb_ib_cust_info t
       where t.pro_is_valid = '1'
         and (i_projname is null or instr(t.projname, i_projname) > 0)
         and (i_khname is null or instr(t.khname, i_khname) > 0)
         and t.projid in (select t.projid from thjs.TMP_USER_PROJID t) --用户相关， 用户所在上级下属所有
      ;
    
    else
      select count(1)
        into o_total_count
        from thjs.tb_ib_cust_info t
       where t.pro_is_valid = '1'
         and (i_projname is null or instr(t.projname, i_projname) > 0)
         and (i_khname is null or instr(t.khname, i_khname) > 0)
         and (v_userpath is null or
             t.projid in (select t.projid from thjs.TMP_USER_PROJID t)) --超级用户查询所选节点，管理人员权限待确定                         
      ;
    end if;
  
  end if;

  if i_page_size is not null and i_page_size <> 0 then
    v_page_size := i_page_size;
  else
    v_page_size := o_total_count;
  end if;

  if v_superuser = 0 then
  
    --非超级用户 根据登录用户 显示用户及用户所属组权限项目   
    open rt_cursor for
      select b.proj_id,
             b.projname,
             b.projrole,
             b.workno,
             b.empname,
             b.username,
             b.khname,
             b.khxycode,
             b.projtype,
             b.projphase,
             b.islx,
             b.deptmananame,
             b.deptmanamobile,
             b.deptname,
             b.pripid,
             b.entname,
             b.stockcode,
             b.stockname
        from (select a.*, rownum as rn
                from (select t.projid as proj_id,
                             t.projname,
                             coalesce(p.projrole, '权限用户') as projrole,
                             p.workno,
                             p.empname,
                             u.username,
                             t.khname,
                             t.khxycode,
                             t.projtype,
                             t.projphase,
                             t.islx,
                             t.deptmananame,
                             t.deptmanamobile,
                             t.deptname,
                             t.pripid,
                             t.entname,
                             t.stockcode,
                             t.stockname
                        from thjs.tb_ib_cust_info t
                       inner join thjs.ib_v_gtja_empname u
                          on u.username = i_username
                        left join thjs.ib_v_finance_projmember p
                          on p.proj_id = t.projid
                         and p.workno = u.workno
                       where t.pro_is_valid = '1'
                         and (i_projname is null or
                             instr(t.projname, i_projname) > 0)
                         and (i_khname is null or
                             instr(t.khname, i_khname) > 0)
                         and t.projid in
                             (select t.projid from thjs.TMP_USER_PROJID t) --用户相关， 用户所在上级下属所有
                      
                      ) a) b
       where rn > v_page_num
         and rn <= v_page_num + v_page_size;
  
  else
  
    --超级用户根据所选择用户组或用户 查询
    open rt_cursor for
      select b.proj_id,
             b.projname,
             b.projrole,
             b.workno,
             b.empname,
             b.username,
             b.khname,
             b.khxycode,
             b.projtype,
             b.projphase,
             b.islx,
             b.deptmananame,
             b.deptmanamobile,
             b.deptname,
             b.pripid,
             b.entname,
             b.stockcode,
             b.stockname
        from (select a.*, rownum as rn
                from (select distinct t.projid as proj_id,
                                      t.projname,
                                      '超级用户' as projrole,
                                      '' as workno,
                                      '' as empname,
                                      i_username as username,
                                      t.khname,
                                      t.khxycode,
                                      t.projtype,
                                      t.projphase,
                                      t.islx,
                                      t.deptmananame,
                                      t.deptmanamobile,
                                      t.deptname,
                                      t.pripid,
                                      t.entname,
                                      t.stockcode,
                                      t.stockname
                        from thjs.tb_ib_cust_info t
                       where t.pro_is_valid = '1'
                         and (i_projname is null or
                             instr(t.projname, i_projname) > 0)
                         and (i_khname is null or
                             instr(t.khname, i_khname) > 0)
                         and (v_userpath is null or
                             t.projid in
                             (select t.projid from thjs.TMP_USER_PROJID t)) --超级用户查询所选节点，管理人员权限待确定                             
                      ) a) b
       where rn > v_page_num
         and rn <= v_page_num + v_page_size;
  
  end if;

  commit;

  o_return_msg  := '执行成功';
  o_return_code := 0;

exception
  -- 非预定义异常处理
  when v_userexp then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    thjs.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
    -- 预定义异常处理
  when others then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    thjs.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
end;

Create or Replace PROCEDURE "THJS"."P_USER_PROJECT_REFRESH" (i_tradedate in char)
/*==============================================================================
  版 本    : 1.0.0
  创建人   : czc
  模块编号 : 0
  日 期    : 2019-11-04
  功能描述 : 投行数据集市 投行系统 业务人员项目信息-实时刷新
  ==============================================================================*/
 as
  v_sqlcode  integer default 0;
  v_sqlstate char(5) default '';
  --v_errcode        integer default 0;
  --v_errstate       char(5) default '';
  v_err_msg varchar2(128) default '';
  --v_not_found      integer default 0;
  --v_last_time      char(8);
  v_function_id    integer default 0; --定义存储过程模块编号
  v_error_line_num integer default 0; --错误行号
  --v_error_level    integer default 0; --错误级别
  v_function_desc varchar2(50) default '业务人员项目信息'; --功能描述
  v_program_name  char(40) default 'p_user_project_refresh'; --程序名
  v_pr_task_id    number default 0; --任务标示
  -- =======================================================================================================================
  -- 定义业务变量
  -- =======================================================================================================================
  v_count integer default 0;
  -- =======================================================================================================================
  -- 业务开始
  -- =======================================================================================================================
begin

  --投行客户项目信息-对接工商主体落地

  delete from thjs.tmp_thdb_cust_info c;
  commit;
  insert into thjs.tmp_thdb_cust_info
    (khname,
     projid,
     projname,
     projtype,
     projphase,
     islx,
     khxycode,
     assdeptcode,
     assdeptname,
     deptmanacode,
     deptmananame,
     deptmanamobile,
     deptname,
     deptcode)
    select t.khname,
           t.projid,
           t.projname,
           t.projtype,
           t.projphase,
           t.islx,
           t.khxycode,
           t.assdeptcode,
           t.assdeptname,
           t.deptmanacode,
           t.deptmananame,
           t.deptmanamobile,
           t.deptname,
           t.deptcode
      from thjs.vw_thdb_cust_info t
     where not exists
     (select 1 from thjs.tb_thdb_cust_info c where c.projid = t.projid);
  commit;
  insert into thjs.tb_thdb_cust_info
    (khname,
     projid,
     projname,
     projtype,
     projphase,
     islx,
     khxycode,
     assdeptcode,
     assdeptname,
     deptmanacode,
     deptmananame,
     deptmanamobile,
     deptname,
     deptcode)
    select c.khname,
           c.projid,
           c.projname,
           c.projtype,
           c.projphase,
           c.islx,
           c.khxycode,
           c.assdeptcode,
           c.assdeptname,
           c.deptmanacode,
           c.deptmananame,
           c.deptmanamobile,
           c.deptname,
           c.deptcode
      from thjs.tmp_thdb_cust_info c;
  commit;

  select count(1)
    into v_count
    from dual
    left join zx90.tcl_asharedescription t
      on t.s_info_code is not null
   where rownum < 10;

  if v_count > 1 then
  
    --股票股票代码，名称匹配； 证券代码使用wind证券代码
    --使用统一社会信用代码匹配
    merge into thjs.tb_thdb_cust_info t
    using (select u.projid, s.s_info_code, s.s_info_name
             from thjs.tmp_thdb_cust_info u
             left join zx90.tcl_compintroduction c
               on c.registernumber = u.khxycode
            inner join zx90.vw_wdzx_asharedescription s
               on s.s_info_compcode = c.comp_id) u
    on (t.projid = u.projid)
    when matched then
      update set t.stockcode = u.s_info_code, t.stockname = u.s_info_name;
    commit;
  
    --使用公司名称匹配
    merge into thjs.tb_thdb_cust_info t
    using (select u.projid, s.s_info_code, s.s_info_name
             from thjs.tmp_thdb_cust_info u
             left join zx90.tcl_compintroduction c
               on c.comp_name = u.khname
            inner join zx90.vw_wdzx_asharedescription s
               on s.s_info_compcode = c.comp_id
            where exists (select 1
                     from thjs.tb_thdb_cust_info x
                    where x.projid = u.projid
                      and x.stockcode is null)) u
    on (t.projid = u.projid)
    when matched then
      update set t.stockcode = u.s_info_code, t.stockname = u.s_info_name;
  
    commit;
  
  end if;

  ------------------------
exception
  when others then
    v_sqlcode := -1 * sqlcode;
    v_err_msg := sqlerrm;
    rollback;
    --记录错误日志
    kingstar.pr_audit_write_errlog(v_pr_task_id, -- 任务标识
                                   0, -- 单位编号
                                   i_tradedate, -- 业务日期
                                   v_function_id, -- 功能标识
                                   v_program_name, -- 程序名
                                   v_error_line_num, -- 程序行号
                                   v_err_msg, -- 错误信息
                                   v_sqlcode, -- SQLCODE
                                   v_sqlstate -- SQLSTATE
                                   );
    commit;
    raise;
end;

Create or Replace procedure "THJS"."P_USER_PROJECT_UQ" (rt_cursor     out sys_refcursor, --返回游标结果集
                                                   i_username    in varchar2,
                                                   i_projname    in varchar2,
                                                   i_khname      in varchar2,
                                                   i_busi_type   in varchar2,
                                                   i_page_num    in number default 0, --默认值0,
                                                   i_page_size   in number default 0, --默认值0  如果i_page_num，i_page_size都为0 则不分页，查询全部
                                                   o_total_count out integer,
                                                   o_return_msg  out varchar2,
                                                   o_return_code out integer) is
  ----------------------------------------------------------------------------------
  --版    权：GTJA
  --版    本：1.0.0
  --开发人员：CZC@GTJA
  --创建日期：20190705
  --模块编号：
  --模块名称：投行信息查询 - 业务人员项目查询 我的项目
  --功能名称：业务人员项目查询
  ----------------------------------------------------------------------------------
  --==============================================================================
  --固定变量
  v_userexp exception; -- 用户定义错
  v_tradedate    varchar2(8); -- 任务执行时间(业务日期)
  v_exec_func_id integer default '0'; -- 任务id
  v_func_own     varchar2(20) default 'thjs'; -- 任务归属用户（schema）
  v_func_name    varchar2(2000) default 'p_user_project_uq'; -- 任务名称(存储过程的名字)
  v_sqlerrm      varchar2(4000); -- 错误提示信息
  v_sqlcode      number; -- 错误代码
  v_sqlerrl      varchar2(4000); -- 错误行号
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  v_page_num  number default 0;
  v_page_size number;
  v_superuser integer default 0;
  --=============================================================
  -- 业务处理过程
  --=============================================================

begin

  v_tradedate := to_char(sysdate, 'yyyyMMdd');

  /*insert into thjs.tb_test
    (id, text)
  values
    (99, i_username || '-' || i_projname || '-' || i_khname);*/

  --判断是否超级用户及开发人员
  select count(1)
    into v_superuser
    from table(thjs.splitstr('admin,yangluting,zhangyongyong', ',')) t
   where instr(',' || t.column_value || ',', ',' || i_username || ',') > 0;

  if i_page_num is not null then
    v_page_num := i_page_num;
  end if;

  --统计记录条数
  if v_page_num < 1 then
  
    select count(1)
      into o_total_count
      from thjs.tb_ib_cust_info t
     inner join thjs.ib_v_finance_projmember p
        on p.proj_id = t.projid
   --  inner join thjs.ib_v_gtja_empname u
    inner join ehr01.tcl_v_emp_info_hgfk u
        on u.ehr_id = p.workno
     where t.pro_is_valid = '1'
       and (i_projname is null or instr(t.projname, i_projname) > 0)
       and (i_khname is null or instr(t.khname, i_khname) > 0)
       and (u.ehr_id = i_username or v_superuser > 0 or u.oa_code = i_username)
       and (i_busi_type is null or t.projtype = i_busi_type);
  end if;

  if i_page_size is not null and i_page_size <> 0 then
    v_page_size := i_page_size;
  else
    v_page_size := o_total_count;
  end if;

  --显示用户权限项目   
  open rt_cursor for
    select b.proj_id,
           b.projname,
           b.projrole,
           b.workno,
           b.empname,
           b.username,
           b.khname,
           b.khxycode,
           b.projtype,
           b.projphase,
           b.islx,
           b.deptmananame,
           b.deptmanamobile,
           b.deptname,
           b.pripid,
           b.entname,
           b.stockcode,
           b.stockname
      from (select a.*, rownum as rn
              from (select t.projid as proj_id,
                           t.projname,
                           p.projrole,
                           p.workno,
                           p.empname,
                           u.ehr_id username,
                           t.khname,
                           t.khxycode,
                           t.projtype,
                           t.projphase,
                           t.islx,
                           t.deptmananame,
                           t.deptmanamobile,
                           t.deptname,
                           t.pripid,
                           t.entname,
                           t.stockcode,
                           t.stockname
                      from thjs.tb_ib_cust_info t
                     inner join thjs.ib_v_finance_projmember p
                        on p.proj_id = t.projid
               --      inner join thjs.ib_v_gtja_empname u
                  inner join ehr01.tcl_v_emp_info_hgfk u
                        on u.ehr_id = p.workno
                     where t.pro_is_valid = '1'
                       and (i_projname is null or
                           instr(t.projname, i_projname) > 0)
                       and (i_khname is null or instr(t.khname, i_khname) > 0)
                       and (u.ehr_id = i_username or v_superuser > 0 or u.oa_code = i_username) --用户相关
                       and (i_busi_type is null or t.projtype = i_busi_type)
                    
                    ) a) b
     where rn > v_page_num
       and rn <= v_page_num + v_page_size;

  commit;

  o_return_msg  := '执行成功';
  o_return_code := 0;

exception
  -- 非预定义异常处理
  when v_userexp then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    thjs.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
    -- 预定义异常处理
  when others then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    thjs.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
end;

Create or Replace procedure "THJS"."P_USER_PROJECT_UQ_YLT" (rt_cursor     out sys_refcursor, --返回游标结果集
                                                       i_username    in varchar2,
                                                       i_projname    in varchar2,
                                                       i_khname      in varchar2,
                                                       i_busi_type   in varchar2,
                                                       i_page_num    in number default 0, --默认值0,
                                                       i_page_size   in number default 0, --默认值0  如果i_page_num，i_page_size都为0 则不分页，查询全部
                                                       o_total_count out integer,
                                                       o_return_msg  out varchar2,
                                                       o_return_code out integer) is
  ----------------------------------------------------------------------------------
  --版    权：GTJA
  --版    本：1.0.0
  --开发人员：CZC@GTJA
  --创建日期：20190705
  --模块编号：
  --模块名称：投行信息查询 - 业务人员项目查询 我的项目
  --功能名称：业务人员项目查询
  ----------------------------------------------------------------------------------
  --==============================================================================
  --固定变量
  v_userexp exception; -- 用户定义错
  v_tradedate    varchar2(8); -- 任务执行时间(业务日期)
  v_exec_func_id integer default '0'; -- 任务id
  v_func_own     varchar2(20) default 'thjs'; -- 任务归属用户（schema）
  v_func_name    varchar2(2000) default 'p_user_project_uq'; -- 任务名称(存储过程的名字)
  v_sqlerrm      varchar2(4000); -- 错误提示信息
  v_sqlcode      number; -- 错误代码
  v_sqlerrl      varchar2(4000); -- 错误行号
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  v_page_num  number default 0;
  v_page_size number;
  v_superuser integer default 0;
  --=============================================================
  -- 业务处理过程
  --=============================================================

begin

  v_tradedate := to_char(sysdate, 'yyyyMMdd');

  /*insert into thjs.tb_test
    (id, text)
  values
    (99, i_username || '-' || i_projname || '-' || i_khname);*/

  --判断是否超级用户及开发人员
  select count(1)
    into v_superuser
    from table(kingstar.splitstr('admin,yangluting,zhangyongyong', ',')) t
   where instr(',' || t.column_value || ',', ',' || i_username || ',') > 0;

  if i_page_num is not null then
    v_page_num := i_page_num;
  end if;

  --统计记录条数
  if v_page_num < 1 then
  
    select count(1)
      into o_total_count
      from thjs.tb_ib_cust_info t
     inner join thjs.ib_v_finance_projmember p
        on p.proj_id = t.projid
     inner join thjs.ib_v_gtja_empname u
        on u.workno = p.workno
     where (i_projname is null or instr(t.projname, i_projname) > 0)
       and (i_khname is null or instr(t.khname, i_khname) > 0)
       and (u.username = i_username or v_superuser > 0)
       and (i_busi_type is null or t.projtype = i_busi_type);
  end if;

  if i_page_size is not null and i_page_size <> 0 then
    v_page_size := i_page_size;
  else
    v_page_size := o_total_count;
  end if;

  --显示用户权限项目   
  open rt_cursor for
    select b.proj_id,
           b.projname,
           b.projrole,
           b.workno,
           b.empname,
           b.username,
           b.khname,
           b.khxycode,
           b.projtype,
           b.projphase,
           b.islx,
           b.deptmananame,
           b.deptmanamobile,
           b.deptname,
           b.pripid,
           b.entname,
           b.stockcode,
           b.stockname
      from (select a.*, rownum as rn
              from (select t.projid as proj_id,
                           t.projname,
                           p.projrole,
                           p.workno,
                           p.empname,
                           u.username,
                           t.khname,
                           t.khxycode,
                           t.projtype,
                           t.projphase,
                           t.islx,
                           t.deptmananame,
                           t.deptmanamobile,
                           t.deptname,
                           t.pripid,
                           t.entname,
                           t.stockcode,
                           t.stockname
                      from thjs.tb_ib_cust_info t
                     inner join thjs.ib_v_finance_projmember p
                        on p.proj_id = t.projid
                     inner join thjs.ib_v_gtja_empname u
                        on u.workno = p.workno
                     where (i_projname is null or
                           instr(t.projname, i_projname) > 0)
                       and (i_khname is null or instr(t.khname, i_khname) > 0)
                       and (u.username = i_username or v_superuser > 0) --用户相关
                       and (i_busi_type is null or t.projtype = i_busi_type)
                    
                    ) a) b
     where rn > v_page_num
       and rn <= v_page_num + v_page_size;

  commit;

  o_return_msg  := '执行成功';
  o_return_code := 0;

exception
  -- 非预定义异常处理
  when v_userexp then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    hgman.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
    -- 预定义异常处理
  when others then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    hgman.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
end;

Create or Replace procedure "THJS"."P_USER_PROJLIST" (rt_cursor     out sys_refcursor, --返回游标结果集
                                                 i_username    in varchar2,
                                                 i_projname    in varchar2,
                                                 i_khname      in varchar2,
                                                 o_return_msg  out varchar2,
                                                 o_return_code out integer) is
  ----------------------------------------------------------------------------------
  --版    权：GTJA
  --版    本：1.0.0
  --开发人员：CZC@GTJA
  --创建日期：20190426
  --模块编号：
  --模块名称：投行信息查询 - 业务人员项目列表查询
  --功能名称：业务人员项目列表查询
  ----------------------------------------------------------------------------------
  --==============================================================================
  --固定变量
  v_userexp exception; -- 用户定义错
  v_tradedate    varchar2(8); -- 任务执行时间(业务日期)
  v_exec_func_id integer default '0'; -- 任务id
  v_func_own     varchar2(20) default 'thjs'; -- 任务归属用户（schema）
  v_func_name    varchar2(2000) default 'p_user_projlist'; -- 任务名称(存储过程的名字)
  v_sqlerrm      varchar2(4000); -- 错误提示信息
  v_sqlcode      number; -- 错误代码
  v_sqlerrl      varchar2(4000); -- 错误行号
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  v_superuser  integer default 0;
  v_user_pcode varchar2(100);
  --v_ccode      varchar2(100);
  v_pcode varchar2(100);
  --v_isleaf     integer default 0;

  --=============================================================
  -- 业务处理过程
  --=============================================================

begin

  v_tradedate := to_char(sysdate, 'yyyyMMdd');

  --判断是否超级用户
  select count(1)
    into v_superuser
    from table(thjs.splitstr('admin,zhangqilong', ',')) t
   where instr(',' || t.column_value || ',', ',' || i_username || ',') > 0;

  delete from thjs.TMP_USER_PROJID;
  commit;
  --获取用户所在组
  if v_superuser = 0 then
    /*select t.p_code
     into v_user_pcode
     from thjs.vw_userinfo_tree t
    where t.ccode = i_username;*/
  
    insert into thjs.TMP_USER_PROJID
      (projid)
      select t.proj_id
        from THJS.IB_V_FINANCE_PROJMEMBER t
       inner join thjs.ib_v_gtja_empname e
          on e.workno = t.workno
       where e.emp_name = i_username
         and t.projrole = '项目负责人'; --只有项目负责人可以进行清单填报
    /*where exists (select *
     from thjs.vw_userinfo_tree_root r
    where r.root_code = v_user_pcode
      and r.ccode = e.username);*/
  
  end if;

  if v_superuser = 0 then
  
    --非超级用户 根据登录用户 显示用户及用户所属组权限项目   
    open rt_cursor for
      select t.projid as proj_id, t.projname, t.khname
        from thjs.tb_ib_cust_info t
       where (i_projname is null or instr(t.projname, i_projname) > 0)
         and (i_khname is null or instr(t.khname, i_khname) > 0)
         and t.projid in (select t.projid from thjs.TMP_USER_PROJID t) --用户相关， 用户所在上级下属所有
      ;
  
  else
  
    --超级用户根据所选择用户组或用户 查询
    open rt_cursor for
      select t.projid as proj_id, t.projname, t.khname
        from thjs.tb_ib_cust_info t
       where (i_projname is null or instr(t.projname, i_projname) > 0)
         and (i_khname is null or instr(t.khname, i_khname) > 0) --超级用户查询所选节点，管理人员权限待确定                             
      ;
  
  end if;

  commit;

  o_return_msg  := '执行成功';
  o_return_code := 0;

exception
  -- 非预定义异常处理
  when v_userexp then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    thjs.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
    -- 预定义异常处理
  when others then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    thjs.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
end;

Create or Replace procedure "THJS"."P_USER_TREE_Q" (o_sql out clob, --返回游标结果集
                                               --i_flag        in varchar2, --树结构标志,
                                               o_return_code out integer,
                                               o_return_msg  out varchar2) is
  ----------------------------------------------------------------------------------
  --版    权：GTJA
  --版    本：1.0.0
  --开发人员：CZC@GTJA
  --创建日期：20190411
  --模块编号：
  --模块名称：投行信息查询 - 获取投行部门组树形结构
  --功能名称：
  ----------------------------------------------------------------------------------
  --==============================================================================
  --固定变量
  v_userexp exception; -- 用户定义错
  v_tradedate    varchar2(8); -- 任务执行时间(业务日期)
  v_exec_func_id integer default '0'; -- 任务id
  v_func_own     varchar2(20) default 'thjs'; -- 任务归属用户（schema）
  v_func_name    varchar2(2000) default 'p_user_tree_q'; -- 任务名称(存储过程的名字)
  v_sqlerrm      varchar2(4000); -- 错误提示信息
  v_sqlcode      number; -- 错误代码
  v_sqlerrl      varchar2(4000); -- 错误行号
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  v_sql     clob;
  v_nodesql varchar2(500);
  v_level   integer default 0;
  v_count   integer default 0;
  v_close   varchar2(100);
  --=============================================================
  -- 业务处理过程
  --=============================================================

begin

  --if i_flag = 1 then

  v_sql := '{"fileName":"Root"'; --"children":[{"path":"","filename":"","text":"全部",cls":"wb_pointer","leaf":true,"inframe":true}

  for node in (select '{"path":"","filename":"","text":"全部","cls":"wb_pointer","leaf":true,"inframe":true' as node,
                      '' as path,
                      '' as filenmae,
                      '' as p_filename,
                      '全部' as TEXT,
                      1 as nodelevel,
                      1 as isleaf
                 from dual
               union all
               select '{"path":"' ||
                      ltrim(sys_connect_by_path(t.ccode, '/'), '/') ||
                      '","filename":"' || t.ccode || '","text":"' || t.cname ||
                      '","cls":"wb_pointer","leaf":' ||
                      decode(connect_by_isleaf, 0, 'false', 'true') ||
                      ',"inframe":true' as node,
                      ltrim(sys_connect_by_path(t.ccode, '/'), '/') as path,
                      t.ccode as filename,
                      prior t.ccode as p_filename,
                      t.cname as text,
                      level as nodelevel,
                      connect_by_isleaf as isleaf
                 from (select distinct CCODE, CNAME, P_CODE --投行客户项目有关的组织结构树
                         from thjs.vw_userinfo_tree t
                        start with exists
                        (select 1
                                      from thjs.thdb_v_cust_info c
                                     where c.deptname = t.cname)
                       connect by t.ccode = prior t.p_code
                       /*union
                       select CCODE, CNAME, P_CODE
                         from thjs.vw_userinfo_tree t
                        start with exists
                        (select 1
                                      from thjs.thdb_v_cust_info c
                                     where c.deptmananame = t.cname)
                       connect by t.ccode = prior t.p_code*/
                       ) t
                where t.ccode is not null
                start with t.p_code = '-1'
                        or t.p_code is null
               connect by prior t.ccode = t.p_code) loop
  
    if node.nodelevel >= v_level then
      --子节点
    
      if node.isleaf = 1 then
        if node.nodelevel = v_level then
          v_nodesql := ',' || node.node || '}'; --子节点同级别，闭合
        else
          v_nodesql := ',"children":[' || node.node || '}'; --非自己的内部循环
        end if;
      else
        if node.nodelevel = v_level then
          v_nodesql := ',' || node.node; --同级别新循环开始
        else
          v_nodesql := ',"children":[' || node.node; --子节点循环跳出，
        end if;
      end if;
    
    else
      --跳出前一个树形后，判断后续节点维度，决定闭环的数量
      v_count := v_level - node.nodelevel;
    
      select listagg(']}', '') within group(order by null)
        into v_close
        from dual
      connect by level <= v_count;
    
      if node.isleaf = 1 then
        v_nodesql := v_close || ',' || node.node || '}';
      else
        v_nodesql := v_close || ',' || node.node;
      end if;
    end if;
  
    dbms_output.put_line(v_nodesql);
    v_sql   := v_sql || v_nodesql;
    v_level := node.nodelevel;
  
  end loop;

  --判断最后结束的树形层级，决定闭环的数量
  v_count := v_level;

  select listagg(']}', '') within group(order by null)
    into v_close
    from dual
  connect by level <= v_count;

  v_sql := v_sql || v_close;

  o_sql := v_sql;

  /*'{"fileName":"Root","children":
                [{"path":"8BA7BBB3DC4A43B6A1E90CCE616AE5ED","fileName":"8BA7BBB3DC4A43B6A1E90CCE616AE5ED","children":
                   [{"path":"8BA7BBB3DC4A43B6A1E90CCE616AE5ED/liuguifang","fileName":"liuguifang","text":"刘桂芳","cls":"wb_pointer","leaf":true,"inframe":true}],
                  "text":"高级管理人员","cls":"wb_pointer","inframe":false},
                 {"path":"B5BE3830787C443AA88979FC95743163","fileName":"8BA7BBB3DC4A43B6A1E90CCE616AE5ED","children":
                   [{"path":"B5BE3830787C443AA88979FC95743163/119B6AB06A494D94B134729CC64BA4C1","fileName":"119B6AB06A494D94B134729CC64BA4C1","children":
                      [{"path":"B5BE3830787C443AA88979FC95743163/119B6AB06A494D94B134729CC64BA4C1/12AF9026415D4D0C93B16158F92EA2D4","fileName":"12AF9026415D4D0C93B16158F92EA2D4","text":"彭凯组","cls":"wb_pointer","leaf":true,"inframe":true}],
                   "text":"投资银行部","cls":"wb_pointer","inframe":true}],
                  "text":"投行业务委员会","cls":"wb_pointer","inframe":false}
                ]}'  
  
  
   select '{"path":"' ||
          ltrim(sys_connect_by_path(t.ccode, '/'), '/') ||
          '","filename":"' || t.ccode || '","text":"' || t.cname ||
          '","cls":"wb_pointer","leaf":' ||
          decode(connect_by_isleaf, 0, 'false', 'true') ||
          ',"inframe":true' as node,
          ltrim(sys_connect_by_path(t.ccode, '/'), '/') as path,
          t.ccode as filename,
          prior t.ccode as p_filename,
          t.cname as text,
          level as nodelevel,
          connect_by_isleaf as isleaf
     from (select t.dept_id     as ccode,
                  t.dept_name   as cname,
                  t.dept_par_id as p_code
             from THJS.THDB_V_FINANCE_DEPT_INFO t) t
    where t.ccode is not null
    start with t.p_code = 'B5BE3830787C443AA88979FC95743163'
   connect by prior t.ccode = t.p_code
  
  select '{"path":"' ||
          ltrim(sys_connect_by_path(t.ccode, '/'), '/') ||
          '","filename":"' || t.ccode || '","text":"' || t.cname ||
          '","cls":"wb_pointer","leaf":' ||
          decode(connect_by_isleaf, 0, 'false', 'true') ||
          ',"inframe":true' as node,
          ltrim(sys_connect_by_path(t.ccode, '/'), '/') as path,
          t.ccode as filename,
          prior t.ccode as p_filename,
          t.cname as text,
          level as nodelevel,
          connect_by_isleaf as isleaf
     from (select t.ccode, t.cname, t.p_code, 2 as torder
             from thjs.vw_userinfo_tree t
            where t.ccode is not null) t
    where t.ccode is not null
    start with t.p_code = '-1'
            or t.p_code is null
   connect by prior t.ccode = t.p_code  
  */
  --end if;

  commit;

  o_return_msg  := '执行成功';
  o_return_code := 0;

exception
  -- 非预定义异常处理
  when v_userexp then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    thjs.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
    -- 预定义异常处理
  when others then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    thjs.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
end;

Create or Replace PROCEDURE "THJS"."P_WIND_ASHAREFINDERIVATIVE" (i_tradedate in char)
/*==============================================================================
  版 本    : 1.0.0
  创建人   : czc
  模块编号 : 0
  日 期    : 2019-07-03
  功能描述 : 投行数据集市 投行系统 WIND资讯资产负债表拉平
  ==============================================================================*/
 as
  v_sqlcode  integer default 0;
  v_sqlstate char(5) default '';
  --v_errcode        integer default 0;
  --v_errstate       char(5) default '';
  v_err_msg varchar2(128) default '';
  --v_not_found      integer default 0;
  --v_last_time      char(8);
  v_function_id    integer default 0; --定义存储过程模块编号
  v_error_line_num integer default 0; --错误行号
  --v_error_level    integer default 0; --错误级别
  v_function_desc varchar2(50) default 'WIND资讯财务指标表拉平'; --功能描述
  v_program_name  char(40) default 'p_wind_asharefinderivative'; --程序名
  v_pr_task_id    number default 0; --任务标示
  -- =======================================================================================================================
  -- 定义业务变量
  -- =======================================================================================================================
  v_flag    char(1);
  v_sql     varchar2(20000);
  v_cols    varchar2(5000);
  v_periods varchar2(10000);
  -- =======================================================================================================================
  -- 业务开始
  -- =======================================================================================================================
begin

  --每日8点dblink全量采集
  select case
           when t.TABLE_NAME is null then
            '0'
           else
            '1'
         end
    into v_flag
    from dual
    left join all_tables t
      on t.OWNER = 'THJS'
     and t.TABLE_NAME = 'TB_WIND_FINANCIALDERIVATIVE';

  if v_flag = '1' then
    execute immediate 'drop table thjs.tb_wind_financialderivative';
  end if;

  select to_char(wm_concat(lower(c.column_name)))
    into v_cols
    from all_tab_cols c
   where c.owner = 'ZX90'
     and c.table_name = 'TCL_ASHAREFINANCIALDERIVATIVE'
     and c.COLUMN_NAME <> 'INTERVAL_LENGTH' --移除非指标数据number列
     and c.data_type = 'NUMBER';

  select xmlagg(xmlparse(content '''' || b.report_period || ''' as "' || b.report_period || '",' wellformed) order by b.report_period desc)
         .getclobval()
    into v_periods
    from (select distinct b.enddate as report_period
            from zx90.tcl_asharefinancialderivative b) b;

  v_periods := rtrim(v_periods, ',');

  v_sql := 'create table thjs.tb_wind_financialderivative as 
            with financialindicator as
             (select c.column_name,
                     c.comments,
                     c.column_id,
                     s.s_info_compcode,
                     s.report_period,
                     t.indexvalue
                from (select c.column_name, cc.comments, c.column_id
                        from all_tab_cols c
                        left join all_col_comments cc
                          on cc.owner = c.owner
                         and cc.table_name = c.table_name
                         and cc.column_name = c.column_name
                       where c.owner = ''ZX90''
                         and c.table_name = ''TCL_ASHAREFINANCIALDERIVATIVE''
                         and c.column_name <> ''INTERVAL_LENGTH''
                         and c.data_type =''NUMBER'') c
                left join (select distinct s.s_info_compcode, s.enddate as report_period
                            from thjs.vw_wind_financialderivative s) s
                  on 1 = 1
                left join (select * from thjs.vw_wind_financialderivative t unpivot(indexvalue for indexname in(' ||
           v_cols ||
           '))) t
                  on t.s_info_compcode = s.s_info_compcode
                 and t.enddate = s.report_period
                 and t.indexname = c.column_name
               order by c.column_id)
            select *
              from (select b.column_name,
                           b.comments        as column_title,
                           b.column_id,
                           b.s_info_compcode as wind_compcode,
                           b.report_period,
                           b.indexvalue
                      from financialindicator b)
            pivot (sum(indexvalue) for report_period in(' ||
           v_periods || ')) b
             order by b.column_id';

  --dbms_output.put_line(v_sql);

  execute immediate v_sql;

  execute immediate 'create index thjs.idx_wind_financialderivative on thjs.tb_wind_financialderivative (wind_compcode)';

  commit;

  ------------------------
exception
  when others then
    v_sqlcode := -1 * sqlcode;
    v_err_msg := sqlerrm;
    rollback;
    --记录错误日志
    kingstar.pr_audit_write_errlog(v_pr_task_id, -- 任务标识
                                   0, -- 单位编号
                                   i_tradedate, -- 业务日期
                                   v_function_id, -- 功能标识
                                   v_program_name, -- 程序名
                                   v_error_line_num, -- 程序行号
                                   v_err_msg, -- 错误信息
                                   v_sqlcode, -- SQLCODE
                                   v_sqlstate -- SQLSTATE
                                   );
    commit;
    raise;
end;

