Create or Replace PROCEDURE "THJS"."P_ZTGS_CACHE" (i_tradedate in char)
/*==============================================================================
  版 本    : 1.0.0
  创建人   : czc
  模块编号 : 0
  日 期    : 2019-03-22
  功能描述 : 投行数据集市 涉及工商信息查询的数据绑定 非实时盘后数据
  ==============================================================================*/
 as
  v_sqlcode  integer default 0;
  v_sqlstate char(5) default '';
  --v_errcode        integer default 0;
  --v_errstate       char(5) default '';
  v_err_msg varchar2(128) default '';
  --v_not_found      integer default 0;
  --v_last_time      char(8);
  v_function_id    integer default 0; --定义存储过程模块编号
  v_error_line_num integer default 0; --错误行号
  --v_error_level    integer default 0; --错误级别
  v_function_desc varchar2(50) default '业务人员关注公司政通工商映射落地'; --功能描述
  v_program_name  char(40) default 'p_user_focus'; --程序名
  v_pr_task_id    number default 0; --任务标示
  -- =======================================================================================================================
  -- 定义业务变量
  -- =======================================================================================================================
  v_tradedate varchar2(8);
  -- =======================================================================================================================
  -- 业务开始
  -- =======================================================================================================================
begin

  v_tradedate := i_tradedate;

  execute immediate 'truncate table thjs.tb_cxdd_ashareanency';

  insert into thjs.tb_cxdd_ashareanency
    (busi_date,
     s_info_windcode,
     market,
     stock_code,
     stock_name,
     comp_code,
     comp_name,
     pripid,
     entname,
     regno,
     credit_code)
    select t.busi_date,
           t.s_info_windcode,
           t.s_info_exchmarket,
           t.s_info_code,
           t.s_info_name,
           t.s_info_compcode,
           c.comp_name,
           e.pripid,
           e.entname,
           e.regno,
           e.credit_code
      from zx90.tcl_asharedescription t
     inner join zx90.tcl_compintroduction c
        on c.comp_id = t.s_info_compcode
     inner join ztgs.enterprisebaseinfocollect e
        on e.credit_code = c.registernumber
     where t.s_info_windcode in
           (select distinct t1.s_info_windcode
              from zx90.tcl_ashareagency t1
             where t1.s_agency_nameid = '2024680');

  commit;

  execute immediate 'truncate table thjs.tb_cxdd_cbondanency';
  insert into thjs.tb_cxdd_cbondanency
    (busi_date,
     s_info_windcode,
     market,
     bond_code,
     bond_name,
     issuer_code,
     issuer_name,
     pripid,
     entname,
     regno,
     credit_code)
    select t.busi_date,
           t.s_info_windcode,
           t.s_info_exchmarket,
           substr(t.s_info_windcode, 0, instr(t.s_info_windcode, '.') - 1) as bond_code,
           t.s_info_name,
           t.b_info_issuercode,
           c.comp_name,
           e.pripid,
           e.entname,
           e.regno,
           e.credit_code
      from zx90.tcl_cbonddescription t
      left join zx90.tcl_compintroduction c
        on c.comp_id = t.b_info_issuercode
      left join ztgs.enterprisebaseinfocollect e
        on e.credit_code = c.registernumber
     where t.s_info_windcode in
           (select t1.b_info_windcode
              from zx90.tcl_cbondagency t1
             where t1.b_agency_nameid = '2024680');

  commit;

  --对持续督导，项目信息中涉及的主体进行缓存
  --其余主体在查询时计算 并计入缓存
  --提前执行一次，每日工商数据更新后，会通过任务再执行一次
  thjs.p_comp_cache_task(i_tradedate => v_tradedate);

  ------------------------
exception
  when others then
    v_sqlcode := -1 * sqlcode;
    v_err_msg := sqlerrm;
    rollback;
    --记录错误日志
    kingstar.pr_audit_write_errlog(v_pr_task_id, -- 任务标识
                                   0, -- 单位编号
                                   i_tradedate, -- 业务日期
                                   v_function_id, -- 功能标识
                                   v_program_name, -- 程序名
                                   v_error_line_num, -- 程序行号
                                   v_err_msg, -- 错误信息
                                   v_sqlcode, -- SQLCODE
                                   v_sqlstate -- SQLSTATE
                                   );
    commit;
    raise;
end;

