Create or Replace PROCEDURE "THJS"."P_ZTGS_DATA_DAILY" (i_tradedate in char)
/*==============================================================================
  版 本    : 1.0.0
  创建人   : czc
  模块编号 : 0
  日 期    : 2019-01-21
  功能描述 : 投行数据集市 政通工商数据日增量转换
  ==============================================================================*/
 as
  v_sqlcode  integer default 0;
  v_sqlstate char(5) default '';
  --v_errcode        integer default 0;
  --v_errstate       char(5) default '';
  v_err_msg varchar2(128) default '';
  --v_not_found      integer default 0;
  --v_last_time      char(8);
  v_function_id    integer default 0; --定义存储过程模块编号
  v_error_line_num integer default 0; --错误行号
  --v_error_level    integer default 0; --错误级别
  v_function_desc varchar2(50) default '政通工商数据日增量转换'; --功能描述
  v_program_name  char(40) default 'p_ztgs_data_daily'; --程序名
  v_pr_task_id    number default 0; --任务标示
  -- =======================================================================================================================
  -- 定义业务变量
  -- =======================================================================================================================

  -- =======================================================================================================================
  -- 业务开始
  -- =======================================================================================================================
begin

  --从每日增量表转换至全量表
  --各表按对应的ID删除旧表数据，重新插入增量表数据

  --企业主体表
  delete from ztgs.enterprisebaseinfocollect e
   where exists (select 1
            from ztgs.enterprisebaseinfocollect_tmp t
           where t.pripid = e.pripid);
  insert into ztgs.enterprisebaseinfocollect
    select * from ztgs.enterprisebaseinfocollect_tmp t;
  commit;

  --同步名称索引
  ctx_ddl.sync_index('ztgs.idx_enterprisebaseinfo_t');

  --企业人员表
  delete from ztgs.e_pri_person e
   where exists
   (select 1 from ztgs.e_pri_person_tmp t where t.pripid = e.pripid);
  insert into ztgs.e_pri_person
    select * from ztgs.e_pri_person_tmp t;
  commit;

  --企业股东表
  delete from ztgs.e_inv_investment e
   where exists (select 1
            from ztgs.e_inv_investment_tmp t
           where t.pripid = e.pripid);
  insert into ztgs.e_inv_investment
    select * from ztgs.e_inv_investment_tmp t;
  commit;

  --企业变更表
  delete from ztgs.e_alter_recoder e
   where exists
   (select 1 from ztgs.e_alter_recoder_tmp t where t.pripid = e.pripid);
  insert into ztgs.e_alter_recoder
    select * from ztgs.e_alter_recoder_tmp t;
  commit;

  --分支机构-全量
  --execute immediate 'truncate table ztgs.filiation';
  delete from ztgs.filiation;
  insert into ztgs.filiation
    select * from ztgs.filiation_tmp;
  commit;

  --企业对外投资--全量
  --execute immediate 'truncate table ztgs.entinvitem';
  delete from ztgs.entinvitem;
  insert into ztgs.entinvitem
    select * from ztgs.entinvitem_tmp;
  commit;

  --清算信息
  delete from ztgs.e_liquidation e
   where exists
   (select 1 from ztgs.e_liquidation_tmp t where t.pripid = e.pripid);
  insert into ztgs.e_liquidation
    select * from ztgs.e_liquidation_tmp t;
  commit;

  --行政处罚-违法行为及处罚信息
  delete from ztgs.case_cf_irregpunishinfo e
   where exists (select 1
            from ztgs.case_cf_irregpunishinfo_tmp t
           where t.case_info_id = e.case_info_id);
  insert into ztgs.case_cf_irregpunishinfo
    select * from ztgs.case_cf_irregpunishinfo_tmp t;
  commit;

  --行政处罚-当事人信息
  delete from ztgs.case_cf_partyinfo e
   where exists
   (select 1 from ztgs.case_cf_partyinfo_tmp t where t.eid = e.eid);
  insert into ztgs.case_cf_partyinfo
    select * from ztgs.case_cf_partyinfo_tmp t;
  commit;

  --股权冻结
  delete from ztgs.e_shares_frost_new e
   where exists
   (select 1 from ztgs.e_shares_frost_new_tmp t where t.eid = e.eid);
  insert into ztgs.e_shares_frost_new
    select * from ztgs.e_shares_frost_new_tmp t;
  commit;

  --股权出质
  delete from ztgs.e_shares_impawn e
   where exists
   (select 1 from ztgs.e_shares_impawn_tmp t where t.eid = e.eid);
  insert into ztgs.e_shares_impawn
    select * from ztgs.e_shares_impawn_tmp t;
  commit;

  --动产抵押物
  delete from ztgs.mort_guarantee_info e
   where exists (select 1
            from ztgs.mort_guarantee_info_tmp t
           where t.mort_reg_id = e.mort_reg_id);
  insert into ztgs.mort_guarantee_info
    select * from ztgs.mort_guarantee_info_tmp t;
  commit;

  --动产抵押权人
  delete from ztgs.mort_person_info e
   where exists (select 1
            from ztgs.mort_person_info_tmp t
           where t.mort_reg_id = e.mort_reg_id);
  insert into ztgs.mort_person_info
    select * from ztgs.mort_person_info_tmp t;
  commit;

  --动产抵押被担保主债权
  delete from ztgs.mort_principal_claim e
   where exists (select 1
            from ztgs.mort_principal_claim_tmp t
           where t.mort_reg_id = e.mort_reg_id);
  insert into ztgs.mort_principal_claim
    select * from ztgs.mort_principal_claim_tmp t;
  commit;

  --动产抵押登记
  delete from ztgs.mort_reg_info e
   where exists
   (select 1 from ztgs.mort_reg_info_tmp t where t.eid = e.eid);
  insert into ztgs.mort_reg_info
    select * from ztgs.mort_reg_info_tmp t;
  commit;

  --历史名称
  delete from ztgs.rep_ent_history e
   where exists
   (select 1 from ztgs.rep_ent_history_tmp t where t.pripid = e.pripid);
  insert into ztgs.rep_ent_history
    select * from ztgs.rep_ent_history_tmp t;
  commit;

  --经营异常
  delete from ztgs.business_abnormal e
   where exists
   (select 1 from ztgs.business_abnormal_tmp t where t.eid = e.eid);
  insert into ztgs.business_abnormal
    select * from ztgs.business_abnormal_tmp t;
  commit;

  --严重违法
  delete from ztgs.e_li_illdisdetail e
   where exists
   (select 1 from ztgs.e_li_illdisdetail_tmp t where t.eid = e.eid);
  insert into ztgs.e_li_illdisdetail
    select * from ztgs.e_li_illdisdetail_tmp t;
  commit;

  --许可信息
  delete from ztgs.e_licence_certificate e
   where exists
   (select 1 from ztgs.e_licence_certificate_tmp t where t.eid = e.eid);
  insert into ztgs.e_licence_certificate
    select * from ztgs.e_licence_certificate_tmp t;
  commit;

  ------------------------
exception
  when others then
    v_sqlcode := -1 * sqlcode;
    v_err_msg := sqlerrm;
    rollback;
    --记录错误日志
    kingstar.pr_audit_write_errlog(v_pr_task_id, -- 任务标识
                                   0, -- 单位编号
                                   i_tradedate, -- 业务日期
                                   v_function_id, -- 功能标识
                                   v_program_name, -- 程序名
                                   v_error_line_num, -- 程序行号
                                   v_err_msg, -- 错误信息
                                   v_sqlcode, -- SQLCODE
                                   v_sqlstate -- SQLSTATE
                                   );
    commit;
    raise;
end;

