  v_sqlcode  integer default 0;
  v_sqlstate char(5) default '';
  --v_errcode        integer default 0;
  --v_errstate       char(5) default '';
  v_err_msg varchar2(128) default '';
  --v_not_found      integer default 0;
  --v_last_time      char(8);
  v_function_id    integer default 0; --定义存储过程模块编号
  v_error_line_num integer default 0; --错误行号
  --v_error_level    integer default 0; --错误级别
  v_function_desc varchar2(50) default '政通工商数据日增量转换'; --功能描述
  v_program_name  char(40) default 'p_ztgs_enterprisebaseinfo'; --程序名
  v_pr_task_id    number default 0; --任务标示
  -- =======================================================================================================================
  -- 定义业务变量
  -- =======================================================================================================================
  v_index_count integer default 0;
  -- =======================================================================================================================
  -- 业务开始
  -- =======================================================================================================================
begin

  --从每日增量表转换至全量表
  --各表按对应的ID删除旧表数据，重新插入增量表数据

  --性能优化 unusable索引
  --禁用索引，以提高删除及插入效率
  /*EXECUTE IMMEDIATE 'alter index ZTGS.IDX_ENTERPRISEBASEINFO_1 unusable';
  EXECUTE IMMEDIATE 'alter index ZTGS.IDX_ENTERPRISEBASEINFO_2 unusable';
  EXECUTE IMMEDIATE 'alter index ZTGS.IDX_ENTERPRISEBASEINFO_3 unusable';
  EXECUTE IMMEDIATE 'alter index ZTGS.IDX_ENTERPRISEBASEINFO_4 unusable';
  EXECUTE IMMEDIATE 'alter index ZTGS.IDX_ENTERPRISEBASEINFO_5 unusable';
  EXECUTE IMMEDIATE 'alter index ZTGS.IDX_ENTERPRISEBASEINFO_6 unusable';*/

  --企业主体表 以pripid+eid更新
  delete /*+parallel(8) full(e)*/
  from ztgs.enterprisebaseinfocollect e
   where exists (select /*+parallel(8)*/
           1
            from ztgs.enterprisebaseinfocollect_tmp t
           where t.pripid = e.pripid
             and t.eid = e.eid);
  commit;

  insert /*+APPEND PARALLEL(8) */
  into ztgs.enterprisebaseinfocollect
    (id,
     pripid,
     entname,
     regno,
     ppripid,
     industryphy,
     industryco,
     opfrom,
     opto,
     esdate,
     apprdate,
     regcap,
     opscope,
     dom,
     --reccap,
     enttype_name,
     industryphy_name,
     industryco_name,
     regorg_name,
     regorg_prov,
     regorg_city,
     regorg_county,
     credit_code,
     regcapcur_name,
     entstatus_name,
     legal_person,
     candate,
     revdate,
     eid,
     revan_rea,
     create_time,
     update_time,
     modify_type,
     push_time)
    select /*+PARALLEL(8)*/
     t.id,
     t.pripid,
     t.entname,
     t.regno,
     t.ppripid,
     t.industryphy,
     t.industryco,
     t.opfrom,
     t.opto,
     t.esdate,
     t.apprdate,
     t.regcap,
     t.opscope,
     t.dom,
     --t.reccap,
     t.enttype_name,
     t.industryphy_name,
     t.industryco_name,
     t.regorg_name,
     t.regorg_prov,
     t.regorg_city,
     t.regorg_county,
     t.credit_code,
     t.regcapcur_name,
     t.entstatus_name,
     t.legal_person,
     t.candate,
     t.revdate,
     t.eid,
     t.revan_rea,
     t.create_time,
     t.update_time,
     t.modify_type,
     t.push_time
      from ztgs.enterprisebaseinfocollect_tmp t;
  commit;

  --恢复索引
  /*EXECUTE IMMEDIATE 'alter index ZTGS.IDX_ENTERPRISEBASEINFO_1 rebuild';
  EXECUTE IMMEDIATE 'alter index ZTGS.IDX_ENTERPRISEBASEINFO_2 rebuild';
  EXECUTE IMMEDIATE 'alter index ZTGS.IDX_ENTERPRISEBASEINFO_3 rebuild';
  EXECUTE IMMEDIATE 'alter index ZTGS.IDX_ENTERPRISEBASEINFO_4 rebuild';
  EXECUTE IMMEDIATE 'alter index ZTGS.IDX_ENTERPRISEBASEINFO_5 rebuild';
  EXECUTE IMMEDIATE 'alter index ZTGS.IDX_ENTERPRISEBASEINFO_6 rebuild';*/

  --中文分词索引异常处理
  select count(1)
    into v_index_count
    from all_indexes i
   where i.OWNER = 'ZTGS'
     and i.TABLE_NAME = 'ENTERPRISEBASEINFOCOLLECT'
     and i.INDEX_NAME = 'IDX_ENTERPRISEBASEINFO_T';

  if v_index_count > 0 then
  
    --同步名称索引
    ctx_ddl.sync_index('ztgs.idx_enterprisebaseinfo_t',
                       parallel_degree => 8); --数据变化时刷新索引
    ctx_ddl.optimize_index('ztgs.idx_enterprisebaseinfo_t',
                           'full',
                           parallel_degree => 8); --索引优化
  
  end if;

  commit;

  ------------------------
exception
  when others then
    v_sqlcode := -1 * sqlcode;
    v_err_msg := sqlerrm;
    rollback;
    --记录错误日志
    kingstar.pr_audit_write_errlog(v_pr_task_id, -- 任务标识
                                   0, -- 单位编号
                                   i_tradedate, -- 业务日期
                                   v_function_id, -- 功能标识
                                   v_program_name, -- 程序名
                                   v_error_line_num, -- 程序行号
                                   v_err_msg, -- 错误信息
                                   v_sqlcode, -- SQLCODE
                                   v_sqlstate -- SQLSTATE
                                   );
    commit;
    raise;
end;

