Create or Replace PROCEDURE "THJS"."SP_QUERY_NEGATIVE_NEWS" (RT_CURSOR      OUT TYPES.CURSORTYPE,
                                                   p_ztgs_prip_id in varchar2, --政通工商主体id
                                                   p_ztgs_comp_id in varchar2, --政通工商企业id
                                                   o_news_title   out varchar2, --负面新闻标题
                                                   o_news_source  out varchar2, --负面新闻来源
                                                   o_publish_date out varchar2, --负面新闻发布时间
                                                   o_check_path   out varchar2, --负面新闻内容路径
                                                   o_return_msg   out varchar2,
                                                   o_return_code  out integer) is

  --固定变量
  v_userexp exception; -- 用户定义错
  V_TRADEDATE      VARCHAR2(8) := to_char(sysdate, 'yyyyMMdd'); --任务执行时间(业务日期)
  v_exec_func_id   integer default '0'; -- 任务id
  v_func_own       varchar2(20) default 'EDW00'; -- 任务归属用户（schema）
  v_func_name      varchar2(2000) default 'SP_QUERY_NEGATIVE_NEWS'; -- 任务名称(存储过程的名字)
  v_sqlerrm        varchar2(4000); -- 错误提示信息
  v_sqlcode        number; -- 错误代码
  v_sqlerrl        varchar2(100); -- 错误行号
  v_chyq_comp_code varchar2(20);

  -- 业务处理过程
begin
  --数据处理开始 日志记录
  o_return_msg  := '执行开始';
  o_return_code := 0;

  --首先查询政通工商企业在映射表中对应财汇舆情的企业内码值
  if p_ztgs_prip_id is not null then
    select t.chyq_comp_code
      into v_chyq_comp_code
      from edw00.pty_mapping_info t
     where t.ztgs_prip_id = p_ztgs_prip_id;
  end if;

  if p_ztgs_comp_id is not null then
    select t.chyq_comp_code
      into v_chyq_comp_code
      from edw00.pty_mapping_info t
     where t.ztgs_comp_id = p_ztgs_comp_id;
  end if;

  if v_chyq_comp_code is not null then
    open RT_CURSOR for
    --查询对应企业下涉及到的负面新闻
      select n.news_title, --标题
             n.news_source, --来源
             n.publish_date, --发布时间
             n.news_check_path --内容路径
        into o_news_title, o_news_source, o_publish_date, o_check_path
        from EDW00.MKT_NEWS_COMP_NEGATIVE t
       inner join edw00.mkt_news_main_negative n
          on n.news_check_code = t.news_check_code
       where n.is_valid = 1 --有效
         and t.comp_code = v_chyq_comp_code
         and not (n.news_check_code is null and n.news_check_path is null);
  end if;

  --数据处理结束 日志记录
  o_return_msg  := '执行成功';
  o_return_code := 0;

  commit;

exception
  -- 非预定义异常处理
  when v_userexp then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    qlj.sp_write_error_log(i_tradedate    => v_tradedate,
                           i_exec_func_id => v_exec_func_id,
                           i_func_own     => v_func_own,
                           i_func_name    => v_func_name,
                           i_occur_time   => sysdate,
                           i_sqlerrm      => v_sqlerrm,
                           i_sqlcode      => v_sqlcode,
                           i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
    -- 预定义异常处理
  when others then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    qlj.sp_write_error_log(i_tradedate    => v_tradedate,
                           i_exec_func_id => v_exec_func_id,
                           i_func_own     => v_func_own,
                           i_func_name    => v_func_name,
                           i_occur_time   => sysdate,
                           i_sqlerrm      => v_sqlerrm,
                           i_sqlcode      => v_sqlcode,
                           i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
end SP_QUERY_NEGATIVE_NEWS;

Create or Replace PROCEDURE "THJS"."SP_WIND_COMP_PROSPECT" (I_TRADEDATE IN VARCHAR2, --日期
                                  RETURN_MSG  OUT VARCHAR2,
                                  RETURN_CODE OUT INTEGER) IS

    --固定变量
    V_USEREXP EXCEPTION; -- 用户定义错
    V_TRADEDATE    VARCHAR2(8) := I_TRADEDATE; -- 任务执行时间(业务日期)
    V_EXEC_FUNC_ID INTEGER DEFAULT '0'; -- 任务ID
    V_FUNC_OWN     VARCHAR2(20) DEFAULT 'GZW'; -- 任务归属用户（SCHEMA）
    V_FUNC_NAME    VARCHAR2(2000) DEFAULT 'SP_WIND_COMP_PROSPECT'; -- 任务名称(存储过程的名字)
    V_SQLERRM      VARCHAR2(4000); -- 错误提示信息
    V_SQLCODE      NUMBER; -- 错误代码
    V_SQLERRL      VARCHAR2(100); -- 错误行号

    -- 业务处理过程
  BEGIN
    --数据处理开始 日志记录
    RETURN_MSG  := '执行开始';
    RETURN_CODE := 0;

    EXECUTE IMMEDIATE 'truncate table GZW.TB_WIND_SWIND_PROSPECT';

    --全量初始化
    INSERT /*+APPEND*/
    INTO GZW.TB_WIND_SWIND_PROSPECT
      (IND_CODE,
       IND_NAME,
       IND_LEVEL,
       REPORT_PERIOD,
       PE_TTM_1,
       PE_TTM_2,
       PE_TTM_3,
       PE_AVG,
       FMC_1,
       FMC_2,
       FMC_3,
       FMC_AVG,
       FMC_STAND,
       PE_TTM_SCORE,
       /*KF_ROE_1,
       KF_ROE_2,
       KF_ROE_3,
       KF_ROE_AVG,
       ROA2_1,
       ROA2_2,
       ROA2_3,
       ROA2_AVG,
       OR_GR_1,
       OR_GR_2,
       OR_GR_3,
       OR_CAGR,
       OR_AVG,
       KF_PNP,*/
       GEN_TIME)
      SELECT /*+PARALLEL(t,8)*/
       t.sw_ind_name,
       '' ind_code,
       substr(t.sw_ind_name, 3) ind_name,
       case
         when instr(substr(t.sw_ind_name, 3), 'Ⅲ') > 0 then
          '三'
         when instr(substr(t.sw_ind_name, 3), 'Ⅱ') > 0 then
          '二'
         else
          '一'
       end ind_class,
       '' peport_period,
       t.ttm_20151231 pe_ttm_1,
       t.ttm_20161231 pe_ttm_2,
       t.ttm_20171231 pe_ttm_3,
       '' pe_avg,
       t.fmc_20171231 fmc_1,
       t.fmc_20181231 fmc_2,
       t.fmc_20191231 fmc_3,
       '' fmc_avg,
       '' FMC_STAND, --自由流通市值平均值[1-2]标准化
       '' pe_ttm_score --pe_ttm得分（行业前景得分） =(3年内每半年共6个时点)*自由流通市值[1-2]标准化值
