  v_func_own     varchar2(20) default 'thjs'; -- 任务归属用户（schema）
  v_func_name    varchar2(2000) default 'ylt_p_fxq_cust_authorizer_q'; -- 任务名称(存储过程的名字)
  v_sqlerrm      varchar2(4000); -- 错误提示信息
  v_sqlcode      number; -- 错误代码
  v_sqlerrl      varchar2(4000); -- 错误行号
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  --=============================================================
  -- 业务处理过程
  --=============================================================

begin

  v_tradedate := to_char(sysdate, 'yyyyMMdd');
  --如果是查草稿数据
  if i_qry_flag = '0' then
    open rt_cursor for
      select r.cust_id, --客户id
             s.name, --姓名
             s.birth, --出生年月
             s.certtype, --证件类型
             s.certno, --证件号码
             s.certstart, --证照有效起始
             s.certend, --证照有效截止
             s.data_order
        from thjs.tb_fxq_cust_rz_draft r
       inner join thjs.tb_fxq_cust_authorizer_draft s
          on s.cust_id = r.cust_id
       where r.cust_id = i_cust_id
       order by s.data_order;
  
  --如果是查正式数据
  elsif i_qry_flag = '1' then
    open rt_cursor for
      select r.cust_id, --客户id
             s.name, --姓名
             s.birth, --出生年月
             s.certtype, --证件类型
             s.certno, --证件号码
