             s.certend, --证照有效截止
             s.data_order
        from thjs.tb_fxq_cust_rz r
       inner join thjs.tb_fxq_cust_authorizer s
          on s.cust_id = r.cust_id
       where r.cust_id = i_cust_id
       order by s.data_order;
  else
    --万一前端没有传入i_qry_flag标识，查询返回空
    open rt_cursor for
      select '' cust_id, --客户id
             '' name, --姓名
             '' birth, --出生年月
             '' certtype, --证件类型
             '' certno, --证件号码
             '' certstart, --证照有效起始
             '' certend --证照有效截止
        from dual;
  
  end if;
  commit;

  o_return_msg  := '执行成功';
  o_return_code := 0;

exception
  -- 非预定义异常处理
  when v_userexp then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    hgman.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
    -- 预定义异常处理
  when others then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    hgman.p_write_error_log(i_tradedate    => v_tradedate,
