Create or Replace procedure "THJS"."YLT_P_FXQ_CUST_CONTROLLER_Q" (rt_cursor     out sys_refcursor, --返回游标结果集
                                                        i_cust_id     in varchar2, --客户id
                                                        i_type        in varchar2, --实际控制人类型：0-法人 1-自然人
                                                        i_qry_flag    in varchar2, --查询标识：0-草稿 1-提交 v101+
                                                        o_return_msg  out varchar2,
                                                        o_return_code out integer) is
  ----------------------------------------------------------------------------------
  --版    权：GTJA
  --版    本：1.0.0
  --v101 YLT@GTJA 20191031 反洗钱客户填报逻辑优化，加上查询草稿数据处理

  --开发人员：CZC@GTJA
  --创建日期：20190603
  --模块编号：
  --模块名称：投行反洗钱 - 客户基本信息（融资端）实际控制人查询
  --功能名称：
  ----------------------------------------------------------------------------------
  --==============================================================================
  --固定变量
  v_userexp exception; -- 用户定义错
  v_tradedate    varchar2(8); -- 任务执行时间(业务日期)
  v_exec_func_id integer default '0'; -- 任务id
  v_func_own     varchar2(20) default 'thjs'; -- 任务归属用户（schema）
  v_func_name    varchar2(2000) default 'ylt_p_fxq_cust_controller_q'; -- 任务名称(存储过程的名字)
  v_sqlerrm      varchar2(4000); -- 错误提示信息
  v_sqlcode      number; -- 错误代码
  v_sqlerrl      varchar2(4000); -- 错误行号
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  --=============================================================
  -- 业务处理过程
  --=============================================================

begin

  v_tradedate := to_char(sysdate, 'yyyyMMdd');
  --如果是查草稿数据
  if i_qry_flag = '0' then
    open rt_cursor for
      select r.cust_id, --客户id
             s.type, --股东类型：0-法人 1-自然人
             s.name, --姓名
             s.birth, --出生年月
             s.certtype, --证件类型
             s.certno, --证件号码
             s.certstart, --证照有效起始
             s.certend, --证照有效截止
             s.data_order
        from thjs.tb_fxq_cust_rz_draft r
       inner join thjs.tb_fxq_cust_controller_draft s
          on s.cust_id = r.cust_id
         and (i_type is null or s.type = i_type)
       where r.cust_id = i_cust_id
       order by s.data_order;
  --如果是查正式数据
  elsif i_qry_flag = '1' then
    open rt_cursor for
      select r.cust_id, --客户id
             s.type, --股东类型：0-法人 1-自然人
             s.name, --姓名
             s.birth, --出生年月
             s.certtype, --证件类型
             s.certno, --证件号码
             s.certstart, --证照有效起始
             s.certend, --证照有效截止
             s.data_order
        from thjs.tb_fxq_cust_rz r
       inner join thjs.tb_fxq_cust_controller s
          on s.cust_id = r.cust_id
         and (i_type is null or s.type = i_type)
       where r.cust_id = i_cust_id
       order by s.data_order;
  else
    --万一前端没有传入i_qry_flag标识，查询返回空
    open rt_cursor for
      select '' cust_id, --客户id
             '' type, --股东类型：0-法人 1-自然人
             '' name, --姓名
             '' birth, --出生年月
             '' certtype, --证件类型
             '' certno, --证件号码
             '' certstart, --证照有效起始
             '' certend --证照有效截止
        from dual;
  end if;
  commit;

  o_return_msg  := '执行成功';
  o_return_code := 0;

exception
  -- 非预定义异常处理
  when v_userexp then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    hgman.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
    -- 预定义异常处理
  when others then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    hgman.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
end;

Create or Replace procedure "THJS"."YLT_P_FXQ_CUST_CONTROLLER_S" (i_cust_id     in varchar2, --客户id
                                                        i_type        in varchar2, --实际控制人类型：0-法人 1-自然人
                                                        i_name        in varchar2, --姓名
                                                        i_birth       in varchar2, --出生年月
                                                        i_certtype    in varchar2, --证件类型
                                                        i_certno      in varchar2, --证件号码
                                                        i_certstart   in varchar2, --证照有效起始
                                                        i_certend     in varchar2, --证照有效截止
                                                        i_submit_flag in varchar2, --提交标识：0-草稿 1-提交 v101+
                                                        i_order       in varchar2, --用于区分数据展示顺序 v101+
                                                        o_return_msg  out varchar2,
                                                        o_return_code out integer) is
  ----------------------------------------------------------------------------------
  --版    权：GTJA
  --版    本：1.0.0
  --v101 YLT@GTJA 20191031 反洗钱客户填报逻辑优化，加上保存草稿处理

  --开发人员：CZC@GTJA
  --创建日期：20190603
  --模块编号：
  --模块名称：投行反洗钱 - 客户基本信息（融资端）实际控制人填报增删改
  --功能名称：
  ----------------------------------------------------------------------------------
  --==============================================================================
  --固定变量
  v_userexp exception; -- 用户定义错
  v_tradedate    varchar2(8); -- 任务执行时间(业务日期)
  v_exec_func_id integer default '0'; -- 任务id
  v_func_own     varchar2(20) default 'thjs'; -- 任务归属用户（schema）
  v_func_name    varchar2(2000) default 'ylt_p_fxq_cust_controller_s'; -- 任务名称(存储过程的名字)
  v_sqlerrm      varchar2(4000); -- 错误提示信息
  v_sqlcode      number; -- 错误代码
  v_sqlerrl      varchar2(4000); -- 错误行号
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  --=============================================================
  -- 业务处理过程
  --=============================================================

begin

  v_tradedate := to_char(sysdate, 'yyyyMMdd');
  --如果是保存草稿操作
  if i_submit_flag = '0' then
    /*--先把该客户存在的信息删除再进行插入
    delete from thjs.tb_fxq_cust_controller_draft
     where cust_id = i_cust_id;*/
    insert into thjs.tb_fxq_cust_controller_draft
      (busi_date,
       cust_id,
       type,
       name,
       birth,
       certtype,
       certno,
       certstart,
       certend,
       data_order)
    values
      (v_tradedate,
       i_cust_id,
       i_type,
       i_name,
       to_char(to_date(replace(i_birth, '/', '-'), 'YYYY-MM-DD'),
               'YYYY-MM-DD'),
       i_certtype,
       i_certno,
       to_char(to_date(replace(i_certstart, '/', '-'), 'YYYY-MM-DD'),
               'YYYY-MM-DD'),
       to_char(to_date(replace(i_certend, '/', '-'), 'YYYY-MM-DD'),
               'YYYY-MM-DD'),
       i_order);
  end if;
  --点击‘正式提交’操作时
  if i_submit_flag = '1' then
    /*--先把该客户存在的信息删除再进行插入
    delete from thjs.tb_fxq_cust_controller where cust_id = i_cust_id;*/
    insert into thjs.tb_fxq_cust_controller
      (busi_date,
       cust_id,
       type,
       name,
       birth,
       certtype,
       certno,
       certstart,
       certend,
       data_order)
    values
      (v_tradedate,
       i_cust_id,
       i_type,
       i_name,
       to_char(to_date(replace(i_birth, '/', '-'), 'YYYY-MM-DD'),
               'YYYY-MM-DD'),
       i_certtype,
       i_certno,
       to_char(to_date(replace(i_certstart, '/', '-'), 'YYYY-MM-DD'),
               'YYYY-MM-DD'),
       to_char(to_date(replace(i_certend, '/', '-'), 'YYYY-MM-DD'),
               'YYYY-MM-DD'),
       i_order);
  end if;
  commit;

  o_return_msg  := '执行成功';
  o_return_code := 0;

exception
  -- 非预定义异常处理
  when v_userexp then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    hgman.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
    -- 预定义异常处理
  when others then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    hgman.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
end;

Create or Replace procedure "THJS"."YLT_P_FXQ_CUST_RZ_BILLRST_Q" (rt_cursor        out sys_refcursor, --返回游标结果集
                                                        i_sno            in integer, --序号
                                                        i_comp_name      in varchar2, --公司名称
                                                        i_cert_no        in varchar2, --统一社会信用代码
                                                        i_chair_man      in varchar2, --法定代表人姓名
                                                        i_chair_certtype in varchar2, --法定代表人证件类型
                                                        i_chair_certno   in varchar2, --法定代表人证件号码
                                                        o_return_msg     out varchar2,
                                                        o_return_code    out integer) is
  ----------------------------------------------------------------------------------
  --版    权：GTJA
  --版    本：1.0.0
  --开发人员：YLT@GTJA
  --创建日期：20200420
  --模块编号：
  --模块名称：投行反洗钱 - 客户基本信息（融资端）存托客户风险核查（道琼斯黑名单筛查）
  --功能名称：
  ----------------------------------------------------------------------------------
  --==============================================================================
  --固定变量
  v_userexp exception; -- 用户定义错
  v_tradedate    varchar2(8); -- 任务执行时间(业务日期)
  v_exec_func_id integer default '0'; -- 任务id
  v_func_own     varchar2(20) default 'thjs'; -- 任务归属用户（schema）
  v_func_name    varchar2(2000) default 'ylt_p_fxq_cust_rz_billrst_q'; -- 任务名称(存储过程的名字)
  v_sqlerrm      varchar2(4000); -- 错误提示信息
  v_sqlcode      number; -- 错误代码
  v_sqlerrl      varchar2(4000); -- 错误行号
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  v_count integer default 0;
  v_if_a1 varchar2(200);
  v_if_a2 varchar2(200);
  v_if_a3 varchar2(200);
  --=============================================================
  -- 业务处理过程
  --=============================================================

begin

  v_tradedate := to_char(sysdate, 'yyyyMMdd');
  with temp as
   (SELECT distinct if_a1, if_a2, if_a3
      FROM (
            --机构客户名称匹配
            select b.if_a1, b.if_a2, b.if_a3
              from thjs.tmp_cust_rz_billrst_1 b
             WHERE b.entityname = i_comp_name
               and b.type = 'entity'
            union all
            --机构客户证件号码匹配
            select b.if_a1, b.if_a2, b.if_a3
              from thjs.tmp_cust_rz_billrst_1 b
             WHERE b.idnumber = i_cert_no
               and b.type = 'entity'
            union all
            --个人客户证件匹配
            SELECT b.if_a1, b.if_a2, b.if_a3
              from thjs.tmp_cust_rz_billrst_1 b
             where b.IDNUMBER_TYPE = i_chair_certno
               and b.type = 'person'
            --法定代表人姓名匹配
            union all
            select b.if_a1, b.if_a2, b.if_a3
              from thjs.tmp_cust_rz_billrst_1 b
             WHERE (b.fms_name = i_chair_man or b.mfs_name = i_chair_man or
                   b.sfm_name = i_chair_man or b.smf_name = i_chair_man or
                   b.fms_name = upper(i_chair_man) or
                   b.mfs_name = upper(i_chair_man) or
                   b.sfm_name = upper(i_chair_man) or
                   b.smf_name = upper(i_chair_man))
               and b.type = 'person'
            union all
            --个人客户证件类型匹配
            SELECT b.if_a1, b.if_a2, b.if_a3
              from thjs.tmp_cust_rz_billrst_1 b
             where b.idnumber = i_chair_certtype
               and b.type = 'person'
            
            ) t)
  SELECT LISTAGG(if_a1, ',') WITHIN GROUP(ORDER BY NULL) AS if_a1,
         LISTAGG(if_a2, ',') WITHIN GROUP(ORDER BY NULL) AS if_a2,
         LISTAGG(if_a3, ',') WITHIN GROUP(ORDER BY NULL) AS if_a3
    into v_if_a1, v_if_a2, v_if_a3
    FROM temp;
    
  open RT_CURSOR for
    SELECT case
             when instr(v_if_a1, '1') > 0 and instr(v_if_a2, '1') > 0 and
                  instr(v_if_a3, '1') > 0 then
              'A1,A2,A3'
             when instr(v_if_a1, '1') > 0 and instr(v_if_a2, '1') > 0 then
              'A1,A2'
             when instr(v_if_a1, '1') > 0 and instr(v_if_a3, '1') > 0 then
              'A1,A3'
             when instr(v_if_a2, '1') > 0 and instr(v_if_a3, '1') > 0 then
              'A2,A3'
             when instr(v_if_a1, '1') > 0 then
              'A1'
             when instr(v_if_a2, '1') > 0 then
              'A2'
             when instr(v_if_a3, '1') > 0 then
              'A3'
             else
              ''
           end if_a_val,i_sno
      FROM dual;

  o_return_msg  := '执行成功';
  o_return_code := 0;

exception
  -- 非预定义异常处理
  when v_userexp then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    hgman.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
    -- 预定义异常处理
  when others then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    hgman.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
end;

Create or Replace procedure "THJS"."YLT_P_FXQ_CUST_RZ_Q" (rt_cursor     out sys_refcursor, --返回游标结果集
                                                     i_projid      in varchar2, --由项目信息查询界面打开时传入
                                                     i_entname     in varchar2, --新增填报业务人员输入客户名称时传入
                                                     i_cust_id     in integer, --客户id
                                                     i_usercode    in varchar2, --查询人
                                                     i_data_type   in varchar2, --要查询的数据类型：0-草稿 1-正式
                                                     o_return_msg  out varchar2,
                                                     o_return_code out integer) is
  ----------------------------------------------------------------------------------
  --版    权：GTJA
  --版    本：1.0.0
  --开发人员：CZC@GTJA
  --创建日期：20190603
  --模块编号：
  --模块名称：投行反洗钱 - 客户基本信息（融资端）填报查询
  --功能名称：
  ----------------------------------------------------------------------------------
  --==============================================================================
  --固定变量
  v_userexp exception; -- 用户定义错
  v_tradedate    varchar2(8); -- 任务执行时间(业务日期)
  v_exec_func_id integer default '0'; -- 任务id
  v_func_own     varchar2(20) default 'thjs'; -- 任务归属用户（schema）
  v_func_name    varchar2(2000) default 'ylt_p_fxq_cust_rz_q'; -- 任务名称(存储过程的名字)
  v_sqlerrm      varchar2(4000); -- 错误提示信息
  v_sqlcode      number; -- 错误代码
  v_sqlerrl      varchar2(4000); -- 错误行号
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  v_count       integer default 0;
  v_cust_id     varchar2(100);
  v_ztgs_count  integer default 0;
  v_ztgs_name   varchar2(200);
  v_index_count integer default 0;
  v_fk_flag     char(1) default '0'; --反馈结果查看权限标识
  --=============================================================
  -- 业务处理过程
  --=============================================================

begin

  v_tradedate := to_char(sysdate, 'yyyyMMdd');

  insert into thjs.tb_test
    (id, text)
  values
    (111,
     'i_projid:' || i_projid || ' -' || 'i_entname:' || i_entname || ' -' ||
     'i_cust_id:' || i_cust_id || ' -' || 'i_usercode:' || i_usercode || ' -' ||
     'i_data_type:' || i_data_type);
  commit;

  --检查是否保存过此客户
  select count(1)
    into v_count
    from thjs.tb_fxq_cust_rz r
   where r.cust_id = i_cust_id;

  select case
           when count(1) > 0 then
            '1'
           else
            '0'
         end
    into v_fk_flag
    from table(kingstar.splitstr('admin,chenzhenkuan,zhangqilong', ',')) t
   where instr(',' || t.column_value || ',', ',' || i_usercode || ',') > 0;

  if i_data_type = '1' then
    --如果根据传入的i_cust_id在反洗钱客户表中查询不到对应客户
    if v_count = 0 then
      --检查该客户名称是否存在反洗钱客户主表中
      if i_entname is not null then
        select count(1)
          into v_count
          from thjs.tb_fxq_cust_rz r
         where r.cust_name = i_entname;
      end if;
    
      --如果根据客户名称查询到该客户不存在反洗钱客户主表中
      if v_count = 0 then
        select thjs.seq_fxq_custid.nextval into v_cust_id from dual;
      
        --未保存过此客户信息
        --第一次填报，通过所选项目id 查询工商主体表，默认展示相关信息
        if i_projid is not null then
          open rt_cursor for
            select nvl(r.cust_id, v_cust_id) as cust_id, --客户id
                   e.entname as cust_name, --客户名称
                   e.dom as office_adr, --办公住所
                   '0' as industry_id, --行业分类
                   e.industryphy_name as industry_name, --行业分类名称（或其他）
                   e.opscope as busi_scope, --经营范围
                   decode(e.regcap,
                          null,
                          '',
                          kingstar.fn_number_thousandpoint(e.regcap, 4)) as reg_capital, --注册资本金
                   nvl(d.entry_value, '0') as reg_currency, --注册资本金币种
                   '3' as cert_type, --证件类型
                   e.credit_code as cert_no, --证件号码
                   '' as cert_startdate, --证照有效起始
                   '' as cert_enddate, --证照有效截止
                   e.legal_person as chair_man, --法人代表姓名
                   '' as chair_birth, --法人出生年月
                   '0' as chair_certtype, --法人证件类型
                   '' as chair_certno, --法人证件号码
                   '' as chair_certstart, --法人证照有效起始
                   '' as chair_certend, --法人证照有效截止
                   '' as write_date, --填写日期
                   decode(r.cust_id, null, '0', '1') as is_exists, --客户信息是否已存在：0 否 1 是
                   '1' data_type,
                   '' associatied_date,
                   decode(r.cust_id, null, '0', v_fk_flag) as fk_flag
              from dual
              left join thjs.tb_thdb_cust_info c
                on c.projid = i_projid
              left join ztgs.enterprisebaseinfocollect e
                on e.pripid = c.projid
              left join thjs.tb_fxq_cust_rz r
                on r.cust_name = e.entname
              left join thjs.tb_dict_entry d
                on d.entry_code = 'CURRENCY_CODE'
               and instr(',' || d.entry_content_match || ',',
                         ',' || e.regcapcur_name || ',') > 0;
        else
          --通过客户名称或工商注册号，统一社会信用代码进行匹配查询
          if i_entname is not null then
            --检查是否有索引
            select count(1)
              into v_index_count
              from all_indexes i
             where i.OWNER = 'ZTGS'
               and i.TABLE_NAME = 'ENTERPRISEBASEINFOCOLLECT'
               and i.INDEX_NAME = 'IDX_ENTERPRISEBASEINFO_T';
          
            --没有对应索引的时候使用instr()查询匹配
            if v_index_count = 0 then
              select count(1)
                into v_ztgs_count
                from ztgs.enterprisebaseinfocollect e
               where instr(e.entname, i_entname) > 0; --能够匹配到
            else
              --存在对应索引时，使用contains()检索提高效率
              select count(1)
                into v_ztgs_count
                from ztgs.enterprisebaseinfocollect e
               where contains(e.entname, i_entname) > 0;
            end if;
          
            --根据传入的客户名称没有查询到对应的数据时，将传入的客户名称与注册号进行再一次匹配
            if v_ztgs_count = 0 then
              select count(1)
                into v_ztgs_count
                from ztgs.enterprisebaseinfocollect e
               where e.regno = i_entname;
            
              --如果根据 传入的客户名称与注册号 再一次匹配仍未查询到对应的客户数据，
              --则根据 传入的客户名称与统一社会信用代码进行三次匹配
              if v_ztgs_count = 0 then
                select count(1)
                  into v_ztgs_count
                  from ztgs.enterprisebaseinfocollect e
                 where e.credit_code = i_entname;
              
                --如果根据 传入的客户名称与统一社会信用代码 三次匹配仍未查询到对应的客户数据，
                --那么，给 v_ztgs_name 置空
                if v_ztgs_count = 0 then
                  v_ztgs_name := '';
                else
                
                  --如果根据 传入的客户名称与统一社会信用代码 三次匹配查询到对应的客户数据，将对应企业名称值返回给 v_ztgs_name
                  select e.entname
                    into v_ztgs_name
                    from ztgs.enterprisebaseinfocollect e
                   where e.credit_code = i_entname;
                end if;
              
                --如果根据 传入的客户名称与注册号 匹配到了对应客户数据，将对应企业名称值返回给 v_ztgs_name
              else
                select e.entname
                  into v_ztgs_name
                  from ztgs.enterprisebaseinfocollect e
                 where e.regno = i_entname;
              end if;
              --根据传入的客户名称直接查询到对应客户数据，则直接将查询到的企业名称值返回给 v_ztgs_name
            elsif v_ztgs_count = 1 then
              select e.entname
                into v_ztgs_name
                from ztgs.enterprisebaseinfocollect e
               where contains(e.entname, i_entname) > 0;
            
              --否则，如果根据传入的客户名称与工商主体表中的企业名称匹配查询到多条数据时，直接将入参的客户名称返回给 v_ztgs_name
            else
              v_ztgs_name := i_entname;
            end if;
          
          end if;
        
          --根据处理后得到的v_ztgs_name查询对应的企业基本信息
          open rt_cursor for
            select nvl(r.cust_id, v_cust_id) as cust_id, --客户id
                   e.entname as cust_name, --客户名称
                   e.dom as office_adr, --办公住所exist
                   '0' as industry_id, --行业分类
                   e.industryphy_name as industry_name, --行业分类名称（或其他）
                   e.opscope as busi_scope, --经营范围
                   decode(e.regcap,
                          null,
                          '',
                          kingstar.fn_number_thousandpoint(e.regcap, 4)) as reg_capital, --注册资本金
                   nvl(d.entry_value, '0') as reg_currency, --注册资本金币种
                   '3' as cert_type, --证件类型
                   e.credit_code as cert_no, --证件号码
                   '' as cert_startdate, --证照有效起始
                   '' as cert_enddate, --证照有效截止
                   e.legal_person as chair_man, --法人代表姓名
                   '' as chair_birth, --法人出生年月
                   '0' as chair_certtype, --法人证件类型
                   '' as chair_certno, --法人证件号码
                   '' chair_certstart, --法人证照有效起始
                   '' as chair_certend, --法人证照有效截止
                   '' as write_date, --填写日期
                   decode(r.cust_id, null, '0', '1') as is_exists, --客户信息是否已存在：0 否 1 是
                   '1' data_type,
                   '' associatied_date,
                   decode(r.cust_id, null, '0', v_fk_flag) as fk_flag
              from dual
              left join ztgs.enterprisebaseinfocollect e
                on e.entname = v_ztgs_name
              left join thjs.tb_fxq_cust_rz r
                on r.cust_name = e.entname
              left join thjs.tb_dict_entry d
                on d.entry_code = 'CURRENCY_CODE'
               and instr(',' || d.entry_content_match || ',',
                         ',' || e.regcapcur_name || ',') > 0;
        
        end if;
      
        --如果根据客户名称查询到该客户已经存在反洗钱客户主表中，直接将该反洗钱客户信息查询出来
      else
        open rt_cursor for
          select r.cust_id as cust_id, --客户id
                 r.cust_name, --客户名称
                 r.office_adr, --办公住所
                 r.industry_id, --行业分类
                 r.industry_name, --行业分类名称（或其他）
                 r.busi_scope, --经营范围
                 decode(r.reg_capital,
                        null,
                        '',
                        kingstar.fn_number_thousandpoint(r.reg_capital, 4)) as reg_capital, --注册资本金
                 r.reg_currency, --注册资本金币种
                 r.cert_type, --证件类型
                 r.cert_no, --证件号码
                 r.cert_startdate, --证照有效起始
                 r.cert_enddate, --证照有效截止
                 r.chair_man, --法人代表姓名
                 r.chair_birth, --法人出生年月
                 r.chair_certtype, --法人证件类型
                 r.chair_certno, --法人证件号码
                 r.chair_certstart, --法人证照有效起始
                 r.chair_certend, --法人证照有效截止
                 r.write_date, --填写日期
                 '1' as is_exists, --客户信息是否已存在：0 否 1 是
                 '1' data_type,
                 r.associatied_date,
                 v_fk_flag as fk_flag
            from thjs.tb_fxq_cust_rz r
            left join thjs.tb_dict_entry d
              on d.entry_code = 'INDUSTRY_TYPE'
             and d.entry_value = r.industry_id
           where r.cust_name = i_entname;
      
      end if;
      --如果根据传入的i_cust_id在反洗钱客户表中查询到对应客户，直接根据i_cust_id查询反洗钱客户主表将该反洗钱客户信息返回
    else
      open rt_cursor for
        select r.cust_id as cust_id, --客户id
               r.cust_name, --客户名称
               r.office_adr, --办公住所
               r.industry_id, --行业分类
               r.industry_name, --行业分类名称（或其他）
               r.busi_scope, --经营范围
               decode(r.reg_capital,
                      null,
                      '',
                      kingstar.fn_number_thousandpoint(r.reg_capital, 4)) as reg_capital, --注册资本金
               r.reg_currency, --注册资本金币种
               r.cert_type, --证件类型
               r.cert_no, --证件号码
               r.cert_startdate, --证照有效起始
               r.cert_enddate, --证照有效截止
               r.chair_man, --法人代表姓名
               r.chair_birth, --法人出生年月
               r.chair_certtype, --法人证件类型
               r.chair_certno, --法人证件号码
               r.chair_certstart, --法人证照有效起始
               r.chair_certend, --法人证照有效截止
               r.write_date, --填写日期
               '1' as is_exists, --客户信息是否已存在：0 否 1 是
               '1' date_type,
               r.associatied_date,
               decode(r.cust_biz, '测试', '', v_fk_flag) as fk_flag
          from thjs.tb_fxq_cust_rz r
          left join thjs.tb_dict_entry d
            on d.entry_code = 'INDUSTRY_TYPE'
           and d.entry_value = r.industry_id
         where r.cust_id = i_cust_id;
    end if;
  
  end if;

  if i_data_type = '0' then
    --草稿数据直接查询，无需匹配
    open rt_cursor for
      select r.cust_id as cust_id, --客户id
             r.cust_name, --客户名称
             r.office_adr, --办公住所
             r.industry_id, --行业分类
             r.industry_name, --行业分类名称（或其他）
             r.busi_scope, --经营范围
             decode(r.reg_capital,
                    null,
                    '',
                    kingstar.fn_number_thousandpoint(r.reg_capital, 4)) as reg_capital, --注册资本金
             r.reg_currency, --注册资本金币种
             r.cert_type, --证件类型
             r.cert_no, --证件号码
             r.cert_startdate, --证照有效起始
             r.cert_enddate, --证照有效截止
             r.chair_man, --法人代表姓名
             r.chair_birth, --法人出生年月
             r.chair_certtype, --法人证件类型
             r.chair_certno, --法人证件号码
             r.chair_certstart, --法人证照有效起始
             r.chair_certend, --法人证照有效截止
             r.write_date, --填写日期
             '1' as is_exists, --客户信息是否已存在：0 否 1 是
             '0' date_type,
             r.associatied_date,
             '0' as fk_flag --草稿不展示
        from thjs.tb_fxq_cust_rz_draft r
        left join thjs.tb_dict_entry d
          on d.entry_code = 'INDUSTRY_TYPE'
         and d.entry_value = r.industry_id
       where r.cust_id = i_cust_id;
  
  end if;

  commit;

  o_return_msg  := '执行成功';
  o_return_code := 0;

exception
  -- 非预定义异常处理
  when v_userexp then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    hgman.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
    -- 预定义异常处理
  when others then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    hgman.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
end;

Create or Replace procedure "THJS"."YLT_P_FXQ_CUST_RZ_QRY" (rt_cursor     out sys_refcursor, --返回游标结果集
                                                  i_cust_sno    in integer, --客户序号
                                                  i_cust_biz    in varchar2, --客户业务分类
                                                  i_cust_name   in varchar2, --客户名称
                                                  i_status      in varchar2, --状态：0-正常 1-删除
                                                  i_usercode    in varchar2, --查询人
                                                  i_page_num    in number default 0, --默认值0,
                                                  i_page_size   in number default 0, --默认值0  如果i_page_num，i_page_size都为0 则不分页，查询全部
                                                  o_total_count out integer,
                                                  o_return_msg  out varchar2,
                                                  o_return_code out integer) is
  ----------------------------------------------------------------------------------
  --版    权：GTJA
  --版    本：1.0.0
  --开发人员：YLT@GTJA
  --创建日期：20191028
  --模块编号：
  --模块名称：投行反洗钱 - 客户基本信息（融资端）查询
  --功能名称：
  ----------------------------------------------------------------------------------
  --==============================================================================
  --固定变量
  v_userexp exception; -- 用户定义错
  v_tradedate    varchar2(8); -- 任务执行时间(业务日期)
  v_exec_func_id integer default '0'; -- 任务id
  v_func_own     varchar2(20) default 'thjs'; -- 任务归属用户（schema）
  v_func_name    varchar2(2000) default 'ylt_p_fxq_cust_rz_qry'; -- 任务名称(存储过程的名字)
  v_sqlerrm      varchar2(4000); -- 错误提示信息
  v_sqlcode      number; -- 错误代码
  v_sqlerrl      varchar2(4000); -- 错误行号
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  v_page_num  number default 0;
  v_page_size number;
  --=============================================================
  -- 业务处理过程
  --=============================================================

begin

  v_tradedate := to_char(sysdate, 'yyyyMMdd');

  insert into thjs.tb_test (id, text) values (123, i_usercode);

  if i_page_num is not null then
    v_page_num := i_page_num;
  end if;

  --统计记录条数
  if v_page_num < 1 then
  
    SELECT sum(cnt)
      into o_total_count
      FROM (select count(1) cnt
              from thjs.tb_fxq_cust_rz r
             where (i_cust_sno is null or r.cust_sno = i_cust_sno)
               and (i_cust_biz is null or r.cust_biz = i_cust_biz)
               and (i_cust_name is null or
                   instr(r.cust_name, i_cust_name) > 0)
               and r.status = '0');
  
  end if;

  if i_page_size is not null and i_page_size <> 0 then
    v_page_size := i_page_size;
  else
    v_page_size := o_total_count;
  end if;

  open rt_cursor for
    select r.status, --状态：0-正常 1-删除
           r.cust_sno, --客户序号
           r.cust_biz, --客户业务分类
           r.cust_id, --客户id
           r.cust_name, --客户名称
           r.office_adr, --办公住所
           r.industry_id, --行业分类
           r.industry_name, --行业分类名称（或其他）
           r.busi_scope, --经营范围
           decode(r.reg_capital,
                  null,
                  '',
                  kingstar.fn_number_thousandpoint(r.reg_capital, 4)) as reg_capital, --注册资本金
           r.reg_currency, --注册资本金币种
           r.cert_type, --证件类型
           r.cert_no, --证件号码
           r.cert_startdate, --证照有效起始
           r.cert_enddate, --证照有效截止
           r.chair_man, --法人代表姓名
           r.chair_birth, --法人出生年月
           r.chair_certtype, --法人证件类型
           r.chair_certno, --法人证件号码
           r.chair_certstart, --法人证照有效起始
           r.chair_certend, --法人证照有效截止
           0 as s_cn, --控股股东数量
           0 as c_cn, --实际控制人数量
           0 as a_cn, --授权代表人数量
           0 as b_cn, --受益所有人数量
           r.update_user, --更新人
           r.update_time, --更新时间
           r.create_user,
           r.create_time,
           r.data_type --0-草稿/1-正式
      from (
            --只查正式表和草稿表中的客户数据
            select r.*,
                    1 data_type,
                    row_number() over(partition by null order by r.cust_sno) as rn
              from thjs.tb_fxq_cust_rz r
             where r.status = '0'
               and (i_cust_sno is null or r.cust_sno = i_cust_sno)
               and (i_cust_biz is null or r.cust_biz = i_cust_biz)
               and (i_cust_name is null or
                   instr(r.cust_name, i_cust_name) > 0)) r
      left join thjs.tb_dict_entry d
        on d.entry_code = 'INDUSTRY_TYPE'
       and d.entry_value = r.industry_id
     where r.rn > v_page_num
       and r.rn <= v_page_num + v_page_size
     order by r.rn;

  commit;

  o_return_msg  := '执行成功';
  o_return_code := 0;

exception
  -- 非预定义异常处理
  when v_userexp then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    hgman.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
    -- 预定义异常处理
  when others then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    hgman.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
end;

Create or Replace procedure "THJS"."YLT_P_FXQ_CUST_RZ_S" (i_cust_id          in integer, --客户id
                                                     i_cust_name        in varchar2, --客户名称
                                                     i_office_adr       in varchar2, --办公住所
                                                     i_industry_id      in varchar2, --行业分类
                                                     i_industry_name    in varchar2, --行业分类名称（或其他）
                                                     i_busi_scope       in varchar2, --经营范围
                                                     i_reg_capital      in varchar2, --注册资本金
                                                     i_reg_currency     in varchar2, --注册资本金币种
                                                     i_cert_type        in varchar2, --证件类型
                                                     i_cert_no          in varchar2, --证件号码
                                                     i_cert_startdate   in varchar2, --证照有效起始
                                                     i_cert_enddate     in varchar2, --证照有效截止
                                                     i_chair_man        in varchar2, --法人代表姓名
                                                     i_chair_birth      in varchar2, --法人出生年月
                                                     i_chair_certtype   in varchar2, --法人证件类型
                                                     i_chair_certno     in varchar2, --法人证件号码
                                                     i_chair_certstart  in varchar2, --法人证照有效起始
                                                     i_chair_certend    in varchar2, --法人证照有效截止
                                                     i_write_date       in varchar2, --填写日期
                                                     i_submit_flag      in varchar2, --提交标识：0-草稿 1-提交
                                                     i_data_type        in varchar2, --标志数据状态：0-草稿数据 1-正式数据
                                                     i_associatied_date in varchar2, --建议业务关系日期
                                                     i_remark           in varchar2, --备注
                                                     i_usercode         in varchar2, --操作人
                                                     o_return_msg       out varchar2,
                                                     o_return_code      out integer) is
  ----------------------------------------------------------------------------------
  --版    权：GTJA
  --版    本：1.0.0
  --开发人员：YLT@GTJA
  --创建日期：20191030
  --模块编号：
  --模块名称：投行反洗钱 - 客户基本信息（融资端）填报增删改
  --功能名称：
  ----------------------------------------------------------------------------------
  /*v101 YLT@GTJA 2019/10/24 反洗钱客户填报‘保存草稿’及‘正式提交’逻辑优化，要新增历史数据表。
  草稿保留最新一份，正式提交的数据保留最新一份，历史表数据保存正式提交前的一份数据*/

  --==============================================================================
  --固定变量
  v_userexp exception; -- 用户定义错
  v_tradedate    varchar2(8); -- 任务执行时间(业务日期)
  v_exec_func_id integer default '0'; -- 任务id
  v_func_own     varchar2(20) default 'thjs'; -- 任务归属用户（schema）
  v_func_name    varchar2(2000) default 'ylt_p_fxq_cust_rz_s'; -- 任务名称(存储过程的名字)
  v_sqlerrm      varchar2(4000); -- 错误提示信息
  v_sqlcode      number; -- 错误代码
  v_sqlerrl      varchar2(4000); -- 错误行号
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  v_count          integer default 0; --用于记录正式客户主表表中是否有对应数据  
  v_samename_count integer default 0;
  v_his_id         varchar2(100);
  --v_count_draft integer default 0; --用于记录草稿客户主表表中是否有对应数据
  --=============================================================
  -- 业务处理过程
  --=============================================================

begin

  v_tradedate := to_char(sysdate, 'yyyyMMdd');

  insert into thjs.tb_test
    (id, text)
  values
    (94,
     'cust_id:' || i_cust_id || ',cust_name:' || i_cust_name ||
     ',office_adr:' || i_office_adr || ',industry_id:' || i_industry_id ||
     ',industry_name:' || i_industry_name || ',busi_scope:' || i_busi_scope ||
     ',reg_capital:' || i_reg_capital || ',reg_currency:' || i_reg_currency ||
     ',cert_type:' || i_cert_type || ',cert_no:' || i_cert_no ||
     ',cert_startdate:' || i_cert_startdate || ',cert_enddate:' ||
     i_cert_enddate || ',chair_man:' || i_chair_man || ',chair_birth:' ||
     i_chair_birth || ',chair_certtype:' || i_chair_certtype ||
     ',chair_certno:' || i_chair_certno || ',chair_certstart:' ||
     i_chair_certstart || ',chair_certend:' || i_chair_certend ||
     ',usercode:' || i_usercode || ',i_data_type:' || i_data_type ||
     ',i_associatied_date:' || i_associatied_date || ',i_remark:' ||
     i_remark);
  commit;

  /*i_submit_flag: 0-草稿 1-正式提交
  草稿保存至草稿表，只保存最新的一份
  正式提交，将前次提交数据移至历史表，保存当次提交数据至存量表
  客户工作类型：创建-确认-更新
  初始为创建，确认信息无变化时，移动存量数据至历史表，存量表保存“确认”工作类型数据
  编辑更新时，移动存量数据至历史表，存量表保存“更新”工作类型数据
  
  客户填报查询
  */

  --如果提交类型是‘保存草稿’
  if i_submit_flag = '0' then
  
    --不同cust_id，同一名称，返回错误  
    select count(1)
      into v_samename_count
      from thjs.tb_fxq_cust_rz_draft t
     where t.cust_id <> i_cust_id
       and t.cust_name = i_cust_name;
  
    if v_samename_count > 0 then
      o_return_msg  := '已存在同名客户草稿信息，无法保存！';
      o_return_code := -1;
      return;
    end if;
  
    --检查是否保存过此客户草稿
    select count(1)
      into v_count
      from thjs.tb_fxq_cust_rz_draft r
     where r.cust_id = i_cust_id;
  
    if v_count > 0 then
      --如果存在该客户草稿数据，则将草稿表中该客户信息进行更新
      update thjs.tb_fxq_cust_rz_draft r
         set r.cust_name        = i_cust_name,
             r.office_adr       = i_office_adr,
             r.industry_id      = i_industry_id,
             r.industry_name    = i_industry_name,
             r.busi_scope       = i_busi_scope,
             r.reg_capital      = to_number(replace(i_reg_capital, ',', '')),
             r.reg_currency     = i_reg_currency,
             r.cert_type        = i_cert_type,
             r.cert_no          = i_cert_no,
             r.cert_startdate   = to_char(to_date(replace(i_cert_startdate,
                                                          '/',
                                                          '-'),
                                                  'YYYY-MM-DD'),
                                          'YYYY-MM-DD'),
             r.cert_enddate     = to_char(to_date(replace(i_cert_enddate,
                                                          '/',
                                                          '-'),
                                                  'YYYY-MM-DD'),
                                          'YYYY-MM-DD'),
             r.chair_man        = i_chair_man,
             r.chair_birth      = to_char(to_date(replace(i_chair_birth,
                                                          '/',
                                                          '-'),
                                                  'YYYY-MM-DD'),
                                          'YYYY-MM-DD'),
             r.chair_certtype   = i_chair_certtype,
             r.chair_certno     = i_chair_certno,
             r.chair_certstart  = to_char(to_date(replace(i_chair_certstart,
                                                          '/',
                                                          '-'),
                                                  'YYYY-MM-DD'),
                                          'YYYY-MM-DD'),
             r.chair_certend    = to_char(to_date(replace(i_chair_certend,
                                                          '/',
                                                          '-'),
                                                  'YYYY-MM-DD'),
                                          'YYYY-MM-DD'),
             r.write_date       = to_char(to_date(replace(i_write_date,
                                                          '/',
                                                          '-'),
                                                  'YYYY-MM-DD'),
                                          'YYYY-MM-DD'),
             r.update_user      = i_usercode,
             r.update_time      = sysdate,
             r.associatied_date = to_char(to_date(replace(i_associatied_date,
                                                          '/',
                                                          '-'),
                                                  'YYYY-MM-DD'),
                                          'YYYY-MM-DD'),
             r.remark           = i_remark,
             r.work_type        = '2'
       WHERE r.cust_id = i_cust_id; --2-更新
      commit;
      --如果v_count>0，说明是更新数据，那么更新完主表数据后，将其余几张表数据删除。（因为前端会调那4张表单独的insert）
      --更新客戶主信息同时，删除其余全删全插信息
      delete from thjs.tb_fxq_cust_shareholder_draft s
       where s.cust_id = i_cust_id;
      delete from thjs.tb_fxq_cust_controller_draft s
       where s.cust_id = i_cust_id;
      delete from thjs.tb_fxq_cust_authorizer_draft s
       where s.cust_id = i_cust_id;
      delete from thjs.tb_fxq_cust_beneficiary_draft s
       where s.cust_id = i_cust_id;
      commit;
    else
      --如果不存在该客户草稿数据，则将该客户信息插入到草稿表中
      insert into thjs.tb_fxq_cust_rz_draft r
        (busi_date,
         cust_biz,
         cust_id,
         cust_name,
         office_adr,
         industry_id,
         industry_name,
         busi_scope,
         reg_capital,
         reg_currency,
         cert_type,
         cert_no,
         cert_startdate,
         cert_enddate,
         chair_man,
         chair_birth,
         chair_certtype,
         chair_certno,
         chair_certstart,
         chair_certend,
         write_date,
         update_user,
         update_time,
         create_user,
         create_time,
         work_type,
         associatied_date,
         remark)
      values
        (v_tradedate,
         decode(i_usercode, 'admin', '测试', '投行'), --系统管理员新增为测试数据，其余为投行数据
         i_cust_id,
         i_cust_name,
         i_office_adr,
         i_industry_id,
         i_industry_name,
         i_busi_scope,
         to_number(replace(i_reg_capital, ',', '')),
         i_reg_currency,
         i_cert_type,
         i_cert_no,
         to_char(to_date(replace(i_cert_startdate, '/', '-'), 'YYYY-MM-DD'),
                 'YYYY-MM-DD'),
         to_char(to_date(replace(i_cert_enddate, '/', '-'), 'YYYY-MM-DD'),
                 'YYYY-MM-DD'),
         i_chair_man,
         to_char(to_date(replace(i_chair_birth, '/', '-'), 'YYYY-MM-DD'),
                 'YYYY-MM-DD'),
         i_chair_certtype,
         i_chair_certno,
         to_char(to_date(replace(i_chair_certstart, '/', '-'), 'YYYY-MM-DD'),
                 'YYYY-MM-DD'),
         to_char(to_date(replace(i_chair_certend, '/', '-'), 'YYYY-MM-DD'),
                 'YYYY-MM-DD'),
         to_char(to_date(replace(i_write_date, '/', '-'), 'YYYY-MM-DD'),
                 'YYYY-MM-DD'),
         i_usercode,
         sysdate,
         i_usercode,
         sysdate,
         '0',
         to_char(to_date(replace(i_associatied_date, '/', '-'),
                         'YYYY-MM-DD'),
                 'YYYY-MM-DD'),
         i_remark); --0-创建
      commit;
    end if;
  
  end if;

  --如果提交类型是‘正式提交’
  if i_submit_flag = '1' then
  
    --不同cust_id，同一名称，返回错误  
    select count(1)
      into v_samename_count
      from thjs.tb_fxq_cust_rz t
     where t.cust_id <> i_cust_id
       and t.cust_name = i_cust_name;
  
    if v_samename_count > 0 then
      o_return_msg  := '已存在同名客户信息，无法保存！';
      o_return_code := -1;
      return;
    end if;
  
    --检查是否保存过此客户
    select count(1)
      into v_count
      from thjs.tb_fxq_cust_rz r
     where r.cust_id = i_cust_id;
  
    --当数据类型是 [草稿数据]时
    if i_data_type = '0' then
      --首先判断正式表中是否有该客户信息
      if v_count > 0 then
      
        select sys_guid() into v_his_id from dual;
      
        --如果正式表中有该客户信息，将正式表数据存至历史表中
        insert into thjs.tb_fxq_cust_rz_his
          (busi_date,
           cust_biz,
           cust_id,
           cust_name,
           office_adr,
           industry_id,
           industry_name,
           busi_scope,
           reg_capital,
           reg_currency,
           cert_type,
           cert_no,
           cert_startdate,
           cert_enddate,
           chair_man,
           chair_birth,
           chair_certtype,
           chair_certno,
           chair_certstart,
           chair_certend,
           write_date,
           update_user,
           update_time,
           create_user,
           create_time,
           work_type,
           associatied_date,
           remark,
           his_id)
          SELECT busi_date,
                 cust_biz,
                 cust_id,
                 cust_name,
                 office_adr,
                 industry_id,
                 industry_name,
                 busi_scope,
                 reg_capital,
                 reg_currency,
                 cert_type,
                 cert_no,
                 cert_startdate,
                 cert_enddate,
                 chair_man,
                 chair_birth,
                 chair_certtype,
                 chair_certno,
                 chair_certstart,
                 chair_certend,
                 write_date,
                 update_user,
                 update_time,
                 create_user,
                 create_time,
                 r.work_type,
                 associatied_date,
                 remark,
                 v_his_id
            FROM thjs.tb_fxq_cust_rz r
           where r.cust_id = i_cust_id;
      
        --将[控股股东、实际控制人、授权代表人、受益所有人]的正式表数据也存一份到历史表中
        --控股股东
        insert into thjs.tb_fxq_cust_shareholder_his
          SELECT t.*, v_his_id
            FROM thjs.tb_fxq_cust_shareholder t
           WHERE cust_id = i_cust_id;
        --实际控制人
        insert into thjs.tb_fxq_cust_controller_his
          SELECT t.*, v_his_id
            FROM thjs.tb_fxq_cust_controller t
           WHERE cust_id = i_cust_id;
        --授权代表人
        insert into thjs.tb_fxq_cust_authorizer_his
          SELECT t.*, v_his_id
            FROM thjs.tb_fxq_cust_authorizer t
           WHERE cust_id = i_cust_id;
        --受益所有人
        insert into thjs.tb_fxq_cust_beneficiary_his
          SELECT t.*, v_his_id
            FROM thjs.tb_fxq_cust_beneficiary t
           WHERE cust_id = i_cust_id;
        commit;
      
      end if;
    
      --然后把正式表对应的客户数据删除
      --页面会在该存储过程处理完成后再调用【控股股东、实际控制人、授权人代表、收益所有人】这4个会进行insert操作的sp
      DELETE FROM thjs.tb_fxq_cust_rz r where r.cust_id = i_cust_id;
      DELETE FROM thjs.tb_fxq_cust_shareholder WHERE cust_id = i_cust_id;
      DELETE FROM thjs.tb_fxq_cust_controller WHERE cust_id = i_cust_id;
      DELETE FROM thjs.tb_fxq_cust_authorizer WHERE cust_id = i_cust_id;
      DELETE FROM thjs.tb_fxq_cust_beneficiary WHERE cust_id = i_cust_id;
      commit;
    
      --然后将草稿表的最终页面数据存至正式表中
      insert into thjs.tb_fxq_cust_rz
        (busi_date,
         cust_biz,
         cust_id,
         cust_name,
         office_adr,
         industry_id,
         industry_name,
         busi_scope,
         reg_capital,
         reg_currency,
         cert_type,
         cert_no,
         cert_startdate,
         cert_enddate,
         chair_man,
         chair_birth,
         chair_certtype,
         chair_certno,
         chair_certstart,
         chair_certend,
         write_date,
         update_user,
         update_time,
         create_user,
         create_time,
         work_type,
         associatied_date,
         remark)
      values
        (v_tradedate,
         decode(i_usercode, 'admin', '测试', '投行'), --系统管理员新增为测试数据，其余为投行数据
         i_cust_id,
         i_cust_name,
         i_office_adr,
         i_industry_id,
         i_industry_name,
         i_busi_scope,
         to_number(replace(i_reg_capital, ',', '')),
         i_reg_currency,
         i_cert_type,
         i_cert_no,
         to_char(to_date(replace(i_cert_startdate, '/', '-'), 'YYYY-MM-DD'),
                 'YYYY-MM-DD'),
         to_char(to_date(replace(i_cert_enddate, '/', '-'), 'YYYY-MM-DD'),
                 'YYYY-MM-DD'),
         i_chair_man,
         to_char(to_date(replace(i_chair_birth, '/', '-'), 'YYYY-MM-DD'),
                 'YYYY-MM-DD'),
         i_chair_certtype,
         i_chair_certno,
         to_char(to_date(replace(i_chair_certstart, '/', '-'), 'YYYY-MM-DD'),
                 'YYYY-MM-DD'),
         to_char(to_date(replace(i_chair_certend, '/', '-'), 'YYYY-MM-DD'),
                 'YYYY-MM-DD'),
         to_char(to_date(replace(i_write_date, '/', '-'), 'YYYY-MM-DD'),
                 'YYYY-MM-DD'),
         i_usercode,
         sysdate,
         i_usercode,
         sysdate,
         '0',
         to_char(to_date(replace(i_associatied_date, '/', '-'),
                         'YYYY-MM-DD'),
                 'YYYY-MM-DD'),
         i_remark);
      commit;
    
      --最后删除草稿表中该客户的信息
      DELETE FROM thjs.tb_fxq_cust_rz_draft WHERE cust_id = i_cust_id;
      DELETE FROM thjs.tb_fxq_cust_shareholder_draft
       WHERE cust_id = i_cust_id;
      DELETE FROM thjs.tb_fxq_cust_controller_draft
       WHERE cust_id = i_cust_id;
      DELETE FROM thjs.tb_fxq_cust_authorizer_draft
       WHERE cust_id = i_cust_id;
      DELETE FROM thjs.tb_fxq_cust_beneficiary_draft
       WHERE cust_id = i_cust_id;
      commit;
    
    end if;
  
    --当数据类型是 [正式数据]时
    if i_data_type = '1' then
    
      --首先判断正式表中是否有该客户信息
      --如果正式表中有该客户信息，将正式表数据存至历史表中
      if v_count > 0 then
      
        select sys_guid() into v_his_id from dual;
      
        --如果正式表中有该客户信息，将正式表数据存至历史表中
        insert into thjs.tb_fxq_cust_rz_his
          (busi_date,
           cust_biz,
           cust_id,
           cust_name,
           office_adr,
           industry_id,
           industry_name,
           busi_scope,
           reg_capital,
           reg_currency,
           cert_type,
           cert_no,
           cert_startdate,
           cert_enddate,
           chair_man,
           chair_birth,
           chair_certtype,
           chair_certno,
           chair_certstart,
           chair_certend,
           write_date,
           update_user,
           update_time,
           create_user,
           create_time,
           work_type,
           associatied_date,
           remark,
           his_id)
          SELECT busi_date,
                 cust_biz,
                 cust_id,
                 cust_name,
                 office_adr,
                 industry_id,
                 industry_name,
                 busi_scope,
                 reg_capital,
                 reg_currency,
                 cert_type,
                 cert_no,
                 cert_startdate,
                 cert_enddate,
                 chair_man,
                 chair_birth,
                 chair_certtype,
                 chair_certno,
                 chair_certstart,
                 chair_certend,
                 write_date,
                 update_user,
                 update_time,
                 create_user,
                 create_time,
                 r.work_type,
                 associatied_date,
                 remark,
                 v_his_id
            FROM thjs.tb_fxq_cust_rz r
           where r.cust_id = i_cust_id;
      
        --将[控股股东、实际控制人、授权代表人、受益所有人]的正式表数据也存一份到历史表中
        --控股股东
        insert into thjs.tb_fxq_cust_shareholder_his
          SELECT t.*, v_his_id
            FROM thjs.tb_fxq_cust_shareholder t
           WHERE cust_id = i_cust_id;
        --实际控制人
        insert into thjs.tb_fxq_cust_controller_his
          SELECT t.*, v_his_id
            FROM thjs.tb_fxq_cust_controller t
           WHERE cust_id = i_cust_id;
        --授权代表人
        insert into thjs.tb_fxq_cust_authorizer_his
          SELECT t.*, v_his_id
            FROM thjs.tb_fxq_cust_authorizer t
           WHERE cust_id = i_cust_id;
        --受益所有人
        insert into thjs.tb_fxq_cust_beneficiary_his
          SELECT t.*, v_his_id
            FROM thjs.tb_fxq_cust_beneficiary t
           WHERE cust_id = i_cust_id;
        commit;
      
        --然后将数据更新至正式表中
        update thjs.tb_fxq_cust_rz r
           set r.cust_name        = i_cust_name,
               r.office_adr       = i_office_adr,
               r.industry_id      = i_industry_id,
               r.industry_name    = i_industry_name,
               r.busi_scope       = i_busi_scope,
               r.reg_capital      = to_number(replace(i_reg_capital, ',', '')),
               r.reg_currency     = i_reg_currency,
               r.cert_type        = i_cert_type,
               r.cert_no          = i_cert_no,
               r.cert_startdate   = to_char(to_date(replace(i_cert_startdate,
                                                            '/',
                                                            '-'),
                                                    'YYYY-MM-DD'),
                                            'YYYY-MM-DD'),
               r.cert_enddate     = to_char(to_date(replace(i_cert_enddate,
                                                            '/',
                                                            '-'),
                                                    'YYYY-MM-DD'),
                                            'YYYY-MM-DD'),
               r.chair_man        = i_chair_man,
               r.chair_birth      = to_char(to_date(replace(i_chair_birth,
                                                            '/',
                                                            '-'),
                                                    'YYYY-MM-DD'),
                                            'YYYY-MM-DD'),
               r.chair_certtype   = i_chair_certtype,
               r.chair_certno     = i_chair_certno,
               r.chair_certstart  = to_char(to_date(replace(i_chair_certstart,
                                                            '/',
                                                            '-'),
                                                    'YYYY-MM-DD'),
                                            'YYYY-MM-DD'),
               r.chair_certend    = to_char(to_date(replace(i_chair_certend,
                                                            '/',
                                                            '-'),
                                                    'YYYY-MM-DD'),
                                            'YYYY-MM-DD'),
               r.write_date       = to_char(to_date(replace(i_write_date,
                                                            '/',
                                                            '-'),
                                                    'YYYY-MM-DD'),
                                            'YYYY-MM-DD'),
               r.update_user      = i_usercode,
               r.update_time      = sysdate,
               r.work_type        = '2',
               r.associatied_date = to_char(to_date(replace(i_associatied_date,
                                                            '/',
                                                            '-'),
                                                    'YYYY-MM-DD'),
                                            'YYYY-MM-DD'),
               r.remark           = i_remark
         where r.cust_id = i_cust_id;
        commit;
      
        --因页面会在该存储过程处理完成后再调用【控股股东、实际控制人、授权人代表、收益所有人】这4个会进行insert操作的sp，所以此处先把对应数据给删除
        delete from thjs.tb_fxq_cust_shareholder where cust_id = i_cust_id;
        delete from thjs.tb_fxq_cust_controller where cust_id = i_cust_id;
        delete from thjs.tb_fxq_cust_authorizer where cust_id = i_cust_id;
        delete from thjs.tb_fxq_cust_beneficiary where cust_id = i_cust_id;
        commit;
      else
        --如果用户操作为：第一次填写该反洗钱用户，并且直接‘正式提交’，那么直接将该反洗钱客户信息保存至反洗钱客户正式表中
        insert into thjs.tb_fxq_cust_rz
          (busi_date,
           cust_biz,
           cust_id,
           cust_name,
           office_adr,
           industry_id,
           industry_name,
           busi_scope,
           reg_capital,
           reg_currency,
           cert_type,
           cert_no,
           cert_startdate,
           cert_enddate,
           chair_man,
           chair_birth,
           chair_certtype,
           chair_certno,
           chair_certstart,
           chair_certend,
           write_date,
           update_user,
           update_time,
           create_user,
           create_time,
           work_type,
           associatied_date,
           remark)
        
        values
          (v_tradedate,
           decode(i_usercode, 'admin', '测试', '投行'), --系统管理员新增为测试数据，其余为投行数据
           i_cust_id,
           i_cust_name,
           i_office_adr,
           i_industry_id,
           i_industry_name,
           i_busi_scope,
           to_number(replace(i_reg_capital, ',', '')),
           i_reg_currency,
           i_cert_type,
           i_cert_no,
           to_char(to_date(replace(i_cert_startdate, '/', '-'),
                           'YYYY-MM-DD'),
                   'YYYY-MM-DD'),
           to_char(to_date(replace(i_cert_enddate, '/', '-'), 'YYYY-MM-DD'),
                   'YYYY-MM-DD'),
           i_chair_man,
           to_char(to_date(replace(i_chair_birth, '/', '-'), 'YYYY-MM-DD'),
                   'YYYY-MM-DD'),
           i_chair_certtype,
           i_chair_certno,
           to_char(to_date(replace(i_chair_certstart, '/', '-'),
                           'YYYY-MM-DD'),
                   'YYYY-MM-DD'),
           to_char(to_date(replace(i_chair_certend, '/', '-'), 'YYYY-MM-DD'),
                   'YYYY-MM-DD'),
           to_char(to_date(replace(i_write_date, '/', '-'), 'YYYY-MM-DD'),
                   'YYYY-MM-DD'),
           i_usercode,
           sysdate,
           i_usercode,
           sysdate,
           0,
           to_char(to_date(replace(i_associatied_date, '/', '-'),
                           'YYYY-MM-DD'),
                   'YYYY-MM-DD'),
           i_remark);
        commit;
      end if;
    
    end if;
  
    --第一次正式提交，保存反洗钱客户填报人  
    if v_count = 0 then
    
      insert into thjs.Tb_Fxq_Cust_Operator
        (cust_id,
         cust_name,
         user_code,
         user_name,
         work_no,
         update_user,
         update_time)
        select r.cust_id,
               r.cust_name,
               r.update_user,
               u.display_name,
               u.user_id,
               'admin',
               sysdate
          from thjs.tb_fxq_cust_rz r
          left join BASIC_THJS.wb_user u
            on u.user_name = r.update_user
         where r.cust_id = i_cust_id;
    end if;
  
  end if;

  commit;

  o_return_msg  := '执行成功';
  o_return_code := 0;

exception
  -- 非预定义异常处理
  when v_userexp then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    hgman.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
    -- 预定义异常处理
  when others then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    hgman.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
end;

Create or Replace procedure "THJS"."YLT_P_FXQ_CUST_RZ_SELF_Q" (rt_cursor     out sys_refcursor, --返回游标结果集
                                                     i_cust_name   in varchar2, --客户名称
                                                     i_usercode    in varchar2, --查询人
                                                     i_page_num    in number default 0, --默认值0,
                                                     i_page_size   in number default 0, --默认值0  如果i_page_num，i_page_size都为0 则不分页，查询全部
                                                     o_total_count out integer,
                                                     o_return_msg  out varchar2,
                                                     o_return_code out integer) is
  ----------------------------------------------------------------------------------
  --版    权：GTJA
  --版    本：1.0.0
  --开发人员：YLT@GTJA
  --创建日期：20191028
  --模块编号：
  --模块名称：投行反洗钱 - 我填报的反洗钱客户查询
  --功能名称：
  ----------------------------------------------------------------------------------
  --==============================================================================
  --固定变量
  v_userexp exception; -- 用户定义错
  v_tradedate    varchar2(8); -- 任务执行时间(业务日期)
  v_exec_func_id integer default '0'; -- 任务id
  v_func_own     varchar2(20) default 'thjs'; -- 任务归属用户（schema）
  v_func_name    varchar2(2000) default 'ylt_p_fxq_cust_rz_self_q'; -- 任务名称(存储过程的名字)
  v_sqlerrm      varchar2(4000); -- 错误提示信息
  v_sqlcode      number; -- 错误代码
  v_sqlerrl      varchar2(4000); -- 错误行号
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  v_page_num  number default 0;
  v_page_size number;
  --=============================================================
  -- 业务处理过程
  --=============================================================

begin

  v_tradedate := to_char(sysdate, 'yyyyMMdd');

  insert into thjs.tb_test (id, text) values (123, i_usercode);

  if i_page_num is not null then
    v_page_num := i_page_num;
  end if;

  --统计记录条数
  if v_page_num < 1 then
  
    if i_usercode <> 'admin' then
      SELECT sum(cnt)
        into o_total_count
        FROM (select count(1) cnt
                from thjs.tb_fxq_cust_rz r
               where (i_cust_name is null or
                     instr(r.cust_name, i_cust_name) > 0)
                 and r.status = '0'
                 and r.update_user = i_usercode
              union
              select count(1) cnt
                from thjs.tb_fxq_cust_rz_draft r
               where (i_cust_name is null or
                     instr(r.cust_name, i_cust_name) > 0)
                 and r.status = '0'
                 and r.update_user = i_usercode);
    else
      --如果登录用户是'admin'，则可以查询所有人员填报的反洗钱客户数据
      SELECT sum(cnt)
        into o_total_count
        FROM (select count(1) cnt
                from thjs.tb_fxq_cust_rz r
               where (i_cust_name is null or
                     instr(r.cust_name, i_cust_name) > 0)
                 and r.status = '0'
              union
              select count(1) cnt
                from thjs.tb_fxq_cust_rz_draft r
               where (i_cust_name is null or
                     instr(r.cust_name, i_cust_name) > 0)
                 and r.status = '0');
    
    end if;
  
  end if;

  if i_page_size is not null and i_page_size <> 0 then
    v_page_size := i_page_size;
  else
    v_page_size := o_total_count;
  end if;

  if i_usercode <> 'admin' then
    open rt_cursor for
      select r.cust_sno,
             r.cust_id,
             r.cust_name, --客户名称
             r.industry_id, --行业分类
             case
               when d.entry_value <> 26 or
                    (d.entry_value = 26 and r.industry_name is null) then
                d.entry_content
               else
                r.industry_name
             end as industry_name, --行业分类名称（或其他）
             decode(r.work_type, '', '0', r.work_type) work_type,
             r.write_date,
             r.data_type,
             '' proj_link --项目关联（保留字段）
        from (
              --只查正式表和草稿表中的客户数据
              select r.*,
                      '1' data_type, --1-正式提交
                      row_number() over(partition by null order by r.cust_sno) as rn
                from thjs.tb_fxq_cust_rz r
               where r.status = '0'
                 and (i_cust_name is null or
                     instr(r.cust_name, i_cust_name) > 0)
                 and r.update_user = i_usercode
              union all
              select r.*,
                      '0' data_type, --0-保存草稿
                      row_number() over(partition by null order by r.cust_sno) as rn
                from thjs.tb_fxq_cust_rz_draft r
               where r.status = '0'
                 and (i_cust_name is null or
                     instr(r.cust_name, i_cust_name) > 0)
                 and r.update_user = i_usercode) r
        left join thjs.tb_dict_entry d
          on d.entry_code = 'INDUSTRY_TYPE'
         and d.entry_value = r.industry_id
       where r.rn > v_page_num
         and r.rn <= v_page_num + v_page_size
       order by r.rn;
  else
    open rt_cursor for
      select r.cust_sno,
             r.cust_id,
             r.cust_name, --客户名称
             r.industry_id, --行业分类
             case
               when d.entry_value <> 26 or
                    (d.entry_value = 26 and r.industry_name is null) then
                d.entry_content
               else
                r.industry_name
             end as industry_name, --行业分类名称（或其他）
             decode(r.work_type, '', '0', r.work_type) work_type,
             r.write_date,
             r.data_type,
             '' proj_link --项目关联（保留字段）
        from (
              --只查正式表和草稿表中的客户数据
              select r.*,
                      '1' data_type, --1-正式提交
                      row_number() over(partition by null order by r.cust_sno) as rn
                from thjs.tb_fxq_cust_rz r
               where r.status = '0'
                 and (i_cust_name is null or
                     instr(r.cust_name, i_cust_name) > 0)
              union all
              select r.*,
                      '0' data_type, --0-保存草稿
                      row_number() over(partition by null order by r.cust_sno) as rn
                from thjs.tb_fxq_cust_rz_draft r
               where r.status = '0'
                 and (i_cust_name is null or
                     instr(r.cust_name, i_cust_name) > 0)) r
        left join thjs.tb_dict_entry d
          on d.entry_code = 'INDUSTRY_TYPE'
         and d.entry_value = r.industry_id
       where r.rn > v_page_num
         and r.rn <= v_page_num + v_page_size
       order by r.rn;
  end if;

  o_return_msg  := '执行成功';
  o_return_code := 0;

exception
  -- 非预定义异常处理
  when v_userexp then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    hgman.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
    -- 预定义异常处理
  when others then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    hgman.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
end;

Create or Replace procedure "THJS"."YLT_P_FXQ_CUST_SHAREHOLDER_Q" (rt_cursor     out sys_refcursor, --返回游标结果集
                                                         i_cust_id     in varchar2, --客户id
                                                         i_type        in varchar2, --股东类型：0-法人 1-自然人
                                                         i_qry_flag    in varchar2, --查询标识：0-草稿 1-提交 v101+
                                                         o_return_msg  out varchar2,
                                                         o_return_code out integer) is
  ----------------------------------------------------------------------------------
  --版    权：GTJA
  --版    本：1.0.0
  --v101 YLT@GTJA 20191031 反洗钱客户填报逻辑优化，加上查询草稿数据处理

  --开发人员：CZC@GTJA
  --创建日期：20190603
  --模块编号：
  --模块名称：投行反洗钱 - 客户基本信息（融资端）控股股东查询
  --功能名称：
  ----------------------------------------------------------------------------------
  --==============================================================================
  --固定变量
  v_userexp exception; -- 用户定义错
  v_tradedate    varchar2(8); -- 任务执行时间(业务日期)
  v_exec_func_id integer default '0'; -- 任务id
  v_func_own     varchar2(20) default 'thjs'; -- 任务归属用户（schema）
  v_func_name    varchar2(2000) default 'ylt_p_fxq_cust_shareholder_q'; -- 任务名称(存储过程的名字)
  v_sqlerrm      varchar2(4000); -- 错误提示信息
  v_sqlcode      number; -- 错误代码
  v_sqlerrl      varchar2(4000); -- 错误行号
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  --=============================================================
  -- 业务处理过程
  --=============================================================

begin

  v_tradedate := to_char(sysdate, 'yyyyMMdd');
  --如果是查草稿数据
  if i_qry_flag = '0' then
    open rt_cursor for
      select r.cust_id, --客户id
             s.type, --股东类型：0-法人 1-自然人
             s.name, --姓名
             s.birth, --出生年月
             s.certtype, --证件类型
             s.certno, --证件号码
             s.certstart, --证照有效起始
             s.certend, --证照有效截止
             s.data_order
        from thjs.tb_fxq_cust_rz_draft r
       inner join thjs.tb_fxq_cust_shareholder_draft s
          on s.cust_id = r.cust_id
         and (i_type is null or s.type = i_type)
       where r.cust_id = i_cust_id
       order by s.data_order;
  --如果是查正式数据
  elsif i_qry_flag = '1' then
    open rt_cursor for
      select r.cust_id, --客户id
             s.type, --股东类型：0-法人 1-自然人
             s.name, --姓名
             s.birth, --出生年月
             s.certtype, --证件类型
             s.certno, --证件号码
             s.certstart, --证照有效起始
             s.certend, --证照有效截止
             s.data_order
        from thjs.tb_fxq_cust_rz r
       inner join thjs.tb_fxq_cust_shareholder s
          on s.cust_id = r.cust_id
         and (i_type is null or s.type = i_type)
       where r.cust_id = i_cust_id
       order by s.data_order;
  else
    --万一前端没有传入i_qry_flag标识，查询返回空
    open rt_cursor for
      select '' cust_id, --客户id
             '' type, --股东类型：0-法人 1-自然人
             '' name, --姓名
             '' birth, --出生年月
             '' certtype, --证件类型
             '' certno, --证件号码
             '' certstart, --证照有效起始
             '' certend --证照有效截止
        from dual;
  end if;
  commit;

  o_return_msg  := '执行成功';
  o_return_code := 0;

exception
  -- 非预定义异常处理
  when v_userexp then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    hgman.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
    -- 预定义异常处理
  when others then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    hgman.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
end;

Create or Replace procedure "THJS"."YLT_P_FXQ_CUST_SHAREHOLDER_S" (i_cust_id     in varchar2, --客户id
                                                         i_type        in varchar2, --股东类型：0-法人 1-自然人
                                                         i_name        in varchar2, --姓名
                                                         i_birth       in varchar2, --出生年月
                                                         i_certtype    in varchar2, --证件类型
                                                         i_certno      in varchar2, --证件号码
                                                         i_certstart   in varchar2, --证照有效起始
                                                         i_certend     in varchar2, --证照有效截止
                                                         i_submit_flag in varchar2, --提交标识：0-草稿 1-提交 v101+
                                                         i_order       in varchar2, --用于区分数据展示顺序 v101+
                                                         o_return_msg  out varchar2,
                                                         o_return_code out integer) is
  ----------------------------------------------------------------------------------
  --版    权：GTJA
  --版    本：1.0.0
  --v101 YLT@GTJA 20191031 反洗钱客户填报逻辑优化，加上保存草稿处理

  --开发人员：CZC@GTJA
  --创建日期：20190603
  --模块编号：
  --模块名称：投行反洗钱 - 客户基本信息（融资端）控股股东填报增删改
  --功能名称：
  ----------------------------------------------------------------------------------
  --==============================================================================
  --固定变量
  v_userexp exception; -- 用户定义错
  v_tradedate    varchar2(8); -- 任务执行时间(业务日期)
  v_exec_func_id integer default '0'; -- 任务id
  v_func_own     varchar2(20) default 'thjs'; -- 任务归属用户（schema）
  v_func_name    varchar2(2000) default 'ylt_p_fxq_cust_shareholder_s'; -- 任务名称(存储过程的名字)
  v_sqlerrm      varchar2(4000); -- 错误提示信息
  v_sqlcode      number; -- 错误代码
  v_sqlerrl      varchar2(4000); -- 错误行号
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  --=============================================================
  -- 业务处理过程
  --=============================================================

begin

  v_tradedate := to_char(sysdate, 'yyyyMMdd');

  --如果是保存草稿操作
  if i_submit_flag = '0' then
    /*--先把该客户存在的信息删除再进行插入
    delete from thjs.tb_fxq_cust_shareholder_draft
     where cust_id = i_cust_id;*/
    insert into thjs.tb_fxq_cust_shareholder_draft
      (busi_date,
       cust_id,
       type,
       name,
       birth,
       certtype,
       certno,
       certstart,
       certend,
       data_order)
    values
      (v_tradedate,
       i_cust_id,
       i_type,
       i_name,
       to_char(to_date(replace(i_birth, '/', '-'), 'YYYY-MM-DD'),
               'YYYY-MM-DD'),
       i_certtype,
       i_certno,
       to_char(to_date(replace(i_certstart, '/', '-'), 'YYYY-MM-DD'),
               'YYYY-MM-DD'),
       to_char(to_date(replace(i_certend, '/', '-'), 'YYYY-MM-DD'),
               'YYYY-MM-DD'),
       i_order);
  end if;
  --点击‘正式提交’操作时
  if i_submit_flag = '1' then
    /*--先把该客户存在的信息删除再进行插入
    delete from thjs.tb_fxq_cust_shareholder where cust_id = i_cust_id;*/
    insert into thjs.tb_fxq_cust_shareholder
      (busi_date,
       cust_id,
       type,
       name,
       birth,
       certtype,
       certno,
       certstart,
       certend,
       data_order)
    values
      (v_tradedate,
       i_cust_id,
       i_type,
       i_name,
       to_char(to_date(replace(i_birth, '/', '-'), 'YYYY-MM-DD'),
               'YYYY-MM-DD'),
       i_certtype,
       i_certno,
       to_char(to_date(replace(i_certstart, '/', '-'), 'YYYY-MM-DD'),
               'YYYY-MM-DD'),
       to_char(to_date(replace(i_certend, '/', '-'), 'YYYY-MM-DD'),
               'YYYY-MM-DD'),
       i_order);
  end if;
  commit;

  o_return_msg  := '执行成功';
  o_return_code := 0;

exception
  -- 非预定义异常处理
  when v_userexp then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    hgman.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
    -- 预定义异常处理
  when others then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    hgman.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
end;

Create or Replace procedure "THJS"."YLT_P_FXQ_OP_LOG_S" (i_op_type     in varchar2, --操作类型：0-确认 1-修改
                                               i_cust_id     in integer, --客户id
                                               i_usercode    in varchar2, --操作员
                                               o_return_msg  out varchar2,
                                               o_return_code out integer) is
  ----------------------------------------------------------------------------------
  --版    权：GTJA
  --版    本：1.0.0
  --开发人员：CZC@GTJA
  --创建日期：20191031
  --模块编号：
  --模块名称：反洗钱客户管理 - 客户信息确认修改记录保存
  --功能名称：客户信息确认修改记录保存
  ----------------------------------------------------------------------------------
  --==============================================================================
  --固定变量
  v_userexp exception; -- 用户定义错
  v_tradedate    varchar2(8); -- 任务执行时间(业务日期)
  v_exec_func_id integer default '0'; -- 任务id
  v_func_own     varchar2(20) default 'thjs'; -- 任务归属用户（schema）
  v_func_name    varchar2(2000) default 'ylt_p_fxq_op_log_s'; -- 任务名称(存储过程的名字)
  v_sqlerrm      varchar2(4000); -- 错误提示信息
  v_sqlcode      number; -- 错误代码
  v_sqlerrl      varchar2(4000); -- 错误行号
  --==============================================================================
  ---------------------------------------------------------------------------------------
  --业务变量
  --v_count integer default 0;
  v_his_id varchar2(100);
  --=============================================================
  -- 业务处理过程
  --=============================================================

begin

  v_tradedate := to_char(sysdate, 'yyyyMMdd');
  select sys_guid() into v_his_id from dual;

  insert into thjs.tb_fxq_op_log
    (busi_date, cust_id, cust_name, op_type, op_user)
    select v_tradedate, r.cust_id, r.cust_name, i_op_type, i_usercode
      from thjs.tb_fxq_cust_rz r
     where r.cust_id = i_cust_id;

  --确认操作时，将数据存一份到历史表中
  insert into thjs.tb_fxq_cust_rz_his
    (busi_date,
     cust_biz,
     cust_id,
     cust_name,
     office_adr,
     industry_id,
     industry_name,
     busi_scope,
     reg_capital,
     reg_currency,
     cert_type,
     cert_no,
     cert_startdate,
     cert_enddate,
     chair_man,
     chair_birth,
     chair_certtype,
     chair_certno,
     chair_certstart,
     chair_certend,
     write_date,
     update_user,
     update_time,
     create_user,
     create_time,
     work_type,
     his_id)
    SELECT busi_date,
           cust_biz,
           cust_id,
           cust_name,
           office_adr,
           industry_id,
           industry_name,
           busi_scope,
           reg_capital,
           reg_currency,
           cert_type,
           cert_no,
           cert_startdate,
           cert_enddate,
           chair_man,
           chair_birth,
           chair_certtype,
           chair_certno,
           chair_certstart,
           chair_certend,
           write_date,
           update_user,
           update_time,
           create_user,
           create_time,
           work_type,
           v_his_id
      FROM thjs.tb_fxq_cust_rz r
     where r.cust_id = i_cust_id;
  --控股股东
  insert into thjs.tb_fxq_cust_shareholder_his
    SELECT t.*, v_his_id
      FROM thjs.tb_fxq_cust_shareholder t
     WHERE cust_id = i_cust_id;
  --实际控制人
  insert into thjs.tb_fxq_cust_controller_his
    SELECT t.*, v_his_id
      FROM thjs.tb_fxq_cust_controller t
     WHERE cust_id = i_cust_id;
  --授权代表人
  insert into thjs.tb_fxq_cust_authorizer_his
    SELECT t.*, v_his_id
      FROM thjs.tb_fxq_cust_authorizer t
     WHERE cust_id = i_cust_id;
  --受益所有人
  insert into thjs.tb_fxq_cust_beneficiary_his
    SELECT t.*, v_his_id
      FROM thjs.tb_fxq_cust_beneficiary t
     WHERE cust_id = i_cust_id;
  commit;
  
  --然后将反洗钱客户主表中的work_type更新为2-确认
  update thjs.tb_fxq_cust_rz r
     set r.work_type = '2'
   where r.cust_id = i_cust_id;
  commit;

  o_return_msg  := '执行成功';
  o_return_code := 0;

exception
  -- 非预定义异常处理
  when v_userexp then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    hgman.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
    -- 预定义异常处理
  when others then
    rollback;
  
    v_sqlerrm := sqlerrm;
    v_sqlcode := sqlcode;
    v_sqlerrl := dbms_utility.format_error_backtrace();
  
    hgman.p_write_error_log(i_tradedate    => v_tradedate,
                            i_exec_func_id => v_exec_func_id,
                            i_func_own     => v_func_own,
                            i_func_name    => v_func_name,
                            i_occur_time   => sysdate,
                            i_sqlerrm      => v_sqlerrm,
                            i_sqlcode      => v_sqlcode,
                            i_sqlerrl      => v_sqlerrl);
    commit;
    raise;
end;

